-- 和合本全文数据（文件序号见文件名 bible_cuv_data_NN.sql）。先运行 bible_cuv_schema.sql 建表，再按序号依次运行各数据文件。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 10, 1, '耶稣从那里起身，来到犹太的境界并约但河外。众人又聚集到他那里，他又照常教训他们。'),
('CUV', '马可福音', 41, 10, 2, '有法利赛人来问他说：人休妻可以不可以？意思要试探他。'),
('CUV', '马可福音', 41, 10, 3, '耶稣回答说：摩西吩咐你们的是甚么？'),
('CUV', '马可福音', 41, 10, 4, '他们说：摩西许人写了休书便可以休妻。'),
('CUV', '马可福音', 41, 10, 5, '耶稣说：摩西因为你们的心硬，所以写这条例给你们；'),
('CUV', '马可福音', 41, 10, 6, '但从起初创造的时候，神造人是造男造女。'),
('CUV', '马可福音', 41, 10, 7, '因此，人要离开父母，与妻子连合，二人成为一体。'),
('CUV', '马可福音', 41, 10, 8, '既然如此，夫妻不再是两个人，乃是一体的了。'),
('CUV', '马可福音', 41, 10, 9, '所以神配合的，人不可分开。'),
('CUV', '马可福音', 41, 10, 10, '到了屋里，门徒就问他这事。'),
('CUV', '马可福音', 41, 10, 11, '耶稣对他们说：凡休妻另娶的，就是犯奸淫，辜负他的妻子；'),
('CUV', '马可福音', 41, 10, 12, '妻子若离弃丈夫另嫁，也是犯奸淫了。'),
('CUV', '马可福音', 41, 10, 13, '有人带著小孩子来见耶稣，要耶稣摸他们，门徒便责备那些人。'),
('CUV', '马可福音', 41, 10, 14, '耶稣看见就恼怒，对门徒说：让小孩子到我这里来，不要禁止他们；因为在神国的，正是这样的人。'),
('CUV', '马可福音', 41, 10, 15, '我实在告诉你们，凡要承受神国的，若不像小孩子，断不能进去。'),
('CUV', '马可福音', 41, 10, 16, '于是抱著小孩子，给他们按手，为他们祝福。'),
('CUV', '马可福音', 41, 10, 17, '耶稣出来行路的时候，有一个人跑来，跪在他面前，问他说：良善的夫子，我当作甚么事才可以承受永生？'),
('CUV', '马可福音', 41, 10, 18, '耶稣对他说：你为甚么称我是良善的？除了神一位之外，再没有良善的。'),
('CUV', '马可福音', 41, 10, 19, '诫命你是晓得的：不可杀人；不可奸淫；不可偷盗；不可作假见证；不可亏负人；当孝敬父母。'),
('CUV', '马可福音', 41, 10, 20, '他对耶稣说：夫子，这一切我从小都遵守了。'),
('CUV', '马可福音', 41, 10, 21, '耶稣看著他，就爱他，对他说：你还缺少一件：去变卖你所有的，分给穷人，就必有财宝在天上；你还要来跟从我。'),
('CUV', '马可福音', 41, 10, 22, '他听见这话，脸上就变了色，忧忧愁愁的走了，因为他的产业很多。'),
('CUV', '马可福音', 41, 10, 23, '耶稣周围一看，对门徒说：有钱财的人进神的国是何等的难哪！'),
('CUV', '马可福音', 41, 10, 24, '门徒希奇他的话。耶稣又对他们说：小子，倚靠钱财的人进神的国是何等的难哪！'),
('CUV', '马可福音', 41, 10, 25, '骆驼穿过针的眼，比财主进神的国还容易呢。'),
('CUV', '马可福音', 41, 10, 26, '门徒就分外希奇，对他说：这样谁能得救呢？'),
('CUV', '马可福音', 41, 10, 27, '耶稣看著他们，说：在人是不能，在神却不然，因为神凡事都能。'),
('CUV', '马可福音', 41, 10, 28, '彼得就对他说：看哪，我们已经撇下所有的跟从你了。'),
('CUV', '马可福音', 41, 10, 29, '耶稣说：我实在告诉你们，人为我和福音撇下房屋，或是弟兄、姐妹、父母、儿女、田地，'),
('CUV', '马可福音', 41, 10, 30, '没有不在今世得百倍的，就是房屋、弟兄、姐妹、母亲、儿女、田地，并且要受逼迫，在来世必得永生。'),
('CUV', '马可福音', 41, 10, 31, '然而，有许多在前的，将要在后，在后的，将要在前。'),
('CUV', '马可福音', 41, 10, 32, '他们行路上耶路撒冷去。耶稣在前头走，门徒就希奇，跟从的人也害怕。耶稣又叫过十二个门徒来，把自己将要遭遇的事告诉他们说：'),
('CUV', '马可福音', 41, 10, 33, '看哪，我们上耶路撒冷去，人子将要被交给祭司长和文士，他们要定他死罪，交给外邦人。'),
('CUV', '马可福音', 41, 10, 34, '他们要戏弄他，吐唾沫在他脸上，鞭打他，杀害他。过了三天，他要复活。'),
('CUV', '马可福音', 41, 10, 35, '西庇太的儿子雅各、约翰进前来，对耶稣说：夫子，我们无论求你甚么，愿你给我们作。'),
('CUV', '马可福音', 41, 10, 36, '耶稣说：要我给你们作甚么？'),
('CUV', '马可福音', 41, 10, 37, '他们说：赐我们在你的荣耀里，一个坐在你右边，一个坐在你左边。'),
('CUV', '马可福音', 41, 10, 38, '耶稣说：你们不知道所求的是甚么，我所喝的杯，你们能喝么？我所受的洗，你们能受么？'),
('CUV', '马可福音', 41, 10, 39, '他们说：我们能。耶稣说：我所喝的杯，你们也要喝；我所受的洗，你们也要受；'),
('CUV', '马可福音', 41, 10, 40, '只是坐在我的左右，不是我可以赐的，乃是为谁预备的，就赐给谁。'),
('CUV', '马可福音', 41, 10, 41, '那十个门徒听见，就恼怒雅各、约翰。'),
('CUV', '马可福音', 41, 10, 42, '耶稣叫他们来，对他们说：你们知道，外邦人有尊为君王的，治理他们，有大臣操权管束他们。'),
('CUV', '马可福音', 41, 10, 43, '只是在你们中间，不是这样。你们中间，谁愿为大，就必作你们的用人；'),
('CUV', '马可福音', 41, 10, 44, '在你们中间，谁愿为首，就必作众人的仆人。'),
('CUV', '马可福音', 41, 10, 45, '因为人子来，并不是要受人的服事，乃是要服事人，并且要舍命作多人的赎价。'),
('CUV', '马可福音', 41, 10, 46, '到了耶利哥；耶稣同门徒并许多人出耶利哥的时候，有一个讨饭的瞎子，是底买的儿子巴底买，坐在路旁。'),
('CUV', '马可福音', 41, 10, 47, '他听见是拿撒勒的耶稣，就喊著说：大卫的子孙耶稣阿！可怜我罢！'),
('CUV', '马可福音', 41, 10, 48, '有许多人责备他，不许他作声。他却越发大声喊著说：大卫的子孙哪，可怜我罢！'),
('CUV', '马可福音', 41, 10, 49, '耶稣就站住，说：叫过他来。他们就叫那瞎子，对他说：放心，起来！他叫你啦。'),
('CUV', '马可福音', 41, 10, 50, '瞎子就丢下衣服，跳起来，走到耶稣那里。'),
('CUV', '马可福音', 41, 10, 51, '耶稣说：要我为你作甚么？瞎子说：拉波尼（就是夫子），我要能看见。'),
('CUV', '马可福音', 41, 10, 52, '耶稣说：你去罢！你的信救了你了。瞎子立刻看见了，就在路上跟随耶稣。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 11, 1, '耶稣和门徒将近耶路撒冷，到了伯法其和伯大尼，在橄榄山那里；耶稣就打发两个门徒，'),
('CUV', '马可福音', 41, 11, 2, '对他们说：你们往对面村子里去，一进去的时候，必看见一匹驴驹拴在那里，是从来没有人骑过的，可以解开，牵来。'),
('CUV', '马可福音', 41, 11, 3, '若有人对你们说：为甚么作这事？你们就说：主要用他。那人必立时让你们牵来。'),
('CUV', '马可福音', 41, 11, 4, '他们去了，便看见一匹驴驹拴在门外街道上，就把他解开。'),
('CUV', '马可福音', 41, 11, 5, '在那里站著的人，有几个说：你们解驴驹作甚么？'),
('CUV', '马可福音', 41, 11, 6, '门徒照著耶稣所说的回答，那些人就任凭他们牵去了。'),
('CUV', '马可福音', 41, 11, 7, '他们把驴驹牵到耶稣那里，把自己的衣服搭在上面，耶稣就骑上。'),
('CUV', '马可福音', 41, 11, 8, '有许多人把衣服铺在路上，也有人把田间的树枝砍下来，铺在路上。'),
('CUV', '马可福音', 41, 11, 9, '前行后随的人都喊著说：和散那（和散那：原有求救的意思，在此乃是称颂的话）！奉主名来的是应当称颂的！'),
('CUV', '马可福音', 41, 11, 10, '那将要来的我祖大卫之国是应当称颂的！高高在上和散那！'),
('CUV', '马可福音', 41, 11, 11, '耶稣进了耶路撒冷，入了圣殿，周围看了各样物件。天色已晚，就和十二个门徒出城，往伯大尼去了。'),
('CUV', '马可福音', 41, 11, 12, '第二天，他们从伯大尼出来，耶稣饿了。'),
('CUV', '马可福音', 41, 11, 13, '远远的看见一棵无花果树，树上有叶子，就往那里去，或者在树上可以找著甚么。到了树下，竟找不著甚么，不过有叶子，因为不是收无花果的时候。'),
('CUV', '马可福音', 41, 11, 14, '耶稣就对树说：从今以后，永没有人吃你的果子。他的门徒也听见了。'),
('CUV', '马可福音', 41, 11, 15, '他们来到耶路撒冷。耶稣进入圣殿，赶出殿里作买卖的人，推倒兑换银钱之人的桌子，和卖鸽子之人的凳子；'),
('CUV', '马可福音', 41, 11, 16, '也不许人拿著器具从殿里经过；'),
('CUV', '马可福音', 41, 11, 17, '便教训他们说：经上不是记著说：我的殿必称为万国祷告的殿么？你们倒使他成为贼窝了。'),
('CUV', '马可福音', 41, 11, 18, '祭司长和文士听见这话，就想法子要除灭耶稣，却又怕他，因为众人都希奇他的教训。'),
('CUV', '马可福音', 41, 11, 19, '每天晚上，耶稣出城去。'),
('CUV', '马可福音', 41, 11, 20, '早晨，他们从那里经过，看见无花果树连根都枯干了。'),
('CUV', '马可福音', 41, 11, 21, '彼得想起耶稣的话来，就对他说：拉比，请看！你所咒诅的无花果树，已经枯干了。'),
('CUV', '马可福音', 41, 11, 22, '耶稣回答说：你们当信服神。'),
('CUV', '马可福音', 41, 11, 23, '我实在告诉你们，无论何人对这座山说：你挪开此地，投在海里！他若心里不疑惑，只信他所说的必成，就必给他成了。'),
('CUV', '马可福音', 41, 11, 24, '所以我告诉你们，凡你们祷告祈求的，无论是甚么，只要信是得著的，就必得著。'),
('CUV', '马可福音', 41, 11, 25, '你们站著祷告的时候，若想起有人得罪你们，就当饶恕他，好叫你们在天上的父也饶恕你们的过犯。'),
('CUV', '马可福音', 41, 11, 26, '你们若不饶恕人，你们在天上的父也不饶恕你们的过犯。（有古卷无此节）'),
('CUV', '马可福音', 41, 11, 27, '他们又来到耶路撒冷。耶稣在殿里行走的时候，祭司长和文士并长老进前来，'),
('CUV', '马可福音', 41, 11, 28, '问他说：你仗著甚么权柄作这些事？给你这权柄的是谁呢？'),
('CUV', '马可福音', 41, 11, 29, '耶稣对他们说：我要问你们一句话，你们回答我，我就告诉你们我仗著甚么权柄作这些事。'),
('CUV', '马可福音', 41, 11, 30, '约翰的洗礼是从天上来的？是从人间来的呢？你们可以回答我。'),
('CUV', '马可福音', 41, 11, 31, '他们彼此商议说：我们若说从天上来，他必说：这样，你们为甚么不信他呢？'),
('CUV', '马可福音', 41, 11, 32, '若说从人间来，却又怕百姓，因为众人真以约翰为先知。'),
('CUV', '马可福音', 41, 11, 33, '于是回答耶稣说：我们不知道。耶稣说：我也不告诉你们我仗著甚么权柄作这些事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 12, 1, '耶稣就用比喻对他们说：有人栽了一个葡萄园，周围圈上篱笆，挖了一个压酒池，盖了一座楼，租给园户，就往外国去了。'),
('CUV', '马可福音', 41, 12, 2, '到了时候，打发一个仆人到园户那里，要从园户收葡萄园的果子。'),
('CUV', '马可福音', 41, 12, 3, '园户拿住他，打了他，叫他空手回去。'),
('CUV', '马可福音', 41, 12, 4, '再打发一个仆人到他们那里。他们打伤他的头，并且凌辱他。'),
('CUV', '马可福音', 41, 12, 5, '又打发一个仆人去，他们就杀了他。后又打发好些仆人去，有被他们打的，有被他们杀的。'),
('CUV', '马可福音', 41, 12, 6, '园主还有一位是他的爱子，末后又打发他去，意思说：他们必尊敬我的儿子。'),
('CUV', '马可福音', 41, 12, 7, '不料，那些园户彼此说：这是承受产业的。来罢，我们杀他，产业就归我们了！'),
('CUV', '马可福音', 41, 12, 8, '于是拿住他，杀了他，把他丢在园外。'),
('CUV', '马可福音', 41, 12, 9, '这样，葡萄园的主人要怎么办呢？他要来除灭那些园户，将葡萄园转给别人。'),
('CUV', '马可福音', 41, 12, 10, '经上写著说：匠人所弃的石头，已作了房角的头块石头。'),
('CUV', '马可福音', 41, 12, 11, '这是主所作的，在我们眼中看为希奇。这经你们没有念过么？'),
('CUV', '马可福音', 41, 12, 12, '他们看出这比喻是指著他们说的，就想要捉拿他，只是惧怕百姓，于是离开他走了。'),
('CUV', '马可福音', 41, 12, 13, '后来，他们打发几个法利赛人和几个希律党的人到耶稣那里，要就著他的话陷害他。'),
('CUV', '马可福音', 41, 12, 14, '他们来了，就对他说：夫子，我们知道你是诚实的，甚么人你都不徇情面；因为你不看人的外貌，乃是诚诚实实传神的道。纳税给该撒可以不可以？'),
('CUV', '马可福音', 41, 12, 15, '我们该纳不该纳？耶稣知道他们的假意，就对他们说：你们为甚么试探我？拿一个银钱来给我看！'),
('CUV', '马可福音', 41, 12, 16, '我们该纳不该纳？耶稣知道他们的假意，就对他们说：你们为甚么试探我？拿一个银钱来给我看！'),
('CUV', '马可福音', 41, 12, 17, '耶稣说：该撒的物当归给该撒，神的物当归给神。他们就很希奇他。'),
('CUV', '马可福音', 41, 12, 18, '撒都该人常说没有复活的事。他们来问耶稣说：'),
('CUV', '马可福音', 41, 12, 19, '夫子，摩西为我们写著说：人若死了，撇下妻子，没有孩子，他兄弟当娶他的妻，为哥哥生子立后。'),
('CUV', '马可福音', 41, 12, 20, '有弟兄七人，第一个娶了妻，死了，没有留下孩子。'),
('CUV', '马可福音', 41, 12, 21, '第二个娶了他，也死了，没有留下孩子。第三个也是这样。'),
('CUV', '马可福音', 41, 12, 22, '那七个人都没有留下孩子；末了，那妇人也死了。'),
('CUV', '马可福音', 41, 12, 23, '当复活的时候，他是那一个的妻子呢？因为他们七个人都娶过他。'),
('CUV', '马可福音', 41, 12, 24, '耶稣说：你们所以错了，岂不是因为不明白圣经，不晓得神的大能么？'),
('CUV', '马可福音', 41, 12, 25, '人从死里复活，也不娶也不嫁，乃像天上的使者一样。'),
('CUV', '马可福音', 41, 12, 26, '论到死人复活，你们没有念过摩西的书荆棘篇上所载的么？神对摩西说：我是亚伯拉罕的神，以撒的神，雅各的神。'),
('CUV', '马可福音', 41, 12, 27, '神不是死人的神，乃是活人的神。你们是大错了。'),
('CUV', '马可福音', 41, 12, 28, '有一个文士来，听见他们辩论，晓得耶稣回答的好，就问他说：诫命中那是第一要紧的呢？'),
('CUV', '马可福音', 41, 12, 29, '耶稣回答说：第一要紧的就是说：以色列阿，你要听，主─我们神是独一的主。'),
('CUV', '马可福音', 41, 12, 30, '你要尽心、尽性、尽意、尽力爱主─你的神。'),
('CUV', '马可福音', 41, 12, 31, '其次就是说：要爱人如己。再没有比这两条诫命更大的了。'),
('CUV', '马可福音', 41, 12, 32, '那文士对耶稣说：夫子说，神是一位，实在不错；除了他以外，再没有别的神；'),
('CUV', '马可福音', 41, 12, 33, '并且尽心、尽智、尽力爱他，又爱人如己，就比一切燔祭和各样祭祀好的多。'),
('CUV', '马可福音', 41, 12, 34, '耶稣见他回答的有智慧，就对他说：你离神的国不远了。从此以后，没有人敢再问他甚么。'),
('CUV', '马可福音', 41, 12, 35, '耶稣在殿里教训人，就问他们说：文士怎么说基督是大卫的子孙呢？'),
('CUV', '马可福音', 41, 12, 36, '大卫被圣灵感动，说：主对我主说，你坐在我的右边，等我使你仇敌作你的脚凳。'),
('CUV', '马可福音', 41, 12, 37, '大卫既自己称他为主，他怎么又是大卫的子孙呢？众人都喜欢听他。'),
('CUV', '马可福音', 41, 12, 38, '耶稣在教训之间，说：你们要防备文士；他们好穿长衣游行，喜爱人在街市上问他们的安，'),
('CUV', '马可福音', 41, 12, 39, '又喜爱会堂里的高位，筵席上的首座。'),
('CUV', '马可福音', 41, 12, 40, '他们侵吞寡妇的家产，假意作很长的祷告。这些人要受更重的刑罚！'),
('CUV', '马可福音', 41, 12, 41, '耶稣对银库坐著，看众人怎样投钱入库。有好些财主往里投了若干的钱。'),
('CUV', '马可福音', 41, 12, 42, '有一个穷寡妇来，往里投了两个小钱，就是一个大钱。'),
('CUV', '马可福音', 41, 12, 43, '耶稣叫门徒来，说：我实在告诉你们，这穷寡妇投入库里的，比众人所投的更多。'),
('CUV', '马可福音', 41, 12, 44, '因为，他们都是自己有余，拿出来投在里头；但这寡妇是自己不足，把他一切养生的都投上了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 13, 1, '耶稣从殿里出来的时候，有一个门徒对他说：夫子，请看，这是何等的石头！何等的殿宇！'),
('CUV', '马可福音', 41, 13, 2, '耶稣对他说：你看见这大殿宇么？将来在这里没有一块石头留在石头上，不被拆毁了。'),
('CUV', '马可福音', 41, 13, 3, '耶稣在橄榄山上对圣殿而坐，彼得、雅各、约翰，和安得烈暗暗的问他说：'),
('CUV', '马可福音', 41, 13, 4, '请告诉我们，甚么时候有这些事呢？这一切事将成的时候有甚么豫兆呢？'),
('CUV', '马可福音', 41, 13, 5, '耶稣说：你们要谨慎，免得有人迷惑你们。'),
('CUV', '马可福音', 41, 13, 6, '将来有好些人冒我的名来，说：我是基督，并且要迷惑许多人。'),
('CUV', '马可福音', 41, 13, 7, '你们听见打仗和打仗的风声，不要惊慌。这些事是必须有的，只是末期还没有到。'),
('CUV', '马可福音', 41, 13, 8, '民要攻打民，国要攻打国；多处必有地震、饥荒。这都是灾难（灾难：原文是生产之难）的起头。'),
('CUV', '马可福音', 41, 13, 9, '但你们要谨慎；因为人要把你们交给公会，并且你们在会堂里要受鞭打，又为我的缘故站在诸侯与君王面前，对他们.作见证。'),
('CUV', '马可福音', 41, 13, 10, '然而，福音必须先传给万民。'),
('CUV', '马可福音', 41, 13, 11, '人把你们拉去交官的时候，不要预先思虑说甚么；到那时候，赐给你们甚么话，你们就说甚么；因为说话的不是你们，乃是圣灵。'),
('CUV', '马可福音', 41, 13, 12, '弟兄要把弟兄，父亲要把儿子，送到死地；儿女要起来与父母为敌，害死他们；'),
('CUV', '马可福音', 41, 13, 13, '并且你们要为我的名被众人恨恶。惟有忍耐到底的，必然得救。'),
('CUV', '马可福音', 41, 13, 14, '你们看见那行毁坏可憎的，站在不当站的地方（读这经的人须要会意）。那时，在犹太的，应当逃到山上；'),
('CUV', '马可福音', 41, 13, 15, '在房上的，不要下来，也不要进去拿家里的东西；'),
('CUV', '马可福音', 41, 13, 16, '在田里的，也不要回去取衣裳。'),
('CUV', '马可福音', 41, 13, 17, '当那些日子，怀孕的和奶孩子的有祸了！'),
('CUV', '马可福音', 41, 13, 18, '你们应当祈求，叫这些事不在冬天临到。'),
('CUV', '马可福音', 41, 13, 19, '因为在那些日子必有灾难，自从神创造万物直到如今，并没有这样的灾难，后来也必没有。'),
('CUV', '马可福音', 41, 13, 20, '若不是主减少那日子，凡有血气的，总没有一个得救的；只是为主的选民，他将那日子减少了。'),
('CUV', '马可福音', 41, 13, 21, '那时若有人对你们说：看哪，基督在这里，或说：基督在那里，你们不要信！'),
('CUV', '马可福音', 41, 13, 22, '因为假基督、假先知将要起来，显神迹奇事，倘若能行，就把选民迷惑了。'),
('CUV', '马可福音', 41, 13, 23, '你们要谨慎。看哪，凡事我都预先告诉你们了。'),
('CUV', '马可福音', 41, 13, 24, '在那些日子，那灾难以后，日头要变黑了，月亮也不放光，'),
('CUV', '马可福音', 41, 13, 25, '众星要从天上坠落，天势都要震动。'),
('CUV', '马可福音', 41, 13, 26, '那时，他们（马太二十四章三十节是地上的万族）要看见人子有大能力、大荣耀，驾云降临。'),
('CUV', '马可福音', 41, 13, 27, '他要差遣天使，把他的选民，从四方（方：原文是风），从地极直到天边，都招聚了来。'),
('CUV', '马可福音', 41, 13, 28, '你们可以从无花果树学个比方：当树枝发嫩长叶的时候，你们就知道夏天近了。'),
('CUV', '马可福音', 41, 13, 29, '这样，你们几时看见这些事成就，也该知道人子（人子：或作神的国）近了，正在门口了。'),
('CUV', '马可福音', 41, 13, 30, '我实在告诉你们，这世代还没有过去，这些事都要成就。'),
('CUV', '马可福音', 41, 13, 31, '天地要废去，我的话却不能废去。'),
('CUV', '马可福音', 41, 13, 32, '但那日子，那时辰，没有人知道，连天上的使者也不知道，子也不知道，惟有父知道。'),
('CUV', '马可福音', 41, 13, 33, '你们要谨慎，儆醒祈祷，因为你们不晓得那日期几时来到。'),
('CUV', '马可福音', 41, 13, 34, '这事正如一个人离开本家，寄居外邦，把权柄交给仆人，分派各人当作的工又吩咐看门的儆醒。'),
('CUV', '马可福音', 41, 13, 35, '所以，你们要儆醒；因为你们不知道家主甚么时候来，或晚上，或半夜，或鸡叫，或早晨；'),
('CUV', '马可福音', 41, 13, 36, '恐怕他忽然来到，看见你们睡著了。'),
('CUV', '马可福音', 41, 13, 37, '我对你们所说的话，也是对众人说：要儆醒！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 14, 1, '过两天是逾越节，又是除酵节，祭司长和文士想法子怎么用诡计捉拿耶稣，杀他。'),
('CUV', '马可福音', 41, 14, 2, '只是说：当节的日子不可，恐怕百姓生乱。'),
('CUV', '马可福音', 41, 14, 3, '耶稣在伯大尼长大痲疯的西门家里坐席的时候，有一个女人拿著一玉瓶至贵的真哪哒香膏来，打破玉瓶，把膏浇在耶稣的头上。'),
('CUV', '马可福音', 41, 14, 4, '有几个人心中很不喜悦，说：何用这样枉费香膏呢？'),
('CUV', '马可福音', 41, 14, 5, '这香膏可以卖三十多两银子赒济穷人。他们就向那女人生气。'),
('CUV', '马可福音', 41, 14, 6, '耶稣说：由他罢！为甚么难为他呢？他在我身上作的是一件美事。'),
('CUV', '马可福音', 41, 14, 7, '因为常有穷人和你们同在，要向他们行善随时都可以；只是你们不常有我。'),
('CUV', '马可福音', 41, 14, 8, '他所作的，是尽他所能的；他是为我安葬的事把香膏预先浇在我身上。'),
('CUV', '马可福音', 41, 14, 9, '我实在告诉你们，普天之下，无论在甚么地方传这福音，也要述说这女人所作的，以为记念。'),
('CUV', '马可福音', 41, 14, 10, '十二门徒之中，有一个加略人犹大去见祭司长，要把耶稣交给他们。'),
('CUV', '马可福音', 41, 14, 11, '他们听见就欢喜，又应许给他银子；他就寻思如何得便把耶稣交给他们。'),
('CUV', '马可福音', 41, 14, 12, '除酵节的第一天，就是宰逾越羊羔的那一天，门徒对耶稣说：你吃逾越节的筵席要我们往那里去预备呢？'),
('CUV', '马可福音', 41, 14, 13, '耶稣就打发两个门徒，对他们说：你们进城去，必有人拿著一瓶水迎面而来，你们就跟著他。'),
('CUV', '马可福音', 41, 14, 14, '他进那家去，你们就对那家的主人说：夫子说：客房在那里？我与门徒好在那里吃逾越节的筵席。'),
('CUV', '马可福音', 41, 14, 15, '他必指给你们摆设整齐的一间大楼，你们就在那里为我们预备。'),
('CUV', '马可福音', 41, 14, 16, '门徒出去，进了城，所遇见的正如耶稣所说的。他们就预备了逾越节的筵席。'),
('CUV', '马可福音', 41, 14, 17, '到了晚上，耶稣和十二个门徒都来了。'),
('CUV', '马可福音', 41, 14, 18, '他们坐席正吃的时候，耶稣说：我实在告诉你们，你们中间有一个与我同吃的人要卖我了。'),
('CUV', '马可福音', 41, 14, 19, '他们就忧愁起来，一个一个的问他说：是我么？'),
('CUV', '马可福音', 41, 14, 20, '耶稣对他们说：是十二个门徒中同我蘸手在盘子里的那个人。'),
('CUV', '马可福音', 41, 14, 21, '人子必要去世，正如经上指著他所写的；但卖人子的人有祸了！那人不生在世上倒好。'),
('CUV', '马可福音', 41, 14, 22, '他们吃的时候，耶稣拿起饼来，祝了福，就擘开，递给他们，说：你们拿著吃，这是我的身体；'),
('CUV', '马可福音', 41, 14, 23, '又拿起杯来，祝谢了，递给他们；他们都喝了。'),
('CUV', '马可福音', 41, 14, 24, '耶稣说：这是我立约的血，为多人流出来的。'),
('CUV', '马可福音', 41, 14, 25, '我实在告诉你们，我不再喝这葡萄汁，直到我在神的国里喝新的那日子。'),
('CUV', '马可福音', 41, 14, 26, '他们唱了诗，就出来，往橄榄山去。'),
('CUV', '马可福音', 41, 14, 27, '耶稣对他们说：你们都要跌倒了，因为经上记著说：我要击打牧人，羊就分散了。'),
('CUV', '马可福音', 41, 14, 28, '但我复活以后，要在你们以先往加利利去。'),
('CUV', '马可福音', 41, 14, 29, '彼得说：众人虽然跌倒，我总不能。'),
('CUV', '马可福音', 41, 14, 30, '耶稣对他说：我实在告诉你，就在今天夜里，鸡叫两遍以先，你要三次不认我。'),
('CUV', '马可福音', 41, 14, 31, '彼得却极力的说：我就是必须和你同死，也总不能不认你。众门徒都是这样说。'),
('CUV', '马可福音', 41, 14, 32, '他们来到一个地方，名叫客西马尼。耶稣对门徒说：你们坐在这里，等我祷告。'),
('CUV', '马可福音', 41, 14, 33, '于是带著彼得、雅各、约翰同去，就惊恐起来，极其难过，'),
('CUV', '马可福音', 41, 14, 34, '对他们说：我心里甚是忧伤，几乎要死；你们在这里等候，儆醒。'),
('CUV', '马可福音', 41, 14, 35, '他就稍往前走，俯伏在地，祷告说：倘若可行，便叫那时候过去。'),
('CUV', '马可福音', 41, 14, 36, '他说：阿爸！父阿！在你凡事都能；求你将这杯撤去。然而，不要从我的意思，只要从你的意思。'),
('CUV', '马可福音', 41, 14, 37, '耶稣回来，见他们睡著了，就对彼得说：西门，你睡觉么？不能儆醒片时么？'),
('CUV', '马可福音', 41, 14, 38, '总要儆醒祷告，免得入了迷惑。你们心灵固然愿意，肉体却软弱了。'),
('CUV', '马可福音', 41, 14, 39, '耶稣又去祷告，说的话还是与先前一样，'),
('CUV', '马可福音', 41, 14, 40, '又来见他们睡著了，因为他们的眼睛甚是困倦；他们也不知道怎么回答。'),
('CUV', '马可福音', 41, 14, 41, '第三次来，对他们说：现在你们仍然睡觉安歇罢（或作么？）！够了，时候到了。看哪，人子被卖在罪人手里了。'),
('CUV', '马可福音', 41, 14, 42, '起来！我们走罢。看哪，那卖我的人近了。'),
('CUV', '马可福音', 41, 14, 43, '说话之间，忽然那十二个门徒里的犹大来了，并有许多人带著刀棒，从祭司长和文士并长老那里与他同来。'),
('CUV', '马可福音', 41, 14, 44, '卖耶稣的人曾给他们一个暗号，说：我与谁亲嘴，谁就是他。你们把他拿住，牢牢靠靠的带去。'),
('CUV', '马可福音', 41, 14, 45, '犹大来了，随即到耶稣跟前，说：拉比，便与他亲嘴。'),
('CUV', '马可福音', 41, 14, 46, '他们就下手拿住他。'),
('CUV', '马可福音', 41, 14, 47, '旁边站著的人，有一个拔出刀来，将大祭司的仆人砍了一刀，削掉了他一个耳朵。'),
('CUV', '马可福音', 41, 14, 48, '耶稣对他们说：你们带著刀棒出来拿我，如同拿强盗么？'),
('CUV', '马可福音', 41, 14, 49, '我天天教训人，同你们在殿里，你们并没有拿我。但这事成就，为要应验经上的话。'),
('CUV', '马可福音', 41, 14, 50, '门徒都离开他，逃走了。'),
('CUV', '马可福音', 41, 14, 51, '有一个少年人，赤身披著一块麻布，跟随耶稣，众人就捉拿他。'),
('CUV', '马可福音', 41, 14, 52, '他却丢了麻布，赤身逃走了。'),
('CUV', '马可福音', 41, 14, 53, '他们把耶稣带到大祭司那里，又有众祭司长和长老并文士都来和大祭司一同聚集。'),
('CUV', '马可福音', 41, 14, 54, '彼得远远的跟著耶稣，一直进入大祭司的院里，和差役一同坐在火光.里烤火。'),
('CUV', '马可福音', 41, 14, 55, '祭司长和全公会寻找见证控告耶稣，要治死他，却寻不著。'),
('CUV', '马可福音', 41, 14, 56, '因为有好些人作见证告他，只是他们的见证各不相合。'),
('CUV', '马可福音', 41, 14, 57, '又有几个人站起来作假见证告他，说：'),
('CUV', '马可福音', 41, 14, 58, '我们听见他说：我要拆毁这人手所造的殿，三日内就另造一座不是人手所造的。'),
('CUV', '马可福音', 41, 14, 59, '他们就是这么作见证，也是各不相合。'),
('CUV', '马可福音', 41, 14, 60, '大祭司起来站在中间，问耶稣说：你甚么都不回答么？这些人作见证告你?的是甚么呢？'),
('CUV', '马可福音', 41, 14, 61, '耶稣却不言语，一句也不回答。大祭司又问他说：你是那当称颂者的儿子基督不是？'),
('CUV', '马可福音', 41, 14, 62, '耶稣说：我是。你们必看见人子坐在那权能者的右边，驾著天上的云降临。'),
('CUV', '马可福音', 41, 14, 63, '大祭司就撕开衣服，说：我们何必再用见证人呢？'),
('CUV', '马可福音', 41, 14, 64, '你们已经听见他这僭妄的话了。你们的意见如何？他们都定他该死的罪。'),
('CUV', '马可福音', 41, 14, 65, '就有人吐唾沫在他脸上，又蒙著他的脸，用拳头打他，对他说：你说预言罢！差役接过他来，用手掌打他。'),
('CUV', '马可福音', 41, 14, 66, '彼得在下边院子里；来了大祭司的一个使女，'),
('CUV', '马可福音', 41, 14, 67, '见彼得烤火，就看著他，说：你素来也是同拿撒勒人耶稣一伙的。'),
('CUV', '马可福音', 41, 14, 68, '彼得却不承认，说：我不知道，也不明白你说的是甚么。于是出来，到了前院，鸡就叫了。'),
('CUV', '马可福音', 41, 14, 69, '那使女看见他，又对旁边站著的人说：这也是他们一党的。'),
('CUV', '马可福音', 41, 14, 70, '彼得又不承认。过了不多的时候，旁边站著的人又对彼得说：你真是他们一党的！因为你是加利利人。'),
('CUV', '马可福音', 41, 14, 71, '彼得就发咒起誓的说：我不认得你们说的这个人。'),
('CUV', '马可福音', 41, 14, 72, '立时鸡叫了第二遍。彼得想起耶稣对他所说的话：鸡叫两遍以先，你要三次不认我。思想起来，就哭了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 15, 1, '一到早晨，祭司长和长老、文士、全公会的人大家商议，就把耶稣捆绑，解去交给彼拉多。'),
('CUV', '马可福音', 41, 15, 2, '彼拉多问他说：你是犹太人的王么？耶稣回答说：你说的是。'),
('CUV', '马可福音', 41, 15, 3, '祭司长告他许多的事。'),
('CUV', '马可福音', 41, 15, 4, '彼拉多又问他说：你看，他们告你这么多的事，你甚么都不回答么？'),
('CUV', '马可福音', 41, 15, 5, '耶稣仍不回答，以致彼拉多觉得希奇。'),
('CUV', '马可福音', 41, 15, 6, '每逢这节期，巡抚照众人所求的，释放一个囚犯给他们。'),
('CUV', '马可福音', 41, 15, 7, '有一个人名叫巴拉巴，和作乱的人一同捆绑。他们作乱的时候，曾杀过人。'),
('CUV', '马可福音', 41, 15, 8, '众人上去求巡抚，照常例给他们办。'),
('CUV', '马可福音', 41, 15, 9, '彼拉多说：你们要我释放犹太人的王给你们么？'),
('CUV', '马可福音', 41, 15, 10, '他原晓得，祭司长是因为嫉妒才把耶稣解了来。'),
('CUV', '马可福音', 41, 15, 11, '只是祭司长挑唆众人，宁可释放巴拉巴给他们。'),
('CUV', '马可福音', 41, 15, 12, '彼拉多又说：那么样，你们所称为犹太人的王，我怎么办他呢？'),
('CUV', '马可福音', 41, 15, 13, '}他们又喊著说：把他钉十字架！'),
('CUV', '马可福音', 41, 15, 14, '彼拉多说：为甚么呢？他作了甚么恶事呢？他们便极力的喊著说：把他钉十字架！'),
('CUV', '马可福音', 41, 15, 15, '彼拉多要叫众人喜悦，就释放巴拉巴给他们，将耶稣鞭打了，交给人钉十字架。'),
('CUV', '马可福音', 41, 15, 16, '兵丁把耶稣带进衙门院里，叫齐了全营的兵.。'),
('CUV', '马可福音', 41, 15, 17, '他们给他穿上紫袍，又用荆棘编作冠冕给他戴上，'),
('CUV', '马可福音', 41, 15, 18, '就庆贺他说：恭喜，犹太人的王阿！'),
('CUV', '马可福音', 41, 15, 19, '又拿一根苇子打他的头，吐唾沫在他脸上，屈膝拜他。'),
('CUV', '马可福音', 41, 15, 20, '戏弄完了，就给他脱了紫袍，仍穿上他自己的衣服，带他出去，要钉十字架。'),
('CUV', '马可福音', 41, 15, 21, '有一个古利奈人西门，就是亚力山大和鲁孚的父亲，从乡下来，经过那地方，他们就勉强他同去，好背著耶稣的十字架。'),
('CUV', '马可福音', 41, 15, 22, '他们带耶稣到了各各他地方（各各他繙出来就是髑髅地），'),
('CUV', '马可福音', 41, 15, 23, '拿没药调和的酒给耶稣，他却不受。'),
('CUV', '马可福音', 41, 15, 24, '于是将他钉在十字架上，拈阄分他的衣服，看是谁得甚么。'),
('CUV', '马可福音', 41, 15, 25, '钉他在十字架上是已初的时候。'),
('CUV', '马可福音', 41, 15, 26, '在上面有他的罪状，写的是：犹太人.的王。'),
('CUV', '马可福音', 41, 15, 27, '他们又把两个强盗和他同钉十字架，一个在右边，一个在左边。（有古卷在此有：'),
('CUV', '马可福音', 41, 15, 28, '这就应了经上的话说：他被列在罪犯之中。）'),
('CUV', '马可福音', 41, 15, 29, '从那里经过的人辱骂他，摇著头说：咳！你这拆毁圣殿、三日又建造起来的，'),
('CUV', '马可福音', 41, 15, 30, '可以救自己，从十字架上下来罢！'),
('CUV', '马可福音', 41, 15, 31, '祭司长和文士也是这样戏弄他，彼此说：他救了别人，不能救自己。'),
('CUV', '马可福音', 41, 15, 32, '以色列的王基督，现在可以从十字架上下来，叫我们看见，就信了。那和他同钉的人也是讥诮他。'),
('CUV', '马可福音', 41, 15, 33, '从午正到申初，遍地都黑暗了。'),
('CUV', '马可福音', 41, 15, 34, '申初的时候，耶稣大声喊著说：以罗伊！以罗伊！拉马撒巴各大尼？繙出来就是：我的神！我的神！为甚么离弃我？'),
('CUV', '马可福音', 41, 15, 35, '旁边站著的人，有的听见就说：看哪，他叫以利亚呢！'),
('CUV', '马可福音', 41, 15, 36, '有一个人跑去，把海绒蘸满了醋，绑在苇子上，送给他喝，说：且等著，看以利亚来不来把他取下。'),
('CUV', '马可福音', 41, 15, 37, '耶稣大声喊叫，气就断了。'),
('CUV', '马可福音', 41, 15, 38, '殿里的幔子从上到下裂为两半。'),
('CUV', '马可福音', 41, 15, 39, '对面站著的百夫长看见耶稣这样喊叫（有古卷没有喊叫二字）断气，就说：这人真是神的儿子！'),
('CUV', '马可福音', 41, 15, 40, '还有些妇女远远的观看；内中有抹大拉的马利亚，又有小雅各和约西的母亲马利亚，并有撒罗米，'),
('CUV', '马可福音', 41, 15, 41, '就是耶稣在加利利的时候，跟随他、服事他的那些人，还有同耶稣上耶路撒冷的好些妇女在那里观看。'),
('CUV', '马可福音', 41, 15, 42, '到了晚上，因为这是预备日，就是安息日的前一日，'),
('CUV', '马可福音', 41, 15, 43, '有亚利马太的约瑟前来，他是尊贵的议士，也是等候神国的。他放胆进去见彼拉多，求耶稣的身体；'),
('CUV', '马可福音', 41, 15, 44, '彼拉多诧异耶稣已经死了，便叫百夫长来，问他耶稣死了久不久。'),
('CUV', '马可福音', 41, 15, 45, '既从百夫长得知实情，就把耶稣的尸首赐给约瑟。'),
('CUV', '马可福音', 41, 15, 46, '约瑟买了细麻布，把耶稣取下来，用细麻布裹好，安放在磐石中凿出来的坟墓里，又辊过一块石头来挡住墓门。'),
('CUV', '马可福音', 41, 15, 47, '抹大拉的马利亚和约西的母亲马利亚都看见安放他的地方。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 16, 1, '过了安息日，抹大拉的马利亚和雅各的母亲马利亚并撒罗米，买了香膏要去膏耶稣的身体。'),
('CUV', '马可福音', 41, 16, 2, '七日的第一日清早，出太阳的时候，他们来到坟墓那里，'),
('CUV', '马可福音', 41, 16, 3, '彼此说：谁给我们把石头从墓门辊开呢？'),
('CUV', '马可福音', 41, 16, 4, '那石头原来很大，他们抬头一看，却见石头已经辊开了。'),
('CUV', '马可福音', 41, 16, 5, '他们进了坟墓，看见一个少年人坐在右边，穿著白袍，就甚惊恐。'),
('CUV', '马可福音', 41, 16, 6, '那少年人对他们说：不要惊恐！你们寻找那钉十字架的拿撒勒人耶稣，他已经复活了，不在这里。请看安放他的地方。'),
('CUV', '马可福音', 41, 16, 7, '你们可以去告诉他的门徒和彼得，说：他在你们以先往加利利去。在那里你们要见他，正如他从前所告诉你们的。'),
('CUV', '马可福音', 41, 16, 8, '他们就出来，从坟墓那里逃跑，又发抖又惊奇，甚么也不告诉人，因为他们害怕。'),
('CUV', '马可福音', 41, 16, 9, '在七日的第一日清早，耶稣复活了，就先向抹大拉的马利亚显现。耶稣从他身上曾赶出七个鬼。'),
('CUV', '马可福音', 41, 16, 10, '他去告诉那向来跟随耶稣的人；那时他们正哀恸哭泣。'),
('CUV', '马可福音', 41, 16, 11, '他们听见耶稣活了，被马利亚看见，却是不信。'),
('CUV', '马可福音', 41, 16, 12, '这事以后，门徒中间有两个人往乡下去。走路的时候，耶稣变了形像，向他们显现。'),
('CUV', '马可福音', 41, 16, 13, '他们就去告诉其余的门徒；其余的门徒也是不信。'),
('CUV', '马可福音', 41, 16, 14, '后来，十一个门徒坐席的时候，耶稣向他们显现，责备他们不信，心里刚硬，因为他们不信那些在他复活以后看见他的人。'),
('CUV', '马可福音', 41, 16, 15, '他又对他们说：你们往普天下去，传福音给万民（万民：原文是凡受造的）听。'),
('CUV', '马可福音', 41, 16, 16, '信而受洗的，必然得救；不信的，必被定罪。'),
('CUV', '马可福音', 41, 16, 17, '信的人必有神迹随著他们，就是奉我的名赶鬼；说新方言；'),
('CUV', '马可福音', 41, 16, 18, '手能拿蛇；若喝了甚么毒物，也必不受害；手按病人，病人就必好了。'),
('CUV', '马可福音', 41, 16, 19, '主耶稣和他们说完了话，后来被接到天上，坐在神的右边。'),
('CUV', '马可福音', 41, 16, 20, '门徒出去，到处宣传福音。主和他们同工，用神迹随著，证实所传的道。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 1, 1, '提阿非罗大人哪，有好些人提笔作书，述说在我们中间所成就的事，是照传道的人从起初亲眼看见又传给我们的。'),
('CUV', '路加福音', 42, 1, 2, 'a'),
('CUV', '路加福音', 42, 1, 3, '这些事我既从起头都详细考察了，就定意要按著次序写给你，'),
('CUV', '路加福音', 42, 1, 4, '使你知道所学之道都是确实的。'),
('CUV', '路加福音', 42, 1, 5, '当犹太王希律的时候，亚比雅班里有一个祭司，名叫撒迦利亚；他妻子是亚伦的后人，名叫以利沙伯。'),
('CUV', '路加福音', 42, 1, 6, '他们二人在神面前都是义人，遵行主的一切诫命礼仪，没有可指摘的，'),
('CUV', '路加福音', 42, 1, 7, '只是没有孩子；因为以利沙伯不生育，两个人又年纪老迈了。'),
('CUV', '路加福音', 42, 1, 8, '撒迦利亚按班次在神面前供祭司的职分，'),
('CUV', '路加福音', 42, 1, 9, '照祭司的规矩掣签，得进主殿烧香。'),
('CUV', '路加福音', 42, 1, 10, '烧香的时候，众百姓在外面祷告。'),
('CUV', '路加福音', 42, 1, 11, '有主的使者站在香坛的右边，向他显现。'),
('CUV', '路加福音', 42, 1, 12, '撒迦利亚看见，就惊慌害怕。'),
('CUV', '路加福音', 42, 1, 13, '天使对他说：撒迦利亚，不要害怕，因为你的祈祷已经被听见了。你的妻子以利沙伯要给你生一个儿子，你要给他起名叫约翰。'),
('CUV', '路加福音', 42, 1, 14, '你必欢喜快乐；有许多人因他出世，也必喜乐。'),
('CUV', '路加福音', 42, 1, 15, '他在主面前将要为大，淡酒浓酒都不喝，从母腹里就被圣灵充满了。'),
('CUV', '路加福音', 42, 1, 16, '他要使许多以色列人回转，归于主─他们的神。'),
('CUV', '路加福音', 42, 1, 17, '他必有以利亚的心志能力，行在主的前面，叫为父的心转向儿女，叫悖逆的人转从义人的智慧，又为主预备合用的百姓。'),
('CUV', '路加福音', 42, 1, 18, '撒迦利亚对天使说：我凭著甚么可知道这事呢？我已经老了，我的妻子也年纪老迈了。'),
('CUV', '路加福音', 42, 1, 19, '天使回答说：我是站在神面前的加百列，奉差而来对你说话，将这好信息报给你。'),
('CUV', '路加福音', 42, 1, 20, '到了时候，这话必然应验；只因你不信，你必哑吧，不能说话，直到这事成就的日子。'),
('CUV', '路加福音', 42, 1, 21, '百姓等候撒迦利亚，诧异他许久在殿里。'),
('CUV', '路加福音', 42, 1, 22, '及至他出来，不能和他们说话，他们就知道他在殿里见了异象；因为他直向他们打手式，竟成了哑吧。'),
('CUV', '路加福音', 42, 1, 23, '他供职的日子已满，就回家去了。'),
('CUV', '路加福音', 42, 1, 24, '这些日子以后，他的妻子以利沙伯怀了孕，就隐藏了五个月，'),
('CUV', '路加福音', 42, 1, 25, '说：主在眷顾我的日子，这样看待我，要把我在人间的羞耻除掉。'),
('CUV', '路加福音', 42, 1, 26, '到了第六个月，天使加百列奉神的差遣往加利利的一座城去，这城名叫拿撒勒，'),
('CUV', '路加福音', 42, 1, 27, '到一个童女那里，是已经许配大卫家的一个人，名叫约瑟。童女的名字叫马利亚；'),
('CUV', '路加福音', 42, 1, 28, '天使进去，对他说：蒙大恩的女子，我问你安，主和你同在了！'),
('CUV', '路加福音', 42, 1, 29, '马利亚因这话就很惊慌，又反复思想这样问安是甚么意思。'),
('CUV', '路加福音', 42, 1, 30, '天使对他说：马利亚，不要怕！你在神面前已经蒙恩了。'),
('CUV', '路加福音', 42, 1, 31, '你要怀孕生子，可以给他起名叫耶稣。'),
('CUV', '路加福音', 42, 1, 32, '他要为大，称为至高者的儿子；主神要把他祖大卫的位给他。'),
('CUV', '路加福音', 42, 1, 33, '他要作雅各家的王，直到永远；他的国也没有穷尽。'),
('CUV', '路加福音', 42, 1, 34, '马利亚对天使说：我没有出嫁，怎么有这事呢？'),
('CUV', '路加福音', 42, 1, 35, '天使回答说：圣灵要临到你身上，至高者的能力要荫庇你，因此所要生的圣者必称为神的儿子（或作：所要生的，必称为圣，称为神的儿子）。'),
('CUV', '路加福音', 42, 1, 36, '况且你的亲戚以利沙伯，在年老的时候也怀了男胎，就是那素来称为不生育的，现在有孕六个月了。'),
('CUV', '路加福音', 42, 1, 37, '因为，出于神的话，没有一句不带能力的。'),
('CUV', '路加福音', 42, 1, 38, '马利亚说：我是主的使女，情愿照你的话成就在我身上。天使就离开他去了。'),
('CUV', '路加福音', 42, 1, 39, '那时候，马利亚起身，急忙往山地里去，来到犹大的一座城；'),
('CUV', '路加福音', 42, 1, 40, '进了撒迦利亚的家，问以利沙伯安。'),
('CUV', '路加福音', 42, 1, 41, '以利沙伯一听马利亚问安，所怀的胎就在腹里跳动。以利沙伯且被圣灵充满，'),
('CUV', '路加福音', 42, 1, 42, '高声喊著说：你在妇女中是有福的！你所怀的胎也是有福的！'),
('CUV', '路加福音', 42, 1, 43, '我主的母到我这里来，这是从那里得的呢？'),
('CUV', '路加福音', 42, 1, 44, '因为你问安的声音一入我耳，我腹里的胎就欢喜跳动。'),
('CUV', '路加福音', 42, 1, 45, '这相信的女子是有福的！因为主对他所说的话都要应验。'),
('CUV', '路加福音', 42, 1, 46, '马利亚说：我心尊主为大；'),
('CUV', '路加福音', 42, 1, 47, '我灵以神我的救主为乐；'),
('CUV', '路加福音', 42, 1, 48, '因为他顾念他使女的卑微；从今以后，万代要称我有福。'),
('CUV', '路加福音', 42, 1, 49, '那有权能的，为我成就了大事；他的名为圣。'),
('CUV', '路加福音', 42, 1, 50, '他怜悯敬畏他的人，直到世世代代。'),
('CUV', '路加福音', 42, 1, 51, '他用膀臂施展大能；那狂傲的人正心里妄想就被他赶散了。'),
('CUV', '路加福音', 42, 1, 52, '他叫有权柄的失位，叫卑贱的升高；'),
('CUV', '路加福音', 42, 1, 53, '叫饥饿的得饱美食，叫富足的空手回去。'),
('CUV', '路加福音', 42, 1, 54, '他扶助了他的仆人以色列，'),
('CUV', '路加福音', 42, 1, 55, '为要记念亚伯拉罕和他的后裔，施怜悯直到永远，正如从前对我们列祖所说的话。'),
('CUV', '路加福音', 42, 1, 56, '马利亚和以利沙伯同住，约有三个月，就回家去了。'),
('CUV', '路加福音', 42, 1, 57, '以利沙伯的产期到了，就生了一个儿子。'),
('CUV', '路加福音', 42, 1, 58, '邻里亲族听见主向他大施怜悯，就和他一同欢乐。'),
('CUV', '路加福音', 42, 1, 59, '到了第八日，他们来要给孩子行割礼，并要照他父亲的名字叫他撒迦利亚。'),
('CUV', '路加福音', 42, 1, 60, '他母亲说：不可！要叫他约翰。'),
('CUV', '路加福音', 42, 1, 61, '他们说：你亲族中没有叫这名字的。'),
('CUV', '路加福音', 42, 1, 62, '他们就向他父亲打手式，问他要叫这孩子甚么名字。'),
('CUV', '路加福音', 42, 1, 63, '他要了一块写字的板，就写上，说：他的名字是约翰。他们便都希奇。'),
('CUV', '路加福音', 42, 1, 64, '撒迦利亚的口立时开了，舌头也舒展了，就说出话来，称颂神。'),
('CUV', '路加福音', 42, 1, 65, '周围居住的人都惧怕；这一切的事就传遍了犹太的山地。'),
('CUV', '路加福音', 42, 1, 66, '凡听见的人都将这事放在心里，说：这个孩子将来怎么样呢？因为有主与他同在。'),
('CUV', '路加福音', 42, 1, 67, '他父亲撒迦利亚被圣灵充满了，就预言说：'),
('CUV', '路加福音', 42, 1, 68, '主─以色列的神是应当称颂的！因他眷顾他的百姓，为他们施行救赎，'),
('CUV', '路加福音', 42, 1, 69, '在他仆人大卫家中，为我们兴起了拯救的角，'),
('CUV', '路加福音', 42, 1, 70, '正如主藉著从创世以来圣先知的口所说的话，'),
('CUV', '路加福音', 42, 1, 71, '拯救我们脱离仇敌和一切恨我们之人的手，'),
('CUV', '路加福音', 42, 1, 72, '向我们列祖施怜悯，记念他的圣约─'),
('CUV', '路加福音', 42, 1, 73, '就是他对我们祖宗亚伯拉罕所起的誓─'),
('CUV', '路加福音', 42, 1, 74, '叫我们既从仇敌手中被救出来，'),
('CUV', '路加福音', 42, 1, 75, '就可以终身在他面前，坦然无惧的用圣洁、公义事奉他。'),
('CUV', '路加福音', 42, 1, 76, '孩子阿！你要称为至高者的先知；因为你要行在主的前面，预备他的道路，'),
('CUV', '路加福音', 42, 1, 77, '叫他的百姓因罪得赦，就知道救恩。'),
('CUV', '路加福音', 42, 1, 78, '因我们神怜悯的心肠，叫清晨的日光从高天临到我们，'),
('CUV', '路加福音', 42, 1, 79, '要照亮坐在黑暗中死荫里的人，把我们的脚引到平安的路上。'),
('CUV', '路加福音', 42, 1, 80, '那孩子渐渐长大，心灵强健，住在旷野，直到他显明在以色列人面前的日子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 2, 1, '当那些日子，该撒亚古士督有旨意下来，叫天下人民都报名上册。'),
('CUV', '路加福音', 42, 2, 2, '这是居里扭作叙利亚巡抚的时候，头一次行报名上册的事。'),
('CUV', '路加福音', 42, 2, 3, '众人各归各城，报名上册。'),
('CUV', '路加福音', 42, 2, 4, '约瑟也从加利利的拿撒勒城上犹太去，到了大卫的城，名叫伯利恒，因他本是大卫一族一家的人，'),
('CUV', '路加福音', 42, 2, 5, '要和他所聘之妻马利亚一同报名上册。那时马利亚的身孕已经重了。'),
('CUV', '路加福音', 42, 2, 6, '他们在那里的时候，马利亚的产期到了，'),
('CUV', '路加福音', 42, 2, 7, '就生了头胎的儿子，用布包起来，放在马槽里，因为客店里没有地方。'),
('CUV', '路加福音', 42, 2, 8, '在伯利恒之野地里有牧羊的人，夜间按著更次看守羊群。'),
('CUV', '路加福音', 42, 2, 9, '有主的使者站在他们旁边，主的荣光四面照著他们；牧羊的人就甚惧怕。'),
('CUV', '路加福音', 42, 2, 10, '那天使对他们说：不要惧怕！我报给你们大喜的信息，是关乎万民的；'),
('CUV', '路加福音', 42, 2, 11, '因今天在大卫的城里，为你们生了救主，就是主基督。'),
('CUV', '路加福音', 42, 2, 12, '你们要看见一个婴孩，包著布，卧在马槽里，那就是记号了。'),
('CUV', '路加福音', 42, 2, 13, '忽然，有一大队天兵同那天使赞美神说：'),
('CUV', '路加福音', 42, 2, 14, '在至高之处荣耀归与神！在地上平安归与他所喜悦的人（有古卷作：喜悦归与人）！'),
('CUV', '路加福音', 42, 2, 15, '众天使离开他们，升天去了。牧羊的人彼此说：我们往伯利恒去，看看所成的事，就是主所指示我们的。'),
('CUV', '路加福音', 42, 2, 16, '他们急忙去了，就寻见马利亚和约瑟，又有那婴孩卧在马槽里；'),
('CUV', '路加福音', 42, 2, 17, '既然看见，就把天使论这孩子的话传开了。'),
('CUV', '路加福音', 42, 2, 18, '凡听见的，就诧异牧羊之人对他们所说的话。'),
('CUV', '路加福音', 42, 2, 19, '马利亚却把这一切的事存在心里，反复思想。'),
('CUV', '路加福音', 42, 2, 20, '牧羊的人回去了，因所听见所看见的一切事，正如天使向他们所说的，就归荣耀与神，赞美他。'),
('CUV', '路加福音', 42, 2, 21, '满了八天，就给孩子行割礼，与他起名叫耶稣；这就是没有成胎以前，天使所起的名。'),
('CUV', '路加福音', 42, 2, 22, '按摩西律法满了洁净的日子，他们带著孩子上耶路撒冷去，要把他献与主。'),
('CUV', '路加福音', 42, 2, 23, '（正如主的律法上所记：凡头生的男子必称圣归主；）'),
('CUV', '路加福音', 42, 2, 24, '又要照主的律法上所说，或用一对班鸠，或用两只雏鸽献祭。'),
('CUV', '路加福音', 42, 2, 25, '在耶路撒冷有一个人，名叫西面；这人又公义又虔诚，素常盼望以色列的安慰者来到，又有圣灵在他身上。'),
('CUV', '路加福音', 42, 2, 26, '他得了圣灵的启示，知道自己未死以前，必看见主所立的基督。'),
('CUV', '路加福音', 42, 2, 27, '他受了圣灵的感动，进入圣殿，正遇见耶稣的父母抱著孩子进来，要照律法的规矩办理。'),
('CUV', '路加福音', 42, 2, 28, '西面就用手接过他来，称颂神说：'),
('CUV', '路加福音', 42, 2, 29, '主阿！如今可以照你的话，释放仆人安然去世；'),
('CUV', '路加福音', 42, 2, 30, '因为我的眼睛已经看见你的救恩─'),
('CUV', '路加福音', 42, 2, 31, '就是你在万民面前所预备的：'),
('CUV', '路加福音', 42, 2, 32, '是照亮外邦人的光，又是你民以色列的荣耀。'),
('CUV', '路加福音', 42, 2, 33, '孩子的父母因这论耶稣的话就希奇。'),
('CUV', '路加福音', 42, 2, 34, '西面给他们祝福，又对孩子的母亲马利亚说：这孩子被立，是要叫以色列中许多人跌倒，许多人兴起；又要作毁谤的话柄，叫许多人心里的意念显露出来；你自己的心也要被刀刺透。'),
('CUV', '路加福音', 42, 2, 35, 'a'),
('CUV', '路加福音', 42, 2, 36, '又有女先知，名叫亚拿，是亚设支派法内力的女儿，年纪已经老迈，从作童女出嫁的时候，同丈夫住了七年就寡居了，'),
('CUV', '路加福音', 42, 2, 37, '现在已经八十四岁（或作：就寡居了八十四年），并不离开圣殿，禁食祈求，昼夜事奉神。'),
('CUV', '路加福音', 42, 2, 38, '正当那时，他进前来称谢神，将孩子的事对一切盼望耶路撒冷得救赎的人讲说。'),
('CUV', '路加福音', 42, 2, 39, '约瑟和马利亚照主的律法办完了一切的事，就回加利利，到自己的城拿撒勒去了。'),
('CUV', '路加福音', 42, 2, 40, '孩子渐渐长大，强健起来，充满智慧，又有神的恩在他身上。'),
('CUV', '路加福音', 42, 2, 41, '每年到逾越节，他父母就上耶路撒冷去。'),
('CUV', '路加福音', 42, 2, 42, '当他十二岁的时候，他们按著节期的规矩上去。'),
('CUV', '路加福音', 42, 2, 43, '守满了节期，他们回去，孩童耶稣仍旧在耶路撒冷。他的父母并不知道，'),
('CUV', '路加福音', 42, 2, 44, '以为他在同行的人中间，走了一天的路程，就在亲族和熟识的人中找他，'),
('CUV', '路加福音', 42, 2, 45, '既找不著，就回耶路撒冷去找他。'),
('CUV', '路加福音', 42, 2, 46, '过了三天，就遇见他在殿里，坐在教师中间，一面听，一面问。'),
('CUV', '路加福音', 42, 2, 47, '凡听见他的，都希奇他的聪明和他的应对。'),
('CUV', '路加福音', 42, 2, 48, '他父母看见就很希奇。他母亲对他说：我儿！为甚么向我们这样行呢？看哪！你父亲和我伤心来找你！'),
('CUV', '路加福音', 42, 2, 49, '耶稣说：为甚么找我呢？岂不知我应当以我父的事为念么（或作：岂不知我应当在我父的家里么）？'),
('CUV', '路加福音', 42, 2, 50, '他所说的这话，他们不明白。'),
('CUV', '路加福音', 42, 2, 51, '他就同他们下去，回到拿撒勒，并且顺从他们。他母亲把这一切的事都存在心里。'),
('CUV', '路加福音', 42, 2, 52, '耶稣的智慧和身量（或作：年纪），并神和人喜爱他的心，都一齐增长。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 3, 1, '该撒提庇留在位第十五年，本丢彼拉多作犹太巡抚，希律作加利利分封的王，他兄弟腓力作以士利亚和特拉可尼地方分封的王，吕撒聂作亚比利尼分封的王，'),
('CUV', '路加福音', 42, 3, 2, '亚那和该亚法作大祭司。那时，撒迦利亚的儿子约翰在旷野里，神的话临到他。'),
('CUV', '路加福音', 42, 3, 3, '他就来到约但河一带地方，宣讲悔改的洗礼，使罪得赦。'),
('CUV', '路加福音', 42, 3, 4, '正如先知以赛亚书上所记的话，说：在旷野有人声喊著说：预备主的道，修直他的路！'),
('CUV', '路加福音', 42, 3, 5, '一切山洼都要填满；大小山冈都要削平！弯弯曲曲的地方要改为正直；高高低低的道路要改为平坦！'),
('CUV', '路加福音', 42, 3, 6, '凡有血气的，都要见神的救恩！'),
('CUV', '路加福音', 42, 3, 7, '约翰对那出来要受他洗的众人说：毒蛇的种类！谁指示你们逃避将来的忿怒呢？'),
('CUV', '路加福音', 42, 3, 8, '你们要结出果子来，与悔改的心相称。不要自己心里说：有亚伯拉罕为我们的祖宗。我告诉你们，神能从这些石头中，给亚伯拉罕兴起子孙来。'),
('CUV', '路加福音', 42, 3, 9, '现在斧子已经放在树根上，凡不结好果子的树就砍下来，丢在火里。'),
('CUV', '路加福音', 42, 3, 10, '众人问他说：这样，我们当作甚么呢？'),
('CUV', '路加福音', 42, 3, 11, '约翰回答说：有两件衣裳的，就分给那没有的；有食物的，也当这样行。'),
('CUV', '路加福音', 42, 3, 12, '又有税吏来要受洗，问他说：夫子，我们当作甚么呢？'),
('CUV', '路加福音', 42, 3, 13, '约翰说：除了例定的数目，不要多取。'),
('CUV', '路加福音', 42, 3, 14, '又有兵丁问他说：我们当作甚么呢？约翰说：不要以强暴待人，也不要讹诈人，自己有钱粮就当知足。'),
('CUV', '路加福音', 42, 3, 15, '百姓指望基督来的时候，人都心里猜疑，或者约翰是基督。'),
('CUV', '路加福音', 42, 3, 16, '约翰说：我是用水给你们施洗，但有一位能力比我更大的要来，我就是给他解鞋带也不配。他要用圣灵与火给你们施洗。'),
('CUV', '路加福音', 42, 3, 17, '他手里拿著簸箕，要扬净他的场，把麦子收在仓里，把糠用不灭的火烧尽了。'),
('CUV', '路加福音', 42, 3, 18, '约翰又用许多别的话劝百姓，向他们传福音。'),
('CUV', '路加福音', 42, 3, 19, '只是分封的王希律，因他兄弟之妻希罗底的缘故，并因他所行的一切恶事，受了约翰的责备；'),
('CUV', '路加福音', 42, 3, 20, '又另外添了一件，就是把约翰收在监里。'),
('CUV', '路加福音', 42, 3, 21, '众百姓都受了洗，耶稣也受了洗。正祷告的时候，天就开了，'),
('CUV', '路加福音', 42, 3, 22, '圣灵降临在他身上，形状仿佛鸽子；又有声音从天上来，说：你是我的爱子，我喜悦你。'),
('CUV', '路加福音', 42, 3, 23, '耶稣开头传道，年纪约有三十岁。依人看来，他是约瑟的儿子；约瑟是希里的儿子；'),
('CUV', '路加福音', 42, 3, 24, '希里是玛塔的儿子；玛塔是利未的儿子；利未是麦基的儿子；麦基是雅拿的儿子；雅拿是约瑟的儿子；'),
('CUV', '路加福音', 42, 3, 25, '约瑟是玛他提亚的儿子；玛他提亚是亚摩斯的儿子；亚摩斯是拿鸿的儿子；拿鸿是以斯利的儿子；以斯利是拿该的儿子；'),
('CUV', '路加福音', 42, 3, 26, '拿该是玛押的儿子；玛押是玛他提亚的儿子；玛他提亚是西美的儿子；西美是约瑟的儿子；约瑟是犹大的儿子；犹大是约亚拿的儿子；'),
('CUV', '路加福音', 42, 3, 27, '约亚拿是利撒的儿子；利撒是所罗巴伯的儿子；所罗巴伯是撒拉铁的儿子；撒拉铁是尼利的儿子；尼利是麦基的儿子；'),
('CUV', '路加福音', 42, 3, 28, '麦基是亚底的儿子；亚底是哥桑的儿子；哥桑是以摩当的儿子；以摩当是珥的儿子；珥是约细的儿子；'),
('CUV', '路加福音', 42, 3, 29, '约细是以利以谢的儿子；以利以谢是约令的儿子；约令是玛塔的儿子；玛塔是利未的儿子；'),
('CUV', '路加福音', 42, 3, 30, '利未是西缅的儿子；西缅是犹大的儿子；犹大是约瑟的儿子；约瑟是约南的儿子；约南是以利亚敬的儿子；'),
('CUV', '路加福音', 42, 3, 31, '以利亚敬是米利亚的儿子；米利亚是买南的儿子；买南是玛达他的儿子；玛达他是拿单的儿子；拿单是大卫的儿子；'),
('CUV', '路加福音', 42, 3, 32, '大卫是耶西的儿子；耶西是俄备得的儿子；俄备得是波阿斯的儿子；波阿斯是撒门的儿子；撒门是拿顺的儿子；'),
('CUV', '路加福音', 42, 3, 33, '拿顺是亚米拿达的儿子；亚米拿达是亚兰的儿子；亚兰是希斯仑的儿子；希斯仑是法勒斯的儿子；法勒斯是犹大的儿子；'),
('CUV', '路加福音', 42, 3, 34, '犹大是雅各的儿子；雅各是以撒的儿子；以撒是亚伯拉罕的儿子；亚伯拉罕是他拉的儿子；他拉是拿鹤的儿子；'),
('CUV', '路加福音', 42, 3, 35, '拿鹤是西鹿的儿子；西鹿是拉吴的儿子；拉吴是法勒的儿子；法勒是希伯的儿子；希伯是沙拉的儿子；'),
('CUV', '路加福音', 42, 3, 36, '沙拉是该南的儿子；该南是亚法撒的儿子；亚法撒是闪的儿子；闪是挪亚的儿子；挪亚是拉麦的儿子；'),
('CUV', '路加福音', 42, 3, 37, '拉麦是玛土撒拉的儿子；玛土撒拉是以诺的儿子；以诺是雅列的儿子；雅列是玛勒列的儿子；玛勒列是该南的儿子；该南是以挪士的儿子；'),
('CUV', '路加福音', 42, 3, 38, '以挪士是塞特的儿子；塞特是亚当的儿子；亚当是神的儿子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 4, 1, '耶稣被圣灵充满，从约但河回来，圣灵将他引到旷野，四十天受魔鬼的试探。'),
('CUV', '路加福音', 42, 4, 2, '那些日子没有吃甚么；日子满了，他就饿了。'),
('CUV', '路加福音', 42, 4, 3, '魔鬼对他说：你若是神的儿子，可以吩咐这块石头变成食物。'),
('CUV', '路加福音', 42, 4, 4, '耶稣回答说：经上记著说：人活著不是单靠食物，乃是靠神口里所出的一切话。'),
('CUV', '路加福音', 42, 4, 5, '魔鬼又领他上了高山，霎时间把天下的万国都指给他看，'),
('CUV', '路加福音', 42, 4, 6, '对他说：这一切权柄、荣华，我都要给你，因为这原是交付我的，我愿意给谁就给谁。'),
('CUV', '路加福音', 42, 4, 7, '你若在我面前下拜，这都要归你。'),
('CUV', '路加福音', 42, 4, 8, '耶稣说：经上记著说：当拜主─你的神，单要事奉他。'),
('CUV', '路加福音', 42, 4, 9, '魔鬼又领他到耶路撒冷去，叫他站在殿顶（顶：原文是翅）上，对他说：你若是神的儿子，可以从这里跳下去；'),
('CUV', '路加福音', 42, 4, 10, '因为经上记著说：主要为你吩咐他的使者保护你；'),
('CUV', '路加福音', 42, 4, 11, '他们要用手托著你，免得你的脚碰在石头上。'),
('CUV', '路加福音', 42, 4, 12, '耶稣对他说：经上说：不可试探主─你的神。'),
('CUV', '路加福音', 42, 4, 13, '魔鬼用完了各样的试探，就暂时离开耶稣。'),
('CUV', '路加福音', 42, 4, 14, '耶稣满有圣灵的能力，回到加利利；他的名声就传遍了四方。'),
('CUV', '路加福音', 42, 4, 15, '他在各会堂里教训人，众人都称赞他。'),
('CUV', '路加福音', 42, 4, 16, '耶稣来到拿撒勒，就是他长大的地方。在安息日，照他平常的规矩进了会堂，站起来要念圣经。'),
('CUV', '路加福音', 42, 4, 17, '有人把先知以赛亚的书交给他，他就打开，找到一处写著说：'),
('CUV', '路加福音', 42, 4, 18, '主的灵在我身上，因为他用膏膏我，叫我传福音给贫穷的人；差遣我报告：被掳的得释放，瞎眼的得看见，叫那受压制的得自由，'),
('CUV', '路加福音', 42, 4, 19, '报告神悦纳人的禧年。'),
('CUV', '路加福音', 42, 4, 20, '于是把书卷起来，交还执事，就坐下。会堂里的人都定睛看他。'),
('CUV', '路加福音', 42, 4, 21, '耶稣对他们说：今天这经应验在你们耳中了。'),
('CUV', '路加福音', 42, 4, 22, '众人都称赞他，并希奇他口中所出的恩言；又说：这不是约瑟的儿子么？'),
('CUV', '路加福音', 42, 4, 23, '耶稣对他们说：你们必引这俗语向我说：医生，你医治自己罢！我们听见你在迦百农所行的事，也当行在你自己家乡里；'),
('CUV', '路加福音', 42, 4, 24, '又说：我实在告诉你们，没有先知在自己家乡被人悦纳的。'),
('CUV', '路加福音', 42, 4, 25, '我对你们说实话，当以利亚的时候，天闭塞了三年零六个月，遍地有大饥荒，那时，以色列中有许多寡妇，'),
('CUV', '路加福音', 42, 4, 26, '以利亚并没有奉差往他们一个人那里去，只奉差往西顿的撒勒法一个寡妇那里去。'),
('CUV', '路加福音', 42, 4, 27, '先知以利沙的时候，以色列中有许多长大痲疯的，但内中除了叙利亚国的乃缦，没有一个得洁净的。'),
('CUV', '路加福音', 42, 4, 28, '会堂里的人听见这话，都怒气满胸，'),
('CUV', '路加福音', 42, 4, 29, '就起来撵他出城，他们的城造在山上；他们带他到山崖，要把他推下去。'),
('CUV', '路加福音', 42, 4, 30, '他却从他们中间直行，过去了。'),
('CUV', '路加福音', 42, 4, 31, '耶稣下到迦百农，就是加利利的一座城，在安息日教训众人。'),
('CUV', '路加福音', 42, 4, 32, '他们很希奇他的教训，因为他的话里有权柄。'),
('CUV', '路加福音', 42, 4, 33, '在会堂里有一个人，被污鬼的精气附著，大声喊叫说：'),
('CUV', '路加福音', 42, 4, 34, '唉！拿撒勒的耶稣，我们与你有甚么相干？你来灭我们么？我知道你是谁，乃是神的圣者。'),
('CUV', '路加福音', 42, 4, 35, '耶稣责备他说：不要作声，从这人身上出来罢！鬼把那人摔倒在众人中间，就出来了，却也没有害他。'),
('CUV', '路加福音', 42, 4, 36, '众人都惊讶，彼此对问说：这是甚么道理呢？因为他用权柄能力吩咐污鬼，污鬼就出来。'),
('CUV', '路加福音', 42, 4, 37, '于是耶稣的名声传遍了周围地方。'),
('CUV', '路加福音', 42, 4, 38, '耶稣出了会堂，进了西门的家。西门的岳母害热病甚重，有人为他求耶稣。'),
('CUV', '路加福音', 42, 4, 39, '耶稣站在他旁边，斥责那热病，热就退了。他立刻起来服事他们。'),
('CUV', '路加福音', 42, 4, 40, '日落的时候，凡有病人的，不论害甚么病，都带到耶稣那里。耶稣按手在他们各人身上，医好他们。'),
('CUV', '路加福音', 42, 4, 41, '又有鬼从好些人身上出来，喊著说：你是神的儿子。耶稣斥责他们，不许他们说话。因为他们知道他是基督。'),
('CUV', '路加福音', 42, 4, 42, '天亮的时候，耶稣出来，走到旷野地方。众人去找他，到了他那里，要留住他，不要他离开他们。'),
('CUV', '路加福音', 42, 4, 43, '但耶稣对他们说：我也必须在别城传神国的福音，因我奉差原是为此。'),
('CUV', '路加福音', 42, 4, 44, '于是耶稣在加利利的各会堂传道。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 5, 1, '耶稣站在革尼撒勒湖边，众人拥挤他，要听神的道。'),
('CUV', '路加福音', 42, 5, 2, '他见有两只船湾在湖边；打鱼的人却离开船洗网去了。'),
('CUV', '路加福音', 42, 5, 3, '有一只船是西门的，耶稣就上去，请他把船撑开，稍微离岸，就坐下，从船上教训众人。'),
('CUV', '路加福音', 42, 5, 4, '讲完了，对西门说：把船开到水深之处，下网打鱼。'),
('CUV', '路加福音', 42, 5, 5, '西门说：夫子，我们整夜劳力，并没有打著甚么。但依从你的话，我就下网。'),
('CUV', '路加福音', 42, 5, 6, '他们下了网，就圈住许多鱼，网险些裂开，'),
('CUV', '路加福音', 42, 5, 7, '便招呼那只船上的同伴来帮助。他们就来，把鱼装满了两只船，甚至船要沉下去。'),
('CUV', '路加福音', 42, 5, 8, '西门彼得看见，就俯伏在耶稣膝前，说：主阿！离开我，我是个罪人！'),
('CUV', '路加福音', 42, 5, 9, '他和一切同在的人都惊讶这一网所打的鱼。'),
('CUV', '路加福音', 42, 5, 10, '他的伙伴西庇太的儿子雅各、约翰，也是这样。耶稣对西门说：不要怕！从今以后，你要得人了。'),
('CUV', '路加福音', 42, 5, 11, '他们把两只船拢了岸，就撇下所有的，跟从了耶稣。'),
('CUV', '路加福音', 42, 5, 12, '有一回，耶稣在一个城里，有人满身长了大痲疯，看见他，就俯伏在地，求他说：主若肯，必能叫我洁净了。'),
('CUV', '路加福音', 42, 5, 13, '耶稣伸手摸他，说：我肯，你洁净了罢！大痲疯立刻就离了他的身。'),
('CUV', '路加福音', 42, 5, 14, '耶稣嘱咐他：你切不可告诉人，只要去把身体给祭司察看，又要为你得了洁净，照摩西所吩咐的献上礼物，对众人作证据。'),
('CUV', '路加福音', 42, 5, 15, '但耶稣的名声越发传扬出去。有极多的人聚集来听道，也指望医治他们的病。'),
('CUV', '路加福音', 42, 5, 16, '耶稣却退到旷野去祷告。'),
('CUV', '路加福音', 42, 5, 17, '有一天，耶稣教训人，有法利赛人和教法师在旁边坐著；他们是从加利利各乡村和犹太并耶路撒冷来的。主的能力与耶稣同在，使他能医治病人。'),
('CUV', '路加福音', 42, 5, 18, '有人用褥子抬著一个瘫子，要抬进去放在耶稣面前，'),
('CUV', '路加福音', 42, 5, 19, '却因人多，寻不出法子抬进去，就上了房顶，从瓦间把他连褥子缒到当中，正在耶稣面前。'),
('CUV', '路加福音', 42, 5, 20, '耶稣见他们的信心，就对瘫子说：你的罪赦了。'),
('CUV', '路加福音', 42, 5, 21, '文士和法利赛人就议论说：这说僭妄话的是谁？除了神以外，谁能赦罪呢？'),
('CUV', '路加福音', 42, 5, 22, '耶稣知道他们所议论的，就说：你们心里议论的是甚么呢？'),
('CUV', '路加福音', 42, 5, 23, '或说你的罪赦了，或说你起来行走，那一样容易呢？'),
('CUV', '路加福音', 42, 5, 24, '但要叫你们知道，人子在地上有赦罪的权柄。就对瘫子说：我吩咐你，起来，拿你的褥子回家去罢！'),
('CUV', '路加福音', 42, 5, 25, '那人当众人面前立刻起来，拿著他所躺卧的褥子回家去，归荣耀与神。'),
('CUV', '路加福音', 42, 5, 26, '众人都惊奇，也归荣耀与神，并且满心惧怕，说：我们今日看见非常的事了。'),
('CUV', '路加福音', 42, 5, 27, '这事以后，耶稣出去，看见一个税吏，名叫利未，坐在税关上，就对他说：你跟从我来。'),
('CUV', '路加福音', 42, 5, 28, '他就撇下所有的，起来，跟从了耶稣。'),
('CUV', '路加福音', 42, 5, 29, '利未在自己家里为耶稣大摆筵席，有许多税吏和别人与他们一同坐席。'),
('CUV', '路加福音', 42, 5, 30, '法利赛人和文士就向耶稣的门徒发怨言说：你们为甚么和税吏并罪人一同吃喝呢？'),
('CUV', '路加福音', 42, 5, 31, '耶稣对他们说：无病的人用不著医生；有病的人才用得著。'),
('CUV', '路加福音', 42, 5, 32, '我来本不是召义人悔改，乃是召罪人悔改。'),
('CUV', '路加福音', 42, 5, 33, '他们说：约翰的门徒屡次禁食祈祷，法利赛人的门徒也是这样；惟独你的门徒又吃又喝。'),
('CUV', '路加福音', 42, 5, 34, '耶稣对他们说：新郎和陪伴之人同在的时候，岂能叫陪伴之人禁食呢？'),
('CUV', '路加福音', 42, 5, 35, '但日子将到，新郎要离开他们，那日他们就要禁食了。'),
('CUV', '路加福音', 42, 5, 36, '耶稣又设一个比喻，对他们说：没有人把新衣服撕下一块来补在旧衣服上；若是这样，就把新的撕破了，并且所撕下来的那块新的和旧的也不相称。'),
('CUV', '路加福音', 42, 5, 37, '也没有人把新酒装在旧皮袋里；若是这样，新酒必将皮袋裂开，酒便漏出来，皮袋也就坏了。'),
('CUV', '路加福音', 42, 5, 38, '但新酒必须装在新皮袋里。'),
('CUV', '路加福音', 42, 5, 39, '没有人喝了陈酒又想喝新的；他总说陈的好。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 6, 1, '有一个安息日，耶稣从麦地经过。他的门徒掐了麦穗，用手搓著吃。'),
('CUV', '路加福音', 42, 6, 2, '有几个法利赛人说：你们为甚么作安息日不可作的事呢？'),
('CUV', '路加福音', 42, 6, 3, '耶稣对他们说：经上记著大卫和跟从他的人饥饿之时所作的事，连这个你们也没有念过么？'),
('CUV', '路加福音', 42, 6, 4, '他怎么进了神的殿，拿陈设饼吃，又给跟从的人吃？这饼除了祭司以外，别人都不可吃。'),
('CUV', '路加福音', 42, 6, 5, '又对他们说：人子是安息日的主。'),
('CUV', '路加福音', 42, 6, 6, '又有一个安息日，耶稣进了会堂教训人，在那里有一个人右手枯干了。'),
('CUV', '路加福音', 42, 6, 7, '文士和法利赛人窥探耶稣，在安息日治病不治病，要得把柄去告他。'),
('CUV', '路加福音', 42, 6, 8, '耶稣却知道他们的意念，就对那枯干一只手的人说：起来！站在当中。那人就起来，站著。'),
('CUV', '路加福音', 42, 6, 9, '耶稣对他们说：我问你们，在安息日行善行恶，救命害命，那样是可以的呢？'),
('CUV', '路加福音', 42, 6, 10, '他就周围看著他们众人，对那人说：伸出手来！他把手一伸，手就复了原。'),
('CUV', '路加福音', 42, 6, 11, '他们就满心大怒，彼此商议怎样处治耶稣。'),
('CUV', '路加福音', 42, 6, 12, '那时，耶稣出去，上山祷告，整夜祷告神；'),
('CUV', '路加福音', 42, 6, 13, '到了天亮，叫他的门徒来，就从他们中间挑选十二个人，称他们为使徒。'),
('CUV', '路加福音', 42, 6, 14, '这十二个人有西门，耶稣又给他起名叫彼得，还有他兄弟安得烈，又有雅各和约翰，腓力和巴多罗买，'),
('CUV', '路加福音', 42, 6, 15, '马太和多马，亚勒腓的儿子雅各和奋锐党的西门，'),
('CUV', '路加福音', 42, 6, 16, '雅各的儿子（或作：兄弟）犹大，和卖主的加略人犹大。'),
('CUV', '路加福音', 42, 6, 17, '耶稣和他们下了山，站在一块平地上；同站的有许多门徒，又有许多百姓，从犹太全地和耶路撒冷，并推罗、西顿的海边来，都要听他讲道，又指望医治他们的病；'),
('CUV', '路加福音', 42, 6, 18, '还有被污鬼缠磨的，也得了医治。'),
('CUV', '路加福音', 42, 6, 19, '众人都想要摸他；因为有能力从他身上发出来，医好了他们。'),
('CUV', '路加福音', 42, 6, 20, '耶稣举目看著门徒，说：你们贫穷的人有福了！因为神的国是你们的。'),
('CUV', '路加福音', 42, 6, 21, '你们饥饿的人有福了！因为你们将要饱足。你们哀哭的人有福了！因为你们将要喜笑。'),
('CUV', '路加福音', 42, 6, 22, '人为人子恨恶你们，拒绝你们，辱骂你们，弃掉你们的名，以为是恶，你们就有福了！'),
('CUV', '路加福音', 42, 6, 23, '当那日，你们要欢喜跳跃，因为你们在天上的赏赐是大的。他们的祖宗待先知也是这样。'),
('CUV', '路加福音', 42, 6, 24, '但你们富足的人有祸了！因为你们受过你们的安慰。'),
('CUV', '路加福音', 42, 6, 25, '你们饱足的人有祸了！因为你们将要饥饿。你们喜笑的人有祸了！因为你们将要哀恸哭泣。'),
('CUV', '路加福音', 42, 6, 26, '人都说你们好的时候，你们就有祸了！因为他们的祖宗待假先知也是这样。'),
('CUV', '路加福音', 42, 6, 27, '只是我告诉你们这听道的人，你们的仇敌，要爱他！恨你们的，要待他好！'),
('CUV', '路加福音', 42, 6, 28, '咒诅你们的，要为他祝福！凌辱你们的，要为他祷告！'),
('CUV', '路加福音', 42, 6, 29, '有人打你这边的脸，连那边的脸也由他打。有人夺你的外衣，连里衣也由他拿去。'),
('CUV', '路加福音', 42, 6, 30, '凡求你的，就给他。有人夺你的东西去，不用再要回来。'),
('CUV', '路加福音', 42, 6, 31, '你们愿意人怎样待你们，你们也要怎样待人。'),
('CUV', '路加福音', 42, 6, 32, '你们若单爱那爱你们的人，有甚么可酬谢的呢？就是罪人也爱那爱他们的人。'),
('CUV', '路加福音', 42, 6, 33, '你们若善待那善待你们的人，有甚么可酬谢的呢？就是罪人也是这样行。'),
('CUV', '路加福音', 42, 6, 34, '你们若借给人，指望从他收回，有甚么可酬谢的呢？就是罪人也借给罪人，要如数收回。'),
('CUV', '路加福音', 42, 6, 35, '你们倒要爱仇敌，也要善待他们，并要借给人不指望偿还，你们的赏赐就必大了，你们也必作至高者的儿子；因为他恩待那忘恩的和作恶的。'),
('CUV', '路加福音', 42, 6, 36, '你们要慈悲，像你们的父慈悲一样。'),
('CUV', '路加福音', 42, 6, 37, '你们不要论断人，就不被论断；你们不要定人的罪，就不被定罪；你们要饶恕人，就必蒙饶恕（饶恕：原文作释放）；'),
('CUV', '路加福音', 42, 6, 38, '你们要给人，就必有给你们的，并且用十足的升斗，连摇带按，上尖下流的倒在你们怀里；因为你们用甚么量器量给人，也必用甚么量器量给你们。'),
('CUV', '路加福音', 42, 6, 39, '耶稣又用比喻对他们说：瞎子岂能领瞎子，两个人不是都要掉在坑里么？'),
('CUV', '路加福音', 42, 6, 40, '学生不能高过先生；凡学成了的不过和先生一样。'),
('CUV', '路加福音', 42, 6, 41, '为甚么看见你弟兄眼中有刺，却不想自己眼中有梁木呢？'),
('CUV', '路加福音', 42, 6, 42, '你不见自己眼中有梁木，怎能对你弟兄说：容我去掉你眼中的刺呢？你这假冒为善的人！先去掉自己眼中的梁木，然后才能看得清楚，去掉你弟兄眼中的刺。'),
('CUV', '路加福音', 42, 6, 43, '因为，没有好树结坏果子，也没有坏树结好果子。'),
('CUV', '路加福音', 42, 6, 44, '凡树木看果子，就可以认出他来。人不是从荆棘上摘无花果，也不是从蒺藜里摘葡萄。'),
('CUV', '路加福音', 42, 6, 45, '善人从他心里所存的善就发出善来；恶人从他心里所存的恶就发出恶来；因为心里所充满的，口里就说出来。'),
('CUV', '路加福音', 42, 6, 46, '你们为甚么称呼我主阿，主阿，却不遵我的话行呢？'),
('CUV', '路加福音', 42, 6, 47, '凡到我这里来，听见我的话就去行的，我要告诉你们他像甚么人：'),
('CUV', '路加福音', 42, 6, 48, '他像一个人盖房子，深深的挖地，把根基安在磐石上；到发大水的时候，水冲那房子，房子总不能摇动，因为根基立在磐石上（有古卷：因为盖造得好）。'),
('CUV', '路加福音', 42, 6, 49, '惟有听见不去行的，就像一个人在土地上盖房子，没有根基；水一冲，随即倒塌了，并且那房子坏的很大。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 7, 1, '耶稣对百姓讲完了这一切的话，就进了迦百农。'),
('CUV', '路加福音', 42, 7, 2, '有一个百夫长所宝贵的仆人害病，快要死了。'),
('CUV', '路加福音', 42, 7, 3, '百夫长风闻耶稣的事，就托犹太人的几个长老去求耶稣来救他的仆人。'),
('CUV', '路加福音', 42, 7, 4, '他们到了耶稣那里，就切切的求他说：你给他行这事是他所配得的；'),
('CUV', '路加福音', 42, 7, 5, '因为他爱我们的百姓，给我们建造会堂。'),
('CUV', '路加福音', 42, 7, 6, '耶稣就和他们同去。离那家不远，百夫长托几个朋友去见耶稣，对他说：主阿！不要劳动；因你到我舍下，我不敢当。'),
('CUV', '路加福音', 42, 7, 7, '我也自以为不配去见你，只要你说一句话，我的仆人就必好了。'),
('CUV', '路加福音', 42, 7, 8, '因为我在人的权下，也有兵在我以下，对这个说：去！他就去；对那个说：来！他就来；对我的仆人说：你作这事！他就去作。'),
('CUV', '路加福音', 42, 7, 9, '耶稣听见这话，就希奇他，转身对跟随的众人说：我告诉你们，这么大的信心，就是在以色列中，我也没有遇见过。'),
('CUV', '路加福音', 42, 7, 10, '那托来的人回到百夫长家里，看见仆人已经好了。'),
('CUV', '路加福音', 42, 7, 11, '过了不多时（有古卷：次日），耶稣往一座城去，这城名叫拿因，他的门徒和极多的人与他同行。'),
('CUV', '路加福音', 42, 7, 12, '将近城门，有一个死人被抬出来。这人是他母亲独生的儿子；他母亲又是寡妇。有城里的许多人同著寡妇送殡。'),
('CUV', '路加福音', 42, 7, 13, '主看见那寡妇，就怜悯他，对他说：不要哭！'),
('CUV', '路加福音', 42, 7, 14, '于是进前按著杠，抬的人就站住了。耶稣说：少年人，我吩咐你，起来！'),
('CUV', '路加福音', 42, 7, 15, '那死人就坐起，并且说话。耶稣便把他交给他母亲。'),
('CUV', '路加福音', 42, 7, 16, '众人都惊奇，归荣耀与神，说：有大先知在我们中间兴起来了！又说：神眷顾了他的百姓！'),
('CUV', '路加福音', 42, 7, 17, '他这事的风声就传遍了犹太和周围地方。'),
('CUV', '路加福音', 42, 7, 18, '约翰的门徒把这些事都告诉约翰。'),
('CUV', '路加福音', 42, 7, 19, '他便叫了两个门徒来，打发他们到主那里去，说：那将要来的是你么？还是我们等候别人呢？'),
('CUV', '路加福音', 42, 7, 20, '那两个人来到耶稣那里，说：施洗的约翰打发我们来问你：那将要来的是你么？还是我们等候别人呢？'),
('CUV', '路加福音', 42, 7, 21, '正当那时候，耶稣治好了许多有疾病的，受灾患的，被恶鬼附著的，又开恩叫好些瞎子能看见。'),
('CUV', '路加福音', 42, 7, 22, '耶稣回答说：你们去，把所看见所听见的事告诉约翰，就是瞎子看见，瘸子行走，长大痲疯的洁净，聋子听见，死人复活，穷人有福音传给他们。'),
('CUV', '路加福音', 42, 7, 23, '凡不因我跌倒的，就有福了！'),
('CUV', '路加福音', 42, 7, 24, '约翰所差来的人既走了，耶稣就对众人讲论约翰说：你们从前出去到旷野，是要看甚么呢？要看风吹动的芦苇么？'),
('CUV', '路加福音', 42, 7, 25, '你们出去，到底是要看甚么？要看穿细软衣服的人么？那穿华丽衣服、宴乐度日的人是在王宫里。'),
('CUV', '路加福音', 42, 7, 26, '你们出去，究竟是要看甚么？要看先知么？我告诉你们，是的，他比先知大多了。'),
('CUV', '路加福音', 42, 7, 27, '经上记著说：我要差遣我的使者在你前面预备道路，所说的就是这个人。'),
('CUV', '路加福音', 42, 7, 28, '我告诉你们，凡妇人所生的，没有一个大过约翰的；然而神国里最小的比他还大。'),
('CUV', '路加福音', 42, 7, 29, '众百姓和税吏既受过约翰的洗，听见这话，就以神为义；'),
('CUV', '路加福音', 42, 7, 30, '但法利赛人和律法师没有受过约翰的洗，竟为自己废弃了神的旨意。（29，30两节或作：众百姓和税吏听见了约翰的话，就受了他的洗，便以神为义；但法利赛人和律法师不受约翰的洗，竟为自己废弃了神的旨意。）'),
('CUV', '路加福音', 42, 7, 31, '主又说：这样，我可用甚么比这世代的人呢？他们好像甚么呢？'),
('CUV', '路加福音', 42, 7, 32, '好像孩童坐在街市上，彼此呼叫说：我们向你们吹笛，你们不跳舞；我们向你们举哀，你们不啼哭。'),
('CUV', '路加福音', 42, 7, 33, '施洗的约翰来，不吃饼，不喝酒，你们说他是被鬼附著的。'),
('CUV', '路加福音', 42, 7, 34, '人子来，也吃也喝，你们说他是贪食好酒的人，是税吏和罪人的朋友。'),
('CUV', '路加福音', 42, 7, 35, '但智慧之子都以智慧为是。'),
('CUV', '路加福音', 42, 7, 36, '有一个法利赛人请耶稣和他吃饭；耶稣就到法利赛人家里去坐席。'),
('CUV', '路加福音', 42, 7, 37, '那城里有一个女人，是个罪人，知道耶稣在法利赛人家里坐席，就拿著盛香膏的玉瓶，'),
('CUV', '路加福音', 42, 7, 38, '站在耶稣背后，挨著他的脚哭，眼泪湿了耶稣的脚，就用自己的头发擦干，又用嘴连连亲他的脚，把香膏抹上。'),
('CUV', '路加福音', 42, 7, 39, '请耶稣的法利赛人看见这事，心里说：这人若是先知，必知道摸他的是谁，是个怎样的女人，乃是个罪人。'),
('CUV', '路加福音', 42, 7, 40, '耶稣对他说：西门！我有句话要对你说。西门说：夫子，请说。'),
('CUV', '路加福音', 42, 7, 41, '耶稣说：一个债主有两个人欠他的债；一个欠五十两银子，一个欠五两银子；'),
('CUV', '路加福音', 42, 7, 42, '因为他们无力偿还，债主就开恩免了他们两个人的债。这两个人那一个更爱他呢？'),
('CUV', '路加福音', 42, 7, 43, '西门回答说：我想是那多得恩免的人。耶稣说：你断的不错。'),
('CUV', '路加福音', 42, 7, 44, '于是转过来向著那女人，便对西门说：你看见这女人么？我进了你的家，你没有给我水洗脚；但这女人用眼泪湿了我的脚，用头发擦干。'),
('CUV', '路加福音', 42, 7, 45, '你没有与我亲嘴；但这女人从我进来的时候就不住的用嘴亲我的脚。'),
('CUV', '路加福音', 42, 7, 46, '你没有用油抹我的头；但这女人用香膏抹我的脚。'),
('CUV', '路加福音', 42, 7, 47, '所以我告诉你，他许多的罪都赦免了，因为他的爱多；但那赦免少的，他的爱就少。'),
('CUV', '路加福音', 42, 7, 48, '于是对那女人说：你的罪赦免了。'),
('CUV', '路加福音', 42, 7, 49, '同席的人心里说：这是甚么人，竟赦免人的罪呢？'),
('CUV', '路加福音', 42, 7, 50, '耶稣对那女人说：你的信救了你；平平安安的回去罢！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 8, 1, '过了不多日，耶稣周游各城各乡传道，宣讲神国的福音。和他同去的有十二个门徒，'),
('CUV', '路加福音', 42, 8, 2, '还有被恶鬼所附、被疾病所累、已经治好的几个妇女，内中有称为抹大拉的马利亚，曾有七个鬼从他身上赶出来，'),
('CUV', '路加福音', 42, 8, 3, '又有希律的家宰苦撒的妻子约亚拿，并苏撒拿，和好些别的妇女，都是用自己的财物供给耶稣和门徒。'),
('CUV', '路加福音', 42, 8, 4, '当许多人聚集、又有人从各城里出来见耶稣的时候，耶稣就用比喻说：'),
('CUV', '路加福音', 42, 8, 5, '有一个撒种的出去撒种。撒的时候，有落在路旁的，被人践踏，天上的飞鸟又来吃尽了。'),
('CUV', '路加福音', 42, 8, 6, '有落在磐石上的，一出来就枯干了，因为得不著滋润。'),
('CUV', '路加福音', 42, 8, 7, '有落在荆棘里的，荆棘一同生长，把他挤住了。'),
('CUV', '路加福音', 42, 8, 8, '又有落在好土里的，生长起来，结实百倍。耶稣说了这些话，就大声说：有耳可听的，就应当听！'),
('CUV', '路加福音', 42, 8, 9, '门徒问耶稣说：这比喻是甚么意思呢？'),
('CUV', '路加福音', 42, 8, 10, '他说：神国的奥秘只叫你们知道；至于别人，就用比喻，叫他们看也看不见，听也听不明。'),
('CUV', '路加福音', 42, 8, 11, '这比喻乃是这样：种子就是神的道。'),
('CUV', '路加福音', 42, 8, 12, '那些在路旁的，就是人听了道，随后魔鬼来，从他们心里把道夺去，恐怕他们信了得救.'),
('CUV', '路加福音', 42, 8, 13, '那些在磐石上的，就是人听道，欢喜领受，但心中没有根，不过暂时相信，及至遇见试炼就退后了。'),
('CUV', '路加福音', 42, 8, 14, '那落在荆棘里的，就是人听了道，走开以后，被今生的思虑、钱财、宴乐挤住了，便结不出成熟的子粒来。'),
('CUV', '路加福音', 42, 8, 15, '那落在好土里的，就是人听了道，持守在诚实善良的心里，并且忍耐著结实。'),
('CUV', '路加福音', 42, 8, 16, '没有人点灯用器皿盖上，或放在床底下，乃是放在灯台上，叫进来的人看见亮光。'),
('CUV', '路加福音', 42, 8, 17, '因为掩藏的事没有不显出来的；隐瞒的事没有不露出来被人知道的。'),
('CUV', '路加福音', 42, 8, 18, '所以，你们应当小心怎样听；因为凡有的，还要加给他；凡没有的，连他自以为有的，也要夺去。'),
('CUV', '路加福音', 42, 8, 19, '耶稣的母亲和他弟兄来了，因为人多，不得到他跟前。'),
('CUV', '路加福音', 42, 8, 20, '有人告诉他说：你母亲和你弟兄站在外边，要见你。'),
('CUV', '路加福音', 42, 8, 21, '耶稣回答说：听了神之道而遵行的人就是我的母亲，我的弟兄了。'),
('CUV', '路加福音', 42, 8, 22, '有一天，耶稣和门徒上了船，对门徒说：我们可以渡到湖那边去。他们就开了船。'),
('CUV', '路加福音', 42, 8, 23, '正行的时候，耶稣睡著了。湖上忽然起了暴风，船将满了水，甚是危险。'),
('CUV', '路加福音', 42, 8, 24, '门徒来叫醒了他，说：夫子！夫子！我们丧命啦！耶稣醒了，斥责那狂风大浪；风浪就止住，平静了。'),
('CUV', '路加福音', 42, 8, 25, '耶稣对他们说：你们的信心在那里呢？他们又惧怕又希奇，彼此说：这到底是谁？他吩咐风和水，连风和水也听从他了。'),
('CUV', '路加福音', 42, 8, 26, '他们到了格拉森（有古卷：加大拉）人的地方，就是加利利的对面。'),
('CUV', '路加福音', 42, 8, 27, '耶稣上了岸，就有城里一个被鬼附著的人迎面而来。这个人许久不穿衣服，不住房子，只住在坟茔里。'),
('CUV', '路加福音', 42, 8, 28, '他见了耶稣，就俯伏在他面前，大声喊叫，说：至高神的儿子耶稣，我与你有甚么相干？求你不要叫我受苦！'),
('CUV', '路加福音', 42, 8, 29, '是因耶稣曾吩咐污鬼从那人身上出来。原来这鬼屡次抓住他；他常被人看守，又被铁链和脚镣捆锁，他竟把锁链挣断，被鬼赶到旷野去。'),
('CUV', '路加福音', 42, 8, 30, '耶稣问他说：你名叫甚么？他说：我名叫群；这是因为附著他的鬼多。'),
('CUV', '路加福音', 42, 8, 31, '鬼就央求耶稣，不要吩咐他们到无底坑里去。'),
('CUV', '路加福音', 42, 8, 32, '那里有一大群猪在山上吃食。鬼央求耶稣，准他们进入猪里去。耶稣准了他们，'),
('CUV', '路加福音', 42, 8, 33, '鬼就从那人出来，进入猪里去。于是那群猪闯下山崖，投在湖里淹死了。'),
('CUV', '路加福音', 42, 8, 34, '放猪的看见这事就逃跑了，去告诉城里和乡下的人。'),
('CUV', '路加福音', 42, 8, 35, '众人出来要看是甚么事；到了耶稣那里，看见鬼所离开的那人，坐在耶稣脚前，穿著衣服，心里明白过来，他们就害怕。'),
('CUV', '路加福音', 42, 8, 36, '看见这事的便将被鬼附著的人怎么得救告诉他们。'),
('CUV', '路加福音', 42, 8, 37, '格拉森四围的人，因为害怕得很，都求耶稣离开他们；耶稣就上船回去了。'),
('CUV', '路加福音', 42, 8, 38, '鬼所离开的那人恳求和耶稣同在；耶稣却打发他回去，说：'),
('CUV', '路加福音', 42, 8, 39, '你回家去，传说神为你作了何等大的事。他就去，满城里传扬耶稣为他作了何等大的事。'),
('CUV', '路加福音', 42, 8, 40, '耶稣回来的时候，众人迎接他，因为他们都等候他。'),
('CUV', '路加福音', 42, 8, 41, '有一个管会堂的，名叫睚鲁，来俯伏在耶稣脚前，求耶稣到他家里去；'),
('CUV', '路加福音', 42, 8, 42, '因他有一个独生女儿，约有十二岁，快要死了。耶稣去的时候，众人拥挤他。'),
('CUV', '路加福音', 42, 8, 43, '有一个女人，患了十二年的血漏，在医生手里花尽了他一切养生的，并没有一人能医好他。'),
('CUV', '路加福音', 42, 8, 44, '他来到耶稣背后，摸他的衣裳䍁子，血漏立刻就止住了。'),
('CUV', '路加福音', 42, 8, 45, '耶稣说：摸我的是谁？众人都不承认。彼得和同行的人都说：夫子，众人拥拥挤挤紧靠著你。（有古卷在此有：你还问摸我的是谁么？'),
('CUV', '路加福音', 42, 8, 46, '耶稣说：总有人摸我，因我觉得有能力从我身上出去。'),
('CUV', '路加福音', 42, 8, 47, '那女人知道不能隐藏，就战战兢兢的来俯伏在耶稣脚前，把摸他的缘故和怎样立刻得好了，当著众人都说出来。'),
('CUV', '路加福音', 42, 8, 48, '耶稣对他说：女儿，你的信救了你；平平安安的去罢！'),
('CUV', '路加福音', 42, 8, 49, '还说话的时候，有人从管会堂的家里来，说：你的女儿死了，不要劳动夫子。'),
('CUV', '路加福音', 42, 8, 50, '耶稣听见就对他说：不要怕，只要信！你的女儿就必得救。'),
('CUV', '路加福音', 42, 8, 51, '耶稣到了他的家，除了彼得、约翰、雅各，和女儿的父母，不许别人同他进去。'),
('CUV', '路加福音', 42, 8, 52, '众人都为这女儿哀哭捶胸。耶稣说：不要哭。他不是死了，是睡著了。'),
('CUV', '路加福音', 42, 8, 53, '他们晓得女儿已经死了，就嗤笑耶稣。'),
('CUV', '路加福音', 42, 8, 54, '耶稣拉著他的手，呼叫说：女儿，起来罢！'),
('CUV', '路加福音', 42, 8, 55, '他的灵魂便回来，他就立刻起来了。耶稣吩咐给他东西吃。'),
('CUV', '路加福音', 42, 8, 56, '他的父母惊奇得很；耶稣嘱咐他们，不要把所作的事告诉人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 9, 1, '耶稣叫齐了十二个门徒，给他们能力、权柄，制伏一切的鬼，医治各样的病，'),
('CUV', '路加福音', 42, 9, 2, '又差遣他们去宣传神国的道，医治病人，'),
('CUV', '路加福音', 42, 9, 3, '对他们说：行路的时候，不要带拐杖和口袋，不要带食物和银子，也不要带两件褂子。'),
('CUV', '路加福音', 42, 9, 4, '无论进那一家，就住在那里，也从那里起行。'),
('CUV', '路加福音', 42, 9, 5, '凡不接待你们的，你们离开那城的时候，要把脚上的尘土跺下去，见证他们的不是。'),
('CUV', '路加福音', 42, 9, 6, '门徒就出去，走遍各乡宣传福音，到处治病。'),
('CUV', '路加福音', 42, 9, 7, '分封的王希律听见耶稣所作的一切事，就游移不定；因为有人说：是约翰从死里复活；'),
('CUV', '路加福音', 42, 9, 8, '又有人说：是以利亚显现；还有人说：是古时的一个先知又活了。'),
('CUV', '路加福音', 42, 9, 9, '希律说：约翰我已经斩了，这却是甚么人？我竟听见他这样的事呢？就想要见他。'),
('CUV', '路加福音', 42, 9, 10, '使徒回来，将所作的事告诉耶稣，耶稣就带他们暗暗的离开那里，往一座城去；那城名叫伯赛大。'),
('CUV', '路加福音', 42, 9, 11, '但众人知道了，就跟著他去；耶稣便接待他们，对他们讲论神国的道，医治那些需医的人。'),
('CUV', '路加福音', 42, 9, 12, '日头快要平西，十二个门徒来对他说：请叫众人散开，他们好往四面乡村里去借宿找吃的，因为我们这里是野地。'),
('CUV', '路加福音', 42, 9, 13, '耶稣说：你们给他们吃罢！门徒说：我们不过有五个饼，两条鱼，若不去为这许多人买食物就不够。'),
('CUV', '路加福音', 42, 9, 14, '那时，人数约有五千。耶稣对门徒说：叫他们一排一排的坐下，每排大约五十个人。'),
('CUV', '路加福音', 42, 9, 15, '门徒就如此行，叫众人都坐下。'),
('CUV', '路加福音', 42, 9, 16, '耶稣拿著这五个饼，两条鱼，望著天祝福，擘开，递给门徒，摆在众人面前。'),
('CUV', '路加福音', 42, 9, 17, '他们就吃，并且都吃饱了；把剩下的零碎收拾起来，装满了十二篮子。'),
('CUV', '路加福音', 42, 9, 18, '耶稣自己祷告的时候，门徒也同他在那里。耶稣问他们说：众人说我是谁？'),
('CUV', '路加福音', 42, 9, 19, '他们说：有人说是施洗的约翰；有人说是以利亚；还有人说是古时的一个先知又活了。'),
('CUV', '路加福音', 42, 9, 20, '耶稣说：你们说我是谁？彼得回答说：是神所立的基督。'),
('CUV', '路加福音', 42, 9, 21, '耶稣切切的嘱咐他们，不可将这事告诉人，'),
('CUV', '路加福音', 42, 9, 22, '又说：人子必须受许多的苦，被长老、祭司长、和文士弃绝，并且被杀，第三日复活。'),
('CUV', '路加福音', 42, 9, 23, '耶稣又对众人说：若有人要跟从我，就当舍己，天天背起他的十字架来跟从我。'),
('CUV', '路加福音', 42, 9, 24, '因为，凡要救自己生命（生命：或作灵魂；下同）的，必丧掉生命；凡为我丧掉生命的，必救了生命。'),
('CUV', '路加福音', 42, 9, 25, '人若赚得全世界，却丧了自己，赔上自己，有甚么益处呢？'),
('CUV', '路加福音', 42, 9, 26, '凡把我和我的道当作可耻的，人子在自己的荣耀里，并天父与圣天使的荣耀里降临的时候，也要把那人当作可耻的。'),
('CUV', '路加福音', 42, 9, 27, '我实在告诉你们，站在这里的，有人在没尝死味以前，必看见神的国。'),
('CUV', '路加福音', 42, 9, 28, '说了这话以后约有八天，耶稣带著彼得、约翰、雅各上山去祷告。'),
('CUV', '路加福音', 42, 9, 29, '正祷告的时候，他的面貌就改变了，衣服洁白放光。'),
('CUV', '路加福音', 42, 9, 30, '忽然有摩西、以利亚两个人同耶稣说话；'),
('CUV', '路加福音', 42, 9, 31, '他们在荣光里显现，谈论耶稣去世的事，就是他在耶路撒冷将要成的事。'),
('CUV', '路加福音', 42, 9, 32, '彼得和他的同伴都打盹，既清醒了，就看见耶稣的荣光，并同他站著的那两个人。'),
('CUV', '路加福音', 42, 9, 33, '二人正要和耶稣分离的时候，彼得对耶稣说：夫子，我们在这里真好！可以搭三座棚，一座为你，一座为摩西，一座为以利亚。他却不知道所说的是甚么。'),
('CUV', '路加福音', 42, 9, 34, '说这话的时候，有一朵云彩来遮盖他们；他们进入云彩里就惧怕。'),
('CUV', '路加福音', 42, 9, 35, '有声音从云彩里出来，说：这是我的儿子，我所拣选的（有古卷：这是我的爱子），你们要听他。'),
('CUV', '路加福音', 42, 9, 36, '声音住了，只见耶稣一人在那里。当那些日子，门徒不提所看见的事，一样也不告诉人。'),
('CUV', '路加福音', 42, 9, 37, '第二天，他们下了山，就有许多人迎见耶稣。'),
('CUV', '路加福音', 42, 9, 38, '其中有一人喊叫说：夫子！求你看顾我的儿子，因为他是我的独生子。'),
('CUV', '路加福音', 42, 9, 39, '他被鬼抓住就忽然喊叫；鬼又叫他抽疯，口中流沫，并且重重的伤害他，难以离开他。'),
('CUV', '路加福音', 42, 9, 40, '我求过你的门徒，把鬼赶出去，他们却是不能。'),
('CUV', '路加福音', 42, 9, 41, '耶稣说：嗳！这又不信又悖谬的世代阿，我在你们这里，忍耐你们要到几时呢？将你的儿子带到这里来罢！'),
('CUV', '路加福音', 42, 9, 42, '正来的时候，鬼把他摔倒，叫他重重的抽疯。耶稣就斥责那污鬼，把孩子治好了，交给他父亲。'),
('CUV', '路加福音', 42, 9, 43, '众人都诧异神的大能（大能：或作威荣）。耶稣所作的一切事，众人正希奇的时候，耶稣对门徒说：'),
('CUV', '路加福音', 42, 9, 44, '你们要把这些话存在耳中，因为人子将要被交在人手里。'),
('CUV', '路加福音', 42, 9, 45, '他们不明白这话，意思乃是隐藏的，叫他们不能明白，他们也不敢问这话的意思。'),
('CUV', '路加福音', 42, 9, 46, '门徒中间起了议论，谁将为大。'),
('CUV', '路加福音', 42, 9, 47, '耶稣看出他们心中的议论，就领一个小孩子来，叫他站在自己旁边，'),
('CUV', '路加福音', 42, 9, 48, '对他们说：凡为我名接待这小孩子的，就是接待我；凡接待我的，就是接待那差我来的。你们中间最小的，他便为大。'),
('CUV', '路加福音', 42, 9, 49, '约翰说：夫子，我们看见一个人奉你的名赶鬼，我们就禁止他，因为他不与我们一同跟从你。'),
('CUV', '路加福音', 42, 9, 50, '耶稣说：不要禁止他；因为不敌挡你们的，就是帮助你们的。'),
('CUV', '路加福音', 42, 9, 51, '耶稣被接上升的日子将到，他就定意向耶路撒冷去，'),
('CUV', '路加福音', 42, 9, 52, '便打发使者在他前头走。他们到了撒玛利亚的一个村庄，要为他预备。'),
('CUV', '路加福音', 42, 9, 53, '那里的人不接待他，因他面向耶路撒冷去。'),
('CUV', '路加福音', 42, 9, 54, '他的门徒雅各、约翰看见了，就说：主阿，你要我们吩咐火从天上降下来烧灭他们，像以利亚所作的（有古卷无「像以利亚所作的」数字）么？'),
('CUV', '路加福音', 42, 9, 55, '耶稣转身责备两个门徒，说：你们的心如何，你们并不知道。'),
('CUV', '路加福音', 42, 9, 56, '人子来不是要灭人的性命（或作：灵魂；下同），是要救人的性命。说著就往别的村庄去了（有古卷只有五十五节首句，五十六节末句）。'),
('CUV', '路加福音', 42, 9, 57, '他们走路的时候，有一人对耶稣说：你无论往那里去，我要跟从你。'),
('CUV', '路加福音', 42, 9, 58, '耶稣说：狐狸有洞，天空的飞鸟有窝，只是人子没有枕头的地方。'),
('CUV', '路加福音', 42, 9, 59, '又对一个人说：跟从我来！那人说：主，容我先回去埋葬我的父亲。'),
('CUV', '路加福音', 42, 9, 60, '耶稣说：任凭死人埋葬他们的死人，你只管去传扬神国的道。'),
('CUV', '路加福音', 42, 9, 61, '又有一人说：主，我要跟从你，但容我先去辞别我家里的人。'),
('CUV', '路加福音', 42, 9, 62, '耶稣说：手扶著犁向后看的，不配进神的国。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 10, 1, '这事以后，主又设立七十个人，差遣他们两个两个的在他前面，往自己所要到的各城各地方去，'),
('CUV', '路加福音', 42, 10, 2, '就对他们说：要收的庄稼多，作工的人少。所以，你们当求庄稼的主打发工人出去收他的庄稼。'),
('CUV', '路加福音', 42, 10, 3, '你们去罢！我差你们出去，如同羊羔进入狼群。'),
('CUV', '路加福音', 42, 10, 4, '不要带钱囊，不要带口袋，不要带鞋；在路上也不要问人的安。'),
('CUV', '路加福音', 42, 10, 5, '无论进那一家，先要说：愿这一家平安。'),
('CUV', '路加福音', 42, 10, 6, '那里若有当得平安的人（当得平安的人：原文是平安之子），你们所求的平安就必临到那家；不然，就归与你们了。'),
('CUV', '路加福音', 42, 10, 7, '你们要住在那家，吃喝他们所供给的，因为工人得工价是应当的；不要从这家搬到那家。'),
('CUV', '路加福音', 42, 10, 8, '无论进那一城，人若接待你们，给你们摆上甚么，你们就吃甚么。'),
('CUV', '路加福音', 42, 10, 9, '要医治那城里的病人，对他们说：神的国临近你们了。'),
('CUV', '路加福音', 42, 10, 10, '无论进那一城，人若不接待你们，你们就到街上去，'),
('CUV', '路加福音', 42, 10, 11, '说：就是你们城里的尘土黏在我们的脚上，我们也当著你们擦去。虽然如此，你们该知道神的国临近了。'),
('CUV', '路加福音', 42, 10, 12, '我告诉你们，当审判的日子，所多玛所受的，比那城还容易受呢！'),
('CUV', '路加福音', 42, 10, 13, '哥拉汛哪，你有祸了！伯赛大阿，你有祸了！因为在你们中间所行的异能若行在推罗、西顿，他们早已披麻蒙灰，坐在地上悔改了。'),
('CUV', '路加福音', 42, 10, 14, '当审判的日子，推罗、西顿所受的，比你们还容易受呢！'),
('CUV', '路加福音', 42, 10, 15, '迦百农阿，你已经升到天上（或作：你将要升到天上么），将来必推下阴间。'),
('CUV', '路加福音', 42, 10, 16, '又对门徒说：听从你们的就是听从我；弃绝你们的就是弃绝我；弃绝我的就是弃绝那差我来的。'),
('CUV', '路加福音', 42, 10, 17, '那七十个人欢欢喜喜的回来，说：主阿！因你的名，就是鬼也服了我们。'),
('CUV', '路加福音', 42, 10, 18, '耶稣对他们说：我曾看见撒但从天上坠落，像闪电一样。'),
('CUV', '路加福音', 42, 10, 19, '我已经给你们权柄可以践踏蛇和蝎子，又胜过仇敌一切的能力，断没有甚么能害你们。'),
('CUV', '路加福音', 42, 10, 20, '然而，不要因鬼服了你们就欢喜，要因你们的名记录在天上欢喜。'),
('CUV', '路加福音', 42, 10, 21, '正当那时，耶稣被圣灵感动就欢乐，说：父阿，天地的主，我感谢你！因为你将这些事向聪明通达人就藏起来，向婴孩就显出来。父阿！是的，因为你的美意本是如此。'),
('CUV', '路加福音', 42, 10, 22, '一切所有的都是我父交付我的；除了父，没有人知道子是谁；除了子和子所愿意指示的，没有人知道父是谁。'),
('CUV', '路加福音', 42, 10, 23, '耶稣转身暗暗的对门徒说：看见你们所看见的，那眼睛就有福了。'),
('CUV', '路加福音', 42, 10, 24, '我告诉你们，从前有许多先知和君王要看你们所看的，却没有看见，要听你们所听的，却没有听见。'),
('CUV', '路加福音', 42, 10, 25, '有一个律法师起来试探耶稣，说：夫子！我该作甚么才可以承受永生？'),
('CUV', '路加福音', 42, 10, 26, '耶稣对他说：律法上写的是甚么？你念的是怎样呢？'),
('CUV', '路加福音', 42, 10, 27, '他回答说：「你要尽心、尽性、尽力、尽意爱主─你的神；又要爱邻舍如同自己。」'),
('CUV', '路加福音', 42, 10, 28, '耶稣说：「你回答的是；你这样行，就必得永生。」'),
('CUV', '路加福音', 42, 10, 29, '那人要显明自己有理，就对耶稣说：谁是我的邻舍呢？'),
('CUV', '路加福音', 42, 10, 30, '耶稣回答说：有一个人从耶路撒冷下耶利哥去，落在强盗手中。他们剥去他的衣裳，把他打个半死，就丢下他走了。'),
('CUV', '路加福音', 42, 10, 31, '偶然有一个祭司从这条路下来，看见他就从那边过去了。'),
('CUV', '路加福音', 42, 10, 32, '又有一个利未人来到这地方，看见他，也照样从那边过去了。'),
('CUV', '路加福音', 42, 10, 33, '惟有一个撒玛利亚人行路来到那里，看见他就动了慈心，'),
('CUV', '路加福音', 42, 10, 34, '上前用油和酒倒在他的伤处，包裹好了，扶他骑上自己的牲口，带到店里去照应他。'),
('CUV', '路加福音', 42, 10, 35, '第二天拿出二钱银子来，交给店主，说：你且照应他；此外所费用的，我回来必还你。'),
('CUV', '路加福音', 42, 10, 36, '你想，这三个人那一个是落在强盗手中的邻舍呢？'),
('CUV', '路加福音', 42, 10, 37, '他说：是怜悯他的。耶稣说：你去照样行罢。'),
('CUV', '路加福音', 42, 10, 38, '他们走路的时候，耶稣进了一个村庄。有一个女人，名叫马大，接他到自己家里。'),
('CUV', '路加福音', 42, 10, 39, '他有一个妹子，名叫马利亚，在耶稣脚前坐著听他的道。'),
('CUV', '路加福音', 42, 10, 40, '马大伺候的事多，心里忙乱，就进前来，说：主阿，我的妹子留下我一个人伺候，你不在意么？请吩咐他来帮助我。'),
('CUV', '路加福音', 42, 10, 41, '耶稣回答说：马大！马大！你为许多的事思虑烦扰，'),
('CUV', '路加福音', 42, 10, 42, '但是不可少的只有一件；马利亚已经选择那上好的福分，是不能夺去的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 11, 1, '耶稣在一个地方祷告；祷告完了，有个门徒对他说：求主教导我们祷告，像约翰教导他的门徒。'),
('CUV', '路加福音', 42, 11, 2, '耶稣说：你们祷告的时候，要说：我们在天上的父（有古卷只作：父阿）：愿人都尊你的名为圣。愿你的国降临；愿你的旨意行在地上，如同行在天上（有古卷无愿你的旨意云云）。'),
('CUV', '路加福音', 42, 11, 3, '我们日用的饮食，天天赐给我们。'),
('CUV', '路加福音', 42, 11, 4, '赦免我们的罪，因为我们也赦免凡亏欠我们的人。不叫我们遇见试探；救我们脱离凶恶（有古卷无末句）。'),
('CUV', '路加福音', 42, 11, 5, '耶稣又说：你们中间谁有一个朋友半夜到他那里去，说：朋友！请借给我三个饼；'),
('CUV', '路加福音', 42, 11, 6, '因为我有一个朋友行路，来到我这里，我没有甚么给他摆上。'),
('CUV', '路加福音', 42, 11, 7, '那人在里面回答说：不要搅扰我，门已经关闭，孩子们也同我在床上了，我不能起来给你。'),
('CUV', '路加福音', 42, 11, 8, '我告诉你们，虽不因他是朋友起来给他，但因他情词迫切的直求，就必起来照他所需用的给他。'),
('CUV', '路加福音', 42, 11, 9, '我又告诉你们，你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。'),
('CUV', '路加福音', 42, 11, 10, '因为，凡祈求的，就得著；寻找的，就寻见；叩门的，就给他开门。'),
('CUV', '路加福音', 42, 11, 11, '你们中间作父亲的，谁有儿子求饼，反给他石头呢？求鱼，反拿蛇当鱼给他呢？'),
('CUV', '路加福音', 42, 11, 12, '求鸡蛋，反给他蝎子呢？'),
('CUV', '路加福音', 42, 11, 13, '你们虽然不好，尚且知道拿好东西给儿女；何况天父，岂不更将圣灵给求他的人么？'),
('CUV', '路加福音', 42, 11, 14, '耶稣赶出一个叫人哑吧的鬼，鬼出去了，哑吧就说出话来；众人都希奇。'),
('CUV', '路加福音', 42, 11, 15, '内中却有人说：他是靠著鬼王别西卜赶鬼。'),
('CUV', '路加福音', 42, 11, 16, '又有人试探耶稣，向他求从天上来的神迹。'),
('CUV', '路加福音', 42, 11, 17, '他晓得他们的意念，便对他们说：凡一国自相纷争，就成为荒场；凡一家自相纷争，就必败落。'),
('CUV', '路加福音', 42, 11, 18, '若撒但自相纷争，他的国怎能站得住呢？因为你们说我是靠著别西卜赶鬼。'),
('CUV', '路加福音', 42, 11, 19, '我若靠著别西卜赶鬼，你们的子弟赶鬼又靠著谁呢？这样，他们就要断定你们的是非。'),
('CUV', '路加福音', 42, 11, 20, '我若靠著神的能力赶鬼，这就是神的国临到你们了。'),
('CUV', '路加福音', 42, 11, 21, '壮士披挂整齐，看守自己的住宅，他所有的都平安无事；'),
('CUV', '路加福音', 42, 11, 22, '但有一个比他更壮的来，胜过他，就夺去他所倚靠的盔甲兵器，又分了他的赃。'),
('CUV', '路加福音', 42, 11, 23, '不与我相合的，就是敌我的；不同我收聚的，就是分散的。'),
('CUV', '路加福音', 42, 11, 24, '污鬼离了人身，就在无水之地过来过去，寻求安歇之处；既寻不著，便说：我要回到我所出来的屋里去。'),
('CUV', '路加福音', 42, 11, 25, '到了，就看见里面打扫干净，修饰好了，'),
('CUV', '路加福音', 42, 11, 26, '便去另带了七个比自己更恶的鬼来，都进去住在那里。那人末后的景况比先前更不好了。'),
('CUV', '路加福音', 42, 11, 27, '耶稣正说这话的时候，众人中间有一个女人大声说：怀你胎的和乳养你的有福了！'),
('CUV', '路加福音', 42, 11, 28, '耶稣说：是，却还不如听神之道而遵守的人有福。'),
('CUV', '路加福音', 42, 11, 29, '当众人聚集的时候，耶稣开讲说：这世代是一个邪恶的世代。他们求看神迹，除了约拿的神迹以外，再没有神迹给他们看。'),
('CUV', '路加福音', 42, 11, 30, '约拿怎样为尼尼微人成了神迹，人子也要照样为这世代的人成了神迹。'),
('CUV', '路加福音', 42, 11, 31, '当审判的时候，南方的女王要起来定这世代的罪；因为他从地极而来，要听所罗门的智慧话。看哪！在这里有一人比所罗门更大。'),
('CUV', '路加福音', 42, 11, 32, '当审判的时候，尼尼微人要起来定这世代的罪，因为尼尼微人听了约拿所传的就悔改了。看哪！在这里有一人比约拿更大。'),
('CUV', '路加福音', 42, 11, 33, '没有人点灯放在地窨子里，或是斗底下，总是放在灯台上，使进来的人得见亮光。'),
('CUV', '路加福音', 42, 11, 34, '你眼睛就是身上的灯。你的眼睛若瞭亮，全身就光明；眼睛若昏花，全身就黑暗。'),
('CUV', '路加福音', 42, 11, 35, '所以，你要省察，恐怕你里头的光或者黑暗了。'),
('CUV', '路加福音', 42, 11, 36, '若是你全身光明，毫无黑暗，就必全然光明，如同灯的明光照亮你。'),
('CUV', '路加福音', 42, 11, 37, '说话的时候，有一个法利赛人请耶稣同他吃饭，耶稣就进去坐席。'),
('CUV', '路加福音', 42, 11, 38, '这法利赛人看见耶稣饭前不洗手便诧异。'),
('CUV', '路加福音', 42, 11, 39, '主对他说：如今你们法利赛人洗净杯盘的外面，你们里面却满了勒索和邪恶。'),
('CUV', '路加福音', 42, 11, 40, '无知的人哪，造外面的，不也造里面么？'),
('CUV', '路加福音', 42, 11, 41, '只要把里面的施舍给人，凡物于你们就都洁净了。'),
('CUV', '路加福音', 42, 11, 42, '你们法利赛人有祸了！因为你们将薄荷、芸香并各样菜蔬献上十分之一，那公义和爱神的事反倒不行了。这原是你们当行的；那也是不可不行的。'),
('CUV', '路加福音', 42, 11, 43, '你们法利赛人有祸了！因为你们喜爱会堂里的首位，又喜爱人在街市上问你们的安。'),
('CUV', '路加福音', 42, 11, 44, '你们有祸了！因为你们如同不显露的坟墓，走在上面的人并不知道。'),
('CUV', '路加福音', 42, 11, 45, '律法师中有一个回答耶稣说：夫子！你这样说也把我们糟蹋了。'),
('CUV', '路加福音', 42, 11, 46, '耶稣说：你们律法师也有祸了！因为你们把难担的担子放在人身上，自己一个指头却不肯动。'),
('CUV', '路加福音', 42, 11, 47, '你们有祸了！因为你们修造先知的坟墓，那先知正是你们的祖宗所杀的。'),
('CUV', '路加福音', 42, 11, 48, '可见你们祖宗所作的事，你们又证明又喜欢；因为他们杀了先知，你们修造先知的坟墓。'),
('CUV', '路加福音', 42, 11, 49, '所以，神用智慧（用智慧：或作的智者）曾说：我要差遣先知和使徒到他们那里去，有的他们要杀害，有的他们要逼迫，'),
('CUV', '路加福音', 42, 11, 50, '使创世以来所流众先知血的罪都要问在这世代的人身上，'),
('CUV', '路加福音', 42, 11, 51, '就是从亚伯的血起，直到被杀在坛和殿中间撒迦利亚的血为止。我实在告诉你们，这都要问在这世代的人身上。'),
('CUV', '路加福音', 42, 11, 52, '你们律法师有祸了！因为你们把知识的钥匙夺了去，自己不进去，正要进去的人你们也阻挡他们。'),
('CUV', '路加福音', 42, 11, 53, '耶稣从那里出来，文士和法利赛人就极力的催逼他，引动他多说话，'),
('CUV', '路加福音', 42, 11, 54, '私下窥听，要拿他的话柄。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 12, 1, '这时，有几万人聚集，甚至彼此践踏。耶稣开讲，先对门徒说：你们要防备法利赛人的酵，就是假冒为善。'),
('CUV', '路加福音', 42, 12, 2, '掩盖的事没有不露出来的；隐藏的事，没有不被人知道的。'),
('CUV', '路加福音', 42, 12, 3, '因此，你们在暗中所说的，将要在明处被人听见；在内室附耳所说的，将要在房上被人宣扬。'),
('CUV', '路加福音', 42, 12, 4, '我的朋友，我对你们说，那杀身体以后不能再作甚么的，不要怕他们。'),
('CUV', '路加福音', 42, 12, 5, '我要指示你们当怕的是谁：当怕那杀了以后又有权柄丢在地狱里的。我实在告诉你们，正要怕他。'),
('CUV', '路加福音', 42, 12, 6, '五个麻雀不是卖二分银子么？但在神面前，一个也不忘记；'),
('CUV', '路加福音', 42, 12, 7, '就是你们的头发，也都被数过了。不要惧怕，你们比许多麻雀还贵重！'),
('CUV', '路加福音', 42, 12, 8, '我又告诉你们，凡在人面前认我的，人子在神的使者面前也必认他；'),
('CUV', '路加福音', 42, 12, 9, '在人面前不认我的，人子在神的使者面前也必不认他。'),
('CUV', '路加福音', 42, 12, 10, '凡说话干犯人子的，还可得赦免；惟独亵渎圣灵的，总不得赦免。'),
('CUV', '路加福音', 42, 12, 11, '人带你们到会堂，并官府和有权柄的人面前，不要思虑怎么分诉，说甚么话；'),
('CUV', '路加福音', 42, 12, 12, '因为正在那时候，圣灵要指教你们当说的话。'),
('CUV', '路加福音', 42, 12, 13, '众人中有一个人对耶稣说：夫子！请你吩咐我的兄长和我分开家业。'),
('CUV', '路加福音', 42, 12, 14, '耶稣说：你这个人！谁立我作你们断事的官，给你们分家业呢？'),
('CUV', '路加福音', 42, 12, 15, '于是对众人说：你们要谨慎自守，免去一切的贪心，因为人的生命不在乎家道丰富。'),
('CUV', '路加福音', 42, 12, 16, '就用比喻对他们说：有一个财主田产丰盛；'),
('CUV', '路加福音', 42, 12, 17, '自己心里思想说：我的出产没有地方收藏，怎么办呢？'),
('CUV', '路加福音', 42, 12, 18, '又说：我要这么办：要把我的仓房拆了，另盖更大的，在那里好收藏我一切的粮食和财物，'),
('CUV', '路加福音', 42, 12, 19, '然后要对我的灵魂说：灵魂哪，你有许多财物积存，可作多年的费用，只管安安逸逸的吃喝快乐罢！'),
('CUV', '路加福音', 42, 12, 20, '神却对他说：无知的人哪，今夜必要你的灵魂；你所预备的要归谁呢？'),
('CUV', '路加福音', 42, 12, 21, '凡为自己积财，在神面前却不富足的，也是这样。'),
('CUV', '路加福音', 42, 12, 22, '耶稣又对门徒说：所以我告诉你们，不要为生命忧虑吃甚么，为身体忧虑穿甚么；'),
('CUV', '路加福音', 42, 12, 23, '因为生命胜于饮食，身体胜于衣裳。'),
('CUV', '路加福音', 42, 12, 24, '你想乌鸦，也不种也不收，又没有仓又没有库，神尚且养活他。你们比飞鸟是何等的贵重呢！'),
('CUV', '路加福音', 42, 12, 25, '你们那一个能用思虑使寿数多加一刻呢（或作：使身量多加一肘呢）？'),
('CUV', '路加福音', 42, 12, 26, '这最小的事，你们尚且不能作，为甚么还忧虑其余的事呢？'),
('CUV', '路加福音', 42, 12, 27, '你想百合花怎么长起来；他也不劳苦，也不纺线。然而我告诉你们，就是所罗门极荣华的时候，他所穿戴的，还不如这花一朵呢！'),
('CUV', '路加福音', 42, 12, 28, '你们这小信的人哪，野地里的草今天还在，明天就丢在炉里，神还给他这样的妆饰，何况你们呢！'),
('CUV', '路加福音', 42, 12, 29, '你们不要求吃甚么，喝甚么，也不要罣心；'),
('CUV', '路加福音', 42, 12, 30, '这都是外邦人所求的。你们必须用这些东西，你们的父是知道的。'),
('CUV', '路加福音', 42, 12, 31, '你们只要求他的国，这些东西就必加给你们了。'),
('CUV', '路加福音', 42, 12, 32, '你们这小群，不要惧怕，因为你们的父乐意把国赐给你们。'),
('CUV', '路加福音', 42, 12, 33, '你们要变卖所有的赒济人，为自己预备永不坏的钱囊，用不尽的财宝在天上，就是贼不能近、虫不能蛀的地方。'),
('CUV', '路加福音', 42, 12, 34, '因为，你们的财宝在那里，你们的心也在那里。'),
('CUV', '路加福音', 42, 12, 35, '你们腰里要束上带，灯也要点著，'),
('CUV', '路加福音', 42, 12, 36, '自己好像仆人等候主人从婚姻的筵席上回来。他来到，叩门，就立刻给他开门。'),
('CUV', '路加福音', 42, 12, 37, '主人来了，看见仆人儆醒，那仆人就有福了。我实在告诉你们，主人必叫他们坐席，自己束上带，进前伺候他们。'),
('CUV', '路加福音', 42, 12, 38, '或是二更天来，或是三更天来，看见仆人这样，那仆人就有福了。'),
('CUV', '路加福音', 42, 12, 39, '家主若知道贼甚么时候来，就必儆醒，不容贼挖透房屋，这是你们所知道的。'),
('CUV', '路加福音', 42, 12, 40, '你们也要预备；因为你们想不到的时候，人子就来了。'),
('CUV', '路加福音', 42, 12, 41, '彼得说：主阿，这比喻是为我们说的呢？还是为众人呢？'),
('CUV', '路加福音', 42, 12, 42, '主说：谁是那忠心有见识的管家，主人派他管理家里的人，按时分粮给他们呢？'),
('CUV', '路加福音', 42, 12, 43, '主人来到，看见仆人这样行，那仆人就有福了。'),
('CUV', '路加福音', 42, 12, 44, '我实在告诉你们，主人要派他管理一切所有的。'),
('CUV', '路加福音', 42, 12, 45, '那仆人若心里说：我的主人必来得迟，就动手打仆人和使女，并且吃喝醉酒；'),
('CUV', '路加福音', 42, 12, 46, '在他想不到的日子，不知道的时辰，那仆人的主人要来，重重的处治他（或作：把他腰轧了），定他和不忠心的人同罪。'),
('CUV', '路加福音', 42, 12, 47, '仆人知道主人的意思，却不预备，又不顺他的意思行，那仆人必多受责打；'),
('CUV', '路加福音', 42, 12, 48, '惟有那不知道的，做了当受责打的事，必少受责打；因为多给谁，就向谁多取；多托谁，就向谁多要。'),
('CUV', '路加福音', 42, 12, 49, '我来要把火丢在地上，倘若已经著起来，不也是我所愿意的么？'),
('CUV', '路加福音', 42, 12, 50, '我有当受的洗还没有成就，我是何等的迫切呢？'),
('CUV', '路加福音', 42, 12, 51, '你们以为我来，是叫地上太平么？我告诉你们，不是，乃是叫人分争。'),
('CUV', '路加福音', 42, 12, 52, '从今以后，一家五个人将要分争：三个人和两个人相争，两个人和三个人相争；'),
('CUV', '路加福音', 42, 12, 53, '父亲和儿子相争，儿子和父亲相争；母亲和女儿相争，女儿和母亲相争；婆婆和媳妇相争，媳妇和婆婆相争。'),
('CUV', '路加福音', 42, 12, 54, '耶稣又对众人说：你们看见西边起了云彩，就说：要下一阵雨；果然就有。'),
('CUV', '路加福音', 42, 12, 55, '起了南风，就说：将要燥热；也就有了。'),
('CUV', '路加福音', 42, 12, 56, '假冒为善的人哪，你们知道分辨天地的气色，怎么不知道分辨这时候呢？'),
('CUV', '路加福音', 42, 12, 57, '你们又为何不自己审量甚么是合理的呢？'),
('CUV', '路加福音', 42, 12, 58, '你同告你的对头去见官，还在路上，务要尽力的和他了结；恐怕他拉你到官面前，官交付差役，差役把你下在监里。'),
('CUV', '路加福音', 42, 12, 59, '我告诉你，若有半文钱没有还清，你断不能从那里出来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 13, 1, '正当那时，有人将彼拉多使加利利人的血搀杂在他们祭物中的事告诉耶稣。'),
('CUV', '路加福音', 42, 13, 2, '耶稣说；你们以为这些加利利人比众加利利人更有罪，所以受这害么？'),
('CUV', '路加福音', 42, 13, 3, '我告诉你们，不是的！你们若不悔改，都要如此灭亡！'),
('CUV', '路加福音', 42, 13, 4, '从前西罗亚楼倒塌了，压死十八个人；你们以为那些人比一切住在耶路撒冷的人更有罪么？'),
('CUV', '路加福音', 42, 13, 5, '我告诉你们，不是的！你们若不悔改，都要如此灭亡！'),
('CUV', '路加福音', 42, 13, 6, '于是用比喻说：一个人有一棵无花果树栽在葡萄园里。他来到树前找果子，却找不著。'),
('CUV', '路加福音', 42, 13, 7, '就对管园的说：看哪，我这三年来到这无花果树前找果子，竟找不著。把他砍了罢，何必白占地土呢！'),
('CUV', '路加福音', 42, 13, 8, '管园的说：主阿，今年且留著，等我周围掘开土，加上粪；'),
('CUV', '路加福音', 42, 13, 9, '以后若结果子便罢，不然再把他砍了。'),
('CUV', '路加福音', 42, 13, 10, '安息日，耶稣在会堂里教训人。'),
('CUV', '路加福音', 42, 13, 11, '有一个女人被鬼附著，病了十八年，腰弯得一点直不起来。'),
('CUV', '路加福音', 42, 13, 12, '耶稣看见，便叫过他来，对他说：女人，你脱离这病了！'),
('CUV', '路加福音', 42, 13, 13, '于是用两只手按著他；他立刻直起腰来，就归荣耀与神。'),
('CUV', '路加福音', 42, 13, 14, '管会堂的因为耶稣在安息日治病，就气忿忿的对众人说：有六日应当做工；那六日之内可以来求医，在安息日却不可。'),
('CUV', '路加福音', 42, 13, 15, '主说：假冒为善的人哪，难道你们各人在安息日不解开槽上的牛、驴，牵去饮么？'),
('CUV', '路加福音', 42, 13, 16, '况且这女人本是亚伯拉罕的后裔，被撒但捆绑了这十八年，不当在安息日解开他的绑么？'),
('CUV', '路加福音', 42, 13, 17, '耶稣说这话，他的敌人都惭愧了；众人因他所行一切荣耀的事，就都欢喜了。'),
('CUV', '路加福音', 42, 13, 18, '耶稣说：神的国好像甚么？我拿甚么来比较呢？'),
('CUV', '路加福音', 42, 13, 19, '好像一粒芥菜种，有人拿去种在园子里，长大成树，天上的飞鸟宿在他的枝上。'),
('CUV', '路加福音', 42, 13, 20, '又说：我拿甚么来比神的国呢？'),
('CUV', '路加福音', 42, 13, 21, '好比面酵，有妇人拿来藏在三斗面里，直等全团都发起来。'),
('CUV', '路加福音', 42, 13, 22, '耶稣往耶路撒冷去，在所经过的各城各乡教训人。'),
('CUV', '路加福音', 42, 13, 23, '有一个人问他说：主阿，得救的人少么？'),
('CUV', '路加福音', 42, 13, 24, '耶稣对众人说：你们要努力进窄门。我告诉你们，将来有许多人想要进去，却是不能。'),
('CUV', '路加福音', 42, 13, 25, '及至家主起来关了门，你们站在外面叩门，说：主阿，给我们开门！他就回答说：我不认识你们，不晓得你们是那里来的！'),
('CUV', '路加福音', 42, 13, 26, '那时，你们要说：我们在你面前吃过喝过，你也在我们的街上教训过人。'),
('CUV', '路加福音', 42, 13, 27, '他要说：我告诉你们，我不晓得你们是那里来的。你们这一切作恶的人，离开我去罢！'),
('CUV', '路加福音', 42, 13, 28, '你们要看见亚伯拉罕、以撒、雅各，和众先知都在神的国里，你们却被赶到外面，在那里必要哀哭切齿了。'),
('CUV', '路加福音', 42, 13, 29, '从东、从西、从南、从北将有人来，在神的国里坐席。'),
('CUV', '路加福音', 42, 13, 30, '只是有在后的，将要在前；有在前的，将要在后。'),
('CUV', '路加福音', 42, 13, 31, '正当那时，有几个法利赛人来对耶稣说：离开这里去罢，因为希律想要杀你。'),
('CUV', '路加福音', 42, 13, 32, '耶稣说：你们去告诉那个狐狸说：今天、明天我赶鬼治病，第三天我的事就成全了。'),
('CUV', '路加福音', 42, 13, 33, '虽然这样，今天、明天、后天，我必须前行，因为先知在耶路撒冷之外丧命是不能的。'),
('CUV', '路加福音', 42, 13, 34, '耶路撒冷阿！耶路撒冷阿！你常杀害先知，又用石头打死那奉差遣到你这里来的人。我多次愿意聚集你的儿女，好像母鸡把小鸡聚集在翅膀底下，只是你们不愿意。'),
('CUV', '路加福音', 42, 13, 35, '看哪，你们的家成为荒场留给你们。我告诉你们，从今以后你们不得再见我，直等到你们说：奉主名来的是应当称颂的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 14, 1, '安息日，耶稣到一个法利赛人的首领家里去吃饭，他们就窥探他。'),
('CUV', '路加福音', 42, 14, 2, '在他面前有一个患水臌的人。'),
('CUV', '路加福音', 42, 14, 3, '耶稣对律法师和法利赛人说：安息日治病，可以不可以？'),
('CUV', '路加福音', 42, 14, 4, '他们却不言语。耶稣就治好那人，叫他走了；'),
('CUV', '路加福音', 42, 14, 5, '便对他们说：你们中间谁有驴或有牛，在安息日掉在井里，不立时拉他上来呢？'),
('CUV', '路加福音', 42, 14, 6, '他们不能对答这话。'),
('CUV', '路加福音', 42, 14, 7, '耶稣见所请的客拣择首位，就用比喻对他们说：'),
('CUV', '路加福音', 42, 14, 8, '你被人请去赴婚姻的筵席，不要坐在首位上，恐怕有比你尊贵的客被他请来；'),
('CUV', '路加福音', 42, 14, 9, '那请你们的人前来对你说：让座给这一位罢！你就羞羞惭惭的退到末位上去了。'),
('CUV', '路加福音', 42, 14, 10, '你被请的时候，就去坐在末位上，好叫那请你的人来对你说：朋友，请上坐。那时，你在同席的人面前就有光彩了。'),
('CUV', '路加福音', 42, 14, 11, '因为，凡自高的，必降为卑，自卑的，必升为高。'),
('CUV', '路加福音', 42, 14, 12, '耶稣又对请他的人说：你摆设午饭或晚饭，不要请你的朋友、弟兄、亲属，和富足的邻舍，恐怕他们也请你，你就得了报答。'),
('CUV', '路加福音', 42, 14, 13, '你摆设筵席，倒要请那贫穷的、残废的、瘸腿的、瞎眼的，你就有福了！'),
('CUV', '路加福音', 42, 14, 14, '因为他们没有甚么可报答你。到义人复活的时候，你要得著报答。'),
('CUV', '路加福音', 42, 14, 15, '同席的有一人听见这话，就对耶稣说：在神国里吃饭的有福了！'),
('CUV', '路加福音', 42, 14, 16, '耶稣对他说：有一人摆设大筵席，请了许多客。'),
('CUV', '路加福音', 42, 14, 17, '到了坐席的时候，打发仆人去对所请的人说：请来罢！样样都齐备了。'),
('CUV', '路加福音', 42, 14, 18, '众人一口同音的推辞。头一个说：我买了一块地，必须去看看。请你准我辞了。'),
('CUV', '路加福音', 42, 14, 19, '又有一个说：我买了五对牛，要去试一试。请你准我辞了。'),
('CUV', '路加福音', 42, 14, 20, '又有一个说：我才娶了妻，所以不能去。'),
('CUV', '路加福音', 42, 14, 21, '那仆人回来，把这事都告诉了主人。家主就动怒，对仆人说：快出去，到城里大街小巷，领那贫穷的、残废的、瞎眼的、瘸腿的来。'),
('CUV', '路加福音', 42, 14, 22, '仆人说：主阿，你所吩咐的已经办了，还有空座。'),
('CUV', '路加福音', 42, 14, 23, '主人对仆人说，你出去到路上和篱笆那里，勉强人进来，坐满我的屋子。'),
('CUV', '路加福音', 42, 14, 24, '我告诉你们，先前所请的人，没有一个得尝我的筵席。'),
('CUV', '路加福音', 42, 14, 25, '有极多的人和耶稣同行。他转过来对他们说：'),
('CUV', '路加福音', 42, 14, 26, '人到我这里来，若不爱我胜过爱（爱我胜过爱：原文是恨）自己的父母、妻子、儿女、弟兄、姐妹，和自己的性命，就不能作我的门徒。'),
('CUV', '路加福音', 42, 14, 27, '凡不背著自己十字架跟从我的，也不能作我的门徒。'),
('CUV', '路加福音', 42, 14, 28, '你们那一个要盖一座楼，不先坐下算计花费，能盖成不能呢？'),
('CUV', '路加福音', 42, 14, 29, '恐怕安了地基，不能成功，看见的人都笑话他，说：'),
('CUV', '路加福音', 42, 14, 30, '这个人开了工，却不能完工。'),
('CUV', '路加福音', 42, 14, 31, '或是一个王出去和别的王打仗，岂不先坐下酌量，能用一万兵去敌那领二万兵来攻打他的么？'),
('CUV', '路加福音', 42, 14, 32, '若是不能，就趁敌人还远的时候，派使者去求和息的条款。'),
('CUV', '路加福音', 42, 14, 33, '这样，你们无论甚么人，若不撇下一切所有的，就不能作我的门徒。'),
('CUV', '路加福音', 42, 14, 34, '盐本是好的；盐若失了味，可用甚么叫他再咸呢？'),
('CUV', '路加福音', 42, 14, 35, '或用在田里，或堆在粪里，都不合式，只好丢在外面。有耳可听的，就应当听！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 15, 1, '众税吏和罪人都挨近耶稣，要听他讲道。'),
('CUV', '路加福音', 42, 15, 2, '法利赛人和文士私下议论说：这个人接待罪人，又同他们吃饭。'),
('CUV', '路加福音', 42, 15, 3, '耶稣就用比喻说：'),
('CUV', '路加福音', 42, 15, 4, '你们中间谁有一百只羊失去一只，不把这九十九只撇在旷野、去找那失去的羊，直到找著呢？'),
('CUV', '路加福音', 42, 15, 5, '找著了，就欢欢喜喜的扛在肩上，回到家里，'),
('CUV', '路加福音', 42, 15, 6, '就请朋友邻舍来，对他们说：我失去的羊已经找著了，你们和我一同欢喜罢！'),
('CUV', '路加福音', 42, 15, 7, '我告诉你们，一个罪人悔改，在天上也要这样为他欢喜，较比为九十九个不用悔改的义人欢喜更大。'),
('CUV', '路加福音', 42, 15, 8, '或是一个妇人有十块钱，若失落一块，岂不点上灯，打扫屋子，细细的找，直到找著么？'),
('CUV', '路加福音', 42, 15, 9, '找著了，就请朋友邻舍来，对他们说：我失落的那块钱已经找著了，你们和我一同欢喜罢！'),
('CUV', '路加福音', 42, 15, 10, '我告诉你们，一个罪人悔改，在神的使者面前也是这样为他欢喜。」'),
('CUV', '路加福音', 42, 15, 11, '耶稣又说：一个人有两个儿子。'),
('CUV', '路加福音', 42, 15, 12, '小儿子对父亲说：父亲，请你把我应得的家业分给我。他父亲就把产业分给他们。'),
('CUV', '路加福音', 42, 15, 13, '过了不多几日，小儿子就把他一切所有的都收拾起来，往远方去了。在那里任意放荡，浪费赀财。'),
('CUV', '路加福音', 42, 15, 14, '既耗尽了一切所有的，又遇著那地方大遭饥荒，就穷苦起来。'),
('CUV', '路加福音', 42, 15, 15, '于是去投靠那地方的一个人；那人打发他到田里去放猪。'),
('CUV', '路加福音', 42, 15, 16, '他恨不得拿猪所吃的豆荚充饥，也没有人给他。'),
('CUV', '路加福音', 42, 15, 17, '他醒悟过来，就说：我父亲有多少的雇工，口粮有余，我倒在这里饿死么？'),
('CUV', '路加福音', 42, 15, 18, '我要起来，到我父亲那里去，向他说：父亲！我得罪了天，又得罪了你；'),
('CUV', '路加福音', 42, 15, 19, '从今以后，我不配称为你的儿子，把我当作一个雇工罢！'),
('CUV', '路加福音', 42, 15, 20, '于是起来，往他父亲那里去。相离还远，他父亲看见，就动了慈心，跑去抱著他的颈项，连连与他亲嘴。'),
('CUV', '路加福音', 42, 15, 21, '儿子说：父亲！我得罪了天，又得罪了你；从今以后，我不配称为你的儿子。'),
('CUV', '路加福音', 42, 15, 22, '父亲却吩咐仆人说：把那上好的袍子快拿出来给他穿；把戒指戴在他指头上；把鞋穿在他脚上；'),
('CUV', '路加福音', 42, 15, 23, '把那肥牛犊牵来宰了，我们可以吃喝快乐；'),
('CUV', '路加福音', 42, 15, 24, '因为我这个儿子是死而复活，失而又得的。他们就快乐起来。'),
('CUV', '路加福音', 42, 15, 25, '那时，大儿子正在田里。他回来，离家不远，听见作乐跳舞的声音，'),
('CUV', '路加福音', 42, 15, 26, '便叫过一个仆人来，问是甚么事。'),
('CUV', '路加福音', 42, 15, 27, '仆人说：你兄弟来了；你父亲因为得他无灾无病的回来，把肥牛犊宰了。'),
('CUV', '路加福音', 42, 15, 28, '大儿子却生气，不肯进去；他父亲就出来劝他。'),
('CUV', '路加福音', 42, 15, 29, '他对父亲说：我服事你这多年，从来没有违背过你的命，你并没有给我一只山羊羔，叫我和朋友一同快乐。'),
('CUV', '路加福音', 42, 15, 30, '但你这个儿子和娼妓吞尽了你的产业，他一来了，你倒为他宰了肥牛犊。'),
('CUV', '路加福音', 42, 15, 31, '父亲对他说：儿阿！你常和我同在，我一切所有的都是你的；'),
('CUV', '路加福音', 42, 15, 32, '只是你这个兄弟是死而复活、失而又得的，所以我们理当欢喜快乐。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 16, 1, '耶稣又对门徒说：有一个财主的管家，别人向他主人告他浪费主人的财物。'),
('CUV', '路加福音', 42, 16, 2, '主人叫他来，对他说：我听见你这事怎么样呢？把你所经管的交代明白，因你不能再作我的管家。'),
('CUV', '路加福音', 42, 16, 3, '那管家心里说：主人辞我，不用我再作管家，我将来作甚么？锄地呢？无力；讨饭呢？怕羞。'),
('CUV', '路加福音', 42, 16, 4, '我知道怎么行，好叫人在我不作管家之后，接我到他们家里去。'),
('CUV', '路加福音', 42, 16, 5, '于是把欠他主人债的，一个一个的叫了来，问头一个说：你欠我主人多少？'),
('CUV', '路加福音', 42, 16, 6, '他说：一百篓（每篓约五十斤）油。管家说：拿你的账，快坐下，写五十。'),
('CUV', '路加福音', 42, 16, 7, '又问一个说：你欠多少？他说：一百石麦子。管家说：拿你的账，写八十。'),
('CUV', '路加福音', 42, 16, 8, '主人就夸奖这不义的管家做事聪明。因为今世之子，在世事之上，较比光明之子更加聪明。'),
('CUV', '路加福音', 42, 16, 9, '我又告诉你们，要藉著那不义的钱财结交朋友，到了钱财无用的时候，他们可以接你们到永存的帐幕里去。'),
('CUV', '路加福音', 42, 16, 10, '人在最小的事上忠心，在大事上也忠心；在最小的事上不义，在大事上也不义。'),
('CUV', '路加福音', 42, 16, 11, '倘若你们在不义的钱财上不忠心，谁还把那真实的钱财托付你们呢？'),
('CUV', '路加福音', 42, 16, 12, '倘若你们在别人的东西上不忠心，谁还把你们自己的东西给你们呢？'),
('CUV', '路加福音', 42, 16, 13, '一个仆人不能事奉两个主；不是恶这个爱那个，就是重这个轻那个。你们不能又事奉神，又事奉玛门。'),
('CUV', '路加福音', 42, 16, 14, '法利赛人是贪爱钱财的，他们听见这一切话，就嗤笑耶稣。'),
('CUV', '路加福音', 42, 16, 15, '耶稣对他们说：你们是在人面前自称为义的，你们的心，神却知道；因为人所尊贵的，是神看为可憎恶的。'),
('CUV', '路加福音', 42, 16, 16, '律法和先知到约翰为止，从此神国的福音传开了，人人努力要进去。'),
('CUV', '路加福音', 42, 16, 17, '天地废去较比律法的一点一画落空还容易。'),
('CUV', '路加福音', 42, 16, 18, '凡休妻另娶的就是犯奸淫；娶被休之妻的也是犯奸淫。'),
('CUV', '路加福音', 42, 16, 19, '有一个财主穿著紫色袍和细麻布衣服，天天奢华宴乐。'),
('CUV', '路加福音', 42, 16, 20, '又有一个讨饭的，名叫拉撒路，浑身生疮，被人放在财主门口，'),
('CUV', '路加福音', 42, 16, 21, '要得财主桌子上掉下来的零碎充饥；并且狗来餂他的疮。'),
('CUV', '路加福音', 42, 16, 22, '后来那讨饭的死了，被天使带去放在亚伯拉罕的怀里。财主也死了，并且埋葬了。'),
('CUV', '路加福音', 42, 16, 23, '他在阴间受痛苦，举目远远的望见亚伯拉罕，又望见拉撒路在他怀里，'),
('CUV', '路加福音', 42, 16, 24, '就喊著说：我祖亚伯拉罕哪，可怜我罢！打发拉撒路来，用指头尖蘸点水，凉凉我的舌头；因为我在这火燄里，极其痛苦。'),
('CUV', '路加福音', 42, 16, 25, '亚伯拉罕说：儿阿，你该回想你生前享过福，拉撒路也受过苦；如今他在这里得安慰，你倒受痛苦。'),
('CUV', '路加福音', 42, 16, 26, '不但这样，并且在你我之间，有深渊限定，以致人要从这边过到你们那边是不能的；要从那边过到我们这边也是不能的。'),
('CUV', '路加福音', 42, 16, 27, '财主说：我祖阿！既是这样，求你打发拉撒路到我父家去；'),
('CUV', '路加福音', 42, 16, 28, '因为我还有五个弟兄，他可以对他们作见证，免得他们也来到这痛苦的地方。'),
('CUV', '路加福音', 42, 16, 29, '亚伯拉罕说：他们有摩西和先知的话可以听从。'),
('CUV', '路加福音', 42, 16, 30, '他说：我祖亚伯拉罕哪，不是的，若有一个从死里复活的，到他们那里去的，他们必要悔改。'),
('CUV', '路加福音', 42, 16, 31, '亚伯拉罕说：若不听从摩西和先知的话，就是有一个从死里复活的，他们也是不听劝。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 17, 1, '耶稣又对门徒说：绊倒人的事是免不了的；但那绊倒人的有祸了。'),
('CUV', '路加福音', 42, 17, 2, '就是把磨石拴在这人的颈项上，丢在海里，还强如他把这小子里的一个绊倒了。'),
('CUV', '路加福音', 42, 17, 3, '你们要谨慎！若是你的弟兄得罪你，就劝戒他；他若懊悔，就饶恕他。'),
('CUV', '路加福音', 42, 17, 4, '倘若他一天七次得罪你，又七次回转，说：我懊悔了，你总要饶恕他。'),
('CUV', '路加福音', 42, 17, 5, '使徒对主说：求主加增我们的信心。'),
('CUV', '路加福音', 42, 17, 6, '主说：你们若有信心像一粒芥菜种，就是对这棵桑树说：你要拔起根来，栽在海里，他也必听从你们。'),
('CUV', '路加福音', 42, 17, 7, '你们谁有仆人耕地或是放羊，从田里回来，就对他说：你快来坐下吃饭呢？'),
('CUV', '路加福音', 42, 17, 8, '岂不对他说：你给我预备晚饭，束上带子伺候我，等我吃喝完了，你才可以吃喝么？'),
('CUV', '路加福音', 42, 17, 9, '仆人照所吩咐的去做，主人还谢谢他么？'),
('CUV', '路加福音', 42, 17, 10, '这样，你们做完了一切所吩咐的，只当说：我们是无用的仆人，所做的本是我们应分做的。'),
('CUV', '路加福音', 42, 17, 11, '耶稣往耶路撒冷去，经过撒玛利亚和加利利。'),
('CUV', '路加福音', 42, 17, 12, '进入一个村子，有十个长大痲疯的，迎面而来，远远的站著，'),
('CUV', '路加福音', 42, 17, 13, '高声说：耶稣，夫子，可怜我们罢！'),
('CUV', '路加福音', 42, 17, 14, '耶稣看见，就对他们说：你们去把身体给祭司察看。他们去的时候就洁净了。'),
('CUV', '路加福音', 42, 17, 15, '内中有一个见自己已经好了，就回来大声归荣耀与神，'),
('CUV', '路加福音', 42, 17, 16, '又俯伏在耶稣脚前感谢他；这人是撒玛利亚人。'),
('CUV', '路加福音', 42, 17, 17, '耶稣说：洁净了的不是十个人么？那九个在那里呢？'),
('CUV', '路加福音', 42, 17, 18, '除了这外族人，再没有别人回来归荣耀与神么？'),
('CUV', '路加福音', 42, 17, 19, '就对那人说：起来，走罢！你的信救了你了。'),
('CUV', '路加福音', 42, 17, 20, '法利赛人问：神的国几时来到？耶稣回答说：神的国来到不是眼所能见的。'),
('CUV', '路加福音', 42, 17, 21, '人也不得说：看哪，在这里！看哪，在那里！因为神的国就在你们心里（心里：或作中间）。'),
('CUV', '路加福音', 42, 17, 22, '他又对门徒说：日子将到，你们巴不得看见人子的一个日子，却不得看见。'),
('CUV', '路加福音', 42, 17, 23, '人将要对你们说：看哪，在那里！看哪，在这里！你们不要出去，也不要跟随他们！'),
('CUV', '路加福音', 42, 17, 24, '因为人子在他降临的日子，好像闪电从天这边一闪直照到天那边。'),
('CUV', '路加福音', 42, 17, 25, '只是他必须先受许多苦，又被这世代弃绝。'),
('CUV', '路加福音', 42, 17, 26, '挪亚的日子怎样，人子的日子也要怎样。'),
('CUV', '路加福音', 42, 17, 27, '那时候的人又吃又喝，又娶又嫁，到挪亚进方舟的那日，洪水就来，把他们全都灭了。'),
('CUV', '路加福音', 42, 17, 28, '又好像罗得的日子；人又吃又喝，又买又卖，又耕种又盖造。'),
('CUV', '路加福音', 42, 17, 29, '到罗得出所多玛的那日，就有火与硫磺从天上降下来，把他们全都灭了。'),
('CUV', '路加福音', 42, 17, 30, '人子显现的日子也要这样。'),
('CUV', '路加福音', 42, 17, 31, '当那日，人在房上，器具在屋里，不要下来拿；人在田里，也不要回家。'),
('CUV', '路加福音', 42, 17, 32, '你们要回想罗得的妻子。'),
('CUV', '路加福音', 42, 17, 33, '凡想要保全生命的，必丧掉生命；凡丧掉生命的，必救活生命。'),
('CUV', '路加福音', 42, 17, 34, '我对你们说，当那一夜，两个人在一个床上，要取去一个，撇下一个。'),
('CUV', '路加福音', 42, 17, 35, '两个女人一同推磨；要取去一个，撇下一个。（有古卷在此有：'),
('CUV', '路加福音', 42, 17, 36, '两个人在田里，要取去一个，撇下一个。）'),
('CUV', '路加福音', 42, 17, 37, '门徒说：主阿，在那里有这事呢？耶稣说：尸首在那里，鹰也必聚在那里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 18, 1, '耶稣设一个比喻，是要人常常祷告，不可灰心。'),
('CUV', '路加福音', 42, 18, 2, '说：某城里有一个官，不惧怕神，也不尊重世人。'),
('CUV', '路加福音', 42, 18, 3, '那城里有个寡妇，常到他那里，说：我有一个对头，求你给我伸冤。'),
('CUV', '路加福音', 42, 18, 4, '他多日不准。后来心里说：我虽不惧怕神，也不尊重世人，'),
('CUV', '路加福音', 42, 18, 5, '只因这寡妇烦扰我，我就给他伸冤罢，免得他常来缠磨我！'),
('CUV', '路加福音', 42, 18, 6, '主说：你们听这不义之官所说的话。'),
('CUV', '路加福音', 42, 18, 7, '神的选民昼夜呼吁他，他纵然为他们忍了多时，岂不终久给他们伸冤么？'),
('CUV', '路加福音', 42, 18, 8, '我告诉你们，要快快的给他们伸冤了。然而，人子来的时候，遇得见世上有信德么？'),
('CUV', '路加福音', 42, 18, 9, '耶稣向那些仗著自己是义人，藐视别人的，设一个比喻，'),
('CUV', '路加福音', 42, 18, 10, '说：有两个人上殿里去祷告：一个是法利赛人，一个是税吏。'),
('CUV', '路加福音', 42, 18, 11, '法利赛人站著，自言自语的祷告说：神阿，我感谢你，我不像别人勒索、不义、奸淫，也不像这个税吏。'),
('CUV', '路加福音', 42, 18, 12, '我一个礼拜禁食两次，凡我所得的都捐上十分之一。'),
('CUV', '路加福音', 42, 18, 13, '那税吏远远的站著，连举目望天也不敢，只捶著胸说：神阿，开恩可怜我这个罪人！'),
('CUV', '路加福音', 42, 18, 14, '我告诉你们，这人回家去比那人倒算为义了；因为，凡自高的，必降为卑；自卑的，必升为高。'),
('CUV', '路加福音', 42, 18, 15, '有人抱著自己的婴孩来见耶稣，要他摸他们；门徒看见就责备那些人。'),
('CUV', '路加福音', 42, 18, 16, '耶稣却叫他们来，说：让小孩子到我这里来，不要禁止他们；因为在神国的正是这样的人。'),
('CUV', '路加福音', 42, 18, 17, '我实在告诉你们，凡要承受神国的，若不像小孩子，断不能进去。'),
('CUV', '路加福音', 42, 18, 18, '有一个官问耶稣说：良善的夫子，我该做甚么事才可以承受永生？'),
('CUV', '路加福音', 42, 18, 19, '耶稣对他说：你为甚么称我是良善的？除了神一位之外，再没有良善的。'),
('CUV', '路加福音', 42, 18, 20, '诫命你是晓得的：不可奸淫；不可杀人；不可偷盗；不可作假见证；当孝敬父母。'),
('CUV', '路加福音', 42, 18, 21, '那人说：这一切我从小都遵守了。'),
('CUV', '路加福音', 42, 18, 22, '耶稣听见了，就说：你还缺少一件：要变卖你一切所有的，分给穷人，就必有财宝在天上；你还要来跟从我。'),
('CUV', '路加福音', 42, 18, 23, '他听见这话，就甚忧愁，因为他很富足。'),
('CUV', '路加福音', 42, 18, 24, '耶稣看见他，就说：有钱财的人进神的国是何等的难哪！'),
('CUV', '路加福音', 42, 18, 25, '骆驼穿过针的眼比财主进神的国还容易呢！'),
('CUV', '路加福音', 42, 18, 26, '听见的人说：这样，谁能得救呢？'),
('CUV', '路加福音', 42, 18, 27, '耶稣说：在人所不能的事，在神却能。'),
('CUV', '路加福音', 42, 18, 28, '彼得说：看哪，我们已经撇下自己所有的跟从你了。'),
('CUV', '路加福音', 42, 18, 29, '耶稣说：我实在告诉你们，人为神的国撇下房屋，或是妻子、弟兄、父母、儿女，'),
('CUV', '路加福音', 42, 18, 30, '没有在今世不得百倍，在来世不得永生的。'),
('CUV', '路加福音', 42, 18, 31, '耶稣带著十二个门徒，对他们说：看哪，我们上耶路撒冷去，先知所写的一切事都要成就在人子身上。'),
('CUV', '路加福音', 42, 18, 32, '他将要被交给外邦人，他们要戏弄他，凌辱他，吐唾沫在他脸上，'),
('CUV', '路加福音', 42, 18, 33, '并要鞭打他，杀害他；第三日他要复活。'),
('CUV', '路加福音', 42, 18, 34, '这些事门徒一样也不懂得，意思乃是隐藏的；他们不晓得所说的是甚么。'),
('CUV', '路加福音', 42, 18, 35, '耶稣将近耶利哥的时候，有一个瞎子坐在路旁讨饭。'),
('CUV', '路加福音', 42, 18, 36, '听见许多人经过，就问是甚么事。'),
('CUV', '路加福音', 42, 18, 37, '他们告诉他，是拿撒勒人耶稣经过。'),
('CUV', '路加福音', 42, 18, 38, '他就呼叫说：大卫的子孙耶稣阿，可怜我罢！'),
('CUV', '路加福音', 42, 18, 39, '在前头走的人就责备他，不许他作声；他却越发喊叫说：大卫的子孙，可怜我罢！'),
('CUV', '路加福音', 42, 18, 40, '耶稣站住，吩咐把他领过来，到了跟前，就问他说：'),
('CUV', '路加福音', 42, 18, 41, '你要我为你做甚么？他说：主阿，我要能看见。'),
('CUV', '路加福音', 42, 18, 42, '耶稣说：你可以看见！你的信救了你了。'),
('CUV', '路加福音', 42, 18, 43, '瞎子立刻看见了，就跟随耶稣，一路归荣耀与神。众人看见这事，也赞美神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 19, 1, '耶稣进了耶利哥，正经过的时候，'),
('CUV', '路加福音', 42, 19, 2, '有一个人名叫撒该，作税吏长，是个财主。'),
('CUV', '路加福音', 42, 19, 3, '他要看看耶稣是怎样的人；只因人多，他的身量又矮，所以不得看见，'),
('CUV', '路加福音', 42, 19, 4, '就跑到前头，爬上桑树，要看耶稣，因为耶稣必从那里经过。'),
('CUV', '路加福音', 42, 19, 5, '耶稣到了那里，抬头一看，对他说：撒该，快下来！今天我必住在你家里。'),
('CUV', '路加福音', 42, 19, 6, '他就急忙下来，欢欢喜喜的接待耶稣。'),
('CUV', '路加福音', 42, 19, 7, '众人看见，都私下议论说：他竟到罪人家里去住宿。'),
('CUV', '路加福音', 42, 19, 8, '撒该站著对主说：主阿，我把所有的一半给穷人；我若讹诈了谁，就还他四倍。'),
('CUV', '路加福音', 42, 19, 9, '耶稣说：今天救恩到了这家，因为他也是亚伯拉罕的子孙。'),
('CUV', '路加福音', 42, 19, 10, '人子来，为要寻找，拯救失丧的人。'),
('CUV', '路加福音', 42, 19, 11, '众人正在听见这些话的时候，耶稣因为将近耶路撒冷，又因他们以为神的国快要显出来，就另设一个比喻，说：'),
('CUV', '路加福音', 42, 19, 12, '有一个贵胄往远方去，要得国回来，'),
('CUV', '路加福音', 42, 19, 13, '便叫了他的十个仆人来，交给他们十锭（锭：原文作弥拿约银十两）银子，说：你们去作生意，直等我回来。'),
('CUV', '路加福音', 42, 19, 14, '他本国的人却恨他，打发使者随后去，说：我们不愿意这个人作我们的王。'),
('CUV', '路加福音', 42, 19, 15, '他既得国回来，就吩咐叫那领银子的仆人来，要知道他们做生意赚了多少。'),
('CUV', '路加福音', 42, 19, 16, '头一个上来，说：主阿，你的一锭银子已经赚了十锭。'),
('CUV', '路加福音', 42, 19, 17, '主人说：好！良善的仆人，你既在最小的事上有忠心，可以有权柄管十座城。'),
('CUV', '路加福音', 42, 19, 18, '第二个来，说：主阿！你的一锭银子，已经赚了五锭。'),
('CUV', '路加福音', 42, 19, 19, '主人说：你也可以管五座城。'),
('CUV', '路加福音', 42, 19, 20, '又有一个来说：主阿，看哪，你的一锭银子在这里，我把他包在手巾里存著。'),
('CUV', '路加福音', 42, 19, 21, '我原是怕你，因为你是严厉的人；没有放下的，还要去拿；没有种下的，还要去收。'),
('CUV', '路加福音', 42, 19, 22, '主人对他说：你这恶仆，我要凭你的口定你的罪。你既知道我是严厉的人，没有放下的，还要去拿，没有种下的，还要去收，'),
('CUV', '路加福音', 42, 19, 23, '为甚么不把我的银子交给银行，等我来的时候，连本带利都可以要回来呢？'),
('CUV', '路加福音', 42, 19, 24, '就对旁边站著的人说：夺过他这一锭来，给那有十锭的。'),
('CUV', '路加福音', 42, 19, 25, '他们说：主阿，他已经有十锭了。'),
('CUV', '路加福音', 42, 19, 26, '主人说：我告诉你们，凡有的，还要加给他；没有的，连他所有的也要夺过来。'),
('CUV', '路加福音', 42, 19, 27, '至于我那些仇敌，不要我作他们王的，把他们拉来，在我面前杀了罢！'),
('CUV', '路加福音', 42, 19, 28, '耶稣说完了这话，就在前面走，上耶路撒冷去。'),
('CUV', '路加福音', 42, 19, 29, '将近伯法其和伯大尼，在一座山名叫橄榄山那里，就打发两个门徒，说：'),
('CUV', '路加福音', 42, 19, 30, '你们往对面村子里去，进去的时候，必看见一匹驴驹拴在那里，是从来没有人骑过的，可以解开牵来。'),
('CUV', '路加福音', 42, 19, 31, '若有人问为甚么解他，你们就说：主要用他。'),
('CUV', '路加福音', 42, 19, 32, '打发的人去了，所遇见的正如耶稣所说的。'),
('CUV', '路加福音', 42, 19, 33, '他们解驴驹的时候，主人问他们说：解驴驹做甚么？'),
('CUV', '路加福音', 42, 19, 34, '他们说：主要用他。'),
('CUV', '路加福音', 42, 19, 35, '他们牵到耶稣那里，把自己的衣服搭在上面，扶著耶稣骑上。'),
('CUV', '路加福音', 42, 19, 36, '走的时候，众人把衣服铺在路上。'),
('CUV', '路加福音', 42, 19, 37, '将近耶路撒冷，正下橄榄山的时候，众门徒因所见过的一切异能，都欢乐起来，大声赞美神，'),
('CUV', '路加福音', 42, 19, 38, '说：奉主名来的王是应当称颂的！在天上有和平；在至高之处有荣光。'),
('CUV', '路加福音', 42, 19, 39, '众人中有几个法利赛人对耶稣说：夫子，责备你的门徒罢！'),
('CUV', '路加福音', 42, 19, 40, '耶稣说：我告诉你们，若是他们闭口不说，这些石头必要呼叫起来。'),
('CUV', '路加福音', 42, 19, 41, '耶稣快到耶路撒冷，看见城，就为他哀哭，'),
('CUV', '路加福音', 42, 19, 42, '说：巴不得你在这日子知道关系你平安的事；无奈这事现在是隐藏的，叫你的眼看不出来。'),
('CUV', '路加福音', 42, 19, 43, '因为日子将到，你的仇敌必筑起土垒，周围环绕你，四面困住你，'),
('CUV', '路加福音', 42, 19, 44, '并要扫灭你和你里头的儿女，连一块石头也不留在石头上，因你不知道眷顾你的时候。'),
('CUV', '路加福音', 42, 19, 45, '耶稣进了殿，赶出里头做买卖的人，'),
('CUV', '路加福音', 42, 19, 46, '对他们说：经上说：我的殿必作祷告的殿，你们倒使他成为贼窝了。'),
('CUV', '路加福音', 42, 19, 47, '耶稣天天在殿里教训人。祭司长和文士与百姓的尊长都想要杀他，'),
('CUV', '路加福音', 42, 19, 48, '但寻不出法子来，因为百姓都侧耳听他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 20, 1, '有一天，耶稣在殿里教训百姓，讲福音的时候，祭司长和文士并长老上前来，'),
('CUV', '路加福音', 42, 20, 2, '问他说：你告诉我们，你仗著甚么权柄做这些事？给你这权柄的是谁呢？'),
('CUV', '路加福音', 42, 20, 3, '耶稣回答说：我也要问你们一句话，你们且告诉我。'),
('CUV', '路加福音', 42, 20, 4, '约翰的洗礼是从天上来的？是从人间来的呢？'),
('CUV', '路加福音', 42, 20, 5, '他们彼此商议说：我们若说从天上来，他必说：你们为甚么不信他呢？'),
('CUV', '路加福音', 42, 20, 6, '若说从人间来，百姓都要用石头打死我们，因为他们信约翰是先知。'),
('CUV', '路加福音', 42, 20, 7, '于是回答说：不知道是从那里来的。'),
('CUV', '路加福音', 42, 20, 8, '耶稣说：我也不告诉你们，我仗著甚么权柄做这些事。'),
('CUV', '路加福音', 42, 20, 9, '耶稣就设比喻对百姓说：有人栽了一个葡萄园，租给园户，就往外国去住了许久。'),
('CUV', '路加福音', 42, 20, 10, '到了时候，打发一个仆人到园户那里去，叫他们把园中当纳的果子交给他；园户竟打了他，叫他空手回去。'),
('CUV', '路加福音', 42, 20, 11, '又打发一个仆人去，他们也打了他，并且凌辱他，叫他空手回去。'),
('CUV', '路加福音', 42, 20, 12, '又打发第三个仆人去，他们也打伤了他，把他推出去了。'),
('CUV', '路加福音', 42, 20, 13, '园主说：我怎么办呢？我要打发我的爱子去，或者他们尊敬他。'),
('CUV', '路加福音', 42, 20, 14, '不料，园户看见他，就彼此商量说：这是承受产业的，我们杀他罢，使产业归于我们！'),
('CUV', '路加福音', 42, 20, 15, '于是把他推出葡萄园外，杀了。这样，葡萄园的主人要怎样处治他们呢？'),
('CUV', '路加福音', 42, 20, 16, '他要来除灭这些园户，将葡萄园转给别人。听见的人说：这是万不可的！'),
('CUV', '路加福音', 42, 20, 17, '耶稣看著他们说：经上记著：匠人所弃的石头已作了房角的头块石头。这是甚么意思呢？'),
('CUV', '路加福音', 42, 20, 18, '凡掉在那石头上的，必要跌碎；那石头掉在谁的身上，就要把谁砸得稀烂。'),
('CUV', '路加福音', 42, 20, 19, '文士和祭司长看出这比喻是指著他们说的，当时就想要下手拿他，只是惧怕百姓。'),
('CUV', '路加福音', 42, 20, 20, '于是窥探耶稣，打发奸细装作好人，要在他的话上得把柄，好将他交在巡抚的政权之下。'),
('CUV', '路加福音', 42, 20, 21, '奸细就问耶稣说：夫子，我们晓得你所讲所传都是正道，也不取人的外貌，乃是诚诚实实传神的道。'),
('CUV', '路加福音', 42, 20, 22, '我们纳税给该撒，可以不可以？'),
('CUV', '路加福音', 42, 20, 23, '耶稣看出他们的诡诈，就对他们说：'),
('CUV', '路加福音', 42, 20, 24, '拿一个银钱来给我看。这像和这号是谁的？他们说：是该撒的。'),
('CUV', '路加福音', 42, 20, 25, '耶稣说：这样，该撒的物当归给该撒，神的物当归给神。'),
('CUV', '路加福音', 42, 20, 26, '他们当著百姓，在这话上得不著把柄，又希奇他的应对，就闭口无言了。'),
('CUV', '路加福音', 42, 20, 27, '撒都该人常说没有复活的事。有几个来问耶稣说：'),
('CUV', '路加福音', 42, 20, 28, '夫子！摩西为我们写著说：人若有妻无子就死了，他兄弟当娶他的妻，为哥哥生子立后。'),
('CUV', '路加福音', 42, 20, 29, '有弟兄七人，第一个娶了妻，没有孩子死了；'),
('CUV', '路加福音', 42, 20, 30, '第二个、第三个也娶过他；'),
('CUV', '路加福音', 42, 20, 31, '那七个人都娶过他，没有留下孩子就死了。'),
('CUV', '路加福音', 42, 20, 32, '后来妇人也死了。'),
('CUV', '路加福音', 42, 20, 33, '这样，当复活的时候，他是那一个的妻子呢？因为他们七个人都娶过他。'),
('CUV', '路加福音', 42, 20, 34, '耶稣说：这世界的人有娶有嫁；'),
('CUV', '路加福音', 42, 20, 35, '惟有算为配得那世界，与从死里复活的人也不娶也不嫁；'),
('CUV', '路加福音', 42, 20, 36, '因为他们不能再死，和天使一样；既是复活的人，就为神的儿子。'),
('CUV', '路加福音', 42, 20, 37, '至于死人复活，摩西在荆棘篇上，称主是亚伯拉罕的神，以撒的神，雅各的神，就指示明白了。'),
('CUV', '路加福音', 42, 20, 38, '神原不是死人的神，乃是活人的神；因为在他那里（那里：或作看来），人都是活的。'),
('CUV', '路加福音', 42, 20, 39, '有几个文士说：夫子！你说得好。'),
('CUV', '路加福音', 42, 20, 40, '以后他们不敢再问他甚么。'),
('CUV', '路加福音', 42, 20, 41, '耶稣对他们说：人怎么说基督是大卫的子孙呢？'),
('CUV', '路加福音', 42, 20, 42, '诗篇上大卫自己说：主对我主说：你坐在我的右边，'),
('CUV', '路加福音', 42, 20, 43, '等我使你仇敌作你的脚凳。'),
('CUV', '路加福音', 42, 20, 44, '大卫既称他为主，他怎么又是大卫的子孙呢？'),
('CUV', '路加福音', 42, 20, 45, '众百姓听的时候，耶稣对门徒说：'),
('CUV', '路加福音', 42, 20, 46, '你们要防备文士。他们好穿长衣游行，喜爱人在街市上问他们安，又喜爱会堂里的高位，筵席上的首座；'),
('CUV', '路加福音', 42, 20, 47, '他们侵吞寡妇的家产，假意作很长的祷告。这些人要受更重的刑罚！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 21, 1, '耶稣抬头观看，见财主把捐项投在库里，'),
('CUV', '路加福音', 42, 21, 2, '又见一个穷寡妇投了两个小钱，'),
('CUV', '路加福音', 42, 21, 3, '就说：我实在告诉你们，这穷寡妇所投的比众人还多；'),
('CUV', '路加福音', 42, 21, 4, '因为众人都是自己有余，拿出来投在捐项里，但这寡妇是自己不足，把他一切养生的都投上了。'),
('CUV', '路加福音', 42, 21, 5, '有人谈论圣殿是用美石和供物妆饰的；'),
('CUV', '路加福音', 42, 21, 6, '耶稣就说：论到你们所看见的这一切，将来日子到了，在这里没有一块石头留在石头上，不被拆毁了。'),
('CUV', '路加福音', 42, 21, 7, '他们问他说：夫子！甚么时候有这事呢？这事将到的时候有甚么豫兆呢？'),
('CUV', '路加福音', 42, 21, 8, '耶稣说：你们要谨慎，不要受迷惑；因为将来有好些人冒我的名来，说：我是基督，又说：时候近了，你们不要跟从他们！'),
('CUV', '路加福音', 42, 21, 9, '你们听见打仗和扰乱的事，不要惊惶；因为这些事必须先有，只是末期不能立时就到。'),
('CUV', '路加福音', 42, 21, 10, '当时，耶稣对他们说：民要攻打民，国要攻打国；'),
('CUV', '路加福音', 42, 21, 11, '地要大大震动，多处必有饥荒、瘟疫，又有可怕的异象和大神迹从天上显现。'),
('CUV', '路加福音', 42, 21, 12, '但这一切的事以先，人要下手拿住你们，逼迫你们，把你们交给会堂，并且收在监里，又为我的名拉你们到君王诸侯面前。'),
('CUV', '路加福音', 42, 21, 13, '但这些事终必为你们的见证。'),
('CUV', '路加福音', 42, 21, 14, '所以，你们当立定心意，不要预先思想怎样分诉；'),
('CUV', '路加福音', 42, 21, 15, '因为我必赐你们口才、智慧，是你们一切敌人所敌不住、驳不倒的。'),
('CUV', '路加福音', 42, 21, 16, '连你们的父母、弟兄、亲族、朋友也要把你们交官；你们也有被他们害死的。'),
('CUV', '路加福音', 42, 21, 17, '你们要为我的名被众人恨恶，'),
('CUV', '路加福音', 42, 21, 18, '然而，你们连一根头发也必不损坏。'),
('CUV', '路加福音', 42, 21, 19, '你们常存忍耐，就必保全灵魂（或作：必得生命）。'),
('CUV', '路加福音', 42, 21, 20, '你们看见耶路撒冷被兵围困，就可知道他成荒场的日子近了。'),
('CUV', '路加福音', 42, 21, 21, '那时，在犹太的应当逃到山上；在城里的应当出来；在乡下的不要进城；'),
('CUV', '路加福音', 42, 21, 22, '因为这是报应的日子，使经上所写的都得应验。'),
('CUV', '路加福音', 42, 21, 23, '当那些日子，怀孕的和奶孩子的有祸了！因为将有大灾难降在这地方，也有震怒临到这百姓。'),
('CUV', '路加福音', 42, 21, 24, '他们要倒在刀下，又被掳到各国去。耶路撒冷要被外邦人践踏，直到外邦人的日期满了。'),
('CUV', '路加福音', 42, 21, 25, '日、月、星辰要显出异兆，地上的邦国也有困苦；因海中波浪的响声，就慌慌不定。'),
('CUV', '路加福音', 42, 21, 26, '天势都要震动，人想起那将要临到世界的事，就都吓得魂不附体。'),
('CUV', '路加福音', 42, 21, 27, '那时，他们要看见人子有能力，有大荣耀驾云降临。'),
('CUV', '路加福音', 42, 21, 28, '一有这些事，你们就当挺身昂首，因为你们得赎的日子近了。'),
('CUV', '路加福音', 42, 21, 29, '耶稣又设比喻对他们说：你们看无花果树和各样的树；他发芽的时候，你们一看见，自然晓得夏天近了。'),
('CUV', '路加福音', 42, 21, 30, 'a'),
('CUV', '路加福音', 42, 21, 31, '这样，你们看见这些事渐渐的成就，也该晓得神的国近了。'),
('CUV', '路加福音', 42, 21, 32, '我实在告诉你们，这世代还没有过去，这些事都要成就。'),
('CUV', '路加福音', 42, 21, 33, '天地要废去，我的话却不能废去。'),
('CUV', '路加福音', 42, 21, 34, '你们要谨慎，恐怕因贪食、醉酒，并今生的思虑累住你们的心，那日子就如同网罗忽然临到你们；'),
('CUV', '路加福音', 42, 21, 35, '因为那日子要这样临到全地上一切居住的人。'),
('CUV', '路加福音', 42, 21, 36, '你们要时时儆醒，常常祈求，使你们能逃避这一切要来的事，得以站立在人子面前。'),
('CUV', '路加福音', 42, 21, 37, '耶稣每日在殿里教训人，每夜出城在一座山，名叫橄榄山住宿。'),
('CUV', '路加福音', 42, 21, 38, '众百姓清早上圣殿，到耶稣那里，要听他讲道。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 22, 1, '除酵节，又名逾越节，近了。'),
('CUV', '路加福音', 42, 22, 2, '祭司长和文士想法子怎么才能杀害耶稣，是因他们惧怕百姓。'),
('CUV', '路加福音', 42, 22, 3, '这时，撒但入了那称为加略人犹大的心；他本是十二门徒里的一个。'),
('CUV', '路加福音', 42, 22, 4, '他去和祭司长并守殿官商量，怎么可以把耶稣交给他们。'),
('CUV', '路加福音', 42, 22, 5, '他们欢喜，就约定给他银子。'),
('CUV', '路加福音', 42, 22, 6, '他应允了，就找机会，要趁众人不在跟前的时候把耶稣交给他们。'),
('CUV', '路加福音', 42, 22, 7, '除酵节，须宰逾越羊羔的那一天到了。'),
('CUV', '路加福音', 42, 22, 8, '耶稣打发彼得、约翰，说：你们去为我们预备逾越节的筵席，好叫我们吃。'),
('CUV', '路加福音', 42, 22, 9, '他们问他说：要我们在那里预备？'),
('CUV', '路加福音', 42, 22, 10, '耶稣说：你们进了城，必有人拿著一瓶水迎面而来，你们就跟著他，到他所进的房子里去，'),
('CUV', '路加福音', 42, 22, 11, '对那家的主人说：夫子说：客房在那里？我与门徒好在那里吃逾越节的筵席。'),
('CUV', '路加福音', 42, 22, 12, '他必指给你们摆设整齐的一间大楼，你们就在那里预备。'),
('CUV', '路加福音', 42, 22, 13, '他们去了，所遇见的正如耶稣所说的；他们就预备了逾越节的筵席。'),
('CUV', '路加福音', 42, 22, 14, '时候到了，耶稣坐席，使徒也和他同坐。'),
('CUV', '路加福音', 42, 22, 15, '耶稣对他们说：我很愿意在受害以先和你们吃这逾越节的筵席。'),
('CUV', '路加福音', 42, 22, 16, '我告诉你们，我不再吃这筵席，直到成就在神的国里。'),
('CUV', '路加福音', 42, 22, 17, '耶稣接过杯来，祝谢了，说：你们拿这个，大家分著喝。'),
('CUV', '路加福音', 42, 22, 18, '我告诉你们，从今以后，我不再喝这葡萄汁，直等神的国来到。'),
('CUV', '路加福音', 42, 22, 19, '又拿起饼来，祝谢了，就擘开，递给他们，说：这是我的身体，为你们舍的，你们也应当如此行，为的是记念我。'),
('CUV', '路加福音', 42, 22, 20, '饭后也照样拿起杯来，说：这杯是用我血所立的新约，是为你们流出来的。'),
('CUV', '路加福音', 42, 22, 21, '看哪！那卖我之人的手与我一同在桌子上。'),
('CUV', '路加福音', 42, 22, 22, '人子固然要照所预定的去世，但卖人子的人有祸了！'),
('CUV', '路加福音', 42, 22, 23, '他们就彼此对问，是那一个要做这事。'),
('CUV', '路加福音', 42, 22, 24, '门徒起了争论，他们中间那一个可算为大。'),
('CUV', '路加福音', 42, 22, 25, '耶稣说：外邦人有君王为主治理他们，那掌权管他们的称为恩主。'),
('CUV', '路加福音', 42, 22, 26, '但你们不可这样；你们里头为大的，倒要像年幼的；为首领的，倒要像服事人的。'),
('CUV', '路加福音', 42, 22, 27, '是谁为大？是坐席的呢？是服事人的呢？不是坐席的大么？然而，我在你们中间如同服事人的。'),
('CUV', '路加福音', 42, 22, 28, '我在磨炼之中，常和我同在的就是你们。'),
('CUV', '路加福音', 42, 22, 29, '我将国赐给你们，正如我父赐给我一样，'),
('CUV', '路加福音', 42, 22, 30, '叫你们在我国里，坐在我的席上吃喝，并且坐在宝座上，审判以色列十二个支派。'),
('CUV', '路加福音', 42, 22, 31, '主又说：西门！西门！撒但想要得著你们，好筛你们像筛麦子一样；'),
('CUV', '路加福音', 42, 22, 32, '但我已经为你祈求，叫你不至于失了信心，你回头以后，要坚固你的弟兄。'),
('CUV', '路加福音', 42, 22, 33, '彼得说：主阿，我就是同你下监，同你受死，也是甘心！'),
('CUV', '路加福音', 42, 22, 34, '耶稣说：彼得，我告诉你，今日鸡还没有叫，你要三次说不认得我。'),
('CUV', '路加福音', 42, 22, 35, '耶稣又对他们说：我差你们出去的时候，没有钱囊，没有口袋，没有鞋，你们缺少甚么没有？他们说：没有。'),
('CUV', '路加福音', 42, 22, 36, '耶稣说：但如今有钱囊的可以带著，有口袋的也可以带著，没有刀的要卖衣服买刀。'),
('CUV', '路加福音', 42, 22, 37, '我告诉你们，经上写著说：他被列在罪犯之中。这话必应验在我身上；因为那关系我的事必然成就。'),
('CUV', '路加福音', 42, 22, 38, '他们说：主阿，请看！这里有两把刀。耶稣说：够了。'),
('CUV', '路加福音', 42, 22, 39, '耶稣出来，照常往橄榄山去，门徒也跟随他。'),
('CUV', '路加福音', 42, 22, 40, '到了那地方，就对他们说：你们要祷告，免得入了迷惑。'),
('CUV', '路加福音', 42, 22, 41, '于是离开他们约有扔一块石头那么远，跪下祷告，'),
('CUV', '路加福音', 42, 22, 42, '说：父阿！你若愿意，就把这杯撤去；然而，不要成就我的意思，只要成就你的意思。'),
('CUV', '路加福音', 42, 22, 43, '有一位天使从天上显现，加添他的力量。'),
('CUV', '路加福音', 42, 22, 44, '耶稣极其伤痛，祷告更加恳切，汗珠如大血点滴在地上。'),
('CUV', '路加福音', 42, 22, 45, '祷告完了，就起来，到门徒那里，见他们因为忧愁都睡著了，'),
('CUV', '路加福音', 42, 22, 46, '就对他们说：你们为甚么睡觉呢？起来祷告，免得入了迷惑！'),
('CUV', '路加福音', 42, 22, 47, '说话之间，来了许多人。那十二个门徒里名叫犹大的，走在前头，就近耶稣，要与他亲嘴。'),
('CUV', '路加福音', 42, 22, 48, '耶稣对他说：犹大！你用亲嘴的暗号卖人子么？'),
('CUV', '路加福音', 42, 22, 49, '左右的人见光景不好，就说：主阿﹗我们拿刀砍可以不可以？'),
('CUV', '路加福音', 42, 22, 50, '内中有一个人把大祭司的仆人砍了一刀，削掉了他的右耳。'),
('CUV', '路加福音', 42, 22, 51, '耶稣说：到了这个地步，由他们罢！就摸那人的耳朵，把他治好了。'),
('CUV', '路加福音', 42, 22, 52, '耶稣对那些来拿他的祭司长和守殿官并长老说：你们带著刀棒出来拿我，如同拿强盗么？'),
('CUV', '路加福音', 42, 22, 53, '我天天同你们在殿里，你们不下手拿我。现在却是你们的时候，黑暗掌权了。'),
('CUV', '路加福音', 42, 22, 54, '他们拿住耶稣，把他带到大祭司的宅里。彼得远远的跟著。'),
('CUV', '路加福音', 42, 22, 55, '他们在院子里生了火，一同坐著；彼得也坐在他们中间。'),
('CUV', '路加福音', 42, 22, 56, '有一个使女看见彼得坐在火光里，就定睛看他，说：这个人素来也是同那人一伙的。'),
('CUV', '路加福音', 42, 22, 57, '彼得却不承认，说：女子，我不认得他。'),
('CUV', '路加福音', 42, 22, 58, '过了不多的时候，又有一个人看见他，说：你也是他们一党的。彼得说：你这个人！我不是。'),
('CUV', '路加福音', 42, 22, 59, '约过了一小时，又有一个人极力的说：他实在是同那人一伙的，因为他也是加利利人。'),
('CUV', '路加福音', 42, 22, 60, '彼得说：你这个人！我不晓得你说的是甚么！正说话之间，鸡就叫了。'),
('CUV', '路加福音', 42, 22, 61, '主转过身来看彼得。彼得便想起主对他所说的话：今日鸡叫以先，你要三次不认我。'),
('CUV', '路加福音', 42, 22, 62, '他就出去痛哭。'),
('CUV', '路加福音', 42, 22, 63, '看守耶稣的人戏弄他，打他，'),
('CUV', '路加福音', 42, 22, 64, '又蒙著他的眼，问他说：你是先知，告诉我们打你的是谁？'),
('CUV', '路加福音', 42, 22, 65, '他们还用许多别的话辱骂他。'),
('CUV', '路加福音', 42, 22, 66, '天一亮，民间的众长老连祭司长带文士都聚会，把耶稣带到他们的公会里，'),
('CUV', '路加福音', 42, 22, 67, '说：你若是基督，就告诉我们。耶稣说：我若告诉你们，你们也不信；'),
('CUV', '路加福音', 42, 22, 68, '我若问你们，你们也不回答。'),
('CUV', '路加福音', 42, 22, 69, '从今以后，人子要坐在神权能的右边。'),
('CUV', '路加福音', 42, 22, 70, '他们都说：这样，你是神的儿子么？耶稣说：你们所说的是。'),
('CUV', '路加福音', 42, 22, 71, '他们说：何必再用见证呢？他亲口所说的，我们都亲自听见了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 23, 1, '众人都起来，把耶稣解到彼拉多面前，'),
('CUV', '路加福音', 42, 23, 2, '就告他说：我们见这人诱惑国民，禁止纳税给该撒，并说自己是基督，是王。'),
('CUV', '路加福音', 42, 23, 3, '彼拉多问耶稣说：你是犹太人的王么？耶稣回答说：你说的是。'),
('CUV', '路加福音', 42, 23, 4, '彼拉多对祭司长和众人说：我查不出这人有甚么罪来。'),
('CUV', '路加福音', 42, 23, 5, '但他们越发极力的说：他煽惑百姓，在犹太遍地传道，从加利利起，直到这里了。'),
('CUV', '路加福音', 42, 23, 6, '彼拉多一听见，就问：这人是加利利人么？'),
('CUV', '路加福音', 42, 23, 7, '既晓得耶稣属希律所管，就把他送到希律那里去。那时希律正在耶路撒冷。'),
('CUV', '路加福音', 42, 23, 8, '希律看见耶稣，就很欢喜；因为听见过他的事，久已想要见他，并且指望看他行一件神迹。'),
('CUV', '路加福音', 42, 23, 9, '于是问他许多的话；耶稣却一言不答。'),
('CUV', '路加福音', 42, 23, 10, '祭司长和文士都站著，极力的告他。'),
('CUV', '路加福音', 42, 23, 11, '希律和他的兵丁就藐视耶稣，戏弄他，给他穿上华丽衣服，把他送回彼拉多那里去。'),
('CUV', '路加福音', 42, 23, 12, '从前希律和彼拉多彼此有仇，在那一天就成了朋友。'),
('CUV', '路加福音', 42, 23, 13, '彼拉多传齐了祭司长和官府并百姓，'),
('CUV', '路加福音', 42, 23, 14, '就对他们说：你们解这人到我这里，说他是诱惑百姓的。看哪，我也曾将你们告他的事，在你们面前审问他，并没有查出他甚么罪来；'),
('CUV', '路加福音', 42, 23, 15, '就是希律也是如此，所以把他送回来。可见他没有做甚么该死的事。'),
('CUV', '路加福音', 42, 23, 16, '故此，我要责打他，把他释放了。（有古卷在此有：'),
('CUV', '路加福音', 42, 23, 17, '每逢这节期，巡抚必须释放一个囚犯给他们。）'),
('CUV', '路加福音', 42, 23, 18, '众人却一齐喊著说：除掉这个人！释放巴拉巴给我们！'),
('CUV', '路加福音', 42, 23, 19, '这巴拉巴是因在城里作乱杀人，下在监里的。'),
('CUV', '路加福音', 42, 23, 20, '彼拉多愿意释放耶稣，就又劝解他们。'),
('CUV', '路加福音', 42, 23, 21, '无奈他们喊著说：钉他十字架！钉他十字架！'),
('CUV', '路加福音', 42, 23, 22, '彼拉多第三次对他们说：为甚么呢？这人作了甚么恶事呢？我并没有查出他甚么该死的罪来。所以，我要责打他，把他释放了。'),
('CUV', '路加福音', 42, 23, 23, '他们大声催逼彼拉多，求他把耶稣钉在十字架上。他们的声音就得了胜。'),
('CUV', '路加福音', 42, 23, 24, '彼拉多这才照他们所求的定案，'),
('CUV', '路加福音', 42, 23, 25, '把他们所求的那作乱杀人、下在监里的释放了，把耶稣交给他们，任凭他们的意思行。'),
('CUV', '路加福音', 42, 23, 26, '带耶稣去的时候，有一个古利奈人西门，从乡下来；他们就抓住他，把十字架搁在他身上，叫他背著跟随耶稣。'),
('CUV', '路加福音', 42, 23, 27, '有许多百姓跟随耶稣，内中有好些妇女；妇女们为他号咷痛哭。'),
('CUV', '路加福音', 42, 23, 28, '耶稣转身对他们说：耶路撒冷的女子，不要为我哭，当为自己和自己的儿女哭。'),
('CUV', '路加福音', 42, 23, 29, '因为日子要到，人必说：不生育的，和未曾怀胎的，未曾乳养婴孩的，有福了！'),
('CUV', '路加福音', 42, 23, 30, '那时，人要向大山说：倒在我们身上！向小山说：遮盖我们！'),
('CUV', '路加福音', 42, 23, 31, '这些事既行在有汁水的树上，那枯干的树将来怎么样呢？'),
('CUV', '路加福音', 42, 23, 32, '又有两个犯人，和耶稣一同带来处死。'),
('CUV', '路加福音', 42, 23, 33, '到了一个地方，名叫髑髅地，就在那里把耶稣钉在十字架上，又钉了两个犯人：一个在左边，一个在右边。'),
('CUV', '路加福音', 42, 23, 34, '当下耶稣说：父阿！赦免他们；因为他们所做的，他们不晓得。兵丁就拈阄分他的衣服。'),
('CUV', '路加福音', 42, 23, 35, '百姓站在那里观看。官府也嗤笑他，说：他救了别人；他若是基督，神所拣选的，可以救自己罢！'),
('CUV', '路加福音', 42, 23, 36, '兵丁也戏弄他，上前拿醋送给他喝，'),
('CUV', '路加福音', 42, 23, 37, '说：你若是犹太人的王，可以救自己罢！'),
('CUV', '路加福音', 42, 23, 38, '在耶稣以上有一个牌子（有古卷在此有：用希利尼、罗马、希伯来的文字）写著：这是犹太人的王。'),
('CUV', '路加福音', 42, 23, 39, '那同钉的两个犯人有一个讥诮他，说：你不是基督么？可以救自己和我们罢！'),
('CUV', '路加福音', 42, 23, 40, '那一个就应声责备他，说：你既是一样受刑的，还不怕神么？'),
('CUV', '路加福音', 42, 23, 41, '我们是应该的，因我们所受的与我们所做的相称，但这个人没有做过一件不好的事。'),
('CUV', '路加福音', 42, 23, 42, '就说：耶稣阿，你得国降临的时候，求你记念我！'),
('CUV', '路加福音', 42, 23, 43, '耶稣对他说：我实在告诉你，今日你要同我在乐园里了。'),
('CUV', '路加福音', 42, 23, 44, '那时约有午正，遍地都黑暗了，直到申初，'),
('CUV', '路加福音', 42, 23, 45, '日头变黑了；殿里的幔子从当中裂为两半。'),
('CUV', '路加福音', 42, 23, 46, '耶稣大声喊著说：父阿！我将我的灵魂交在你手里。说了这话，气就断了。'),
('CUV', '路加福音', 42, 23, 47, '百夫长看见所成的事，就归荣耀与神，说：这真是个义人！'),
('CUV', '路加福音', 42, 23, 48, '聚集观看的众人见了这所成的事都捶著胸回去了。'),
('CUV', '路加福音', 42, 23, 49, '还有一切与耶稣熟识的人，和从加利利跟著他来的妇女们，都远远的站著看这些事。'),
('CUV', '路加福音', 42, 23, 50, '有一个人名叫约瑟，是个议士，为人善良公义；'),
('CUV', '路加福音', 42, 23, 51, '众人所谋所为，他并没有附从。他本是犹太、亚利马太城里素常盼望神国的人。'),
('CUV', '路加福音', 42, 23, 52, '这人去见彼拉多，求耶稣的身体，'),
('CUV', '路加福音', 42, 23, 53, '就取下来，用细麻布裹好，安放在石头凿成的坟墓里；那里头从来没有葬过人。'),
('CUV', '路加福音', 42, 23, 54, '那日是预备日，安息日也快到了。'),
('CUV', '路加福音', 42, 23, 55, '那些从加利利和耶稣同来的妇女跟在后面，看见了坟墓和他的身体怎样安放。'),
('CUV', '路加福音', 42, 23, 56, '他们就回去，预备了香料香膏。他们在安息日，便遵著诫命安息了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '路加福音', 42, 24, 1, '七日的头一日，黎明的时候，那些妇女带著所预备的香料来到坟墓前，'),
('CUV', '路加福音', 42, 24, 2, '看见石头已经从坟墓辊开了，'),
('CUV', '路加福音', 42, 24, 3, '他们就进去，只是不见主耶稣的身体。'),
('CUV', '路加福音', 42, 24, 4, '正在猜疑之间，忽然有两个人站在旁边，衣服放光。'),
('CUV', '路加福音', 42, 24, 5, '妇女们惊怕，将脸伏地。那两个人就对他们说：为甚么在死人中找活人呢？'),
('CUV', '路加福音', 42, 24, 6, '他不在这里，已经复活了。当记念他还在加利利的时候怎样告诉你们，'),
('CUV', '路加福音', 42, 24, 7, '说：人子必须被交在罪人手里，钉在十字架上，第三日复活。'),
('CUV', '路加福音', 42, 24, 8, '他们就想起耶稣的话来，'),
('CUV', '路加福音', 42, 24, 9, '便从坟墓那里回去，把这一切事告诉十一个使徒和其余的人。'),
('CUV', '路加福音', 42, 24, 10, '那告诉使徒的就是抹大拉的马利亚和约亚拿，并雅各的母亲马利亚，还有与他们在一处的妇女。'),
('CUV', '路加福音', 42, 24, 11, '他们这些话，使徒以为是胡言，就不相信。'),
('CUV', '路加福音', 42, 24, 12, '彼得起来，跑到坟墓前，低头往里看，见细麻布独在一处，就回去了，心里希奇所成的事。'),
('CUV', '路加福音', 42, 24, 13, '正当那日，门徒中有两个人往一个村子去；这村子名叫以马忤斯，离耶路撒冷约有二十五里。'),
('CUV', '路加福音', 42, 24, 14, '他们彼此谈论所遇见的这一切事。'),
('CUV', '路加福音', 42, 24, 15, '正谈论相问的时候，耶稣亲自就近他们，和他们同行；'),
('CUV', '路加福音', 42, 24, 16, '只是他们的眼睛迷糊了，不认识他。'),
('CUV', '路加福音', 42, 24, 17, '耶稣对他们说：你们走路彼此谈论的是甚么事呢？他们就站住，脸上带著愁容。'),
('CUV', '路加福音', 42, 24, 18, '二人中有一个名叫革流巴的回答说：你在耶路撒冷作客，还不知道这几天在那里所出的事么？'),
('CUV', '路加福音', 42, 24, 19, '耶稣说：甚么事呢？他们说：就是拿撒勒人耶稣的事。他是个先知，在神和众百姓面前，说话行事都有大能。'),
('CUV', '路加福音', 42, 24, 20, '祭司长和我们的官府竟把他解去，定了死罪，钉在十字架上。'),
('CUV', '路加福音', 42, 24, 21, '但我们素来所盼望、要赎以色列民的就是他！不但如此，而且这事成就，现在已经三天了。'),
('CUV', '路加福音', 42, 24, 22, '再者，我们中间有几个妇女使我们惊奇；他们清早到了坟墓那里，'),
('CUV', '路加福音', 42, 24, 23, '不见他的身体，就回来告诉我们，说看见了天使显现，说他活了。'),
('CUV', '路加福音', 42, 24, 24, '又有我们的几个人往坟墓那里去，所遇见的正如妇女们所说的，只是没有看见他。'),
('CUV', '路加福音', 42, 24, 25, '耶稣对他们说：无知的人哪，先知所说的一切话，你们的心信得太迟钝了。'),
('CUV', '路加福音', 42, 24, 26, '基督这样受害，又进入他的荣耀，岂不是应当的么？'),
('CUV', '路加福音', 42, 24, 27, '于是从摩西和众先知起，凡经上所指著自己的话都给他们讲解明白了。'),
('CUV', '路加福音', 42, 24, 28, '将近他们所去的村子，耶稣好像还要往前行，'),
('CUV', '路加福音', 42, 24, 29, '他们却强留他，说：时候晚了，日头已经平西了，请你同我们住下罢！耶稣就进去，要同他们住下。'),
('CUV', '路加福音', 42, 24, 30, '到了坐席的时候，耶稣拿起饼来，祝谢了，擘开，递给他们。'),
('CUV', '路加福音', 42, 24, 31, '他们的眼睛明亮了，这才认出他来。忽然耶稣不见了。'),
('CUV', '路加福音', 42, 24, 32, '他们彼此说：在路上，他和我们说话，给我们讲解圣经的时候，我们的心岂不是火热的么？'),
('CUV', '路加福音', 42, 24, 33, '他们就立时起身，回耶路撒冷去，正遇见十一个使徒和他们的同人聚集在一处，'),
('CUV', '路加福音', 42, 24, 34, '说：主果然复活，已经现给西门看了。'),
('CUV', '路加福音', 42, 24, 35, '两个人就把路上所遇见，和擘饼的时候怎么被他们认出来的事，都述说了一遍。'),
('CUV', '路加福音', 42, 24, 36, '正说这话的时候，耶稣亲自站在他们当中，说：愿你们平安！'),
('CUV', '路加福音', 42, 24, 37, '他们却惊慌害怕，以为所看见的是魂。'),
('CUV', '路加福音', 42, 24, 38, '耶稣说：你们为甚么愁烦？为甚么心里起疑念呢？'),
('CUV', '路加福音', 42, 24, 39, '你们看我的手，我的脚，就知道实在是我了。摸我看看！魂无骨无肉，你们看，我是有的。'),
('CUV', '路加福音', 42, 24, 40, '说了这话，就把手和脚给他们看。'),
('CUV', '路加福音', 42, 24, 41, '他们正喜得不敢信，并且希奇；耶稣就说：你们这里有甚么吃的没有？'),
('CUV', '路加福音', 42, 24, 42, '他们便给他一片烧鱼。（有古卷在此有：和一块蜜房。）'),
('CUV', '路加福音', 42, 24, 43, '他接过来，在他们面前吃了。'),
('CUV', '路加福音', 42, 24, 44, '耶稣对他们说：这就是我从前与你们同在之时所告诉你们的话说：摩西的律法、先知的书，和诗篇上所记的，凡指著我的话都必须应验。'),
('CUV', '路加福音', 42, 24, 45, '于是耶稣开他们的心窍，使他们能明白圣经，'),
('CUV', '路加福音', 42, 24, 46, '又对他们说：照经上所写的，基督必受害，第三日从死里复活，'),
('CUV', '路加福音', 42, 24, 47, '并且人要奉他的名传悔改、赦罪的道，从耶路撒冷起直传到万邦。'),
('CUV', '路加福音', 42, 24, 48, '你们就是这些事的见证。'),
('CUV', '路加福音', 42, 24, 49, '我要将我父所应许的降在你们身上，你们要在城里等候，直到你们领受从上头来的能力。'),
('CUV', '路加福音', 42, 24, 50, '耶稣领他们到伯大尼的对面，就举手给他们祝福。'),
('CUV', '路加福音', 42, 24, 51, '正祝福的时候，他就离开他们，被带到天上去了。'),
('CUV', '路加福音', 42, 24, 52, '他们就拜他，大大的欢喜，回耶路撒冷去，'),
('CUV', '路加福音', 42, 24, 53, '常在殿里称颂神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 1, 1, '太初有道，道与神同在，道就是神。'),
('CUV', '约翰福音', 43, 1, 2, '这道太初与神同在。'),
('CUV', '约翰福音', 43, 1, 3, '万物是藉著他造的；凡被造的，没有一样不是藉著他造的。'),
('CUV', '约翰福音', 43, 1, 4, '生命在他里头，这生命就是人的光。'),
('CUV', '约翰福音', 43, 1, 5, '光照在黑暗里，黑暗却不接受光。'),
('CUV', '约翰福音', 43, 1, 6, '有一个人，是从神那里差来的，名叫约翰。'),
('CUV', '约翰福音', 43, 1, 7, '这人来，为要作见证，就是为光作见证，叫众人因他可以信。'),
('CUV', '约翰福音', 43, 1, 8, '他不是那光，乃是要为光作见证。'),
('CUV', '约翰福音', 43, 1, 9, '那光是真光，照亮一切生在世上的人。'),
('CUV', '约翰福音', 43, 1, 10, '他在世界，世界也是藉著他造的，世界却不认识他。'),
('CUV', '约翰福音', 43, 1, 11, '他到自己的地方来，自己的人倒不接待他。'),
('CUV', '约翰福音', 43, 1, 12, '凡接待他的，就是信他名的人，他就赐他们权柄，作神的儿女。'),
('CUV', '约翰福音', 43, 1, 13, '这等人不是从血气生的，不是从情欲生的，也不是从人意生的，乃是从神生的。'),
('CUV', '约翰福音', 43, 1, 14, '道成了肉身，住在我们中间，充充满满的有恩典有真理。我们也见过他的荣光，正是父独生子的荣光。'),
('CUV', '约翰福音', 43, 1, 15, '约翰为他作见证，喊著说：「这就是我曾说：『那在我以后来的，反成了在我以前的，因他本来在我以前。』」'),
('CUV', '约翰福音', 43, 1, 16, '从他丰满的恩典里，我们都领受了，而且恩上加恩。'),
('CUV', '约翰福音', 43, 1, 17, '律法本是藉著摩西传的；恩典和真理都是由耶稣基督来的。'),
('CUV', '约翰福音', 43, 1, 18, '从来没有人看见神，只有在父怀里的独生子将他表明出来。'),
('CUV', '约翰福音', 43, 1, 19, '约翰所作的见证记在下面：犹太人从耶路撒冷差祭司和利未人到约翰那里，问他说：「你是谁？」'),
('CUV', '约翰福音', 43, 1, 20, '他就明说，并不隐瞒，明说：「我不是基督。」'),
('CUV', '约翰福音', 43, 1, 21, '他们又问他说：「这样，你是谁呢？是以利亚吗？」他说：「我不是。」「是那先知吗？」他回答说：「不是。」'),
('CUV', '约翰福音', 43, 1, 22, '于是他们说：「你到底是谁，叫我们好回复差我们来的人。你自己说，你是谁？」'),
('CUV', '约翰福音', 43, 1, 23, '他说：「我就是那在旷野有人声喊著说：『修直主的道路』，正如先知以赛亚所说的。」'),
('CUV', '约翰福音', 43, 1, 24, '那些人是法利赛人差来的（或作：那差来的是法利赛人）；'),
('CUV', '约翰福音', 43, 1, 25, '他们就问他说：「你既不是基督，不是以利亚，也不是那先知，为甚么施洗呢？」'),
('CUV', '约翰福音', 43, 1, 26, '约翰回答说：「我是用水施洗，但有一位站在你们中间，是你们不认识的，'),
('CUV', '约翰福音', 43, 1, 27, '就是那在我以后来的，我给他解鞋带也不配。」'),
('CUV', '约翰福音', 43, 1, 28, '这是在约但河外伯大尼（有古卷：伯大巴喇），约翰施洗的地方作的见证。'),
('CUV', '约翰福音', 43, 1, 29, '次日，约翰看见耶稣来到他那里，就说：「看哪，神的羔羊，除去（或译：背负）世人罪孽的！'),
('CUV', '约翰福音', 43, 1, 30, '这就是我曾说：『有一位在我以后来、反成了在我以前的，因他本来在我以前。』'),
('CUV', '约翰福音', 43, 1, 31, '我先前不认识他，如今我来用水施洗，为要叫他显明给以色列人。」'),
('CUV', '约翰福音', 43, 1, 32, '约翰又作见证说：「我曾看见圣灵，仿佛鸽子从天降下，住在他的身上。'),
('CUV', '约翰福音', 43, 1, 33, '我先前不认识他，只是那差我来用水施洗的、对我说：『你看见圣灵降下来，住在谁的身上，谁就是用圣灵施洗的。』'),
('CUV', '约翰福音', 43, 1, 34, '我看见了，就证明这是神的儿子。」'),
('CUV', '约翰福音', 43, 1, 35, '再次日，约翰同两个门徒站在那里。'),
('CUV', '约翰福音', 43, 1, 36, '他见耶稣行走，就说：「看哪，这是神的羔羊！」'),
('CUV', '约翰福音', 43, 1, 37, '两个门徒听见他的话，就跟从了耶稣。'),
('CUV', '约翰福音', 43, 1, 38, '耶稣转过身来，看见他们跟著，就问他们说：「你们要甚么？」他们说：「拉比，在哪里住？」（拉比翻出来就是夫子。）'),
('CUV', '约翰福音', 43, 1, 39, '耶稣说：「你们来看。」他们就去看他在那里住，这一天便与他同住；那时约有申正了。'),
('CUV', '约翰福音', 43, 1, 40, '听见约翰的话跟从耶稣的那两个人，一个是西门彼得的兄弟安得烈。'),
('CUV', '约翰福音', 43, 1, 41, '他先找著自己的哥哥西门，对他说：「我们遇见弥赛亚了。」（弥赛亚繙出来就是基督。）'),
('CUV', '约翰福音', 43, 1, 42, '于是领他去见耶稣。耶稣看著他，说：「你是约翰的儿子西门（约翰在马太16：17称约拿），你要称为矶法。」（矶法翻出来就是彼得。）'),
('CUV', '约翰福音', 43, 1, 43, '又次日，耶稣想要往加利利去，遇见腓力，就对他说：「来跟从我吧。」'),
('CUV', '约翰福音', 43, 1, 44, '这腓力是伯赛大人，和安得烈、彼得同城。'),
('CUV', '约翰福音', 43, 1, 45, '腓力找著拿但业，对他说「摩西在律法上所写的和众先知所记的那一位，我们遇见了，就是约瑟的儿子拿撒勒人耶稣。」'),
('CUV', '约翰福音', 43, 1, 46, '拿但业对他说：「拿撒勒还能出甚么好的吗？」腓力说：「你来看！」'),
('CUV', '约翰福音', 43, 1, 47, '耶稣看见拿但业来，就指著他说：「看哪，这是个真以色列人，他心里是没有诡诈的。」'),
('CUV', '约翰福音', 43, 1, 48, '拿但业对耶稣说：「你从哪知道我呢？」耶稣回答说：「腓力还没有招呼你，你在无花果树底下，我就看见你了。」'),
('CUV', '约翰福音', 43, 1, 49, '拿但业说：「拉比，你是神的儿子，你是以色列的王！」'),
('CUV', '约翰福音', 43, 1, 50, '耶稣对他说：「因为我说『在无花果树底下看见你』，你就信吗？你将要看见比这更大的事」；'),
('CUV', '约翰福音', 43, 1, 51, '又说：「我实实在在地告诉你们，你们将要看见天开了，神的使者上去下来在人子身上。」')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 2, 1, '第三日，在加利利的迦拿有娶亲的筵席，耶稣的母亲在那里。'),
('CUV', '约翰福音', 43, 2, 2, '耶稣和他的门徒也被请去赴席。'),
('CUV', '约翰福音', 43, 2, 3, '酒用尽了，耶稣的母亲对他说：「他们没有酒了。」'),
('CUV', '约翰福音', 43, 2, 4, '耶稣说：「母亲（原文是妇人），我与你有甚么相干？我的时候还没有到。」'),
('CUV', '约翰福音', 43, 2, 5, '他母亲对用人说：「他告诉你们甚么，你们就做甚么。」'),
('CUV', '约翰福音', 43, 2, 6, '照犹太人洁净的规矩，有六口石缸摆在那里，每口可以盛两三桶水。'),
('CUV', '约翰福音', 43, 2, 7, '耶稣对用人说：「把缸倒满了水。他们就倒满了，直到缸口。」'),
('CUV', '约翰福音', 43, 2, 8, '耶稣又说：「现在可以舀出来，送给管筵席的。他们就送了去。」'),
('CUV', '约翰福音', 43, 2, 9, '管筵席的尝了那水变的酒，并不知道是那里来的，只有舀水的用人知道。管筵席的便叫新郎来，'),
('CUV', '约翰福音', 43, 2, 10, '对他说：「人都是先摆上好酒，等客喝足了，才摆上次的，你倒把好酒留到如今！」'),
('CUV', '约翰福音', 43, 2, 11, '这是耶稣所行的头一件神迹，是在加利利的迦拿行的，显出他的荣耀来；他的门徒就信他了。'),
('CUV', '约翰福音', 43, 2, 12, '这事以后，耶稣与他的母亲、弟兄、和门徒都下迦百农去，在那里住了不多几日。'),
('CUV', '约翰福音', 43, 2, 13, '犹太人的逾越节近了，耶稣就上耶路撒冷去。'),
('CUV', '约翰福音', 43, 2, 14, '看见殿里有卖牛、羊、鸽子的，并有兑换银钱的人坐在那里，'),
('CUV', '约翰福音', 43, 2, 15, '耶稣就拿绳子做成鞭子，把牛羊都赶出殿去，倒出兑换银钱之人的银钱，推翻他们的桌子，'),
('CUV', '约翰福音', 43, 2, 16, '又对卖鸽子的说：「把这些东西拿去！不要将我父的殿当作买卖的地方。」'),
('CUV', '约翰福音', 43, 2, 17, '他的门徒就想起经上记著说：「我为你的殿心里焦急，如同火烧。」'),
('CUV', '约翰福音', 43, 2, 18, '因此犹太人问他说：「你既做这些事，还显甚么神迹给我们看呢？」'),
('CUV', '约翰福音', 43, 2, 19, '耶稣回答说：「你们拆毁这殿，我三日内要再建立起来。」'),
('CUV', '约翰福音', 43, 2, 20, '犹太人便说：「这殿是四十六年才造成的，你三日内就再建立起来吗？」'),
('CUV', '约翰福音', 43, 2, 21, '但耶稣这话是以他的身体为殿。'),
('CUV', '约翰福音', 43, 2, 22, '所以到他从死里复活以后，门徒就想起他说过这话，便信了圣经和耶稣所说的。'),
('CUV', '约翰福音', 43, 2, 23, '当耶稣在耶路撒冷过逾越节的时候，有许多人看见他所行的神迹，就信了他的名。'),
('CUV', '约翰福音', 43, 2, 24, '耶稣却不将自己交托他们；因为他知道万人，'),
('CUV', '约翰福音', 43, 2, 25, '也用不著谁见证人怎样，因他知道人心里所存的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 3, 1, '有一个法利赛人，名叫尼哥底母，是犹太人的官。'),
('CUV', '约翰福音', 43, 3, 2, '这人夜里来见耶稣，说「拉比，我们知道你是由神那来作师傅的；因为你所行的神迹，若没有神同在，无人能行。」'),
('CUV', '约翰福音', 43, 3, 3, '耶稣回答说：「我实实在在地告诉你，人若不重生，就不能见神的国。」'),
('CUV', '约翰福音', 43, 3, 4, '尼哥底母说：「人已经老了，如何能重生呢？岂能再进母腹生出来吗？」'),
('CUV', '约翰福音', 43, 3, 5, '耶稣说：「我实实在在的告诉你，人若不是从水和圣灵生的，就不能进神的国。'),
('CUV', '约翰福音', 43, 3, 6, '从肉身生的就是肉身；从灵生的就是灵。'),
('CUV', '约翰福音', 43, 3, 7, '我说：『你们必须重生』，你不要以为希奇。'),
('CUV', '约翰福音', 43, 3, 8, '风随著意思吹，你听见风的响声，却不晓得从那里来，往那里去；凡从圣灵生的，也是如此。」'),
('CUV', '约翰福音', 43, 3, 9, '尼哥底母问他说：「怎能有这事呢？」'),
('CUV', '约翰福音', 43, 3, 10, '耶稣回答说：「你是以色列人的先生，还不明白这事吗？'),
('CUV', '约翰福音', 43, 3, 11, '我实实在在的告诉你，我们所说的是我们知道的；我们所见证的是我们见过的；你们却不领受我们的见证。'),
('CUV', '约翰福音', 43, 3, 12, '我对你们说地上的事，你们尚且不信，若说天上的事，如何能信呢？'),
('CUV', '约翰福音', 43, 3, 13, '除了从天降下、仍旧在天的人子，没有人升过天。'),
('CUV', '约翰福音', 43, 3, 14, '摩西在旷野怎样举蛇，人子也必照样被举起来，'),
('CUV', '约翰福音', 43, 3, 15, '叫一切信他的都得永生（或作：叫一切信的人在他里面得永生）。'),
('CUV', '约翰福音', 43, 3, 16, '「神爱世人，甚至将他的独生子赐给他们，叫一切信他的，不至灭亡，反得永生。'),
('CUV', '约翰福音', 43, 3, 17, '因为神差他的儿子降世，不是要定世人的罪（或作：审判世人；下同），乃是要叫世人因他得救。'),
('CUV', '约翰福音', 43, 3, 18, '信他的人，不被定罪；不信的人，罪已经定了，因为他不信神独生子的名。'),
('CUV', '约翰福音', 43, 3, 19, '光来到世间，世人因自己的行为是恶的，不爱光，倒爱黑暗，定他们的罪就是在此。'),
('CUV', '约翰福音', 43, 3, 20, '凡作恶的便恨光，并不来就光，恐怕他的行为受责备。'),
('CUV', '约翰福音', 43, 3, 21, '但行真理的必来就光，要显明他所行的是靠神而行。」'),
('CUV', '约翰福音', 43, 3, 22, '这事以后，耶稣和门徒到了犹太地，在那里居住，施洗。'),
('CUV', '约翰福音', 43, 3, 23, '约翰在靠近撒冷的哀嫩也施洗；因为那里水多，众人都去受洗。'),
('CUV', '约翰福音', 43, 3, 24, '（那时约翰还没有下在监计。）'),
('CUV', '约翰福音', 43, 3, 25, '约翰的门徒和一个犹太人辩论洁净的礼，'),
('CUV', '约翰福音', 43, 3, 26, '就来见约翰，说：「拉比，从前同你在约旦河外、你所见证的那位，现在施洗，众人都往他那里去了。」'),
('CUV', '约翰福音', 43, 3, 27, '约翰说：「若不是从天上赐的，人就不能得甚么。'),
('CUV', '约翰福音', 43, 3, 28, '我曾说：『我不是基督，是奉差遣在他前面的』，你们自己可以给我作见证。'),
('CUV', '约翰福音', 43, 3, 29, '娶新妇的就是新郎；新郎的朋友站著，听见新郎的声音就甚喜乐。故此，我这喜乐满足了。'),
('CUV', '约翰福音', 43, 3, 30, '他必兴旺，我必衰微。」'),
('CUV', '约翰福音', 43, 3, 31, '「从天上来的是在万有之上；从地上来的是属乎地，他所说的也是属乎地。从天上来的是在万有之上。'),
('CUV', '约翰福音', 43, 3, 32, '他将所见所闻的见证出来，只是没有人领受他的见证。'),
('CUV', '约翰福音', 43, 3, 33, '那领受他见证的，就印上印，证明神是真的。'),
('CUV', '约翰福音', 43, 3, 34, '神所差来的就说神的话，因为神赐圣灵给他是没有限量的。'),
('CUV', '约翰福音', 43, 3, 35, '父爱子，已将万有交在他手里。'),
('CUV', '约翰福音', 43, 3, 36, '信子的人有永生；不信子的人得不著永生（原文作不得见永生），神的震怒常在他身上。」')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 4, 1, '主知道法利赛人听见他收门徒，施洗，比约翰还多，'),
('CUV', '约翰福音', 43, 4, 2, '（其实不是耶稣亲自施洗，乃是他的门徒施洗，）'),
('CUV', '约翰福音', 43, 4, 3, '他就离了犹太，又往加利利去。'),
('CUV', '约翰福音', 43, 4, 4, '必须经过撒玛利亚，'),
('CUV', '约翰福音', 43, 4, 5, '于是到了撒玛利亚的一座城，名叫叙加，靠近雅各给他儿子约瑟的那块地。'),
('CUV', '约翰福音', 43, 4, 6, '在那里有雅各井；耶稣因走路困乏，就坐在井旁。那时约有午正。'),
('CUV', '约翰福音', 43, 4, 7, '有一个撒玛利亚的妇人来打水。耶稣对他说：「请你给我水喝。」'),
('CUV', '约翰福音', 43, 4, 8, '（那时门徒进城买食物去了。〉'),
('CUV', '约翰福音', 43, 4, 9, '撒玛利亚的妇人对他说：「你既是犹太人，怎么向我一个撒马利亚妇人要水喝呢？」原来犹太人和撒玛利亚人没有来往。'),
('CUV', '约翰福音', 43, 4, 10, '耶稣回答说：「你若知道神的恩赐，和对你说『给我水喝』的是谁，你必早求他，他也必早给了你活水。」'),
('CUV', '约翰福音', 43, 4, 11, '妇人说：「先生，没有打水的器具，井又深，你从那里得活水呢？'),
('CUV', '约翰福音', 43, 4, 12, '我们的祖宗雅各将这井留给我们，他自己和儿子并牲畜也都喝这井里的水，难道你比他还大吗？」'),
('CUV', '约翰福音', 43, 4, 13, '耶稣回答说：凡喝这水的还要再渴；'),
('CUV', '约翰福音', 43, 4, 14, '人若喝我所赐的水就永远不渴。我所赐的水要在他里头成为泉源，直涌到永生。」'),
('CUV', '约翰福音', 43, 4, 15, '妇人说：「先生，请把这水赐给我，叫我不渴，也不用来这么远打水。」'),
('CUV', '约翰福音', 43, 4, 16, '耶稣说：「你去叫你丈夫也到这里来。」'),
('CUV', '约翰福音', 43, 4, 17, '妇人说：「我没有丈夫。」耶稣说：「你说没有丈夫是不错的。'),
('CUV', '约翰福音', 43, 4, 18, '你已经有五个丈夫，你现在有的并不是你的丈夫。你这话是真的。」'),
('CUV', '约翰福音', 43, 4, 19, '妇人说：先生，我看出你是先知。'),
('CUV', '约翰福音', 43, 4, 20, '我们的祖宗在这山上礼拜，你们倒说，应当礼拜的地方是在耶路撒冷。」'),
('CUV', '约翰福音', 43, 4, 21, '耶稣说：妇人，你当信我。时候将到，你们拜父，也不在这山上，也不在耶路撒冷。'),
('CUV', '约翰福音', 43, 4, 22, '你们所拜的，你们不知道；我们所拜的，我们知道，因为救恩是从犹太人出来的。'),
('CUV', '约翰福音', 43, 4, 23, '时候将到，如今就是了，那真正拜父的，要用心灵和诚实拜他，因为父要这样的人拜他。'),
('CUV', '约翰福音', 43, 4, 24, '神是个灵（或无个字），所以拜他的必须用心灵和诚实拜他。」'),
('CUV', '约翰福音', 43, 4, 25, '妇人说：「我知道弥赛亚（就是那称为基督的）要来；他来了，必将一切的事都告诉我们。」'),
('CUV', '约翰福音', 43, 4, 26, '耶稣说：「这和你说话的就是他！」'),
('CUV', '约翰福音', 43, 4, 27, '当下门徒回来，就希奇耶稣和一个妇人说话；只是没有人说：「你是要甚么？」或说：「你为甚么和他说话？」'),
('CUV', '约翰福音', 43, 4, 28, '那妇人就留下水罐子，往城里去，对众人说：'),
('CUV', '约翰福音', 43, 4, 29, '「你们来看！有一个人将我素来所行的一切事都给我说出来了，莫非这就是基督吗？」'),
('CUV', '约翰福音', 43, 4, 30, '众人就出城，往耶稣那里去。'),
('CUV', '约翰福音', 43, 4, 31, '这其间，门徒对耶稣说：「拉比，请吃。」'),
('CUV', '约翰福音', 43, 4, 32, '耶稣说：「我有食物吃，是你们不知道的。」'),
('CUV', '约翰福音', 43, 4, 33, '门徒就彼此对问说：「莫非有人拿甚么给他吃吗？」'),
('CUV', '约翰福音', 43, 4, 34, '耶稣说：「我的食物就是遵行差我来者的旨意，做成他的工。'),
('CUV', '约翰福音', 43, 4, 35, '你们岂不说『到收割的时候还有四个月』吗？我告诉你们，举目向田观看，庄稼已经熟了（原文是发白），可以收割了。'),
('CUV', '约翰福音', 43, 4, 36, '收割的人得工价，积蓄五谷到永生，叫撒种的和收割的一同快乐。'),
('CUV', '约翰福音', 43, 4, 37, '俗语说：：『那人撒种，这人收割』，这话可见是真的。'),
('CUV', '约翰福音', 43, 4, 38, '我差你们去收你们所没有劳苦的；别人劳苦，你们享受他们所劳苦的。」'),
('CUV', '约翰福音', 43, 4, 39, '那城里有好些撒玛利亚人信了耶稣，因为那妇人作见证说：「他将我素来所行的一切事都给我说出来了。」'),
('CUV', '约翰福音', 43, 4, 40, '于是撒玛利亚人来见耶稣，求他在他们那里住下，他便在那里住了两天。'),
('CUV', '约翰福音', 43, 4, 41, '因耶稣的话，信的人就更多了，'),
('CUV', '约翰福音', 43, 4, 42, '便对妇人说：「现在我们信，不是因为你的话，是我们亲自听见了，知道这真是救世主。」'),
('CUV', '约翰福音', 43, 4, 43, '过了那两天，耶稣离了那地方，往加利利去。'),
('CUV', '约翰福音', 43, 4, 44, '因为耶稣自己作过见证说：「先知在本地是没有人尊敬的。」'),
('CUV', '约翰福音', 43, 4, 45, '到了加利利，加利利人既然看见他在耶路撒冷过节所行的一切事，就接待他，因为他们也是上去过节。'),
('CUV', '约翰福音', 43, 4, 46, '耶稣又到了加利利的迦拿，就是他从前变水为酒的地方。有一个大臣，他的儿子在迦百农患病。'),
('CUV', '约翰福音', 43, 4, 47, '他听见耶稣从犹太到了加利利，就来见他，求他下去医治他的儿子，因为他儿子快要死了。'),
('CUV', '约翰福音', 43, 4, 48, '耶稣就对他说：「若不看见神迹奇事，你们总是不信。」'),
('CUV', '约翰福音', 43, 4, 49, '那大臣说：「先生，求你趁著我的孩子还没有死就下去。」'),
('CUV', '约翰福音', 43, 4, 50, '耶稣对他说：「回去吧，你的儿子活了！」那人信耶稣所说的话就回去了。'),
('CUV', '约翰福音', 43, 4, 51, '正下去的时候，他的仆人迎见他，说他的儿子活了。'),
('CUV', '约翰福音', 43, 4, 52, '他就问甚么时候见好的。他们说：「昨日未时热就退了。」'),
('CUV', '约翰福音', 43, 4, 53, '他便知道这正是耶稣对他说「你儿子活了」的时候；他自己和全家就都信了。'),
('CUV', '约翰福音', 43, 4, 54, '这是耶稣在加利利行的第二件神迹，是他从犹太回去以后行的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 5, 1, '这事以后，到了犹太人的一个节期，耶稣就上耶路撒冷去。'),
('CUV', '约翰福音', 43, 5, 2, '在耶路撒冷，靠近羊门有一个池子，希伯来话叫作毕士大，旁边有五个廊子；'),
('CUV', '约翰福音', 43, 5, 3, '里面躺著瞎眼的、瘸腿的、血气枯干的许多病人。（有古卷在此有：等候水动；'),
('CUV', '约翰福音', 43, 5, 4, '因为有天使按时下池子搅动那水，水动之后，谁先下去，无论害甚么病就痊愈了。）'),
('CUV', '约翰福音', 43, 5, 5, '在那里有一个人，病了三十八年。'),
('CUV', '约翰福音', 43, 5, 6, '耶稣看见他躺著，知道他病了许久，就问他说：你要痊瘉么？'),
('CUV', '约翰福音', 43, 5, 7, '病人回答说：先生，水动的时候，没有人把我放在池子里；我正去的时候，就有别人比我先下去。'),
('CUV', '约翰福音', 43, 5, 8, '耶稣对他说：起来，拿你的褥子走罢！'),
('CUV', '约翰福音', 43, 5, 9, '那人立刻痊愈，就拿起褥子来走了。'),
('CUV', '约翰福音', 43, 5, 10, '那天是安息日，所以犹太人对那医好的人说：今天是安息日，你拿褥子是不可的。'),
('CUV', '约翰福音', 43, 5, 11, '他却回答说：那使我痊愈的，对我说：拿你的褥子走罢。'),
('CUV', '约翰福音', 43, 5, 12, '他们问他说：对你说拿褥子走的是甚么人？'),
('CUV', '约翰福音', 43, 5, 13, '那医好的人不知道是谁；因为那里的人多，耶稣已经躲开了。'),
('CUV', '约翰福音', 43, 5, 14, '后来耶稣在殿里遇见他，对他说：你已经痊愈了，不要再犯罪，恐怕你遭遇的更加利害。'),
('CUV', '约翰福音', 43, 5, 15, '那人就去告诉犹太人，使他痊愈的是耶稣。'),
('CUV', '约翰福音', 43, 5, 16, '所以犹太人逼迫耶稣，因为他在安息日做了这事。'),
('CUV', '约翰福音', 43, 5, 17, '耶稣就对他们说：我父做事直到如今，我也做事。'),
('CUV', '约翰福音', 43, 5, 18, '所以犹太人越发想要杀他；因他不但犯了安息日，并且称神为他的父，将自己和神当作平等。'),
('CUV', '约翰福音', 43, 5, 19, '耶稣对他们说：我实实在在的告诉你们，子凭著自己不能做甚么，惟有看见父所做的，子才能做；父所做的事，子也照样做。'),
('CUV', '约翰福音', 43, 5, 20, '父爱子，将自己所做的一切事指给他看，还要将比这更大的事指给他看，叫你们希奇。'),
('CUV', '约翰福音', 43, 5, 21, '父怎样叫死人起来，使他们活著，子也照样随自己的意思使人活著。'),
('CUV', '约翰福音', 43, 5, 22, '父不审判甚么人，乃将审判的事全交与子，'),
('CUV', '约翰福音', 43, 5, 23, '叫人都尊敬子如同尊敬父一样。不尊敬子的，就是不尊敬差子来的父。'),
('CUV', '约翰福音', 43, 5, 24, '我实实在在的告诉你们，那听我话、又信差我来者的，就有永生；不至于定罪，是已经出死入生了。'),
('CUV', '约翰福音', 43, 5, 25, '我实实在在的告诉你们，时候将到，现在就是了，死人要听见神儿子的声音，听见的人就要活了。'),
('CUV', '约翰福音', 43, 5, 26, '因为父怎样在自己有生命，就赐给他儿子也照样在自己有生命，'),
('CUV', '约翰福音', 43, 5, 27, '并且因为他是人子，就赐给他行审判的权柄。'),
('CUV', '约翰福音', 43, 5, 28, '你们不要把这事看作希奇。时候要到，凡在坟墓里的，都要听见他的声音，就出来；'),
('CUV', '约翰福音', 43, 5, 29, '行善的，复活得生；作恶的，复活定罪。'),
('CUV', '约翰福音', 43, 5, 30, '我凭著自己不能做甚么，我怎么听见就怎么审判。我的审判也是公平的；因为我不求自己的意思，只求那差我来者的意思。'),
('CUV', '约翰福音', 43, 5, 31, '我若为自己作见证，我的见证就不真。'),
('CUV', '约翰福音', 43, 5, 32, '另有一位给我作见证，我也知道他给我作的见证是真的。'),
('CUV', '约翰福音', 43, 5, 33, '你们曾差人到约翰那里，他为真理作过见证。'),
('CUV', '约翰福音', 43, 5, 34, '其实，我所受的见证不是从人来的；然而，我说这些话，为要叫你们得救。'),
('CUV', '约翰福音', 43, 5, 35, '约翰是点著的明灯，你们情愿暂时喜欢他的光。'),
('CUV', '约翰福音', 43, 5, 36, '但我有比约翰更大的见证；因为父交给我要我成就的事，就是我所做的事，这便见证我是父所差来的。'),
('CUV', '约翰福音', 43, 5, 37, '差我来的父也为我作过见证。你们从来没有听见他的声音，也没有看见他的形像。'),
('CUV', '约翰福音', 43, 5, 38, '你们并没有他的道存在心里；因为他所差来的，你们不信。'),
('CUV', '约翰福音', 43, 5, 39, '你们查考圣经（或作：应当查考圣经），因你们以为内中有永生；给我作见证的就是这经。'),
('CUV', '约翰福音', 43, 5, 40, '然而，你们不肯到我这里来得生命。'),
('CUV', '约翰福音', 43, 5, 41, '我不受从人来的荣耀。'),
('CUV', '约翰福音', 43, 5, 42, '但我知道，你们心里没有神的爱。'),
('CUV', '约翰福音', 43, 5, 43, '我奉我父的名来，你们并不接待我；若有别人奉自己的名来，你们倒要接待他。'),
('CUV', '约翰福音', 43, 5, 44, '你们互相受荣耀，却不求从独一之神来的荣耀，怎能信我呢？'),
('CUV', '约翰福音', 43, 5, 45, '不要想我在父面前要告你们；有一位告你们的，就是你们所仰赖的摩西。'),
('CUV', '约翰福音', 43, 5, 46, '你们如果信摩西，也必信我，因为他书上有指著我写的话。'),
('CUV', '约翰福音', 43, 5, 47, '你们若不信他的书，怎能信我的话呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 6, 1, '这事以后，耶稣渡过加利利海，就是提比哩亚海。'),
('CUV', '约翰福音', 43, 6, 2, '有许多人因为看见他在病人身上所行的神迹，就跟随他。'),
('CUV', '约翰福音', 43, 6, 3, '耶稣上了山，和门徒一同坐在那里。'),
('CUV', '约翰福音', 43, 6, 4, '那时犹太人的逾越节近了。'),
('CUV', '约翰福音', 43, 6, 5, '耶稣举目看见许多人来，就对腓力说：我们从那里买饼叫这些人吃呢？'),
('CUV', '约翰福音', 43, 6, 6, '他说这话是要试验腓力；他自己原知道要怎样行。'),
('CUV', '约翰福音', 43, 6, 7, '腓力回答说：就是二十两银子的饼，叫他们各人吃一点也是不够的。'),
('CUV', '约翰福音', 43, 6, 8, '有一个门徒，就是西门彼得的兄弟安得烈，对耶稣说：'),
('CUV', '约翰福音', 43, 6, 9, '在这里有一个孩童，带著五个大麦饼、两条鱼，只是分给这许多人还算甚么呢？'),
('CUV', '约翰福音', 43, 6, 10, '耶稣说：你们叫众人坐下。原来那地方的草多，众人就坐下，数目约有五千。'),
('CUV', '约翰福音', 43, 6, 11, '耶稣拿起饼来，祝谢了，就分给那坐著的人；分鱼也是这样，都随著他们所要的。'),
('CUV', '约翰福音', 43, 6, 12, '他们吃饱了，耶稣对门徒说：把剩下的零碎收拾起来，免得有糟蹋的。'),
('CUV', '约翰福音', 43, 6, 13, '他们便将那五个大麦饼的零碎，就是众人吃了剩下的，收拾起来，装满了十二个篮子。'),
('CUV', '约翰福音', 43, 6, 14, '众人看见耶稣所行的神迹，就说：这真是那要到世间来的先知！'),
('CUV', '约翰福音', 43, 6, 15, '耶稣既知道众人要来强逼他作王，就独自又退到山上去了。'),
('CUV', '约翰福音', 43, 6, 16, '到了晚上，他的门徒下海边去，'),
('CUV', '约翰福音', 43, 6, 17, '上了船，要过海往迦百农去。天已经黑了，耶稣还没有来到他们那里。'),
('CUV', '约翰福音', 43, 6, 18, '忽然狂风大作，海就翻腾起来。'),
('CUV', '约翰福音', 43, 6, 19, '门徒摇橹，约行了十里多路，看见耶稣在海面上走，渐渐近了船，他们就害怕。'),
('CUV', '约翰福音', 43, 6, 20, '耶稣对他们说：是我，不要怕！'),
('CUV', '约翰福音', 43, 6, 21, '门徒就喜欢接他上船，船立时到了他们所要去的地方。'),
('CUV', '约翰福音', 43, 6, 22, '第二日，站在海那边的众人知道那里没有别的船，只有一只小船，又知道耶稣没有同他的门徒上船，乃是门徒自己去的。'),
('CUV', '约翰福音', 43, 6, 23, '然而，有几只小船从提比哩亚来，靠近主祝谢后分饼给人吃的地方。'),
('CUV', '约翰福音', 43, 6, 24, '众人见耶稣和门徒都不在那里，就上了船，往迦百农去找耶稣。'),
('CUV', '约翰福音', 43, 6, 25, '既在海那边找著了，就对他说：拉比，是几时到这里来的？'),
('CUV', '约翰福音', 43, 6, 26, '耶稣回答说：我实实在在的告诉你们，你们找我，并不是因见了神迹，乃是因吃饼得饱。'),
('CUV', '约翰福音', 43, 6, 27, '不要为那必坏的食物劳力，要为那存到永生的食物劳力，就是人子要赐给你们的，因为人子是父神所印证的。'),
('CUV', '约翰福音', 43, 6, 28, '众人问他说：我们当行甚么，才算做神的工呢？'),
('CUV', '约翰福音', 43, 6, 29, '耶稣回答说：信神所差来的，这就是做神的工。'),
('CUV', '约翰福音', 43, 6, 30, '他们又说：你行甚么神迹，叫我们看见就信你；你到底做甚么事呢？'),
('CUV', '约翰福音', 43, 6, 31, '我们的祖宗在旷野吃过吗哪，如经上写著说：他从天上赐下粮来给他们吃。'),
('CUV', '约翰福音', 43, 6, 32, '耶稣说：我实实在在的告诉你们，那从天上来的粮不是摩西赐给你们的，乃是我父将天上来的真粮赐给你们。'),
('CUV', '约翰福音', 43, 6, 33, '因为神的粮就是那从天上降下来、赐生命给世界的。'),
('CUV', '约翰福音', 43, 6, 34, '他们说：主阿，常将这粮赐给我们！'),
('CUV', '约翰福音', 43, 6, 35, '耶稣说：我就是生命的粮。到我这里来的，必定不饿；信我的，永远不渴。'),
('CUV', '约翰福音', 43, 6, 36, '只是我对你们说过，你们已经看见我，还是不信。'),
('CUV', '约翰福音', 43, 6, 37, '凡父所赐给我的人必到我这里来；到我这里来的，我总不丢弃他。'),
('CUV', '约翰福音', 43, 6, 38, '因为我从天上降下来，不是要按自己的意思行，乃是要按那差我来者的意思行。'),
('CUV', '约翰福音', 43, 6, 39, '差我来者的意思就是：他所赐给我的，叫我一个也不失落，在末日却叫他复活。'),
('CUV', '约翰福音', 43, 6, 40, '因为我父的意思是叫一切见子而信的人得永生，并且在末日我要叫他复活。'),
('CUV', '约翰福音', 43, 6, 41, '犹太人因为耶稣说我是从天上降下来的粮，就私下议论他，'),
('CUV', '约翰福音', 43, 6, 42, '说：这不是约瑟的儿子耶稣么？他的父母我们岂不认得么？他如今怎么说我是从天上降下来的呢？'),
('CUV', '约翰福音', 43, 6, 43, '耶稣回答说：你们不要大家议论。'),
('CUV', '约翰福音', 43, 6, 44, '若不是差我来的父吸引人，就没有能到我这里来的；到我这里来的，在末日我要叫他复活。'),
('CUV', '约翰福音', 43, 6, 45, '在先知书上写著说：他们都要蒙神的教训。凡听见父之教训又学习的，就到我这里来。'),
('CUV', '约翰福音', 43, 6, 46, '这不是说有人看见过父；惟独从神来的，他看见过父。'),
('CUV', '约翰福音', 43, 6, 47, '我实实在在的告诉你们，信的人有永生。'),
('CUV', '约翰福音', 43, 6, 48, '我就是生命的粮。'),
('CUV', '约翰福音', 43, 6, 49, '你们的祖宗在旷野吃过吗哪，还是死了。'),
('CUV', '约翰福音', 43, 6, 50, '这是从天上降下来的粮，叫人吃了就不死。'),
('CUV', '约翰福音', 43, 6, 51, '我是从天上降下来生命的粮；人若吃这粮，就必永远活著。我所要赐的粮就是我的肉，为世人之生命所赐的。'),
('CUV', '约翰福音', 43, 6, 52, '因此，犹太人彼此争论说：这个人怎能把他的肉给我们吃呢？'),
('CUV', '约翰福音', 43, 6, 53, '耶稣说：我实实在在的告诉你们，你们若不吃人子的肉，不喝人子的血，就没有生命在你们里面。'),
('CUV', '约翰福音', 43, 6, 54, '吃我肉、喝我血的人就有永生，在末日我要叫他复活。'),
('CUV', '约翰福音', 43, 6, 55, '我的肉真是可吃的，我的血真是可喝的。'),
('CUV', '约翰福音', 43, 6, 56, '吃我肉、喝我血的人常在我里面，我也常在他里面。'),
('CUV', '约翰福音', 43, 6, 57, '永活的父怎样差我来，我又因父活著；照样，吃我肉的人也要因我活著。'),
('CUV', '约翰福音', 43, 6, 58, '这就是从天上降下来的粮。吃这粮的人就永远活著，不像你们的祖宗吃过吗哪还是死了。'),
('CUV', '约翰福音', 43, 6, 59, '这些话是耶稣在迦百农会堂里教训人说的。'),
('CUV', '约翰福音', 43, 6, 60, '他的门徒中有好些人听见了，就说：这话甚难，谁能听呢？'),
('CUV', '约翰福音', 43, 6, 61, '耶稣心里知道门徒为这话议论，就对他们说：这话是叫你们厌弃（原文是跌倒）么？'),
('CUV', '约翰福音', 43, 6, 62, '倘或你们看见人子升到他原来所在之处，怎么样呢？'),
('CUV', '约翰福音', 43, 6, 63, '叫人活著的乃是灵，肉体是无益的。我对你们所说的话就是灵，就是生命。'),
('CUV', '约翰福音', 43, 6, 64, '只是你们中间有不信的人。耶稣从起头就知道谁不信他，谁要卖他。'),
('CUV', '约翰福音', 43, 6, 65, '耶稣又说：所以我对你们说过，若不是蒙我父的恩赐，没有人能到我这里来。'),
('CUV', '约翰福音', 43, 6, 66, '从此，他门徒中多有退去的，不再和他同行。'),
('CUV', '约翰福音', 43, 6, 67, '耶稣就对那十二个门徒说：你们也要去么？'),
('CUV', '约翰福音', 43, 6, 68, '西门彼得回答说：主阿，你有永生之道，我们还归从谁呢？'),
('CUV', '约翰福音', 43, 6, 69, '我们已经信了，又知道你是神的圣者。'),
('CUV', '约翰福音', 43, 6, 70, '耶稣说：我不是拣选了你们十二个门徒么？但你们中间有一个是魔鬼。'),
('CUV', '约翰福音', 43, 6, 71, '耶稣这话是指著加略人西门的儿子犹大说的；他本是十二个门徒里的一个，后来要卖耶稣的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 7, 1, '这事以后，耶稣在加利利游行，不愿在犹太游行，因为犹太人想要杀他。'),
('CUV', '约翰福音', 43, 7, 2, '当时犹太人的住棚节近了。'),
('CUV', '约翰福音', 43, 7, 3, '耶稣的弟兄就对他说：你离开这里上犹太去罢，叫你的门徒也看见你所行的事。'),
('CUV', '约翰福音', 43, 7, 4, '人要显扬名声，没有在暗处行事的；你如果行这些事，就当将自己显明给世人看。'),
('CUV', '约翰福音', 43, 7, 5, '因为连他的弟兄说这话，是因为不信他。'),
('CUV', '约翰福音', 43, 7, 6, '耶稣就对他们说：我的时候还没有到；你们的时候常是方便的。'),
('CUV', '约翰福音', 43, 7, 7, '世人不能恨你们，却是恨我，因为我指证他们所做的事是恶的。'),
('CUV', '约翰福音', 43, 7, 8, '你们上去过节罢，我现在不上去过这节，因为我的时候还没有满。'),
('CUV', '约翰福音', 43, 7, 9, '耶稣说了这话，仍旧住在加利利。'),
('CUV', '约翰福音', 43, 7, 10, '但他弟兄上去以后，他也上去过节，不是明去，似乎是暗去的。'),
('CUV', '约翰福音', 43, 7, 11, '正在节期，犹太人寻找耶稣，说：他在那里？'),
('CUV', '约翰福音', 43, 7, 12, '众人为他纷纷议论，有的说：他是好人。有的说：不然，他是迷惑众人的。'),
('CUV', '约翰福音', 43, 7, 13, '只是没有人明明的讲论他，因为怕犹太人。'),
('CUV', '约翰福音', 43, 7, 14, '到了节期，耶稣上殿里去教训人。'),
('CUV', '约翰福音', 43, 7, 15, '犹太人就希奇，说：这个人没有学过，怎么明白书呢？'),
('CUV', '约翰福音', 43, 7, 16, '耶稣说：我的教训不是我自己的，乃是那差我来者的。'),
('CUV', '约翰福音', 43, 7, 17, '人若立志遵著他的旨意行，就必晓得这教训或是出于神，或是我凭著自己说的。'),
('CUV', '约翰福音', 43, 7, 18, '人凭著自己说，是求自己的荣耀；惟有求那差他来者的荣耀，这人是真的，在他心里没有不义。'),
('CUV', '约翰福音', 43, 7, 19, '摩西岂不是传律法给你们么？你们却没有一个人守律法。为甚么想要杀我呢？'),
('CUV', '约翰福音', 43, 7, 20, '众人回答说：你是被鬼附著了！谁想要杀你？'),
('CUV', '约翰福音', 43, 7, 21, '耶稣说：我做了一件事，你们都以为希奇。'),
('CUV', '约翰福音', 43, 7, 22, '摩西传割礼给你们（其实不是从摩西起的，乃是从祖先起的），因此你们也在安息日给人行割礼。'),
('CUV', '约翰福音', 43, 7, 23, '人若在安息日受割礼，免得违背摩西的律法，我在安息日叫一个人全然好了，你们就向我生气么？'),
('CUV', '约翰福音', 43, 7, 24, '不可按外貌断定是非，总要按公平断定是非。'),
('CUV', '约翰福音', 43, 7, 25, '耶路撒冷人中有的说：这不是他们想要杀的人么？'),
('CUV', '约翰福音', 43, 7, 26, '你看他还明明的讲道，他们也不向他说甚么，难道官长真知道这是基督么？'),
('CUV', '约翰福音', 43, 7, 27, '然而，我们知道这个人从那里来；只是基督来的时候，没有人知道他从那里来。'),
('CUV', '约翰福音', 43, 7, 28, '那时，耶稣在殿里教训人，大声说：你们也知道我，也知道我从那里来；我来并不是由于自己。但那差我来的是真的。你们不认识他，'),
('CUV', '约翰福音', 43, 7, 29, '我却认识他；因为我是从他来的，他也是差了我来。'),
('CUV', '约翰福音', 43, 7, 30, '他们就想要捉拿耶稣；只是没有人下手，因为他的时候还没有到。'),
('CUV', '约翰福音', 43, 7, 31, '但众人中间有好些信他的，说：基督来的时候，他所行的神迹岂能比这人所行的更多么？'),
('CUV', '约翰福音', 43, 7, 32, '法利赛人听见众人为耶稣这样纷纷议论，祭司长和法利赛人就打发差役去捉拿他。'),
('CUV', '约翰福音', 43, 7, 33, '于是耶稣说：我还有不多的时候和你们同在，以后就回到差我来的那里去。'),
('CUV', '约翰福音', 43, 7, 34, '你们要找我，却找不著；我所在的地方你们不能到。'),
('CUV', '约翰福音', 43, 7, 35, '犹太人就彼此对问说：这人要往那里去，叫我们找不著呢？难道他要往散住希利尼中的犹太人那里去教训希利尼人么？'),
('CUV', '约翰福音', 43, 7, 36, '他说：你们要找我，却找不著；我所在的地方，你们不能到，这话是甚么意思呢？'),
('CUV', '约翰福音', 43, 7, 37, '节期的末日，就是最大之日，耶稣站著高声说：人若渴了，可以到我这里来喝。'),
('CUV', '约翰福音', 43, 7, 38, '信我的人就如经上所说：从他腹中要流出活水的江河来。'),
('CUV', '约翰福音', 43, 7, 39, '耶稣这话是指著信他之人要受圣灵说的。那时还没有赐下圣灵来，因为耶稣尚未得著荣耀。'),
('CUV', '约翰福音', 43, 7, 40, '众人听见这话，有的说：这真是那先知。'),
('CUV', '约翰福音', 43, 7, 41, '有的说：这是基督。但也有的说：基督岂是从加利利出来的么？'),
('CUV', '约翰福音', 43, 7, 42, '经上岂不是说基督是大卫的后裔，从大卫本乡伯利恒出来的么？'),
('CUV', '约翰福音', 43, 7, 43, '于是众人因著耶稣起了分争。'),
('CUV', '约翰福音', 43, 7, 44, '其中有人要捉拿他，只是无人下手。'),
('CUV', '约翰福音', 43, 7, 45, '差役回到祭司长和法利赛人那里。他们对差役说；你们为甚么没有带他来呢？'),
('CUV', '约翰福音', 43, 7, 46, '差役回答说：从来没有像他这样说话的！'),
('CUV', '约翰福音', 43, 7, 47, '法利赛人说：你们也受了迷惑么？'),
('CUV', '约翰福音', 43, 7, 48, '官长或是法利赛人岂有信他的呢？'),
('CUV', '约翰福音', 43, 7, 49, '但这些不明白律法的百姓是被咒诅的！'),
('CUV', '约翰福音', 43, 7, 50, '内中有尼哥底母，就是从前去见耶稣的，对他们说：'),
('CUV', '约翰福音', 43, 7, 51, '不先听本人的口供，不知道他所做的事，难道我们的律法还定他的罪么？'),
('CUV', '约翰福音', 43, 7, 52, '他们回答说：你也是出于加利利么？你且去查考，就可知道加利利没有出过先知。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 8, 1, '于是各人都回家去了；耶稣却往橄榄山去，'),
('CUV', '约翰福音', 43, 8, 2, '清早又回到殿里。众百姓都到他那里去，他就坐下，教训他们。'),
('CUV', '约翰福音', 43, 8, 3, '文士和法利赛人带著一个行淫时被拿的妇人来，叫他站在当中，'),
('CUV', '约翰福音', 43, 8, 4, '就对耶稣说：夫子，这妇人是正行淫之时被拿的。'),
('CUV', '约翰福音', 43, 8, 5, '摩西在律法上吩咐我们把这样的妇人用石头打死。你说该把他怎么样呢？'),
('CUV', '约翰福音', 43, 8, 6, '他们说这话，乃试探耶稣，要得著告他的把柄。耶稣却弯著腰，用指头在地上画字。'),
('CUV', '约翰福音', 43, 8, 7, '他们还是不住的问他，耶稣就直起腰来，对他们说：你们中间谁是没有罪的，谁就可以先拿石头打他。'),
('CUV', '约翰福音', 43, 8, 8, '于是又弯著腰，用指头在地上画字。'),
('CUV', '约翰福音', 43, 8, 9, '他们听见这话，就从老到少，一个一个的都出去了，只剩下耶稣一人，还有那妇人仍然站在当中。'),
('CUV', '约翰福音', 43, 8, 10, '耶稣就直起腰来，对他说：妇人，那些人在那里呢？没有人定你的罪么？'),
('CUV', '约翰福音', 43, 8, 11, '他说：主阿，没有。耶稣说：我也不定你的罪。去罢，从此不要再犯罪了！'),
('CUV', '约翰福音', 43, 8, 12, '耶稣又对众人说：我是世界的光。跟从我的，就不在黑暗里走，必要得著生命的光。'),
('CUV', '约翰福音', 43, 8, 13, '法利赛人对他说：你是为自己作见证，你的见证不真。'),
('CUV', '约翰福音', 43, 8, 14, '耶稣说：我虽然为自己作见证，我的见证还是真的；因我知道我从那里来，往那里去；你们却不知道我从那里来，往那里去。'),
('CUV', '约翰福音', 43, 8, 15, '你们是以外貌（原文是凭肉身）判断人，我却不判断人。'),
('CUV', '约翰福音', 43, 8, 16, '就是判断人，我的判断也是真的；因为不是我独自在这里，还有差我来的父与我同在。'),
('CUV', '约翰福音', 43, 8, 17, '你们的律法上也记著说：两个人的见证是真的。'),
('CUV', '约翰福音', 43, 8, 18, '我是为自己作见证，还有差我来的父也是为我作见证。'),
('CUV', '约翰福音', 43, 8, 19, '他们就问他说：你的父在那里？耶稣回答说：你们不认识我，也不认识我的父；若是认识我，也就认识我的父。'),
('CUV', '约翰福音', 43, 8, 20, '这些话是耶稣在殿里的库房、教训人时所说的，也没有人拿他，因为他的时候还没有到。'),
('CUV', '约翰福音', 43, 8, 21, '耶稣又对他们说：我要去了，你们要找我，并且你们要死在罪中。我所去的地方，你们不能到。'),
('CUV', '约翰福音', 43, 8, 22, '犹太人说：他说：我所去的地方，你们不能到，难道他要自尽么？'),
('CUV', '约翰福音', 43, 8, 23, '耶稣对他们说：你们是从下头来的，我是从上头来的；你们是属这世界的，我不是属这世界的。'),
('CUV', '约翰福音', 43, 8, 24, '所以我对你们说，你们要死在罪中。你们若不信我是基督，必要死在罪中。'),
('CUV', '约翰福音', 43, 8, 25, '他们就问他说：你是谁？耶稣对他们说：就是我从起初所告诉你们的。'),
('CUV', '约翰福音', 43, 8, 26, '我有许多事讲论你们，判断你们；但那差我来的是真的，我在他那里所听见的，我就传给世人。'),
('CUV', '约翰福音', 43, 8, 27, '他们不明白耶稣是指著父说的。'),
('CUV', '约翰福音', 43, 8, 28, '所以耶稣说：你们举起人子以后，必知道我是基督，并且知道我没有一件事是凭著自己作的。我说这些话乃是照著父所教训我的。'),
('CUV', '约翰福音', 43, 8, 29, '那差我来的是与我同在；他没有撇下我独自在这里，因为我常做他所喜悦的事。'),
('CUV', '约翰福音', 43, 8, 30, '耶稣说这话的时候，就有许多人信他。'),
('CUV', '约翰福音', 43, 8, 31, '耶稣对信他的犹太人说：你们若常常遵守我的道，就真是我的门徒；'),
('CUV', '约翰福音', 43, 8, 32, '你们必晓得真理，真理必叫你们得以自由。'),
('CUV', '约翰福音', 43, 8, 33, '他们回答说：我们是亚伯拉罕的后裔，从来没有作过谁的奴仆。你怎么说你们必得自由呢？'),
('CUV', '约翰福音', 43, 8, 34, '耶稣回答说：我实实在在的告诉你们，所有犯罪的就是罪的奴仆。'),
('CUV', '约翰福音', 43, 8, 35, '奴仆不能永远住在家里；儿子是永远住在家里。'),
('CUV', '约翰福音', 43, 8, 36, '所以天父的儿子若叫你们自由，你们就真自由了。'),
('CUV', '约翰福音', 43, 8, 37, '我知道你们是亚伯拉罕的子孙，你们却想要杀我，因为你们心里容不下我的道。'),
('CUV', '约翰福音', 43, 8, 38, '我所说的是在我父那里看见的；你们所行的是在你们的父那里听见的。'),
('CUV', '约翰福音', 43, 8, 39, '他们说：我们的父就是亚伯拉罕。耶稣说：你们若是亚伯拉罕的儿子，就必行亚伯拉罕所行的事。'),
('CUV', '约翰福音', 43, 8, 40, '我将在神那里所听见的真理告诉了你们，现在你们却想要杀我，这不是亚伯拉罕所行的事。'),
('CUV', '约翰福音', 43, 8, 41, '你们是行你们父所行的事。他们说：我们不是从淫乱生的；我们只有一位父，就是神。'),
('CUV', '约翰福音', 43, 8, 42, '耶稣说：倘若神是你们的父，你们就必爱我；因为我本是出于神，也是从神而来，并不是由著自己来，乃是他差我来。'),
('CUV', '约翰福音', 43, 8, 43, '你们为甚么不明白我的话呢？无非是因你们不能听我的道。'),
('CUV', '约翰福音', 43, 8, 44, '你们是出于你们的父魔鬼，你们父的私欲你们偏要行。他从起初是杀人的，不守真理，因他心里没有真理。他说谎是出于自己；因他本来是说谎的，也是说谎之人的父。'),
('CUV', '约翰福音', 43, 8, 45, '我将真理告诉你们，你们就因此不信我。'),
('CUV', '约翰福音', 43, 8, 46, '你们中间谁能指证我有罪呢？我既然将真理告诉你们，为甚么不信我呢？'),
('CUV', '约翰福音', 43, 8, 47, '出于神的，必听神的话；你们不听，因为你们不是出于神。'),
('CUV', '约翰福音', 43, 8, 48, '犹太人回答说：我们说你是撒玛利亚人，并且是鬼附著的，这话岂不正对么？'),
('CUV', '约翰福音', 43, 8, 49, '耶稣说：我不是鬼附著的；我尊敬我的父，你们倒轻慢我。'),
('CUV', '约翰福音', 43, 8, 50, '我不求自己的荣耀，有一位为我求荣耀、定是非的。'),
('CUV', '约翰福音', 43, 8, 51, '我实实在在的告诉你们，人若遵守我的道，就永远不见死。'),
('CUV', '约翰福音', 43, 8, 52, '犹太人对他说：现在我们知道你是鬼附著的。亚伯拉罕死了，众先知也死了，你还说：人若遵守我的道，就永远不尝死味。'),
('CUV', '约翰福音', 43, 8, 53, '难道你比我们的祖宗亚伯拉罕还大么？他死了，众先知也死了，你将自己当作甚么人呢？'),
('CUV', '约翰福音', 43, 8, 54, '耶稣回答说：我若荣耀自己，我的荣耀就算不得甚么；荣耀我的乃是我的父，就是你们所说是你们的神。'),
('CUV', '约翰福音', 43, 8, 55, '你们未曾认识他；我却认识他。我若说不认识他，我就是说谎的，像你们一样；但我认识他，也遵守他的道。'),
('CUV', '约翰福音', 43, 8, 56, '你们的祖宗亚伯拉罕欢欢喜喜的仰望我的日子，既看见了就快乐。'),
('CUV', '约翰福音', 43, 8, 57, '犹太人说：你还没有五十岁，岂见过亚伯拉罕呢？'),
('CUV', '约翰福音', 43, 8, 58, '耶稣说：我实实在在的告诉你们，还没有亚伯拉罕就有了我。'),
('CUV', '约翰福音', 43, 8, 59, '于是他们拿石头要打他；耶稣却躲藏，从殿去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 9, 1, '耶稣过去的时候，看见一个人生来是瞎眼的。'),
('CUV', '约翰福音', 43, 9, 2, '门徒问耶稣说：拉比，这人生来是瞎眼的，是谁犯了罪？是这人呢？是他父母呢？'),
('CUV', '约翰福音', 43, 9, 3, '耶稣回答说：也不是这人犯了罪，也不是他父母犯了罪，是要在他身上显出神的作为来。'),
('CUV', '约翰福音', 43, 9, 4, '趁著白日，我们必须做那差我来者的工；黑夜将到，就没有人能做工了。'),
('CUV', '约翰福音', 43, 9, 5, '我在世上的时候，是世上的光。'),
('CUV', '约翰福音', 43, 9, 6, '耶稣说了这话，就吐唾沫在地上，用唾沫和泥抹在瞎子的眼睛上，'),
('CUV', '约翰福音', 43, 9, 7, '对他说：你往西罗亚池子里去洗（西罗亚繙出来就是奉差遣）。他去一洗，回头就看见了。'),
('CUV', '约翰福音', 43, 9, 8, '他的邻舍和那素常见他是讨饭的，就说：这不是那从前坐著讨饭的人么？'),
('CUV', '约翰福音', 43, 9, 9, '有人说：是他；又有人说；不是，却是像他。他自己说：是我。'),
('CUV', '约翰福音', 43, 9, 10, '他们对他说：你的眼睛是怎么开的呢？'),
('CUV', '约翰福音', 43, 9, 11, '他回答说：有一个人，名叫耶稣，他和泥抹我的眼睛，对我说：你往西罗亚池子去洗。我去一洗，就看见了。'),
('CUV', '约翰福音', 43, 9, 12, '他们说：那个人在那里？他说：我不知道。'),
('CUV', '约翰福音', 43, 9, 13, '他们把从前瞎眼的人带到法利赛人那里。'),
('CUV', '约翰福音', 43, 9, 14, '耶稣和泥开他眼睛的日子是安息日。'),
('CUV', '约翰福音', 43, 9, 15, '法利赛人也问他是怎么得看见的。瞎子对他们说：他把泥抹在我的眼睛上，我去一洗，就看见了。'),
('CUV', '约翰福音', 43, 9, 16, '法利赛人中有的说：这个人不是从神来的，因为他不守安息日。又有人说：一个罪人怎能行这样的神迹呢？他们就起了分争。'),
('CUV', '约翰福音', 43, 9, 17, '他们又对瞎子说：他既然开了你的眼睛，你说他是怎样的人呢？他说：是个先知。'),
('CUV', '约翰福音', 43, 9, 18, '犹太人不信他从前是瞎眼，后来能看见的，等到叫了他的父母来，'),
('CUV', '约翰福音', 43, 9, 19, '问他们说：这是你们的儿子么？你们说他生来是瞎眼的，如今怎么能看见了呢？'),
('CUV', '约翰福音', 43, 9, 20, '他父母回答说：他是我们的儿子，生来就瞎眼，这是我们知道的。'),
('CUV', '约翰福音', 43, 9, 21, '至于他如今怎么能看见，我们却不知道；是谁开了他的眼睛，我们也不知道。他已经成了人，你们问他罢，他自己必能说。'),
('CUV', '约翰福音', 43, 9, 22, '他父母说这话，是怕犹太人；因为犹太人已经商议定了，若有认耶稣是基督的，要把他赶出会堂。'),
('CUV', '约翰福音', 43, 9, 23, '因此他父母说：他已经成了人，你们问他罢。'),
('CUV', '约翰福音', 43, 9, 24, '所以法利赛人第二次叫了那从前瞎眼的人来，对他说：你该将荣耀归给神，我们知道这人是个罪人。'),
('CUV', '约翰福音', 43, 9, 25, '他说：他是个罪人不是，我不知道；有一件事我知道，从前我是眼瞎的，如今能看见了。'),
('CUV', '约翰福音', 43, 9, 26, '他们就问他说：他向你做甚么？是怎么开了你的眼睛呢？'),
('CUV', '约翰福音', 43, 9, 27, '他回答说：我方才告诉你们，你们不听，为甚么又要听呢？莫非你们也要作他的门徒么？'),
('CUV', '约翰福音', 43, 9, 28, '他们就骂他说：你是他的门徒；我们是摩西的门徒。'),
('CUV', '约翰福音', 43, 9, 29, '神对摩西说话是我们知道的；只是这个人，我们不知道他从那里来！'),
('CUV', '约翰福音', 43, 9, 30, '那人回答说：他开了我的眼睛，你们竟不知道他从那里来，这真是奇怪！'),
('CUV', '约翰福音', 43, 9, 31, '我们知道神不听罪人，惟有敬奉神、遵行他旨意的，神才听他。'),
('CUV', '约翰福音', 43, 9, 32, '从创世以来，未曾听见有人把生来是瞎子的眼睛开了。'),
('CUV', '约翰福音', 43, 9, 33, '这人若不是从神来的，甚么也不能做。'),
('CUV', '约翰福音', 43, 9, 34, '他们回答说：你全然生在罪孽中，还要教训我们么？于是把他赶出去了。'),
('CUV', '约翰福音', 43, 9, 35, '耶稣听说他们把他赶出去，后来遇见他，就说：你信神的儿子么？'),
('CUV', '约翰福音', 43, 9, 36, '他回答说：主阿，谁是神的儿子，叫我信他呢？'),
('CUV', '约翰福音', 43, 9, 37, '耶稣说：你已经看见他，现在和你说话的就是他。'),
('CUV', '约翰福音', 43, 9, 38, '他说：主阿，我信！就拜耶稣。'),
('CUV', '约翰福音', 43, 9, 39, '耶稣说：我为审判到这世上来，叫不能看见的，可以看见；能看见的，反瞎了眼。'),
('CUV', '约翰福音', 43, 9, 40, '同他在那里的法利赛人听见这话，就说：难道我们也瞎了眼么？'),
('CUV', '约翰福音', 43, 9, 41, '耶稣对他们说：你们若瞎了眼，就没有罪了；但如今你们说我们能看见，所以你们的罪还在。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 10, 1, '我实实在在的告诉你们，人进羊圈，不从门进去，倒从别处爬进去，那人就是贼，就是强盗。'),
('CUV', '约翰福音', 43, 10, 2, '从门进去的，才是羊的牧人。'),
('CUV', '约翰福音', 43, 10, 3, '看门的就给他开门；羊也听他的声音。他按著名叫自己的羊，把羊领出来。'),
('CUV', '约翰福音', 43, 10, 4, '既放出自己的羊来，就在前头走，羊也跟著他，因为认得他的声音。'),
('CUV', '约翰福音', 43, 10, 5, '羊不跟著生人；因为不认得他的声音。必要逃跑。'),
('CUV', '约翰福音', 43, 10, 6, '耶稣将这比喻告诉他们，但他们不明白所说的是甚么意思。'),
('CUV', '约翰福音', 43, 10, 7, '所以，耶稣又对他们说：我实实在在的告诉你们，我就是羊的门。'),
('CUV', '约翰福音', 43, 10, 8, '凡在我以先来的都是贼，是强盗；羊却不听他们。'),
('CUV', '约翰福音', 43, 10, 9, '我就是门；凡从我进来的，必然得救，并且出入得草吃。'),
('CUV', '约翰福音', 43, 10, 10, '盗贼来，无非要偷窃，杀害，毁坏；我来了，是要叫羊（或作：人）得生命，并且得的更丰盛。'),
('CUV', '约翰福音', 43, 10, 11, '我是好牧人；好牧人为羊舍命。'),
('CUV', '约翰福音', 43, 10, 12, '若是雇工，不是牧人，羊也不是他自己的，他看见狼来，就撇下羊逃走；狼抓住羊，赶散了羊群。'),
('CUV', '约翰福音', 43, 10, 13, '雇工逃走，因他是雇工，并不顾念羊。'),
('CUV', '约翰福音', 43, 10, 14, '我是好牧人；我认识我的羊，我的羊也认识我，'),
('CUV', '约翰福音', 43, 10, 15, '正如父认识我，我也认识父一样；并且我为羊舍命。'),
('CUV', '约翰福音', 43, 10, 16, '我另外有羊，不是这圈里的；我必须领他们来，他们也要听我的声音，并且要合成一群，归一个牧人了。'),
('CUV', '约翰福音', 43, 10, 17, '我父爱我；因我将命舍去，好再取回来。'),
('CUV', '约翰福音', 43, 10, 18, '没有人夺我的命去，是我自己舍的。我有权柄舍了，也有权柄取回来。这是我从我父所受的命令。'),
('CUV', '约翰福音', 43, 10, 19, '犹太人为这些话又起了分争。'),
('CUV', '约翰福音', 43, 10, 20, '内中有好些人说：他是被鬼附著，而且疯了，为甚么听他呢？'),
('CUV', '约翰福音', 43, 10, 21, '又有人说：这不是鬼附之人所说的话。鬼岂能叫瞎子的眼睛开了呢？'),
('CUV', '约翰福音', 43, 10, 22, '在耶路撒冷有修殿节，是冬天的时候。'),
('CUV', '约翰福音', 43, 10, 23, '耶稣在殿里所罗门的廊下行走。'),
('CUV', '约翰福音', 43, 10, 24, '犹太人围著他，说：你叫我们犹疑不定到几时呢？你若是基督，就明明的告诉我们。'),
('CUV', '约翰福音', 43, 10, 25, '耶稣回答说：我已经告诉你们，你们不信。我奉我父之名所行的事可以为我作见证；'),
('CUV', '约翰福音', 43, 10, 26, '只是你们不信，因为你们不是我的羊。'),
('CUV', '约翰福音', 43, 10, 27, '我的羊听我的声音，我也认识他们，他们也跟著我。'),
('CUV', '约翰福音', 43, 10, 28, '我又赐给他们永生；他们永不灭亡，谁也不能从我手里把他们夺去。'),
('CUV', '约翰福音', 43, 10, 29, '我父把羊赐给我，他比万有都大，谁也不能从我父手里把他们夺去。'),
('CUV', '约翰福音', 43, 10, 30, '我与父原为一。'),
('CUV', '约翰福音', 43, 10, 31, '犹太人又拿起石头来要打他。'),
('CUV', '约翰福音', 43, 10, 32, '耶稣对他们说：我从父显出许多善事给你们看，你们是为那一件拿石头打我呢？'),
('CUV', '约翰福音', 43, 10, 33, '犹太人回答说：我们不是为善事拿石头打你，是为你说僭妄的话；又为你是个人，反将自己当作神。'),
('CUV', '约翰福音', 43, 10, 34, '耶稣说：你们的律法上岂不是写著我曾说你们是神么？'),
('CUV', '约翰福音', 43, 10, 35, '经上的话是不能废的；若那些承受神道的人尚且称为神，'),
('CUV', '约翰福音', 43, 10, 36, '父所分别为圣、又差到世间来的，他自称是神的儿子，你们还向他说你说僭妄的话么？'),
('CUV', '约翰福音', 43, 10, 37, '我若不行我父的事，你们就不必信我；'),
('CUV', '约翰福音', 43, 10, 38, '我若行了，你们纵然不信我，也当信这些事，叫你们又知道又明白父在我里面，我也在父里面。'),
('CUV', '约翰福音', 43, 10, 39, '他们又要拿他，他却逃出他们的手走了。'),
('CUV', '约翰福音', 43, 10, 40, '耶稣又往约但河外去，到了约翰起初施洗的地方，就住在那里。'),
('CUV', '约翰福音', 43, 10, 41, '有许多人来到他那里。他们说：约翰一件神迹没有行过，但约翰指著这人所说的一切话都是真的。'),
('CUV', '约翰福音', 43, 10, 42, '在那里，信耶稣的人就多了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 11, 1, '有一个患病的人，名叫拉撒路，住在伯大尼，就是马利亚和他姐姐马大的村庄。'),
('CUV', '约翰福音', 43, 11, 2, '这马利亚就是那用香膏抹主，又用头发擦他脚的；患病的拉撒路是他的兄弟。'),
('CUV', '约翰福音', 43, 11, 3, '他姐妹两个就打发人去见耶稣，说：主阿，你所爱的人病了。'),
('CUV', '约翰福音', 43, 11, 4, '耶稣听见，就说：这病不至于死，乃是为神的荣耀，叫神的儿子因此得荣耀。'),
('CUV', '约翰福音', 43, 11, 5, '耶稣素来爱马大和他妹子并拉撒路。'),
('CUV', '约翰福音', 43, 11, 6, '听见拉撒路病了。就在所居之地仍住了两天。'),
('CUV', '约翰福音', 43, 11, 7, '然后对门徒说：我们再往犹太去罢。'),
('CUV', '约翰福音', 43, 11, 8, '门徒说：拉比，犹太人近来要拿石头打你，你还往那里去么？'),
('CUV', '约翰福音', 43, 11, 9, '耶稣回答说：白日不是有十二小时么？人在白日走路，就不至跌倒，因为看见这世上的光。'),
('CUV', '约翰福音', 43, 11, 10, '若在黑夜走路，就必跌倒，因为他没有光。'),
('CUV', '约翰福音', 43, 11, 11, '耶稣说了这话，随后对他们说：我们的朋友拉撒路睡了，我去叫醒他。'),
('CUV', '约翰福音', 43, 11, 12, '门徒说：主阿，他若睡了，就必好了。'),
('CUV', '约翰福音', 43, 11, 13, '耶稣这话是指著他死说的，他们却以为是说照常睡了。'),
('CUV', '约翰福音', 43, 11, 14, '耶稣就明明的告诉他们说：拉撒路死了。'),
('CUV', '约翰福音', 43, 11, 15, '我没有在那里就欢喜，这是为你们的缘故，好叫你们相信。如今我们可以往他那里去罢。'),
('CUV', '约翰福音', 43, 11, 16, '多马，又称为低土马，就对那同作门徒的说：我们也去和他同死罢。'),
('CUV', '约翰福音', 43, 11, 17, '耶稣到了，就知道拉撒路在坟墓里已经四天了。'),
('CUV', '约翰福音', 43, 11, 18, '伯大尼离耶路撒冷不远，约有六里路。'),
('CUV', '约翰福音', 43, 11, 19, '有好些犹太人来看马大和马利亚，要为他们的兄弟安慰他们。'),
('CUV', '约翰福音', 43, 11, 20, '马大听见耶稣来了，就出去迎接他；马利亚却仍然坐在家里。'),
('CUV', '约翰福音', 43, 11, 21, '马大对耶稣说：主阿，你若早在这里，我兄弟必不死。'),
('CUV', '约翰福音', 43, 11, 22, '就是现在，我也知道，你无论向神求甚么，神也必赐给你。'),
('CUV', '约翰福音', 43, 11, 23, '耶稣说：你兄弟必然复活。'),
('CUV', '约翰福音', 43, 11, 24, '马大说：我知道在末日复活的时候，他必复活。'),
('CUV', '约翰福音', 43, 11, 25, '耶稣对他说：复活在我，生命也在我。信我的人虽然死了，也必复活，'),
('CUV', '约翰福音', 43, 11, 26, '凡活著信我的人必永远不死。你信这话么？'),
('CUV', '约翰福音', 43, 11, 27, '马大说：主阿，是的，我信你是基督，是神的儿子，就是那要临到世界的。'),
('CUV', '约翰福音', 43, 11, 28, '马大说了这话，就回去暗暗的叫他妹子马利亚，说：夫子来了，叫你。'),
('CUV', '约翰福音', 43, 11, 29, '马利亚听见了，就急忙起来，到耶稣那里去。'),
('CUV', '约翰福音', 43, 11, 30, '那时，耶稣还没有进村子，仍在马大迎接他的地方。'),
('CUV', '约翰福音', 43, 11, 31, '那些同马利亚在家里安慰他的犹太人，见他急忙起来出去，就跟著他，以为他要往坟墓那里去哭。'),
('CUV', '约翰福音', 43, 11, 32, '马利亚到了耶稣那里，看见他，就俯伏在他脚前，说：主阿，你若早在这里，我兄弟必不死。'),
('CUV', '约翰福音', 43, 11, 33, '耶稣看见他哭，并看见与他同来的犹太人也哭，就心里悲叹，又甚忧愁，'),
('CUV', '约翰福音', 43, 11, 34, '便说：你们把他安放在那里？他们回答说：请主来看。'),
('CUV', '约翰福音', 43, 11, 35, '耶稣哭了。'),
('CUV', '约翰福音', 43, 11, 36, '犹太人就说：你看他爱这人是何等恳切。'),
('CUV', '约翰福音', 43, 11, 37, '其中有人说：他既然开了瞎子的眼睛，岂不能叫这人不死么？'),
('CUV', '约翰福音', 43, 11, 38, '耶稣又心里悲叹，来到坟墓前；那坟墓是个洞，有一块石头挡著。'),
('CUV', '约翰福音', 43, 11, 39, '耶稣说：你们把石头挪开。那死人的姐姐马大对他说：主阿，他现在必是臭了，因为他死了已经四天了。'),
('CUV', '约翰福音', 43, 11, 40, '耶稣说：我不是对你说过，你若信，就必看见神的荣耀么？'),
('CUV', '约翰福音', 43, 11, 41, '他们就把石头挪开。耶稣举目望天，说：父阿，我感谢你，因为你已经听我。'),
('CUV', '约翰福音', 43, 11, 42, '我也知道你常听我，但我说这话是为周围站著的众人，叫他们信是你差了我来。'),
('CUV', '约翰福音', 43, 11, 43, '说了这话，就大声呼叫说：拉撒路出来！'),
('CUV', '约翰福音', 43, 11, 44, '那死人就出来了，手脚裹著布，脸上包著手巾。耶稣对他们说，解开，叫他走！'),
('CUV', '约翰福音', 43, 11, 45, '那些来看马利亚的犹太人见了耶稣所做的事，就多有信他的；'),
('CUV', '约翰福音', 43, 11, 46, '但其中也有去见法利赛人的，将耶稣所做的事告诉他们。'),
('CUV', '约翰福音', 43, 11, 47, '祭司长和法利赛人聚集公会，说：这人行好些神迹，我们怎么办呢？'),
('CUV', '约翰福音', 43, 11, 48, '若这样由著他，人人都要信他，罗马人也要来夺我们的地土和我们的百姓。'),
('CUV', '约翰福音', 43, 11, 49, '内中有一个人，名叫该亚法，本年作大祭司，对他们说：你们不知道甚么。'),
('CUV', '约翰福音', 43, 11, 50, '独不想一个人替百姓死，免得通国灭亡，就是你们的益处。'),
('CUV', '约翰福音', 43, 11, 51, '他这话不是出于自己，是因他本年作大祭司，所以预言耶稣将要替这一国死；'),
('CUV', '约翰福音', 43, 11, 52, '也不但替这一国死，并要将神四散的子民都聚集归一。'),
('CUV', '约翰福音', 43, 11, 53, '从那日起，他们就商议要杀耶稣。'),
('CUV', '约翰福音', 43, 11, 54, '所以，耶稣不再显然行在犹太人中间，就离开那里往靠近旷野的地方去，到了一座城，名叫以法莲，就在那里和门徒同住。'),
('CUV', '约翰福音', 43, 11, 55, '犹太人的逾越节近了，有许多人从乡下上耶路撒冷去，要在节前洁净自己。'),
('CUV', '约翰福音', 43, 11, 56, '他们就寻找耶稣，站在殿里彼此说：你们的意思如何，他不来过节么？'),
('CUV', '约翰福音', 43, 11, 57, '那时，祭司长和法利赛人早已吩咐说，若有人知道耶稣在那里，就要报明，好去拿他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 12, 1, '逾越节前六日，耶稣来到伯大尼，就是他叫拉撒路从死里复活之处。'),
('CUV', '约翰福音', 43, 12, 2, '有人在那里给耶稣预备筵席；马大伺候，拉撒路也在那同耶稣坐席的人中。'),
('CUV', '约翰福音', 43, 12, 3, '马利亚就拿著一斤极贵的真哪哒香膏，抹耶稣的脚，又用自己头发去擦，屋里就满了膏的香气。'),
('CUV', '约翰福音', 43, 12, 4, '有一个门徒，就是那将要卖耶稣的加略人犹大，'),
('CUV', '约翰福音', 43, 12, 5, '说：这香膏为甚么不卖三十两银子赒济穷人呢？'),
('CUV', '约翰福音', 43, 12, 6, '他说这话，并不是挂念穷人，乃因他是个贼，又带著钱囊，常取其中所存的。'),
('CUV', '约翰福音', 43, 12, 7, '耶稣说：由他罢！他是为我安葬之日存留的。'),
('CUV', '约翰福音', 43, 12, 8, '因为常有穷人和你们同在，只是你们不常有我。'),
('CUV', '约翰福音', 43, 12, 9, '有许多犹太人知道耶稣在那里，就来了，不但是为耶稣的缘故，也是要看他从死里所复活的拉撒路。'),
('CUV', '约翰福音', 43, 12, 10, '但祭司长商议连拉撒路也要杀了；'),
('CUV', '约翰福音', 43, 12, 11, '因有好些犹太人为拉撒路的缘故，回去信了耶稣。'),
('CUV', '约翰福音', 43, 12, 12, '第二天，有许多上来过节的人听见耶稣将到耶路撒冷，'),
('CUV', '约翰福音', 43, 12, 13, '就拿著棕树枝出去迎接他，喊著说：和散那！奉主名来的以色列王是应当称颂的！'),
('CUV', '约翰福音', 43, 12, 14, '耶稣得了一个驴驹，就骑上，如经上所记的说：'),
('CUV', '约翰福音', 43, 12, 15, '锡安的民（原文作女子）哪，不要惧怕！你的王骑著驴驹来了。'),
('CUV', '约翰福音', 43, 12, 16, '这些事门徒起先不明白，等到耶稣得了荣耀以后才想起这话是指著他写的，并且众人果然向他这样行了。'),
('CUV', '约翰福音', 43, 12, 17, '当耶稣呼唤拉撒路，叫他从死复活出坟墓的时候，同耶稣在那里的众人就作见证。'),
('CUV', '约翰福音', 43, 12, 18, '众人因听见耶稣行了这神迹，就去迎接他。'),
('CUV', '约翰福音', 43, 12, 19, '法利赛人彼此说：看哪，你们是徒劳无益，世人都随从他去了。'),
('CUV', '约翰福音', 43, 12, 20, '那时，上来过节礼拜的人中，有几个希利尼人。'),
('CUV', '约翰福音', 43, 12, 21, '他们来见加利利伯赛大的腓力，求他说：先生，我们愿意见耶稣。'),
('CUV', '约翰福音', 43, 12, 22, '腓力去告诉安得烈，安得烈同腓力去告诉耶稣。'),
('CUV', '约翰福音', 43, 12, 23, '耶稣说：人子得荣耀的时候到了。'),
('CUV', '约翰福音', 43, 12, 24, '我实实在在的告诉你们，一粒麦子不落在地里死了，仍旧是一粒，若是死了，就结出许多子粒来。'),
('CUV', '约翰福音', 43, 12, 25, '爱惜自己生命的，就失丧生命；在这世上恨恶自己生命的，就要保守生命到永生。'),
('CUV', '约翰福音', 43, 12, 26, '若有人服事我，就当跟从我；我在那里，服事我的人也要在那里；若有人服事我，我父必尊重他。'),
('CUV', '约翰福音', 43, 12, 27, '我现在心里忧愁，我说甚么才好呢？父阿，救我脱离这时候；但我原是为这时候来的。'),
('CUV', '约翰福音', 43, 12, 28, '父阿，愿你荣耀你的名！当时就有声音从天上来，说：我已经荣耀了我的名，还要再荣耀。'),
('CUV', '约翰福音', 43, 12, 29, '站在旁边的众人听见，就说：打雷了。还有人说：有天使对他说话。'),
('CUV', '约翰福音', 43, 12, 30, '耶稣说：这声音不是为我，是为你们来的。'),
('CUV', '约翰福音', 43, 12, 31, '现在这世界受审判，这世界的王要被赶出去。'),
('CUV', '约翰福音', 43, 12, 32, '我若从地上被举起来，就要吸引万人来归我。'),
('CUV', '约翰福音', 43, 12, 33, '耶稣这话原是指著自己将要怎样死说的。'),
('CUV', '约翰福音', 43, 12, 34, '众人回答说：我们听见律法上有话说，基督是永存的，你怎么说人子必须被举起来呢？这人子是谁呢？'),
('CUV', '约翰福音', 43, 12, 35, '耶稣对他们说：光在你们中间还有不多的时候，应当趁著有光行走，免得黑暗临到你们；那在黑暗里行走的，不知道往何处去。'),
('CUV', '约翰福音', 43, 12, 36, '你们应当趁著有光，信从这光，使你们成为光明之子。耶稣说了这话，就离开隐藏了。'),
('CUV', '约翰福音', 43, 12, 37, '他虽然在他们面前行了许多神迹，他们还是不信他。'),
('CUV', '约翰福音', 43, 12, 38, '这是要应验先知以赛亚的话，说：主阿，我们所传的有谁信呢？主的膀臂向谁显露呢？'),
('CUV', '约翰福音', 43, 12, 39, '他们所以不能信，因为以赛亚又说：'),
('CUV', '约翰福音', 43, 12, 40, '主叫他们瞎了眼，硬了心，免得他们眼睛看见，心里明白，回转过来，我就医治他们。'),
('CUV', '约翰福音', 43, 12, 41, '以赛亚因为看见他的荣耀，就指著他说这话。'),
('CUV', '约翰福音', 43, 12, 42, '虽然如此，官长中却有好些信他的，只因法利赛人的缘故，就不承认，恐怕被赶出会堂。'),
('CUV', '约翰福音', 43, 12, 43, '这是因他们爱人的荣耀过于爱神的荣耀。'),
('CUV', '约翰福音', 43, 12, 44, '耶稣大声说：信我的，不是信我，乃是信那差我来的。'),
('CUV', '约翰福音', 43, 12, 45, '人看见我，就是看见那差我来的。'),
('CUV', '约翰福音', 43, 12, 46, '我到世上来，乃是光，叫凡信我的，不住在黑暗里。'),
('CUV', '约翰福音', 43, 12, 47, '若有人听见我的话不遵守，我不审判他。我来本不是要审判世界，乃是要拯救世界。'),
('CUV', '约翰福音', 43, 12, 48, '弃绝我、不领受我话的人，有审判他的─就是我所讲的道在末日要审判他。'),
('CUV', '约翰福音', 43, 12, 49, '因为我没有凭著自己讲，惟有差我来的父已经给我命令，叫我说甚么，讲甚么。'),
('CUV', '约翰福音', 43, 12, 50, '我也知道他的命令就是永生。故此，我所讲的话正是照著父对我所说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 13, 1, '逾越节以前，耶稣知道自己离世归父的时候到了。他既然爱世间属自己的人，就爱他们到底。'),
('CUV', '约翰福音', 43, 13, 2, '吃晚饭的时候，魔鬼已将卖耶稣的意思放在西门的儿子加略人犹大心里。'),
('CUV', '约翰福音', 43, 13, 3, '耶稣知道父已将万有交在他手里，且知道自己是从神出来的，又要归到神那里去，'),
('CUV', '约翰福音', 43, 13, 4, '就离席站起来，脱了衣服，拿一条手巾束腰，'),
('CUV', '约翰福音', 43, 13, 5, '随后把水倒在盆里，就洗门徒的脚，并用自己所束的手巾擦干。'),
('CUV', '约翰福音', 43, 13, 6, '挨到西门彼得，彼得对他说：主阿，你洗我的脚么？'),
('CUV', '约翰福音', 43, 13, 7, '耶稣回答说：我所做的，你如今不知道，后来必明白。'),
('CUV', '约翰福音', 43, 13, 8, '彼得说：你永不可洗我的脚！耶稣说：我若不洗你，你就与我无分了。'),
('CUV', '约翰福音', 43, 13, 9, '西门彼得说：主阿，不但我的脚，连手和头也要洗。'),
('CUV', '约翰福音', 43, 13, 10, '耶稣说：凡洗过澡的人，只要把脚一洗，全身就干净了。你们是干净的，然而不都是干净的。'),
('CUV', '约翰福音', 43, 13, 11, '耶稣原知道要卖他的是谁，所以说：你们不都是干净的。'),
('CUV', '约翰福音', 43, 13, 12, '耶稣洗完了他们的脚，就穿上衣服，又坐下，对他们说：我向你们所做的，你们明白么？'),
('CUV', '约翰福音', 43, 13, 13, '你们称呼我夫子，称呼我主，你们说的不错，我本来是。'),
('CUV', '约翰福音', 43, 13, 14, '我是你们的主，你们的夫子，尚且洗你们的脚，你们也当彼此洗脚。'),
('CUV', '约翰福音', 43, 13, 15, '我给你们做了榜样，叫你们照著我向你们所做的去做。'),
('CUV', '约翰福音', 43, 13, 16, '我实实在在的告诉你们，仆人不能大于主人，差人也不能大于差他的人。'),
('CUV', '约翰福音', 43, 13, 17, '你们既知道这事，若是去行就有福了。'),
('CUV', '约翰福音', 43, 13, 18, '我这话不是指著你们众人说的，我知道我所拣选的是谁。现在要应验经上的话，说：同我吃饭的人用脚踢我。'),
('CUV', '约翰福音', 43, 13, 19, '如今事情还没有成就，我要先告诉你们，叫你们到事情成就的时候可以信我是基督。'),
('CUV', '约翰福音', 43, 13, 20, '我实实在在的告诉你们，有人接待我所差遣的，就是接待我；接待我，就是接待那差遣我的。'),
('CUV', '约翰福音', 43, 13, 21, '耶稣说了这话，心里忧愁，就明说：我实实在在的告诉你们，你们中间有一个人要卖我了。'),
('CUV', '约翰福音', 43, 13, 22, '门徒彼此对看，猜不透所说的是谁。'),
('CUV', '约翰福音', 43, 13, 23, '有一个门徒，是耶稣所爱的，侧身挨近耶稣的怀里。'),
('CUV', '约翰福音', 43, 13, 24, '西门彼得点头对他说：你告诉我们，主是指著谁说的。'),
('CUV', '约翰福音', 43, 13, 25, '那门徒便就势靠著耶稣的胸膛，问他说：主阿，是谁呢？'),
('CUV', '约翰福音', 43, 13, 26, '耶稣回答说：我蘸一点饼给谁，就是谁。耶稣就蘸了一点饼，递给加略人西门的儿子犹大。'),
('CUV', '约翰福音', 43, 13, 27, '他吃了以后，撒但就入了他的心。耶稣便对他说：你所做的，快做罢！'),
('CUV', '约翰福音', 43, 13, 28, '同席的人没有一个知道是为甚么对他说这话。'),
('CUV', '约翰福音', 43, 13, 29, '有人因犹大带著钱囊，以为耶稣是对他说：你去买我们过节所应用的东西，或是叫他拿甚么赒济穷人。'),
('CUV', '约翰福音', 43, 13, 30, '犹大受了那点饼，立刻就出去。那时候是夜间了。'),
('CUV', '约翰福音', 43, 13, 31, '他既出去，耶稣就说：如今人子得了荣耀，神在人子身上也得了荣耀。'),
('CUV', '约翰福音', 43, 13, 32, '神要因自己荣耀人子，并且要快快的荣耀他。'),
('CUV', '约翰福音', 43, 13, 33, '小子们，我还有不多的时候与你们同在；后来你们要找我，但我所去的地方你们不能到。这话我曾对犹太人说过，如今也照样对你们说。'),
('CUV', '约翰福音', 43, 13, 34, '我赐给你们一条新命令，乃是叫你们彼此相爱；我怎样爱你们，你们也要怎样相爱。'),
('CUV', '约翰福音', 43, 13, 35, '你们若有彼此相爱的心，众人因此就认出你们是我的门徒了。'),
('CUV', '约翰福音', 43, 13, 36, '西门彼得问耶稣说：主往那里去？耶稣回答说：我所去的地方，你现在不能跟我去，后来却要跟我去。'),
('CUV', '约翰福音', 43, 13, 37, '彼得说：主阿，我为甚么现在不能跟你去？我愿意为你舍命！'),
('CUV', '约翰福音', 43, 13, 38, '耶稣说：你愿意为我舍命么？我实实在在的告诉你，鸡叫以先，你要三次不认我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 14, 1, '你们心里不要忧愁；你们信神，也当信我。'),
('CUV', '约翰福音', 43, 14, 2, '在我父的家里有许多住处；若是没有，我就早已告诉你们了。我去原是为你们预备地方去。'),
('CUV', '约翰福音', 43, 14, 3, '我若去为你们预备了地方，就必再来接你们到我那里去，我在那里，叫你们也在那里。'),
('CUV', '约翰福音', 43, 14, 4, '我往那里去，你们知道；那条路，你们也知道（有古卷作：我往那里去，你们知道那条路）。'),
('CUV', '约翰福音', 43, 14, 5, '多马对他说：主阿，我们不知道你往那里去，怎么知道那条路呢？'),
('CUV', '约翰福音', 43, 14, 6, '耶稣说我就是道路、真理、生命；若不藉著我，没有人能到父那里去。'),
('CUV', '约翰福音', 43, 14, 7, '你们若认识我，也就认识我的父。从今以后，你们认识他，并且已经看见他。'),
('CUV', '约翰福音', 43, 14, 8, '腓力对他说：求主将父显给我们看，我们就知足了。'),
('CUV', '约翰福音', 43, 14, 9, '耶稣对他说：腓力，我与你们同在这样长久，你还不认识我么？人看见了我，就是看见了父；你怎么说将父显给我们看呢？'),
('CUV', '约翰福音', 43, 14, 10, '我在父里面，父在我里面，你不信么？我对你们所说的话，不是凭著自己说的，乃是住在我里面的父做他自己的事。'),
('CUV', '约翰福音', 43, 14, 11, '你们当信我，我在父里面，父在我里面；即或不信，也当因我所做的事信我。'),
('CUV', '约翰福音', 43, 14, 12, '我实实在在的告诉你们，我所做的事，信我的人也要做，并且要做比这更大的事，因为我往父那里去。'),
('CUV', '约翰福音', 43, 14, 13, '你们奉我的名无论求甚么，我必成就，叫父因儿子得荣耀。'),
('CUV', '约翰福音', 43, 14, 14, '你们若奉我的名求甚么，我必成就。'),
('CUV', '约翰福音', 43, 14, 15, '你们若爱我，就必遵守我的命令。'),
('CUV', '约翰福音', 43, 14, 16, '我要求父，父就另外赐给你们一位保惠师（或作：训慰师；下同），叫他永远与你们同在，'),
('CUV', '约翰福音', 43, 14, 17, '就是真理的圣灵，乃世人不能接受的；因为不见他，也不认识他。你们却认识他，因他常与你们同在，也要在你们里面。'),
('CUV', '约翰福音', 43, 14, 18, '我不撇下你们为孤儿，我必到你们这里来。'),
('CUV', '约翰福音', 43, 14, 19, '还有不多的时候，世人不再看见我，你们却看见我；因为我活著，你们也要活著。'),
('CUV', '约翰福音', 43, 14, 20, '到那日，你们就知道我在父里面，你们在我里面，我也在你们里面。'),
('CUV', '约翰福音', 43, 14, 21, '有了我的命令又遵守的，这人就是爱我的；爱我的必蒙我父爱他，我也要爱他，并且要向他显现。'),
('CUV', '约翰福音', 43, 14, 22, '犹大（不是加略人犹大）问耶稣说：主阿，为甚么要向我们显现，不向世人显现呢？'),
('CUV', '约翰福音', 43, 14, 23, '耶稣回答说：人若爱我，就必遵守我的道；我父也必爱他，并且我们要到他那里去，与他同住。'),
('CUV', '约翰福音', 43, 14, 24, '不爱我的人就不遵守我的道。你们所听见的道不是我的，乃是差我来之父的道。'),
('CUV', '约翰福音', 43, 14, 25, '我还与你们同住的时候，已将这些话对你们说了。'),
('CUV', '约翰福音', 43, 14, 26, '但保惠师，就是父因我的名所要差来的圣灵，他要将一切的事指教你们，并且要叫你们想起我对你们所说的一切话。'),
('CUV', '约翰福音', 43, 14, 27, '我留下平安给你们；我将我的平安赐给你们。我所赐的，不像世人所赐的。你们心里不要忧愁，也不要胆怯。'),
('CUV', '约翰福音', 43, 14, 28, '你们听见我对你们说了，我去还要到你们这里来。你们若爱我，因我到父那里去，就必喜乐，因为父是比我大的。'),
('CUV', '约翰福音', 43, 14, 29, '现在事情还没有成就，我预先告诉你们，叫你们到事情成就的时候就可以信。'),
('CUV', '约翰福音', 43, 14, 30, '以后我不再和你们多说话，因为这世界的王将到。他在我里面是毫无所有；'),
('CUV', '约翰福音', 43, 14, 31, '但要叫世人知道我爱父，并且父怎样吩咐我，我就怎样行。起来，我们走罢！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 15, 1, '我是真葡萄树，我父是栽培的人。'),
('CUV', '约翰福音', 43, 15, 2, '凡属我不结果子的枝子，他就剪去；凡结果子的，他就修理干净，使枝子结果子更多。'),
('CUV', '约翰福音', 43, 15, 3, '现在你们因我讲给你们的道，已经干净了。'),
('CUV', '约翰福音', 43, 15, 4, '你们要常在我里面，我也常在你们里面。枝子若不常在葡萄树上，自己就不能结果子；你们若不常在我里面，也是这样。'),
('CUV', '约翰福音', 43, 15, 5, '我是葡萄树，你们是枝子。常在我里面的，我也常在他里面，这人就多结果子；因为离了我，你们就不能做甚么。'),
('CUV', '约翰福音', 43, 15, 6, '人若不常在我里面，就像枝子丢在外面枯干，人拾起来，扔在火里烧了。'),
('CUV', '约翰福音', 43, 15, 7, '你们若常在我里面，我的话也常在你们里面，凡你们所愿意的，祈求，就给你们成就。'),
('CUV', '约翰福音', 43, 15, 8, '你们多结果子，我父就因此得荣耀，你们也就是我的门徒了。'),
('CUV', '约翰福音', 43, 15, 9, '我爱你们，正如父爱我一样；你们要常在我的爱里。'),
('CUV', '约翰福音', 43, 15, 10, '你们若遵守我的命令，就常在我的爱里，正如我遵守了我父的命令，常在他的爱里。'),
('CUV', '约翰福音', 43, 15, 11, '这些事我已经对你们说了，是要叫我的喜乐存在你们心里，并叫你们的喜乐可以满足。'),
('CUV', '约翰福音', 43, 15, 12, '你们要彼此相爱，像我爱你们一样；这就是我的命令。'),
('CUV', '约翰福音', 43, 15, 13, '人为朋友舍命，人的爱心没有比这个大的。'),
('CUV', '约翰福音', 43, 15, 14, '你们若遵行我所吩咐的，就是我的朋友了。'),
('CUV', '约翰福音', 43, 15, 15, '以后我不再称你们为仆人，因仆人不知道主人所做的事。我乃称你们为朋友；因我从我父所听见的，已经都告诉你们了。'),
('CUV', '约翰福音', 43, 15, 16, '不是你们拣选了我，是我拣选了你们，并且分派你们去结果子，叫你们的果子常存，使你们奉我的名，无论向父求甚么，他就赐给你们。'),
('CUV', '约翰福音', 43, 15, 17, '我这样吩咐你们，是要叫你们彼此相爱。'),
('CUV', '约翰福音', 43, 15, 18, '世人若恨你们，你们知道（或作：该知道），恨你们以先已经恨我了。'),
('CUV', '约翰福音', 43, 15, 19, '你们若属世界，世界必爱属自己的；只因你们不属世界，乃是我从世界中拣选了你们，所以世界就恨你们。'),
('CUV', '约翰福音', 43, 15, 20, '你们要记念我从前对你们所说的话：仆人不能大于主人。他们若逼迫了我，也要逼迫你们；若遵守了我的话，也要遵守你们的话。'),
('CUV', '约翰福音', 43, 15, 21, '但他们因我的名要向你们行这一切的事，因为他们不认识那差我来的。'),
('CUV', '约翰福音', 43, 15, 22, '我若没有来教训他们，他们就没有罪；但如今他们的罪无可推诿了。'),
('CUV', '约翰福音', 43, 15, 23, '恨我的，也恨我的父。'),
('CUV', '约翰福音', 43, 15, 24, '我若没有在他们中间行过别人未曾行的事，他们就没有罪；但如今连我与我的父，他们也看见也恨恶了。'),
('CUV', '约翰福音', 43, 15, 25, '这要应验他们律法上所写的话，说：他们无故的恨我。'),
('CUV', '约翰福音', 43, 15, 26, '但我要从父那里差保惠师来，就是从父出来真理的圣灵；他来了，就要为我作见证。'),
('CUV', '约翰福音', 43, 15, 27, '你们也要作见证，因为你们从起头就与我同在。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 16, 1, '我已将这些事告诉你们，使你们不至于跌倒。'),
('CUV', '约翰福音', 43, 16, 2, '人要把你们赶出会堂，并且时候将到，凡杀你们的就以为是事奉神。'),
('CUV', '约翰福音', 43, 16, 3, '他们这样行，是因未曾认识父，也未曾认识我。'),
('CUV', '约翰福音', 43, 16, 4, '我将这事告诉你们，是叫你们到了时候可以想起我对你们说过了。我起先没有将这事告诉你们，因为我与你们同在。'),
('CUV', '约翰福音', 43, 16, 5, '现今我往差我来的父那里去，你们中间并没有人问我：你往那里去？'),
('CUV', '约翰福音', 43, 16, 6, '只因我将这事告诉你们，你们就满心忧愁。'),
('CUV', '约翰福音', 43, 16, 7, '然而，我将真情告诉你们，我去是与你们有益的；我若不去，保惠师就不到你们这里来；我若去，就差他来。'),
('CUV', '约翰福音', 43, 16, 8, '他既来了，就要叫世人为罪、为义、为审判，自己责备自己。'),
('CUV', '约翰福音', 43, 16, 9, '为罪，是因他们不信我；'),
('CUV', '约翰福音', 43, 16, 10, '为义，是因我往父那里去，你们就不再见我；'),
('CUV', '约翰福音', 43, 16, 11, '为审判，是因这世界的王受了审判。'),
('CUV', '约翰福音', 43, 16, 12, '我还有好些事要告诉你们，但你们现在担当不了（或作：不能领会）。'),
('CUV', '约翰福音', 43, 16, 13, '只等真理的圣灵来了，他要引导你们明白（原文作进入）一切的真理；因为他不是凭自己说的，乃是把他所听见的都说出来，并要把将来的事告诉你们。'),
('CUV', '约翰福音', 43, 16, 14, '他要荣耀我，因为他要将受于我的告诉你们。'),
('CUV', '约翰福音', 43, 16, 15, '凡父所有的，都是我的；所以我说，他要将受于我的告诉你们。'),
('CUV', '约翰福音', 43, 16, 16, '等不多时，你们就不得见我；再等不多时，你们还要见我。'),
('CUV', '约翰福音', 43, 16, 17, '有几个门徒就彼此说：他对我们说：等不多时，你们就不得见我；再等不多时，你们还要见我；又说：因我往父那里去。这是甚么意思呢？'),
('CUV', '约翰福音', 43, 16, 18, '门徒彼此说：他说等不多时到底是甚么意思呢？我们不明白他所说的话。'),
('CUV', '约翰福音', 43, 16, 19, '耶稣看出他们要问他，就说：我说等不多时，你们就不得见我；再等不多时，你们还要见我，你们为这话彼此相问么？'),
('CUV', '约翰福音', 43, 16, 20, '我实实在在的告诉你们，你们将要痛哭、哀号，世人倒要喜乐；你们将要忧愁，然而你们的忧愁要变为喜乐。'),
('CUV', '约翰福音', 43, 16, 21, '妇人生产的时候就忧愁，因为他的时候到了；既生了孩子，就不再记念那苦楚，因为欢喜世上生了一个人。'),
('CUV', '约翰福音', 43, 16, 22, '你们现在也是忧愁，但我要再见你们，你们的心就喜乐了；这喜乐也没有人能夺去。'),
('CUV', '约翰福音', 43, 16, 23, '到那日，你们甚么也就不问我了。我实实在在的告诉你们，你们若向父求甚么，他必因我的名赐给你们。'),
('CUV', '约翰福音', 43, 16, 24, '向来你们没有奉我的名求甚么，如今你们求，就必得著，叫你们的喜乐可以满足。'),
('CUV', '约翰福音', 43, 16, 25, '这些事，我是用比喻对你们说的；时候将到，我不再用比喻对你们说，乃要将父明明的告诉你们。'),
('CUV', '约翰福音', 43, 16, 26, '到那日，你们要奉我的名祈求；我并不对你们说，我要为你们求父。'),
('CUV', '约翰福音', 43, 16, 27, '父自己爱你们；因为你们已经爱我，又信我是从父出来的。'),
('CUV', '约翰福音', 43, 16, 28, '我从父出来，到了世界；我又离开世界，往父那里去。'),
('CUV', '约翰福音', 43, 16, 29, '门徒说：如今你是明说，并不用比喻了。'),
('CUV', '约翰福音', 43, 16, 30, '现在我们晓得你凡事都知道，也不用人问你，因此我们信你是从神出来的。'),
('CUV', '约翰福音', 43, 16, 31, '耶稣说：现在你们信么？'),
('CUV', '约翰福音', 43, 16, 32, '看哪，时候将到，且是已经到了，你们要分散，各归自己的地方去，留下我独自一人；其实我不是独自一人，因为有父与我同在。'),
('CUV', '约翰福音', 43, 16, 33, '我将这些事告诉你们，是要叫你们在我里面有平安。在世上，你们有苦难；但你们可以放心，我已经胜了世界。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 17, 1, '耶稣说了这话，就举目望天，说：父阿，时候到了，愿你荣耀你的儿子，使儿子也荣耀你；'),
('CUV', '约翰福音', 43, 17, 2, '正如你曾赐给他权柄管理凡有血气的，叫他将永生赐给你所赐给他的人。'),
('CUV', '约翰福音', 43, 17, 3, '认识你─独一的真神，并且认识你所差来的耶稣基督，这就是永生。'),
('CUV', '约翰福音', 43, 17, 4, '我在地上已经荣耀你，你所托付我的事，我已成全了。'),
('CUV', '约翰福音', 43, 17, 5, '父阿，现在求你使我同你享荣耀，就是未有世界以先，我同你所有的荣耀。'),
('CUV', '约翰福音', 43, 17, 6, '你从世上赐给我的人，我已将你的名显明与他们。他们本是你的，你将他们赐给我，他们也遵守了你的道。'),
('CUV', '约翰福音', 43, 17, 7, '如今他们知道，凡你所赐给我的，都是从你那里来的；'),
('CUV', '约翰福音', 43, 17, 8, '因为你所赐给我的道，我已经赐给他们，他们也领受了，又确实知道，我是从你出来的，并且信你差了我来。'),
('CUV', '约翰福音', 43, 17, 9, '我为他们祈求，不为世人祈求，却为你所赐给我的人祈求，因他们本是你的。'),
('CUV', '约翰福音', 43, 17, 10, '凡是我的，都是你的；你的也是我的，并且我因他们得了荣耀。'),
('CUV', '约翰福音', 43, 17, 11, '从今以后，我不在世上，他们却在世上；我往你那里去。圣父阿，求你因你所赐给我的名保守他们，叫他们合而为一像我们一样。'),
('CUV', '约翰福音', 43, 17, 12, '我与他们同在的时候，因你所赐给我的名保守了他们，我也护卫了他们；其中除了那灭亡之子，没有一个灭亡的，好叫经上的话得应验。'),
('CUV', '约翰福音', 43, 17, 13, '现在我往你那里去，我还在世上说这话，是叫他们心里充满我的喜乐。'),
('CUV', '约翰福音', 43, 17, 14, '我已将你的道赐给他们。世界又恨他们；因为他们不属世界，正如我不属世界一样。'),
('CUV', '约翰福音', 43, 17, 15, '我不求你叫他们离开世界，只求你保守他们脱离那恶者（或作：脱离罪恶）。'),
('CUV', '约翰福音', 43, 17, 16, '他们不属世界，正如我不属世界一样。'),
('CUV', '约翰福音', 43, 17, 17, '求你用真理使他们成圣；你的道就是真理。'),
('CUV', '约翰福音', 43, 17, 18, '你怎样差我到世上，我也照样差他们到世上。'),
('CUV', '约翰福音', 43, 17, 19, '我为他们的缘故，自己分别为圣，叫他们也因真理成圣。'),
('CUV', '约翰福音', 43, 17, 20, '我不但为这些人祈求，也为那些因他们的话信我的人祈求，'),
('CUV', '约翰福音', 43, 17, 21, '使他们都合而为一。正如你父在我里面，我在你里面，使他们也在我们里面，叫世人可以信你差了我来。'),
('CUV', '约翰福音', 43, 17, 22, '你所赐给我的荣耀，我已赐给他们，使他们合而为一，像我们合而为一。'),
('CUV', '约翰福音', 43, 17, 23, '我在他们里面，你在我里面，使他们完完全全的合而为一，叫世人知道你差了我来，也知道你爱他们如同爱我一样。'),
('CUV', '约翰福音', 43, 17, 24, '父阿，我在那里，愿你所赐给我的人也同我在那里，叫他们看见你所赐给我的荣耀；因为创立世界以前，你已经爱我了。'),
('CUV', '约翰福音', 43, 17, 25, '公义的父阿，世人未曾认识你，我却认识你；这些人也知道你差了我来。'),
('CUV', '约翰福音', 43, 17, 26, '我已将你的名指示他们，还要指示他们，使你所爱我的爱在他们里面，我也在他们里面。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 18, 1, '耶稣说了这话，就同门徒出去，过了汲沦溪。在那里有一个园子，他和门徒进去了。'),
('CUV', '约翰福音', 43, 18, 2, '卖耶稣的犹大也知道那地方，因为耶稣和门徒屡次上那里去聚集。'),
('CUV', '约翰福音', 43, 18, 3, '犹大领了一队兵，和祭司长并法利赛人的差役，拿著灯笼、火把、兵器，就来到园里。'),
('CUV', '约翰福音', 43, 18, 4, '耶稣知道将要临到自己的一切事，就出来对他们说：你们找谁？'),
('CUV', '约翰福音', 43, 18, 5, '他们回答说：找拿撒勒人耶稣。耶稣说：我就是。卖他的犹大也同他们站在那里。'),
('CUV', '约翰福音', 43, 18, 6, '耶稣一说我就是，他们就退后倒在地上。'),
('CUV', '约翰福音', 43, 18, 7, '他又问他们说：你们找谁？他们说：找拿撒勒人耶稣。'),
('CUV', '约翰福音', 43, 18, 8, '耶稣说：我已经告诉你们，我就是。你们若找我，就让这些人去罢。'),
('CUV', '约翰福音', 43, 18, 9, '这要应验耶稣从前的话，说：你所赐给我的人，我没有失落一个。'),
('CUV', '约翰福音', 43, 18, 10, '西门彼得带著一把刀，就拔出来，将大祭司的仆人砍了一刀，削掉他的右耳；那仆人名叫马勒古。'),
('CUV', '约翰福音', 43, 18, 11, '耶稣就对彼得说：收刀入鞘罢，我父所给我的那杯，我岂可不喝呢？'),
('CUV', '约翰福音', 43, 18, 12, '那队兵和千夫长，并犹太人的差役就拿住耶稣，把他捆绑了，'),
('CUV', '约翰福音', 43, 18, 13, '先带到亚那面前，因为亚那是本年作大祭司该亚法的岳父。'),
('CUV', '约翰福音', 43, 18, 14, '这该亚法就是从前向犹太人发议论说一个人替百姓死是有益的那位。'),
('CUV', '约翰福音', 43, 18, 15, '西门彼得跟著耶稣，还有一个门徒跟著。那门徒是大祭司所认识的，他就同耶稣进了大祭司的院子。'),
('CUV', '约翰福音', 43, 18, 16, '彼得却站在门外。大祭司所认识的那个门徒出来，和看门的使女说了一声，就领彼得进去。'),
('CUV', '约翰福音', 43, 18, 17, '那看门的使女对彼得说：你不也是这人的门徒么？他说：我不是。'),
('CUV', '约翰福音', 43, 18, 18, '仆人和差役因为天冷，就生了炭火，站在那里烤火；彼得也同他们站著烤火。'),
('CUV', '约翰福音', 43, 18, 19, '大祭司就以耶稣的门徒和他的教训盘问他。'),
('CUV', '约翰福音', 43, 18, 20, '耶稣回答说：我从来是明明的对世人说话。我常在会堂和殿里，就是犹太人聚集的地方教训人；我在暗地里并没有说甚么。'),
('CUV', '约翰福音', 43, 18, 21, '你为甚么问我呢？可以问那听见的人，我对他们说的是甚么；我所说的，他们都知道。'),
('CUV', '约翰福音', 43, 18, 22, '耶稣说了这话，旁边站著的一个差役用手掌打他，说：你这样回答大祭司么？'),
('CUV', '约翰福音', 43, 18, 23, '耶稣说：我若说的不是，你可以指证那不是；我若说的是，你为甚么打我呢？'),
('CUV', '约翰福音', 43, 18, 24, '亚那就把耶稣解到大祭司该亚法那里，仍是捆著解去的。'),
('CUV', '约翰福音', 43, 18, 25, '西门彼得正站著烤火，有人对他说：你不也是他的门徒么？彼得不承认，说：我不是。'),
('CUV', '约翰福音', 43, 18, 26, '有大祭司的一个仆人，是彼得削掉耳朵那人的亲属，说：我不是看见你同他在园子里么？'),
('CUV', '约翰福音', 43, 18, 27, '彼得又不承认。立时鸡就叫了。'),
('CUV', '约翰福音', 43, 18, 28, '众人将耶稣从该亚法那里往衙门内解去，那时天还早。他们自己却不进衙门，恐怕染了污秽，不能吃逾越节的筵席。'),
('CUV', '约翰福音', 43, 18, 29, '彼拉多就出来，到他们那里，说：你们告这人是为甚么事呢？'),
('CUV', '约翰福音', 43, 18, 30, '他们回答说：这人若不是作恶的，我们就不把他交给你。'),
('CUV', '约翰福音', 43, 18, 31, '彼拉多说：你们自己带他去，按著你们的律法审问他罢。犹太人说：我们没有杀人的权柄。'),
('CUV', '约翰福音', 43, 18, 32, '这要应验耶稣所说自己将要怎样死的话了。'),
('CUV', '约翰福音', 43, 18, 33, '彼拉多又进了衙门，叫耶稣来，对他说：你是犹太人的王么？'),
('CUV', '约翰福音', 43, 18, 34, '耶稣回答说：这话是你自己说的，还是别人论我对你说的呢？'),
('CUV', '约翰福音', 43, 18, 35, '彼拉多说：我岂是犹太人呢？你本国的人和祭司长把你交给我。你做了甚么事呢？'),
('CUV', '约翰福音', 43, 18, 36, '耶稣回答说：我的国不属这世界；我的国若属这世界，我的臣仆必要争战，使我不至于被交给犹太人。只是我的国不属这世界。'),
('CUV', '约翰福音', 43, 18, 37, '彼拉多就对他说：这样，你是王么？耶稣回答说：你说我是王。我为此而生，也为此来到世间，特为给真理作见证。凡属真理的人就听我的话。'),
('CUV', '约翰福音', 43, 18, 38, '彼拉多说：真理是甚么呢？说了这话，又出来到犹太人那里，对他们说：我查不出他有甚么罪来。'),
('CUV', '约翰福音', 43, 18, 39, '但你们有个规矩，在逾越节要我给你们释放一个人，你们要我给你们释放犹太人的王么？'),
('CUV', '约翰福音', 43, 18, 40, '他们又喊著说：不要这人，要巴拉巴！这巴拉巴是个强盗。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 19, 1, '当下彼拉多将耶稣鞭打了。'),
('CUV', '约翰福音', 43, 19, 2, '兵丁用荆棘编作冠冕戴在他头上，给他穿上紫袍，'),
('CUV', '约翰福音', 43, 19, 3, '又挨近他，说：恭喜，犹太人的王阿！他们就用手掌打他。'),
('CUV', '约翰福音', 43, 19, 4, '彼拉多又出来对众人说：我带他出来见你们，叫你们知道我查不出他有甚么罪来。'),
('CUV', '约翰福音', 43, 19, 5, '耶稣出来，戴著荆棘冠冕，穿著紫袍。彼拉多对他们说：你们看这个人！'),
('CUV', '约翰福音', 43, 19, 6, '祭司长和差役看见他，就喊著说：钉他十字架！钉他十字架！彼拉多说：你们自己把他钉十字架罢！我查不出他有甚么罪来。'),
('CUV', '约翰福音', 43, 19, 7, '犹太人回答说：我们有律法，按那律法，他是该死的，因他以自己为神的儿子。'),
('CUV', '约翰福音', 43, 19, 8, '彼拉多听见这话，越发害怕，'),
('CUV', '约翰福音', 43, 19, 9, '又进衙门，对耶稣说：你是那里来的？耶稣却不回答。'),
('CUV', '约翰福音', 43, 19, 10, '彼拉多说：你不对我说话么？你岂不知我有权柄释放你，也有权柄把你钉十字架么？'),
('CUV', '约翰福音', 43, 19, 11, '耶稣回答说：若不是从上头赐给你的，你就毫无权柄办我。所以，把我交给你的那人罪更重了。'),
('CUV', '约翰福音', 43, 19, 12, '从此，彼拉多想要释放耶稣，无奈犹太人喊著说：你若释放这个人，就不是该撒的忠臣（原文作朋友）。凡以自己为王的，就是背叛该撒了。'),
('CUV', '约翰福音', 43, 19, 13, '彼拉多听见这话，就带耶稣出来，到了一个地方，名叫铺华石处，希伯来话叫厄巴大，就在那里坐堂。'),
('CUV', '约翰福音', 43, 19, 14, '那日是预备逾越节的日子，约有午正。彼拉多对犹太人说：看哪，这是你们的王！'),
('CUV', '约翰福音', 43, 19, 15, '他们喊著说：除掉他！除掉他！钉他在十字架上！彼拉多说：我可以把你们的王钉十字架么？祭司长回答说：除了该撒，我们没有王。'),
('CUV', '约翰福音', 43, 19, 16, '于是彼拉多将耶稣交给他们去钉十字架。'),
('CUV', '约翰福音', 43, 19, 17, '他们就把耶稣带了去。耶稣背著自己的十字架出来，到了一个地方，名叫髑髅地，希伯来话叫各各他。'),
('CUV', '约翰福音', 43, 19, 18, '他们就在那里钉他在十字架上，还有两个人和他一同钉著，一边一个，耶稣在中间。'),
('CUV', '约翰福音', 43, 19, 19, '彼拉多又用牌子写了一个名号，安在十字架上，写的是：犹太人的王，拿撒勒人耶稣。'),
('CUV', '约翰福音', 43, 19, 20, '有许多犹太人念这名号；因为耶稣被钉十字架的地方与城相近，并且是用希伯来、罗马、希利尼三样文字写的。'),
('CUV', '约翰福音', 43, 19, 21, '犹太人的祭司长就对彼拉多说：不要写犹太人的王，要写他自己说：我是犹太人的王。'),
('CUV', '约翰福音', 43, 19, 22, '彼拉多说：我所写的，我已经写上了。'),
('CUV', '约翰福音', 43, 19, 23, '兵丁既然将耶稣钉在十字架上，就拿他的衣服分为四分，每兵一分；又拿他的里衣，这件里衣原来没有缝儿，是上下一片织成的。'),
('CUV', '约翰福音', 43, 19, 24, '他们就彼此说：我们不要撕开，只要拈阄，看谁得著。这要应验经上的话说：他们分了我的外衣，为我的里衣拈阄。兵丁果然做了这事。'),
('CUV', '约翰福音', 43, 19, 25, '站在耶稣十字架旁边的，有他母亲与他母亲的姊妹，并革罗罢的妻子马利亚，和抹大拉的马利亚。'),
('CUV', '约翰福音', 43, 19, 26, '耶稣见母亲和他所爱的那门徒站在旁边，就对他母亲说：母亲（原文作妇人），看，你的儿子！'),
('CUV', '约翰福音', 43, 19, 27, '又对那门徒说：看，你的母亲！从此，那门徒就接他到自己家里去了。'),
('CUV', '约翰福音', 43, 19, 28, '这事以后，耶稣知道各样的事已经成了，为要使经上的话应验，就说：我渴了。'),
('CUV', '约翰福音', 43, 19, 29, '有一个器皿盛满了醋，放在那里；他们就拿海绒蘸满了醋，绑在牛膝草上，送到他口。'),
('CUV', '约翰福音', 43, 19, 30, '耶稣尝（原文作受）了那醋，就说：成了！便低下头，将灵魂交付神了。'),
('CUV', '约翰福音', 43, 19, 31, '犹太人因这日是预备日，又因那安息日是个大日，就求彼拉多叫人打断他们的腿，把他们拿去，免得尸首当安息日留在十字架上。'),
('CUV', '约翰福音', 43, 19, 32, '于是兵丁来，把头一个人的腿，并与耶稣同钉第二个人的腿，都打断了。'),
('CUV', '约翰福音', 43, 19, 33, '只是来到耶稣那里，见他已经死了，就不打断他的腿。'),
('CUV', '约翰福音', 43, 19, 34, '惟有一个兵拿枪扎他的肋旁，随即有血和水流出来。'),
('CUV', '约翰福音', 43, 19, 35, '看见这事的那人就作见证─他的见证也是真的，并且他知道自己所说的是真的─叫你们也可以信。'),
('CUV', '约翰福音', 43, 19, 36, '这些事成了，为要应验经上的话说：他的骨头一根也不可折断。'),
('CUV', '约翰福音', 43, 19, 37, '经上又有一句说：他们要仰望自己所扎的人。'),
('CUV', '约翰福音', 43, 19, 38, '这些事以后，有亚利马太人约瑟，是耶稣的门徒，只因怕犹太人，就暗暗的作门徒。他来求彼拉多，要把耶稣的身体领去。彼拉多允准，他就把耶稣的身体领去了。'),
('CUV', '约翰福音', 43, 19, 39, '又有尼哥底母，就是先前夜里去见耶稣的，带著没药和沉香约有一百斤前来。'),
('CUV', '约翰福音', 43, 19, 40, '他们就照犹太人殡葬的规矩，把耶稣的身体用细麻布加上香料裹好了。'),
('CUV', '约翰福音', 43, 19, 41, '在耶稣钉十字架的地方有一个园子，园子里有一座新坟墓，是从来没有葬过人的。'),
('CUV', '约翰福音', 43, 19, 42, '只因是犹太人的预备日，又因那坟墓近，他们就把耶稣安放在那里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 20, 1, '七日的第一日清早，天还黑的时候，抹大拉的马利亚来到坟墓那里，看见石头从坟墓挪开了，'),
('CUV', '约翰福音', 43, 20, 2, '就跑来见西门彼得和耶稣所爱的那个门徒，对他们说：有人把主从坟墓里挪了去，我们不知道放在那里。'),
('CUV', '约翰福音', 43, 20, 3, '彼得和那门徒就出来，往坟墓那里去。'),
('CUV', '约翰福音', 43, 20, 4, '两个人同跑，那门徒比彼得跑的更快，先到了坟墓，'),
('CUV', '约翰福音', 43, 20, 5, '低头往里看，就见细麻布还放在那里，只是没有进去。'),
('CUV', '约翰福音', 43, 20, 6, '西门彼得随后也到了，进坟墓里去，就看见细麻布还放在那里，'),
('CUV', '约翰福音', 43, 20, 7, '又看见耶稣的裹头巾没有和细麻布放在一处，是另在一处卷著。'),
('CUV', '约翰福音', 43, 20, 8, '先到坟墓的那门徒也进去，看见就信了。'),
('CUV', '约翰福音', 43, 20, 9, '因为他们还不明白圣经的意思，就是耶稣必要从死里复活。'),
('CUV', '约翰福音', 43, 20, 10, '于是两个门徒回自己的住处去了。'),
('CUV', '约翰福音', 43, 20, 11, '马利亚却站在坟墓外面哭。哭的时候，低头往坟墓里看，'),
('CUV', '约翰福音', 43, 20, 12, '就见两个天使，穿著白衣，在安放耶稣身体的地方坐著，一个在头，一个在脚。'),
('CUV', '约翰福音', 43, 20, 13, '天使对他说：妇人，你为甚么哭？他说：因为有人把我主挪了去，我不知道放在那里。'),
('CUV', '约翰福音', 43, 20, 14, '说了这话，就转过身来，看见耶稣站在那里，却不知道是耶稣。'),
('CUV', '约翰福音', 43, 20, 15, '耶稣问他说：妇人，为甚么哭？你找谁呢？马利亚以为是看园的，就对他说：先生，若是你把他移了去，请告诉我，你把他放在那里，我便去取他。'),
('CUV', '约翰福音', 43, 20, 16, '耶稣说：马利亚。马利亚就转过来，用希伯来话对他说：拉波尼！（拉波尼就是夫子的意思。）'),
('CUV', '约翰福音', 43, 20, 17, '耶稣说：不要摸我，因我还没有升上去见我的父。你往我弟兄那里去，告诉他们说，我要升上去见我的父，也是你们的父，见我的神，也是你们的神。'),
('CUV', '约翰福音', 43, 20, 18, '抹大拉的马利亚就去告诉门徒说：我已经看见了主。他又将主对他说的这话告诉他们。'),
('CUV', '约翰福音', 43, 20, 19, '那日（就是七日的第一日）晚上，门徒所在的地方，因怕犹太人，门都关了。耶稣来，站在当中，对他们说：愿你们平安！'),
('CUV', '约翰福音', 43, 20, 20, '说了这话，就把手和肋旁指给他们看。门徒看见主，就喜乐了。'),
('CUV', '约翰福音', 43, 20, 21, '耶稣又对他们说：愿你们平安！父怎样差遣了我，我也照样差遣你们。'),
('CUV', '约翰福音', 43, 20, 22, '说了这话，就向他们吹一口气，说：你们受圣灵！'),
('CUV', '约翰福音', 43, 20, 23, '你们赦免谁的罪，谁的罪就赦免了；你们留下谁的罪，谁的罪就留下了。'),
('CUV', '约翰福音', 43, 20, 24, '那十二个门徒中，有称为低土马的多马；耶稣来的时候，他没有和他们同在。'),
('CUV', '约翰福音', 43, 20, 25, '那些门徒就对他说：我们已经看见主了。多马却说：我非看见他手上的钉痕，用指头探入那钉痕，又用手探入他的肋旁，我总不信。'),
('CUV', '约翰福音', 43, 20, 26, '过了八日，门徒又在屋里，多马也和他们同在，门都关了。耶稣来，站在当中说：愿你们平安！'),
('CUV', '约翰福音', 43, 20, 27, '就对多马说：伸过你的指头来，摸（原文是看）我的手；伸出你的手来，探入我的肋旁。不要疑惑，总要信。'),
('CUV', '约翰福音', 43, 20, 28, '多马说：我的主！我的神！'),
('CUV', '约翰福音', 43, 20, 29, '耶稣对他说：你因看见了我才信；那没有看见就信的有福了。'),
('CUV', '约翰福音', 43, 20, 30, '耶稣在门徒面前另外行了许多神迹，没有记在这书上。'),
('CUV', '约翰福音', 43, 20, 31, '但记这些事要叫你们信耶稣是基督，是神的儿子，并且叫你们信了他，就可以因他的名得生命。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰福音', 43, 21, 1, '这些事以后，耶稣在提比哩亚海边又向门徒显现。他怎样显现记在下面：'),
('CUV', '约翰福音', 43, 21, 2, '有西门彼得和称为低土马的多马，并加利利的迦拿人拿但业，还有西庇太的两个儿子，又有两个门徒，都在一处。'),
('CUV', '约翰福音', 43, 21, 3, '西门彼得对他们说：我打鱼去。他们说：我们也和你同去。他们就出去，上了船；那一夜并没有打著甚么。'),
('CUV', '约翰福音', 43, 21, 4, '天将亮的时候，耶稣站在岸上，门徒却不知道是耶稣。'),
('CUV', '约翰福音', 43, 21, 5, '耶稣就对他们说：小子！你们有吃的没有？他们回答说：没有。'),
('CUV', '约翰福音', 43, 21, 6, '耶稣说：你们把网撒在船的右边，就必得著。他们便撒下网去，竟拉不上来了，因为鱼甚多。'),
('CUV', '约翰福音', 43, 21, 7, '耶稣所爱的那门徒对彼得说：是主！那时西门彼得赤著身子，一听见是主，就束上一件外衣，跳在海里。'),
('CUV', '约翰福音', 43, 21, 8, '其余的门徒离岸不远，约有二百肘（古代以肘为尺，一肘约有今时尺半），就在小船上把那网鱼拉过来。'),
('CUV', '约翰福音', 43, 21, 9, '他们上了岸，就看见那里有炭火，上面有鱼，又有饼。'),
('CUV', '约翰福音', 43, 21, 10, '耶稣对他们说：把刚才打的鱼拿几条来。'),
('CUV', '约翰福音', 43, 21, 11, '西门彼得就去（或作：上船），把网拉到岸上。那网满了大鱼，共一百五十三条；鱼虽这样多，网却没有破。'),
('CUV', '约翰福音', 43, 21, 12, '耶稣说：你们来吃早饭。门徒中没有一个敢问他：你是谁？因为知道是主。'),
('CUV', '约翰福音', 43, 21, 13, '耶稣就来拿饼和鱼给他们。'),
('CUV', '约翰福音', 43, 21, 14, '耶稣从死里复活以后，向门徒显现，这是第三次。'),
('CUV', '约翰福音', 43, 21, 15, '他们吃完了早饭，耶稣对西门彼得说：约翰（在太16：17称约拿）的儿子西门，你爱我比这些更深么？彼得说：主阿，是的，你知道我爱你。耶稣对他说：你喂养我的小羊。'),
('CUV', '约翰福音', 43, 21, 16, '耶稣第二次又对他说：约翰的儿子西门，你爱我么？彼得说：主阿，是的，你知道我爱你。耶稣说：你牧养我的羊。'),
('CUV', '约翰福音', 43, 21, 17, '第三次对他说：约翰的儿子西门﹐你爱我么？彼得因为耶稣第三次对他说你爱我么，就忧愁，对耶稣说：主阿，你是无所不知的；你知道我爱你。耶稣说：你喂养我的羊。'),
('CUV', '约翰福音', 43, 21, 18, '我实实在在的告诉你，你年少的时候，自己束上带子，随意往来；但年老的时候，你要伸出手来，别人要把你束上，带你到不愿意去的地方。'),
('CUV', '约翰福音', 43, 21, 19, '耶稣说这话是指著彼得要怎样死，荣耀神。说了这话，就对他说：你跟从我罢！'),
('CUV', '约翰福音', 43, 21, 20, '彼得转过来，看见耶稣所爱的那门徒跟著，就是在晚饭的时候，靠著耶稣胸膛说：主阿，卖你的是谁？的那门徒。'),
('CUV', '约翰福音', 43, 21, 21, '彼得看见他，就问耶稣说：主阿，这人将来如何？'),
('CUV', '约翰福音', 43, 21, 22, '耶稣对他说：我若要他等到我来的时候，与你何干？你跟从我罢！'),
('CUV', '约翰福音', 43, 21, 23, '于是这话传在弟兄中间，说那门徒不死。其实，耶稣不是说他不死，乃是说：我若要他等到我来的时候，与你何干？'),
('CUV', '约翰福音', 43, 21, 24, '为这些事作见证，并且记载这些事的就是这门徒；我们也知道他的见证是真的。'),
('CUV', '约翰福音', 43, 21, 25, '耶稣所行的事还有许多，若是一一的都写出来，我想，所写的书就是世界也容不下了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 1, 1, '提阿非罗阿，我已经作了前书，论到耶稣开头一切所行所教训的，'),
('CUV', '使徒行传', 44, 1, 2, '直到他藉著圣灵吩咐所拣选的使徒，以后被接上升的日子为止。'),
('CUV', '使徒行传', 44, 1, 3, '他受害之后，用许多的凭据将自己活活的显给使徒看，四十天之久向他们显现，讲说神国的事。'),
('CUV', '使徒行传', 44, 1, 4, '耶稣和他们聚集的时候，嘱咐他们说：不要离开耶路撒冷，要等候父所应许的，就是你们听见我说过的。'),
('CUV', '使徒行传', 44, 1, 5, '约翰是用水施洗，但不多几日，你们要受圣灵的洗。'),
('CUV', '使徒行传', 44, 1, 6, '他们聚集的时候，问耶稣说：主阿，你复兴以色列国就在这时候么？'),
('CUV', '使徒行传', 44, 1, 7, '耶稣对他们说：父凭著自己的权柄所定的时候、日期，不是你们可以知道的。'),
('CUV', '使徒行传', 44, 1, 8, '但圣灵降临在你们身上，你们就必得著能力，并要在耶路撒冷、犹太全地，和撒玛利亚，直到地极，作我的见证。'),
('CUV', '使徒行传', 44, 1, 9, '说了这话，他们正看的时候，他就被取上升，有一朵云彩把他接去，便看不见他了。'),
('CUV', '使徒行传', 44, 1, 10, '当他往上去，他们定睛望天的时候，忽然有两个人身穿白衣，站在旁边，说：'),
('CUV', '使徒行传', 44, 1, 11, '加利利人哪，你们为甚么站著望天呢？这离开你们被接升天的耶稣，你们见他怎样往天上去，他还要怎样来。'),
('CUV', '使徒行传', 44, 1, 12, '有一座山，名叫橄榄山，离耶路撒冷不远，约有安息日可走的路程。当下，门徒从那里回耶路撒冷去，'),
('CUV', '使徒行传', 44, 1, 13, '进了城，就上了所住的一间楼房；在那里有彼得、约翰、雅各、安得烈、腓力、多马、巴多罗买、马太、亚勒腓的儿子雅各、奋锐党的西门，和雅各的儿子（或作：兄弟）犹大。'),
('CUV', '使徒行传', 44, 1, 14, '这些人同著几个妇人和耶稣的母亲马利亚，并耶稣的弟兄，都同心合意的恒切祷告。'),
('CUV', '使徒行传', 44, 1, 15, '那时，有许多人聚会，约有一百二十名，彼得就在弟兄中间站起来，说：'),
('CUV', '使徒行传', 44, 1, 16, '弟兄们！圣灵藉大卫的口，在圣经上预言领人捉拿耶稣的犹大，这话是必须应验的。'),
('CUV', '使徒行传', 44, 1, 17, '他本来列在我们数中，并且在使徒的职任上得了一分。'),
('CUV', '使徒行传', 44, 1, 18, '这人用他作恶的工价买了一块田，以后身子仆倒，肚腹崩裂，肠子都流出来。'),
('CUV', '使徒行传', 44, 1, 19, '住在耶路撒冷的众人都知道这事，所以按著他们那里的话给那块田起名叫亚革大马，就是血田的意思。'),
('CUV', '使徒行传', 44, 1, 20, '因为诗篇上写著，说：愿他的住处变为荒场，无人在内居住；又说：愿别人得他的职分。'),
('CUV', '使徒行传', 44, 1, 21, '所以，主耶稣在我们中间始终出入的时候，'),
('CUV', '使徒行传', 44, 1, 22, '就是从约翰施洗起，直到主离开我们被接上升的日子为止，必须从那常与我们作伴的人中立一位与我们同作耶稣复活的见证。'),
('CUV', '使徒行传', 44, 1, 23, '于是选举两个人，就是那叫作巴撒巴，又称呼犹士都的约瑟，和马提亚。'),
('CUV', '使徒行传', 44, 1, 24, '众人就祷告说：主阿，你知道万人的心，求你从这两个人中，指明你所拣选的是谁，叫他得这使徒的位分。这位分犹大已经丢弃，往自己的地方去了。'),
('CUV', '使徒行传', 44, 1, 25, 'a'),
('CUV', '使徒行传', 44, 1, 26, '于是众人为他们摇签，摇出马提亚来；他就和十一个使徒同列。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 2, 1, '五旬节到了，门徒都聚集在一处。'),
('CUV', '使徒行传', 44, 2, 2, '忽然，从天上有响声下来，好像一阵大风吹过，充满了他们所坐的屋子，'),
('CUV', '使徒行传', 44, 2, 3, '又有舌头如火燄显现出来，分开落在他们各人头上。'),
('CUV', '使徒行传', 44, 2, 4, '他们就都被圣灵充满，按著圣灵所赐的口才说起别国的话来。'),
('CUV', '使徒行传', 44, 2, 5, '那时，有虔诚的犹太人从天下各国来，住在耶路撒冷。'),
('CUV', '使徒行传', 44, 2, 6, '这声音一响，众人都来聚集，各人听见门徒用众人的乡谈说话，就甚纳闷；'),
('CUV', '使徒行传', 44, 2, 7, '都惊讶希奇说：看哪，这说话的不都是加利利人么？'),
('CUV', '使徒行传', 44, 2, 8, '我们各人，怎么听见他们说我们生来所用的乡谈呢？'),
('CUV', '使徒行传', 44, 2, 9, '我们帕提亚人、玛代人、以拦人，和住在米所波大米、犹太、加帕多家、本都、亚西亚、'),
('CUV', '使徒行传', 44, 2, 10, '弗吕家、旁非利亚、埃及的人，并靠近古利奈的吕彼亚一带地方的人，从罗马来的客旅中，或是犹太人，或是进犹太教的人，'),
('CUV', '使徒行传', 44, 2, 11, '革哩底和亚拉伯人，都听见他们用我们的乡谈，讲说神的大作为。'),
('CUV', '使徒行传', 44, 2, 12, '众人就都惊讶猜疑，彼此说：这是甚么意思呢？'),
('CUV', '使徒行传', 44, 2, 13, '还有人讥诮说：他们无非是新酒灌满了。'),
('CUV', '使徒行传', 44, 2, 14, '彼得和十一个使徒站起，高声说：犹太人和一切住在耶路撒冷的人哪，这件事你们当知道，也当侧耳听我的话。'),
('CUV', '使徒行传', 44, 2, 15, '你们想这些人是醉了；其实不是醉了，因为时候刚到巳初。'),
('CUV', '使徒行传', 44, 2, 16, '这正是先知约珥所说的：'),
('CUV', '使徒行传', 44, 2, 17, '神说：在末后的日子，我要将我的灵浇灌凡有血气的。你们的儿女要说预言；你们的少年人要见异象；老年人要做异梦。'),
('CUV', '使徒行传', 44, 2, 18, '在那些日子，我要将我的灵浇灌我的仆人和使女，他们就要说预言。'),
('CUV', '使徒行传', 44, 2, 19, '在天上、我要显出奇事；在地下、我要显出神迹；有血，有火，有烟雾。'),
('CUV', '使徒行传', 44, 2, 20, '日头要变为黑暗，月亮要变为血；这都在主大而明显的日子未到以前。'),
('CUV', '使徒行传', 44, 2, 21, '到那时候，凡求告主名的，就必得救。'),
('CUV', '使徒行传', 44, 2, 22, '以色列人哪，请听我的话：神藉著拿撒勒人耶稣在你们中间施行异能、奇事神迹，将他证明出来，这是你们自己知道的。'),
('CUV', '使徒行传', 44, 2, 23, '他既按著神的定旨先见被交与人，你们就藉著无法之人的手，把他钉在十字架上，杀了。'),
('CUV', '使徒行传', 44, 2, 24, '神却将死的痛苦解释了，叫他复活，因为他原不能被死拘禁。'),
('CUV', '使徒行传', 44, 2, 25, '大卫指著他说：我看见主常在我眼前；他在我右边，叫我不至于摇动。'),
('CUV', '使徒行传', 44, 2, 26, '所以，我心里欢喜，我的灵（原文是舌）快乐；并且我的肉身要安居在指望中。'),
('CUV', '使徒行传', 44, 2, 27, '因你必不将我的灵魂撇在阴间，也不叫你的圣者见朽坏。'),
('CUV', '使徒行传', 44, 2, 28, '你已将生命的道路指示我，必叫我因见你的面（或作：叫我在你面前）得著满足的快乐。'),
('CUV', '使徒行传', 44, 2, 29, '弟兄们！先祖大卫的事，我可以明明的对你们说：他死了，也葬埋了，并且他的坟墓直到今日还在我们这里。'),
('CUV', '使徒行传', 44, 2, 30, '大卫既是先知，又晓得神曾向他起誓，要从他的后裔中立一位坐在他的宝座上，'),
('CUV', '使徒行传', 44, 2, 31, '就预先看明这事，讲论基督复活说：他的灵魂不撇在阴间；他的肉身也不见朽坏。'),
('CUV', '使徒行传', 44, 2, 32, '这耶稣，神已经叫他复活了，我们都为这事作见证。'),
('CUV', '使徒行传', 44, 2, 33, '他既被神的右手高举（或作：他既高举在神的右边），又从父受了所应许的圣灵，就把你们所看见所听见的，浇灌下来。'),
('CUV', '使徒行传', 44, 2, 34, '大卫并没有升到天上，但自己说：主对我主说：你坐在我的右边，'),
('CUV', '使徒行传', 44, 2, 35, '等我使你仇敌作你的脚凳。'),
('CUV', '使徒行传', 44, 2, 36, '故此，以色列全家当确实的知道，你们钉在十字架上的这位耶稣，神已经立他为主，为基督了。'),
('CUV', '使徒行传', 44, 2, 37, '众人听见这话，觉得扎心，就对彼得和其余的使徒说：弟兄们，我们当怎样行？'),
('CUV', '使徒行传', 44, 2, 38, '彼得说：你们各人要悔改，奉耶稣基督的名受洗，叫你们的罪得赦，就必领受所赐的圣灵；'),
('CUV', '使徒行传', 44, 2, 39, '因为这应许是给你们和你们的儿女，并一切在远方的人，就是主─我们神所召来的。'),
('CUV', '使徒行传', 44, 2, 40, '彼得还用许多话作见证，劝勉他们说：你们当救自己脱离这弯曲的世代。'),
('CUV', '使徒行传', 44, 2, 41, '于是领受他话的人就受了洗。那一天，门徒约添了三千人，'),
('CUV', '使徒行传', 44, 2, 42, '都恒心遵守使徒的教训，彼此交接，擘饼，祈祷。'),
('CUV', '使徒行传', 44, 2, 43, '众人都惧怕；使徒又行了许多奇事神迹。'),
('CUV', '使徒行传', 44, 2, 44, '信的人都在一处，凡物公用；'),
('CUV', '使徒行传', 44, 2, 45, '并且卖了田产，家业，照各人所需用的分给各人。'),
('CUV', '使徒行传', 44, 2, 46, '他们天天同心合意恒切的在殿里，且在家中擘饼，存著欢喜、诚实的心用饭，'),
('CUV', '使徒行传', 44, 2, 47, '赞美神，得众民的喜爱。主将得救的人天天加给他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 3, 1, '申初祷告的时候，彼得、约翰上圣殿去。'),
('CUV', '使徒行传', 44, 3, 2, '有一个人，生来是瘸腿的，天天被人抬来，放在殿的一个门口，那门名叫美门，要求进殿的人赒济。'),
('CUV', '使徒行传', 44, 3, 3, '他看见彼得、约翰将要进殿，就求他们赒济。'),
('CUV', '使徒行传', 44, 3, 4, '彼得约翰定睛看他；彼得说：你看我们！'),
('CUV', '使徒行传', 44, 3, 5, '那人就留意看他们，指望得著甚么。'),
('CUV', '使徒行传', 44, 3, 6, '彼得说：金银我都没有，只把我所有的给你：我奉拿撒勒人耶稣基督的名，叫你起来行走！'),
('CUV', '使徒行传', 44, 3, 7, '于是拉著他的右手，扶他起来；他的脚和踝子骨立刻健壮了，'),
('CUV', '使徒行传', 44, 3, 8, '就跳起来，站著，又行走，同他们进了殿，走著，跳著，赞美神。'),
('CUV', '使徒行传', 44, 3, 9, '百姓都看见他行走，赞美神；'),
('CUV', '使徒行传', 44, 3, 10, '认得他是那素常坐在殿的美门口求赒济的，就因他所遇著的事满心希奇、惊讶。'),
('CUV', '使徒行传', 44, 3, 11, '那人正在称为所罗门的廊下，拉著彼得、约翰；众百姓一齐跑到他们那里，很觉希奇。'),
('CUV', '使徒行传', 44, 3, 12, '彼得看见，就对百姓说：以色列人哪，为甚么把这事当作希奇呢？为甚么定睛看我们，以为我们凭自己的能力和虔诚使这人行走呢？'),
('CUV', '使徒行传', 44, 3, 13, '亚伯拉罕、以撒、雅各的神，就是我们列祖的神，已经荣耀了他的仆人（或作：儿子）耶稣；你们却把他交付彼拉多。彼拉多定意要释放他，你们竟在彼拉多面前弃绝了他。'),
('CUV', '使徒行传', 44, 3, 14, '你们弃绝了那圣洁公义者，反求著释放一个凶手给你们。'),
('CUV', '使徒行传', 44, 3, 15, '你们杀了那生命的主，神却叫他从死里复活了；我们都是为这事作见证。'),
('CUV', '使徒行传', 44, 3, 16, '我们因信他的名，他的名便叫你们所看见所认识的这人健壮了；正是他所赐的信心，叫这人在你们众人面前全然好了。'),
('CUV', '使徒行传', 44, 3, 17, '弟兄们，我晓得你们做这事是出于不知，你们的官长也是如此。'),
('CUV', '使徒行传', 44, 3, 18, '但神曾藉众先知的口，预言基督将要受害，就这样应验了。'),
('CUV', '使徒行传', 44, 3, 19, '所以，你们当悔改归正，使你们的罪得以涂抹，这样，那安舒的日子就必从主面前来到；'),
('CUV', '使徒行传', 44, 3, 20, '主也必差遣所预定给你们的基督耶稣降临。'),
('CUV', '使徒行传', 44, 3, 21, '天必留他，等到万物复兴的时候，就是神从创世以来、藉著圣先知的口所说的。'),
('CUV', '使徒行传', 44, 3, 22, '摩西曾说：主─神要从你们弟兄中间给你们兴起一位先知像我，凡他向你们所说的，你们都要听从。'),
('CUV', '使徒行传', 44, 3, 23, '凡不听从那先知的，必要从民中全然灭绝。'),
('CUV', '使徒行传', 44, 3, 24, '从撒母耳以来的众先知，凡说预言的，也都说到这些日子。'),
('CUV', '使徒行传', 44, 3, 25, '你们是先知的子孙，也承受神与你们祖宗所立的约，就是对亚伯拉罕说：地上万族都要因你的后裔得福。'),
('CUV', '使徒行传', 44, 3, 26, '神既兴起他的仆人，（或作：儿子），就先差他到你们这里来，赐福给你们，叫你们各人回转，离开罪恶。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 4, 1, '使徒对百姓说话的时候，祭司们和守殿官，并撒都该人忽然来了。'),
('CUV', '使徒行传', 44, 4, 2, '因他们教训百姓，本著耶稣，传说死人复活，就很烦恼，'),
('CUV', '使徒行传', 44, 4, 3, '于是下手拿住他们；因为天已经晚了，就把他们押到第二天。'),
('CUV', '使徒行传', 44, 4, 4, '但听道之人有许多信的，男丁数目约到五千。'),
('CUV', '使徒行传', 44, 4, 5, '第二天，官府、长老，和文士在耶路撒冷聚会，'),
('CUV', '使徒行传', 44, 4, 6, '又有大祭司亚那和该亚法、约翰、亚力山大，并大祭司的亲族都在那里，'),
('CUV', '使徒行传', 44, 4, 7, '叫使徒站在当中，就问他们说：你们用甚么能力，奉谁的名做这事呢？'),
('CUV', '使徒行传', 44, 4, 8, '那时彼得被圣灵充满，对他们说：'),
('CUV', '使徒行传', 44, 4, 9, '治民的官府和长老阿，倘若今日因为在残疾人身上所行的善事查问我们他是怎么得了痊愈，'),
('CUV', '使徒行传', 44, 4, 10, '你们众人和以色列百姓都当知道，站在你们面前的这人得痊愈是因你们所钉十字架、神叫他从死里复活的拿撒勒人耶稣基督的名。'),
('CUV', '使徒行传', 44, 4, 11, '他是你们匠人所弃的石头，已成了房角的头块石头。'),
('CUV', '使徒行传', 44, 4, 12, '除他以外，别无拯救；因为在天下人间，没有赐下别的名，我们可以靠著得救。'),
('CUV', '使徒行传', 44, 4, 13, '他们见彼得、约翰的胆量，又看出他们原是没有学问的小民，就希奇，认明他们是跟过耶稣的；'),
('CUV', '使徒行传', 44, 4, 14, '又看见那治好了的人和他们一同站著，就无话可驳。'),
('CUV', '使徒行传', 44, 4, 15, '于是吩咐他们从公会出去，就彼此商议说：'),
('CUV', '使徒行传', 44, 4, 16, '我们当怎样办这两个人呢？因为他们诚然行了一件明显的神迹，凡住耶路撒冷的人都知道，我们也不能说没有。'),
('CUV', '使徒行传', 44, 4, 17, '惟恐这事越发传扬在民间，我们必须恐吓他们，叫他们不再奉这名对人讲论。'),
('CUV', '使徒行传', 44, 4, 18, '于是叫了他们来，禁止他们总不可奉耶稣的名讲论教训人。'),
('CUV', '使徒行传', 44, 4, 19, '彼得、约翰说：听从你们，不听从神，这在神面前合理不合理，你们自己酌量罢！'),
('CUV', '使徒行传', 44, 4, 20, '我们所看见所听见的，不能不说。'),
('CUV', '使徒行传', 44, 4, 21, '官长为百姓的缘故，想不出法子刑罚他们，又恐吓一番，把他们释放了。这是因众人为所行的奇事都归荣耀与神。'),
('CUV', '使徒行传', 44, 4, 22, '原来藉著神迹医好的那人有四十多岁了。'),
('CUV', '使徒行传', 44, 4, 23, '二人既被释放，就到会友那里去，把祭司长和长老所说的话都告诉他们。'),
('CUV', '使徒行传', 44, 4, 24, '他们听见了，就同心合意的高声向神说：主阿！你是造天、地、海，和其中万物的，'),
('CUV', '使徒行传', 44, 4, 25, '你曾藉著圣灵，托你仆人─我们祖宗大卫的口，说：外邦为甚么争闹？万民为甚么谋算虚妄的事？'),
('CUV', '使徒行传', 44, 4, 26, '世上的君王一齐起来，臣宰也聚集，要敌挡主，并主的受膏者（或作：基督）。'),
('CUV', '使徒行传', 44, 4, 27, '希律和本丢彼拉多，外邦人和以色列民，果然在这城里聚集，要攻打你所膏的圣仆（仆：或作子）耶稣，'),
('CUV', '使徒行传', 44, 4, 28, '成就你手和你意旨所预定必有的事。'),
('CUV', '使徒行传', 44, 4, 29, '他们恐吓我们，现在求主鉴察，一面叫你仆人大放胆量讲你的道，一面伸出你的手来医治疾病，并且使神迹奇事因著你圣仆（仆：或作子）耶稣的名行出来。'),
('CUV', '使徒行传', 44, 4, 30, 'a'),
('CUV', '使徒行传', 44, 4, 31, '祷告完了，聚会的地方震动，他们就都被圣灵充满，放胆讲论神的道。'),
('CUV', '使徒行传', 44, 4, 32, '那许多信的人都是一心一意的，没有一人说他的东西有一样是自己的，都是大家公用。'),
('CUV', '使徒行传', 44, 4, 33, '使徒大有能力，见证主耶稣复活；众人也都蒙大恩。'),
('CUV', '使徒行传', 44, 4, 34, '内中也没有一个缺乏的，因为人人将田产房屋都卖了，把所卖的价银拿来，放在使徒脚前，'),
('CUV', '使徒行传', 44, 4, 35, '照各人所需用的，分给各人。'),
('CUV', '使徒行传', 44, 4, 36, '有一个利未人，生在居比路，名叫约瑟，使徒称他为巴拿巴（巴拿巴翻出来就是劝慰子）。'),
('CUV', '使徒行传', 44, 4, 37, '他有田地，也卖了，把价银拿来，放在使徒脚前。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 5, 1, '有一个人，名叫亚拿尼亚，同他的妻子撒非喇卖了田产，'),
('CUV', '使徒行传', 44, 5, 2, '把价银私自留下几分，他的妻子也知道，其余的几分拿来放在使徒脚前。'),
('CUV', '使徒行传', 44, 5, 3, '彼得说：亚拿尼亚！为甚么撒但充满了你的心，叫你欺哄圣灵，把田地的价银私自留下几分呢？'),
('CUV', '使徒行传', 44, 5, 4, '田地还没有卖，不是你自己的么？既卖了，价银不是你作主么？你怎么心里起这意念呢？你不是欺哄人，是欺哄神了。'),
('CUV', '使徒行传', 44, 5, 5, '亚拿尼亚听见这话，就仆倒，断了气；听见的人都甚惧怕r。'),
('CUV', '使徒行传', 44, 5, 6, '有些少年人起来，把他包裹，抬出去埋葬了。'),
('CUV', '使徒行传', 44, 5, 7, '约过了三小时，他的妻子进来，还不知道这事。'),
('CUV', '使徒行传', 44, 5, 8, '彼得对他说：你告诉我，你们卖田地的价银就是这些么？他说：就是这些。'),
('CUV', '使徒行传', 44, 5, 9, '彼得说：你们为甚么同心试探主的灵呢？埋葬你丈夫之人的脚已到门口，他们也要把你抬出去。'),
('CUV', '使徒行传', 44, 5, 10, '妇人立刻仆倒在彼得脚前，断了气。那些少年人进来，见他已经死了，就抬出去，埋在他丈夫旁边。'),
('CUV', '使徒行传', 44, 5, 11, '全教会和听见这事的人都甚惧怕。'),
('CUV', '使徒行传', 44, 5, 12, '主藉使徒的手在民间行了许多神迹s奇事；他们（或作：信的人）都同心合意的在所罗门的廊下.。'),
('CUV', '使徒行传', 44, 5, 13, '其余的人没有一个敢贴近他们百姓却尊重他们。'),
('CUV', '使徒行传', 44, 5, 14, '信而归主的人越发增添，连男带女很多。'),
('CUV', '使徒行传', 44, 5, 15, '甚至有人将病人抬到街上，放在床上或褥子上，指望彼得过来的时候，或者得他的影儿照在甚么人身上。'),
('CUV', '使徒行传', 44, 5, 16, '还有许多人带著病人和被污鬼缠磨的，从耶路撒冷四围的城邑来，全都得了医治。'),
('CUV', '使徒行传', 44, 5, 17, '大祭司和他的一切同人，就是撒都该教门的人，都起来，满心忌恨，'),
('CUV', '使徒行传', 44, 5, 18, '就下手拿住使徒，收在外监。'),
('CUV', '使徒行传', 44, 5, 19, '但主的使者夜间开了监门，领他们出来，'),
('CUV', '使徒行传', 44, 5, 20, '说：你们去站在殿里，把这生命的道都讲给百姓听。'),
('CUV', '使徒行传', 44, 5, 21, '使徒听了这话，天将亮的时候就进殿里去教训人。大祭司和他的同人来了，叫齐公会的人，和以色列族的众长老，就差人到监里去，要把使徒提出来。'),
('CUV', '使徒行传', 44, 5, 22, '但差役到了，不见他们在监里，就回来禀报说：'),
('CUV', '使徒行传', 44, 5, 23, '我们看见监牢关得极妥当，看守的人也站在门外；及至开了门，里面一个人都不见。'),
('CUV', '使徒行传', 44, 5, 24, '守殿官和祭司长听见这话，心里犯难，不知这事将来如何。'),
('CUV', '使徒行传', 44, 5, 25, '有一个人来禀报说：你们收在监里的人，现在站在殿里教训百姓。'),
('CUV', '使徒行传', 44, 5, 26, '于是守殿官和差役去带使徒来，并没有用强暴，因为怕百姓用石头打他们。'),
('CUV', '使徒行传', 44, 5, 27, '带到了，便叫使徒站在公会前；大祭司问他们说：'),
('CUV', '使徒行传', 44, 5, 28, '我们不是严严的禁止你们，不可奉这名教训人么？你们倒把你们的道理充满了耶路撒冷，想要叫这人的血归到我们身上！'),
('CUV', '使徒行传', 44, 5, 29, '彼得和众使徒回答说：顺从神，不顺从人，是应当的。'),
('CUV', '使徒行传', 44, 5, 30, '你们挂在木头上杀害的耶稣，我们祖宗的神已经叫他复活。'),
('CUV', '使徒行传', 44, 5, 31, '神且用右手将他高举（或作：他就是神高举在自己的右边），叫他作君王，作救主，将悔改的心和赦罪的恩赐给以色列人。'),
('CUV', '使徒行传', 44, 5, 32, '我们为这事作见证；神赐给顺从之人的圣灵也为这事作见证。'),
('CUV', '使徒行传', 44, 5, 33, '公会的人听见就极其恼怒，想要杀他们。'),
('CUV', '使徒行传', 44, 5, 34, '但有一个法利赛人，名叫迦玛列，是众百姓所敬重的教法师，在公会中站起来，吩咐人把使徒暂且带到外面去，'),
('CUV', '使徒行传', 44, 5, 35, '就对众人说：以色列人哪，论到这些人，你们应当小心怎样办理。'),
('CUV', '使徒行传', 44, 5, 36, '从前丢大起来，自夸为大；附从他的人约有四百，他被杀后，附从他的全都散了，归于无有。'),
('CUV', '使徒行传', 44, 5, 37, '此后，报名上册的时候，又有加利利的犹大起来，引诱些百姓跟从他；他也灭亡，附从他的人也都四散了。'),
('CUV', '使徒行传', 44, 5, 38, '现在，我劝你们不要管这些人，任凭他们罢！他们所谋的、所行的，若是出于人，必要败坏；'),
('CUV', '使徒行传', 44, 5, 39, '若是出于神，你们就不能败坏他们，恐怕你们倒是攻击神了。'),
('CUV', '使徒行传', 44, 5, 40, '公会的人听从了他，便叫使徒来，把他们打了，又吩咐他们不可奉耶稣的名讲道，就把他们释放了。'),
('CUV', '使徒行传', 44, 5, 41, '他们离开公会，心里欢喜，因被算是配为这名受辱。'),
('CUV', '使徒行传', 44, 5, 42, '他们就每日在殿里、在家里、不住的教训人，传耶稣是基督。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 6, 1, '那时，门徒增多，有说希利尼话的犹太人向希伯来人发怨言，因为在天天的供给上忽略了他们的寡妇。'),
('CUV', '使徒行传', 44, 6, 2, '十二使徒叫众门徒来，对他们说：我们撇下神的道去管理饭食，原是不合宜的。'),
('CUV', '使徒行传', 44, 6, 3, '所以弟兄们，当从你们中间选出七个有好名声、被圣灵充满、智慧充足的人，我们就派他们管理这事。'),
('CUV', '使徒行传', 44, 6, 4, '但我们要专心以祈祷、传道为事。'),
('CUV', '使徒行传', 44, 6, 5, '大众都喜悦这话，就拣选了司提反，乃是大有信心、圣灵充满的人，又拣选腓利、伯罗哥罗、尼迦挪、提门、巴米拿，并进犹太教的安提阿人尼哥拉，'),
('CUV', '使徒行传', 44, 6, 6, '叫他们站在使徒面前。使徒祷告了，就按手在他们头上。'),
('CUV', '使徒行传', 44, 6, 7, '神的道兴旺起来；在耶路撒冷门徒数目加增的甚多，也有许多祭司信从了这道。'),
('CUV', '使徒行传', 44, 6, 8, '司提反满得恩惠、能力，在民间行了大奇事和神迹。'),
('CUV', '使徒行传', 44, 6, 9, '当时有称利百地拿会堂的几个人，并有古利奈、亚力山太、基利家、亚西亚、各处会堂的几个人，都起来和司提反辩论。'),
('CUV', '使徒行传', 44, 6, 10, '司提反是以智慧和圣灵说话，众人敌挡不住，'),
('CUV', '使徒行传', 44, 6, 11, '就买出人来说：我们听见他说谤讟摩西和神的话。'),
('CUV', '使徒行传', 44, 6, 12, '他们又耸动了百姓、长老，并文士，就忽然来捉拿他，把他带到公会去，'),
('CUV', '使徒行传', 44, 6, 13, '设下假见证，说：这个人说话，不住的蹧践圣所和律法。'),
('CUV', '使徒行传', 44, 6, 14, '我们曾听见他说：这拿撒勒人耶稣要毁坏此地，也要改变摩西所交给我们的规条。'),
('CUV', '使徒行传', 44, 6, 15, '在公会里坐著的人都定睛看他，见他的面貌，好像天使的面貌。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 7, 1, '大祭司就说：这些事果然有么？'),
('CUV', '使徒行传', 44, 7, 2, '司提反说：诸位父兄请听！当日我们的祖宗亚伯拉罕在米所波大米还未住哈兰的时候，荣耀的神向他显现，'),
('CUV', '使徒行传', 44, 7, 3, '对他说：你要离开本地和亲族，往我所要指示你的地方去。'),
('CUV', '使徒行传', 44, 7, 4, '他就离开迦勒底人之地，住在哈兰。他父亲死了以后，神使他从那里搬到你们现在所住之地。'),
('CUV', '使徒行传', 44, 7, 5, '在这地方，神并没有给他产业，连立足之地也没有给他；但应许要将这地赐给他和他的后裔为业；那时他还没有儿子。'),
('CUV', '使徒行传', 44, 7, 6, '神说：他的后裔必寄居外邦，那里的人要叫他们作奴仆，苦待他们四百年。'),
('CUV', '使徒行传', 44, 7, 7, '神又说：使他们作奴仆的那国，我要惩罚。以后他们要出来，在这地方事奉我。'),
('CUV', '使徒行传', 44, 7, 8, '神又赐他割礼的约。于是亚伯拉罕生了以撒，第八日给他行了割礼。以撒生雅各，雅各生十二位先祖。'),
('CUV', '使徒行传', 44, 7, 9, '先祖嫉妒约瑟，把他卖到埃及去；神却与他同在，'),
('CUV', '使徒行传', 44, 7, 10, '救他脱离一切苦难，又使他在埃及王法老面前得恩典，有智慧。法老就派他作埃及国的宰相兼管全家。'),
('CUV', '使徒行传', 44, 7, 11, '后来埃及和迦南全地遭遇饥荒，大受艰难，我们的祖宗就绝了粮。'),
('CUV', '使徒行传', 44, 7, 12, '雅各听见在埃及有粮，就打发我们的祖宗初次往那里去。'),
('CUV', '使徒行传', 44, 7, 13, '第二次约瑟与弟兄们相认，他的亲族也被法老知道了。'),
('CUV', '使徒行传', 44, 7, 14, '约瑟就打发弟兄请父亲雅各和全家七十五个人都来。'),
('CUV', '使徒行传', 44, 7, 15, '于是雅各下了埃及，后来他和我们的祖宗都死在那里；'),
('CUV', '使徒行传', 44, 7, 16, '又被带到示剑，葬于亚伯拉罕在示剑用银子从哈抹子孙买来的坟墓里。'),
('CUV', '使徒行传', 44, 7, 17, '及至神应许亚伯拉罕的日期将到，以色列民在埃及兴盛众多，'),
('CUV', '使徒行传', 44, 7, 18, '直到有不晓得约瑟的新王兴起。'),
('CUV', '使徒行传', 44, 7, 19, '他用诡计待我们的宗族，苦害我们的祖宗，叫他们丢弃婴孩，使婴孩不能存活。'),
('CUV', '使徒行传', 44, 7, 20, '那时，摩西生下来，俊美非凡，在他父亲家里抚养了三个月。'),
('CUV', '使徒行传', 44, 7, 21, '他被丢弃的时候，法老的女儿拾了去，养为自己的儿子。'),
('CUV', '使徒行传', 44, 7, 22, '摩西学了埃及人一切的学问，说话行事都有才能。'),
('CUV', '使徒行传', 44, 7, 23, '他将到四十岁，心中起意去看望他的弟兄以色列人；'),
('CUV', '使徒行传', 44, 7, 24, '到了那里，见他们一个人受冤屈，就护庇他，为那受欺压的人报仇，打死了那埃及人。'),
('CUV', '使徒行传', 44, 7, 25, '他以为弟兄必明白神是藉他的手搭救他们；他们却不明白。'),
('CUV', '使徒行传', 44, 7, 26, '第二天，遇见两个以色列人争斗，就劝他们和睦，说：你们二位是弟兄，为甚么彼此欺负呢？'),
('CUV', '使徒行传', 44, 7, 27, '那欺负邻舍的把他推开，说：谁立你作我们的首领和审判官呢？'),
('CUV', '使徒行传', 44, 7, 28, '难道你要杀我，像昨天杀那埃及人么？'),
('CUV', '使徒行传', 44, 7, 29, '摩西听见这话就逃走了，寄居于米甸；在那里生了两个儿子。'),
('CUV', '使徒行传', 44, 7, 30, '过了四十年，在西乃山的旷野，有一位天使从荆棘火燄中向摩西显现。'),
('CUV', '使徒行传', 44, 7, 31, '摩西见了那异象，便觉希奇，正进前观看的时候，有主的声音说：'),
('CUV', '使徒行传', 44, 7, 32, '我是你列祖的神，就是亚伯拉罕的神，以撒的神，雅各的神。摩西战战兢兢，不敢观看。'),
('CUV', '使徒行传', 44, 7, 33, '主对他说：把你脚上的鞋脱下来；因为你所站之地是圣地。'),
('CUV', '使徒行传', 44, 7, 34, '我的百姓在埃及所受的困苦，我实在看见了，他们悲叹的声音，我也听见了。我下来要救他们。你来！我要差你往埃及去。'),
('CUV', '使徒行传', 44, 7, 35, '这摩西就是百姓弃绝说谁立你作我们的首领和审判官的；神却藉那在荆棘中显现之使者的手差派他作首领、作救赎的。'),
('CUV', '使徒行传', 44, 7, 36, '这人领百姓出来，在埃及，在红海、在旷野，四十年间行了奇事神迹。'),
('CUV', '使徒行传', 44, 7, 37, '那曾对以色列人说神要从你们弟兄中间给你们兴起一位先知像我的，就是这位摩西。'),
('CUV', '使徒行传', 44, 7, 38, '这人曾在旷野会中和西乃山上，与那对他说话的天使同在，又与我们的祖宗同在，并且领受活泼的圣言传给我们。'),
('CUV', '使徒行传', 44, 7, 39, '我们的祖宗不肯听从，反弃绝他，心里归向埃及，'),
('CUV', '使徒行传', 44, 7, 40, '对亚伦说：你且为我们造些神像，在我们前面引路；因为领我们出埃及地的那个摩西，我们不知道他遭了甚么事。'),
('CUV', '使徒行传', 44, 7, 41, '那时，他们造了一个牛犊，又拿祭物献给那像，欢喜自己手中的工作。'),
('CUV', '使徒行传', 44, 7, 42, '神就转脸不顾，任凭他们事奉天上的日月星辰，正如先知书上所写的说：以色列家阿，你们四十年间在旷野，岂是将牺牲和祭物献给我么？'),
('CUV', '使徒行传', 44, 7, 43, '你们抬著摩洛的帐幕和理番神的星，就是你们所造为要敬拜的像。因此，我要把你们迁到巴比伦外去。'),
('CUV', '使徒行传', 44, 7, 44, '我们的祖宗在旷野，有法柜的帐幕，是神吩咐摩西叫他照所看见的样式做的。'),
('CUV', '使徒行传', 44, 7, 45, '这帐幕，我们的祖宗相继承受。当神在他们面前赶出外邦人去的时候，他们同约书亚把帐幕搬进承受为业之地，直存到大卫的日子。'),
('CUV', '使徒行传', 44, 7, 46, '大卫在神面前蒙恩，祈求为雅各的神预备居所；'),
('CUV', '使徒行传', 44, 7, 47, '却是所罗门为神造成殿宇。'),
('CUV', '使徒行传', 44, 7, 48, '其实，至高者并不住人手所造的，就如先知所言：'),
('CUV', '使徒行传', 44, 7, 49, '主说：天是我的座位，地是我的脚凳；你们要为我造何等的殿宇？那里是我安息的地方呢？'),
('CUV', '使徒行传', 44, 7, 50, '这一切不都是我手所造的么？'),
('CUV', '使徒行传', 44, 7, 51, '你们这硬著颈项、心与耳未受割礼的人，常时抗拒圣灵！你们的祖宗怎样，你们也怎样。'),
('CUV', '使徒行传', 44, 7, 52, '那一个先知不是你们祖宗逼迫呢？他们也把预先传说那义者要来的人杀了；如今你们又把那义者卖了，杀了。'),
('CUV', '使徒行传', 44, 7, 53, '你们受了天使所传的律法，竟不遵守。'),
('CUV', '使徒行传', 44, 7, 54, '众人听见这话就极其恼怒，向司提反咬牙切齿。'),
('CUV', '使徒行传', 44, 7, 55, '但司提反被圣灵充满，定睛望天，看见神的荣耀，又看见耶稣站在神的右边，'),
('CUV', '使徒行传', 44, 7, 56, '就说：我看见天开了，人子站在神的右边。'),
('CUV', '使徒行传', 44, 7, 57, '众人大声喊叫，摀著耳朵，齐心拥上前去，'),
('CUV', '使徒行传', 44, 7, 58, '把他推到城外，用石头打他。作见证的人把衣裳放在一个少年人名叫扫罗的脚前。'),
('CUV', '使徒行传', 44, 7, 59, '他们正用石头打的时候，司提反呼吁主说：求主耶稣接收我的灵魂！'),
('CUV', '使徒行传', 44, 7, 60, '又跪下大声喊著说：主阿，不要将这罪归于他们！说了这话，就睡了。扫罗也喜悦他被害。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 8, 1, '从这日起，耶路撒冷的教会大遭逼迫，除了使徒以外，门徒都分散在犹太和撒玛利亚各处。'),
('CUV', '使徒行传', 44, 8, 2, '有虔诚的人把司提反埋葬了，为他捶胸大哭。'),
('CUV', '使徒行传', 44, 8, 3, '扫罗却残害教会，进各人的家，拉著男女下在监里。'),
('CUV', '使徒行传', 44, 8, 4, '那些分散的人往各处去传道。'),
('CUV', '使徒行传', 44, 8, 5, '腓利下撒玛利亚城去，宣讲基督。'),
('CUV', '使徒行传', 44, 8, 6, '众人听见了，又看见腓利所行的神迹，就同心合意的听从他的话。'),
('CUV', '使徒行传', 44, 8, 7, '因为有许多人被污鬼附著，那些鬼大声呼叫，从他们身上出来；还有许多瘫痪的，瘸腿的，都得了医治。'),
('CUV', '使徒行传', 44, 8, 8, '在那城里，就大有欢喜。'),
('CUV', '使徒行传', 44, 8, 9, '有一个人，名叫西门，向来在那城里行邪术，妄自尊大，使撒玛利亚的百姓惊奇；'),
('CUV', '使徒行传', 44, 8, 10, '无论大小都听从他，说：这人就是那称为神的大能者。'),
('CUV', '使徒行传', 44, 8, 11, '他们听从他，因他久用邪术，使他们惊奇。'),
('CUV', '使徒行传', 44, 8, 12, '及至他们信了腓利所传神国的福音和耶稣基督的名，连男带女就受了洗。'),
('CUV', '使徒行传', 44, 8, 13, '西门自己也信了；既受了洗，就常与腓利在一处，看见他所行的神迹和大异能，就甚惊奇。'),
('CUV', '使徒行传', 44, 8, 14, '使徒在耶路撒冷听见撒玛利亚人领受了神的道，就打发彼得、约翰往他们那里去。'),
('CUV', '使徒行传', 44, 8, 15, '两个人到了，就为他们祷告，要叫他们受圣灵。'),
('CUV', '使徒行传', 44, 8, 16, '因为圣灵还没有降在他们一个人身上，他们只奉主耶稣的名受了洗。'),
('CUV', '使徒行传', 44, 8, 17, '于是使徒按手在他们头上，他们就受了圣灵。'),
('CUV', '使徒行传', 44, 8, 18, '西门看见使徒按手，便有圣灵赐下，就拿钱给使徒，'),
('CUV', '使徒行传', 44, 8, 19, '说：把这权柄也给我，叫我手按著谁，谁就可以受圣灵。'),
('CUV', '使徒行传', 44, 8, 20, '彼得说：你的银子和你一同灭亡罢！因你想神的恩赐是可以用钱买的。'),
('CUV', '使徒行传', 44, 8, 21, '你在这道上无分无关；因为在神面前，你的心不正。'),
('CUV', '使徒行传', 44, 8, 22, '你当懊悔你这罪恶，祈求主，或者你心里的意念可得赦免。'),
('CUV', '使徒行传', 44, 8, 23, '我看出你正在苦胆之中，被罪恶捆绑。'),
('CUV', '使徒行传', 44, 8, 24, '西门说：愿你们为我求主，叫你们所说的，没有一样临到我身上。'),
('CUV', '使徒行传', 44, 8, 25, '使徒既证明主道，而且传讲，就回耶路撒冷去，一路在撒玛利亚好些村庄传扬福音。'),
('CUV', '使徒行传', 44, 8, 26, '有主的一个使者对腓利说：起来！向南走，往那从耶路撒冷下迦萨的路上去。那路是旷野。'),
('CUV', '使徒行传', 44, 8, 27, '腓利就起身去了，不料，有一个埃提阿伯（即古实，见以赛亚十八章一节）人，是个有大权的太监，在埃提阿伯女王干大基的手下总管银库，他上耶路撒冷礼拜去了。'),
('CUV', '使徒行传', 44, 8, 28, '现在回来，在车上坐著，念先知以赛亚的书。'),
('CUV', '使徒行传', 44, 8, 29, '圣灵对腓利说：你去！贴近那车走。'),
('CUV', '使徒行传', 44, 8, 30, '腓利就跑到太监那里，听见他念先知以赛亚的书，便问他说：你所念的，你明白么？'),
('CUV', '使徒行传', 44, 8, 31, '他说：没有人指教我，怎能明白呢？于是请腓利上车，与他同坐。'),
('CUV', '使徒行传', 44, 8, 32, '他所念的那段经，说：他像羊被牵到宰杀之地，又像羊羔在剪毛的人手下无声；他也是这样不开口。'),
('CUV', '使徒行传', 44, 8, 33, '他卑微的时候，人不按公义审判他（原文是他的审判被夺去）；谁能述说他的世代，因为他的生命从地上夺去。'),
('CUV', '使徒行传', 44, 8, 34, '太监对腓利说：请问，先知说这话是指著谁？是指著自己呢？是指著别人呢？'),
('CUV', '使徒行传', 44, 8, 35, '腓利就开口从这经上起，对他传讲耶稣。'),
('CUV', '使徒行传', 44, 8, 36, '二人正往前走，到了有水的地方，太监说：看哪，这里有水，我受洗有甚么妨碍呢？（有古卷在此有：'),
('CUV', '使徒行传', 44, 8, 37, '腓利说：你若是一心相信，就可以。他回答说：我信耶稣基督是神的儿子。）'),
('CUV', '使徒行传', 44, 8, 38, '于是吩咐车站住，腓利和太监二人同下水里去，腓利就给他施洗。'),
('CUV', '使徒行传', 44, 8, 39, '从水里上来，主的灵把腓利提了去，太监也不再见他了，就欢欢喜喜的走路。'),
('CUV', '使徒行传', 44, 8, 40, '后来有人在亚锁都遇见腓利；他走遍那地方，在各城宣传福音，直到该撒利亚。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 9, 1, '扫罗仍然向主的门徒口吐威吓凶杀的话，去见大祭司，'),
('CUV', '使徒行传', 44, 9, 2, '求文书给大马色的各会堂，若是找著信奉这道的人，无论男女，都准他捆绑带到耶路撒冷。'),
('CUV', '使徒行传', 44, 9, 3, '扫罗行路，将到大马色，忽然从天上发光，四面照著他；'),
('CUV', '使徒行传', 44, 9, 4, '他就仆倒在地，听见有声音对他说：扫罗！扫罗！你为甚么逼迫我？'),
('CUV', '使徒行传', 44, 9, 5, '他说：主阿！你是谁？主说：我就是你所逼迫的耶稣。'),
('CUV', '使徒行传', 44, 9, 6, '起来！进城去，你所当做的事，必有人告诉你。'),
('CUV', '使徒行传', 44, 9, 7, '同行的人站在那里，说不出话来，听见声音，却看不见人。'),
('CUV', '使徒行传', 44, 9, 8, '扫罗从地上起来，睁开眼睛，竟不能看见甚么。有人拉他的手，领他进了大马色；'),
('CUV', '使徒行传', 44, 9, 9, '三日不能看见，也不吃也不喝。'),
('CUV', '使徒行传', 44, 9, 10, '当下，在大马色有一个门徒，名叫亚拿尼亚。主在异象中对他说：亚拿尼亚。他说：主，我在这里。'),
('CUV', '使徒行传', 44, 9, 11, '主对他说：起来！往直街去，在犹大的家里，访问一个大数人，名叫扫罗。他正祷告，'),
('CUV', '使徒行传', 44, 9, 12, '又看见了一个人，名叫亚拿尼亚，进来按手在他身上，叫他能看见。'),
('CUV', '使徒行传', 44, 9, 13, '亚拿尼亚回答说：主阿，我听见许多人说：这人怎样在耶路撒冷多多苦害你的圣徒，'),
('CUV', '使徒行传', 44, 9, 14, '并且他在这里有从祭司长得来的权柄捆绑一切求告你名的人。'),
('CUV', '使徒行传', 44, 9, 15, '主对亚拿尼亚说：你只管去！他是我所拣选的器皿，要在外邦人和君王，并以色列人面前宣扬我的名。'),
('CUV', '使徒行传', 44, 9, 16, '我也要指示他，为我的名必须受许多的苦难。'),
('CUV', '使徒行传', 44, 9, 17, '亚拿尼亚就去了，进入那家，把手按在扫罗身上，说：兄弟扫罗，在你来的路上向你显现的主，就是耶稣，打发我来，叫你能看见，又被圣灵充满。'),
('CUV', '使徒行传', 44, 9, 18, '扫罗的眼睛上，好像有鳞立刻掉下来，他就能看见。于是起来受了洗；'),
('CUV', '使徒行传', 44, 9, 19, '吃过饭就健壮了。扫罗和大马色的门徒同住了些日子，'),
('CUV', '使徒行传', 44, 9, 20, '就在各会堂里宣传耶稣，说他是神的儿子。'),
('CUV', '使徒行传', 44, 9, 21, '凡听见的人都惊奇，说：在耶路撒冷残害求告这名的，不是这人么？并且他到这里来，特要捆绑他们，带到祭司长那里。'),
('CUV', '使徒行传', 44, 9, 22, '但扫罗越发有能力，驳倒住大马色的犹太人，证明耶稣是基督。'),
('CUV', '使徒行传', 44, 9, 23, '过了好些日子，犹太人商议要杀扫罗，'),
('CUV', '使徒行传', 44, 9, 24, '但他们的计谋被扫罗知道了。他们又昼夜在城门守候，要杀他。'),
('CUV', '使徒行传', 44, 9, 25, '他的门徒就在夜间用筐子把他从城墙上缒下去。'),
('CUV', '使徒行传', 44, 9, 26, '扫罗到了耶路撒冷，想与门徒结交，他们却都怕他，不信他是门徒。'),
('CUV', '使徒行传', 44, 9, 27, '惟有巴拿巴接待他，领去见使徒，把他在路上怎么看见主，主怎么向他说话，他在大马色怎么奉耶稣的名放胆传道，都述说出来。'),
('CUV', '使徒行传', 44, 9, 28, '于是扫罗在耶路撒冷和门徒出入来往，'),
('CUV', '使徒行传', 44, 9, 29, '奉主的名放胆传道，并与说希利尼话的犹太人讲论辩驳；他们却想法子要杀他。'),
('CUV', '使徒行传', 44, 9, 30, '弟兄们知道了就送他下该撒利亚，打发他往大数去。'),
('CUV', '使徒行传', 44, 9, 31, '那时，犹太加利利、撒玛利亚各处的教会都得平安，被建立；凡事敬畏主，蒙圣灵的安慰，人数就增多了。'),
('CUV', '使徒行传', 44, 9, 32, '彼得周流四方的时候，也到了居住吕大的圣徒那里；'),
('CUV', '使徒行传', 44, 9, 33, '遇见一个人，名叫以尼雅，得了瘫痪，在褥子上躺卧八年。'),
('CUV', '使徒行传', 44, 9, 34, '彼得对他说：以尼雅，耶稣基督医好你了；起来！收拾你的褥子。他就立刻起来了。'),
('CUV', '使徒行传', 44, 9, 35, '凡住吕大和沙仑的人都看见了他，就归服主。'),
('CUV', '使徒行传', 44, 9, 36, '在约帕有一个女徒，名叫大比大，繙希利尼话就是多加（就是羚羊的意思）；他广行善事，多施赒济。'),
('CUV', '使徒行传', 44, 9, 37, '当时，他患病而死，有人把他洗了，停在楼上。'),
('CUV', '使徒行传', 44, 9, 38, '吕大原与约帕相近；门徒听见彼得在那里，就打发两个人去见他，央求他说：快到我们那里去，不要耽延。'),
('CUV', '使徒行传', 44, 9, 39, '彼得就起身和他们同去；到了，便有人领他上楼。众寡妇都站在彼得旁边哭，拿多加与他们同在时所做的里衣外衣给他看。'),
('CUV', '使徒行传', 44, 9, 40, '彼得叫他们都出去，就跪下祷告，转身对著死人说：大比大，起来！他就睁开眼睛，见了彼得，便坐起来。'),
('CUV', '使徒行传', 44, 9, 41, '彼得伸手扶他起来，叫众圣徒和寡妇进去，把多加活活的交给他们。'),
('CUV', '使徒行传', 44, 9, 42, '这事传遍了约帕，就有许多人信了主。'),
('CUV', '使徒行传', 44, 9, 43, '此后，彼得在约帕一个硝皮匠西门的家里住了多日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 10, 1, '在该撒利亚有一个人，名叫哥尼流，是义大利营的百夫长。'),
('CUV', '使徒行传', 44, 10, 2, '他是个虔诚人，他和全家都敬畏神，多多赒济百姓，常常祷告神。'),
('CUV', '使徒行传', 44, 10, 3, '有一天，约在申初，他在异象中明明看见神的一个使者进去，到他那里，说：哥尼流。'),
('CUV', '使徒行传', 44, 10, 4, '哥尼流定睛看他，惊怕说：主阿，甚么事呢？天使说：你的祷告和你的赒济达到神面前，已蒙记念了。'),
('CUV', '使徒行传', 44, 10, 5, '现在你当打发人往约帕去，请那称呼彼得的西门来。'),
('CUV', '使徒行传', 44, 10, 6, '他住在海边一个硝皮匠西门的家里，房子在海边上。'),
('CUV', '使徒行传', 44, 10, 7, '向他说话的天使去后，哥尼流叫了两个家人和常伺候他的一个虔诚兵来，'),
('CUV', '使徒行传', 44, 10, 8, '把这事都述说给他们听，就打发他们往约帕去。'),
('CUV', '使徒行传', 44, 10, 9, '第二天，他们行路将近那城。彼得约在午正，上房顶去祷告，'),
('CUV', '使徒行传', 44, 10, 10, '觉得饿了，想要吃。那家的人正预备饭的时候，彼得魂游象外，'),
('CUV', '使徒行传', 44, 10, 11, '看见天开了，有一物降下，好像一块大布，系著四角，缒在地上，'),
('CUV', '使徒行传', 44, 10, 12, '里面有地上各样四足的走兽和昆虫，并天上的飞鸟；'),
('CUV', '使徒行传', 44, 10, 13, '又有声音向他说：彼得，起来，宰了吃！'),
('CUV', '使徒行传', 44, 10, 14, '彼得却说：主阿，这是不可的！凡俗物和不洁净的物，我从来没有吃过。'),
('CUV', '使徒行传', 44, 10, 15, '第二次有声音向他说：神所洁净的，你不可当作俗物。'),
('CUV', '使徒行传', 44, 10, 16, '这样一连三次，那物随即收回天上去了。'),
('CUV', '使徒行传', 44, 10, 17, '彼得心里正在猜疑之间，不知所看见的异象是甚么意思。哥尼流所差来的人已经访问到西门的家，站在门外，'),
('CUV', '使徒行传', 44, 10, 18, '喊著问：有称呼彼得的西门住在这里没有？'),
('CUV', '使徒行传', 44, 10, 19, '彼得还思想那异象的时候，圣灵向他说：有三个人来找你。'),
('CUV', '使徒行传', 44, 10, 20, '起来，下去，和他们同往，不要疑惑，因为是我差他们来的。'),
('CUV', '使徒行传', 44, 10, 21, '于是彼得下去见那些人，说：我就是你们所找的人。你们来是为甚么缘故？'),
('CUV', '使徒行传', 44, 10, 22, '他们说：百夫长哥尼流是个义人，敬畏神，为犹太通国所称赞。他蒙一位圣天使指示，叫他请你到他家里去，听你的话。'),
('CUV', '使徒行传', 44, 10, 23, '彼得就请他们进去，住了一宿。次日，起身和他们同去，还有约帕的几个弟兄同著他去；'),
('CUV', '使徒行传', 44, 10, 24, '又次日，他们进入该撒利亚，哥尼流已经请了他的亲属密友等候他们。'),
('CUV', '使徒行传', 44, 10, 25, '彼得一进去，哥尼流就迎接他，俯伏在他脚前拜他。'),
('CUV', '使徒行传', 44, 10, 26, '彼得拉他，说：你起来，我也是人。'),
('CUV', '使徒行传', 44, 10, 27, '彼得和他说著话进去，见有好些人在那里聚集，'),
('CUV', '使徒行传', 44, 10, 28, '就对他们说：你们知道，犹太人和别国的人亲近来往本是不合例的，但神已经指示我，无论甚么人都不可看作俗而不洁净的。'),
('CUV', '使徒行传', 44, 10, 29, '所以我被请的时候，就不推辞而来。现在请问：你们叫我来有甚么意思呢？'),
('CUV', '使徒行传', 44, 10, 30, '哥尼流说：前四天，这个时候，我在家中守著申初的祷告，忽然有一个人穿著光明的衣裳，站在我面前，'),
('CUV', '使徒行传', 44, 10, 31, '说：哥尼流，你的祷告已蒙垂听，你的赒济达到神面前已蒙记念了。'),
('CUV', '使徒行传', 44, 10, 32, '你当打发人往约帕去，请那称呼彼得的西门来，他住在海边一个硝皮匠西门的家里。'),
('CUV', '使徒行传', 44, 10, 33, '所以我立时打发人去请你。你来了很好；现今我们都在神面前，要听主所吩咐你的一切话。'),
('CUV', '使徒行传', 44, 10, 34, '彼得就开口说：我真看出神是不偏待人。'),
('CUV', '使徒行传', 44, 10, 35, '原来，各国中那敬畏主、行义的人都为主所悦纳。'),
('CUV', '使徒行传', 44, 10, 36, '神藉著耶稣基督（他是万有的主）传和平的福音，将这道赐给以色列人。'),
('CUV', '使徒行传', 44, 10, 37, '这话在约翰宣传洗礼以后，从加利利起，传遍了犹太。'),
('CUV', '使徒行传', 44, 10, 38, '神怎样以圣灵和能力膏拿撒勒人耶稣，这都是你们知道的。他周流四方，行善事，医好凡被魔鬼压制的人，因为神与他同在。'),
('CUV', '使徒行传', 44, 10, 39, '他在犹太人之地，并耶路撒冷所行的一切事，有我们作见证。他们竟把他挂在木头上杀了。'),
('CUV', '使徒行传', 44, 10, 40, '第三日，神叫他复活，显现出来；'),
('CUV', '使徒行传', 44, 10, 41, '不是显现给众人看，乃是显现给神预先所拣选为他作见证的人看，就是我们这些在他从死里复活以后和他同吃同喝的人。'),
('CUV', '使徒行传', 44, 10, 42, '他吩咐我们传道给众人，证明他是神所立定的，要作审判活人、死人的主。'),
('CUV', '使徒行传', 44, 10, 43, '众先知也为他作见证说：凡信他的人必因他的名得蒙赦罪。'),
('CUV', '使徒行传', 44, 10, 44, '彼得还说这话的时候，圣灵降在一切听道的人身上。'),
('CUV', '使徒行传', 44, 10, 45, '那些奉割礼、和彼得同来的信徒，见圣灵的恩赐也浇在外邦人身上，就都希奇；'),
('CUV', '使徒行传', 44, 10, 46, '因听见他们说方言，称赞神为大。'),
('CUV', '使徒行传', 44, 10, 47, '于是彼得说：这些人既受了圣灵，与我们一样，谁能禁止用水给他们施洗呢？'),
('CUV', '使徒行传', 44, 10, 48, '就吩咐奉耶稣基督的名给他们施洗。他们又请彼得住了几天。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 11, 1, '使徒和在犹太的众弟兄听说外邦人也领受了神的道。'),
('CUV', '使徒行传', 44, 11, 2, '及至彼得上了耶路撒冷，那些奉割礼的门徒和他争辩说：'),
('CUV', '使徒行传', 44, 11, 3, '你进入未受割礼之人的家和他们一同吃饭了。'),
('CUV', '使徒行传', 44, 11, 4, '彼得就开口把这事挨次给他们讲解说：'),
('CUV', '使徒行传', 44, 11, 5, '我在约帕城里祷告的时候，魂游象外，看见异象，有一物降下，好像一块大布，系著四角，从天缒下，直来到我跟前。'),
('CUV', '使徒行传', 44, 11, 6, '我定睛观看，见内中有地上四足的牲畜和野兽、昆虫，并天上的飞鸟。'),
('CUV', '使徒行传', 44, 11, 7, '我且听见有声音向我说：彼得，起来，宰了吃！'),
('CUV', '使徒行传', 44, 11, 8, '我说：主阿，这是不可的！凡俗而不洁净的物从来没有入过我的口。'),
('CUV', '使徒行传', 44, 11, 9, '第二次，有声音从天上说：神所洁净的，你不可当作俗物。'),
('CUV', '使徒行传', 44, 11, 10, '这样一连三次，就都收回天上去了。'),
('CUV', '使徒行传', 44, 11, 11, '正当那时，有三个人站在我们所住的房门前，是从该撒利亚差来见我的。'),
('CUV', '使徒行传', 44, 11, 12, '圣灵吩咐我和他们同去，不要疑惑。（或作：不要分别等类）。同著我去的，还有这六位弟兄；我们都进了那人的家，'),
('CUV', '使徒行传', 44, 11, 13, '那人就告诉我们，他如何看见一位天使，站在他屋里，说：你打发人往约帕去，请那称呼彼得的西门来；'),
('CUV', '使徒行传', 44, 11, 14, '他有话告诉你，可以叫你和你的全家得救。'),
('CUV', '使徒行传', 44, 11, 15, '我一开讲，圣灵便降在他们身上，正像当初降在我们身上一样。'),
('CUV', '使徒行传', 44, 11, 16, '我就想起主的话说：约翰是用水施洗，但你们要受圣灵的洗。'),
('CUV', '使徒行传', 44, 11, 17, '神既然给他们恩赐，像在我们信主耶稣基督的时候给了我们一样；我是谁，能拦阻神呢！'),
('CUV', '使徒行传', 44, 11, 18, '众人听见这话，就不言语了，只归荣耀与神，说：这样看来，神也赐恩给外邦人，叫他们悔改得生命了。'),
('CUV', '使徒行传', 44, 11, 19, '那些因司提反的事遭患难四散的门徒直走到腓尼基和居比路，并安提阿；他们不向别人讲道，只向犹太人讲。'),
('CUV', '使徒行传', 44, 11, 20, '但内中有居比路和古利奈人，他们到了安提阿也向希利尼人传讲主耶稣（有古卷作：也向说希利尼话的犹太人传讲主耶稣）。'),
('CUV', '使徒行传', 44, 11, 21, '主与他们同在，信而归主的人就很多了。'),
('CUV', '使徒行传', 44, 11, 22, '这风声传到耶路撒冷教会人的耳中，他们就打发巴拿巴出去，走到安提阿为止。'),
('CUV', '使徒行传', 44, 11, 23, '他到了那里，看见神所赐的恩就欢喜，劝勉众人，立定心志，恒久靠主。'),
('CUV', '使徒行传', 44, 11, 24, '这巴拿巴原是个好人，被圣灵充满，大有信心。于是有许多人归服了主。'),
('CUV', '使徒行传', 44, 11, 25, '他又往大数去找扫罗，'),
('CUV', '使徒行传', 44, 11, 26, '找著了，就带他到安提阿去。他们足有一年的工夫和教会一同聚集，教训了许多人。门徒称为基督徒是从安提阿起首。'),
('CUV', '使徒行传', 44, 11, 27, '当那些日子，有几位先知从耶路撒冷下到安提阿。'),
('CUV', '使徒行传', 44, 11, 28, '内中有一位，名叫亚迦布，站起来，藉著圣灵指明天下将有大饥荒。这事到革老丢年间果然有了。'),
('CUV', '使徒行传', 44, 11, 29, '于是门徒定意照各人的力量捐钱，送去供给住在犹太的弟兄。'),
('CUV', '使徒行传', 44, 11, 30, '他们就这样行，把捐项托巴拿巴和扫罗送到众长老那里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 12, 1, '那时，希律王下手苦害教会中几个人，'),
('CUV', '使徒行传', 44, 12, 2, '用刀杀了约翰的哥哥雅各。'),
('CUV', '使徒行传', 44, 12, 3, '他见犹太人喜欢这事，又去捉拿彼得。那时正是除酵的日子。'),
('CUV', '使徒行传', 44, 12, 4, '希律拿了彼得，收在监里，交付四班兵丁看守，每班四个人，意思要在逾越节后把他提出来，当著百姓办他。'),
('CUV', '使徒行传', 44, 12, 5, '于是彼得被囚在监里；教会却为他切切的祷告神。'),
('CUV', '使徒行传', 44, 12, 6, '希律将要提他出来的前一夜，彼得被两条铁链锁著，睡在两个兵丁当中；看守的人也在门外看守。'),
('CUV', '使徒行传', 44, 12, 7, '忽然，有主的一个使者站在旁边，屋里有光照耀，天使拍彼得的肋旁，拍醒了他，说：快快起来！那铁链就从他手上脱落下来。'),
('CUV', '使徒行传', 44, 12, 8, '天使对他说：束上带子，穿上鞋。他就那样做。天使又说：披上外衣，跟著我来。'),
('CUV', '使徒行传', 44, 12, 9, '彼得就出来跟著他，不知道天使所做是真的，只当见了异象。'),
('CUV', '使徒行传', 44, 12, 10, '过了第一层第二层监牢，就来到临街的铁门，那门自己开了。他们出来，走过一条街，天使便离开他去了。'),
('CUV', '使徒行传', 44, 12, 11, '彼得醒悟过来，说：我现在真知道主差遣他的使者，救我脱离希律的手和犹太百姓一切所盼望的。'),
('CUV', '使徒行传', 44, 12, 12, '想了一想，就往那称呼马可的约翰、他母亲马利亚家去，在那里有好些人聚集祷告。'),
('CUV', '使徒行传', 44, 12, 13, '彼得敲外门，有一个使女，名叫罗大，出来探听，'),
('CUV', '使徒行传', 44, 12, 14, '听得是彼得的声音，就欢喜的顾不得开门，跑进去告诉众人说：彼得站在门外。'),
('CUV', '使徒行传', 44, 12, 15, '他们说：你是疯了！使女极力的说：真是他！他们说：必是他的天使！'),
('CUV', '使徒行传', 44, 12, 16, '彼得不住的敲门。他们开了门，看见他，就甚惊奇。'),
('CUV', '使徒行传', 44, 12, 17, '彼得摆手，不要他们作声，就告诉他们主怎样领他出监；又说：你们把这事告诉雅各和众弟兄。于是出去，往别处去了。'),
('CUV', '使徒行传', 44, 12, 18, '到了天亮，兵丁扰乱得很，不知道彼得往那里去了。'),
('CUV', '使徒行传', 44, 12, 19, '希律找他，找不著，就审问看守的人，吩咐把他们拉去杀了。后来希律离开犹太，下该撒利亚去，住在那里。'),
('CUV', '使徒行传', 44, 12, 20, '希律恼怒推罗、西顿的人。他们那一带地方是从王的地土得粮，因此就托了王的内侍臣伯拉斯都的情，一心来求和。'),
('CUV', '使徒行传', 44, 12, 21, '希律在所定的日子，穿上朝服，坐在位上，对他们讲论一番。'),
('CUV', '使徒行传', 44, 12, 22, '百姓喊著说：这是神的声音，不是人的声音。'),
('CUV', '使徒行传', 44, 12, 23, '希律不归荣耀给神，所以主的使者立刻罚他，他被虫所咬，气就绝了。'),
('CUV', '使徒行传', 44, 12, 24, '神的道日见兴旺，越发广传。'),
('CUV', '使徒行传', 44, 12, 25, '巴拿巴和扫罗办完了他们供给的事，就从耶路撒冷回来，带著称呼马可的约翰同去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 13, 1, '在安提阿的教会中，有几位先知和教师，就是巴拿巴和称呼尼结的西面、古利奈人路求，与分封之王希律同养的马念，并扫罗。'),
('CUV', '使徒行传', 44, 13, 2, '他们事奉主、禁食的时候，圣灵说：要为我分派巴拿巴和扫罗，去做我召他们所做的工。'),
('CUV', '使徒行传', 44, 13, 3, '于是禁食祷告，按手在他们头上，就打发他们去了。'),
('CUV', '使徒行传', 44, 13, 4, '他们既被圣灵差遣，就下到西流基，从那里坐船往居比路去。'),
('CUV', '使徒行传', 44, 13, 5, '到了撒拉米，就在犹太人各会堂里传讲神的道，也有约翰作他们的帮手。'),
('CUV', '使徒行传', 44, 13, 6, '经过全岛，直到帕弗，在那里遇见一个有法术，假充先知的犹太人，名叫巴耶稣。'),
('CUV', '使徒行传', 44, 13, 7, '这人常和方伯士求保罗同在。士求保罗是个通达人，他请了巴拿巴和扫罗来，要听神的道。'),
('CUV', '使徒行传', 44, 13, 8, '只是那行法术的以吕马（这名翻出来就是行法术的意思）敌挡使徒，要叫方伯不信真道。'),
('CUV', '使徒行传', 44, 13, 9, '扫罗又名保罗，被圣灵充满，定睛看他，'),
('CUV', '使徒行传', 44, 13, 10, '说：你这充满各样诡诈奸恶，魔鬼的儿子，众善的仇敌，你混乱主的正道还不止住么？'),
('CUV', '使徒行传', 44, 13, 11, '现在主的手加在你身上，你要瞎眼，暂且不见日光。他的眼睛立刻昏蒙黑暗，四下里求人拉著手领他。'),
('CUV', '使徒行传', 44, 13, 12, '方伯看见所做的事，很希奇主的道，就信了。'),
('CUV', '使徒行传', 44, 13, 13, '保罗和他的同人从帕弗开船，来到旁非利亚的别加，约翰就离开他们，回耶路撒冷去。'),
('CUV', '使徒行传', 44, 13, 14, '他们离了别加往前行，来到彼西底的安提阿，在安息日进会堂坐下。'),
('CUV', '使徒行传', 44, 13, 15, '读完了律法和先知的书，管会堂的，叫人过去，对他们说：二位兄台，若有甚么劝勉众人的话，请说。'),
('CUV', '使徒行传', 44, 13, 16, '保罗就站起来，举手，说：以色列人和一切敬畏神的人，请听。'),
('CUV', '使徒行传', 44, 13, 17, '这以色列民的神拣选了我们的祖宗，当民寄居埃及的时候抬举他们，用大能的手领他们出来；'),
('CUV', '使徒行传', 44, 13, 18, '又在旷野容忍（或作：抚养）他们，约有四十年。'),
('CUV', '使徒行传', 44, 13, 19, '既灭了迦南地七族的人，就把那地分给他们为业；'),
('CUV', '使徒行传', 44, 13, 20, '此后给他们设立士师，约有四百五十年，直到先知撒母耳的时候。'),
('CUV', '使徒行传', 44, 13, 21, '后来他们求一个王，神就将便雅悯支派中基士的儿子扫罗，给他们作王四十年。'),
('CUV', '使徒行传', 44, 13, 22, '既废了扫罗，就选立大卫作他们的王，又为他作见证说：我寻得耶西的儿子大卫，他是合我心意的人，凡事要遵行我的旨意。'),
('CUV', '使徒行传', 44, 13, 23, '从这人的后裔中，神已经照著所应许的，为以色列人立了一位救主，就是耶稣。'),
('CUV', '使徒行传', 44, 13, 24, '在他没有出来以先，约翰向以色列众民宣讲悔改的洗礼。'),
('CUV', '使徒行传', 44, 13, 25, '约翰将行尽他的程途说：你们以为我是谁？我不是基督；只是有一位在我以后来的，我解他脚上的鞋带也是不配的。'),
('CUV', '使徒行传', 44, 13, 26, '弟兄们，亚伯拉罕的子孙和你们中间敬畏神的人哪，这救世的道是传给我们的。'),
('CUV', '使徒行传', 44, 13, 27, '耶路撒冷居住的人和他们的官长，因为不认识基督，也不明白每安息日所读众先知的书，就把基督定了死罪，正应了先知的预言；'),
('CUV', '使徒行传', 44, 13, 28, '虽然查不出他有当死的罪来，还是求彼拉多杀他；'),
('CUV', '使徒行传', 44, 13, 29, '既成就了经上指著他所记的一切话，就把他从木头上取下来，放在坟墓里。'),
('CUV', '使徒行传', 44, 13, 30, '神却叫他从死里复活。'),
('CUV', '使徒行传', 44, 13, 31, '那从加利利同他上耶路撒冷的人多日看见他，这些人如今在民间是他的见证。'),
('CUV', '使徒行传', 44, 13, 32, '我们也报好信息给你们，就是那应许祖宗的话，'),
('CUV', '使徒行传', 44, 13, 33, '神已经向我们这作儿女的应验，叫耶稣复活了。正如诗篇第二篇上记著说：你是我的儿子，我今日生你。'),
('CUV', '使徒行传', 44, 13, 34, '论到神叫他从死里复活，不再归于朽坏，就这样说：我必将所应许大卫那圣洁、可靠的恩典赐给你们。'),
('CUV', '使徒行传', 44, 13, 35, '又有一篇上说：你必不叫你的圣者见朽坏。'),
('CUV', '使徒行传', 44, 13, 36, '大卫在世的时候遵行了神的旨意，就睡了（或作：大卫按神的旨意服事了他那一世的人，就睡了），归到他祖宗那里，已见朽坏；'),
('CUV', '使徒行传', 44, 13, 37, '惟独神所复活的，他并未见朽坏。'),
('CUV', '使徒行传', 44, 13, 38, '所以，弟兄们，你们当晓得：赦罪的道是由这人传给你们的。'),
('CUV', '使徒行传', 44, 13, 39, '你们靠摩西的律法，在一切不得称义的事上信靠这人，就都得称义了。'),
('CUV', '使徒行传', 44, 13, 40, '所以，你们务要小心，免得先知书上所说的临到你们。'),
('CUV', '使徒行传', 44, 13, 41, '主说：你们这轻慢的人要观看，要惊奇，要灭亡；因为在你们的时候，我行一件事，虽有人告诉你们，你们总是不信。'),
('CUV', '使徒行传', 44, 13, 42, '他们出会堂的时候，众人请他们到下安息日再讲这话给他们听。'),
('CUV', '使徒行传', 44, 13, 43, '散会以后，犹太人和敬虔进犹太教的人多有跟从保罗、巴拿巴的。二人对他们讲道，劝他们务要恒久在神的恩中。'),
('CUV', '使徒行传', 44, 13, 44, '到下安息日，合城的人几乎都来聚集，要听神的道。'),
('CUV', '使徒行传', 44, 13, 45, '但犹太人看见人这样多，就满心嫉妒，硬驳保罗所说的话，并且毁谤。'),
('CUV', '使徒行传', 44, 13, 46, '保罗和巴拿巴放胆说：神的道先讲给你们原是应当的；只因你们弃绝这道，断定自己不配得永生，我们就转向外邦人去。'),
('CUV', '使徒行传', 44, 13, 47, '因为主曾这样吩咐我们说：我已经立你作外邦人的光，叫你施行救恩，直到地极。'),
('CUV', '使徒行传', 44, 13, 48, '外邦人听见这话，就欢喜了，赞美神的道；凡预定得永生的人都信了。'),
('CUV', '使徒行传', 44, 13, 49, '于是主的道传遍了那一带地方。'),
('CUV', '使徒行传', 44, 13, 50, '但犹太人挑唆虔敬、尊贵的妇女和城内有名望的人，逼迫保罗、巴拿巴，将他们赶出境外。'),
('CUV', '使徒行传', 44, 13, 51, '二人对著众人跺下脚上的尘土，就往以哥念去了。'),
('CUV', '使徒行传', 44, 13, 52, '门徒满心喜乐，又被圣灵充满。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 14, 1, '二人在以哥念同进犹太人的会堂，在那里讲的，叫犹太人和希利尼人信的很多。'),
('CUV', '使徒行传', 44, 14, 2, '但那不顺从的犹太人耸动外邦人，叫他们心里恼恨弟兄。'),
('CUV', '使徒行传', 44, 14, 3, '二人在那里住了多日，倚靠主放胆讲道；主藉他们的手施行神迹奇事，证明他的恩道。'),
('CUV', '使徒行传', 44, 14, 4, '城里的众人就分了党，有附从犹太人的，有附从使徒的。'),
('CUV', '使徒行传', 44, 14, 5, '那时，外邦人和犹太人，并他们的官长，一齐拥上来，要凌辱使徒，用石头打他们。'),
('CUV', '使徒行传', 44, 14, 6, '使徒知道了，就逃往吕高尼的路司得、特庇两个城和周围地方去，'),
('CUV', '使徒行传', 44, 14, 7, '在那里传福音。'),
('CUV', '使徒行传', 44, 14, 8, '路司得城里坐著一个两脚无力的人，生来是瘸腿的，从来没有走过。'),
('CUV', '使徒行传', 44, 14, 9, '他听保罗讲道，保罗定睛看他，见他有信心，可得痊愈，'),
('CUV', '使徒行传', 44, 14, 10, '就大声说：你起来，两脚站直！那人就跳起来，而且行走。'),
('CUV', '使徒行传', 44, 14, 11, '众人看见保罗所做的事，就用吕高尼的话大声说：有神藉著人形降临在我们中间了。'),
('CUV', '使徒行传', 44, 14, 12, '于是称巴拿巴为丢斯，称保罗为希耳米，因为他说话领首。'),
('CUV', '使徒行传', 44, 14, 13, '有城外丢斯庙的祭司牵著牛，拿著花圈，来到门前，要同众人向使徒献祭。'),
('CUV', '使徒行传', 44, 14, 14, '巴拿巴、保罗二使徒听见，就撕开衣裳，跳进众人中间，喊著说：'),
('CUV', '使徒行传', 44, 14, 15, '诸君，为甚么做这事呢？我们也是人，性情和你们一样。我们传福音给你们，是叫你们离弃这些虚妄，归向那创造天、地、海、和其中万物的永生神。'),
('CUV', '使徒行传', 44, 14, 16, '他在从前的世代，任凭万国各行其道；'),
('CUV', '使徒行传', 44, 14, 17, '然而为自己未尝不显出证据来，就如常施恩惠，从天降雨，赏赐丰年，叫你们饮食饱足，满心喜乐。'),
('CUV', '使徒行传', 44, 14, 18, '二人说了这些话，仅仅的拦住众人不献祭与他们。'),
('CUV', '使徒行传', 44, 14, 19, '但有些犹太人从安提阿和以哥念来，挑唆众人，就用石头打保罗，以为他是死了，便拖到城外。'),
('CUV', '使徒行传', 44, 14, 20, '门徒正围著他，他就起来，走进城去。第二天，同巴拿巴往特庇去，'),
('CUV', '使徒行传', 44, 14, 21, '对那城里的人传了福音，使好些人作门徒，就回路司得、以哥念、安提阿去，'),
('CUV', '使徒行传', 44, 14, 22, '坚固门徒的心，劝他们恒守所信的道；又说：我们进入神的国，必须经历许多艰难。'),
('CUV', '使徒行传', 44, 14, 23, '二人在各教会中选立了长老，又禁食祷告，就把他们交托所信的主。'),
('CUV', '使徒行传', 44, 14, 24, '二人经过彼西底，来到旁非利亚。'),
('CUV', '使徒行传', 44, 14, 25, '在别加讲了道，就下亚大利去，'),
('CUV', '使徒行传', 44, 14, 26, '从那里坐船，往安提阿去。当初，他们被众人所托、蒙神之恩，要办现在所做之工，就是在这地方。'),
('CUV', '使徒行传', 44, 14, 27, '到了那里，聚集了会众，就述说神藉他们所行的一切事，并神怎样为外邦人开了信道的门。'),
('CUV', '使徒行传', 44, 14, 28, '二人就在那里同门徒住了多日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 15, 1, '有几个人从犹太下来，教训弟兄们说：你们若不按摩西的规条受割礼，不能得救。'),
('CUV', '使徒行传', 44, 15, 2, '保罗、巴拿巴与他们大大的分争辩论；众门徒就定规，叫保罗、巴拿巴和本会中几个人，为所辩论的，上耶路撒冷去见使徒和长老。'),
('CUV', '使徒行传', 44, 15, 3, '于是教会送他们起行。他们经过腓尼基、撒玛利亚，随处传说外邦人归主的事，叫众弟兄都甚欢喜。'),
('CUV', '使徒行传', 44, 15, 4, '到了耶路撒冷，教会和使徒并长老都接待他们，他们就述说神同他们所行的一切事。'),
('CUV', '使徒行传', 44, 15, 5, '惟有几个信徒、是法利赛教门的人，起来说：必须给外邦人行割礼，吩咐他们遵守摩西的律法。'),
('CUV', '使徒行传', 44, 15, 6, '使徒和长老聚会商议这事；'),
('CUV', '使徒行传', 44, 15, 7, '辩论已经多了，彼得就起来，说：诸位弟兄，你们知道神早已在你们中间拣选了我，叫外邦人从我口中得听福音之道，而且相信。'),
('CUV', '使徒行传', 44, 15, 8, '知道人心的神也为他们作了见证，赐圣灵给他们，正如给我们一样；'),
('CUV', '使徒行传', 44, 15, 9, '又藉著信洁净了他们的心，并不分他们我们。'),
('CUV', '使徒行传', 44, 15, 10, '现在为甚么试探神，要把我们祖宗和我们所不能负的轭放在门徒的颈项上呢？'),
('CUV', '使徒行传', 44, 15, 11, '我们得救乃是因主耶稣的恩，和他们一样，这是我们所信的。'),
('CUV', '使徒行传', 44, 15, 12, '众人都默默无声，听巴拿巴和保罗述说神藉他们在外邦人中所行的神迹奇事。'),
('CUV', '使徒行传', 44, 15, 13, '他们住了声，雅各就说：诸位弟兄，请听我的话。'),
('CUV', '使徒行传', 44, 15, 14, '方才西门述说神当初怎样眷顾外邦人，从他们中间选取百姓归于自己的名下；'),
('CUV', '使徒行传', 44, 15, 15, '众先知的话也与这意思相合。'),
('CUV', '使徒行传', 44, 15, 16, '正如经上所写的：此后，我要回来，重新修造大卫倒塌的帐幕，把那破坏的重新修造建立起来，'),
('CUV', '使徒行传', 44, 15, 17, '叫余剩的人，就是凡称为我名下的外邦人，都寻求主。'),
('CUV', '使徒行传', 44, 15, 18, '这话是从创世以来，显明这事的主说的。'),
('CUV', '使徒行传', 44, 15, 19, '所以据我的意见，不可难为那归服神的外邦人；'),
('CUV', '使徒行传', 44, 15, 20, '只要写信，吩咐他们禁戒偶像的污秽和奸淫，并勒死的牲畜和血。'),
('CUV', '使徒行传', 44, 15, 21, '因为从古以来，摩西的书在各城有人传讲，每逢安息日，在会堂里诵读。'),
('CUV', '使徒行传', 44, 15, 22, '那时，使徒和长老并全教会定意从他们中间拣选人，差他们和保罗、巴拿巴同往安提阿去；所拣选的就是称呼巴撒巴的犹大和西拉。这两个人在弟兄中是作首领的。'),
('CUV', '使徒行传', 44, 15, 23, '于是写信交付他们，内中说：使徒和作长老的弟兄们问安提阿、叙利亚、基利家外邦众弟兄的安。'),
('CUV', '使徒行传', 44, 15, 24, '我们听说，有几个人从我们这里出去，用言语搅扰你们，惑乱你们的心。（有古卷在此有：你们必须受割礼，守摩西的律法。）其实我们并没有吩咐他们。'),
('CUV', '使徒行传', 44, 15, 25, '所以，我们同心定意，拣选几个人，差他们同我们所亲爱的巴拿巴和保罗往你们那里去。'),
('CUV', '使徒行传', 44, 15, 26, '这二人是为我主耶稣基督的名不顾性命的。'),
('CUV', '使徒行传', 44, 15, 27, '我们就差了犹大和西拉，他们也要亲口诉说这些事。'),
('CUV', '使徒行传', 44, 15, 28, '因为圣灵和我们定意不将别的重担放在你们身上；惟有几件事是不可少的，'),
('CUV', '使徒行传', 44, 15, 29, '就是禁戒祭偶像的物和血，并勒死的牲畜和奸淫。这几件你们若能自己禁戒不犯就好了。愿你们平安！'),
('CUV', '使徒行传', 44, 15, 30, '他们既奉了差遣，就下安提阿去，聚集众人，交付书信。'),
('CUV', '使徒行传', 44, 15, 31, '众人念了，因为信上安慰的话就欢喜了。'),
('CUV', '使徒行传', 44, 15, 32, '犹大和西拉也是先知，就用许多话劝勉弟兄，坚固他们。'),
('CUV', '使徒行传', 44, 15, 33, '住了些日子，弟兄们打发他们平平安安的回到差遣他们的人那里去。（有古卷在此有：'),
('CUV', '使徒行传', 44, 15, 34, '惟有西拉定意仍住在那里。）'),
('CUV', '使徒行传', 44, 15, 35, '但保罗和巴拿巴仍住在安提阿，和许多别人一同教训人，传主的道。'),
('CUV', '使徒行传', 44, 15, 36, '过了些日子，保罗对巴拿巴说：我们可以回到从前宣传主道的各城，看望弟兄们景况如何。'),
('CUV', '使徒行传', 44, 15, 37, '巴拿巴有意要带称呼马可的约翰同去；'),
('CUV', '使徒行传', 44, 15, 38, '但保罗因为马可从前在旁非利亚离开他们，不和他们同去做工，就以为不可带他去。'),
('CUV', '使徒行传', 44, 15, 39, '于是二人起了争论，甚至彼此分开。巴拿巴带著马可，坐船往居比路去；'),
('CUV', '使徒行传', 44, 15, 40, '保罗拣选了西拉，也出去，蒙弟兄们把他交于主的恩中。'),
('CUV', '使徒行传', 44, 15, 41, '他就走遍叙利亚、基利家，坚固众教会。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 16, 1, '保罗来到特庇，又到路司得。在那里有一个门徒，名叫提摩太，是信主之犹太妇人的儿子，他父亲却是希利尼人。'),
('CUV', '使徒行传', 44, 16, 2, '路司得和以哥念的弟兄都称赞他。'),
('CUV', '使徒行传', 44, 16, 3, '保罗要带他同去，只因那些地方的犹太人都知道他父亲是希利尼人，就给他行了割礼。'),
('CUV', '使徒行传', 44, 16, 4, '他们经过各城，把耶路撒冷使徒和长老所定的条规交给门徒遵守。'),
('CUV', '使徒行传', 44, 16, 5, '于是众教会信心越发坚固，人数天天加增。'),
('CUV', '使徒行传', 44, 16, 6, '圣灵既然禁止他们在亚西亚讲道，他们就经过弗吕家、加拉太一带地方。'),
('CUV', '使徒行传', 44, 16, 7, '到了每西亚的边界，他们想要往庇推尼去，耶稣的灵却不许。'),
('CUV', '使徒行传', 44, 16, 8, '他们就越过每西亚，下到特罗亚去。'),
('CUV', '使徒行传', 44, 16, 9, '在夜间有异象现与保罗。有一个马其顿人站著求他说：请你过到马其顿来帮助我们。'),
('CUV', '使徒行传', 44, 16, 10, '保罗既看见这异象，我们随即想要往马其顿去，以为神召我们传福音给那里的人听。'),
('CUV', '使徒行传', 44, 16, 11, '于是从特罗亚开船，一直行到撒摩特喇，第二天到了尼亚波利。'),
('CUV', '使徒行传', 44, 16, 12, '从那里来到腓立比，就是马其顿这一方的头一个城，也是罗马的驻防城。我们在这城里住了几天。'),
('CUV', '使徒行传', 44, 16, 13, '当安息日，我们出城门，到了河边，知道那里有一个祷告的地方，我们就坐下对那聚会的妇女讲道。'),
('CUV', '使徒行传', 44, 16, 14, '有一个卖紫色布疋的妇人，名叫吕底亚，是推雅推喇城的人，素来敬拜神。他听见了，主就开导他的心，叫他留心听保罗所讲的话。'),
('CUV', '使徒行传', 44, 16, 15, '他和他一家既领了洗，便求我们说：你们若以为我是真信主的（或作：你们若以为我是忠心事主的），请到我家里来住。于是强留我们。'),
('CUV', '使徒行传', 44, 16, 16, '后来，我们往那祷告的地方去。有一个使女迎著面来，他被巫鬼所附，用法术，叫他主人们大得财利。'),
('CUV', '使徒行传', 44, 16, 17, '他跟随保罗和我们，喊著说：这些人是至高神的仆人，对你们传说救人的道。'),
('CUV', '使徒行传', 44, 16, 18, '他一连多日这样喊叫，保罗就心中厌烦，转身对那鬼说：我奉耶稣基督的名，吩咐你从他身上出来！那鬼当时就出来了。'),
('CUV', '使徒行传', 44, 16, 19, '使女的主人们见得利的指望没有了，便揪住保罗和西拉，拉他们到市上去见首领；'),
('CUV', '使徒行传', 44, 16, 20, '又带到官长面前说：这些人原是犹太人，竟骚扰我们的城，'),
('CUV', '使徒行传', 44, 16, 21, '传我们罗马人所不可受不可行的规矩。'),
('CUV', '使徒行传', 44, 16, 22, '众人就一同起来攻击他们。官长吩咐剥了他们的衣裳，用棍打；'),
('CUV', '使徒行传', 44, 16, 23, '打了许多棍，便将他们下在监里，嘱咐禁卒严紧看守。'),
('CUV', '使徒行传', 44, 16, 24, '禁卒领了这样的命，就把他们下在内监里，两脚上了木狗。'),
('CUV', '使徒行传', 44, 16, 25, '约在半夜，保罗和西拉祷告，唱诗赞美神，众囚犯也侧耳而听。'),
('CUV', '使徒行传', 44, 16, 26, '忽然，地大震动，甚至监牢的地基都摇动了，监门立刻全开，众囚犯的锁链也都松开了。'),
('CUV', '使徒行传', 44, 16, 27, '禁卒一醒，看见监门全开，以为囚犯已经逃走，就拔刀要自杀。'),
('CUV', '使徒行传', 44, 16, 28, '保罗大声呼叫说：不要伤害自己！我们都在这里。'),
('CUV', '使徒行传', 44, 16, 29, '禁卒叫人拿灯来，就跳进去，战战兢兢的俯伏在保罗、西拉面前；'),
('CUV', '使徒行传', 44, 16, 30, '又领他们出来，说：二位先生，我当怎样行才可以得救？'),
('CUV', '使徒行传', 44, 16, 31, '他们说：当信主耶稣，你和你一家都必得救。'),
('CUV', '使徒行传', 44, 16, 32, '他们就把主的道讲给他和他全家的人听。'),
('CUV', '使徒行传', 44, 16, 33, '当夜，就在那时候，禁卒把他们带去，洗他们的伤；他和属乎他的人立时都受了洗。'),
('CUV', '使徒行传', 44, 16, 34, '于是禁卒领他们上自己家里去，给他们摆上饭。他和全家，因为信了神，都很喜乐。'),
('CUV', '使徒行传', 44, 16, 35, '到了天亮，官长打发差役来，说：释放那两个人罢。'),
('CUV', '使徒行传', 44, 16, 36, '禁卒就把这话告诉保罗说：官长打发人来叫释放你们，如今可以出监，平平安安的去罢。'),
('CUV', '使徒行传', 44, 16, 37, '保罗却说：我们是罗马人，并没有定罪，他们就在众人面前打了我们，又把我们下在监里，现在要私下撵我们出去么？这是不行的。叫他们自己来领我们出去罢！'),
('CUV', '使徒行传', 44, 16, 38, '差役把这话回禀官长。官长听见他们是罗马人，就害怕了，'),
('CUV', '使徒行传', 44, 16, 39, '于是来劝他们，领他们出来，请他们离开那城。'),
('CUV', '使徒行传', 44, 16, 40, '二人出了监，往吕底亚家里去；见了弟兄们，劝慰他们一番，就走了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 17, 1, '保罗和西拉经过暗妃波里、亚波罗尼亚，来到帖撒罗尼迦，在那里有犹太人的会堂。'),
('CUV', '使徒行传', 44, 17, 2, '保罗照他素常的规矩进去，一连三个安息日，本著圣经与他们辩论，'),
('CUV', '使徒行传', 44, 17, 3, '讲解陈明基督必须受害，从死里复活；又说：我所传与你们的这位耶稣就是基督。'),
('CUV', '使徒行传', 44, 17, 4, '他们中间有些人听了劝，就附从保罗和西拉，并有许多虔敬的希利尼人，尊贵的妇女也不少。'),
('CUV', '使徒行传', 44, 17, 5, '但那不信的犹太人心里嫉妒，招聚了些市井匪类，搭伙成群，耸动合城的人闯进耶孙的家，要将保罗、西拉带到百姓那里。'),
('CUV', '使徒行传', 44, 17, 6, '找不著他们，就把耶孙和几个弟兄拉到地方官那里，喊叫说：那搅乱天下的也到这里来了，'),
('CUV', '使徒行传', 44, 17, 7, '耶孙收留他们。这些人都违背该撒的命令，说另有一个王耶稣。'),
('CUV', '使徒行传', 44, 17, 8, '众人和地方官听见这话，就惊慌了；'),
('CUV', '使徒行传', 44, 17, 9, '于是取了耶孙和其余之人的保状，就释放了他们。'),
('CUV', '使徒行传', 44, 17, 10, '弟兄们随即在夜间打发保罗和西拉往庇哩亚去。二人到了，就进入犹太人的会堂。'),
('CUV', '使徒行传', 44, 17, 11, '这地方的人贤于帖撒罗尼迦的人，甘心领受这道，天天考查圣经，要晓得这道是与不是。'),
('CUV', '使徒行传', 44, 17, 12, '所以他们中间多有相信的，又有希利尼尊贵的妇女，男子也不少。'),
('CUV', '使徒行传', 44, 17, 13, '但帖撒罗尼迦的犹太人知道保罗又在庇哩亚传神的道，也就往那里去，耸动搅扰众人。'),
('CUV', '使徒行传', 44, 17, 14, '当时弟兄们便打发保罗往海边去，西拉和提摩太仍住在庇哩亚。'),
('CUV', '使徒行传', 44, 17, 15, '送保罗的人带他到了雅典，既领了保罗的命，叫西拉和提摩太速速到他这里来，就回去了。'),
('CUV', '使徒行传', 44, 17, 16, '保罗在雅典等候他们的时候，看见满城都是偶像，就心里著急；'),
('CUV', '使徒行传', 44, 17, 17, '于是在会堂里与犹太人和虔敬的人，并每日在市上所遇见的人，辩论。'),
('CUV', '使徒行传', 44, 17, 18, '还有以彼古罗和斯多亚两门的学士，与他争论。有的说：这胡言乱语的要说甚么？有的说：他似乎是传说外邦鬼神的。这话是因保罗传讲耶稣与复活的道。'),
('CUV', '使徒行传', 44, 17, 19, '他们就把他带到亚略巴古，说：你所讲的这新道，我们也可以知道么？'),
('CUV', '使徒行传', 44, 17, 20, '因为你有些奇怪的事传到我们耳中，我们愿意知道这些事是甚么意思。'),
('CUV', '使徒行传', 44, 17, 21, '（雅典人和住在那里的客人都不顾别的事，只将新闻说说听听。）'),
('CUV', '使徒行传', 44, 17, 22, '保罗站在亚略巴古当中，说：众位雅典人哪，我看你们凡事很敬畏鬼神。'),
('CUV', '使徒行传', 44, 17, 23, '我游行的时候，观看你们所敬拜的，遇见一座坛，上面写著未识之神。你们所不认识而敬拜的，我现在告诉你们。'),
('CUV', '使徒行传', 44, 17, 24, '创造宇宙和其中万物的神，既是天地的主，就不住人手所造的殿，'),
('CUV', '使徒行传', 44, 17, 25, '也不用人手服事，好像缺少甚么；自己倒将生命、气息、万物，赐给万人。'),
('CUV', '使徒行传', 44, 17, 26, '他从一本（有古卷作血脉）造出万族的人，住在全地上，并且预先定准他们的年限和所住的疆界，'),
('CUV', '使徒行传', 44, 17, 27, '要叫他们寻求神，或者可以揣摩而得，其实他离我们各人不远；'),
('CUV', '使徒行传', 44, 17, 28, '我们生活、动作、存留，都在乎他。就如你们作诗的，有人说：我们也是他所生的。'),
('CUV', '使徒行传', 44, 17, 29, '我们既是神所生的，就不当以为神的神性像人用手艺、心思所雕刻的金、银、石。'),
('CUV', '使徒行传', 44, 17, 30, '世人蒙昧无知的时候，神并不监察，如今却吩咐各处的人都要悔改。'),
('CUV', '使徒行传', 44, 17, 31, '因为他已经定了日子，要藉著他所设立的人按公义审判天下，并且叫他从死里复活，给万人作可信的凭据。'),
('CUV', '使徒行传', 44, 17, 32, '众人听见从死里复活的话，就有讥诮他的；又有人说：我们再听你讲这个罢！'),
('CUV', '使徒行传', 44, 17, 33, '于是保罗从他们当中出去了。'),
('CUV', '使徒行传', 44, 17, 34, '但有几个人贴近他，信了主，其中有亚略巴古的官丢尼修，并一个妇人，名叫大马哩，还有别人一同信从。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 18, 1, '这事以后，保罗离了雅典，来到哥林多。'),
('CUV', '使徒行传', 44, 18, 2, '遇见一个犹太人，名叫亚居拉，他生在本都；因为革老丢命犹太人都离开罗马，新近带著妻百基拉，从义大利来。保罗就投奔了他们。'),
('CUV', '使徒行传', 44, 18, 3, '他们本是制造帐棚为业。保罗因与他们同业，就和他们同住做工。'),
('CUV', '使徒行传', 44, 18, 4, '每逢安息日，保罗在会堂里辩论，劝化犹太人和希利尼人。'),
('CUV', '使徒行传', 44, 18, 5, '西拉和提摩太从马其顿来的时候，保罗为道迫切，向犹太人证明耶稣是基督。'),
('CUV', '使徒行传', 44, 18, 6, '他们既抗拒、毁谤，保罗就抖著衣裳，说：你们的罪（原文作血）归到你们自己头上，与我无干（原文是我却干净）。从今以后，我要往外邦人那里去。'),
('CUV', '使徒行传', 44, 18, 7, '于是离开那里，到了一个人的家中；这人名叫提多犹士都，是敬拜神的，他的家靠近会堂。'),
('CUV', '使徒行传', 44, 18, 8, '管会堂的基利司布和全家都信了主，还有许多哥林多人听了，就相信受洗。'),
('CUV', '使徒行传', 44, 18, 9, '夜间，主在异象中对保罗说：不要怕，只管讲，不要闭口，'),
('CUV', '使徒行传', 44, 18, 10, '有我与你同在，必没有人下手害你，因为在这城里我有许多的百姓。'),
('CUV', '使徒行传', 44, 18, 11, '保罗在那里住了一年零六个月，将神的道教训他们。'),
('CUV', '使徒行传', 44, 18, 12, '到迦流作亚该亚方伯的时候，犹太人同心起来攻击保罗，拉他到公堂，'),
('CUV', '使徒行传', 44, 18, 13, '说：这个人劝人不按著律法敬拜神。'),
('CUV', '使徒行传', 44, 18, 14, '保罗刚要开口，迦流就对犹太人说：你们这些犹太人！如果是为冤枉或奸恶的事，我理当耐性听你们。'),
('CUV', '使徒行传', 44, 18, 15, '但所争论的，若是关乎言语、名目，和你们的律法，你们自己去办罢！这样的事我不愿意审问；'),
('CUV', '使徒行传', 44, 18, 16, '就把他们撵出公堂。'),
('CUV', '使徒行传', 44, 18, 17, '众人便揪住管会堂的所提尼，在堂前打他。这些事迦流都不管。'),
('CUV', '使徒行传', 44, 18, 18, '保罗又住了多日，就辞别了弟兄，坐船往叙利亚去；百基拉、亚居拉和他同去。他因为许过愿，就在坚革哩剪了头发。'),
('CUV', '使徒行传', 44, 18, 19, '到了以弗所，保罗就把他们留在那里，自己进了会堂，和犹太人辩论。'),
('CUV', '使徒行传', 44, 18, 20, '众人请他多住些日子，他却不允，'),
('CUV', '使徒行传', 44, 18, 21, '就辞别他们，说：神若许我，我还要回到你们这里；于是开船离了以弗所。'),
('CUV', '使徒行传', 44, 18, 22, '在该撒利亚下了船，就上耶路撒冷去问教会安，随后下安提阿去。'),
('CUV', '使徒行传', 44, 18, 23, '住了些日子，又离开那里，挨次经过加拉太和弗吕家地方，坚固众门徒。'),
('CUV', '使徒行传', 44, 18, 24, '有一个犹太人，名叫亚波罗，来到以弗所。他生在亚力山太，是有学问（或作：口才）的，最能讲解圣经。'),
('CUV', '使徒行传', 44, 18, 25, '这人已经在主的道上受了教训，心里火热，将耶稣的事详细讲论教训人；只是他单晓得约翰的洗礼。'),
('CUV', '使徒行传', 44, 18, 26, '他在会堂里放胆讲道；百基拉，亚居拉听见，就接他来，将神的道给他讲解更加详细。'),
('CUV', '使徒行传', 44, 18, 27, '他想要往亚该亚去，弟兄们就勉励他，并写信请门徒接待他（或作：弟兄们就写信劝门徒接待他）。他到了那里，多帮助那蒙恩信主的人，'),
('CUV', '使徒行传', 44, 18, 28, '在众人面前极有能力驳倒犹太人，引圣经证明耶稣是基督。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 19, 1, '亚波罗在哥林多的时候，保罗经过了上边一带地方，就来到以弗所；在那里遇见几个门徒，'),
('CUV', '使徒行传', 44, 19, 2, '问他们说：你们信的时候受了圣灵没有？他们回答说：没有，也未曾听见有圣灵赐下来。'),
('CUV', '使徒行传', 44, 19, 3, '保罗说：这样，你们受的是甚么洗呢？他们说：是约翰的洗。'),
('CUV', '使徒行传', 44, 19, 4, '保罗说：约翰所行的是悔改的洗，告诉百姓当信那在他以后要来的，就是耶稣。'),
('CUV', '使徒行传', 44, 19, 5, '他们听见这话，就奉主耶稣的名受洗。'),
('CUV', '使徒行传', 44, 19, 6, '保罗按手在他们头上，圣灵便降在他们身上，他们就说方言，又说预言（或作：又讲道）'),
('CUV', '使徒行传', 44, 19, 7, '一共约有十二个人。'),
('CUV', '使徒行传', 44, 19, 8, '保罗进会堂，放胆讲道，一连三个月，辩论神国的事，劝化众人。'),
('CUV', '使徒行传', 44, 19, 9, '后来，有些人心里刚硬不信，在众人面前毁谤这道，保罗就离开他们，也叫门徒与他们分离，便在推喇奴的学房天天辩论。'),
('CUV', '使徒行传', 44, 19, 10, '这样有两年之久，叫一切住在亚西亚的，无论是犹太人，是希利尼人，都听见主的道。'),
('CUV', '使徒行传', 44, 19, 11, '神藉保罗的手行了些非常的奇事；'),
('CUV', '使徒行传', 44, 19, 12, '甚至有人从保罗身上拿手巾或围裙放在病人身上，病就退了，恶鬼也出去了。'),
('CUV', '使徒行传', 44, 19, 13, '那时，有几个游行各处、念咒赶鬼的犹太人，向那被恶鬼附的人擅自称主耶稣的名，说：我奉保罗所传的耶稣勒令你们出来！'),
('CUV', '使徒行传', 44, 19, 14, '做这事的，有犹太祭司长士基瓦的七个儿子。'),
('CUV', '使徒行传', 44, 19, 15, '恶鬼回答他们说：耶稣我认识，保罗我也知道。你们却是谁呢？'),
('CUV', '使徒行传', 44, 19, 16, '恶鬼所附的人就跳在他们身上，胜了其中二人，制伏他们，叫他们赤著身子受了伤，从那房子里逃出去了。'),
('CUV', '使徒行传', 44, 19, 17, '凡住在以弗所的，无论是犹太人，是希利尼人，都知道这事，也都惧怕；主耶稣的名从此就尊大了。'),
('CUV', '使徒行传', 44, 19, 18, '那已经信的，多有人来承认诉说自己所行的事。'),
('CUV', '使徒行传', 44, 19, 19, '平素行邪术的，也有许多人把书拿来，堆积在众人面前焚烧。他们算计书价，便知道共合五万块钱。'),
('CUV', '使徒行传', 44, 19, 20, '主的道大大兴旺，而且得胜，就是这样。'),
('CUV', '使徒行传', 44, 19, 21, '这些事完了，保罗心里定意经过了马其顿、亚该亚，就往耶路撒冷去；又说：我到了那里以后，也必须往罗马去看看。'),
('CUV', '使徒行传', 44, 19, 22, '于是从帮助他的人中打发提摩太、以拉都二人往马其顿去，自己暂时等在亚西亚。'),
('CUV', '使徒行传', 44, 19, 23, '那时，因为这道起的扰乱不小。'),
('CUV', '使徒行传', 44, 19, 24, '有一个银匠，名叫底米丢，是制造亚底米神银龛的，他使这样手艺人生意发达。'),
('CUV', '使徒行传', 44, 19, 25, '他聚集他们和同行的工人，说：众位，你们知道我们是倚靠这生意发财。'),
('CUV', '使徒行传', 44, 19, 26, '这保罗不但在以弗所，也几乎在亚西亚全地，引诱迷惑许多人，说：人手所做的，不是神。这是你们所看见所听见的。'),
('CUV', '使徒行传', 44, 19, 27, '这样，不独我们这事业被人藐视，就是大女神亚底米的庙也要被人轻忽，连亚西亚全地和普天下所敬拜的大女神之威荣也要消灭了。'),
('CUV', '使徒行传', 44, 19, 28, '众人听见，就怒气填胸，喊著说：大哉，以弗所人的亚底米阿！'),
('CUV', '使徒行传', 44, 19, 29, '满城都轰动起来。众人拿住与保罗同行的马其顿人该犹和亚里达古，齐心拥进戏园里去。'),
('CUV', '使徒行传', 44, 19, 30, '保罗想要进去，到百姓那里，门徒却不许他去。'),
('CUV', '使徒行传', 44, 19, 31, '还有亚西亚几位首领，是保罗的朋友，打发人来劝他，不要冒险到戏园里去。'),
('CUV', '使徒行传', 44, 19, 32, '聚集的人纷纷乱乱，有喊叫这个的，有喊叫那个的，大半不知道是为甚么聚集。'),
('CUV', '使徒行传', 44, 19, 33, '有人把亚力山大从众人中带出来，犹太人推他往前，亚力山大就摆手，要向百姓分诉；'),
('CUV', '使徒行传', 44, 19, 34, '只因他们认出他是犹太人，就大家同声喊著说：大哉！以弗所人的亚底米阿。如此约有两小时。'),
('CUV', '使徒行传', 44, 19, 35, '那城里的书记安抚了众人，就说：以弗所人哪，谁不知道以弗所人的城是看守大亚底米的庙和从丢斯那里落下来的像呢？'),
('CUV', '使徒行传', 44, 19, 36, '这事既是驳不倒的，你们就当安静，不可造次。'),
('CUV', '使徒行传', 44, 19, 37, '你们把这些人带来，他们并没有偷窃庙中之物，也没有谤讟我们的女神。'),
('CUV', '使徒行传', 44, 19, 38, '若是底米丢和他同行的人有控告人的事，自有放告的日子（或作：自有公堂），也有方伯可以彼此对告。'),
('CUV', '使徒行传', 44, 19, 39, '你们若问别的事，就可以照常例聚集断定。'),
('CUV', '使徒行传', 44, 19, 40, '今日的扰乱本是无缘无故，我们难免被查问。论到这样聚众，我们也说不出所以然来。'),
('CUV', '使徒行传', 44, 19, 41, '说了这话，便叫众人散去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 20, 1, '乱定之后，保罗请门徒来，劝勉他们，就辞别起行，往马其顿去。'),
('CUV', '使徒行传', 44, 20, 2, '走遍了那一带地方，用许多话劝勉门徒。（或作：众人），然后来到希腊。'),
('CUV', '使徒行传', 44, 20, 3, '在那里住了三个月，将要坐船往叙利亚去，犹太人设计要害他，他就定意从马其顿回去。'),
('CUV', '使徒行传', 44, 20, 4, '同他到亚西亚去的，有庇哩亚人毕罗斯的儿子所巴特，帖撒罗尼迦人亚里达古和西公都，还有特庇人该犹，并提摩太，又有亚西亚人推基古和特罗非摩。'),
('CUV', '使徒行传', 44, 20, 5, '这些人先走，在特罗亚等候我们。'),
('CUV', '使徒行传', 44, 20, 6, '过了除酵的日子，我们从腓立比开船，五天到了特罗亚，和他们相会，在那里住了七天。'),
('CUV', '使徒行传', 44, 20, 7, '七日的第一日，我们聚会擘饼的时候，保罗因为要次日起行，就与他们讲论，直讲到半夜。'),
('CUV', '使徒行传', 44, 20, 8, '我们聚会的那座楼上，有好些灯烛。'),
('CUV', '使徒行传', 44, 20, 9, '有一个少年人，名叫犹推古，坐在窗台上，困倦沉睡。保罗讲了多时，少年人睡熟了，就从三层楼上掉下去；扶起他来，已经死了。'),
('CUV', '使徒行传', 44, 20, 10, '保罗下去，伏在他身上，抱著他，说：你们不要发慌，他的灵魂还在身上。'),
('CUV', '使徒行传', 44, 20, 11, '保罗又上去，擘饼，吃了，谈论许久，直到天亮，这才走了。'),
('CUV', '使徒行传', 44, 20, 12, '有人把那童子活活的领来，得的安慰不小。'),
('CUV', '使徒行传', 44, 20, 13, '我们先上船，开往亚朔去，意思要在那里接保罗；因为他是这样安排的，他自己打算要步行。'),
('CUV', '使徒行传', 44, 20, 14, '他既在亚朔与我们相会，我们就接他上船，来到米推利尼。'),
('CUV', '使徒行传', 44, 20, 15, '从那里开船，次日到了基阿的对面；又次日，在撒摩靠岸；又次日，来到米利都。'),
('CUV', '使徒行传', 44, 20, 16, '乃因保罗早已定意越过以弗所，免得在亚西亚耽延，他急忙前走，巴不得赶五旬节能到耶路撒冷。'),
('CUV', '使徒行传', 44, 20, 17, '保罗从米利都打发人往以弗所去，请教会的长老来。'),
('CUV', '使徒行传', 44, 20, 18, '他们来了，保罗就说：你们知道，自从我到亚西亚的日子以来，在你们中间始终为人如何，'),
('CUV', '使徒行传', 44, 20, 19, '服事主，凡事谦卑，眼中流泪，又因犹太人的谋害，经历试炼。'),
('CUV', '使徒行传', 44, 20, 20, '你们也知道，凡与你们有益的，我没有一样避讳不说的，或在众人面前，或在各人家里，我都教导你们；'),
('CUV', '使徒行传', 44, 20, 21, '又对犹太人和希利尼人证明当向神悔改，信靠我主耶稣基督。'),
('CUV', '使徒行传', 44, 20, 22, '现在我往耶路撒冷去，心甚迫切（原文是心被捆绑），不知道在那里要遇见甚么事；'),
('CUV', '使徒行传', 44, 20, 23, '但知道圣灵在各城里向我指证，说有捆锁与患难等待我。'),
('CUV', '使徒行传', 44, 20, 24, '我却不以性命为念，也不看为宝贵，只要行完我的路程，成就我从主耶稣所领受的职事，证明神恩惠的福音。'),
('CUV', '使徒行传', 44, 20, 25, '我素常在你们中间来往，传讲神国的道；如今我晓得，你们以后都不得再见我的面了。'),
('CUV', '使徒行传', 44, 20, 26, '所以我今日向你们证明，你们中间无论何人死亡，罪不在我身上（原文是我于众人的血是洁净的）。'),
('CUV', '使徒行传', 44, 20, 27, '因为神的旨意，我并没有一样避讳不传给你们的。'),
('CUV', '使徒行传', 44, 20, 28, '圣灵立你们作全群的监督，你们就当为自己谨慎，也为全群谨慎，牧养神的教会，就是他用自己血所买来的（或作：救赎的）。'),
('CUV', '使徒行传', 44, 20, 29, '我知道，我去之后必有凶暴的豺狼进入你们中间，不爱惜羊群。'),
('CUV', '使徒行传', 44, 20, 30, '就是你们中间，也必有人起来说悖谬的话，要引诱门徒跟从他们。'),
('CUV', '使徒行传', 44, 20, 31, '所以你们应当儆醒，记念我三年之久昼夜不住的流泪、劝戒你们各人。'),
('CUV', '使徒行传', 44, 20, 32, '如今我把你们交托神和他恩惠的道；这道能建立你们，叫你们和一切成圣的人同得基业。'),
('CUV', '使徒行传', 44, 20, 33, '我未曾贪图一个人的金、银、衣服。'),
('CUV', '使徒行传', 44, 20, 34, '我这两只手常供给我和同人的需用，这是你们自己知道的。'),
('CUV', '使徒行传', 44, 20, 35, '我凡事给你们作榜样，叫你们知道应当这样劳苦，扶助软弱的人，又当记念主耶稣的话，说：施比受更为有福。'),
('CUV', '使徒行传', 44, 20, 36, '保罗说完了这话，就跪下同众人祷告。'),
('CUV', '使徒行传', 44, 20, 37, '众人痛哭，抱著保罗的颈项，和他亲嘴。'),
('CUV', '使徒行传', 44, 20, 38, '叫他们最伤心的，就是他说：以后不能再见我的面那句话，于是送他上船去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 21, 1, '我们离别了众人，就开船一直行到哥士。第二天到了罗底，从那里到帕大喇，'),
('CUV', '使徒行传', 44, 21, 2, '遇见一只船要往腓尼基去，就上船起行。'),
('CUV', '使徒行传', 44, 21, 3, '望见居比路，就从南边行过，往叙利亚去，我们就在推罗上岸，因为船要在那里卸货。'),
('CUV', '使徒行传', 44, 21, 4, '找著了门徒，就在那里住了七天。他们被圣灵感动，对保罗说：不要上耶路撒冷去。'),
('CUV', '使徒行传', 44, 21, 5, '过了这几天，我们就起身前行。他们众人同妻子儿女，送我们到城外，我们都跪在岸上祷告，彼此辞别。'),
('CUV', '使徒行传', 44, 21, 6, '我们上了船，他们就回家去了。'),
('CUV', '使徒行传', 44, 21, 7, '我们从推罗行尽了水路，来到多利买，就问那里的弟兄安，和他们同住了一天。'),
('CUV', '使徒行传', 44, 21, 8, '第二天，我们离开那里，来到该撒利亚，就进了传福音的腓利家里，和他同住。他是那七个执事里的一个。'),
('CUV', '使徒行传', 44, 21, 9, '他有四个女儿，都是处女，是说预言的。'),
('CUV', '使徒行传', 44, 21, 10, '我们在那里多住了几天，有一个先知，名叫亚迦布，从犹太下来，'),
('CUV', '使徒行传', 44, 21, 11, '到了我们这里，就拿保罗的腰带捆上自己的手脚，说：圣灵说：犹太人在耶路撒冷，要如此捆绑这腰带的主人，把他交在外邦人手里。'),
('CUV', '使徒行传', 44, 21, 12, '我们和那本地的人听见这话，都苦劝保罗不要上耶路撒冷去。'),
('CUV', '使徒行传', 44, 21, 13, '保罗说：你们为甚么这样痛哭，使我心碎呢？我为主耶稣的名，不但被人捆绑，就是死在耶路撒冷也是愿意的。'),
('CUV', '使徒行传', 44, 21, 14, '保罗既不听劝，我们便住了口，只说：愿主的旨意成就，便了。'),
('CUV', '使徒行传', 44, 21, 15, '过了几日，我们收拾行李上耶路撒冷去。'),
('CUV', '使徒行传', 44, 21, 16, '有该撒利亚的几个门徒和我们同去，带我们到一个久为（久为：或作老）门徒的家里，叫我们与他同住；他名叫拿孙，是居比路人。'),
('CUV', '使徒行传', 44, 21, 17, '到了耶路撒冷，弟兄们欢欢喜喜的接待我们。'),
('CUV', '使徒行传', 44, 21, 18, '第二天，保罗同我们去见雅各；长老们也都在那里。'),
('CUV', '使徒行传', 44, 21, 19, '保罗问了他们安，便将神用他传教，在外邦人中间所行之事，一一的述说了。'),
('CUV', '使徒行传', 44, 21, 20, '他们听见，就归荣耀与神，对保罗说：兄台，你看犹太人中信主的有多少万，并且都为律法热心。'),
('CUV', '使徒行传', 44, 21, 21, '他们听见人说：你教训一切在外邦的犹太人离弃摩西，对他们说：不要给孩子行割礼，也不要遵行条规。'),
('CUV', '使徒行传', 44, 21, 22, '众人必听见你来了，这可怎么办呢？'),
('CUV', '使徒行传', 44, 21, 23, '你就照著我们的话行罢？我们这里有四个人，都有愿在身。'),
('CUV', '使徒行传', 44, 21, 24, '你带他们去，与他们一同行洁净的礼，替他们拿出规费，叫他们得以剃头。这样，众人就可知道，先前所听见你的事都是虚的；并可知道，你自己为人，循规蹈矩，遵行律法。'),
('CUV', '使徒行传', 44, 21, 25, '至于信主的外邦人，我们已经写信拟定，叫他们谨忌那祭偶像之物，和血，并勒死的牲畜，与奸淫。'),
('CUV', '使徒行传', 44, 21, 26, '于是保罗带著那四个人，第二天与他们一同行了洁净的礼，进了殿，报明洁净的日期满足，只等祭司为他们各人献祭。'),
('CUV', '使徒行传', 44, 21, 27, '那七日将完，从亚西亚来的犹太人看见保罗在殿里，就耸动了众人，下手拿他，'),
('CUV', '使徒行传', 44, 21, 28, '喊叫说：以色列人来帮助，这就是在各处教训众人蹧践我们百姓和律法，并这地方的。他又带著希利尼人进殿，污秽了这圣地。'),
('CUV', '使徒行传', 44, 21, 29, '这话是因他们曾看见以弗所人特罗非摩同保罗在城里，以为保罗带他'),
('CUV', '使徒行传', 44, 21, 30, '合城都震动，百姓一齐跑来，拿住保罗，拉他出殿，殿门立刻都关了。'),
('CUV', '使徒行传', 44, 21, 31, '他们正想要杀他，有人报信给营里的千夫长说：耶路撒冷合城都乱了。'),
('CUV', '使徒行传', 44, 21, 32, '千夫长立时带著兵丁和几个百夫长，跑下去到他们那里。他们见了千夫长和兵丁，就止住不打保罗。'),
('CUV', '使徒行传', 44, 21, 33, '于是千夫长上前拿住他，吩咐用两条铁链捆锁；又问他是甚么人，做的是甚么事。'),
('CUV', '使徒行传', 44, 21, 34, '众人有喊叫这个的，有喊叫那个的；千夫长因为这样乱嚷，得不著实情，就吩咐人将保罗带进营楼去。'),
('CUV', '使徒行传', 44, 21, 35, '到了台阶上，众人挤得凶猛，兵丁只得将保罗抬起来。'),
('CUV', '使徒行传', 44, 21, 36, '众人跟在后面，喊著说：除掉他！'),
('CUV', '使徒行传', 44, 21, 37, '将要带他进营楼，保罗对千夫长说：我对你说句话可以不可以？他说：你懂得希利尼话么？'),
('CUV', '使徒行传', 44, 21, 38, '你莫非是从前作乱、带领四千凶徒往旷野去的那埃及人么？'),
('CUV', '使徒行传', 44, 21, 39, '保罗说：我本是犹太人，生在基利家的大数，并不是无名小城的人。求你准我对百姓说话。'),
('CUV', '使徒行传', 44, 21, 40, '千夫长准了。保罗就站在台阶上，向百姓摆手，他们都静默无声，保罗便用希伯来话对他们说：')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 22, 1, '诸位父兄请听，我现在对你们分诉。'),
('CUV', '使徒行传', 44, 22, 2, '众人听他说的是希伯来话，就更加安静了。'),
('CUV', '使徒行传', 44, 22, 3, '保罗说：我原是犹太人，生在基利家的大数，长在这城里，在迦玛列门下，按著我们祖宗严紧的律法受教，热心事奉神，像你们众人今日一样。'),
('CUV', '使徒行传', 44, 22, 4, '我也曾逼迫奉这道的人，直到死地，无论男女都锁拿下监。'),
('CUV', '使徒行传', 44, 22, 5, '这是大祭司和众长老都可以给我作见证的。我又领了他们达与弟兄的书信，往大马色去，要把在那里奉这道的人锁拿，带到耶路撒冷受刑。'),
('CUV', '使徒行传', 44, 22, 6, '我将到大马色，正走的时候，约在晌午，忽然从天上发大光，四面照著我。'),
('CUV', '使徒行传', 44, 22, 7, '我就仆倒在地，听见有声音对我说：扫罗！扫罗！你为甚么逼迫我？'),
('CUV', '使徒行传', 44, 22, 8, '我回答说：主阿，你是谁？他说：我就是你所逼迫的拿撒勒人耶稣。'),
('CUV', '使徒行传', 44, 22, 9, '与我同行的人看见了那光，却没有听明那位对我说话的声音。'),
('CUV', '使徒行传', 44, 22, 10, '我说：主阿，我当做甚么？主说：起来，进大马色去，在那里，要将所派你做的一切事告诉你。'),
('CUV', '使徒行传', 44, 22, 11, '我因那光的荣耀不能看见，同行的人就拉著我手进了大马色。'),
('CUV', '使徒行传', 44, 22, 12, '那里有一个人，名叫亚拿尼亚，按著律法是虔诚人，为一切住在那里的犹太人所称赞。'),
('CUV', '使徒行传', 44, 22, 13, '他来见我，站在旁边，对我说：兄弟扫罗，你可以看见。我当时往上一看，就看见了他。'),
('CUV', '使徒行传', 44, 22, 14, '他又说：我们祖宗的神拣选了你，叫你明白他的旨意，又得见那义者，听他口中所出的声音。'),
('CUV', '使徒行传', 44, 22, 15, '因为你要将所看见的，所听见的，对著万人为他作见证。'),
('CUV', '使徒行传', 44, 22, 16, '现在你为甚么耽延呢？起来，求告他的名受洗，洗去你的罪。'),
('CUV', '使徒行传', 44, 22, 17, '后来，我回到耶路撒冷，在殿里祷告的时候，魂游象外，'),
('CUV', '使徒行传', 44, 22, 18, '看见主向我说：你赶紧的离开耶路撒冷，不可迟延；因你为我作的见证，这里的人必不领受。'),
('CUV', '使徒行传', 44, 22, 19, '我就说：主阿，他们知道我从前把信你的人收在监里，又在各会堂里鞭打他们。'),
('CUV', '使徒行传', 44, 22, 20, '并且你的见证人司提反被害流血的时候，我也站在旁边欢喜；又看守害死他之人的衣裳。'),
('CUV', '使徒行传', 44, 22, 21, '主向我说：你去罢！我要差你远远的往外邦人那里去。'),
('CUV', '使徒行传', 44, 22, 22, '众人听他说到这句话，就高声说：这样的人，从世上除掉他罢！他是不当活著的。'),
('CUV', '使徒行传', 44, 22, 23, '众人喧嚷，摔掉衣裳，把尘土向空中扬起来。'),
('CUV', '使徒行传', 44, 22, 24, '千夫长就吩咐将保罗带进营楼去，叫人用鞭子拷问他，要知道他们向他这样喧嚷是为甚么缘故。'),
('CUV', '使徒行传', 44, 22, 25, '刚用皮条捆上，保罗对旁边站著的百夫长说：人是罗马人，又没有定罪，你们就鞭打他，有这个例么？'),
('CUV', '使徒行传', 44, 22, 26, '百夫长听见这话，就去见千夫长，告诉他说：你要做甚么？这人是罗马人。'),
('CUV', '使徒行传', 44, 22, 27, '千夫长就来问保罗说：你告诉我，你是罗马人么？保罗说：是。'),
('CUV', '使徒行传', 44, 22, 28, '千夫长说：我用许多银子才入了罗马的民籍。保罗说：我生来就是。'),
('CUV', '使徒行传', 44, 22, 29, '于是那些要拷问保罗的人就离开他去了。千夫长既知道他是罗马人，又因为捆绑了他，也害怕了。'),
('CUV', '使徒行传', 44, 22, 30, '第二天，千夫长为要知道犹太人控告保罗的实情，便解开他，吩咐祭司长和全公会的人都聚集，将保罗带下来，叫他站在他们面前。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 23, 1, '保罗定睛看著公会的人，说：弟兄们，我在神面前行事为人都是凭著良心，直到今日。'),
('CUV', '使徒行传', 44, 23, 2, '大祭司亚拿尼亚就吩咐旁边站著的人打他的嘴。'),
('CUV', '使徒行传', 44, 23, 3, '保罗对他说：你这粉饰的墙，神要打你！你坐堂为的是按律法审问我，你竟违背律法，吩咐人打我么？'),
('CUV', '使徒行传', 44, 23, 4, '站在旁边的人说：你辱骂神的大祭司么？'),
('CUV', '使徒行传', 44, 23, 5, '保罗说：弟兄们，我不晓得他是大祭司；经上记著说：不可毁谤你百姓的官长。'),
('CUV', '使徒行传', 44, 23, 6, '保罗看出大众一半是撒都该人，一半是法利赛人，就在公会中大声说：弟兄们，我是法利赛人，也是法利赛人的子孙。我现在受审问，是为盼望死人复活。'),
('CUV', '使徒行传', 44, 23, 7, '说了这话，法利赛人和撒都该人就争论起来，会众分为两党。'),
('CUV', '使徒行传', 44, 23, 8, '因为撒都该人说，没有复活，也没有天使和鬼魂；法利赛人却说，两样都有。'),
('CUV', '使徒行传', 44, 23, 9, '于是大大的喧嚷起来。有几个法利赛党的文士站起来争辩说：我们看不出这人有甚么恶处，倘若有鬼魂或是天使对他说过话，怎么样呢？'),
('CUV', '使徒行传', 44, 23, 10, '那时大起争吵，千夫长恐怕保罗被他们扯碎了，就吩咐兵丁下去，把他从众人当中抢出来，带进营楼去。'),
('CUV', '使徒行传', 44, 23, 11, '当夜，主站在保罗旁边，说：放心罢！你怎样在耶路撒冷为我作见证，也必怎样在罗马为我作见证。'),
('CUV', '使徒行传', 44, 23, 12, '到了天亮，犹太人同谋起誓，说：若不先杀保罗就不吃不喝。'),
('CUV', '使徒行传', 44, 23, 13, '这样同心起誓的有四十多人。'),
('CUV', '使徒行传', 44, 23, 14, '他们来见祭司长和长老，说：我们已经起了一个大誓，若不先杀保罗就不吃甚么。'),
('CUV', '使徒行传', 44, 23, 15, '现在你们和公会要知会千夫长，叫他带下保罗到你们这里来，假作要详细察考他的事；我们已经预备好了，不等他来到跟前就杀他。'),
('CUV', '使徒行传', 44, 23, 16, '保罗的外甥听见他们设下埋伏，就来到营楼里告诉保罗。'),
('CUV', '使徒行传', 44, 23, 17, '保罗请一个百夫长来，说：你领这少年人去见千夫长，他有事告诉他。'),
('CUV', '使徒行传', 44, 23, 18, '于是把他领去见千夫长，说：被囚的保罗请我到他那里，求我领这少年人来见你；他有事告诉你。'),
('CUV', '使徒行传', 44, 23, 19, '千夫长就拉著他的手，走到一旁，私下问他说：你有甚么事告诉我呢？'),
('CUV', '使徒行传', 44, 23, 20, '他说：犹太人已经约定，要求你明天带下保罗到公会里去，假作要详细查问他的事。'),
('CUV', '使徒行传', 44, 23, 21, '你切不要随从他们；因为他们有四十多人埋伏，已经起誓说：若不先杀保罗就不吃不喝。现在预备好了，只等你应允。'),
('CUV', '使徒行传', 44, 23, 22, '于是千夫长打发少年人走，嘱咐他说：不要告诉人你将这事报给我了。'),
('CUV', '使徒行传', 44, 23, 23, '千夫长便叫了两个百夫长来，说：预备步兵二百，马兵七十，长枪手二百，今夜亥初往该撒利亚去；'),
('CUV', '使徒行传', 44, 23, 24, '也要预备牲口叫保罗骑上，护送到巡抚腓力斯那里去。'),
('CUV', '使徒行传', 44, 23, 25, '千夫长又写了文书，'),
('CUV', '使徒行传', 44, 23, 26, '大略说：革老丢吕西亚，请巡抚腓力斯大人安。'),
('CUV', '使徒行传', 44, 23, 27, '这人被犹太人拿住，将要杀害，我得知他是罗马人，就带兵丁下去救他出来。'),
('CUV', '使徒行传', 44, 23, 28, '因要知道他们告他的缘故，我就带他下到他们的公会去，'),
('CUV', '使徒行传', 44, 23, 29, '便查知他被告是因他们律法的辩论，并没有甚么该死该绑的罪名。'),
('CUV', '使徒行传', 44, 23, 30, '后来有人把要害他的计谋告诉我，我就立时解他到你那里去，又吩咐告他的人在你面前告他。（有古卷在此有：愿你平安！）'),
('CUV', '使徒行传', 44, 23, 31, '于是，兵丁照所吩咐他们的，将保罗夜里带到安提帕底。'),
('CUV', '使徒行传', 44, 23, 32, '第二天，让马兵护送，他们就回营楼去。'),
('CUV', '使徒行传', 44, 23, 33, '马兵来到该撒利亚，把文书呈给巡抚，便叫保罗站在他面前。'),
('CUV', '使徒行传', 44, 23, 34, '巡抚看了文书，问保罗是那省的人，既晓得他是基利家人，'),
('CUV', '使徒行传', 44, 23, 35, '就说：等告你的人来到，我要细听你的事；便吩咐人把他看守在希律的衙门里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 24, 1, '过了五天，大祭司亚拿尼亚同几个长老，和一个辩士帖士罗下来，向巡抚控告保罗。'),
('CUV', '使徒行传', 44, 24, 2, '保罗被提了来，帖士罗就告他说：'),
('CUV', '使徒行传', 44, 24, 3, '腓力斯大人，我们因你得以大享太平，并且这一国的弊病，因著你的先见得以更正了；我们随时随地满心感谢不尽。'),
('CUV', '使徒行传', 44, 24, 4, '惟恐多说，你嫌烦絮，只求你宽容听我们说几句话。'),
('CUV', '使徒行传', 44, 24, 5, '我们看这个人，如同瘟疫一般，是鼓动普天下众犹太人生乱的，又是拿撒勒教党里的一个头目，'),
('CUV', '使徒行传', 44, 24, 6, '连圣殿他也想要污秽；我们把他捉住了。（有古卷在此有：要按我们的律法审问，'),
('CUV', '使徒行传', 44, 24, 7, '不料千夫长吕西亚前来，甚是强横，从我们手中把他夺去，吩咐告他的人到你这里来。）'),
('CUV', '使徒行传', 44, 24, 8, '你自己究问他，就可以知道我们告他的一切事了。'),
('CUV', '使徒行传', 44, 24, 9, '众犹太人也随著告他说：事情诚然是这样。'),
('CUV', '使徒行传', 44, 24, 10, '巡抚点头叫保罗说话。他就说：我知道你在这国里断事多年，所以我乐意为自己分诉。'),
('CUV', '使徒行传', 44, 24, 11, '你查问就可以知道，从我上耶路撒冷礼拜到今日不过有十二天。'),
('CUV', '使徒行传', 44, 24, 12, '他们并没有看见我在殿里，或是在会堂里，或是在城里，和人辩论，耸动众人。'),
('CUV', '使徒行传', 44, 24, 13, '他们现在所告我的事并不能对你证实了。'),
('CUV', '使徒行传', 44, 24, 14, '但有一件事，我向你承认，就是他们所称为异端的道，我正按著那道事奉我祖宗的神，又信合乎律法的和先知书上一切所记载的，'),
('CUV', '使徒行传', 44, 24, 15, '并且靠著神，盼望死人，无论善恶，都要复活，就是他们自己也有这个盼望。'),
('CUV', '使徒行传', 44, 24, 16, '我因此自己勉励，对神对人，常存无亏的良心。'),
('CUV', '使徒行传', 44, 24, 17, '过了几年，我带著赒济本国的捐项和供献的物上去。'),
('CUV', '使徒行传', 44, 24, 18, '正献的时候，他们看见我在殿里已经洁净了，并没有聚众，也没有吵嚷，惟有几个从亚西亚来的犹太人。'),
('CUV', '使徒行传', 44, 24, 19, '他们若有告我的事，就应当到你面前来告我。'),
('CUV', '使徒行传', 44, 24, 20, '即或不然，这些人若看出我站在公会前，有妄为的地方，他们自己也可以说明。'),
('CUV', '使徒行传', 44, 24, 21, '纵然有，也不过一句话，就是我站在他们中间大声说：我今日在你们面前受审，是为死人复活的道理。'),
('CUV', '使徒行传', 44, 24, 22, '腓力斯本是详细晓得这道，就支吾他们说：且等千夫长吕西亚下来，我要审断你们的事。'),
('CUV', '使徒行传', 44, 24, 23, '于是吩咐百夫长看守保罗，并且宽待他，也不拦阻他的亲友来供给他。'),
('CUV', '使徒行传', 44, 24, 24, '过了几天，腓力斯和他夫人─犹太的女子土西拉─一同来到，就叫了保罗来，听他讲论信基督耶稣的道。'),
('CUV', '使徒行传', 44, 24, 25, '保罗讲论公义、节制，和将来的审判。腓力斯甚觉恐惧，说：你暂且去罢，等我得便再叫你来。保罗讲论公义、节制，和将来的审判。腓力斯甚觉恐惧，说：你暂且去罢，等我得便再叫你来。'),
('CUV', '使徒行传', 44, 24, 26, '腓力斯又指望保罗送他银钱，所以屡次叫他来，和他谈论。'),
('CUV', '使徒行传', 44, 24, 27, '过了两年，波求非斯都接了腓力斯的任；腓力斯要讨犹太人的喜欢，就留保罗在监里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 25, 1, '非斯都到了任，过了三天，就从该撒利亚上耶路撒冷去。'),
('CUV', '使徒行传', 44, 25, 2, '祭司长和犹太人的首领向他控告保罗，'),
('CUV', '使徒行传', 44, 25, 3, '又央告他，求他的情，将保罗提到耶路撒冷来，他们要在路上埋伏杀害他。'),
('CUV', '使徒行传', 44, 25, 4, '非斯都却回答说：保罗押在该撒利亚，我自己快要往那里去；'),
('CUV', '使徒行传', 44, 25, 5, '又说：你们中间有权势的人与我一同下去，那人若有甚么不是，就可以告他。'),
('CUV', '使徒行传', 44, 25, 6, '非斯都在他们那里住了不过十天八天，就下该撒利亚去；第二天坐堂，吩咐将保罗提上来。'),
('CUV', '使徒行传', 44, 25, 7, '保罗来了，那些从耶路撒冷下来的犹太人周围站著，将许多重大的事控告他，都是不能证实的。'),
('CUV', '使徒行传', 44, 25, 8, '保罗分诉说：无论犹太人的律法，或是圣殿，或是该撒，我都没有干犯。'),
('CUV', '使徒行传', 44, 25, 9, '但非斯都要讨犹太人的喜欢，就问保罗说：你愿意上耶路撒冷去，在那里听我审断这事么？'),
('CUV', '使徒行传', 44, 25, 10, '保罗说：我站在该撒的堂前，这就是我应当受审的地方。我向犹太人并没有行过甚么不义的事，这也是你明明知道的。'),
('CUV', '使徒行传', 44, 25, 11, '我若行了不义的事，犯了甚么该死的罪，就是死，我也不辞。他们所告我的事若都不实，就没有人可以把我交给他们。我要上告于该撒。'),
('CUV', '使徒行传', 44, 25, 12, '非斯都和议会商量了，就说：你既上告于该撒，可以往该撒那里去。'),
('CUV', '使徒行传', 44, 25, 13, '过了些日子，亚基帕王和百尼基氏来到该撒利亚，问非斯都安。'),
('CUV', '使徒行传', 44, 25, 14, '在那里住了多日，非斯都将保罗的事告诉王，说：这里有一个人，是腓力斯留在监里的。'),
('CUV', '使徒行传', 44, 25, 15, '我在耶路撒冷的时候，祭司长和犹太的长老将他的事禀报了我，求我定他的罪。'),
('CUV', '使徒行传', 44, 25, 16, '我对他们说，无论甚么人，被告还没有和原告对质，未得机会分诉所告他的事，就先定他的罪，这不是罗马人的条例。'),
('CUV', '使徒行传', 44, 25, 17, '及至他们都来到这里，我就不耽延，第二天便坐堂，吩咐把那人提上来。'),
('CUV', '使徒行传', 44, 25, 18, '告他的人站著告他；所告的，并没有我所逆料的那等恶事。'),
('CUV', '使徒行传', 44, 25, 19, '不过是有几样辩论，为他们自己敬鬼神的事，又为一个人名叫耶稣，是已经死了，保罗却说他是活著的。'),
('CUV', '使徒行传', 44, 25, 20, '这些事当怎样究问，我心里作难，所以问他说：你愿意上耶路撒冷去，在那里为这些事听审么？'),
('CUV', '使徒行传', 44, 25, 21, '但保罗求我留下他，要听皇上审断，我就吩咐把他留下，等我解他到该撒那里去。'),
('CUV', '使徒行传', 44, 25, 22, '亚基帕对非斯都说：我自己也愿听这人辩论。非斯都说：明天你可以听。'),
('CUV', '使徒行传', 44, 25, 23, '第二天，亚基帕和百尼基大张威势而来，同著众千夫长和城里的尊贵人进了公厅。非斯都吩咐一声，就有人将保罗带进来。'),
('CUV', '使徒行传', 44, 25, 24, '非斯都说：亚基帕王和在这里的诸位阿，你们看这人，就是一切犹太人，在耶路撒冷和这里，曾向我恳求、呼叫说：不可容他再活著。'),
('CUV', '使徒行传', 44, 25, 25, '但我查明他没有犯甚么该死的罪，并且他自己上告于皇帝，所以我定意把他解去。'),
('CUV', '使徒行传', 44, 25, 26, '论到这人，我没有确实的事可以奏明主上。因此，我带他到你们面前，也特意带他到你亚基帕王面前，为要在查问之后有所陈奏。'),
('CUV', '使徒行传', 44, 25, 27, '据我看来，解送囚犯，不指明他的罪案是不合理的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 26, 1, '亚基帕对保罗说：准你为自己辩明。于是保罗伸手分诉，说：'),
('CUV', '使徒行传', 44, 26, 2, '亚基帕王阿，犹太人所告我的一切事，今日得在你面前分诉，实为万幸；'),
('CUV', '使徒行传', 44, 26, 3, '更可幸的，是你熟悉犹太人的规矩和他们的辩论；所以求你耐心听我。'),
('CUV', '使徒行传', 44, 26, 4, '我从起初在本国的民中，并在耶路撒冷，自幼为人如何，犹太人都知道。'),
('CUV', '使徒行传', 44, 26, 5, '他们若肯作见证就晓得，我从起初是按著我们教中最严紧的教门作了法利赛人。'),
('CUV', '使徒行传', 44, 26, 6, '现在我站在这里受审，是因为指望神向我们祖宗所应许的；'),
('CUV', '使徒行传', 44, 26, 7, '这应许，我们十二个支派，昼夜切切的事奉神，都指望得著。王阿，我被犹太人控告，就是因这指望。'),
('CUV', '使徒行传', 44, 26, 8, '神叫死人复活，你们为甚么看作不可信的呢？'),
('CUV', '使徒行传', 44, 26, 9, '从前我自己以为应当多方攻击拿撒勒人耶稣的名，'),
('CUV', '使徒行传', 44, 26, 10, '我在耶路撒冷也曾这样行了。既从祭司长得了权柄，我就把许多圣徒囚在监里。他们被杀，我也出名定案。'),
('CUV', '使徒行传', 44, 26, 11, '在各会堂，我屡次用刑强逼他们说亵渎的话，又分外恼恨他们，甚至追逼他们，直到外邦的城邑。'),
('CUV', '使徒行传', 44, 26, 12, '那时，我领了祭司长的权柄和命令，往大马色去。'),
('CUV', '使徒行传', 44, 26, 13, '王阿，我在路上，晌午的时候，看见从天发光，比日头还亮，四面照著我并与我同行的人。'),
('CUV', '使徒行传', 44, 26, 14, '我们都仆倒在地，我就听见有声音用希伯来话向我说：扫罗！扫罗！为甚么逼迫我？你用脚踢刺是难的！'),
('CUV', '使徒行传', 44, 26, 15, '我说：主阿，你是谁？主说：我就是你所逼迫的耶稣。'),
('CUV', '使徒行传', 44, 26, 16, '你起来站著，我特意向你显现，要派你作执事，作见证，将你所看见的事和我将要指示你的事证明出来；'),
('CUV', '使徒行传', 44, 26, 17, '我也要救你脱离百姓和外邦人的手。'),
('CUV', '使徒行传', 44, 26, 18, '我差你到他们那里去，要叫他们的眼睛得开，从黑暗中归向光明，从撒但权下归向神；又因信我，得蒙赦罪，和一切成圣的人同得基业。'),
('CUV', '使徒行传', 44, 26, 19, '亚基帕王阿，我故此没有违背那从天上来的异象；'),
('CUV', '使徒行传', 44, 26, 20, '先在大马色，后在耶路撒冷和犹太全地，以及外邦，劝勉他们应当悔改归向神，行事与悔改的心相称。'),
('CUV', '使徒行传', 44, 26, 21, '因此，犹太人在殿里拿住我，想要杀我。'),
('CUV', '使徒行传', 44, 26, 22, '然而我蒙神的帮助，直到今日还站得住，对著尊贵、卑贱、老幼作见证；所讲的并不外乎众先知和摩西所说将来必成的事，'),
('CUV', '使徒行传', 44, 26, 23, '就是基督必须受害，并且因从死里复活，要首先把光明的道传给百姓和外邦人。'),
('CUV', '使徒行传', 44, 26, 24, '保罗这样分诉，非斯都大声说：保罗，你癫狂了罢。你的学问太大，反叫你癫狂了！'),
('CUV', '使徒行传', 44, 26, 25, '保罗说：非斯都大人，我不是癫狂，我说的乃是真实明白话。'),
('CUV', '使徒行传', 44, 26, 26, '王也晓得这些事，所以我向王放胆直言，我深信这些事没有一件向王隐藏的，因都不是在背地里做的。'),
('CUV', '使徒行传', 44, 26, 27, '亚基帕王阿，你信先知么？我知道你是信的。'),
('CUV', '使徒行传', 44, 26, 28, '亚基帕对保罗说：你想少微一劝，便叫我作基督徒阿（或作：你这样劝我，几乎叫我作基督徒了）！'),
('CUV', '使徒行传', 44, 26, 29, '保罗说：无论是少劝是多劝，我向神所求的，不但你一个人，就是今天一切听我的，都要像我一样，只是不要像我有这些锁链。'),
('CUV', '使徒行传', 44, 26, 30, '于是，王和巡抚并百尼基与同坐的人都起来，'),
('CUV', '使徒行传', 44, 26, 31, '退到里面，彼此谈论说：这人并没有犯甚么该死该绑的罪。'),
('CUV', '使徒行传', 44, 26, 32, '亚基帕又对非斯都说：这人若没有上告于该撒，就可以释放了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 27, 1, '非斯都既然定规了，叫我们坐船往义大利去，便将保罗和别的囚犯交给御营里的一个百夫长，名叫犹流。'),
('CUV', '使徒行传', 44, 27, 2, '有一只亚大米田的船，要沿著亚西亚一带地方的海边走，我们就上了那船开行；有马其顿的帖撒罗尼迦人亚里达古和我们同去。'),
('CUV', '使徒行传', 44, 27, 3, '第二天，到了西顿；犹流宽待保罗，准他往朋友那里去，受他们的照应。'),
('CUV', '使徒行传', 44, 27, 4, '从那里又开船，因为风不顺，就贴著居比路背风岸行去。'),
('CUV', '使徒行传', 44, 27, 5, '过了基利家、旁非利亚前面的海，就到了吕家的每拉。'),
('CUV', '使徒行传', 44, 27, 6, '在那里，百夫长遇见一只亚力山大的船，要往义大利去，便叫我们上了那船。'),
('CUV', '使徒行传', 44, 27, 7, '一连多日，船行得慢，仅仅来到革尼土的对面。因为被风拦阻，就贴著革哩底背风岸，从撒摩尼对面行过。'),
('CUV', '使徒行传', 44, 27, 8, '我们沿岸行走，仅仅来到一个地方，名叫佳澳；离那里不远，有拉西亚城。'),
('CUV', '使徒行传', 44, 27, 9, '走的日子多了，已经过了禁食的节期，行船又危险，保罗就劝众人说：'),
('CUV', '使徒行传', 44, 27, 10, '众位，我看这次行船，不但货物和船要受伤损，大遭破坏，连我们的性命也难保。'),
('CUV', '使徒行传', 44, 27, 11, '但百夫长信从掌船的和船主，不信从保罗所说的。'),
('CUV', '使徒行传', 44, 27, 12, '且因在这海口过冬不便，船上的人就多半说：不如开船离开这地方，或者能到非尼基过冬。非尼基是革哩底的一个海口，一面朝东北，一面朝东南。'),
('CUV', '使徒行传', 44, 27, 13, '这时，微微起了南风，他们以为得意，就起了锚，贴近革哩底行去。'),
('CUV', '使徒行传', 44, 27, 14, '不多几时，狂风从岛上扑下来；那风名叫友拉革罗。'),
('CUV', '使徒行传', 44, 27, 15, '船被风抓住，敌不住风，我们就任风刮去。'),
('CUV', '使徒行传', 44, 27, 16, '贴著一个小岛的背风岸奔行，那岛名叫高大，在那里仅仅收住了小船。'),
('CUV', '使徒行传', 44, 27, 17, '既然把小船拉上来，就用缆索捆绑船底，又恐怕在赛耳底沙滩上搁了浅，就落下篷来，任船飘去。'),
('CUV', '使徒行传', 44, 27, 18, '我们被风浪逼得甚急，第二天众人就把货物抛在海里。'),
('CUV', '使徒行传', 44, 27, 19, '到第三天，他们又亲手把船上的器具抛弃了。'),
('CUV', '使徒行传', 44, 27, 20, '太阳和星辰多日不显露，又有狂风大浪催逼，我们得救的指望就都绝了。'),
('CUV', '使徒行传', 44, 27, 21, '众人多日没有吃甚么，保罗就出来站在他们中间，说：众位，你们本该听我的话，不离开革哩底，免得遭这样的伤损破坏。'),
('CUV', '使徒行传', 44, 27, 22, '现在我还劝你们放心，你们的性命一个也不失丧，惟独失丧这船。'),
('CUV', '使徒行传', 44, 27, 23, '因我所属所事奉的神，他的使者昨夜站在我旁边，说：'),
('CUV', '使徒行传', 44, 27, 24, '保罗，不要害怕，你必定站在该撒面前，并且与你同船的人，神都赐给你了。'),
('CUV', '使徒行传', 44, 27, 25, '所以众位可以放心，我信神他怎样对我说：事情也要怎样成就。'),
('CUV', '使徒行传', 44, 27, 26, '只是我们必要撞在一个岛上。'),
('CUV', '使徒行传', 44, 27, 27, '到了第十四天夜间，船在亚底亚海飘来飘去。约到半夜，水手以为渐近旱地，'),
('CUV', '使徒行传', 44, 27, 28, '就探深浅，探得有十二丈；稍往前行，又探深浅，探得有九丈。'),
('CUV', '使徒行传', 44, 27, 29, '恐怕撞在石头上，就从船尾抛下四个锚，盼望天亮。'),
('CUV', '使徒行传', 44, 27, 30, '水手想要逃出船去，把小船放在海里，假作要从船头抛锚的样子。'),
('CUV', '使徒行传', 44, 27, 31, '保罗对百夫长和兵丁说：这些人若不等在船上，你们必不能得救。'),
('CUV', '使徒行传', 44, 27, 32, '于是兵丁砍断小船的绳子，由他飘去。'),
('CUV', '使徒行传', 44, 27, 33, '天渐亮的时候，保罗劝众人都吃饭，说：你们悬望忍饿不吃甚么，已经十四天了。'),
('CUV', '使徒行传', 44, 27, 34, '所以我劝你们吃饭，这是关乎你们救命的事；因为你们各人连一根头发也不至于损坏。'),
('CUV', '使徒行传', 44, 27, 35, '保罗说了这话，就拿著饼，在众人面前祝谢了神，擘开吃。'),
('CUV', '使徒行传', 44, 27, 36, '于是他们都放下心，也就吃了。'),
('CUV', '使徒行传', 44, 27, 37, '我们在船上的共有二百七十六个人。'),
('CUV', '使徒行传', 44, 27, 38, '他们吃饱了，就把船上的麦子抛在海里，为要叫船轻一点。'),
('CUV', '使徒行传', 44, 27, 39, '到了天亮，他们不认识那地方，但见一个海湾，有岸可登，就商议能把船拢进去不能。'),
('CUV', '使徒行传', 44, 27, 40, '于是砍断缆索，弃锚在海里；同时也松开舵绳，拉起头篷，顺著风向岸行去。'),
('CUV', '使徒行传', 44, 27, 41, '但遇著两水夹流的地方，就把船搁了浅；船头胶住不动，船尾被浪的猛力冲坏。'),
('CUV', '使徒行传', 44, 27, 42, '兵丁的意思要把囚犯杀了，恐怕有洑水脱逃的。'),
('CUV', '使徒行传', 44, 27, 43, '但百夫长要救保罗，不准他们任意而行，就吩咐会洑水的，跳下水去先上岸；'),
('CUV', '使徒行传', 44, 27, 44, '其余的人可以用板子或船上的零碎东西上岸。这样，众人都得了救，上了岸。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '使徒行传', 44, 28, 1, '我们既已得救，才知道那岛名叫米利大。'),
('CUV', '使徒行传', 44, 28, 2, '土人看待我们，有非常的情分；因为当时下雨，天气又冷，就生火接待我们众人。'),
('CUV', '使徒行传', 44, 28, 3, '那时，保罗拾起一捆柴，放在火上，有一条毒蛇，因为热了出来，咬住他的手。'),
('CUV', '使徒行传', 44, 28, 4, '土人看见那毒蛇悬在他手上，就彼此说：这人必是个凶手，虽然从海里救上来，天理还不容他活著。'),
('CUV', '使徒行传', 44, 28, 5, '保罗竟把那毒蛇甩在火里，并没有受伤。'),
('CUV', '使徒行传', 44, 28, 6, '土人想他必要肿起来，或是忽然仆倒死了；看了多时，见他无害，就转念，说：他是个神。'),
('CUV', '使徒行传', 44, 28, 7, '离那地方不远，有田产是岛长部百流的；他接纳我们，尽情款待三日。'),
('CUV', '使徒行传', 44, 28, 8, '当时，部百流的父亲患热病和痢疾躺著。保罗进去，为他祷告，按手在他身上，治好了他。'),
('CUV', '使徒行传', 44, 28, 9, '从此，岛上其余的病人也来，得了医治。'),
('CUV', '使徒行传', 44, 28, 10, '他们又多方的尊敬我们；到了开船的时候，也把我们所需用的送到船上。'),
('CUV', '使徒行传', 44, 28, 11, '过了三个月，我们上了亚力山大的船往前行；这船以丢斯双子为记，是在那海岛过了冬的。'),
('CUV', '使徒行传', 44, 28, 12, '到了叙拉古，我们停泊三日；'),
('CUV', '使徒行传', 44, 28, 13, '又从那里绕行，来到利基翁。过了一天，起了南风，第二天就来到部丢利。'),
('CUV', '使徒行传', 44, 28, 14, '在那里遇见弟兄们，请我们与他们同住了七天。这样，我们来到罗马。'),
('CUV', '使徒行传', 44, 28, 15, '那里的弟兄们一听见我们的信息就出来，到亚比乌市和三馆地方迎接我们。保罗见了他们，就感谢神，放心壮胆。'),
('CUV', '使徒行传', 44, 28, 16, '进了罗马城，（有古卷在此有：百夫长把众囚犯交给御营的统领，惟有）保罗蒙准和一个看守他的兵另住在一处。'),
('CUV', '使徒行传', 44, 28, 17, '过了三天，保罗请犹太人的首领来。他们来了，就对他们说：弟兄们，我虽没有做甚么事干犯本国的百姓和我们祖宗的规条，却被锁绑，从耶路撒冷解在罗马人的手里。'),
('CUV', '使徒行传', 44, 28, 18, '他们审问了我，就愿意释放我；因为在我身上，并没有该死的罪。罪。'),
('CUV', '使徒行传', 44, 28, 19, '无奈犹太人不服，我不得已，只好上告于该撒，并非有甚么事要控告我本国的百姓。'),
('CUV', '使徒行传', 44, 28, 20, '因此，我请你们来见面说话，我原为以色列人所指望的，被这链子捆锁。'),
('CUV', '使徒行传', 44, 28, 21, '他们说：我们并没有接著从犹太来论你的信，也没有弟兄到这里来报给我们说你有甚么不好处。'),
('CUV', '使徒行传', 44, 28, 22, '但我们愿意听你的意见如何；因为这教门，我们晓得是到处被毁谤的。'),
('CUV', '使徒行传', 44, 28, 23, '他们和保罗约定了日子，就有许多人到他的寓处来。保罗从早到晚，对他们讲论这事，证明神国的道，引摩西的律法和先知的书，以耶稣的事劝勉他们。'),
('CUV', '使徒行传', 44, 28, 24, '他所说的话，有信的，有不信的。'),
('CUV', '使徒行传', 44, 28, 25, '他们彼此不合，就散了；未散以先，保罗说了一句话，说：圣灵藉先知以赛亚向你们祖宗所说的话是不错的。'),
('CUV', '使徒行传', 44, 28, 26, '他说：你去告诉这百姓说：你们听是要听见，却不明白；看是要看见，却不晓得；'),
('CUV', '使徒行传', 44, 28, 27, '因为这百姓油蒙了心，耳朵发沉，眼睛闭著；恐怕眼睛看见，耳朵听见，心里明白，回转过来，我就医治他们。'),
('CUV', '使徒行传', 44, 28, 28, '所以你们当知道，神这救恩，如今传给外邦人，他们也必听受。（有古卷在此有：'),
('CUV', '使徒行传', 44, 28, 29, '保罗说了这话，犹太人议论纷纷的就走了。）'),
('CUV', '使徒行传', 44, 28, 30, '保罗在自己所租的房子里住了足足两年。凡来见他的人，他全都接待，'),
('CUV', '使徒行传', 44, 28, 31, '放胆传讲神国的道，将主耶稣基督的事教导人，并没有人禁止。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 1, 1, '耶稣基督的仆人保罗，奉召为使徒，特派传神的福音。'),
('CUV', '罗马书', 45, 1, 2, '这福音是神从前藉众先知在圣经上所应许的，'),
('CUV', '罗马书', 45, 1, 3, '论到他儿子─我主耶稣基督。按肉体说，是从大卫后裔生的；'),
('CUV', '罗马书', 45, 1, 4, '按圣善的灵说，因从死里复活，以大能显明是神的儿子。'),
('CUV', '罗马书', 45, 1, 5, '我们从他受了恩惠并使徒的职分，在万国之中叫人为他的名信服真道；'),
('CUV', '罗马书', 45, 1, 6, '其中也有你们这蒙召属耶稣基督的人。'),
('CUV', '罗马书', 45, 1, 7, '我写信给你们在罗马、为神所爱、奉召作圣徒的众人。愿恩惠、平安从我们的父神并主耶稣基督归与你们！'),
('CUV', '罗马书', 45, 1, 8, '第一，我靠著耶稣基督，为你们众人感谢我的神，因你们的信德传遍了天下。'),
('CUV', '罗马书', 45, 1, 9, '我在他儿子福音上，用心灵所事奉的神，可以见证我怎样不住的提到你们；'),
('CUV', '罗马书', 45, 1, 10, '在祷告之间常常恳求，或者照神的旨意，终能得平坦的道路往你们那里去。'),
('CUV', '罗马书', 45, 1, 11, '因为我切切的想见你们，要把些属灵的恩赐分给你们，使你们可以坚固。'),
('CUV', '罗马书', 45, 1, 12, '这样，我在你们中间，因你与我彼此的信心，就可以同得安慰。'),
('CUV', '罗马书', 45, 1, 13, '弟兄们，我不愿意你们不知道，我屡次定意往你们那里去，要在你们中间得些果子，如同在其余的外邦人中一样；只是到如今仍有阻隔。'),
('CUV', '罗马书', 45, 1, 14, '无论是希利尼人、化外人、聪明人、愚拙人，我都欠他们的债，'),
('CUV', '罗马书', 45, 1, 15, '所以情愿尽我的力量，将福音也传给你们在罗马的人。'),
('CUV', '罗马书', 45, 1, 16, '我不以福音为耻；这福音本是神的大能，要救一切相信的，先是犹太人，后是希利尼人。'),
('CUV', '罗马书', 45, 1, 17, '因为神的义正在这福音上显明出来；这义是本于信，以致于信。如经上所记：义人必因信得生。'),
('CUV', '罗马书', 45, 1, 18, '原来，神的忿怒从天上显明在一切不虔不义的人身上，就是那些行不义阻挡真理的人。'),
('CUV', '罗马书', 45, 1, 19, '神的事情，人所能知道的，原显明在人心里，因为神已经给他们显明。'),
('CUV', '罗马书', 45, 1, 20, '自从造天地以来，神的永能和神性是明明可知的，虽是眼不能见，但藉著所造之物就可以晓得，叫人无可推诿。'),
('CUV', '罗马书', 45, 1, 21, '因为，他们虽然知道神，却不当作神荣耀他，也不感谢他。他们的思念变为虚妄，无知的心就昏暗了。'),
('CUV', '罗马书', 45, 1, 22, '自称为聪明，反成了愚拙，'),
('CUV', '罗马书', 45, 1, 23, '将不能朽坏之神的荣耀变为偶像，仿佛必朽坏的人和飞禽、走兽、昆虫的样式。'),
('CUV', '罗马书', 45, 1, 24, '所以，神任凭他们逞著心里的情欲行污秽的事，以致彼此玷辱自己的身体。'),
('CUV', '罗马书', 45, 1, 25, '他们将神的真实变为虚谎，去敬拜事奉受造之物，不敬奉那造物的主；主乃是可称颂的，直到永远。阿们！'),
('CUV', '罗马书', 45, 1, 26, '因此，神任凭他们放纵可羞耻的情欲。他们的女人把顺性的用处变为逆性的用处；'),
('CUV', '罗马书', 45, 1, 27, '男人也是如此，弃了女人顺性的用处，欲火攻心，彼此贪恋，男和男行可羞耻的事，就在自己身上受这妄为当得的报应。'),
('CUV', '罗马书', 45, 1, 28, '他们既然故意不认识神，神就任凭他们存邪僻的心，行那些不合理的事；'),
('CUV', '罗马书', 45, 1, 29, '装满了各样不义、邪恶、贪婪、恶毒（或作：阴毒），满心是嫉妒、凶杀、争竞、诡诈、毒恨；'),
('CUV', '罗马书', 45, 1, 30, '又是谗毁的、背后说人的、怨恨神的（或作：被神所憎恶的）、侮慢人的、狂傲的、自夸的、捏造恶事的、违背父母的。'),
('CUV', '罗马书', 45, 1, 31, '无知的，背约的，无亲情的，不怜悯人的。'),
('CUV', '罗马书', 45, 1, 32, '他们虽知道神判定行这样事的人是当死的，然而他们不但自己去行，还喜欢别人去行。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 2, 1, '你这论断人的，无论你是谁，也无可推诿。你在甚么事上论断人，就在甚么事上定自己的罪；因你这论断人的，自己所行却和别人一样。'),
('CUV', '罗马书', 45, 2, 2, '我们知道这样行的人，神必照真理审判他。'),
('CUV', '罗马书', 45, 2, 3, '你这人哪，你论断行这样事的人，自己所行的却和别人一样，你以为能逃脱神的审判么？'),
('CUV', '罗马书', 45, 2, 4, '还是你藐视他丰富的恩慈、宽容、忍耐，不晓得他的恩慈是领你悔改呢？'),
('CUV', '罗马书', 45, 2, 5, '你竟任著你刚硬不悔改的心，为自己积蓄忿怒，以致神震怒，显他公义审判的日子来到。'),
('CUV', '罗马书', 45, 2, 6, '他必照各人的行为报应各人。'),
('CUV', '罗马书', 45, 2, 7, '凡恒心行善、寻求荣耀、尊贵，和不能朽坏之福的，就以永生报应他们；'),
('CUV', '罗马书', 45, 2, 8, '惟有结党、不顺从真理、反顺从不义的，就以忿怒、恼恨报应他们。'),
('CUV', '罗马书', 45, 2, 9, '将患难、困苦加给一切作恶的人，先是犹太人，后是希利尼人；'),
('CUV', '罗马书', 45, 2, 10, '却将荣耀、尊贵、平安加给一切行善的人，先是犹太人，后是希利尼人。'),
('CUV', '罗马书', 45, 2, 11, '因为神不偏待人。'),
('CUV', '罗马书', 45, 2, 12, '凡没有律法犯了罪的，也必不按律法灭亡；凡在律法以下犯了罪的，也必按律法受审判。'),
('CUV', '罗马书', 45, 2, 13, '（原来在神面前，不是听律法的为义，乃是行律法的称义。'),
('CUV', '罗马书', 45, 2, 14, '没有律法的外邦人若顺著本性行律法上的事，他们虽然没有律法，自己就是自己的律法。'),
('CUV', '罗马书', 45, 2, 15, '这是显出律法的功用刻在他们心里，他们是非之心同作见证，并且他们的思念互相较量，或以为是，或以为非。）'),
('CUV', '罗马书', 45, 2, 16, '就在神藉耶稣基督审判人隐秘事的日子，照著我的福音所言。'),
('CUV', '罗马书', 45, 2, 17, '你称为犹太人，又倚靠律法，且指著神夸口；'),
('CUV', '罗马书', 45, 2, 18, '既从律法中受了教训，就晓得神的旨意，也能分别是非（或作：也喜爱那美好的事）；'),
('CUV', '罗马书', 45, 2, 19, '又深信自己是给瞎子领路的，是黑暗中人的光，'),
('CUV', '罗马书', 45, 2, 20, '是蠢笨人的师傅，是小孩子的先生，在律法上有知识和真理的模范。'),
('CUV', '罗马书', 45, 2, 21, '你既是教导别人，还不教导自己么？你讲说人不可偷窃，自己还偷窃么？'),
('CUV', '罗马书', 45, 2, 22, '你说人不可奸淫，自己还奸淫么？你厌恶偶像，自己还偷窃庙中之物么？'),
('CUV', '罗马书', 45, 2, 23, '你指著律法夸口，自己倒犯律法，玷辱神么？'),
('CUV', '罗马书', 45, 2, 24, '神的名在外邦人中，因你们受了亵渎，正如经上所记的。'),
('CUV', '罗马书', 45, 2, 25, '你若是行律法的，割礼固然于你有益；若是犯律法的，你的割礼就算不得割礼。'),
('CUV', '罗马书', 45, 2, 26, '所以那未受割礼的，若遵守律法的条例，他虽然未受割礼，岂不算是有割礼么？'),
('CUV', '罗马书', 45, 2, 27, '而且那本来未受割礼的，若能全守律法，岂不是要审判你这有仪文和割礼竟犯律法的人么？'),
('CUV', '罗马书', 45, 2, 28, '因为外面作犹太人的，不是真犹太人；外面肉身的割礼，也不是真割礼。'),
('CUV', '罗马书', 45, 2, 29, '惟有里面作的，才是真犹太人；真割礼也是心里的，在乎灵，不在乎仪文。这人的称赞不是从人来的，乃是从神来的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 3, 1, '这样说来，犹太人有甚么长处？割礼有甚么益处呢？'),
('CUV', '罗马书', 45, 3, 2, '凡事大有好处：第一是神的圣言交托他们。'),
('CUV', '罗马书', 45, 3, 3, '即便有不信的，这有何妨呢？难道他们的不信就废掉神的信么？'),
('CUV', '罗马书', 45, 3, 4, '断乎不能！不如说，神是真实的，人都是虚谎的。如经上所记：你责备人的时候，显为公义；被人议论的时候，可以得胜。'),
('CUV', '罗马书', 45, 3, 5, '我且照著人的常话说，我们的不义若显出神的义来，我们可以怎么说呢？神降怒，是他不义么？'),
('CUV', '罗马书', 45, 3, 6, '断乎不是！若是这样，神怎能审判世界呢？'),
('CUV', '罗马书', 45, 3, 7, '若神的真实，因我的虚谎越发显出他的荣耀，为甚么我还受审判，好像罪人呢？'),
('CUV', '罗马书', 45, 3, 8, '为甚么不说，我们可以作恶以成善呢？这是毁谤我们的人说我们有这话。这等人定罪是该当的。'),
('CUV', '罗马书', 45, 3, 9, '这却怎么样呢？我们比他们强么？决不是的！因我们已经证明，犹太人和希利尼人都在罪恶之下。'),
('CUV', '罗马书', 45, 3, 10, '就如经上所记：没有义人，连一个也没有。'),
('CUV', '罗马书', 45, 3, 11, '没有明白的；没有寻求神的；'),
('CUV', '罗马书', 45, 3, 12, '都是偏离正路，一同变为无用。没有行善的，连一个也没有。'),
('CUV', '罗马书', 45, 3, 13, '他们的喉咙是敞开的坟墓；他们用舌头弄诡诈，嘴唇里有虺蛇的毒气，'),
('CUV', '罗马书', 45, 3, 14, '满口是咒骂苦毒。'),
('CUV', '罗马书', 45, 3, 15, '杀人流血，他们的脚飞跑，'),
('CUV', '罗马书', 45, 3, 16, '所经过的路便行残害暴虐的事。'),
('CUV', '罗马书', 45, 3, 17, '平安的路，他们未曾知道；'),
('CUV', '罗马书', 45, 3, 18, '他们眼中不怕神。'),
('CUV', '罗马书', 45, 3, 19, '我们晓得律法上的话都是对律法以下之人说的，好塞住各人的口，叫普世的人都伏在神审判之下。'),
('CUV', '罗马书', 45, 3, 20, '所以凡有血气的，没有一个因行律法能在神面前称义，因为律法本是叫人知罪。'),
('CUV', '罗马书', 45, 3, 21, '但如今，神的义在律法以外已经显明出来，有律法和先知为证：'),
('CUV', '罗马书', 45, 3, 22, '就是神的义，因信耶稣基督加给一切相信的人，并没有分别。'),
('CUV', '罗马书', 45, 3, 23, '因为世人都犯了罪，亏缺了神的荣耀；'),
('CUV', '罗马书', 45, 3, 24, '如今却蒙神的恩典，因基督耶稣的救赎，就白白的称义。'),
('CUV', '罗马书', 45, 3, 25, '神设立耶稣作挽回祭，是凭著耶稣的血，藉著人的信，要显明神的义；因为他用忍耐的心宽容人先时所犯的罪，'),
('CUV', '罗马书', 45, 3, 26, '好在今时显明他的义，使人知道他自己为义，也称信耶稣的人为义。'),
('CUV', '罗马书', 45, 3, 27, '既是这样，那里能夸口呢？没有可夸的了。用何法没有的呢？是用立功之法么？不是，乃用信主之法。'),
('CUV', '罗马书', 45, 3, 28, '所以（有古卷：因为）我们看定了：人称义是因著信，不在乎遵行律法。'),
('CUV', '罗马书', 45, 3, 29, '难道神只作犹太人的神么？不也是作外邦人的神么？是的，也作外邦人的神。'),
('CUV', '罗马书', 45, 3, 30, '神既是一位，他就要因信称那受割礼的为义，也要因信称那未受割礼的为义。'),
('CUV', '罗马书', 45, 3, 31, '这样，我们因信废了律法么？断乎不是！更是坚固律法。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 4, 1, '如此说来，我们的祖宗亚伯拉罕凭著肉体得了甚么呢？'),
('CUV', '罗马书', 45, 4, 2, '倘若亚伯拉罕是因行为称义，就有可夸的；只是在神面前并无可夸。'),
('CUV', '罗马书', 45, 4, 3, '经上说甚么呢？说：亚伯拉罕信神，这就算为他的义。'),
('CUV', '罗马书', 45, 4, 4, '做工的得工价，不算恩典，乃是该得的；'),
('CUV', '罗马书', 45, 4, 5, '惟有不做工的，只信称罪人为义的神，他的信就算为义。'),
('CUV', '罗马书', 45, 4, 6, '正如大卫称那在行为以外蒙神算为义的人是有福的。'),
('CUV', '罗马书', 45, 4, 7, '他说：得赦免其过、遮盖其罪的，这人是有福的。'),
('CUV', '罗马书', 45, 4, 8, '主不算为有罪的，这人是有福的。'),
('CUV', '罗马书', 45, 4, 9, '如此看来，这福是单加给那受割礼的人么？不也是加给那未受割礼的人么？因我们所说，亚伯拉罕的信，就算为他的义，'),
('CUV', '罗马书', 45, 4, 10, '是怎么算的呢？是在他受割礼的时候呢？是在他未受割礼的时候呢？不是在受割礼的时候，乃是在未受割礼的时候。'),
('CUV', '罗马书', 45, 4, 11, '并且他受了割礼的记号，作他未受割礼的时候因信称义的印证，叫他作一切未受割礼而信之人的父，使他们也算为义；'),
('CUV', '罗马书', 45, 4, 12, '又作受割礼之人的父，就是那些不但受割礼，并且按我们的祖宗亚伯拉罕未受割礼而信之踪迹去行的人。'),
('CUV', '罗马书', 45, 4, 13, '因为神应许亚伯拉罕和他后裔，必得承受世界，不是因律法，乃是因信而得的义。'),
('CUV', '罗马书', 45, 4, 14, '若是属乎律法的人才得为后嗣，信就归于虚空，应许也就废弃了。'),
('CUV', '罗马书', 45, 4, 15, '因为律法是惹动忿怒的（或作：叫人受刑的）；那里没有律法，那里就没有过犯。'),
('CUV', '罗马书', 45, 4, 16, '所以人得为后嗣是本乎信，因此就属乎恩，叫应许定然归给一切后裔；不但归给那属乎律法的，也归给那效法亚伯拉罕之信的。'),
('CUV', '罗马书', 45, 4, 17, '亚伯拉罕所信的，是那叫死人复活、使无变为有的神，他在主面前作我们世人的父。如经上所记：我已经立你作多国的父。'),
('CUV', '罗马书', 45, 4, 18, '他在无可指望的时候，因信仍有指望，就得以作多国的父，正如先前所说，你的后裔将要如此。'),
('CUV', '罗马书', 45, 4, 19, '他将近百岁的时候，虽然想到自己的身体如同已死，撒拉的生育已经断绝，他的信心还是不软弱；'),
('CUV', '罗马书', 45, 4, 20, '并且仰望神的应许，总没有因不信心里起疑惑，反倒因信心里得坚固，将荣耀归给神，'),
('CUV', '罗马书', 45, 4, 21, '且满心相信神所应许的必能做成。'),
('CUV', '罗马书', 45, 4, 22, '所以，这就算为他的义。'),
('CUV', '罗马书', 45, 4, 23, '算为他义的这句话不是单为他写的，'),
('CUV', '罗马书', 45, 4, 24, '也是为我们将来得算为义之人写的，就是我们这信神使我们的主耶稣从死里复活的人。'),
('CUV', '罗马书', 45, 4, 25, '耶稣被交给人，是为我们的过犯；复活，是为叫我们称义（或作：耶稣是为我们的过犯交付了，是为我们称义复活了）。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 5, 1, '我们既因信称义，就藉著我们的主耶稣基督得与神相和。'),
('CUV', '罗马书', 45, 5, 2, '我们又藉著他，因信得进入现在所站的这恩典中，并且欢欢喜喜盼望神的荣耀。'),
('CUV', '罗马书', 45, 5, 3, '不但如此，就是在患难中也是欢欢喜喜的；因为知道患难生忍耐，'),
('CUV', '罗马书', 45, 5, 4, '忍耐生老练，老练生盼望；'),
('CUV', '罗马书', 45, 5, 5, '盼望不至于羞耻，因为所赐给我们的圣灵将神的爱浇灌在我们心里。'),
('CUV', '罗马书', 45, 5, 6, '因我们还软弱的时候，基督就按所定的日期为罪人死。'),
('CUV', '罗马书', 45, 5, 7, '为义人死，是少有的；为仁人死、或者有敢做的。'),
('CUV', '罗马书', 45, 5, 8, '惟有基督在我们还作罪人的时候为我们死，神的爱就在此向我们显明了。'),
('CUV', '罗马书', 45, 5, 9, '现在我们既靠著他的血称义，就更要藉著他免去神的忿怒。'),
('CUV', '罗马书', 45, 5, 10, '因为我们作仇敌的时候，且藉著神儿子的死，得与神和好；既已和好，就更要因他的生得救了。'),
('CUV', '罗马书', 45, 5, 11, '不但如此，我们既藉著我主耶稣基督得与神和好，也就藉著他以神为乐。'),
('CUV', '罗马书', 45, 5, 12, '这就如罪是从一人入了世界，死又是从罪来的；于是死就临到众人，因为众人都犯了罪。'),
('CUV', '罗马书', 45, 5, 13, '没有律法之先，罪已经在世上；但没有律法，罪也不算罪。'),
('CUV', '罗马书', 45, 5, 14, '然而从亚当到摩西，死就作了王，连那些不与亚当犯一样罪过的，也在他的权下。亚当乃是那以后要来之人的豫像。'),
('CUV', '罗马书', 45, 5, 15, '只是过犯不如恩赐，若因一人的过犯，众人都死了，何况神的恩典，与那因耶稣基督一人恩典中的赏赐，岂不更加倍的临到众人么？'),
('CUV', '罗马书', 45, 5, 16, '因一人犯罪就定罪，也不如恩赐，原来审判是由一人而定罪，恩赐乃是由许多过犯而称义。'),
('CUV', '罗马书', 45, 5, 17, '若因一人的过犯，死就因这一人作了王，何况那些受洪恩又蒙所赐之义的，岂不更要因耶稣基督一人在生命中作王么？'),
('CUV', '罗马书', 45, 5, 18, '如此说来，因一次的过犯，众人都被定罪；照样，因一次的义行，众人也就被称义得生命了。'),
('CUV', '罗马书', 45, 5, 19, '因一人的悖逆，众人成为罪人；照样，因一人的顺从，众人也成为义了。'),
('CUV', '罗马书', 45, 5, 20, '律法本是外添的，叫过犯显多；只是罪在那里显多，恩典就更显多了。'),
('CUV', '罗马书', 45, 5, 21, '就如罪作王叫人死；照样，恩典也藉著义作王，叫人因我们的主耶稣基督得永生。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 6, 1, '这样，怎么说呢？我们可以仍在罪中、叫恩典显多么？'),
('CUV', '罗马书', 45, 6, 2, '断乎不可！我们在罪上死了的人岂可仍在罪中活著呢？'),
('CUV', '罗马书', 45, 6, 3, '岂不知我们这受洗归入基督耶稣的人是受洗归入他的死么？'),
('CUV', '罗马书', 45, 6, 4, '所以，我们藉著洗礼归入死，和他一同埋葬，原是叫我们一举一动有新生的样式，像基督藉著父的荣耀从死里复活一样。'),
('CUV', '罗马书', 45, 6, 5, '我们若在他死的形状上与他联合，也要在他复活的形状上与他联合；'),
('CUV', '罗马书', 45, 6, 6, '因为知道我们的旧人和他同钉十字架，使罪身灭绝，叫我们不再作罪的奴仆；'),
('CUV', '罗马书', 45, 6, 7, '因为已死的人是脱离了罪。'),
('CUV', '罗马书', 45, 6, 8, '我们若是与基督同死，就信必与他同活。'),
('CUV', '罗马书', 45, 6, 9, '因为知道基督既从死里复活，就不再死，死也不再作他的主了。'),
('CUV', '罗马书', 45, 6, 10, '他死是向罪死了，只有一次；他活是向神活著。'),
('CUV', '罗马书', 45, 6, 11, '这样，你们向罪也当看自己是死的；向神在基督耶稣里，却当看自己是活的。'),
('CUV', '罗马书', 45, 6, 12, '所以，不要容罪在你们必死的身上作王，使你们顺从身子的私欲。'),
('CUV', '罗马书', 45, 6, 13, '也不要将你们的肢体献给罪作不义的器具；倒要像从死里复活的人，将自己献给神，并将肢体作义的器具献给神。'),
('CUV', '罗马书', 45, 6, 14, '罪必不能作你们的主，因你们不在律法之下，乃在恩典之下。'),
('CUV', '罗马书', 45, 6, 15, '这却怎么样呢？我们在恩典之下，不在律法之下，就可以犯罪么？断乎不可！'),
('CUV', '罗马书', 45, 6, 16, '岂不晓得你们献上自己作奴仆，顺从谁，就作谁的奴仆么？或作罪的奴仆，以至于死；或作顺命的奴仆，以至成义。'),
('CUV', '罗马书', 45, 6, 17, '感谢神！因为你们从前虽然作罪的奴仆，现今却从心里顺服了所传给你们道理的模范。'),
('CUV', '罗马书', 45, 6, 18, '你们既从罪里得了释放，就作了义的奴仆。'),
('CUV', '罗马书', 45, 6, 19, '我因你们肉体的软弱，就照人的常话对你们说。你们从前怎样将肢体献给不洁不法作奴仆，以至于不法；现今也要照样将肢体献给义作奴仆，以至于成圣。'),
('CUV', '罗马书', 45, 6, 20, '因为你们作罪之奴仆的时候，就不被义约束了。'),
('CUV', '罗马书', 45, 6, 21, '你们现今所看为羞耻的事，当日有甚么果子呢？那些事的结局就是死。'),
('CUV', '罗马书', 45, 6, 22, '但现今，你们既从罪里得了释放，作了神的奴仆，就有成圣的果子，那结局就是永生。'),
('CUV', '罗马书', 45, 6, 23, '因为罪的工价乃是死；惟有神的恩赐，在我们的主基督耶稣里，乃是永生。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 7, 1, '弟兄们，我现在对明白律法的人说，你们岂不晓得律法管人是在活著的时候么？'),
('CUV', '罗马书', 45, 7, 2, '就如女人有了丈夫，丈夫还活著，就被律法约束；丈夫若死了，就脱离了丈夫的律法。'),
('CUV', '罗马书', 45, 7, 3, '所以丈夫活著，他若归于别人，便叫淫妇；丈夫若死了，他就脱离了丈夫的律法，虽然归于别人，也不是淫妇。'),
('CUV', '罗马书', 45, 7, 4, '我的弟兄们，这样说来，你们藉著基督的身体，在律法上也是死了，叫你们归于别人，就是归于那从死里复活的，叫我们结果子给神。'),
('CUV', '罗马书', 45, 7, 5, '因为我们属肉体的时候，那因律法而生的恶欲就在我们肢体中发动，以致结成死亡的果子。'),
('CUV', '罗马书', 45, 7, 6, '但我们既然在捆我们的律法上死了，现今就脱离了律法，叫我们服事主，要按著心灵（心灵：或作圣灵）的新样，不按著仪文的旧样。'),
('CUV', '罗马书', 45, 7, 7, '这样，我们可说甚么呢？律法是罪么？断乎不是！只是非因律法，我就不知何为罪。非律法说不可起贪心，我就不知何为贪心。'),
('CUV', '罗马书', 45, 7, 8, '然而罪趁著机会，就藉著诫命叫诸般的贪心在我里头发动；因为没有律法，罪是死的。'),
('CUV', '罗马书', 45, 7, 9, '我以前没有律法是活著的；但是诫命来到，罪又活了，我就死了。'),
('CUV', '罗马书', 45, 7, 10, '那本来叫人活的诫命，反倒叫我死；'),
('CUV', '罗马书', 45, 7, 11, '因为罪趁著机会，就藉著诫命引诱我，并且杀了我。'),
('CUV', '罗马书', 45, 7, 12, '这样看来，律法是圣洁的，诫命也是圣洁、公义、良善的。'),
('CUV', '罗马书', 45, 7, 13, '既然如此，那良善的是叫我死么？断乎不是！叫我死的乃是罪。但罪藉著那良善的叫我死，就显出真是罪，叫罪因著诫命更显出是恶极了。'),
('CUV', '罗马书', 45, 7, 14, '我们原晓得律法是属乎灵的，但我是属乎肉体的，是已经卖给罪了。'),
('CUV', '罗马书', 45, 7, 15, '因为我所做的，我自己不明白；我所愿意的，我并不做；我所恨恶的，我倒去做。'),
('CUV', '罗马书', 45, 7, 16, '若我所做的，是我所不愿意的，我就应承律法是善的。'),
('CUV', '罗马书', 45, 7, 17, '既是这样，就不是我做的，乃是住在我里头的罪做的。'),
('CUV', '罗马书', 45, 7, 18, '我也知道在我里头，就是我肉体之中，没有良善。因为，立志为善由得我，只是行出来由不得我。'),
('CUV', '罗马书', 45, 7, 19, '故此，我所愿意的善，我反不做；我所不愿意的恶，我倒去做。'),
('CUV', '罗马书', 45, 7, 20, '若我去做所不愿意做的，就不是我做的，乃是住在我里头的罪做的。'),
('CUV', '罗马书', 45, 7, 21, '我觉得有个律，就是我愿意为善的时候，便有恶与我同在。'),
('CUV', '罗马书', 45, 7, 22, '因为按著我里面的意思（原文是人），我是喜欢神的律；'),
('CUV', '罗马书', 45, 7, 23, '但我觉得肢体中另有个律和我心中的律交战，把我掳去，叫我附从那肢体中犯罪的律。'),
('CUV', '罗马书', 45, 7, 24, '我真是苦阿！谁能救我脱离这取死的身体呢？'),
('CUV', '罗马书', 45, 7, 25, '感谢神，靠著我们的主耶稣基督就能脱离了。这样看来，我以内心顺服神的律，我肉体却顺服罪的律了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 8, 1, '如今，那些在基督耶稣里的就不定罪了。'),
('CUV', '罗马书', 45, 8, 2, '因为赐生命圣灵的律，在基督耶稣里释放了我，使我脱离罪和死的律了。'),
('CUV', '罗马书', 45, 8, 3, '律法既因肉体软弱，有所不能行的，神就差遣自己的儿子，成为罪身的形状，作了赎罪祭，在肉体中定了罪案，'),
('CUV', '罗马书', 45, 8, 4, '使律法的义成就在我们这不随从肉体、只随从圣灵的人身上。'),
('CUV', '罗马书', 45, 8, 5, '因为随从肉体的人体贴肉体的事，随从圣灵的人体贴圣灵的事。'),
('CUV', '罗马书', 45, 8, 6, '体贴肉体的，就是死；体贴圣灵的，乃是生命、平安。'),
('CUV', '罗马书', 45, 8, 7, '原来体贴肉体的，就是与神为仇；因为不服神的律法，也是不能服，'),
('CUV', '罗马书', 45, 8, 8, '而且属肉体的人不能得神的喜欢。'),
('CUV', '罗马书', 45, 8, 9, '如果神的灵住在你们心里，你们就不属肉体，乃属圣灵了。人若没有基督的灵，就不是属基督的。'),
('CUV', '罗马书', 45, 8, 10, '基督若在你们心里，身体就因罪而死，心灵却因义而活。'),
('CUV', '罗马书', 45, 8, 11, '然而，叫耶稣从死里复活者的灵若住在你们心里，那叫基督耶稣从死里复活的，也必藉著住在你们心里的圣灵，使你们必死的身体又活过来。'),
('CUV', '罗马书', 45, 8, 12, '弟兄们，这样看来，我们并不是欠肉体的债去顺从肉体活著。'),
('CUV', '罗马书', 45, 8, 13, '你们若顺从肉体活著，必要死；若靠著圣灵治死身体的恶行，必要活著。'),
('CUV', '罗马书', 45, 8, 14, '因为凡被神的灵引导的，都是神的儿子。'),
('CUV', '罗马书', 45, 8, 15, '你们所受的，不是奴仆的心，仍旧害怕；所受的，乃是儿子的心，因此我们呼叫：阿爸！父！'),
('CUV', '罗马书', 45, 8, 16, '圣灵与我们的心同证我们是神的儿女；'),
('CUV', '罗马书', 45, 8, 17, '既是儿女，便是后嗣，就是神的后嗣，和基督同作后嗣。如果我们和他一同受苦，也必和他一同得荣耀。'),
('CUV', '罗马书', 45, 8, 18, '我想，现在的苦楚若比起将来要显于我们的荣耀就不足介意了。'),
('CUV', '罗马书', 45, 8, 19, '受造之物切望等候神的众子显出来。'),
('CUV', '罗马书', 45, 8, 20, '因为受造之物服在虚空之下，不是自己愿意，乃是因那叫他如此的。'),
('CUV', '罗马书', 45, 8, 21, '但受造之物仍然指望脱离败坏的辖制，得享（享：原文是入）神儿女自由的荣耀。'),
('CUV', '罗马书', 45, 8, 22, '我们知道一切受造之物一同叹息、劳苦，直到如今。'),
('CUV', '罗马书', 45, 8, 23, '不但如此，就是我们这有圣灵初结果子的，也是自己心里叹息，等候得著儿子的名分，乃是我们的身体得赎。'),
('CUV', '罗马书', 45, 8, 24, '我们得救是在乎盼望；只是所见的盼望不是盼望，谁还盼望他所见的呢（有古卷作：人所看见的何必再盼望呢）？'),
('CUV', '罗马书', 45, 8, 25, '但我们若盼望那所不见的，就必忍耐等候。'),
('CUV', '罗马书', 45, 8, 26, '况且我们的软弱有圣灵帮助，我们本不晓得当怎样祷告，只是圣灵亲自用说不出来的叹息替我们祷告。'),
('CUV', '罗马书', 45, 8, 27, '鉴察人心的，晓得圣灵的意思，因为圣灵照著神的旨意替圣徒祈求。'),
('CUV', '罗马书', 45, 8, 28, '我们晓得万事都互相效力，叫爱神的人得益处，就是按他旨意被召的人。'),
('CUV', '罗马书', 45, 8, 29, '因为他预先所知道的人，就预先定下效法他儿子的模样，使他儿子在许多弟兄中作长子。'),
('CUV', '罗马书', 45, 8, 30, '预先所定下的人又召他们来；所召来的人又称他们为义；所称为义的人又叫他们得荣耀。'),
('CUV', '罗马书', 45, 8, 31, '既是这样，还有甚么说的呢？神若帮助我们，谁能敌挡我们呢？'),
('CUV', '罗马书', 45, 8, 32, '神既不爱惜自己的儿子，为我们众人舍了，岂不也把万物和他一同白白的赐给我们么？'),
('CUV', '罗马书', 45, 8, 33, '谁能控告神所拣选的人呢？有神称他们为义了（或作：是称他们为义的神么）'),
('CUV', '罗马书', 45, 8, 34, '谁能定他们的罪呢？有基督耶稣已经死了，而且从死里复活，现今在神的右边，也替我们祈求（有基督....或作是已经死了，而且从死里复活，现今在神的右边，也替我们祈求的基督耶稣么）'),
('CUV', '罗马书', 45, 8, 35, '谁能使我们与基督的爱隔绝呢？难道是患难么？是困苦么？是逼迫么？是饥饿么？是赤身露体么？是危险么？是刀剑么？'),
('CUV', '罗马书', 45, 8, 36, '如经上所记：我们为你的缘故终日被杀；人看我们如将宰的羊。'),
('CUV', '罗马书', 45, 8, 37, '然而，靠著爱我们的主，在这一切的事上已经得胜有余了。'),
('CUV', '罗马书', 45, 8, 38, '因为我深信无论是死，是生，是天使，是掌权的，是有能的，是现在的事，是将来的事，'),
('CUV', '罗马书', 45, 8, 39, '是高处的，是低处的，是别的受造之物，都不能叫我们与神的爱隔绝；这爱是在我们的主基督耶稣里的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 9, 1, '我在基督里说真话，并不谎言，有我良心被圣灵感动，给我作见证；'),
('CUV', '罗马书', 45, 9, 2, '我是大有忧愁，心里时常伤痛；'),
('CUV', '罗马书', 45, 9, 3, '为我弟兄，我骨肉之亲，就是自己被咒诅，与基督分离，我也愿意。'),
('CUV', '罗马书', 45, 9, 4, '他们是以色列人；那儿子的名分、荣耀、诸约、律法、礼仪、应许都是他们的。'),
('CUV', '罗马书', 45, 9, 5, '列祖就是他们的祖宗，按肉体说，基督也是从他们出来的，他是在万有之上，永远可称颂的神。阿们！'),
('CUV', '罗马书', 45, 9, 6, '这不是说神的话落了空。因为从以色列生的不都是以色列人，'),
('CUV', '罗马书', 45, 9, 7, '也不因为是亚伯拉罕的后裔就都作他的儿女；惟独从以撒生的才要称为你的后裔。'),
('CUV', '罗马书', 45, 9, 8, '这就是说，肉身所生的儿女不是神的儿女，惟独那应许的儿女才算是后裔。'),
('CUV', '罗马书', 45, 9, 9, '因为所应许的话是这样说：到明年这时候我要来，撒拉必生一个儿子。'),
('CUV', '罗马书', 45, 9, 10, '不但如此，还有利百加，既从一个人，就是从我们的祖宗以撒怀了孕，'),
('CUV', '罗马书', 45, 9, 11, '（双子还没有生下来，善恶还没有做出来，只因要显明神拣选人的旨意，不在乎人的行为，乃在乎召人的主。）'),
('CUV', '罗马书', 45, 9, 12, '神就对利百加说：将来大的要服事小的。'),
('CUV', '罗马书', 45, 9, 13, '正如经上所记：雅各是我所爱的；以扫是我所恶的。'),
('CUV', '罗马书', 45, 9, 14, '这样，我们可说甚么呢？难道神有甚么不公平么？断乎没有！'),
('CUV', '罗马书', 45, 9, 15, '因他对摩西说：我要怜悯谁就怜悯谁，要恩待谁就恩待谁。'),
('CUV', '罗马书', 45, 9, 16, '据此看来，这不在乎那定意的，也不在乎那奔跑的，只在乎发怜悯的神。'),
('CUV', '罗马书', 45, 9, 17, '因为经上有话向法老说：我将你兴起来，特要在你身上彰显我的权能，并要使我的名传遍天下。'),
('CUV', '罗马书', 45, 9, 18, '如此看来，神要怜悯谁就怜悯谁，要叫谁刚硬就叫谁刚硬。'),
('CUV', '罗马书', 45, 9, 19, '这样，你必对我说：他为甚么还指责人呢？有谁抗拒他的旨意呢？'),
('CUV', '罗马书', 45, 9, 20, '你这个人哪，你是谁，竟敢向神强嘴呢？受造之物岂能对造他的说：你为甚么这样造我呢？'),
('CUV', '罗马书', 45, 9, 21, '窑匠难道没有权柄从一团泥里拿一块做成贵重的器皿，又拿一块做成卑贱的器皿么？'),
('CUV', '罗马书', 45, 9, 22, '倘若神要显明他的忿怒，彰显他的权能，就多多忍耐宽容那可怒预备遭毁灭的器皿，'),
('CUV', '罗马书', 45, 9, 23, '又要将他丰盛的荣耀彰显在那蒙怜悯早预备得荣耀的器皿上。'),
('CUV', '罗马书', 45, 9, 24, '这器皿就是我们被神所召的，不但是从犹太人中，也是从外邦人中。这有甚么不可呢？'),
('CUV', '罗马书', 45, 9, 25, '就像神在何西阿书上说：那本来不是我子民的，我要称为我的子民；本来不是蒙爱的，我要称为蒙爱的。'),
('CUV', '罗马书', 45, 9, 26, '从前在甚么地方对他们说：你们不是我的子民，将来就在那里称他们为永生神的儿子。'),
('CUV', '罗马书', 45, 9, 27, '以赛亚指著以色列人喊著说：以色列人虽多如海沙，得救的不过是剩下的余数；'),
('CUV', '罗马书', 45, 9, 28, '因为主要在世上施行他的话，叫他的话都成全，速速的完结。'),
('CUV', '罗马书', 45, 9, 29, '又如以赛亚先前说过：若不是万军之主给我们存留余种，我们早已像所多玛，蛾摩拉的样子了。'),
('CUV', '罗马书', 45, 9, 30, '这样，我们可说甚么呢？那本来不追求义的外邦人反得了义，就是因信而得的义。'),
('CUV', '罗马书', 45, 9, 31, '但以色列人追求律法的义，反得不著律法的义。'),
('CUV', '罗马书', 45, 9, 32, '这是甚么缘故呢？是因为他们不凭著信心求，只凭著行为求，他们正跌在那绊脚石上。'),
('CUV', '罗马书', 45, 9, 33, '就如经上所记：我在锡安放一块绊脚的石头，跌人的磐石；信靠他的人必不至于羞愧。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 10, 1, '弟兄们，我心里所愿的，向神所求的，是要以色列人得救。'),
('CUV', '罗马书', 45, 10, 2, '我可以证明他们向神有热心，但不是按著真知识；'),
('CUV', '罗马书', 45, 10, 3, '因为不知道神的义，想要立自己的义，就不服神的义了。'),
('CUV', '罗马书', 45, 10, 4, '律法的总结就是基督，使凡信他的都得著义。'),
('CUV', '罗马书', 45, 10, 5, '摩西写著说：人若行那出于律法的义，就必因此活著。'),
('CUV', '罗马书', 45, 10, 6, '惟有出于信心的义如此说：你不要心里说：谁要升到天上去呢？就是要领下基督来；'),
('CUV', '罗马书', 45, 10, 7, '谁要下到阴间去呢？就是要领基督从死里上来。'),
('CUV', '罗马书', 45, 10, 8, '他到底怎么说呢？他说：这道离你不远，正在你口里，在你心里。就是我们所传信主的道。'),
('CUV', '罗马书', 45, 10, 9, '你若口里认耶稣为主，心里信神叫他从死里复活，就必得救。'),
('CUV', '罗马书', 45, 10, 10, '因为人心里相信，就可以称义；口里承认，就可以得救。'),
('CUV', '罗马书', 45, 10, 11, '经上说：凡信他的人必不至于羞愧。'),
('CUV', '罗马书', 45, 10, 12, '犹太人和希利尼人并没有分别，因为众人同有一位主；他也厚待一切求告他的人。'),
('CUV', '罗马书', 45, 10, 13, '因为凡求告主名的，就必得救。'),
('CUV', '罗马书', 45, 10, 14, '然而，人未曾信他，怎能求他呢？未曾听见他，怎能信他呢？没有传道的，怎能听见呢？'),
('CUV', '罗马书', 45, 10, 15, '若没有奉差遣，怎能传道呢？如经上所记：报福音、传喜信的人，他们的脚踪何等佳美。'),
('CUV', '罗马书', 45, 10, 16, '只是人没有都听从福音，因为以赛亚说：主阿，我们所传的有谁信呢？'),
('CUV', '罗马书', 45, 10, 17, '可见信道是从听道来的，听道是从基督的话来的。'),
('CUV', '罗马书', 45, 10, 18, '但我说，人没有听见么？诚然听见了。他们的声音传遍天下；他们的言语传到地极。'),
('CUV', '罗马书', 45, 10, 19, '我再说，以色列人不知道么？先有摩西说：我要用那不成子民的，惹动你们的愤恨；我要用那无知的民触动你们的怒气。'),
('CUV', '罗马书', 45, 10, 20, '又有以赛亚放胆说：没有寻找我的，我叫他们遇见；没有访问我的，我向他们显现。'),
('CUV', '罗马书', 45, 10, 21, '至于以色列人，他说：我整天伸手招呼那悖逆顶嘴的百姓。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 11, 1, '我且说，神弃绝了他的百姓么？断乎没有！因为我也是以色列人，亚伯拉罕的后裔，属便雅悯支派的。'),
('CUV', '罗马书', 45, 11, 2, '神并没有弃绝他预先所知道的百姓。你们岂不晓得经上论到以利亚是怎么说的呢？他在神面前怎样控告以色列人说：'),
('CUV', '罗马书', 45, 11, 3, '主阿，他们杀了你的先知，拆了你的祭坛，只剩下我一个人，他们还要寻索我的命。'),
('CUV', '罗马书', 45, 11, 4, '神的回话是怎么说的呢？他说：我为自己留下七千人，是未曾向巴力屈膝的。'),
('CUV', '罗马书', 45, 11, 5, '如今也是这样，照著拣选的恩典，还有所留的余数。'),
('CUV', '罗马书', 45, 11, 6, '既是出于恩典，就不在乎行为；不然，恩典就不是恩典了。'),
('CUV', '罗马书', 45, 11, 7, '这是怎么样呢？以色列人所求的，他们没有得著，惟有蒙拣选的人得著了；其余的就成了顽梗不化的。'),
('CUV', '罗马书', 45, 11, 8, '如经上所记：神给他们昏迷的心，眼睛不能看见，耳朵不能听见，直到今日。'),
('CUV', '罗马书', 45, 11, 9, '大卫也说：愿他们的筵席变为网罗，变为机槛，变为绊脚石，作他们的报应。'),
('CUV', '罗马书', 45, 11, 10, '愿他们的眼睛昏蒙，不得看见；愿你时常弯下他们的腰。'),
('CUV', '罗马书', 45, 11, 11, '我且说，他们失脚是要他们跌倒么？断乎不是！反倒因他们的过失，救恩便临到外邦人，要激动他们发愤。'),
('CUV', '罗马书', 45, 11, 12, '若他们的过失，为天下的富足，他们的缺乏，为外邦人的富足；何况他们的丰满呢？'),
('CUV', '罗马书', 45, 11, 13, '我对你们外邦人说这话；因我是外邦人的使徒，所以敬重（原文作：荣耀）我的职分，'),
('CUV', '罗马书', 45, 11, 14, '或者可以激动我骨肉之亲发愤，好救他们一些人。'),
('CUV', '罗马书', 45, 11, 15, '若他们被丢弃，天下就得与神和好；他们被收纳，岂不是死而复生么？'),
('CUV', '罗马书', 45, 11, 16, '所献的新面若是圣洁，全团也就圣洁了；树根若是圣洁，树枝也就圣洁了。'),
('CUV', '罗马书', 45, 11, 17, '若有几根枝子被折下来，你这野橄榄得接在其中，一同得著橄榄根的肥汁，'),
('CUV', '罗马书', 45, 11, 18, '你就不可向旧枝子夸口；若是夸口，当知道不是你托著根，乃是根托著你。'),
('CUV', '罗马书', 45, 11, 19, '你若说，那枝子被折下来是特为叫我接上。'),
('CUV', '罗马书', 45, 11, 20, '不错！他们因为不信，所以被折下来；你因为信，所以立得住；你不可自高，反要惧怕。'),
('CUV', '罗马书', 45, 11, 21, '神既不爱惜原来的枝子，也必不爱惜你。'),
('CUV', '罗马书', 45, 11, 22, '可见神的恩慈和严厉，向那跌倒的人是严厉的，向你是有恩慈的；只要你长久在他的恩慈里，不然，你也要被砍下来。'),
('CUV', '罗马书', 45, 11, 23, '而且他们若不是长久不信，仍要被接上，因为神能够把他们从新接上。'),
('CUV', '罗马书', 45, 11, 24, '你是从那天生的野橄榄上砍下来的，尚且逆著性得接在好橄榄上，何况这本树的枝子，要接在本树上呢！'),
('CUV', '罗马书', 45, 11, 25, '弟兄们，我不愿意你们不知道这奥秘（恐怕你们自以为聪明），就是以色列人有几分是硬心的，等到外邦人的数目添满了，'),
('CUV', '罗马书', 45, 11, 26, '于是以色列全家都要得救。如经上所记：必有一位救主从锡安出来，要消除雅各家的一切罪恶；'),
('CUV', '罗马书', 45, 11, 27, '又说：我除去他们罪的时候，这就是我与他们所立的约。'),
('CUV', '罗马书', 45, 11, 28, '就著福音说，他们为你们的缘故是仇敌；就著拣选说，他们为列祖的缘故是蒙爱的。'),
('CUV', '罗马书', 45, 11, 29, '因为神的恩赐和选召是没有后悔的。'),
('CUV', '罗马书', 45, 11, 30, '你们从前不顺服神，如今因他们的不顺服，你们倒蒙了怜恤。'),
('CUV', '罗马书', 45, 11, 31, '这样，他们也是不顺服，叫他们因著施给你们的怜恤，现在也就蒙怜恤。'),
('CUV', '罗马书', 45, 11, 32, '因为神将众人都圈在不顺服之中，特意要怜恤众人。'),
('CUV', '罗马书', 45, 11, 33, '深哉，神丰富的智慧和知识！他的判断何其难测！他的踪迹何其难寻！'),
('CUV', '罗马书', 45, 11, 34, '谁知道主的心？谁作过他的谋士呢？'),
('CUV', '罗马书', 45, 11, 35, '谁是先给了他，使他后来偿还呢？'),
('CUV', '罗马书', 45, 11, 36, '因为万有都是本于他，倚靠他，归于他。愿荣耀归给他，直到永远。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 12, 1, '所以弟兄们，我以神的慈悲劝你们，将身体献上，当作活祭，是圣洁的，是神所喜悦的；你们如此事奉乃是理所当然的。'),
('CUV', '罗马书', 45, 12, 2, '不要效法这个世界，只要心意更新而变化，叫你们察验何为神的善良、纯全、可喜悦的旨意。'),
('CUV', '罗马书', 45, 12, 3, '我凭著所赐我的恩对你们各人说：不要看自己过于所当看的，要照著神所分给各人信心的大小，看得合乎中道。'),
('CUV', '罗马书', 45, 12, 4, '正如我们一个身子上有好些肢体，肢体也不都是一样的用处。'),
('CUV', '罗马书', 45, 12, 5, '我们这许多人，在基督里成为一身，互相联络作肢体，也是如此。'),
('CUV', '罗马书', 45, 12, 6, '按我们所得的恩赐，各有不同。或说预言，就当照著信心的程度说预言，'),
('CUV', '罗马书', 45, 12, 7, '或作执事，就当专一执事；或作教导的，就当专一教导；'),
('CUV', '罗马书', 45, 12, 8, '或作劝化的，就当专一劝化；施舍的，就当诚实；治理的，就当殷勤；怜悯人的，就当甘心。'),
('CUV', '罗马书', 45, 12, 9, '爱人不可虚假；恶要厌恶，善要亲近。'),
('CUV', '罗马书', 45, 12, 10, '爱弟兄，要彼此亲热；恭敬人，要彼此推让。'),
('CUV', '罗马书', 45, 12, 11, '殷勤不可懒惰。要心里火热，常常服事主。'),
('CUV', '罗马书', 45, 12, 12, '在指望中要喜乐，在患难中要忍耐，祷告要恒切。'),
('CUV', '罗马书', 45, 12, 13, '圣徒缺乏要帮补；客要一味的款待。'),
('CUV', '罗马书', 45, 12, 14, '逼迫你们的，要给他们祝福；只要祝福，不可咒诅。'),
('CUV', '罗马书', 45, 12, 15, '与喜乐的人要同乐；与哀哭的人要同哭。'),
('CUV', '罗马书', 45, 12, 16, '要彼此同心；不要志气高大，倒要俯就卑微的人（人：或作事）；不要自以为聪明。'),
('CUV', '罗马书', 45, 12, 17, '不要以恶报恶；众人以为美的事要留心去做。'),
('CUV', '罗马书', 45, 12, 18, '若是能行，总要尽力与众人和睦。'),
('CUV', '罗马书', 45, 12, 19, '亲爱的弟兄，不要自己伸冤，宁可让步，听凭主怒（或作：让人发怒）；因为经上记著：主说：伸冤在我；我必报应。'),
('CUV', '罗马书', 45, 12, 20, '所以，你的仇敌若饿了，就给他吃，若渴了，就给他喝；因为你这样行就是把炭火堆在他的头上。'),
('CUV', '罗马书', 45, 12, 21, '你不可为恶所胜，反要以善胜恶。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 13, 1, '在上有权柄的，人人当顺服他，因为没有权柄不是出于神的。凡掌权的都是神所命的。'),
('CUV', '罗马书', 45, 13, 2, '所以，抗拒掌权的就是抗拒神的命；抗拒的必自取刑罚。'),
('CUV', '罗马书', 45, 13, 3, '作官的原不是叫行善的惧怕，乃是叫作恶的惧怕。你愿意不惧怕掌权的么？你只要行善，就可得他的称赞；'),
('CUV', '罗马书', 45, 13, 4, '因为他是神的用人，是与你有益的。你若作恶，却当惧怕；因为他不是空空的佩剑，他是神的用人，是伸冤的，刑罚那作恶的。'),
('CUV', '罗马书', 45, 13, 5, '所以你们必须顺服，不但是因为刑罚，也是因为良心。'),
('CUV', '罗马书', 45, 13, 6, '你们纳粮，也为这个缘故；因他们是神的差役，常常特管这事。'),
('CUV', '罗马书', 45, 13, 7, '凡人所当得的，就给他。当得粮的，给他纳粮；当得税的，给他上税；当惧怕的，惧怕他；当恭敬的，恭敬他。'),
('CUV', '罗马书', 45, 13, 8, '凡事都不可亏欠人，惟有彼此相爱要常以为亏欠，因为爱人的就完全了律法。'),
('CUV', '罗马书', 45, 13, 9, '像那不可奸淫，不可杀人，不可偷盗，不可贪婪，或有别的诫命，都包在爱人如己这一句话之内了。'),
('CUV', '罗马书', 45, 13, 10, '爱是不加害与人的，所以爱就完全了律法。'),
('CUV', '罗马书', 45, 13, 11, '再者，你们晓得现今就是该趁早睡醒的时候；因为我们得救，现今比初信的时候更近了。'),
('CUV', '罗马书', 45, 13, 12, '黑夜已深，白昼将近；我们就当脱去暗昧的行为，带上光明的兵器。'),
('CUV', '罗马书', 45, 13, 13, '行事为人要端正，好像行在白昼。不可荒宴醉酒，不可好色邪荡，不可争竞嫉妒；'),
('CUV', '罗马书', 45, 13, 14, '总要披戴主耶稣基督，不要为肉体安排，去放纵私欲。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 14, 1, '信心软弱的，你们要接纳，但不要辩论所疑惑的事。'),
('CUV', '罗马书', 45, 14, 2, '有人信百物都可吃；但那软弱的，只吃蔬菜。'),
('CUV', '罗马书', 45, 14, 3, '吃的人不可轻看不吃的人；不吃的人不可论断吃的人；因为神已经收纳他了。'),
('CUV', '罗马书', 45, 14, 4, '你是谁，竟论断别人的仆人呢？他或站住，或跌倒，自有他的主人在；而且他也必要站住，因为主能使他站住。'),
('CUV', '罗马书', 45, 14, 5, '有人看这日比那日强；有人看日日都是一样。只是各人心里要意见坚定。'),
('CUV', '罗马书', 45, 14, 6, '守日的人是为主守的；吃的人是为主吃的，因他感谢神；不吃的人是为主不吃的，也感谢神。'),
('CUV', '罗马书', 45, 14, 7, '我们没有一个人为自己活，也没有一个人为自己死。'),
('CUV', '罗马书', 45, 14, 8, '我们若活著，是为主而活；若死了，是为主而死。所以，我们或活或死总是主的人。'),
('CUV', '罗马书', 45, 14, 9, '因此基督死了又活了，为要作死人并活人的主。'),
('CUV', '罗马书', 45, 14, 10, '你这个人，为甚么论断弟兄呢？又为甚么轻看弟兄呢？因我们都要站在神的台前。'),
('CUV', '罗马书', 45, 14, 11, '经上写著：主说：我凭著我的永生起誓：万膝必向我跪拜；万口必向我承认。'),
('CUV', '罗马书', 45, 14, 12, '这样看来，我们各人必要将自己的事在神面前说明。'),
('CUV', '罗马书', 45, 14, 13, '所以，我们不可再彼此论断，宁可定意谁也不给弟兄放下绊脚跌人之物。'),
('CUV', '罗马书', 45, 14, 14, '我凭著主耶稣确知深信，凡物本来没有不洁净的；惟独人以为不洁净的，在他就不洁净了。'),
('CUV', '罗马书', 45, 14, 15, '你若因食物叫弟兄忧愁，就不是按著爱人的道理行。基督已经替他死，你不可因你的食物叫他败坏。'),
('CUV', '罗马书', 45, 14, 16, '不可叫你的善被人毁谤；'),
('CUV', '罗马书', 45, 14, 17, '因为神的国不在乎吃喝，只在乎公义、和平，并圣灵中的喜乐。'),
('CUV', '罗马书', 45, 14, 18, '在这几样上服事基督的，就为神所喜悦，又为人所称许。'),
('CUV', '罗马书', 45, 14, 19, '所以，我们务要追求和睦的事与彼此建立德行的事。'),
('CUV', '罗马书', 45, 14, 20, '不可因食物毁坏神的工程。凡物固然洁净，但有人因食物叫人跌倒，就是他的罪了。'),
('CUV', '罗马书', 45, 14, 21, '无论是吃肉，是喝酒，是甚么别的事，叫弟兄跌倒，一概不做才好。'),
('CUV', '罗马书', 45, 14, 22, '你有信心，就当在神面前守著。人在自己以为可行的事上能不自责，就有福了。'),
('CUV', '罗马书', 45, 14, 23, '若有疑心而吃的，就必有罪，因为他吃不是出于信心。凡不出于信心的都是罪。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 15, 1, '我们坚固的人应该担代不坚固人的软弱，不求自己的喜悦。'),
('CUV', '罗马书', 45, 15, 2, '我们各人务要叫邻舍喜悦，使他得益处，建立德行。'),
('CUV', '罗马书', 45, 15, 3, '因为基督也不求自己的喜悦，如经上所记：辱骂你人的辱骂都落在我身上。'),
('CUV', '罗马书', 45, 15, 4, '从前所写的圣经都是为教训我们写的，叫我们因圣经所生的忍耐和安慰可以得著盼望。'),
('CUV', '罗马书', 45, 15, 5, '但愿赐忍耐安慰的神叫你们彼此同心，效法基督耶稣，'),
('CUV', '罗马书', 45, 15, 6, '一心一口荣耀神─我们主耶稣基督的父！'),
('CUV', '罗马书', 45, 15, 7, '所以，你们要彼此接纳，如同基督接纳你们一样，使荣耀归与神。'),
('CUV', '罗马书', 45, 15, 8, '我说，基督是为神真理作了受割礼人的执事，要证实所应许列祖的话，'),
('CUV', '罗马书', 45, 15, 9, '并叫外邦人因他的怜悯荣耀神。如经上所记：因此，我要在外邦中称赞你，歌颂你的名；'),
('CUV', '罗马书', 45, 15, 10, '又说：你们外邦人当与主的百姓一同欢乐；'),
('CUV', '罗马书', 45, 15, 11, '又说：外邦阿，你们当赞美主！万民哪，你们都当颂赞他！'),
('CUV', '罗马书', 45, 15, 12, '又有以赛亚说：将来有耶西的根，就是那兴起来要治理外邦的；外邦人要仰望他。'),
('CUV', '罗马书', 45, 15, 13, '但愿使人有盼望的神，因信将诸般的喜乐、平安充满你们的心，使你们藉著圣灵的能力大有盼望。'),
('CUV', '罗马书', 45, 15, 14, '弟兄们，我自己也深信你们是满有良善，充足了诸般的知识，也能彼此劝戒。'),
('CUV', '罗马书', 45, 15, 15, '但我稍微放胆写信给你们，是要提醒你们的记性，特因神所给我的恩典，'),
('CUV', '罗马书', 45, 15, 16, '使我为外邦人作基督耶稣的仆役，作神福音的祭司，叫所献上的外邦人，因著圣灵成为圣洁，可蒙悦纳。'),
('CUV', '罗马书', 45, 15, 17, '所以论到神的事，我在基督耶稣里有可夸的。'),
('CUV', '罗马书', 45, 15, 18, '除了基督藉我做的那些事，我甚么都不敢提，只提他藉我言语作为，用神迹奇事的能力，并圣灵的能力，使外邦人顺服；'),
('CUV', '罗马书', 45, 15, 19, '甚至我从耶路撒冷，直转到以利哩古，到处传了基督的福音。'),
('CUV', '罗马书', 45, 15, 20, '我立了志向，不在基督的名被称过的地方传福音，免得建造在别人的根基上。'),
('CUV', '罗马书', 45, 15, 21, '就如经上所记：未曾闻知他信息的，将要看见；未曾听过的，将要明白。'),
('CUV', '罗马书', 45, 15, 22, '我因多次被拦阻，总不得到你们那里去。'),
('CUV', '罗马书', 45, 15, 23, '但如今，在这里再没有可传的地方，而且这好几年，我切心想望到士班雅去的时候，可以到你们那里，'),
('CUV', '罗马书', 45, 15, 24, '盼望从你们那里经过，得见你们，先与你们彼此交往，心里稍微满足，然后蒙你们送行。'),
('CUV', '罗马书', 45, 15, 25, '但现在，我往耶路撒冷去供给圣徒。'),
('CUV', '罗马书', 45, 15, 26, '因为马其顿和亚该亚人乐意凑出捐项给耶路撒冷圣徒中的穷人。'),
('CUV', '罗马书', 45, 15, 27, '这固然是他们乐意的，其实也算是所欠的债；因外邦人既然在他们属灵的好处上有分，就当把养身之物供给他们。'),
('CUV', '罗马书', 45, 15, 28, '等我办完了这事，把这善果向他们交付明白，我就要路过你们那里，往士班雅去。'),
('CUV', '罗马书', 45, 15, 29, '我也晓得去的时候，必带著基督丰盛的恩典而去。'),
('CUV', '罗马书', 45, 15, 30, '弟兄们，我藉著我们主耶稣基督，又藉著圣灵的爱，劝你们与我一同竭力，为我祈求神，'),
('CUV', '罗马书', 45, 15, 31, '叫我脱离在犹太不顺从的人，也叫我为耶路撒冷所办的捐项可蒙圣徒悦纳，'),
('CUV', '罗马书', 45, 15, 32, '并叫我顺著神的旨意，欢欢喜喜的到你们那里，与你们同得安息。'),
('CUV', '罗马书', 45, 15, 33, '愿赐平安的神常和你们众人同在。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '罗马书', 45, 16, 1, '我对你们举荐我们的姊妹非比，他是坚革哩教会中的女执事。'),
('CUV', '罗马书', 45, 16, 2, '请你们为主接待他，合乎圣徒的体统。他在何事上要你们帮助，你们就帮助他，因他素来帮助许多人，也帮助了我。'),
('CUV', '罗马书', 45, 16, 3, '问百基拉和亚居拉安。他们在基督耶稣里与我同工，'),
('CUV', '罗马书', 45, 16, 4, '也为我的命将自己的颈项置之度外。不但我感谢他们，就是外邦的众教会也感谢他们。'),
('CUV', '罗马书', 45, 16, 5, '又问在他们家中的教会安。问我所亲爱的以拜尼土安；他在亚西亚是归基督初结的果子。'),
('CUV', '罗马书', 45, 16, 6, '又问马利亚安；他为你们多受劳苦。'),
('CUV', '罗马书', 45, 16, 7, '又问我亲属与我一同坐监的安多尼古和犹尼亚安；他们在使徒中是有名望的，也是比我先在基督里。'),
('CUV', '罗马书', 45, 16, 8, '又问我在主里面所亲爱的暗伯利安。'),
('CUV', '罗马书', 45, 16, 9, '又问在基督里与我们同工的耳巴奴，并我所亲爱的士大古安。'),
('CUV', '罗马书', 45, 16, 10, '又问在基督里经过试验的亚比利安。问亚利多布家里的人安。'),
('CUV', '罗马书', 45, 16, 11, '又问我亲属希罗天安。问拿其数家在主里的人安。'),
('CUV', '罗马书', 45, 16, 12, '又问为主劳苦的土非拿氏和土富撒氏安。问可亲爱为主多受劳苦的彼息氏安。'),
('CUV', '罗马书', 45, 16, 13, '又问在主蒙拣选的鲁孚和他母亲安；他的母亲就是我的母亲。'),
('CUV', '罗马书', 45, 16, 14, '又问亚逊其土、弗勒干、黑米、八罗巴、黑马，并与他们在一处的弟兄们安。'),
('CUV', '罗马书', 45, 16, 15, '又问非罗罗古和犹利亚，尼利亚和他姊妹，同阿林巴并与他们在一处的众圣徒安。'),
('CUV', '罗马书', 45, 16, 16, '你们亲嘴问安，彼此务要圣洁。基督的众教会都问你们安。'),
('CUV', '罗马书', 45, 16, 17, '弟兄们，那些离间你们、叫你们跌倒、背乎所学之道的人，我劝你们要留意躲避他们。'),
('CUV', '罗马书', 45, 16, 18, '因为这样的人不服事我们的主基督，只服事自己的肚腹，用花言巧语诱惑那些老实人的心。'),
('CUV', '罗马书', 45, 16, 19, '你们的顺服已经传于众人，所以我为你们欢喜；但我愿意你们在善上聪明，在恶上愚拙。'),
('CUV', '罗马书', 45, 16, 20, '赐平安的神快要将撒但践踏在你们脚下。愿我主耶稣基督的恩常和你们同在！'),
('CUV', '罗马书', 45, 16, 21, '与我同工的提摩太，和我的亲属路求、耶孙、所西巴德，问你们安。'),
('CUV', '罗马书', 45, 16, 22, '我这代笔写信的德丢，在主里面问你们安。'),
('CUV', '罗马书', 45, 16, 23, '那接待我、也接待全教会的该犹问你们安。'),
('CUV', '罗马书', 45, 16, 24, '城内管银库的以拉都，和兄弟括土问你们安。'),
('CUV', '罗马书', 45, 16, 25, '惟有神能照我所传的福音和所讲的耶稣基督，并照永古隐藏不言的奥秘，坚固你们的心。'),
('CUV', '罗马书', 45, 16, 26, '这奥秘如今显明出来，而且按著永生神的命，藉众先知的书指示万国的民，使他们信服真道。'),
('CUV', '罗马书', 45, 16, 27, '愿荣耀因耶稣基督归与独一全智的神，直到永远。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 1, 1, '奉神旨意，蒙召作耶稣基督使徒的保罗，同兄弟所提尼，'),
('CUV', '哥林多前书', 46, 1, 2, '写信给在哥林多神的教会，就是在基督耶稣里成圣、蒙召作圣徒的，以及所有在各处求告我主耶稣基督之名的人。基督是他们的主，也是我们的主。'),
('CUV', '哥林多前书', 46, 1, 3, '愿恩惠、平安从神我们的父并主耶稣基督归与你们。'),
('CUV', '哥林多前书', 46, 1, 4, '我常为你们感谢我的神，因神在基督耶稣里所赐给你们的恩惠；'),
('CUV', '哥林多前书', 46, 1, 5, '又因你们在他里面凡事富足，口才、知识都全备，'),
('CUV', '哥林多前书', 46, 1, 6, '正如我为基督作的见证，在你们心里得以坚固，'),
('CUV', '哥林多前书', 46, 1, 7, '以致你们在恩赐上没有一样不及人的，等候我们的主耶稣基督显现。'),
('CUV', '哥林多前书', 46, 1, 8, '他也必坚固你们到底，叫你们在我们主耶稣基督的日子无可责备。'),
('CUV', '哥林多前书', 46, 1, 9, '神是信实的，你们原是被他所召，好与他儿子─我们的主耶稣基督一同得分。'),
('CUV', '哥林多前书', 46, 1, 10, '弟兄们，我藉我们主耶稣基督的名劝你们都说一样的话。你们中间也不可分党，只要一心一意，彼此相合。'),
('CUV', '哥林多前书', 46, 1, 11, '因为革来氏家里的人曾对我题起弟兄们来，说你们中间有分争。'),
('CUV', '哥林多前书', 46, 1, 12, '我的意思就是你们各人说：我是属保罗的；我是属亚波罗的；我是属矶法的；我是属基督的。'),
('CUV', '哥林多前书', 46, 1, 13, '基督是分开的么？保罗为你们钉了十字架么？你们是奉保罗的名受了洗么？'),
('CUV', '哥林多前书', 46, 1, 14, '我感谢神，除了基利司布并该犹以外，我没有给你们一个人施洗；'),
('CUV', '哥林多前书', 46, 1, 15, '免得有人说，你们是奉我的名受洗。'),
('CUV', '哥林多前书', 46, 1, 16, '我也给司提反家施过洗，此外给别人施洗没有，我却记不清。'),
('CUV', '哥林多前书', 46, 1, 17, '基督差遣我，原不是为施洗，乃是为传福音，并不用智慧的言语，免得基督的十字架落了空。'),
('CUV', '哥林多前书', 46, 1, 18, '因为十字架的道理，在那灭亡的人为愚拙；在我们得救的人，却为神的大能。'),
('CUV', '哥林多前书', 46, 1, 19, '就如经上所记：我要灭绝智慧人的智慧，废弃聪明人的聪明。'),
('CUV', '哥林多前书', 46, 1, 20, '智慧人在那里？文士在那里？这世上的辩士在那里？神岂不是叫这世上的智慧变成愚拙么？'),
('CUV', '哥林多前书', 46, 1, 21, '世人凭自己的智慧，既不认识神，神就乐意用人所当作愚拙的道理，拯救那些信的人；这就是神的智慧了。'),
('CUV', '哥林多前书', 46, 1, 22, '犹太人是要神迹，希利尼人是求智慧，'),
('CUV', '哥林多前书', 46, 1, 23, '我们却是传钉十字架的基督，在犹太人为绊脚石，在外邦人为愚拙；'),
('CUV', '哥林多前书', 46, 1, 24, '但在那蒙召的，无论是犹太人、希利尼人，基督总为神的能力，神的智慧。'),
('CUV', '哥林多前书', 46, 1, 25, '因神的愚拙总比人智慧，神的软弱总比人强壮。'),
('CUV', '哥林多前书', 46, 1, 26, '弟兄们哪，可见你们蒙召的，按著肉体有智慧的不多，有能力的不多，有尊贵的也不多。'),
('CUV', '哥林多前书', 46, 1, 27, '神却拣选了世上愚拙的，叫有智慧的羞愧；又拣选了世上软弱的，叫那强壮的羞愧。'),
('CUV', '哥林多前书', 46, 1, 28, '神也拣选了世上卑贱的，被人厌恶的，以及那无有的，为要废掉那有的。'),
('CUV', '哥林多前书', 46, 1, 29, '使一切有血气的，在神面前一个也不能自夸。'),
('CUV', '哥林多前书', 46, 1, 30, '但你们得在基督耶稣里，是本乎神，神又使他成为我们的智慧、公义、圣洁、救赎。'),
('CUV', '哥林多前书', 46, 1, 31, '如经上所记：夸口的，当指著主夸口。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 2, 1, '弟兄们，从前我到你们那里去，并没有用高言大智对你们宣传神的奥秘。'),
('CUV', '哥林多前书', 46, 2, 2, '因为我曾定了主意，在你们中间不知道别的，只知道耶稣基督并他钉十字架。'),
('CUV', '哥林多前书', 46, 2, 3, '我在你们那里，又软弱又惧怕，又甚战兢。'),
('CUV', '哥林多前书', 46, 2, 4, '我说的话、讲的道，不是用智慧委婉的言语，乃是用圣灵和大能的明证，'),
('CUV', '哥林多前书', 46, 2, 5, '叫你们的信不在乎人的智慧，只在乎神的大能。'),
('CUV', '哥林多前书', 46, 2, 6, '然而，在完全的人中，我们也讲智慧。但不是这世上的智慧，也不是这世上有权有位、将要败亡之人的智慧。'),
('CUV', '哥林多前书', 46, 2, 7, '我们讲的，乃是从前所隐藏、神奥秘的智慧，就是神在万世以前预定使我们得荣耀的。'),
('CUV', '哥林多前书', 46, 2, 8, '这智慧世上有权有位的人没有一个知道的、他们若知道，就不把荣耀的主钉在十字架上了。'),
('CUV', '哥林多前书', 46, 2, 9, '如经上所记：神为爱他的人所预备的是眼睛未曾看见，耳朵未曾听见，人心也未曾想到的。'),
('CUV', '哥林多前书', 46, 2, 10, '只有神藉著圣灵向我们显明了，因为圣灵参透万事，就是神深奥的事也参透了。'),
('CUV', '哥林多前书', 46, 2, 11, '除了在人里头的灵，谁知道人的事；像这样，除了神的灵，也没有人知道神的事。'),
('CUV', '哥林多前书', 46, 2, 12, '我们所领受的，并不是世上的灵，乃是从神来的灵，叫我们能知道神开恩赐给我们的事。'),
('CUV', '哥林多前书', 46, 2, 13, '并且我们讲说这些事，不是用人智慧所指教言语，乃是用圣灵所指教的言语，将属灵的话解释属灵的事。（或作：将属灵的事讲与属灵的人）'),
('CUV', '哥林多前书', 46, 2, 14, '然而，属血气的人不领会神圣灵的事，反倒以为愚拙，并且不能知道，因为这些事惟有属灵的人才能看透。'),
('CUV', '哥林多前书', 46, 2, 15, '属灵的人能看透万事，却没有一人能看透了他。'),
('CUV', '哥林多前书', 46, 2, 16, '谁曾知道主的心去教导他呢？但我们是有基督的心了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 3, 1, '弟兄们，我从前对你们说话，不能把你们当作属灵的，只得把你们当作属肉体，在基督里为婴孩的。'),
('CUV', '哥林多前书', 46, 3, 2, '我是用奶喂你们，没有用饭喂你们。那时你们不能吃，就是如今还是不能。'),
('CUV', '哥林多前书', 46, 3, 3, '你们仍是属肉体的，因为在你们中间有嫉妒、分争，这岂不是属乎肉体、照著世人的样子行么？'),
('CUV', '哥林多前书', 46, 3, 4, '有说：我是属保罗的；有说：我是属亚波罗的。这岂不是你们和世人一样么？'),
('CUV', '哥林多前书', 46, 3, 5, '亚波罗算甚么？保罗算甚么？无非是执事，照主所赐给他们各人的，引导你们相信。'),
('CUV', '哥林多前书', 46, 3, 6, '我栽种了，亚波罗浇灌了，惟有神叫他生长。'),
('CUV', '哥林多前书', 46, 3, 7, '可见栽种的，算不得甚么，浇灌的，也算不得甚么；只在那叫他生长的神。'),
('CUV', '哥林多前书', 46, 3, 8, '栽种的和浇灌的，都是一样，但将来各人要照自己的工夫得自己的赏赐。'),
('CUV', '哥林多前书', 46, 3, 9, '因为我们是与神同工的；你们是神所耕种的田地，所建造的房屋。'),
('CUV', '哥林多前书', 46, 3, 10, '我照神所给我的恩，好像一个聪明的工头，立好了根基，有别人在上面建造；只是各人要谨慎怎样在上面建造。'),
('CUV', '哥林多前书', 46, 3, 11, '因为那已经立好的根基就是耶稣基督，此外没有人能立别的根基。'),
('CUV', '哥林多前书', 46, 3, 12, '若有人用金、银、宝石、草木，禾秸在这根基上建造，'),
('CUV', '哥林多前书', 46, 3, 13, '各人的工程必然显露，因为那日子要将他表明出来，有火发现；这火要试验各人的工程怎样。'),
('CUV', '哥林多前书', 46, 3, 14, '人在那根基上所建造的工程若存得住，他就要得赏赐。'),
('CUV', '哥林多前书', 46, 3, 15, '人的工程若被烧了，他就要受亏损，自己却要得救；虽然得救，乃像从火里经过的一样。'),
('CUV', '哥林多前书', 46, 3, 16, '岂不知你们是神的殿，神的灵住在你们里头么？'),
('CUV', '哥林多前书', 46, 3, 17, '若有人毁坏神的殿，神必要毁坏那人；因为神的殿是圣的，这殿就是你们。'),
('CUV', '哥林多前书', 46, 3, 18, '人不可自欺。你们中间若有人在这世界自以为有智慧，倒不如变作愚拙，好成为有智慧的。'),
('CUV', '哥林多前书', 46, 3, 19, '因这世界的智慧，在神看是愚拙。如经上记著说：主叫有智慧的，中了自己的诡计；'),
('CUV', '哥林多前书', 46, 3, 20, '又说：主知道智慧人的意念是虚妄的。'),
('CUV', '哥林多前书', 46, 3, 21, '所以无论谁，都不可拿人夸口，因为万有全是你们的。'),
('CUV', '哥林多前书', 46, 3, 22, '或保罗，或亚波罗，或矶法，或世界，或生，或死，或现今的事，或将来的事，全是你们的；'),
('CUV', '哥林多前书', 46, 3, 23, '并且你们是属基督的，基督又是属神的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 4, 1, '人应当以我们为基督的执事，为神奥秘事的管家。'),
('CUV', '哥林多前书', 46, 4, 2, '所求于管家的，是要他有忠心。'),
('CUV', '哥林多前书', 46, 4, 3, '我被你们论断，或被别人论断，我都以为极小的事；连我自己也不论断自己。'),
('CUV', '哥林多前书', 46, 4, 4, '我虽不觉得自己有错，却也不能因此得以称义；但判断我的乃是主。'),
('CUV', '哥林多前书', 46, 4, 5, '所以，时候未到，甚么都不要论断，只等主来，他要照出暗中的隐情，显明人心的意念。那时，各人要从神那里得著称赞。'),
('CUV', '哥林多前书', 46, 4, 6, '弟兄们，我为你们的缘故，拿这些事转比自己和亚波罗，叫你们效法我们不可过于圣经所记，免得你们自高自大，贵重这个，轻看那个。'),
('CUV', '哥林多前书', 46, 4, 7, '使你与人不同的是谁呢？你有甚么不是领受的呢；若是领受的，为何自夸，仿佛不是领受的呢？'),
('CUV', '哥林多前书', 46, 4, 8, '你们已经饱足了！已经丰富了！不用我们，自己就作王了！我愿意你们果真作王，叫我们也得与你们一同作王。'),
('CUV', '哥林多前书', 46, 4, 9, '我想神把我们使徒明明列在末后，好像定死罪的囚犯；因为我们成了一台戏，给世人和天使观看。'),
('CUV', '哥林多前书', 46, 4, 10, '我们为基督的缘故算是愚拙的，你们在基督里倒是聪明的；我们软弱，你们倒强壮；你们有荣耀，我们倒被藐视。'),
('CUV', '哥林多前书', 46, 4, 11, '直到如今，我们还是又饥又渴，又赤身露体，又挨打，又没有一定的住处，'),
('CUV', '哥林多前书', 46, 4, 12, '并且劳苦，亲手做工。被人咒骂，我们就祝福；被人逼迫，我们就忍受；'),
('CUV', '哥林多前书', 46, 4, 13, '被人毁谤，我们就善劝。直到如今，人还把我们看作世界上的污秽，万物中的渣滓。'),
('CUV', '哥林多前书', 46, 4, 14, '我写这话，不是叫你们羞愧，乃是警戒你们，好像我所亲爱的儿女一样。'),
('CUV', '哥林多前书', 46, 4, 15, '你们学基督的，师傅虽有一万，为父的却是不多，因我在基督耶稣里用福音生了你们。'),
('CUV', '哥林多前书', 46, 4, 16, '所以，我求你们效法我。'),
('CUV', '哥林多前书', 46, 4, 17, '因此我已打发提摩太到你们那里去。他在主里面，是我所亲爱，有忠心的儿子。他必提醒你们，记念我在基督里怎样行事，在各处各教会中怎样教导人。'),
('CUV', '哥林多前书', 46, 4, 18, '有些人自高自大，以为我不到你们那里去；'),
('CUV', '哥林多前书', 46, 4, 19, '然而，主若许我，我必快到你们那里去，并且我所要知道的，不是那些自高自大之人的言语，乃是他们的权能。'),
('CUV', '哥林多前书', 46, 4, 20, '因为神的国不在乎言语，乃在乎权能。'),
('CUV', '哥林多前书', 46, 4, 21, '你们愿意怎么样呢？是愿意我带著刑杖到你们那里去呢？还是要我存慈爱温柔的心呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 5, 1, '风闻在你们中间有淫乱的事。这样的淫乱连外邦人中也没有，就是有人收了他的继母。'),
('CUV', '哥林多前书', 46, 5, 2, '你们还是自高自大，并不哀痛，把行这事的人从你们中间赶出去。'),
('CUV', '哥林多前书', 46, 5, 3, '我身子虽不在你们那里，心却在你们那里，好像我亲自与你们同在，已经判断了行这事的人。'),
('CUV', '哥林多前书', 46, 5, 4, '就是你们聚会的时候，我的心也同在。奉我们主耶稣的名，并用我们主耶稣的权能，'),
('CUV', '哥林多前书', 46, 5, 5, '要把这样的人交给撒但，败坏他的肉体，使他的灵魂在主耶稣的日子可以得救。'),
('CUV', '哥林多前书', 46, 5, 6, '你们这自夸是不好的。岂不知一点面酵能使全团发起来么？'),
('CUV', '哥林多前书', 46, 5, 7, '你们既是无酵的面，应当把旧酵除净，好使你们成为新团；因为我们逾越节的羔羊基督已经被杀献祭了。'),
('CUV', '哥林多前书', 46, 5, 8, '所以，我们守这节不可用旧酵，也不可用恶毒（或作：阴毒）、邪恶的酵，只用诚实真正的无酵饼。'),
('CUV', '哥林多前书', 46, 5, 9, '我先前写信给你们说，不可与淫乱的人相交。'),
('CUV', '哥林多前书', 46, 5, 10, '此话不是指这世上一概行淫乱的，或贪婪的，勒索的，或拜偶像的；若是这样，你们除非离开世界方可。'),
('CUV', '哥林多前书', 46, 5, 11, '但如今我写信给你们说，若有称为弟兄是行淫乱的，或贪婪的，或拜偶像的，或辱骂的，或醉酒的，或勒索的，这样的人不可与他相交，就是与他吃饭都不可。'),
('CUV', '哥林多前书', 46, 5, 12, '因为审判教外的人与我何干？教内的人岂不是你们审判的么？'),
('CUV', '哥林多前书', 46, 5, 13, '至于外人有神审判他们。你们应当把那恶人从你们中间赶出去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 6, 1, '你们中间有彼此相争的事，怎敢在不义的人面前求审，不在圣徒面前求审呢？'),
('CUV', '哥林多前书', 46, 6, 2, '岂不知圣徒要审判世界么？若世界为你们所审，难道你们不配审判这最小的事么？'),
('CUV', '哥林多前书', 46, 6, 3, '岂不知我们要审判天使么？何况今生的事呢？'),
('CUV', '哥林多前书', 46, 6, 4, '既是这样，你们若有今生的事当审判，是派教会所轻看的人审判么？'),
('CUV', '哥林多前书', 46, 6, 5, '我说这话是要叫你们羞耻。难道你们中间没有一个智慧人能审断弟兄们的事么？'),
('CUV', '哥林多前书', 46, 6, 6, '你们竟是弟兄与弟兄告状，而且告在不信主的人面前。'),
('CUV', '哥林多前书', 46, 6, 7, '你们彼此告状，这已经是你们的大错了。为甚么不情愿受欺呢？为甚么不情愿吃亏呢？'),
('CUV', '哥林多前书', 46, 6, 8, '你们倒是欺压人、亏负人，况且所欺压所亏负的就是弟兄。'),
('CUV', '哥林多前书', 46, 6, 9, '你们岂不知不义的人不能承受神的国么？不要自欺！无论是淫乱的、拜偶像的、奸淫的、作娈童的、亲男色的、'),
('CUV', '哥林多前书', 46, 6, 10, '偷窃的、贪婪的、醉酒的、辱骂的、勒索的，都不能承受神的国。'),
('CUV', '哥林多前书', 46, 6, 11, '你们中间也有人从前是这样；但如今你们奉主耶稣基督的名，并藉著我们神的灵，已经洗净，成圣，称义了。'),
('CUV', '哥林多前书', 46, 6, 12, '凡事我都可行，但不都有益处。凡事我都可行，但无论那一件，我总不受他的辖制。'),
('CUV', '哥林多前书', 46, 6, 13, '食物是为肚腹，肚腹是为食物；但神要叫这两样都废坏。身子不是为淫乱，乃是为主；主也是为身子。'),
('CUV', '哥林多前书', 46, 6, 14, '并且神已经叫主复活，也要用自己的能力叫我们复活。'),
('CUV', '哥林多前书', 46, 6, 15, '岂不知你们的身子是基督的肢体么？我可以将基督的肢体作为娼妓的肢体么？断乎不可！'),
('CUV', '哥林多前书', 46, 6, 16, '岂不知与娼妓联合的，便是与他成为一体么？因为主说﹕二人要成为一体。'),
('CUV', '哥林多前书', 46, 6, 17, '但与主联合的，便是与主成为一灵。'),
('CUV', '哥林多前书', 46, 6, 18, '你们要逃避淫行。人所犯的，无论甚么罪，都在身子以外，惟有行淫的，是得罪自己的身子。'),
('CUV', '哥林多前书', 46, 6, 19, '岂不知你们的身子就是圣灵的殿么？这圣灵是从神而来，住在你们里头的；并且你们不是自己的人；'),
('CUV', '哥林多前书', 46, 6, 20, '因为你们是重价买来的。所以，要在你们的身子上荣耀神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 7, 1, '论到你们信上所提的事，我说男不近女倒好。'),
('CUV', '哥林多前书', 46, 7, 2, '但要免淫乱的事，男子当各有自己的妻子；女子也当各有自己的丈夫。'),
('CUV', '哥林多前书', 46, 7, 3, '丈夫当用合宜之分待妻子；妻子待丈夫也要如此。'),
('CUV', '哥林多前书', 46, 7, 4, '妻子没有权柄主张自己的身子，乃在丈夫；丈夫也没有权柄主张自己的身子，乃在妻子。'),
('CUV', '哥林多前书', 46, 7, 5, '夫妻不可彼此亏负，除非两相情愿，暂时分房，为要专心祷告方可；以后仍要同房，免得撒但趁著你们情不自禁，引诱你们。'),
('CUV', '哥林多前书', 46, 7, 6, '我说这话，原是准你们的，不是命你们的。'),
('CUV', '哥林多前书', 46, 7, 7, '我愿意众人像我一样；只是各人领受神的恩赐，一个是这样，一个是那样。'),
('CUV', '哥林多前书', 46, 7, 8, '我对著没有嫁娶的和寡妇说，若他们常像我就好。'),
('CUV', '哥林多前书', 46, 7, 9, '倘若自己禁止不住，就可以嫁娶。与其欲火攻心，倒不如嫁娶为妙。'),
('CUV', '哥林多前书', 46, 7, 10, '至于那已经嫁娶的，我吩咐他们；其实不是我吩咐，乃是主吩咐说：妻子不可离开丈夫，'),
('CUV', '哥林多前书', 46, 7, 11, '若是离开了，不可再嫁，或是仍同丈夫和好。丈夫也不可离弃妻子。'),
('CUV', '哥林多前书', 46, 7, 12, '我对其余的人说，不是主说，：倘若某弟兄有不信的妻子，妻子也情愿和他同住，他就不要离弃妻子。'),
('CUV', '哥林多前书', 46, 7, 13, '妻子有不信的丈夫，丈夫也情愿和他同住，他就不要离弃丈夫。'),
('CUV', '哥林多前书', 46, 7, 14, '因为不信的丈夫就因著妻子成了圣洁，并且不信的妻子就因著丈夫（原文是弟兄）成了圣洁；不然，你们的儿女就不洁净，但如今他们是圣洁的了。'),
('CUV', '哥林多前书', 46, 7, 15, '倘若那不信的人要离去，就由他离去罢！无论是弟兄，是姐妹，遇著这样的事都不必拘束。神召我们原是要我们和睦。'),
('CUV', '哥林多前书', 46, 7, 16, '你这作妻子的，怎么知道不能救你的丈夫呢？你这作丈夫的，怎么知道不能救你的妻子呢？'),
('CUV', '哥林多前书', 46, 7, 17, '只要照主所分给各人的，和神所召各人的而行。我吩咐各教会都是这样。'),
('CUV', '哥林多前书', 46, 7, 18, '有人已受割礼蒙召呢，就不要废割礼；有人未受割礼蒙召呢，就不要受割礼。'),
('CUV', '哥林多前书', 46, 7, 19, '受割礼算不得甚么，不受割礼也算不得甚么，只要守神的诫命就是了。'),
('CUV', '哥林多前书', 46, 7, 20, '各人蒙召的时候是甚么身分，仍要守住这身分。'),
('CUV', '哥林多前书', 46, 7, 21, '你是作奴隶蒙召的么？不要因此忧虑；若能以自由，就求自由更好。'),
('CUV', '哥林多前书', 46, 7, 22, '因为作奴仆蒙召于主的，就是主所释放的人；作自由之人蒙召的，就是基督的奴仆。'),
('CUV', '哥林多前书', 46, 7, 23, '你们是重价买来的，不要作人的奴仆。'),
('CUV', '哥林多前书', 46, 7, 24, '弟兄们，你们各人蒙召的时候是甚么身分，仍要在神面前守住这身分。'),
('CUV', '哥林多前书', 46, 7, 25, '论到童身的人，我没有主的命令，但我既蒙主怜恤能作忠心的人，就把自己的意见告诉你们。'),
('CUV', '哥林多前书', 46, 7, 26, '因现今的艰难，据我看来，人不如守素安常才好。'),
('CUV', '哥林多前书', 46, 7, 27, '你有妻子缠著呢，就不要求脱离；你没有妻子缠著呢，就不要求妻子。'),
('CUV', '哥林多前书', 46, 7, 28, '你若娶妻，并不是犯罪；处女若出嫁，也不是犯罪。然而这等人肉身必受苦难，我却愿意你们免这苦难。'),
('CUV', '哥林多前书', 46, 7, 29, '弟兄们，我对你们说，时候减少了。从此以后，那有妻子的，要像没有妻子；'),
('CUV', '哥林多前书', 46, 7, 30, '哀哭的，要像不哀哭；快乐的，要像不快乐；置买的，要像无有所得；'),
('CUV', '哥林多前书', 46, 7, 31, '用世物的，要像不用世物，因为这世界的样子将要过去了。'),
('CUV', '哥林多前书', 46, 7, 32, '我愿你们无所罣虑。没有娶妻的，是为主的事罣虑，想怎样叫主喜悦。'),
('CUV', '哥林多前书', 46, 7, 33, '娶了妻的，是为世上的事罣虑，想怎样叫妻子喜悦。'),
('CUV', '哥林多前书', 46, 7, 34, '妇人和处女也有分别。没有出嫁的，是为主的事罣虑，要身体、灵魂都圣洁；已经出嫁的，是为世上的事罣虑，想怎样叫丈夫喜悦。'),
('CUV', '哥林多前书', 46, 7, 35, '我说这话是为你们的益处，不是要牢笼你们，乃是要叫你们行合宜的事，得以殷勤服事主，没有分心的事。'),
('CUV', '哥林多前书', 46, 7, 36, '若有人以为自己待他的女儿不合宜，女儿也过了年岁，事又当行，他就可随意办理，不算有罪，叫二人成亲就是了。'),
('CUV', '哥林多前书', 46, 7, 37, '倘若人心里坚定，没有不得已的事，并且由得自己作主，心里又决定了留下女儿不出嫁，如此行也好。'),
('CUV', '哥林多前书', 46, 7, 38, '这样看来，叫自己的女儿出嫁是好，不叫他出嫁更是好。'),
('CUV', '哥林多前书', 46, 7, 39, '丈夫活著的时候，妻子是被约束的；丈夫若死了，妻子就可以自由，随意再嫁，只是要嫁这在主里面的人。'),
('CUV', '哥林多前书', 46, 7, 40, '然而按我的意见，若常守节更有福气。我也想自己是被神的灵感动了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 8, 1, '论到祭偶像之物，我们晓得我们都有知识。但知识是叫人自高自大，惟有爱心能造就人。'),
('CUV', '哥林多前书', 46, 8, 2, '若有人以为自己知道甚么，按他所当知道的，他仍是不知道。'),
('CUV', '哥林多前书', 46, 8, 3, '若有人爱神，这人乃是神所知道的。'),
('CUV', '哥林多前书', 46, 8, 4, '论到吃祭偶像之物，我们知道偶像在世上算不得甚么，也知道神只有一位，再没有别的神。'),
('CUV', '哥林多前书', 46, 8, 5, '虽有称为神的，或在天，或在地，就如那许多的神，许多的主；'),
('CUV', '哥林多前书', 46, 8, 6, '然而我们只有一位神，就是父，万物都本于他；我们也归于他─并有一位主，就是耶稣基督─万物都是藉著他有的；我们也是藉著他有的。'),
('CUV', '哥林多前书', 46, 8, 7, '但人不都有这等知识。有人到如今因拜惯了偶像，就以为所吃的是祭偶像之物。他们的良心既然软弱，也就污秽了。'),
('CUV', '哥林多前书', 46, 8, 8, '其实食物不能叫神看中我们，因为我们不吃也无损，吃也无益。'),
('CUV', '哥林多前书', 46, 8, 9, '只是你们要谨慎，恐怕你们这自由竟成了那软弱人的绊脚石。'),
('CUV', '哥林多前书', 46, 8, 10, '若有人见你这有知识的，在偶像的庙里坐席，这人的良心，若是软弱，岂不放胆去吃那祭偶像之物么？'),
('CUV', '哥林多前书', 46, 8, 11, '因此，基督为他死的那软弱弟兄，也就因你的知识沉沦了。'),
('CUV', '哥林多前书', 46, 8, 12, '你们这样得罪弟兄们，伤了他们软弱的良心，就是得罪基督。'),
('CUV', '哥林多前书', 46, 8, 13, '所以，食物若叫我弟兄跌倒，我就永远不吃肉，免得叫我弟兄跌倒了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 9, 1, '我不是自由的么？我不是使徒么？我不是见过我们的主耶稣么？你们不是我在主里面所做之工么？'),
('CUV', '哥林多前书', 46, 9, 2, '假若在别人，我不是使徒，在你们，我总是使徒，因为你们在主里正是我作使徒的印证。'),
('CUV', '哥林多前书', 46, 9, 3, '我对那盘问我的人就是这样分诉：'),
('CUV', '哥林多前书', 46, 9, 4, '难道我们没有权柄靠福音吃喝么？'),
('CUV', '哥林多前书', 46, 9, 5, '难道我们没有权柄娶信主的姊妹为妻，带著一同往来，仿佛其余的使徒和主的弟兄并矶法一样么？'),
('CUV', '哥林多前书', 46, 9, 6, '独有我与巴拿巴没有权柄不做工么？'),
('CUV', '哥林多前书', 46, 9, 7, '有谁当兵自备粮饷呢？有谁栽葡萄园不吃园里的果子呢？有谁牧养牛羊不吃牛羊的奶呢？'),
('CUV', '哥林多前书', 46, 9, 8, '我说这话，岂是照人的意见；律法不也是这样说么？'),
('CUV', '哥林多前书', 46, 9, 9, '就如摩西的律法记著说：牛在场上踹谷的时候，不可笼住他的嘴。难道神所挂念的是牛么？'),
('CUV', '哥林多前书', 46, 9, 10, '不全是为我们说的么？分明是为我们说的。因为耕种的当存著指望去耕种；打场的也当存得粮的指望去打场。'),
('CUV', '哥林多前书', 46, 9, 11, '我们若把属灵的种子撒在你们中间，就是从你们收割奉养肉身之物这还算大事么？'),
('CUV', '哥林多前书', 46, 9, 12, '若别人在你们身上有这权柄，何况我们呢？然而，我们没有用过这权柄，倒凡事忍受，免得基督的福音被阻隔。'),
('CUV', '哥林多前书', 46, 9, 13, '你们岂不知为圣事劳碌的就吃殿中的物么？伺候祭坛的就分领坛上的物么？'),
('CUV', '哥林多前书', 46, 9, 14, '主也是这样命定，叫传福音的靠著福音养生。'),
('CUV', '哥林多前书', 46, 9, 15, '但这权柄我全没有用过。我写这话，并非要你们这样待我，因为我宁可死也不叫人使我所夸的落了空。'),
('CUV', '哥林多前书', 46, 9, 16, '我传福音原没有可夸的，因为我是不得已的。若不传福音，我便有祸了。'),
('CUV', '哥林多前书', 46, 9, 17, '我若甘心做这事，就有赏赐；若不甘心，责任却已经托付我了。'),
('CUV', '哥林多前书', 46, 9, 18, '既是这样，我的赏赐是甚么呢？就是我传福音的时候叫人不花钱得福音，免得用尽我传福音的权柄。'),
('CUV', '哥林多前书', 46, 9, 19, '我虽是自由的，无人辖管；然而我甘心作了众人的仆人，为要多得人。'),
('CUV', '哥林多前书', 46, 9, 20, '向犹太人，我就作犹太人，为要得犹太人；向律法以下的人，我虽不在律法以下，还是作律法以下的人，为要得律法以下的人。'),
('CUV', '哥林多前书', 46, 9, 21, '向没有律法的人，我就作没有律法的人，为要得没有律法的人；其实我在神面前，不是没有律法；在基督面前，正在律法之下。'),
('CUV', '哥林多前书', 46, 9, 22, '向软弱的人，我就作软弱的人，为要得软弱的人。向甚么样的人，我就作甚么样的人。无论如何，总要救些人。'),
('CUV', '哥林多前书', 46, 9, 23, '凡我所行的，都是为福音的缘故，为要与人同得这福音的好处。'),
('CUV', '哥林多前书', 46, 9, 24, '岂不知在场上赛跑的都跑，但得奖赏的只有一人？你们也当这样跑，好叫你们得著奖赏。'),
('CUV', '哥林多前书', 46, 9, 25, '凡较力争胜的，诸事都有节制，他们不过是要得能坏的冠冕；我们却是要得不能坏的冠冕。'),
('CUV', '哥林多前书', 46, 9, 26, '所以，我奔跑不像无定向的；我斗拳不像打空气的。'),
('CUV', '哥林多前书', 46, 9, 27, '我是攻克己身，叫身服我，恐怕我传福音给别人，自己反被弃绝了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 10, 1, '弟兄们，我不愿意你们不晓得，我们的祖宗从前都在云下，都从海中经过，'),
('CUV', '哥林多前书', 46, 10, 2, '都在云里、海里受洗归了摩西；'),
('CUV', '哥林多前书', 46, 10, 3, '并且都吃了一样的灵食，'),
('CUV', '哥林多前书', 46, 10, 4, '也都喝了一样的灵水。所喝的，是出于随著他们的灵磐石；那磐石就是基督。'),
('CUV', '哥林多前书', 46, 10, 5, '但他们中间多半是神不喜欢的人，所以在旷野倒毙。'),
('CUV', '哥林多前书', 46, 10, 6, '这些事都是我们的鉴戒，叫我们不要贪恋恶事，像他们那样贪恋的；'),
('CUV', '哥林多前书', 46, 10, 7, '也不要拜偶像，像他们有人拜的。如经上所记：百姓坐下吃喝，起来玩耍。'),
('CUV', '哥林多前书', 46, 10, 8, '我们也不要行奸淫，像他们有人行的，一天就倒毙了二万三千人；'),
('CUV', '哥林多前书', 46, 10, 9, '也不要试探主（有古卷：基督），像他们有人试探的，就被蛇所灭。'),
('CUV', '哥林多前书', 46, 10, 10, '你们也不要发怨言，像他们有发怨言的，就被灭命的所灭。'),
('CUV', '哥林多前书', 46, 10, 11, '他们遭遇这些事，都要作为鉴戒；并且写在经上，正是警戒我们这末世的人。'),
('CUV', '哥林多前书', 46, 10, 12, '所以，自己以为站得稳的，须要谨慎，免得跌倒。'),
('CUV', '哥林多前书', 46, 10, 13, '你们所遇见的试探，无非是人所能受的。神是信实的，必不叫你们受试探过于所能受的；在受试探的时候，总要给你们开一条出路，叫你们能忍受得住。'),
('CUV', '哥林多前书', 46, 10, 14, '我所亲爱的弟兄阿，你们要逃避拜偶像的事。'),
('CUV', '哥林多前书', 46, 10, 15, '我好像对明白人说的，你们要审察我的话。'),
('CUV', '哥林多前书', 46, 10, 16, '我们所祝福的杯，岂不是同领基督的血么？我们所擘开的饼，岂不是同领基督的身体么？'),
('CUV', '哥林多前书', 46, 10, 17, '我们虽多，仍是一个饼，一个身体，因为我们都是分受这一个饼。'),
('CUV', '哥林多前书', 46, 10, 18, '你们看属肉体的以色列人，那吃祭物的岂不是在祭坛上有分么？'),
('CUV', '哥林多前书', 46, 10, 19, '我是怎么说呢？岂是说祭偶像之物算得甚么呢？或说偶像算得甚么呢？'),
('CUV', '哥林多前书', 46, 10, 20, '我乃是说，外邦人所献的祭是祭鬼，不是祭神。我不愿意你们与鬼相交。'),
('CUV', '哥林多前书', 46, 10, 21, '你们不能喝主的杯又喝鬼的杯，不能吃主的筵席又吃鬼的筵席。'),
('CUV', '哥林多前书', 46, 10, 22, '我们可惹主的愤恨么？我们比他还有能力么？'),
('CUV', '哥林多前书', 46, 10, 23, '凡事都可行，但不都有益处。凡事都可行，但不都造就人。'),
('CUV', '哥林多前书', 46, 10, 24, '无论何人，不要求自己的益处，乃要求别人的益处。'),
('CUV', '哥林多前书', 46, 10, 25, '凡市上所卖的，你们只管吃，不要为良心的缘故问甚么话，'),
('CUV', '哥林多前书', 46, 10, 26, '因为地和其中所充满的都属乎主。'),
('CUV', '哥林多前书', 46, 10, 27, '倘有一个不信的人请你们赴席，你们若愿意去，凡摆在你们面前的，只管吃，不要为良心的缘故问甚么话。'),
('CUV', '哥林多前书', 46, 10, 28, '若有人对你们说：这是献过祭的物，就要为那告诉你们的人，并为良心的缘故不吃。'),
('CUV', '哥林多前书', 46, 10, 29, '我说的良心不是你的，乃是他的。我这自由为甚么被别人的良心论断呢？'),
('CUV', '哥林多前书', 46, 10, 30, '我若谢恩而吃，为甚么因我谢恩的物被人毁谤呢？'),
('CUV', '哥林多前书', 46, 10, 31, '所以，你们或吃或喝，无论做甚么，都要为荣耀神而行。'),
('CUV', '哥林多前书', 46, 10, 32, '不拘是犹太人，是希利尼人，是神的教会，你们都不要使他跌倒；'),
('CUV', '哥林多前书', 46, 10, 33, '就好像我凡事都叫众人喜欢，不求自己的益处，只求众人的益处，叫他们得救。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 11, 1, '你们该效法我，像我效法基督一样。'),
('CUV', '哥林多前书', 46, 11, 2, '我称赞你们，因你们凡事记念我，又坚守我所传给你们的。'),
('CUV', '哥林多前书', 46, 11, 3, '我愿意你们知道，基督是各人的头；男人是女人的头；神是基督的头。'),
('CUV', '哥林多前书', 46, 11, 4, '凡男人祷告或是讲道（或作：说预言；下同），若蒙著头，就羞辱自己的头。'),
('CUV', '哥林多前书', 46, 11, 5, '凡女人祷告或是讲道，若不蒙著头，就羞辱自己的头，因为这就如同剃了头发一样。'),
('CUV', '哥林多前书', 46, 11, 6, '女人若不蒙著头，就该剪了头发；女人若以剪发、剃发为羞愧，就该蒙著头。'),
('CUV', '哥林多前书', 46, 11, 7, '男人本不该蒙著头，因为他是神的形像和荣耀；但女人是男人的荣耀。'),
('CUV', '哥林多前书', 46, 11, 8, '起初，男人不是由女人而出，女人乃是由男人而出。'),
('CUV', '哥林多前书', 46, 11, 9, '并且男人不是为女人造的；女人乃是为男人造的。'),
('CUV', '哥林多前书', 46, 11, 10, '因此，女人为天使的缘故，应当在头上有服权柄的记号。'),
('CUV', '哥林多前书', 46, 11, 11, '然而照主的安排，女也不是无男，男也不是无女。'),
('CUV', '哥林多前书', 46, 11, 12, '因为女人原是由男人而出，男人也是由女人而出；但万有都是出乎神。'),
('CUV', '哥林多前书', 46, 11, 13, '你们自己审察，女人祷告神，不蒙著头是合宜的么？'),
('CUV', '哥林多前书', 46, 11, 14, '你们的本性不也指示你们，男人若有长头发，便是他的羞辱么？'),
('CUV', '哥林多前书', 46, 11, 15, '但女人有长头发，乃是他的荣耀，因为这头发是给他作盖头的。'),
('CUV', '哥林多前书', 46, 11, 16, '若有人想要辩驳，我们却没有这样的规矩，神的众教会也是没有的。'),
('CUV', '哥林多前书', 46, 11, 17, '我现今吩咐你们的话，不是称赞你们；因为你们聚会不是受益，乃是招损。'),
('CUV', '哥林多前书', 46, 11, 18, '第一，我听说，你们聚会的时候彼此分门别类，我也稍微的信这话。'),
('CUV', '哥林多前书', 46, 11, 19, '在你们中间不免有分门结党的事，好叫那些有经验的人显明出来。'),
('CUV', '哥林多前书', 46, 11, 20, '你们聚会的时候，算不得吃主的晚餐；'),
('CUV', '哥林多前书', 46, 11, 21, '因为吃的时候，各人先吃自己的饭，甚至这个饥饿，那个酒醉。'),
('CUV', '哥林多前书', 46, 11, 22, '你们要吃喝，难道没有家么？还是藐视神的教会，叫那没有的羞愧呢？我向你们可怎么说呢？可因此称赞你们么？我不称赞！'),
('CUV', '哥林多前书', 46, 11, 23, '我当日传给你们的，原是从主领受的，就是主耶稣被卖的那一夜，拿起饼来，'),
('CUV', '哥林多前书', 46, 11, 24, '祝谢了，就擘开，说：这是我的身体，为你们舍（有古卷：擘开）的，你们应当如此行，为的是记念我。'),
('CUV', '哥林多前书', 46, 11, 25, '饭后，也照样拿起杯来，说：这杯是用我的血所立的新约，你们每逢喝的时候，要如此行，为的是记念我。'),
('CUV', '哥林多前书', 46, 11, 26, '你们每逢吃这饼，喝这杯，是表明主的死，直等到他来。'),
('CUV', '哥林多前书', 46, 11, 27, '所以，无论何人，不按理吃主的饼，喝主的杯，就是干犯主的身、主的血了。'),
('CUV', '哥林多前书', 46, 11, 28, '人应当自己省察，然后吃这饼、喝这杯。'),
('CUV', '哥林多前书', 46, 11, 29, '因为人吃喝，若不分辨是主的身体，就是吃喝自己的罪了。'),
('CUV', '哥林多前书', 46, 11, 30, '因此，在你们中间有好些软弱的与患病的，死（原文是睡）的也不少。'),
('CUV', '哥林多前书', 46, 11, 31, '我们若是先分辨自己，就不至于受审。'),
('CUV', '哥林多前书', 46, 11, 32, '我们受审的时候，乃是被主惩治，免得我们和世人一同定罪。'),
('CUV', '哥林多前书', 46, 11, 33, '所以我弟兄们，你们聚会吃的时候，要彼此等待。'),
('CUV', '哥林多前书', 46, 11, 34, '若有人饥饿，可以在家里先吃，免得你们聚会，自己取罪。其余的事，我来的时候再安排。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 12, 1, '弟兄们，论到属灵的恩赐，我不愿意你们不明白。'),
('CUV', '哥林多前书', 46, 12, 2, '你们作外邦人的时候，随事被牵引，受迷惑，去服事那哑吧偶像，这是你们知道的。'),
('CUV', '哥林多前书', 46, 12, 3, '所以我告诉你们，被神的灵感动的，没有说耶稣是可咒诅的；若不是被圣灵感动的，也没有能说耶稣是主的。'),
('CUV', '哥林多前书', 46, 12, 4, '恩赐原有分别，圣灵却是一位。'),
('CUV', '哥林多前书', 46, 12, 5, '职事也有分别，主却是一位。'),
('CUV', '哥林多前书', 46, 12, 6, '功用也有分别，神却是一位，在众人里面运行一切的事。'),
('CUV', '哥林多前书', 46, 12, 7, '圣灵显在各人身上，是叫人得益处。'),
('CUV', '哥林多前书', 46, 12, 8, '这人蒙圣灵赐他智慧的言语，那人也蒙这位圣灵赐他知识的言语，'),
('CUV', '哥林多前书', 46, 12, 9, '又有一人蒙这位圣灵赐他信心，还有一人蒙这位圣灵赐他医病的恩赐，'),
('CUV', '哥林多前书', 46, 12, 10, '又叫一人能行异能，又叫一人能作先知，又叫一人能辨别诸灵，又叫一人能说方言，又叫一人能繙方言。'),
('CUV', '哥林多前书', 46, 12, 11, '这一切都是这位圣灵所运行、随己意分给各人的。'),
('CUV', '哥林多前书', 46, 12, 12, '就如身子是一个，却有许多肢体；而且肢体虽多，仍是一个身子；基督也是这样。'),
('CUV', '哥林多前书', 46, 12, 13, '我们不拘是犹太人，是希利尼人，是为奴的，是自主的，都从一位圣灵受洗，成了一个身体，饮于一位圣灵。'),
('CUV', '哥林多前书', 46, 12, 14, '身子原不是一个肢体，乃是许多肢体。'),
('CUV', '哥林多前书', 46, 12, 15, '设若脚说：我不是手，所以不属乎身子；他不能因此就不属乎身子。'),
('CUV', '哥林多前书', 46, 12, 16, '设若耳说：我不是眼，所以不属乎身子；他也不能因此就不属乎身子。'),
('CUV', '哥林多前书', 46, 12, 17, '若全身是眼，从那里听声呢？若全身是耳，从那里闻味呢？'),
('CUV', '哥林多前书', 46, 12, 18, '但如今，神随自己的意思把肢体俱各安排在身上了。'),
('CUV', '哥林多前书', 46, 12, 19, '若都是一个肢体，身子在那里呢？'),
('CUV', '哥林多前书', 46, 12, 20, '但如今肢体是多的，身子却是一个。'),
('CUV', '哥林多前书', 46, 12, 21, '眼不能对手说：我用不著你；头也不能对脚说：我用不著你。'),
('CUV', '哥林多前书', 46, 12, 22, '不但如此，身上肢体人以为软弱的，更是不可少的。'),
('CUV', '哥林多前书', 46, 12, 23, '身上肢体，我们看为不体面的，越发给他加上体面；不俊美的，越发得著俊美。'),
('CUV', '哥林多前书', 46, 12, 24, '我们俊美的肢体，自然用不著装饰；但神配搭这身子，把加倍的体面给那有缺欠的肢体，'),
('CUV', '哥林多前书', 46, 12, 25, '免得身上分门别类，总要肢体彼此相顾。'),
('CUV', '哥林多前书', 46, 12, 26, '若一个肢体受苦，所有的肢体就一同受苦；若一个肢体得荣耀，所有的肢体就一同快乐。'),
('CUV', '哥林多前书', 46, 12, 27, '你们就是基督的身子，并且各自作肢体。'),
('CUV', '哥林多前书', 46, 12, 28, '神在教会所设立的：第一是使徒，第二是先知，第三是教师，其次是行异能的，再次是得恩赐医病的，帮助人的，治理事的，说方言的。'),
('CUV', '哥林多前书', 46, 12, 29, '岂都是使徒么？岂都是先知么？岂都是教师么？岂都是行异能的么？'),
('CUV', '哥林多前书', 46, 12, 30, '岂都是得恩赐医病的么？岂都是说方言的么？岂都是繙方言的么？'),
('CUV', '哥林多前书', 46, 12, 31, '你们要切切的求那更大的恩赐。我现今把最妙的道指示你们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 13, 1, '我若能说万人的方言，并天使的话语，却没有爱，我就成了鸣的锣，响的钹一般。'),
('CUV', '哥林多前书', 46, 13, 2, '我若有先知讲道之能，也明白各样的奥秘，各样的知识，而且有全备的信，叫我能够移山，却没有爱，我就算不得甚么。'),
('CUV', '哥林多前书', 46, 13, 3, '我若将所有的赒济穷人，又舍己身叫人焚烧，却没有爱，仍然与我无益。'),
('CUV', '哥林多前书', 46, 13, 4, '爱是恒久忍耐，又有恩慈；爱是不嫉妒；爱是不自夸，不张狂，'),
('CUV', '哥林多前书', 46, 13, 5, '不做害羞的事，不求自己的益处，不轻易发怒，不计算人的恶，'),
('CUV', '哥林多前书', 46, 13, 6, '不喜欢不义，只喜欢真理；'),
('CUV', '哥林多前书', 46, 13, 7, '凡事包容，凡事相信，凡事盼望，凡事忍耐。'),
('CUV', '哥林多前书', 46, 13, 8, '爱是永不止息。先知讲道之能终必归于无有；说方言之能终必停止；知识也终必归于无有。'),
('CUV', '哥林多前书', 46, 13, 9, '我们现在所知道的有限，先知所讲的也有限，'),
('CUV', '哥林多前书', 46, 13, 10, '等那完全的来到，这有限的必归于无有了。'),
('CUV', '哥林多前书', 46, 13, 11, '我作孩子的时候，话语像孩子，心思像孩子，意念像孩子，既成了人，就把孩子的事丢弃了。'),
('CUV', '哥林多前书', 46, 13, 12, '我们如今仿佛对著镜子观看，糢糊不清（原文作：如同猜谜）；到那时就要面对面了。我如今所知道的有限，到那时就全知道，如同主知道我一样。'),
('CUV', '哥林多前书', 46, 13, 13, '如今常存的有信，有望，有爱这三样，其中最大的是爱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 14, 1, '你们要追求爱，也要切慕属灵的恩赐，其中更要羡慕的，是作先知讲道（原文作：是说预言；下同）'),
('CUV', '哥林多前书', 46, 14, 2, '那说方言的，原不是对人说，乃是对神说，因为没有人听出来。然而，他在心灵里却是讲说各样的奥秘。'),
('CUV', '哥林多前书', 46, 14, 3, '但作先知讲道的，是对人说，要造就、安慰、劝勉人。'),
('CUV', '哥林多前书', 46, 14, 4, '说方言的，是造就自己；作先知讲道的，乃是造就教会。'),
('CUV', '哥林多前书', 46, 14, 5, '我愿意你们都说方言，更愿意你们作先知讲道；因为说方言的，若不繙出来，使教会被造就，那作先知讲道的，就比他强了。'),
('CUV', '哥林多前书', 46, 14, 6, '弟兄们，我到你们那里去，若只说方言，不用启示，或知识，或预言，或教训，给你们讲解，我与你们有甚么益处呢？'),
('CUV', '哥林多前书', 46, 14, 7, '就是那有声无气的物，或箫，或琴，若发出来的声音没有分别，怎能知道所吹所弹的是甚么呢？'),
('CUV', '哥林多前书', 46, 14, 8, '若吹无定的号声，谁能预备打仗呢？'),
('CUV', '哥林多前书', 46, 14, 9, '你们也是如此。舌头若不说容易明白的话，怎能知道所说的是甚么呢？这就是向空说话了。'),
('CUV', '哥林多前书', 46, 14, 10, '世上的声音，或者甚多，却没有一样是无意思的。'),
('CUV', '哥林多前书', 46, 14, 11, '我若不明白那声音的意思，这说话的人必以我为化外之人，我也以他为化外之人。'),
('CUV', '哥林多前书', 46, 14, 12, '你们也是如此，既是切慕属灵的恩赐，就当求多得造就教会的恩赐。'),
('CUV', '哥林多前书', 46, 14, 13, '所以那说方言的，就当求著能繙出来。'),
('CUV', '哥林多前书', 46, 14, 14, '我若用方言祷告，是我的灵祷告，但我的悟性没有果效。'),
('CUV', '哥林多前书', 46, 14, 15, '这却怎么样呢？我要用灵祷告，也要用悟性祷告；我要用灵歌唱，也要用悟性歌唱。'),
('CUV', '哥林多前书', 46, 14, 16, '不然，你用灵祝谢，那在座不通方言的人，既然不明白你的话，怎能在你感谢的时候说阿们呢？'),
('CUV', '哥林多前书', 46, 14, 17, '你感谢的固然是好，无奈不能造就别人。'),
('CUV', '哥林多前书', 46, 14, 18, '我感谢神，我说方言比你们众人还多。'),
('CUV', '哥林多前书', 46, 14, 19, '但在教会中，宁可用悟性说五句教导人的话，强如说万句方言。'),
('CUV', '哥林多前书', 46, 14, 20, '弟兄们，在心志上不要作小孩子。然而，在恶事上要作婴孩，在心志上总要作大人。'),
('CUV', '哥林多前书', 46, 14, 21, '律法上记著：主说：我要用外邦人的舌头和外邦人的嘴唇向这百姓说话；虽然如此，他们还是不听从我。'),
('CUV', '哥林多前书', 46, 14, 22, '这样看来，说方言不是为信的人作证据，乃是为不信的人；作先知讲道不是为不信的人作证据，乃是为信的人。'),
('CUV', '哥林多前书', 46, 14, 23, '所以，全教会聚在一处的时候，若都说方言，偶然有不通方言的，或是不信的人进来，岂不说你们癫狂了么？'),
('CUV', '哥林多前书', 46, 14, 24, '若都作先知讲道，偶然有不信的，或是不通方言的人进来，就被众人劝醒，被众人审明，'),
('CUV', '哥林多前书', 46, 14, 25, '他心里的隐情显露出来，就必将脸伏地，敬拜神，说：神真是在你们中间了。'),
('CUV', '哥林多前书', 46, 14, 26, '弟兄们，这却怎么样呢？你们聚会的时候，各人或有诗歌，或有教训，或有启示，或有方言，或有繙出来的话，凡事都当造就人。'),
('CUV', '哥林多前书', 46, 14, 27, '若有说方言的，只好两个人，至多三个人，且要轮流著说，也要一个人繙出来。'),
('CUV', '哥林多前书', 46, 14, 28, '若没有人繙，就当在会中闭口，只对自己和神说就是了。'),
('CUV', '哥林多前书', 46, 14, 29, '至于作先知讲道的，只好两个人或是三个人，其余的就当慎思明辨。'),
('CUV', '哥林多前书', 46, 14, 30, '若旁边坐著的得了启示，那先说话的就当闭口不言。'),
('CUV', '哥林多前书', 46, 14, 31, '因为你们都可以一个一个的作先知讲道，叫众人学道理，叫众人得劝勉。'),
('CUV', '哥林多前书', 46, 14, 32, '先知的灵原是顺服先知的；'),
('CUV', '哥林多前书', 46, 14, 33, '因为神不是叫人混乱，乃是叫人安静。'),
('CUV', '哥林多前书', 46, 14, 34, '妇女在会中要闭口不言，像在圣徒的众教会一样，因为不准他们说话。他们总要顺服，正如律法所说的。'),
('CUV', '哥林多前书', 46, 14, 35, '他们若要学甚么，可以在家里问自己的丈夫，因为妇女在会中说话原是可耻的。'),
('CUV', '哥林多前书', 46, 14, 36, '神的道理岂是从你们出来么？岂是单临到你们么？'),
('CUV', '哥林多前书', 46, 14, 37, '若有人以为自己是先知，或是属灵的，就该知道，我所写给你们的是主的命令。'),
('CUV', '哥林多前书', 46, 14, 38, '若有不知道的，就由他不知道罢！'),
('CUV', '哥林多前书', 46, 14, 39, '所以我弟兄们，你们要切慕作先知讲道，也不要禁止说方言。'),
('CUV', '哥林多前书', 46, 14, 40, '凡事都要规规矩矩的按著次序行。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 15, 1, '弟兄们，我如今把先前所传给你们的福音告诉你们知道；这福音你们也领受了，又靠著站立得住，'),
('CUV', '哥林多前书', 46, 15, 2, '并且你们若不是徒然相信，能以持守我所传给你们的，就必因这福音得救。'),
('CUV', '哥林多前书', 46, 15, 3, '我当日所领受又传给你们的：第一，就是基督照圣经所说，为我们的罪死了，'),
('CUV', '哥林多前书', 46, 15, 4, '而且埋葬了；又照圣经所说，第三天复活了，'),
('CUV', '哥林多前书', 46, 15, 5, '并且显给矶法看，然后显给十二使徒看；'),
('CUV', '哥林多前书', 46, 15, 6, '后来一时显给五百多弟兄看，其中一大半到如今还在，却也有已经睡了的。'),
('CUV', '哥林多前书', 46, 15, 7, '以后显给雅各看，再显给众使徒看，'),
('CUV', '哥林多前书', 46, 15, 8, '末了也显给我看；我如同未到产期而生的人一般。'),
('CUV', '哥林多前书', 46, 15, 9, '我原是使徒中最小的，不配称为使徒，因为我从前逼迫神的教会。'),
('CUV', '哥林多前书', 46, 15, 10, '然而，我今日成了何等人，是蒙神的恩才成的，并且他所赐我的恩不是徒然的。我比众使徒格外劳苦；这原不是我，乃是神的恩与我同在。'),
('CUV', '哥林多前书', 46, 15, 11, '不拘是我，是众使徒，我们如此传，你们也如此信了。'),
('CUV', '哥林多前书', 46, 15, 12, '既传基督是从死里复活了，怎么在你们中间有人说没有死人复活的事呢？'),
('CUV', '哥林多前书', 46, 15, 13, '若没有死人复活的事，基督也就没有复活了。'),
('CUV', '哥林多前书', 46, 15, 14, '若基督没有复活，我们所传的便是枉然，你们所信的也是枉然；'),
('CUV', '哥林多前书', 46, 15, 15, '并且明显我们是为神妄作见证的，因我们见证神是叫基督复活了。若死人真不复活，神也就没有叫基督复活了。'),
('CUV', '哥林多前书', 46, 15, 16, '因为死人若不复活，基督也就没有复活了。'),
('CUV', '哥林多前书', 46, 15, 17, '基督若没有复活，你们的信便是徒然，你们仍在罪里。'),
('CUV', '哥林多前书', 46, 15, 18, '就是在基督里睡了的人也灭亡了。'),
('CUV', '哥林多前书', 46, 15, 19, '我们若靠基督，只在今生有指望，就算比众人更可怜。'),
('CUV', '哥林多前书', 46, 15, 20, '但基督已经从死里复活，成为睡了之人初熟的果子。'),
('CUV', '哥林多前书', 46, 15, 21, '死既是因一人而来，死人复活也是因一人而来。'),
('CUV', '哥林多前书', 46, 15, 22, '在亚当里众人都死了；照样，在基督里众人也都要复活。'),
('CUV', '哥林多前书', 46, 15, 23, '但各人是按著自己的次序复活：初熟的果子是基督；以后，在他来的时候，是那些属基督的。'),
('CUV', '哥林多前书', 46, 15, 24, '再后，末期到了，那时基督既将一切执政的、掌权的、有能的、都毁灭了，就把国交与父神。'),
('CUV', '哥林多前书', 46, 15, 25, '因为基督必要作王，等神把一切仇敌都放在他的脚下。'),
('CUV', '哥林多前书', 46, 15, 26, '尽末了所毁灭的仇敌，就是死。'),
('CUV', '哥林多前书', 46, 15, 27, '因为经上说：神叫万物都服在他的脚下。既说万物都服了他，明显那叫万物服他的，不在其内了。'),
('CUV', '哥林多前书', 46, 15, 28, '万物既服了他，那时子也要自己服那叫万物服他的，叫神在万物之上，为万物之主。'),
('CUV', '哥林多前书', 46, 15, 29, '不然，那些为死人受洗的，将来怎样呢？若死人总不复活，因何为他们受洗呢？'),
('CUV', '哥林多前书', 46, 15, 30, '我们又因何时刻冒险呢？'),
('CUV', '哥林多前书', 46, 15, 31, '弟兄们，我在我主基督耶稣里，指著你们所夸的口极力的说，我是天天冒死。'),
('CUV', '哥林多前书', 46, 15, 32, '我若当日像寻常人，在以弗所同野兽战斗，那于我有甚么益处呢？若死人不复活，我们就吃吃喝喝罢！因为明天要死了。'),
('CUV', '哥林多前书', 46, 15, 33, '你们不要自欺；滥交是败坏善行。'),
('CUV', '哥林多前书', 46, 15, 34, '你们要醒悟为善，不要犯罪，因为有人不认识神。我说这话是要叫你们羞愧。'),
('CUV', '哥林多前书', 46, 15, 35, '或有人问：死人怎样复活，带著甚么身体来呢？'),
('CUV', '哥林多前书', 46, 15, 36, '无知的人哪，你所种的，若不死就不能生。'),
('CUV', '哥林多前书', 46, 15, 37, '并且你所种的不是那将来的形体，不过是子粒，即如麦子，或是别样的谷。'),
('CUV', '哥林多前书', 46, 15, 38, '但神随自己的意思给他一个形体，并叫各等子粒各有自己的形体。'),
('CUV', '哥林多前书', 46, 15, 39, '凡肉体各有不同：人是一样，兽又是一样，鸟又是一样，鱼又是一样。'),
('CUV', '哥林多前书', 46, 15, 40, '有天上的形体，也有地上的形体；但天上形体的荣光是一样，地上形体的荣光又是一样。'),
('CUV', '哥林多前书', 46, 15, 41, '日有日的荣光，月有月的荣光，星有星的荣光。这星和那星的荣光也有分别。'),
('CUV', '哥林多前书', 46, 15, 42, '死人复活也是这样：所种的是必朽坏的，复活的是不朽坏的；'),
('CUV', '哥林多前书', 46, 15, 43, '所种的是羞辱的，复活的是荣耀的；所种的是软弱的，复活的是强壮的；'),
('CUV', '哥林多前书', 46, 15, 44, '所种的是血气的身体，复活的是灵性的身体。若有血气的身体，也必有灵性的身体。'),
('CUV', '哥林多前书', 46, 15, 45, '经上也是这样记著说：首先的人亚当成了有灵（灵：或作血气）的活人；末后的亚当成了叫人活的灵。'),
('CUV', '哥林多前书', 46, 15, 46, '但属灵的不在先，属血气的在先，以后才有属灵的。'),
('CUV', '哥林多前书', 46, 15, 47, '头一个人是出于地，乃属土；第二个人是出于天。'),
('CUV', '哥林多前书', 46, 15, 48, '那属土的怎样，凡属土的也就怎样；属天的怎样，凡属天的也就怎样。'),
('CUV', '哥林多前书', 46, 15, 49, '我们既有属土的形状，将来也必有属天的形状。'),
('CUV', '哥林多前书', 46, 15, 50, '弟兄们，我告诉你们说，血肉之体不能承受神的国，必朽坏的不能承受不朽坏的。'),
('CUV', '哥林多前书', 46, 15, 51, '我如今把一件奥秘的事告诉你们：我们不是都要睡觉，乃是都要改变，'),
('CUV', '哥林多前书', 46, 15, 52, '就在一霎时，眨眼之间，号筒末次吹响的时候。因号筒要响，死人要复活成为不朽坏的，我们也要改变。'),
('CUV', '哥林多前书', 46, 15, 53, '这必朽坏的总要变成（变成：原文是穿；下同）不朽坏的，这必死的总要变成不死的。'),
('CUV', '哥林多前书', 46, 15, 54, '这必朽坏的既变成不朽坏的，这必死的既变成不死的，那时经上所记死被得胜吞灭的话就应验了。'),
('CUV', '哥林多前书', 46, 15, 55, '死阿！你得胜的权势在那里？死阿！你的毒钩在那里？'),
('CUV', '哥林多前书', 46, 15, 56, '死的毒钩就是罪，罪的权势就是律法。'),
('CUV', '哥林多前书', 46, 15, 57, '感谢神，使我们藉著我们的主耶稣基督得胜。'),
('CUV', '哥林多前书', 46, 15, 58, '所以，我亲爱的弟兄们，你们务要坚固，不可摇动，常常竭力多做主工；因为知道，你们的劳苦在主里面不是徒然的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多前书', 46, 16, 1, '论到为圣徒捐钱，我从前怎样吩咐加拉太的众教会，你们也当怎样行。'),
('CUV', '哥林多前书', 46, 16, 2, '每逢七日的第一日，各人要照自己的进项抽出来留著，免得我来的时候现凑。'),
('CUV', '哥林多前书', 46, 16, 3, '及至我来到了，你们写信举荐谁，我就打发他们，把你们的捐资送到耶路撒冷去。'),
('CUV', '哥林多前书', 46, 16, 4, '若我也该去，他们可以和我同去。'),
('CUV', '哥林多前书', 46, 16, 5, '我要从马其顿经过；既经过了，就要到你们那里去，'),
('CUV', '哥林多前书', 46, 16, 6, '或者和你们同住几时，或者也过冬。无论我往那里去，你们就可以给我送行。'),
('CUV', '哥林多前书', 46, 16, 7, '我如今不愿意路过见你们；主若许我，我就指望和你们同住几时。'),
('CUV', '哥林多前书', 46, 16, 8, '但我要仍旧住在以弗所，直等到五旬节；'),
('CUV', '哥林多前书', 46, 16, 9, '因为有宽大又有功效的门为我开了，并且反对的人也多。'),
('CUV', '哥林多前书', 46, 16, 10, '若是提摩太来到，你们要留心，叫他在你们那里无所惧怕；因为他劳力做主的工，像我一样。'),
('CUV', '哥林多前书', 46, 16, 11, '所以，无论谁都不可藐视他，只要送他平安前行，叫他到我这里来，因我指望他和弟兄们同来。'),
('CUV', '哥林多前书', 46, 16, 12, '至于兄弟亚波罗，我再三的劝他同弟兄们到你们那里去；但这时他决不愿意去，几时有了机会他必去。'),
('CUV', '哥林多前书', 46, 16, 13, '你们务要儆醒，在真道上站立得稳，要作大丈夫，要刚强。'),
('CUV', '哥林多前书', 46, 16, 14, '凡你们所做的都要凭爱心而做。'),
('CUV', '哥林多前书', 46, 16, 15, '弟兄们，你们晓得司提反一家，是亚该亚初结的果子，并且他们专以服事圣徒为念。'),
('CUV', '哥林多前书', 46, 16, 16, '我劝你们顺服这样的人，并一切同工同劳的人。'),
('CUV', '哥林多前书', 46, 16, 17, '司提反和福徒拿都，并亚该古到这里来，我很喜欢；因为你们待我有不及之处，他们补上了。'),
('CUV', '哥林多前书', 46, 16, 18, '他们叫我和你们心里都快活。这样的人，你们务要敬重。'),
('CUV', '哥林多前书', 46, 16, 19, '亚西亚的众教会问你们安。亚居拉和百基拉并在他们家里的教会，因主多多的问你们安。'),
('CUV', '哥林多前书', 46, 16, 20, '众弟兄都问你们安。你们要亲嘴问安，彼此务要圣洁。'),
('CUV', '哥林多前书', 46, 16, 21, '我─保罗亲笔问安。'),
('CUV', '哥林多前书', 46, 16, 22, '若有人不爱主，这人可诅可咒。主必要来！'),
('CUV', '哥林多前书', 46, 16, 23, '愿主耶稣基督的恩常与你们众人同在！'),
('CUV', '哥林多前书', 46, 16, 24, '我在基督耶稣里的爱与你们众人同在。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 1, 1, '奉神旨意作基督耶稣使徒的保罗和兄弟提摩太，写信给在哥林多神的教会，并亚该亚遍处的众圣徒。'),
('CUV', '哥林多后书', 47, 1, 2, '愿恩惠、平安从神我们的父和主耶稣基督归与你们！'),
('CUV', '哥林多后书', 47, 1, 3, '愿颂赞归与我们的主耶稣基督的父神，就是发慈悲的父，赐各样安慰的神。'),
('CUV', '哥林多后书', 47, 1, 4, '我们在一切患难中，他就安慰我们，叫我们能用神所赐的安慰去安慰那遭各样患难的人。'),
('CUV', '哥林多后书', 47, 1, 5, '我们既多受基督的苦楚，就靠基督多得安慰。'),
('CUV', '哥林多后书', 47, 1, 6, '我们受患难呢，是为叫你们得安慰，得拯救；我们得安慰呢，也是为叫你们得安慰；这安慰能叫你们忍受我们所受的那样苦楚。'),
('CUV', '哥林多后书', 47, 1, 7, '我们为你们所存的盼望是确定的，因为知道你们既是同受苦楚，也必同得安慰。'),
('CUV', '哥林多后书', 47, 1, 8, '弟兄们，我们不要你们不晓得，我们从前在亚西亚遭遇苦难，被压太重，力不能胜，甚至连活命的指望都绝了；'),
('CUV', '哥林多后书', 47, 1, 9, '自己心里也断定是必死的，叫我们不靠自己，只靠叫死人复活的神。'),
('CUV', '哥林多后书', 47, 1, 10, '他曾救我们脱离那极大的死亡，现在仍要救我们，并且我们指望他将来还要救我们。'),
('CUV', '哥林多后书', 47, 1, 11, '你们以祈祷帮助我们，好叫许多人为我们谢恩，就是为我们因许多人所得的恩。'),
('CUV', '哥林多后书', 47, 1, 12, '我们所夸的是自己的良心，见证我们凭著神的圣洁和诚实；在世为人不靠人的聪明，乃靠神的恩惠，向你们更是这样。'),
('CUV', '哥林多后书', 47, 1, 13, '我们现在写给你们的话，并不外乎你们所念的，所认识的，我也盼望你们到底还是要认识；'),
('CUV', '哥林多后书', 47, 1, 14, '正如你们已经有几分认识我们，以我们夸口，好像我们在我们主耶稣的日子以你们夸口一样。'),
('CUV', '哥林多后书', 47, 1, 15, '我既然这样深信，就早有意到你们那里去，叫你们再得益处；'),
('CUV', '哥林多后书', 47, 1, 16, '也要从你们那里经过，往马其顿去，再从马其顿回到你们那里，叫你们给我送行往犹太去。'),
('CUV', '哥林多后书', 47, 1, 17, '我有此意，岂是反复不定么？我所起的意，岂是从情欲起的，叫我忽是忽非么？'),
('CUV', '哥林多后书', 47, 1, 18, '我指著信实的神说，我们向你们所传的道，并没有是而又非的。'),
('CUV', '哥林多后书', 47, 1, 19, '因为我和西拉并提摩太，在你们中间所传神的儿子耶稣基督，总没有是而又非的，在他只有一是。'),
('CUV', '哥林多后书', 47, 1, 20, '神的应许，不论有多少，在基督都是是的。所以藉著他也都是实在（实在：原文是阿们）的，叫神因我们得荣耀。'),
('CUV', '哥林多后书', 47, 1, 21, '那在基督里坚固我们和你们，并且膏我们的就是神。'),
('CUV', '哥林多后书', 47, 1, 22, '他又用印印了我们，并赐圣灵在我们心里作凭据（原文是质）。'),
('CUV', '哥林多后书', 47, 1, 23, '我呼吁神给我的心作见证，我没有往哥林多去是为要宽容你们。'),
('CUV', '哥林多后书', 47, 1, 24, '我们并不是辖管你们的信心，乃是帮助你们的快乐，因为你们凭信才站立得住。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 2, 1, '我自己定了主意再到你们那里去，必须大家没有忧愁。'),
('CUV', '哥林多后书', 47, 2, 2, '倘若我叫你们忧愁，除了我叫那忧愁的人以外，谁能叫我快乐呢？'),
('CUV', '哥林多后书', 47, 2, 3, '我曾把这事写给你们，恐怕我到的时候，应该叫我快乐的那些人，反倒叫我忧愁。我也深信，你们众人都以我的快乐为自己的快乐。'),
('CUV', '哥林多后书', 47, 2, 4, '我先前心里难过痛苦，多多的流泪，写信给你们，不是叫你们忧愁，乃是叫你们知道我格外的疼爱你们。'),
('CUV', '哥林多后书', 47, 2, 5, '若有叫人忧愁的，他不但叫我忧愁，也是叫你们众人有几分忧愁。我说几分，恐怕说得太重。'),
('CUV', '哥林多后书', 47, 2, 6, '这样的人受了众人的责罚也就够了，'),
('CUV', '哥林多后书', 47, 2, 7, '倒不如赦免他，安慰他，免得他忧愁太过，甚至沉沦了。'),
('CUV', '哥林多后书', 47, 2, 8, '所以我劝你们，要向他显出坚定不移的爱心来。'),
('CUV', '哥林多后书', 47, 2, 9, '为此我先前也写信给你们，要试验你们，看你们凡事顺从不顺从。'),
('CUV', '哥林多后书', 47, 2, 10, '你们赦免谁，我也赦免谁。我若有所赦免的，是在基督面前为你们赦免的；'),
('CUV', '哥林多后书', 47, 2, 11, '免得撒但趁著机会胜过我们，因我们并非不晓得他的诡计。'),
('CUV', '哥林多后书', 47, 2, 12, '我从前为基督的福音到了特罗亚，主也给我开了门。'),
('CUV', '哥林多后书', 47, 2, 13, '那时，因为没有遇见兄弟提多，我心里不安，便辞别那里的人往马其顿去了。'),
('CUV', '哥林多后书', 47, 2, 14, '感谢神！常帅领我们在基督里夸胜，并藉著我们在各处显扬那因认识基督而有的香气。'),
('CUV', '哥林多后书', 47, 2, 15, '因为我们在神面前，无论在得救的人身上或灭亡的人身上，都有基督馨香之气。'),
('CUV', '哥林多后书', 47, 2, 16, '在这等人，就作了死的香气叫他死；在那等人，就作了活的香气叫他活。这事谁能当得起呢？'),
('CUV', '哥林多后书', 47, 2, 17, '我们不像那许多人，为利混乱神的道；乃是由于诚实，由于神，在神面前凭著基督讲道。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 3, 1, '我们岂是又举荐自己么？岂像别人用人的荐信给你们或用你们的荐信给人么？'),
('CUV', '哥林多后书', 47, 3, 2, '你们就是我们的荐信，写在我们的心里，被众人所知道所念诵的。'),
('CUV', '哥林多后书', 47, 3, 3, '你们明显是基督的信，藉著我们修成的。不是用墨写的，乃是用永生神的灵写的；不是写在石版上，乃是写在心版上。'),
('CUV', '哥林多后书', 47, 3, 4, '我们因基督，所以在神面前才有这样的信心。'),
('CUV', '哥林多后书', 47, 3, 5, '并不是我们凭自己能承担甚么事；我们所能承担的，乃是出于神。'),
('CUV', '哥林多后书', 47, 3, 6, '他叫我们能承当这新约的执事，不是凭著字句，乃是凭著精意；因为那字句是叫人死，精意（或作：圣灵）是叫人活。'),
('CUV', '哥林多后书', 47, 3, 7, '那用字刻在石头上属死的职事尚且有荣光，甚至以色列人因摩西面上的荣光，不能定睛看他的脸；这荣光原是渐渐退去的，'),
('CUV', '哥林多后书', 47, 3, 8, '何况那属灵的职事岂不更有荣光么？'),
('CUV', '哥林多后书', 47, 3, 9, '若是定罪的职事有荣光，那称义的职事荣光就越发大了。'),
('CUV', '哥林多后书', 47, 3, 10, '那从前有荣光的，因这极大的荣光就算不得有荣光了；'),
('CUV', '哥林多后书', 47, 3, 11, '若那废掉的有荣光，这长存的就更有荣光了。'),
('CUV', '哥林多后书', 47, 3, 12, '我们既有这样的盼望，就大胆讲说，'),
('CUV', '哥林多后书', 47, 3, 13, '不像摩西将帕子蒙在脸上，叫以色列人不能定睛看到那将废者的结局。'),
('CUV', '哥林多后书', 47, 3, 14, '但他们的心地刚硬，直到今日诵读旧约的时候，这帕子还没有揭去。这帕子在基督里已经废去了。'),
('CUV', '哥林多后书', 47, 3, 15, '然而直到今日，每逢诵读摩西书的时候，帕子还在他们心上。'),
('CUV', '哥林多后书', 47, 3, 16, '但他们的心几时归向主，帕子就几时除去了。'),
('CUV', '哥林多后书', 47, 3, 17, '主就是那灵；主的灵在那里，那里就得以自由。'),
('CUV', '哥林多后书', 47, 3, 18, '我们众人既然敞著脸得以看见主的荣光，好像从镜子里返照，就变成主的形状，荣上加荣，如同从主的灵变成的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 4, 1, '我们既然蒙怜悯，受了这职分，就不丧胆，'),
('CUV', '哥林多后书', 47, 4, 2, '乃将那些暗昧可耻的事弃绝了；不行诡诈，不谬讲神的道理，只将真理表明出来，好在神面前把自己荐与各人的良心。'),
('CUV', '哥林多后书', 47, 4, 3, '如果我们的福音蒙蔽，就是蒙蔽在灭亡的人身上。'),
('CUV', '哥林多后书', 47, 4, 4, '此等不信之人被这世界的神弄瞎了心眼，不叫基督荣耀福音的光照著他们。基督本是神的像。'),
('CUV', '哥林多后书', 47, 4, 5, '我们原不是传自己，乃是传基督耶稣为主，并且自己因耶稣作你们的仆人。'),
('CUV', '哥林多后书', 47, 4, 6, '那吩咐光从黑暗里照出来的神，已经照在我们心里，叫我们得知神荣耀的光显在耶稣基督的面上。'),
('CUV', '哥林多后书', 47, 4, 7, '我们有这宝贝放在瓦器里，要显明这莫大的能力是出于神，不是出于我们。'),
('CUV', '哥林多后书', 47, 4, 8, '我们四面受敌，却不被困住；心里作难，却不至失望；'),
('CUV', '哥林多后书', 47, 4, 9, '遭逼迫，却不被丢弃；打倒了，却不至死亡。'),
('CUV', '哥林多后书', 47, 4, 10, '身上常带著耶稣的死，使耶稣的生也显明在我们身上。'),
('CUV', '哥林多后书', 47, 4, 11, '因为我们这活著的人是常为耶稣被交于死地，使耶稣的生在我们这必死的身上显明出来。'),
('CUV', '哥林多后书', 47, 4, 12, '这样看来，死是在我们身上发动，生却在你们身上发动。'),
('CUV', '哥林多后书', 47, 4, 13, '但我们既有信心，正如经上记著说：我因信，所以如此说话。我们也信，所以也说话。'),
('CUV', '哥林多后书', 47, 4, 14, '自己知道那叫主耶稣复活的，也必叫我们与耶稣一同复活，并且叫我们与你们一同站在他面前。'),
('CUV', '哥林多后书', 47, 4, 15, '凡事都是为你们，好叫恩惠因人多越发加增，感谢格外显多，以致荣耀归与神。'),
('CUV', '哥林多后书', 47, 4, 16, '所以，我们不丧胆。外体虽然毁坏，内心却一天新似一天。'),
('CUV', '哥林多后书', 47, 4, 17, '我们这至暂至轻的苦楚，要为我们成就极重无比、永远的荣耀。'),
('CUV', '哥林多后书', 47, 4, 18, '原来我们不是顾念所见的，乃是顾念所不见的；因为所见的是暂时的，所不见的是永远的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 5, 1, '我们原知道，我们这地上的帐棚若拆毁了，必得神所造，不是人手所造，在天上永存的房屋。'),
('CUV', '哥林多后书', 47, 5, 2, '我们在这帐棚里叹息，深想得那从天上来的房屋，好像穿上衣服；'),
('CUV', '哥林多后书', 47, 5, 3, '倘若穿上，被遇见的时候就不至于赤身了。'),
('CUV', '哥林多后书', 47, 5, 4, '我们在这帐棚里叹息劳苦，并非愿意脱下这个，乃是愿意穿上那个，好叫这必死的被生命吞灭了。'),
('CUV', '哥林多后书', 47, 5, 5, '为此，培植我们的就是神，他又赐给我们圣灵作凭据（原文是质）。'),
('CUV', '哥林多后书', 47, 5, 6, '所以，我们时常坦然无惧，并且晓得我们住在身内，便与主相离。'),
('CUV', '哥林多后书', 47, 5, 7, '因我们行事为人是凭著信心，不是凭著眼见。'),
('CUV', '哥林多后书', 47, 5, 8, '我们坦然无惧，是更愿意离开身体与主同住。'),
('CUV', '哥林多后书', 47, 5, 9, '所以，无论是住在身内，离开身外，我们立了志向，要得主的喜悦。'),
('CUV', '哥林多后书', 47, 5, 10, '因为我们众人必要在基督台前显露出来，叫各人按著本身所行的，或善或恶受报。'),
('CUV', '哥林多后书', 47, 5, 11, '我们既知道主是可畏的，所以劝人。但我们在神面前是显明的，盼望在你们的良心里也是显明的。'),
('CUV', '哥林多后书', 47, 5, 12, '我们不是向你们再举荐自己，乃是叫你们因我们有可夸之处，好对那凭外貌不凭内心夸口的人，有言可答。'),
('CUV', '哥林多后书', 47, 5, 13, '我们若果颠狂，是为神；若果谨守，是为你们。'),
('CUV', '哥林多后书', 47, 5, 14, '原来基督的爱激励我们；因我们想，一人既替众人死，众人就都死了；'),
('CUV', '哥林多后书', 47, 5, 15, '并且他替众人死，是叫那些活著的人不再为自己活，乃为替他们死而复活的主活。'),
('CUV', '哥林多后书', 47, 5, 16, '所以，我们从今以后，不凭著外貌（原文是肉体；本节同）认人了。虽然凭著外貌认过基督，如今却不再这样认他了。'),
('CUV', '哥林多后书', 47, 5, 17, '若有人在基督里，他就是新造的人，旧事已过，都变成新的了。'),
('CUV', '哥林多后书', 47, 5, 18, '一切都是出于神；他藉著基督使我们与他和好，又将劝人与他和好的职分赐给我们。'),
('CUV', '哥林多后书', 47, 5, 19, '这就是神在基督里，叫世人与自己和好，不将他们的过犯归到他们身上，并且将这和好的道理托付了我们。'),
('CUV', '哥林多后书', 47, 5, 20, '所以，我们作基督的使者，就好像神藉我们劝你们一般。我们替基督求你们与神和好。'),
('CUV', '哥林多后书', 47, 5, 21, '神使那无罪（无罪：原文是不知罪）的，替我们成为罪，好叫我们在他里面成为神的义。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 6, 1, '我们与神同工的，也劝你们不可徒受他的恩典。'),
('CUV', '哥林多后书', 47, 6, 2, '因为他说：在悦纳的时候，我应允了你；在拯救的日子，我搭救了你。看哪！现在正是悦纳的时候；现在正是拯救的日子。'),
('CUV', '哥林多后书', 47, 6, 3, '我们凡事都不叫人有妨碍，免得这职分被人毁谤；'),
('CUV', '哥林多后书', 47, 6, 4, '反倒在各样的事上表明自己是神的用人，就如在许多的忍耐、患难、穷乏、困苦、'),
('CUV', '哥林多后书', 47, 6, 5, '鞭打、监禁、扰乱、勤劳、儆醒、不食、'),
('CUV', '哥林多后书', 47, 6, 6, '廉洁、知识、恒忍、恩慈、圣灵的感化、无伪的爱心、'),
('CUV', '哥林多后书', 47, 6, 7, '真实的道理、神的大能；仁义的兵器在左在右；'),
('CUV', '哥林多后书', 47, 6, 8, '荣耀、羞辱，恶名、美名；似乎是诱惑人的，却是诚实的；'),
('CUV', '哥林多后书', 47, 6, 9, '似乎不为人所知，却是人所共知的；似乎要死，却是活著的；似乎受责罚，却是不至丧命的；'),
('CUV', '哥林多后书', 47, 6, 10, '似乎忧愁，却是常常快乐的；似乎贫穷，却是叫许多人富足的；似乎一无所有，却是样样都有的。'),
('CUV', '哥林多后书', 47, 6, 11, '哥林多人哪，我们向你们，口是张开的，心是宽宏的。'),
('CUV', '哥林多后书', 47, 6, 12, '你们狭窄，原不在乎我们，是在乎自己的心肠狭窄。'),
('CUV', '哥林多后书', 47, 6, 13, '你们也要照样用宽宏的心报答我。我这话正像对自己的孩子说的。'),
('CUV', '哥林多后书', 47, 6, 14, '你们和不信的原不相配，不要同负一轭。义和不义有甚么相交呢？光明和黑暗有甚么相通呢？'),
('CUV', '哥林多后书', 47, 6, 15, '基督和彼列（彼列就是撒但的别名）有甚么相和呢？信主的和不信主的有甚么相干呢？'),
('CUV', '哥林多后书', 47, 6, 16, '神的殿和偶像有甚么相同呢？因为我们是永生神的殿，就如神曾说：我要在他们中间居住，在他们中间来往；我要作他们的神；他们要作我的子民。'),
('CUV', '哥林多后书', 47, 6, 17, '又说：你们务要从他们中间出来，与他们分别；不要沾不洁净的物，我就收纳你们。'),
('CUV', '哥林多后书', 47, 6, 18, '我要作你们的父；你们要作我的儿女。这是全能的主说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 7, 1, '亲爱的弟兄阿，我们既有这等应许，就当洁净自己，除去身体、灵魂一切的污秽，敬畏神，得以成圣。'),
('CUV', '哥林多后书', 47, 7, 2, '你们要心地宽大收纳我们。我们未曾亏负谁，未曾败坏谁，未曾占谁的便宜。'),
('CUV', '哥林多后书', 47, 7, 3, '我说这话，不是要定你们的罪。我已经说过，你们常在我们心里，情愿与你们同生同死。'),
('CUV', '哥林多后书', 47, 7, 4, '我大大的放胆，向你们说话；我因你们多多夸口，满得安慰；我们在一切患难中分外的快乐。'),
('CUV', '哥林多后书', 47, 7, 5, '我们从前就是到了马其顿的时候，身体也不得安宁，周围遭患难，外有争战，内有惧怕。'),
('CUV', '哥林多后书', 47, 7, 6, '但那安慰丧气之人的神藉著提多来安慰了我们；'),
('CUV', '哥林多后书', 47, 7, 7, '不但藉著他来，也藉著他从你们所得的安慰，安慰了我们；因他把你们的想念、哀恸，和向我的热心，都告诉了我，叫我更加欢喜。'),
('CUV', '哥林多后书', 47, 7, 8, '我先前写信叫你们忧愁，我后来虽然懊悔，如今却不懊悔；因我知道，那信叫你们忧愁不过是暂时的。'),
('CUV', '哥林多后书', 47, 7, 9, '如今我欢喜，不是因你们忧愁，是因你们从忧愁中生出懊悔来。你们依著神的意思忧愁，凡事就不至于因我们受亏损了。'),
('CUV', '哥林多后书', 47, 7, 10, '因为依著神的意思忧愁，就生出没有后悔的懊悔来。以致得救；但世俗的忧愁是叫人死。'),
('CUV', '哥林多后书', 47, 7, 11, '你看，你们依著神的意思忧愁，从此就生出何等的慇懃、自诉、自恨、恐惧、想念、热心、责罚（或作：自责）。在这一切事上，你们都表明自己是洁净的。'),
('CUV', '哥林多后书', 47, 7, 12, '我虽然从前写信给你们，却不是为那亏负人的，也不是为那受人亏负的，乃要在神面前把你们顾念我们的热心表明出来。'),
('CUV', '哥林多后书', 47, 7, 13, '故此，我们得了安慰。并且在安慰之中，因你们众人使提多心里畅快欢喜，我们就更加欢喜了。'),
('CUV', '哥林多后书', 47, 7, 14, '我若对提多夸奖了你们甚么，也觉得没有惭愧；因我对提多夸奖你们的话成了真的，正如我对你们所说的话也都是真的。'),
('CUV', '哥林多后书', 47, 7, 15, '并且提多想起你们众人的顺服，是怎样恐惧战兢的接待他，他爱你们的心肠就越发热了。'),
('CUV', '哥林多后书', 47, 7, 16, '我如今欢喜，能在凡事上为你们放心。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 8, 1, '弟兄们，我把神赐给马其顿众教会的恩告诉你们，'),
('CUV', '哥林多后书', 47, 8, 2, '就是他们在患难中受大试炼的时候，仍有满足的快乐，在极穷之间还格外显出他们乐捐的厚恩。'),
('CUV', '哥林多后书', 47, 8, 3, '我可以证明，他们是按著力量，而且也过了力量，自己甘心乐意的捐助，'),
('CUV', '哥林多后书', 47, 8, 4, '再三的求我们，准他们在这供给圣徒的恩情上有分；'),
('CUV', '哥林多后书', 47, 8, 5, '并且他们所做的，不但照我们所想望的，更照神的旨意先把自己献给主，又归附了我们。'),
('CUV', '哥林多后书', 47, 8, 6, '因此我劝提多，既然在你们中间开办这慈惠的事，就当办成了。'),
('CUV', '哥林多后书', 47, 8, 7, '你们既然在信心、口才、知识、热心，和待我们的爱心上，都格外显出满足来，就当在这慈惠的事上也格外显出满足来。'),
('CUV', '哥林多后书', 47, 8, 8, '我说这话，不是吩咐你们，乃是藉著别人的热心试验你们爱心的实在。'),
('CUV', '哥林多后书', 47, 8, 9, '你们知道我们主耶稣基督的恩典：他本来富足，却为你们成了贫穷，叫你们因他的贫穷，可以成为富足。'),
('CUV', '哥林多后书', 47, 8, 10, '我在这事上把我的意见告诉你们，是与你们有益；因为你们下手办这事，而且起此心意，已经有一年了，'),
('CUV', '哥林多后书', 47, 8, 11, '如今就当办成这事。既有愿做的心，也当照你们所有的去办成。'),
('CUV', '哥林多后书', 47, 8, 12, '因为人若有愿做的心，必蒙悦纳，乃是照他所有的，并不是照他所无的。'),
('CUV', '哥林多后书', 47, 8, 13, '我原不是要别人轻省，你们受累，'),
('CUV', '哥林多后书', 47, 8, 14, '乃要均平，就是要你们的富余，现在可以补他们的不足，使他们的富余，将来也可以补你们的不足，这就均平了。'),
('CUV', '哥林多后书', 47, 8, 15, '如经上所记：多收的也没有余；少收的也没有缺。'),
('CUV', '哥林多后书', 47, 8, 16, '多谢神，感动提多的心，叫他待你们殷勤，像我一样。'),
('CUV', '哥林多后书', 47, 8, 17, '他固然是听了我的劝，但自己更是热心，情愿往你们那里去。'),
('CUV', '哥林多后书', 47, 8, 18, '我们还打发一位兄弟和他同去，这人在福音上得了众教会的称赞。'),
('CUV', '哥林多后书', 47, 8, 19, '不但这样，他也被众教会挑选，和我们同行，把所托与我们的这捐赀送到了，可以荣耀主，又表明我们乐意的心。'),
('CUV', '哥林多后书', 47, 8, 20, '这就免得有人因我们收的捐银很多，就挑我们的不是。'),
('CUV', '哥林多后书', 47, 8, 21, '我们留心行光明的事，不但在主面前，就在人面前也是这样。'),
('CUV', '哥林多后书', 47, 8, 22, '我们又打发一位兄弟同去；这人的热心，我们在许多事上屡次试验过。现在他因为深信你们，就更加热心了。'),
('CUV', '哥林多后书', 47, 8, 23, '论到提多，他是我的同伴，一同为你们劳碌的。论到那两位兄弟，他们是众教会的使者，是基督的荣耀。'),
('CUV', '哥林多后书', 47, 8, 24, '所以，你们务要在众教会面前显明你们爱心的凭据，并我所夸奖你们的凭据。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 9, 1, '论到供给圣徒的事，我不必写信给你们；'),
('CUV', '哥林多后书', 47, 9, 2, '因为我知道你们乐意的心，常对马其顿人夸奖你们，说亚该亚人预备好了，已经有一年了；并且你们的热心激动了许多人。'),
('CUV', '哥林多后书', 47, 9, 3, '但我打发那几位弟兄去，要叫你们照我的话预备妥当；免得我们在这事上夸奖你们的话落了空。'),
('CUV', '哥林多后书', 47, 9, 4, '万一有马其顿人与我同去，见你们没有预备，就叫我们所确信的，反成了羞愧；你们羞愧，更不用说了。'),
('CUV', '哥林多后书', 47, 9, 5, '因此，我想不得不求那几位弟兄先到你们那里去，把从前所应许的捐赀预备妥当，就显出你们所捐的是出于乐意，不是出于勉强。'),
('CUV', '哥林多后书', 47, 9, 6, '少种的少收，多种的多收，这话是真的。'),
('CUV', '哥林多后书', 47, 9, 7, '各人要随本心所酌定的，不要作难，不要勉强，因为捐得乐意的人是神所喜爱的。'),
('CUV', '哥林多后书', 47, 9, 8, '神能将各样的恩惠多多的加给你们，使你们凡事常常充足，能多行各样善事。'),
('CUV', '哥林多后书', 47, 9, 9, '如经上所记：他施舍钱财，赒济贫穷；他的仁义存到永远。'),
('CUV', '哥林多后书', 47, 9, 10, '那赐种给撒种的，赐粮给人吃的，必多多加给你们种地的种子，又增添你们仁义的果子；'),
('CUV', '哥林多后书', 47, 9, 11, '叫你们凡事富足，可以多多施舍，就藉著我们使感谢归于神。'),
('CUV', '哥林多后书', 47, 9, 12, '因为办这供给的事，不但补圣徒的缺乏，而且叫许多人越发感谢神。'),
('CUV', '哥林多后书', 47, 9, 13, '他们从这供给的事上得了凭据，知道你们承认基督顺服他的福音，多多的捐钱给他们和众人，便将荣耀归与神。'),
('CUV', '哥林多后书', 47, 9, 14, '他们也因神极大的恩赐显在你们心里，就切切的想念你们，为你们祈祷。'),
('CUV', '哥林多后书', 47, 9, 15, '感谢神，因他有说不尽的恩赐！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 10, 1, '我保罗，就是与你们见面的时候是谦卑的，不在你们那里的时候向你们是勇敢的，如今亲自藉著基督的温柔、和平劝你们。'),
('CUV', '哥林多后书', 47, 10, 2, '有人以为我是凭著血气行事，我也以为必须用勇敢待这等人；求你们不要叫我在你们那里的时候，有这样的勇敢。'),
('CUV', '哥林多后书', 47, 10, 3, '因为我们虽然在血气中行事，却不凭著血气争战。'),
('CUV', '哥林多后书', 47, 10, 4, '我们争战的兵器本不是属血气的，乃是在神面前有能力，可以攻破坚固的营垒，'),
('CUV', '哥林多后书', 47, 10, 5, '将各样的计谋，各样拦阻人认识神的那些自高之事，一概攻破了，又将人所有的心意夺回，使他都顺服基督。'),
('CUV', '哥林多后书', 47, 10, 6, '并且我已经预备好了，等你们十分顺服的时候，要责罚那一切不顺服的人。'),
('CUV', '哥林多后书', 47, 10, 7, '你们是看眼前的么？倘若有人自信是属基督的，他要再想想，他如何属基督，我们也是如何属基督的。'),
('CUV', '哥林多后书', 47, 10, 8, '主赐给我们权柄，是要造就你们，并不是要败坏你们；我就是为这权柄稍微夸口，也不至于惭愧。'),
('CUV', '哥林多后书', 47, 10, 9, '我说这话，免得你们以为我写信是要威吓你们；'),
('CUV', '哥林多后书', 47, 10, 10, '因为有人说：他的信又沉重又利害，及至见面，却是气貌不扬，言语粗俗的。'),
('CUV', '哥林多后书', 47, 10, 11, '这等人当想，我们不在那里的时候，信上的言语如何，见面的时候，行事也必如何。'),
('CUV', '哥林多后书', 47, 10, 12, '因为我们不敢将自己和那自荐的人同列相比。他们用自己度量自己，用自己比较自己，乃是不通达的。'),
('CUV', '哥林多后书', 47, 10, 13, '我们不愿意分外夸口，只要照神所量给我们的界限搆到你们那里。'),
('CUV', '哥林多后书', 47, 10, 14, '我们并非过了自己的界限，好像搆不到你们那里；因为我们早到你们那里，传了基督的福音。'),
('CUV', '哥林多后书', 47, 10, 15, '我们不仗著别人所劳碌的，分外夸口；但指望你们信心增长的时候，所量给我们的界限，就可以因著你们更加开展，'),
('CUV', '哥林多后书', 47, 10, 16, '得以将福音传到你们以外的地方；并不是在别人界限之内，藉著他现成的事夸口。'),
('CUV', '哥林多后书', 47, 10, 17, '但夸口的，当指著主夸口。'),
('CUV', '哥林多后书', 47, 10, 18, '因为蒙悦纳的，不是自己称许的，乃是主所称许的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 11, 1, '但愿你们宽容我这一点愚妄，其实你们原是宽容我的。'),
('CUV', '哥林多后书', 47, 11, 2, '我为你们起的愤恨，原是神那样的愤恨。因为我曾把你们许配一个丈夫，要把你们如同贞洁的童女，献给基督。'),
('CUV', '哥林多后书', 47, 11, 3, '我只怕你们的心或偏于邪，失去那向基督所存纯一清洁的心，就像蛇用诡诈诱惑了夏娃一样。'),
('CUV', '哥林多后书', 47, 11, 4, '假如有人来另传一个耶稣，不是我们所传过的；或者你们另受一个灵，不是你们所受过的；或者另得一个福音，不是你们所得过的；你们容让他也就罢了。'),
('CUV', '哥林多后书', 47, 11, 5, '但我想，我一点不在那些最大的使徒以下。'),
('CUV', '哥林多后书', 47, 11, 6, '我的言语虽然粗俗，我的知识却不粗俗。这是我们在凡事上向你们众人显明出来的。'),
('CUV', '哥林多后书', 47, 11, 7, '我因为白白传神的福音给你们，就自居卑微，叫你们高升，这算是我犯罪么？'),
('CUV', '哥林多后书', 47, 11, 8, '我亏负了别的教会，向他们取了工价来给你们效力。'),
('CUV', '哥林多后书', 47, 11, 9, '我在你们那里缺乏的时候，并没有累著你们一个人；因我所缺乏的，那从马其顿来的弟兄们都补足了。我向来凡事谨守，后来也必谨守，总不至于累著你们。'),
('CUV', '哥林多后书', 47, 11, 10, '既有基督的诚实在我里面，就无人能在亚该亚一带地方阻挡我这自夸。'),
('CUV', '哥林多后书', 47, 11, 11, '为甚么呢？是因我不爱你们么？这有神知道。'),
('CUV', '哥林多后书', 47, 11, 12, '我现在所做的，后来还要做，为要断绝那些寻机会人的机会，使他们在所夸的事上也不过与我们一样。'),
('CUV', '哥林多后书', 47, 11, 13, '那等人是假使徒，行事诡诈，装作基督使徒的模样。'),
('CUV', '哥林多后书', 47, 11, 14, '这也不足为怪，因为连撒但也装作光明的天使。'),
('CUV', '哥林多后书', 47, 11, 15, '所以他的差役，若装作仁义的差役，也不算希奇。他们的结局必然照著他们的行为。'),
('CUV', '哥林多后书', 47, 11, 16, '我再说，人不可把我看作愚妄的。纵然如此，也要把我当作愚妄人接纳，叫我可以略略自夸。'),
('CUV', '哥林多后书', 47, 11, 17, '我说的话不是奉主命说的，乃是像愚妄人放胆自夸；'),
('CUV', '哥林多后书', 47, 11, 18, '既有好些人凭著血气自夸，我也要自夸了。'),
('CUV', '哥林多后书', 47, 11, 19, '你们既是精明人，就能甘心忍耐愚妄人。'),
('CUV', '哥林多后书', 47, 11, 20, '假若有人强你们作奴仆，或侵吞你们，或掳掠你们，或侮慢你们，或打你们的脸，你们都能忍耐他。'),
('CUV', '哥林多后书', 47, 11, 21, '我说这话是羞辱自己，好像我们从前是软弱的。然而，人在何事上勇敢，（我说句愚妄话，）我也勇敢。'),
('CUV', '哥林多后书', 47, 11, 22, '他们是希伯来人么？我也是。他们是以色列人么？我也是。他们是亚伯拉罕的后裔么？我也是。'),
('CUV', '哥林多后书', 47, 11, 23, '他们是基督的仆人么？（我说句狂话，）我更是。我比他们多受劳苦，多下监牢，受鞭打是过重的，冒死是屡次有的。'),
('CUV', '哥林多后书', 47, 11, 24, '被犹太人鞭打五次，每次四十减去一下；'),
('CUV', '哥林多后书', 47, 11, 25, '被棍打了三次；被石头打了一次，遇著船坏三次，一昼一夜在深海里。'),
('CUV', '哥林多后书', 47, 11, 26, '又屡次行远路，遭江河的危险、盗贼的危险，同族的危险、外邦人的危险、城里的危险、旷野的危险、海中的危险、假弟兄的危险。'),
('CUV', '哥林多后书', 47, 11, 27, '受劳碌、受困苦，多次不得睡，又饥又渴，多次不得食，受寒冷，赤身露体。'),
('CUV', '哥林多后书', 47, 11, 28, '除了这外面的事，还有为众教会挂心的事，天天压在我身上。'),
('CUV', '哥林多后书', 47, 11, 29, '有谁软弱，我不软弱呢？有谁跌倒，我不焦急呢？'),
('CUV', '哥林多后书', 47, 11, 30, '我若必须自夸，就夸那关乎我软弱的事便了。'),
('CUV', '哥林多后书', 47, 11, 31, '那永远可称颂之主耶稣的父神知道我不说谎。'),
('CUV', '哥林多后书', 47, 11, 32, '在大马色亚哩达王手下的提督把守大马色城，要捉拿我，'),
('CUV', '哥林多后书', 47, 11, 33, '我就从窗户中，在筐子里，从城墙上被人缒下去，脱离了他的手。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 12, 1, '我自夸固然无益，但我是不得已的。如今我要说到主的显现和启示。'),
('CUV', '哥林多后书', 47, 12, 2, '我认得一个在基督里的人，他前十四年被提到第三层天上去；或在身内，我不知道；或在身外，我也不知道；只有神知道。'),
('CUV', '哥林多后书', 47, 12, 3, '我认得这人；或在身内，或在身外，我都不知道，只有神知道。'),
('CUV', '哥林多后书', 47, 12, 4, '他被提到乐园里，听见隐秘的言语，是人不可说的。'),
('CUV', '哥林多后书', 47, 12, 5, '为这人，我要夸口；但是为我自己，除了我的软弱以外，我并不夸口。'),
('CUV', '哥林多后书', 47, 12, 6, '我就是愿意夸口也不算狂，因为我必说实话；只是我禁止不说，恐怕有人把我看高了，过于他在我身上所看见所听见的。'),
('CUV', '哥林多后书', 47, 12, 7, '又恐怕我因所得的启示甚大，就过于自高，所以有一根刺加在我肉体上，就是撒但的差役要攻击我，免得我过于自高。'),
('CUV', '哥林多后书', 47, 12, 8, '为这事，我三次求过主，叫这刺离开我。'),
('CUV', '哥林多后书', 47, 12, 9, '他对我说：我的恩典够你用的，因为我的能力是在人的软弱上显得完全。所以，我更喜欢夸自己的软弱，好叫基督的能力覆庇我。'),
('CUV', '哥林多后书', 47, 12, 10, '我为基督的缘故，就以软弱、凌辱、急难、逼迫、困苦为可喜乐的；因我甚么时候软弱，甚么时候就刚强了。'),
('CUV', '哥林多后书', 47, 12, 11, '我成了愚妄人，是被你们强逼的。我本该被你们称许才是。我虽算不了甚么，却没有一件事在那些最大的使徒以下。'),
('CUV', '哥林多后书', 47, 12, 12, '我在你们中间，用百般的忍耐，藉著神迹、奇事、异能，显出使徒的凭据来。'),
('CUV', '哥林多后书', 47, 12, 13, '除了我不累著你们这一件事，你们还有甚么事不及别的教会呢？这不公之处，求你们饶恕我罢。'),
('CUV', '哥林多后书', 47, 12, 14, '如今，我打算第三次到你们那里去，也必不累著你们；因我所求的是你们，不是你们的财物。儿女不该为父母积财，父母该为儿女积财。'),
('CUV', '哥林多后书', 47, 12, 15, '我也甘心乐意为你们的灵魂费财费力。难道我越发爱你们，就越发少得你们的爱么？'),
('CUV', '哥林多后书', 47, 12, 16, '罢了，我自己并没有累著你们，你们却有人说，我是诡诈，用心计牢笼你们。'),
('CUV', '哥林多后书', 47, 12, 17, '我所差到你们那里去的人，我藉著他们一个人占过你们的便宜么？'),
('CUV', '哥林多后书', 47, 12, 18, '我劝了提多到你们那里去；又差那位兄弟与他同去。提多占过你们的便宜么？我们行事，不同是一个心灵（或作：圣灵）么？不同是一个脚踪么？'),
('CUV', '哥林多后书', 47, 12, 19, '你们到如今，还想我们是向你们分诉；我们本是在基督里当神面前说话。亲爱的弟兄阿，一切的事都是为造就你们。'),
('CUV', '哥林多后书', 47, 12, 20, '我怕我再来的时候，见你们不合我所想望的，你们见我也不合你们所想望的；又怕有纷争、嫉妒、恼怒、结党、毁谤、谗言、狂傲、混乱的事。'),
('CUV', '哥林多后书', 47, 12, 21, '且怕我来的时候，我的神叫我在你们面前惭愧，又因许多人从前犯罪，行污秽、奸淫、邪荡的事不肯悔改，我就忧愁。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哥林多后书', 47, 13, 1, '这是我第三次要到你们那里去。凭两三个人的口作见证，句句都要定准。'),
('CUV', '哥林多后书', 47, 13, 2, '我从前说过，如今不在你们那里又说，正如我第二次见你们的时候所说的一样，就是对那犯了罪的和其余的人说：我若再来，必不宽容。'),
('CUV', '哥林多后书', 47, 13, 3, '你们既然寻求基督在我里面说话的凭据，我必不宽容。因为，基督在你们身上不是软弱的，在你们里面是有大能的。'),
('CUV', '哥林多后书', 47, 13, 4, '他因软弱被钉在十字架上，却因神的大能仍然活著。我们也是这样同他软弱，但因神向你们所显的大能，也必与他同活。'),
('CUV', '哥林多后书', 47, 13, 5, '你们总要自己省察有信心没有，也要自己试验。岂不知你们若不是可弃绝的，就有耶稣基督在你们心里么？'),
('CUV', '哥林多后书', 47, 13, 6, '我却盼望你们晓得，我们不是可弃绝的人。'),
('CUV', '哥林多后书', 47, 13, 7, '我们求神，叫你们一件恶事都不做；这不是要显明我们是蒙悦纳的，是要你们行事端正，任凭人看我们是被弃绝的罢！'),
('CUV', '哥林多后书', 47, 13, 8, '我们凡事不能敌挡真理，只能扶助真理。'),
('CUV', '哥林多后书', 47, 13, 9, '即使我们软弱，你们刚强，我们也欢喜；并且我们所求的，就是你们作完全人。'),
('CUV', '哥林多后书', 47, 13, 10, '所以，我不在你们那里的时候，把这话写给你们，好叫我见你们的时候，不用照主所给我的权柄严厉的待你们；这权柄原是为造就人，并不是为败坏人。'),
('CUV', '哥林多后书', 47, 13, 11, '还有末了的话：愿弟兄们都喜乐。要作完全人；要受安慰；要同心合意；要彼此和睦。如此，仁爱和平的神必常与你们同在。'),
('CUV', '哥林多后书', 47, 13, 12, '你们亲嘴问安，彼此务要圣洁。'),
('CUV', '哥林多后书', 47, 13, 13, '众圣徒都问你们安。'),
('CUV', '哥林多后书', 47, 13, 14, '愿主耶稣基督的恩惠、神的慈爱、圣灵的感动，常与你们众人同在！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '加拉太书', 48, 1, 1, '作使徒的保罗（不是由于人，也不是藉著人，乃是藉著耶稣基督，与叫他从死里复活的父神）'),
('CUV', '加拉太书', 48, 1, 2, '和一切与我同在的众弟兄，写信给加拉太的各教会。'),
('CUV', '加拉太书', 48, 1, 3, '愿恩惠、平安从父神与我们的主耶稣基督归与你们！'),
('CUV', '加拉太书', 48, 1, 4, '基督照我们父神的旨意，为我们的罪舍己，要救我们脱离这罪恶的世代。'),
('CUV', '加拉太书', 48, 1, 5, '但愿荣耀归于神，直到永永远远。阿们！'),
('CUV', '加拉太书', 48, 1, 6, '我希奇你们这么快离开那藉著基督之恩召你们的，去从别的福音。'),
('CUV', '加拉太书', 48, 1, 7, '那并不是福音，不过有些人搅扰你们，要把基督的福音更改了。'),
('CUV', '加拉太书', 48, 1, 8, '但无论是我们，是天上来的使者，若传福音给你们，与我们所传给你们的不同，他就应当被咒诅。'),
('CUV', '加拉太书', 48, 1, 9, '我们已经说了，现在又说，若有人传福音给你们，与你们所领受的不同，他就应当被咒诅。'),
('CUV', '加拉太书', 48, 1, 10, '我现在是要得人的心呢？还是要得神的心呢？我岂是讨人的喜欢么？若仍旧讨人的喜欢，我就不是基督的仆人了。'),
('CUV', '加拉太书', 48, 1, 11, '弟兄们，我告诉你们，我素来所传的福音不是出于人的意思。'),
('CUV', '加拉太书', 48, 1, 12, '因为我不是从人领受的，也不是人教导我的，乃是从耶稣基督启示来的。'),
('CUV', '加拉太书', 48, 1, 13, '你们听见我从前在犹太教中所行的事，怎样极力逼迫残害神的教会。'),
('CUV', '加拉太书', 48, 1, 14, '我又在犹太教中，比我本国许多同岁的人更有长进，为我祖宗的遗传更加热心。'),
('CUV', '加拉太书', 48, 1, 15, '然而，那把我从母腹里分别出来、又施恩召我的神，'),
('CUV', '加拉太书', 48, 1, 16, '既然乐意将他儿子启示在我心里，叫我把他传在外邦人中，我就没有与属血气的人商量，'),
('CUV', '加拉太书', 48, 1, 17, '也没有上耶路撒冷去见那些比我先作使徒的，惟独往亚拉伯去，后又回到大马色。'),
('CUV', '加拉太书', 48, 1, 18, '过了三年，才上耶路撒冷去见矶法，和他同住了十五天。'),
('CUV', '加拉太书', 48, 1, 19, '至于别的使徒，除了主的兄弟雅各，我都没有看见。'),
('CUV', '加拉太书', 48, 1, 20, '我写给你们的不是谎话，这是我在神面前说的。'),
('CUV', '加拉太书', 48, 1, 21, '以后我到了叙利亚和基利家境内。'),
('CUV', '加拉太书', 48, 1, 22, '那时，犹太信基督的各教会都没有见过我的面。'),
('CUV', '加拉太书', 48, 1, 23, '不过听说那从前逼迫我们的，现在传扬他原先所残害的真道。'),
('CUV', '加拉太书', 48, 1, 24, '他们就为我的缘故，归荣耀给神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '加拉太书', 48, 2, 1, '过了十四年，我同巴拿巴又上耶路撒冷去，并带著提多同去。'),
('CUV', '加拉太书', 48, 2, 2, '我是奉启示上去的，把我在外邦人中所传的福音，对弟兄们陈说；却是背地里对那有名望之人说的，惟恐我现在，或是从前，徒然奔跑。'),
('CUV', '加拉太书', 48, 2, 3, '但与我同去的提多，虽是希利尼人，也没有勉强他受割礼；'),
('CUV', '加拉太书', 48, 2, 4, '因为有偷著引进来的假弟兄，私下窥探我们在基督耶稣里的自由，要叫我们作奴仆。'),
('CUV', '加拉太书', 48, 2, 5, '我们就是一刻的工夫也没有容让顺服他们，为要叫福音的真理仍存在你们中间。'),
('CUV', '加拉太书', 48, 2, 6, '至于那些有名望的，不论他是何等人，都与我无干。神不以外貌取人。那些有名望的，并没有加增我甚么，'),
('CUV', '加拉太书', 48, 2, 7, '反倒看见了主托我传福音给那未受割礼的人，正如托彼得传福音给那受割礼的人。'),
('CUV', '加拉太书', 48, 2, 8, '（那感动彼得、叫他为受割礼之人作使徒的，也感动我，叫我为外邦人作使徒；）'),
('CUV', '加拉太书', 48, 2, 9, '又知道所赐给我的恩典，那称为教会柱石的雅各、矶法、约翰，就向我和巴拿巴用右手行相交之礼，叫我们往外邦人那里去，他们往受割礼的人那里去。'),
('CUV', '加拉太书', 48, 2, 10, '只是愿意我们记念穷人；这也是我本来热心去行的。'),
('CUV', '加拉太书', 48, 2, 11, '后来，矶法到了安提阿；因他有可责之处，我就当面抵挡他。'),
('CUV', '加拉太书', 48, 2, 12, '从雅各那里来的人未到以先，他和外邦人一同吃饭，及至他们来到，他因怕奉割礼的人，就退去与外邦人隔开了。'),
('CUV', '加拉太书', 48, 2, 13, '其余的犹太人也都随著他装假，甚至连巴拿巴也随伙装假。'),
('CUV', '加拉太书', 48, 2, 14, '但我一看见他们行的不正，与福音的真理不合，就在众人面前对矶法说：你既是犹太人，若随外邦人行事，不随犹太人行事，怎么还勉强外邦人随犹太人呢？'),
('CUV', '加拉太书', 48, 2, 15, '我们这生来的犹太人，不是外邦的罪人；'),
('CUV', '加拉太书', 48, 2, 16, '既知道人称义不是因行律法，乃是因信耶稣基督，连我们也信了基督耶稣，使我们因信基督称义，不因行律法称义；因为凡有血气的，没有一人因行律法称义。'),
('CUV', '加拉太书', 48, 2, 17, '我们若求在基督里称义，却仍旧是罪人，难道基督是叫人犯罪的么？断乎不是！'),
('CUV', '加拉太书', 48, 2, 18, '我素来所拆毁的，若重新建造，这就证明自己是犯罪的人。'),
('CUV', '加拉太书', 48, 2, 19, '我因律法，就向律法死了，叫我可以向神活著。'),
('CUV', '加拉太书', 48, 2, 20, '我已经与基督同钉十字架，现在活著的不再是我，乃是基督在我里面活著；并且我如今在肉身活著，是因信神的儿子而活；他是爱我，为我舍己。'),
('CUV', '加拉太书', 48, 2, 21, '我不废掉神的恩；义若是藉著律法得的，基督就是徒然死了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '加拉太书', 48, 3, 1, '无知的加拉太人哪，耶稣基督钉十字架，已经活画在你们眼前，谁又迷惑了你们呢？'),
('CUV', '加拉太书', 48, 3, 2, '我只要问你们这一件：你们受了圣灵，是因行律法呢？是因听信福音呢？'),
('CUV', '加拉太书', 48, 3, 3, '你们既靠圣灵入门，如今还靠肉身成全么？你们是这样的无知么？'),
('CUV', '加拉太书', 48, 3, 4, '你们受苦如此之多，都是徒然的么？难道果真是徒然的么？'),
('CUV', '加拉太书', 48, 3, 5, '那赐给你们圣灵，又在你们中间行异能的，是因你们行律法呢？是因你们听信福音呢？'),
('CUV', '加拉太书', 48, 3, 6, '正如亚伯拉罕信神，这就算为他的义。'),
('CUV', '加拉太书', 48, 3, 7, '所以，你们要知道：那以信为本的人，就是亚伯拉罕的子孙。'),
('CUV', '加拉太书', 48, 3, 8, '并且圣经既然预先看明，神要叫外邦人因信称义，就早已传福音给亚伯拉罕，说：万国都必因你得福。'),
('CUV', '加拉太书', 48, 3, 9, '可见那以信为本的人和有信心的亚伯拉罕一同得福。'),
('CUV', '加拉太书', 48, 3, 10, '凡以行律法为本的，都是被咒诅的；因为经上记著：凡不常照律法书上所记一切之事去行的，就被咒诅。'),
('CUV', '加拉太书', 48, 3, 11, '没有一个人靠著律法在神面前称义，这是明显的；因为经上说，义人必因信得生。'),
('CUV', '加拉太书', 48, 3, 12, '律法原不本乎信，只说：行这些事的，就必因此活著。'),
('CUV', '加拉太书', 48, 3, 13, '基督既为我们受（原文是成）了咒诅，就赎出我们脱离律法的咒诅；因为经上记著：凡挂在木头上都是被咒诅的。'),
('CUV', '加拉太书', 48, 3, 14, '这便叫亚伯拉罕的福，因基督耶稣可以临到外邦人，使我们因信得著所应许的圣灵。'),
('CUV', '加拉太书', 48, 3, 15, '弟兄们，我且照著人的常话说：虽然是人的文约，若已经立定了，就没有能废弃或加增的。'),
('CUV', '加拉太书', 48, 3, 16, '所应许的原是向亚伯拉罕和他子孙说的。神并不是说众子孙，指著许多人，乃是说你那一个子孙，指著一个人，就是基督。'),
('CUV', '加拉太书', 48, 3, 17, '我是这么说，神预先所立的约，不能被那四百三十年以后的律法废掉，叫应许归于虚空。'),
('CUV', '加拉太书', 48, 3, 18, '因为承受产业，若本乎律法，就不本乎应许；但神是凭著应许把产业赐给亚伯拉罕。'),
('CUV', '加拉太书', 48, 3, 19, '这样说来，律法是为甚么有的呢？原是为过犯添上的，等候那蒙应许的子孙来到，并且是藉天使经中保之手设立的。'),
('CUV', '加拉太书', 48, 3, 20, '但中保本不是为一面作的；神却是一位。'),
('CUV', '加拉太书', 48, 3, 21, '这样，律法是与神的应许反对么？断乎不是！若曾传一个能叫人得生的律法，义就诚然本乎律法了。'),
('CUV', '加拉太书', 48, 3, 22, '但圣经把众人都圈在罪里，使所应许的福因信耶稣基督，归给那信的人。'),
('CUV', '加拉太书', 48, 3, 23, '但这因信得救的理还未来以先，我们被看守在律法之下，直圈到那将来的真道显明出来。'),
('CUV', '加拉太书', 48, 3, 24, '这样，律法是我们训蒙的师傅，引我们到基督那里，使我们因信称义。'),
('CUV', '加拉太书', 48, 3, 25, '但这因信得救的理既然来到，我们从此就不在师傅的手下了。'),
('CUV', '加拉太书', 48, 3, 26, '所以，你们因信基督耶稣都是神的儿子。'),
('CUV', '加拉太书', 48, 3, 27, '你们受洗归入基督的都是披戴基督了。'),
('CUV', '加拉太书', 48, 3, 28, '并不分犹太人、希利尼人，自主的、为奴的，或男或女，因为你们在基督耶稣里都成为一了。'),
('CUV', '加拉太书', 48, 3, 29, '你们既属乎基督，就是亚伯拉罕的后裔，是照著应许承受产业的了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '加拉太书', 48, 4, 1, '我说那承受产业的，虽然是全业的主人，但为孩童的时候却与奴仆毫无分别，'),
('CUV', '加拉太书', 48, 4, 2, '乃在师傅和管家的手下，直等他父亲预定的时候来到。'),
('CUV', '加拉太书', 48, 4, 3, '我们为孩童的时候，受管于世俗小学之下，也是如此。'),
('CUV', '加拉太书', 48, 4, 4, '及至时候满足，神就差遣他的儿子，为女子所生，且生在律法以下，'),
('CUV', '加拉太书', 48, 4, 5, '要把律法以下的人赎出来，叫我们得著儿子的名分。'),
('CUV', '加拉太书', 48, 4, 6, '你们既为儿子，神就差他儿子的灵进入你们（原文作我们）的心，呼叫：阿爸！父！'),
('CUV', '加拉太书', 48, 4, 7, '可见，从此以后，你不是奴仆，乃是儿子了；既是儿子，就靠著神为后嗣。'),
('CUV', '加拉太书', 48, 4, 8, '但从前你们不认识神的时候，是给那些本来不是神的作奴仆；'),
('CUV', '加拉太书', 48, 4, 9, '现在你们既然认识神，更可说是被神所认识的，怎么还要归回那懦弱无用的小学，情愿再给他作奴仆呢？'),
('CUV', '加拉太书', 48, 4, 10, '你们谨守日子、月分、节期、年分。'),
('CUV', '加拉太书', 48, 4, 11, '我为你们害怕、惟恐我在你们身上是枉费了工夫。'),
('CUV', '加拉太书', 48, 4, 12, '弟兄们，我劝你们要像我一样，因为我也像你们一样。你们一点没有亏负我。'),
('CUV', '加拉太书', 48, 4, 13, '你们知道我头一次传福音给你们，是因为身体有疾病。'),
('CUV', '加拉太书', 48, 4, 14, '你们为我身体的缘故受试炼，没有轻看我，也没有厌弃我，反倒接待我，如同神的使者，如同基督耶稣。'),
('CUV', '加拉太书', 48, 4, 15, '你们当日所夸的福气在那里呢？那时你们若能行，就是把自己的眼睛剜出来给我，也都情愿。这是我可以给你们作见证的。'),
('CUV', '加拉太书', 48, 4, 16, '如今我将真理告诉你们，就成了你们的仇敌么？'),
('CUV', '加拉太书', 48, 4, 17, '那些人热心待你们，却不是好意，是要离间你们（原文是把你们关在外面），叫你们热心待他们。'),
('CUV', '加拉太书', 48, 4, 18, '在善事上，常用热心待人原是好的，却不单我与你们同在的时候才这样。'),
('CUV', '加拉太书', 48, 4, 19, '我小子阿，我为你们再受生产之苦，直等到基督成形在你们心里。'),
('CUV', '加拉太书', 48, 4, 20, '我巴不得现今在你们那里，改换口气，因我为你们心里作难。'),
('CUV', '加拉太书', 48, 4, 21, '你们这愿意在律法以下的人，请告诉我，你们岂没有听见律法么？'),
('CUV', '加拉太书', 48, 4, 22, '因为律法上记著，亚伯拉罕有两个儿子，一个是使女生的，一个是自主之妇人生的。'),
('CUV', '加拉太书', 48, 4, 23, '然而，那使女所生的是按著血气生的；那自主之妇人所生的是凭著应许生的。'),
('CUV', '加拉太书', 48, 4, 24, '这都是比方：那两个妇人就是两约。一约是出于西乃山，生子为奴，乃是夏甲。'),
('CUV', '加拉太书', 48, 4, 25, '这夏甲二字是指著亚拉伯的西乃山，与现在的耶路撒冷同类，因耶路撒冷和他的儿女都是为奴的。'),
('CUV', '加拉太书', 48, 4, 26, '但那在上的耶路撒冷是自主的，他是我们的母。'),
('CUV', '加拉太书', 48, 4, 27, '因为经上记著：不怀孕、不生养的，你要欢乐；未曾经过产难的，你要高声欢呼；因为没有丈夫的，比有丈夫的儿女更多。'),
('CUV', '加拉太书', 48, 4, 28, '弟兄们，我们是凭著应许作儿女，如同以撒一样。'),
('CUV', '加拉太书', 48, 4, 29, '当时，那按著血气生的逼迫了那按著圣灵生的，现在也是这样。'),
('CUV', '加拉太书', 48, 4, 30, '然而经上是怎么说的呢？是说：把使女和他儿子赶出去！因为使女的儿子不可与自主妇人的儿子一同承受产业。'),
('CUV', '加拉太书', 48, 4, 31, '弟兄们，这样看来，我们不是使女的儿女，乃是自主妇人的儿女了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '加拉太书', 48, 5, 1, '基督释放了我们，叫我们得以自由。所以要站立得稳，不要再被奴仆的轭挟制。'),
('CUV', '加拉太书', 48, 5, 2, '我保罗告诉你们，若受割礼，基督就与你们无益了。'),
('CUV', '加拉太书', 48, 5, 3, '我再指著凡受割礼的人确实的说，他是欠著行全律法的债。'),
('CUV', '加拉太书', 48, 5, 4, '你们这要靠律法称义的，是与基督隔绝，从恩典中坠落了。'),
('CUV', '加拉太书', 48, 5, 5, '我们靠著圣灵，凭著信心，等候所盼望的义。'),
('CUV', '加拉太书', 48, 5, 6, '原来在基督耶稣里，受割礼不受割礼全无功效，惟独使人生发仁爱的信心才有功效。'),
('CUV', '加拉太书', 48, 5, 7, '你们向来跑得好，有谁拦阻你们，叫你们不顺从真理呢？'),
('CUV', '加拉太书', 48, 5, 8, '这样的劝导不是出于那召你们的。'),
('CUV', '加拉太书', 48, 5, 9, '一点面酵能使全团都发起来。'),
('CUV', '加拉太书', 48, 5, 10, '我在主里很信你们必不怀别样的心；但搅扰你们的，无论是谁，必担当他的罪名。'),
('CUV', '加拉太书', 48, 5, 11, '弟兄们，我若仍旧传割礼，为甚么还受逼迫呢？若是这样，那十字架讨厌的地方就没有了。'),
('CUV', '加拉太书', 48, 5, 12, '恨不得那搅乱你们的人把自己割绝了。'),
('CUV', '加拉太书', 48, 5, 13, '弟兄们，你们蒙召是要得自由，只是不可将你们的自由当作放纵情欲的机会，总要用爱心互相服事。'),
('CUV', '加拉太书', 48, 5, 14, '因为全律法都包在「爱人如己」这一句话之内了。'),
('CUV', '加拉太书', 48, 5, 15, '你们要谨慎，若相咬相吞，只怕要彼此消灭了。'),
('CUV', '加拉太书', 48, 5, 16, '我说，你们当顺著圣灵而行，就不放纵肉体的情欲了。'),
('CUV', '加拉太书', 48, 5, 17, '因为情欲和圣灵相争，圣灵和情欲相争，这两个是彼此相敌，使你们不能做所愿意做的。'),
('CUV', '加拉太书', 48, 5, 18, '但你们若被圣灵引导，就不在律法以下。'),
('CUV', '加拉太书', 48, 5, 19, '情欲的事都是显而易见的，就如奸淫、污秽、邪荡、'),
('CUV', '加拉太书', 48, 5, 20, '拜偶像、邪术、仇恨、争竞、忌恨、恼怒、结党、纷争、异端、'),
('CUV', '加拉太书', 48, 5, 21, '嫉妒（有古卷在此有：凶杀二字）、醉酒、荒宴等类。我从前告诉你们，现在又告诉你们，行这样事的人必不能承受神的国。'),
('CUV', '加拉太书', 48, 5, 22, '圣灵所结的果子，就是仁爱、喜乐、和平、忍耐、恩慈、良善、信实、'),
('CUV', '加拉太书', 48, 5, 23, '温柔、节制。这样的事没有律法禁止。'),
('CUV', '加拉太书', 48, 5, 24, '凡属基督耶稣的人，是已经把肉体连肉体的邪情私欲同钉在十字架上了。'),
('CUV', '加拉太书', 48, 5, 25, '我们若是靠圣灵得生，就当靠圣灵行事。'),
('CUV', '加拉太书', 48, 5, 26, '不要贪图虚名，彼此惹气，互相嫉妒。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '加拉太书', 48, 6, 1, '弟兄们，若有人偶然被过犯所胜，你们属灵的人就当用温柔的心把他挽回过来；又当自己小心，恐怕也被引诱。'),
('CUV', '加拉太书', 48, 6, 2, '你们各人的重担要互相担当，如此，就完全了基督的律法。'),
('CUV', '加拉太书', 48, 6, 3, '人若无有，自己还以为有，就是自欺了。'),
('CUV', '加拉太书', 48, 6, 4, '各人应当察验自己的行为；这样，他所夸的就专在自己，不在别人了，'),
('CUV', '加拉太书', 48, 6, 5, '因为各人必担当自己的担子。'),
('CUV', '加拉太书', 48, 6, 6, '在道理上受教的，当把一切需用的供给施教的人。'),
('CUV', '加拉太书', 48, 6, 7, '不要自欺，神是轻慢不得的。人种的是甚么，收的也是甚么。'),
('CUV', '加拉太书', 48, 6, 8, '顺著情欲撒种的，必从情欲收败坏；顺著圣灵撒种的，必从圣灵收永生。'),
('CUV', '加拉太书', 48, 6, 9, '我们行善，不可丧志；若不灰心，到了时候就要收成。'),
('CUV', '加拉太书', 48, 6, 10, '所以，有了机会就当向众人行善，向信徒一家的人更当这样。'),
('CUV', '加拉太书', 48, 6, 11, '请看我亲手写给你们的字是何等的大呢！'),
('CUV', '加拉太书', 48, 6, 12, '凡希图外貌体面的人都勉强你们受割礼，无非是怕自己为基督的十字架受逼迫。'),
('CUV', '加拉太书', 48, 6, 13, '他们那些受割礼的，连自己也不守律法；他们愿意你们受割礼，不过要藉著你们的肉体夸口。'),
('CUV', '加拉太书', 48, 6, 14, '但我断不以别的夸口，只夸我们主耶稣基督的十字架；因这十字架，就我而论，世界已经钉在十字架上；就世界而论，我已经钉在十字架上。'),
('CUV', '加拉太书', 48, 6, 15, '受割礼不受割礼都无关紧要，要紧的就是作新造的人。'),
('CUV', '加拉太书', 48, 6, 16, '凡照此理而行的，愿平安、怜悯加给他们，和神的以色列民。'),
('CUV', '加拉太书', 48, 6, 17, '从今以后，人都不要搅扰我，因为我身上带著耶稣的印记。'),
('CUV', '加拉太书', 48, 6, 18, '弟兄们，愿我主耶稣基督的恩常在你们心里。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以弗所书', 49, 1, 1, '奉神旨意，作基督耶稣使徒的保罗，写信给在以弗所的圣徒，就是在基督耶稣里有忠心的人。'),
('CUV', '以弗所书', 49, 1, 2, '愿恩惠、平安从神我们的父和主耶稣基督归与你们！'),
('CUV', '以弗所书', 49, 1, 3, '愿颂赞归与我们主耶稣基督的父神！他在基督里曾赐给我们天上各样属灵的福气：'),
('CUV', '以弗所书', 49, 1, 4, '就如神从创立世界以前，在基督里拣选了我们，使我们在他面前成为圣洁，无有瑕疵；'),
('CUV', '以弗所书', 49, 1, 5, '又因爱我们，就按著自己意旨所喜悦的，预定我们藉著耶稣基督得儿子的名分，'),
('CUV', '以弗所书', 49, 1, 6, '使他荣耀的恩典得著称赞；这恩典是他在爱子里所赐给我们的。'),
('CUV', '以弗所书', 49, 1, 7, '我们藉这爱子的血得蒙救赎，过犯得以赦免，乃是照他丰富的恩典。'),
('CUV', '以弗所书', 49, 1, 8, '这恩典是神用诸般智慧聪明，充充足足赏给我们的；'),
('CUV', '以弗所书', 49, 1, 9, '都是照他自己所预定的美意，叫我们知道他旨意的奥秘，'),
('CUV', '以弗所书', 49, 1, 10, '要照所安排的，在日期满足的时候，使天上、地上、一切所有的都在基督里面同归于一。'),
('CUV', '以弗所书', 49, 1, 11, '我们也在他里面得（或作：成）了基业；这原是那位随己意行、做万事的，照著他旨意所预定的，'),
('CUV', '以弗所书', 49, 1, 12, '叫他的荣耀从我们这首先在基督里有盼望的人可以得著称赞。'),
('CUV', '以弗所书', 49, 1, 13, '你们既听见真理的道，就是那叫你们得救的福音，也信了基督，既然信他，就受了所应许的圣灵为印记。'),
('CUV', '以弗所书', 49, 1, 14, '这圣灵是我们得基业的凭据（原文作：质），直等到神之民（原文作：产业）被赎，使他的荣耀得著称赞。'),
('CUV', '以弗所书', 49, 1, 15, '因此，我既听见你们信从主耶稣，亲爱众圣徒，'),
('CUV', '以弗所书', 49, 1, 16, '就为你们不住的感谢神。祷告的时候，常题到你们，'),
('CUV', '以弗所书', 49, 1, 17, '求我们主耶稣基督的神，荣耀的父，将那赐人智慧和启示的灵赏给你们，使你们真知道他，'),
('CUV', '以弗所书', 49, 1, 18, '并且照明你们心中的眼睛，使你们知道他的恩召有何等指望，他在圣徒中得的基业有何等丰盛的荣耀；'),
('CUV', '以弗所书', 49, 1, 19, '并知道他向我们这信的人所显的能力是何等浩大，'),
('CUV', '以弗所书', 49, 1, 20, '就是照他在基督身上所运行的大能大力，使他从死里复活，叫他在天上坐在自己的右边，'),
('CUV', '以弗所书', 49, 1, 21, '远超过一切执政的、掌权的、有能的、主治的，和一切有名的；不但是今世的，连来世的也都超过了。'),
('CUV', '以弗所书', 49, 1, 22, '又将万有服在他的脚下，使他为教会作万有之首。'),
('CUV', '以弗所书', 49, 1, 23, '教会是他的身体，是那充满万有者所充满的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以弗所书', 49, 2, 1, '你们死在过犯罪恶之中，他叫你们活过来。'),
('CUV', '以弗所书', 49, 2, 2, '那时，你们在其中行事为人，随从今世的风俗，顺服空中掌权者的首领，就是现今在悖逆之子心中运行的邪灵。'),
('CUV', '以弗所书', 49, 2, 3, '我们从前也都在他们中间，放纵肉体的私欲，随著肉体和心中所喜好的去行，本为可怒之子，和别人一样。'),
('CUV', '以弗所书', 49, 2, 4, '然而，神既有丰富的怜悯，因他爱我们的大爱，'),
('CUV', '以弗所书', 49, 2, 5, '当我们死在过犯中的时候，便叫我们与基督一同活过来。你们得救是本乎恩。'),
('CUV', '以弗所书', 49, 2, 6, '他又叫我们与基督耶稣一同复活，一同坐在天上，'),
('CUV', '以弗所书', 49, 2, 7, '要将他极丰富的恩典，就是他在基督耶稣里向我们所施的恩慈，显明给后来的世代看。'),
('CUV', '以弗所书', 49, 2, 8, '你们得救是本乎恩，也因著信；这并不是出于自己，乃是神所赐的；'),
('CUV', '以弗所书', 49, 2, 9, '也不是出于行为，免得有人自夸。'),
('CUV', '以弗所书', 49, 2, 10, '我们原是他的工作，在基督耶稣里造成的，为要叫我们行善，就是神所预备叫我们行的。'),
('CUV', '以弗所书', 49, 2, 11, '所以你们应当记念：你们从前按肉体是外邦人，是称为没受割礼的；这名原是那些凭人手在肉身上称为受割礼之人所起的。'),
('CUV', '以弗所书', 49, 2, 12, '那时，你们与基督无关，在以色列国民以外，在所应许的诸约上是局外人，并且活在世上没有指望，没有神。'),
('CUV', '以弗所书', 49, 2, 13, '你们从前远离神的人，如今却在基督耶稣里，靠著他的血，已经得亲近了。'),
('CUV', '以弗所书', 49, 2, 14, '因他使我们和睦（原文作：因他是我们的和睦），将两下合而为一，拆毁了中间隔断的墙；'),
('CUV', '以弗所书', 49, 2, 15, '而且以自己的身体废掉冤仇，就是那记在律法上的规条，为要将两下藉著自己造成一个新人，如此便成就了和睦。'),
('CUV', '以弗所书', 49, 2, 16, '既在十字架上灭了冤仇，便藉这十字架使两下归为一体，与神和好了，'),
('CUV', '以弗所书', 49, 2, 17, '并且来传和平的福音给你们远处的人，也给那近处的人。'),
('CUV', '以弗所书', 49, 2, 18, '因为我们两下藉著他被一个圣灵所感，得以进到父面前。'),
('CUV', '以弗所书', 49, 2, 19, '这样，你们不再作外人和客旅，是与圣徒同国，是神家里的人了；'),
('CUV', '以弗所书', 49, 2, 20, '并且被建造在使徒和先知的根基上，有基督耶稣自己为房角石，'),
('CUV', '以弗所书', 49, 2, 21, '各（或作：全）房靠他联络得合式，渐渐成为主的圣殿。'),
('CUV', '以弗所书', 49, 2, 22, '你们也靠他同被建造，成为神藉著圣灵居住的所在。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以弗所书', 49, 3, 1, '因此，我─保罗为你们外邦人作了基督耶稣被囚的，替你们祈祷（此句乃照对十四节所加）。'),
('CUV', '以弗所书', 49, 3, 2, '谅必你们曾听见神赐恩给我，将关切你们的职分托付我，'),
('CUV', '以弗所书', 49, 3, 3, '用启示使我知道福音的奥秘，正如我以前略略写过的。'),
('CUV', '以弗所书', 49, 3, 4, '你们念了，就能晓得我深知基督的奥秘。'),
('CUV', '以弗所书', 49, 3, 5, '这奥秘在以前的世代没有叫人知道，像如今藉著圣灵启示他的圣使徒和先知一样。'),
('CUV', '以弗所书', 49, 3, 6, '这奥秘就是外邦人在基督耶稣里，藉著福音，得以同为后嗣，同为一体，同蒙应许。'),
('CUV', '以弗所书', 49, 3, 7, '我作了这福音的执事，是照神的恩赐，这恩赐是照他运行的大能赐给我的。'),
('CUV', '以弗所书', 49, 3, 8, '我本来比众圣徒中最小的还小，然而他还赐我这恩典，叫我把基督那测不透的丰富传给外邦人，'),
('CUV', '以弗所书', 49, 3, 9, '又使众人都明白，这历代以来隐藏在创造万物之神里的奥秘是如何安排的，'),
('CUV', '以弗所书', 49, 3, 10, '为要藉著教会使天上执政的、掌权的，现在得知神百般的智慧。'),
('CUV', '以弗所书', 49, 3, 11, '这是照神从万世以前，在我们主基督耶稣里所定的旨意。'),
('CUV', '以弗所书', 49, 3, 12, '我们因信耶稣，就在他里面放胆无惧，笃信不疑的来到神面前。'),
('CUV', '以弗所书', 49, 3, 13, '所以，我求你们不要因我为你们所受的患难丧胆，这原是你们的荣耀。'),
('CUV', '以弗所书', 49, 3, 14, '因此，我在父面前屈膝，'),
('CUV', '以弗所书', 49, 3, 15, '（天上地上的各（或作：全）家，都是从他得名。）'),
('CUV', '以弗所书', 49, 3, 16, '求他按著他丰盛的荣耀，藉著他的灵，叫你们心里的力量刚强起来，'),
('CUV', '以弗所书', 49, 3, 17, '使基督因你们的信，住在你们心里，叫你们的爱心有根有基，'),
('CUV', '以弗所书', 49, 3, 18, '能以和众圣徒一同明白基督的爱是何等长阔高深，'),
('CUV', '以弗所书', 49, 3, 19, '并知道这爱是过于人所能测度的，便叫神一切所充满的，充满了你们。'),
('CUV', '以弗所书', 49, 3, 20, '神能照著运行在我们心里的大力充充足足的成就一切，超过我们所求所想的。'),
('CUV', '以弗所书', 49, 3, 21, '但愿他在教会中，并在基督耶稣里，得著荣耀，直到世世代代，永永远远。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以弗所书', 49, 4, 1, '我为主被囚的劝你们：既然蒙召，行事为人就当与蒙召的恩相称。'),
('CUV', '以弗所书', 49, 4, 2, '凡事谦虚、温柔、忍耐，用爱心互相宽容，'),
('CUV', '以弗所书', 49, 4, 3, '用和平彼此联络，竭力保守圣灵所赐合而为一的心。'),
('CUV', '以弗所书', 49, 4, 4, '身体只有一个，圣灵只有一个，正如你们蒙召同有一个指望。'),
('CUV', '以弗所书', 49, 4, 5, '一主，一信，一洗，'),
('CUV', '以弗所书', 49, 4, 6, '一神，就是众人的父，超乎众人之上，贯乎众人之中，也住在众人之内。'),
('CUV', '以弗所书', 49, 4, 7, '我们各人蒙恩，都是照基督所量给各人的恩赐。'),
('CUV', '以弗所书', 49, 4, 8, '所以经上说：他升上高天的时候，掳掠了仇敌，将各样的恩赐赏给人。'),
('CUV', '以弗所书', 49, 4, 9, '（既说升上，岂不是先降在地下么？'),
('CUV', '以弗所书', 49, 4, 10, '那降下的，就是远升诸天之上要充满万有的。）'),
('CUV', '以弗所书', 49, 4, 11, '他所赐的，有使徒，有先知，有传福音的，有牧师和教师，'),
('CUV', '以弗所书', 49, 4, 12, '为要成全圣徒，各尽其职，建立基督的身体，'),
('CUV', '以弗所书', 49, 4, 13, '直等到我们众人在真道上同归于一，认识神的儿子，得以长大成人，满有基督长成的身量，'),
('CUV', '以弗所书', 49, 4, 14, '使我们不再作小孩子，中了人的诡计和欺骗的法术，被一切异教之风摇动，飘来飘去，就随从各样的异端；'),
('CUV', '以弗所书', 49, 4, 15, '惟用爱心说诚实话，凡事长进，连于元首基督，'),
('CUV', '以弗所书', 49, 4, 16, '全身都靠他联络得合式，百节各按各职，照著各体的功用彼此相助，便叫身体渐渐增长，在爱中建立自己。'),
('CUV', '以弗所书', 49, 4, 17, '所以我说，且在主里确实的说，你们行事不要再像外邦人存虚妄的心行事。'),
('CUV', '以弗所书', 49, 4, 18, '他们心地昏昧，与神所赐的生命隔绝了，都因自己无知，心里刚硬；'),
('CUV', '以弗所书', 49, 4, 19, '良心既然丧尽，就放纵私欲，贪行种种的污秽。'),
('CUV', '以弗所书', 49, 4, 20, '你们学了基督，却不是这样。'),
('CUV', '以弗所书', 49, 4, 21, '如果你们听过他的道，领了他的教，学了他的真理，'),
('CUV', '以弗所书', 49, 4, 22, '就要脱去你们从前行为上的旧人，这旧人是因私欲的迷惑渐渐变坏的；'),
('CUV', '以弗所书', 49, 4, 23, '又要将你们的心志改换一新，'),
('CUV', '以弗所书', 49, 4, 24, '并且穿上新人；这新人是照著神的形像造的，有真理的仁义和圣洁。'),
('CUV', '以弗所书', 49, 4, 25, '所以你们要弃绝谎言，各人与邻舍说实话，因为我们是互相为肢体。'),
('CUV', '以弗所书', 49, 4, 26, '生气却不要犯罪；不可含怒到日落，'),
('CUV', '以弗所书', 49, 4, 27, '也不可给魔鬼留地步。'),
('CUV', '以弗所书', 49, 4, 28, '从前偷窃的，不要再偷；总要劳力，亲手做正经事，就可有余分给那缺少的人。'),
('CUV', '以弗所书', 49, 4, 29, '污秽的言语一句不可出口，只要随事说造就人的好话，叫听见的人得益处。'),
('CUV', '以弗所书', 49, 4, 30, '不要叫神的圣灵担忧；你们原是受了他的印记，等候得赎的日子来到。'),
('CUV', '以弗所书', 49, 4, 31, '一切苦毒、恼恨、忿怒、嚷闹、毁谤，并一切的恶毒（或作：阴毒），都当从你们中间除掉；'),
('CUV', '以弗所书', 49, 4, 32, '并要以恩慈相待，存怜悯的心，彼此饶恕，正如神在基督里饶恕了你们一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以弗所书', 49, 5, 1, '所以，你们该效法神，好像蒙慈爱的儿女一样。'),
('CUV', '以弗所书', 49, 5, 2, '也要凭爱心行事，正如基督爱我们，为我们舍了自己，当作馨香的供物和祭物，献与神。'),
('CUV', '以弗所书', 49, 5, 3, '至于淫乱并一切污秽，或是贪婪，在你们中间连题都不可，方合圣徒的体统。'),
('CUV', '以弗所书', 49, 5, 4, '淫词、妄语，和戏笑的话都不相宜；总要说感谢的话。'),
('CUV', '以弗所书', 49, 5, 5, '因为你们确实的知道，无论是淫乱的，是污秽的，是有贪心的，在基督和神的国里都是无分的。有贪心的，就与拜偶像的一样。'),
('CUV', '以弗所书', 49, 5, 6, '不要被人虚浮的话欺哄；因这些事，神的忿怒必临到那悖逆之子。'),
('CUV', '以弗所书', 49, 5, 7, '所以，你们不要与他们同伙。'),
('CUV', '以弗所书', 49, 5, 8, '从前你们是暗昧的，但如今在主里面是光明的，行事为人就当像光明的子女。'),
('CUV', '以弗所书', 49, 5, 9, '光明所结的果子就是一切良善、公义、诚实。'),
('CUV', '以弗所书', 49, 5, 10, '总要察验何为主所喜悦的事。'),
('CUV', '以弗所书', 49, 5, 11, '那暗昧无益的事，不要与人同行，倒要责备行这事的人；'),
('CUV', '以弗所书', 49, 5, 12, '因为他们暗中所行的，就是题起来也是可耻的。'),
('CUV', '以弗所书', 49, 5, 13, '凡事受了责备，就被光显明出来，因为一切能显明的就是光。'),
('CUV', '以弗所书', 49, 5, 14, '所以主说：你这睡著的人当醒过来，从死里复活！基督就要光照你了。'),
('CUV', '以弗所书', 49, 5, 15, '你们要谨慎行事，不要像愚昧人，当像智慧人。'),
('CUV', '以弗所书', 49, 5, 16, '要爱惜光阴，因为现今的世代邪恶。'),
('CUV', '以弗所书', 49, 5, 17, '不要作糊涂人，要明白主的旨意如何。'),
('CUV', '以弗所书', 49, 5, 18, '不要醉酒，酒能使人放荡；乃要被圣灵充满。'),
('CUV', '以弗所书', 49, 5, 19, '当用诗章、颂词、灵歌、彼此对说，口唱心和的赞美主。'),
('CUV', '以弗所书', 49, 5, 20, '凡事要奉我们主耶稣基督的名常常感谢父神。'),
('CUV', '以弗所书', 49, 5, 21, '又当存敬畏基督的心，彼此顺服。'),
('CUV', '以弗所书', 49, 5, 22, '你们作妻子的，当顺服自己的丈夫，如同顺服主。'),
('CUV', '以弗所书', 49, 5, 23, '因为丈夫是妻子的头，如同基督是教会的头；他又是教会全体的救主。'),
('CUV', '以弗所书', 49, 5, 24, '教会怎样顺服基督，妻子也要怎样凡事顺服丈夫。'),
('CUV', '以弗所书', 49, 5, 25, '你们作丈夫的，要爱你们的妻子，正如基督爱教会，为教会舍己。'),
('CUV', '以弗所书', 49, 5, 26, '要用水藉著道把教会洗净，成为圣洁，'),
('CUV', '以弗所书', 49, 5, 27, '可以献给自己，作个荣耀的教会，毫无玷污、皱纹等类的病，乃是圣洁没有瑕疵的。'),
('CUV', '以弗所书', 49, 5, 28, '丈夫也当照样爱妻子，如同爱自己的身子；爱妻子便是爱自己了。'),
('CUV', '以弗所书', 49, 5, 29, '从来没有人恨恶自己的身子，总是保养顾惜，正像基督待教会一样，'),
('CUV', '以弗所书', 49, 5, 30, '因我们是他身上的肢体（有古卷在此有：就是他的骨他的肉）。'),
('CUV', '以弗所书', 49, 5, 31, '为这个缘故，人要离开父母，与妻子连合，二人成为一体。'),
('CUV', '以弗所书', 49, 5, 32, '这是极大的奥秘，但我是指著基督和教会说的。'),
('CUV', '以弗所书', 49, 5, 33, '然而，你们各人都当爱妻子，如同爱自己一样。妻子也当敬重他的丈夫。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以弗所书', 49, 6, 1, '你们作儿女的，要在主里听从父母，这是理所当然的。'),
('CUV', '以弗所书', 49, 6, 2, '要孝敬父母，使你得福，在世长寿。这是第一条带应许的诫命。'),
('CUV', '以弗所书', 49, 6, 3, 'a'),
('CUV', '以弗所书', 49, 6, 4, '你们作父亲的，不要惹儿女的气，只要照著主的教训和警戒养育他们。'),
('CUV', '以弗所书', 49, 6, 5, '你们作仆人的，要惧怕战兢，用诚实的心听从你们肉身的主人，好像听从基督一般。'),
('CUV', '以弗所书', 49, 6, 6, '不要只在眼前事奉，像是讨人喜欢的，要像基督的仆人，从心里遵行神的旨意。'),
('CUV', '以弗所书', 49, 6, 7, '甘心事奉，好像服事主，不像服事人。'),
('CUV', '以弗所书', 49, 6, 8, '因为晓得各人所行的善事，不论是为奴的，是自主的，都必按所行的得主的赏赐。'),
('CUV', '以弗所书', 49, 6, 9, '你们作主人的，待仆人也是一理，不要威吓他们。因为知道，他们和你们同有一位主在天上；他并不偏待人。'),
('CUV', '以弗所书', 49, 6, 10, '我还有末了的话：你们要靠著主，倚赖他的大能大力作刚强的人。'),
('CUV', '以弗所书', 49, 6, 11, '要穿戴神所赐的全副军装，就能抵挡魔鬼的诡计。'),
('CUV', '以弗所书', 49, 6, 12, '因我们并不是与属血气的争战（原文作摔跤；下同），乃是与那些执政的、掌权的、管辖这幽暗世界的，以及天空属灵气的恶魔争战。'),
('CUV', '以弗所书', 49, 6, 13, '所以，要拿起神所赐的全副军装，好在磨难的日子抵挡仇敌，并且成就了一切，还能站立得住。'),
('CUV', '以弗所书', 49, 6, 14, '所以要站稳了，用真理当作带子束腰，用公义当作护心镜遮胸，'),
('CUV', '以弗所书', 49, 6, 15, '又用平安的福音当作预备走路的鞋穿在脚上。'),
('CUV', '以弗所书', 49, 6, 16, '此外，又拿著信德当作籐牌，可以灭尽那恶者一切的火箭；'),
('CUV', '以弗所书', 49, 6, 17, '并戴上救恩的头盔，拿著圣灵的宝剑，就是神的道；'),
('CUV', '以弗所书', 49, 6, 18, '靠著圣灵，随时多方祷告祈求；并要在此儆醒不倦，为众圣徒祈求，'),
('CUV', '以弗所书', 49, 6, 19, '也为我祈求，使我得著口才，能以放胆开口讲明福音的奥秘，'),
('CUV', '以弗所书', 49, 6, 20, '我为这福音的奥秘作了带锁链的使者，并使我照著当尽的本分放胆讲论。'),
('CUV', '以弗所书', 49, 6, 21, '今有所亲爱、忠心事奉主的兄弟推基古，他要把我的事情，并我的景况如何全告诉你们，叫你们知道。'),
('CUV', '以弗所书', 49, 6, 22, '我特意打发他到你们那里去，好叫你们知道我们的光景，又叫他安慰你们的心。'),
('CUV', '以弗所书', 49, 6, 23, '愿平安、仁爱、信心、从父神和主耶稣基督归与弟兄们！'),
('CUV', '以弗所书', 49, 6, 24, '并愿所有诚心爱我们主耶稣基督的人都蒙恩惠！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '腓立比书', 50, 1, 1, '基督耶稣的仆人保罗和提摩太写信给凡住腓立比、在基督耶稣里的众圣徒，和诸位监督，诸位执事。'),
('CUV', '腓立比书', 50, 1, 2, '愿恩惠、平安从神我们的父并主耶稣基督归与你们！'),
('CUV', '腓立比书', 50, 1, 3, '我每逢想念你们，就感谢我的神；'),
('CUV', '腓立比书', 50, 1, 4, '每逢为你们众人祈求的时候，常是欢欢喜喜的祈求。'),
('CUV', '腓立比书', 50, 1, 5, '因为从头一天直到如今，你们是同心合意的兴旺福音。'),
('CUV', '腓立比书', 50, 1, 6, '我深信那在你们心里动了善工的，必成全这工，直到耶稣基督的日子。'),
('CUV', '腓立比书', 50, 1, 7, '我为你们众人有这样的意念，原是应当的；因你们常在我心里，无论我是在捆锁之中，是辩明证实福音的时候，你们都与我一同得恩。'),
('CUV', '腓立比书', 50, 1, 8, '我体会基督耶稣的心肠，切切的想念你们众人；这是神可以给我作见证的。'),
('CUV', '腓立比书', 50, 1, 9, '我所祷告的，就是要你们的爱心在知识和各样见识上多而又多，'),
('CUV', '腓立比书', 50, 1, 10, '使你们能分别是非（或作：喜爱那美好的事），作诚实无过的人，直到基督的日子；'),
('CUV', '腓立比书', 50, 1, 11, '并靠著耶稣基督结满了仁义的果子，叫荣耀称赞归与神。'),
('CUV', '腓立比书', 50, 1, 12, '弟兄们，我愿意你们知道，我所遭遇的事更是叫福音兴旺，'),
('CUV', '腓立比书', 50, 1, 13, '以致我受的捆锁在御营全军和其余的人中，已经显明是为基督的缘故。'),
('CUV', '腓立比书', 50, 1, 14, '并且那在主里的弟兄多半因我受的捆锁就笃信不疑，越发放胆传神的道，无所惧怕。'),
('CUV', '腓立比书', 50, 1, 15, '有的传基督是出于嫉妒纷争，也有的是出于好意。'),
('CUV', '腓立比书', 50, 1, 16, '这一等是出于爱心，知道我是为辩明福音设立的；'),
('CUV', '腓立比书', 50, 1, 17, '那一等传基督是出于结党，并不诚实，意思要加增我捆锁的苦楚。'),
('CUV', '腓立比书', 50, 1, 18, '这有何妨呢？或是假意，或是真心，无论怎样，基督究竟被传开了。为此，我就欢喜，并且还要欢喜；'),
('CUV', '腓立比书', 50, 1, 19, '因为我知道，这事藉著你们的祈祷和耶稣基督之灵的帮助，终必叫我得救。'),
('CUV', '腓立比书', 50, 1, 20, '照著我所切慕、所盼望的，没有一事叫我羞愧。只要凡事放胆，无论是生是死，总叫基督在我身上照常显大。'),
('CUV', '腓立比书', 50, 1, 21, '因我活著就是基督，我死了就有益处。'),
('CUV', '腓立比书', 50, 1, 22, '但我在肉身活著，若成就我工夫的果子，我就不知道该挑选甚么。'),
('CUV', '腓立比书', 50, 1, 23, '我正在两难之间，情愿离世与基督同在，因为这是好得无比的。'),
('CUV', '腓立比书', 50, 1, 24, '然而，我在肉身活著，为你们更是要紧的。'),
('CUV', '腓立比书', 50, 1, 25, '我既然这样深信，就知道仍要住在世间，且与你们众人同住，使你们在所信的道上又长进又喜乐，'),
('CUV', '腓立比书', 50, 1, 26, '叫你们在基督耶稣里的欢乐，因我再到你们那里去，就越发加增。'),
('CUV', '腓立比书', 50, 1, 27, '只要你们行事为人与基督的福音相称，叫我或来见你们，或不在你们那里，可以听见你们的景况，知道你们同有一个心志，站立得稳，为所信的福音齐心努力。'),
('CUV', '腓立比书', 50, 1, 28, '凡事不怕敌人的惊吓，这是证明他们沉沦，你们得救都是出于神。'),
('CUV', '腓立比书', 50, 1, 29, '因为你们蒙恩，不但得以信服基督，并要为他受苦。'),
('CUV', '腓立比书', 50, 1, 30, '你们的争战，就与你们在我身上从前所看见、现在所听见的一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '腓立比书', 50, 2, 1, '所以，在基督里若有甚么劝勉，爱心有甚么安慰，圣灵有甚么交通，心中有甚么慈悲怜悯，'),
('CUV', '腓立比书', 50, 2, 2, '你们就要意念相同，爱心相同，有一样的心思，有一样的意念，使我的喜乐可以满足。'),
('CUV', '腓立比书', 50, 2, 3, '凡事不可结党，不可贪图虚浮的荣耀；只要存心谦卑，各人看别人比自己强。'),
('CUV', '腓立比书', 50, 2, 4, '各人不要单顾自己的事，也要顾别人的事。'),
('CUV', '腓立比书', 50, 2, 5, '你们当以基督耶稣的心为心：'),
('CUV', '腓立比书', 50, 2, 6, '他本有神的形像，不以自己与神同等为强夺的；'),
('CUV', '腓立比书', 50, 2, 7, '反倒虚己，取了奴仆的形像，成为人的样式；'),
('CUV', '腓立比书', 50, 2, 8, '既有人的样子，就自己卑微，存心顺服，以至于死，且死在十字架上。'),
('CUV', '腓立比书', 50, 2, 9, '所以，神将他升为至高，又赐给他那超乎万名之上的名，'),
('CUV', '腓立比书', 50, 2, 10, '叫一切在天上的、地上的，和地底下的，因耶稣的名无不屈膝，'),
('CUV', '腓立比书', 50, 2, 11, '无不口称耶稣基督为主，使荣耀归与父神。'),
('CUV', '腓立比书', 50, 2, 12, '这样看来，我亲爱的弟兄，你们既是常顺服的，不但我在你们那里，就是我如今不在你们那里，更是顺服的，就当恐惧战兢做成你们得救的工夫。'),
('CUV', '腓立比书', 50, 2, 13, '因为你们立志行事都是神在你们心里运行，为要成就他的美意。'),
('CUV', '腓立比书', 50, 2, 14, '凡所行的，都不要发怨言，起争论，'),
('CUV', '腓立比书', 50, 2, 15, '使你们无可指摘，诚实无伪，在这弯曲悖谬的世代作神无瑕疵的儿女。你们显在这世代中，好像明光照耀，'),
('CUV', '腓立比书', 50, 2, 16, '将生命的道表明出来，叫我在基督的日子好夸我没有空跑，也没有徒劳。'),
('CUV', '腓立比书', 50, 2, 17, '我以你们的信心为供献的祭物，我若被浇奠在其上，也是喜乐，并且与你们众人一同喜乐。'),
('CUV', '腓立比书', 50, 2, 18, '你们也要照样喜乐，并且与我一同喜乐。'),
('CUV', '腓立比书', 50, 2, 19, '我靠主耶稣指望快打发提摩太去见你们，叫我知道你们的事，心里就得著安慰。'),
('CUV', '腓立比书', 50, 2, 20, '因为我没有别人与我同心，实在罣念你们的事。'),
('CUV', '腓立比书', 50, 2, 21, '别人都求自己的事，并不求耶稣基督的事。'),
('CUV', '腓立比书', 50, 2, 22, '但你们知道提摩太的明证；他兴旺福音，与我同劳，待我像儿子待父亲一样。'),
('CUV', '腓立比书', 50, 2, 23, '所以，我一看出我的事要怎样了结，就盼望立刻打发他去；'),
('CUV', '腓立比书', 50, 2, 24, '但我靠著主自信我也必快去。'),
('CUV', '腓立比书', 50, 2, 25, '然而，我想必须打发以巴弗提到你们那里去。他是我的兄弟，与我一同做工，一同当兵，是你们所差遣的，也是供给我需用的。'),
('CUV', '腓立比书', 50, 2, 26, '他很想念你们众人，并且极其难过，因为你们听见他病了。'),
('CUV', '腓立比书', 50, 2, 27, '他实在是病了，几乎要死；然而神怜恤他，不但怜恤他，也怜恤我，免得我忧上加忧。'),
('CUV', '腓立比书', 50, 2, 28, '所以我越发急速打发他去，叫你们再见他，就可以喜乐，我也可以少些忧愁。'),
('CUV', '腓立比书', 50, 2, 29, '故此，你们要在主里欢欢乐乐的接待他，而且要尊重这样的人；'),
('CUV', '腓立比书', 50, 2, 30, '因他为做基督的工夫，几乎至死，不顾性命，要补足你们供给我的不及之处。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '腓立比书', 50, 3, 1, '弟兄们，我还有话说，你们要靠主喜乐。我把这话再写给你们，于我并不为难，于你们却是妥当。'),
('CUV', '腓立比书', 50, 3, 2, '应当防备犬类，防备作恶的，防备妄自行割的。'),
('CUV', '腓立比书', 50, 3, 3, '因为真受割礼的，乃是我们这以神的灵敬拜、在基督耶稣里夸口、不靠著肉体的。'),
('CUV', '腓立比书', 50, 3, 4, '其实，我也可以靠肉体；若是别人想他可以靠肉体，我更可以靠著了。'),
('CUV', '腓立比书', 50, 3, 5, '我第八天受割礼；我是以色列族、便雅悯支派的人，是希伯来人所生的希伯来人。就律法说，我是法利赛人；'),
('CUV', '腓立比书', 50, 3, 6, '就热心说，我是逼迫教会的；就律法上的义说，我是无可指摘的。'),
('CUV', '腓立比书', 50, 3, 7, '只是我先前以为与我有益的，我现在因基督都当作有损的。'),
('CUV', '腓立比书', 50, 3, 8, '不但如此，我也将万事当作有损的，因我以认识我主基督耶稣为至宝。我为他已经丢弃万事，看作粪土，为要得著基督；'),
('CUV', '腓立比书', 50, 3, 9, '并且得以在他里面，不是有自己因律法而得的义，乃是有信基督的义，就是因信神而来的义，'),
('CUV', '腓立比书', 50, 3, 10, '使我认识基督，晓得他复活的大能，并且晓得和他一同受苦，效法他的死，'),
('CUV', '腓立比书', 50, 3, 11, '或者我也得以从死里复活。'),
('CUV', '腓立比书', 50, 3, 12, '这不是说我已经得著了，已经完全了；我乃是竭力追求，或者可以得著基督耶稣所以得著我的（或作：所要我得的）。'),
('CUV', '腓立比书', 50, 3, 13, '弟兄们，我不是以为自己已经得著了；我只有一件事，就是忘记背后，努力面前的，'),
('CUV', '腓立比书', 50, 3, 14, '向著标竿直跑，要得神在基督耶稣里从上面召我来得的奖赏。'),
('CUV', '腓立比书', 50, 3, 15, '所以我们中间，凡是完全人总要存这样的心；若在甚么事上存别样的心，神也必以此指示你们。'),
('CUV', '腓立比书', 50, 3, 16, '然而，我们到了甚么地步，就当照著甚么地步行。'),
('CUV', '腓立比书', 50, 3, 17, '弟兄们，你们要一同效法我，也当留意看那些照我们榜样行的人。'),
('CUV', '腓立比书', 50, 3, 18, '因为有许多人行事是基督十字架的仇敌。我屡次告诉你们，现在又流泪的告诉你们：'),
('CUV', '腓立比书', 50, 3, 19, '他们的结局就是沉沦；他们的神就是自己的肚腹。他们以自己的羞辱为荣耀，专以地上的事为念。'),
('CUV', '腓立比书', 50, 3, 20, '我们却是天上的国民，并且等候救主，就是主耶稣基督从天上降临。'),
('CUV', '腓立比书', 50, 3, 21, '他要按著那能叫万有归服自己的大能，将我们这卑贱的身体改变形状，和他自己荣耀的身体相似。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '腓立比书', 50, 4, 1, '我所亲爱、所想念的弟兄们，你们就是我的喜乐，我的冠冕。我亲爱的弟兄，你们应当靠主站立得稳。'),
('CUV', '腓立比书', 50, 4, 2, '我劝友阿爹和循都基，要在主里同心。'),
('CUV', '腓立比书', 50, 4, 3, '我也求你这真实同负一轭的，帮助这两个女人，因为他们在福音上曾与我一同劳苦；还有革利免，并其余和我一同做工的，他们的名字都在生命册上。'),
('CUV', '腓立比书', 50, 4, 4, '你们要靠主常常喜乐。我再说，你们要喜乐。'),
('CUV', '腓立比书', 50, 4, 5, '当叫众人知道你们谦让的心。主已经近了。'),
('CUV', '腓立比书', 50, 4, 6, '应当一无罣虑，只要凡事藉著祷告、祈求，和感谢，将你们所要的告诉神。'),
('CUV', '腓立比书', 50, 4, 7, '神所赐、出人意外的平安必在基督耶稣里保守你们的心怀意念。'),
('CUV', '腓立比书', 50, 4, 8, '弟兄们，我还有未尽的话：凡是真实的、可敬的、公义的、清洁的、可爱的、有美名的，若有甚么德行，若有甚么称赞，这些事你们都要思念。'),
('CUV', '腓立比书', 50, 4, 9, '你们在我身上所学习的，所领受的，所听见的，所看见的，这些事你们都要去行，赐平安的神就必与你们同在。'),
('CUV', '腓立比书', 50, 4, 10, '我靠主大大的喜乐，因为你们思念我的心如今又发生；你们向来就思念我，只是没得机会。'),
('CUV', '腓立比书', 50, 4, 11, '我并不是因缺乏说这话；我无论在甚么景况都可以知足，这是我已经学会了。'),
('CUV', '腓立比书', 50, 4, 12, '我知道怎样处卑贱，也知道怎样处丰富；或饱足，或饥饿；或有余，或缺乏，随事随在，我都得了秘诀。'),
('CUV', '腓立比书', 50, 4, 13, '我靠著那加给我力量的，凡事都能做。'),
('CUV', '腓立比书', 50, 4, 14, '然而，你们和我同受患难原是美事。'),
('CUV', '腓立比书', 50, 4, 15, '腓立比人哪，你们也知道我初传福音离了马其顿的时候，论到授受的事，除了你们以外，并没有别的教会供给我。'),
('CUV', '腓立比书', 50, 4, 16, '就是我在帖撒罗尼迦，你们也一次两次的打发人供给我的需用。'),
('CUV', '腓立比书', 50, 4, 17, '我并不求甚么餽送，所求的就是你们的果子渐渐增多，归在你们的账上。'),
('CUV', '腓立比书', 50, 4, 18, '但我样样都有，并且有余。我已经充足，因我从以巴弗提受了你们的餽送，当作极美的香气，为神所收纳、所喜悦的祭物。'),
('CUV', '腓立比书', 50, 4, 19, '我的神必照他荣耀的丰富，在基督耶稣里，使你们一切所需用的都充足。'),
('CUV', '腓立比书', 50, 4, 20, '愿荣耀归给我们的父神，直到永永远远。阿们！'),
('CUV', '腓立比书', 50, 4, 21, '请问在基督耶稣里的各位圣徒安。在我这里的众弟兄都问你们安。'),
('CUV', '腓立比书', 50, 4, 22, '众圣徒都问你们安。在该撒家里的人特特的问你们安。'),
('CUV', '腓立比书', 50, 4, 23, '愿主耶稣基督的恩常在你们心里！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '歌罗西书', 51, 1, 1, '奉神旨意，作基督耶稣使徒的保罗和兄弟提摩太'),
('CUV', '歌罗西书', 51, 1, 2, '写信给歌罗西的圣徒，在基督里有忠心的弟兄。愿恩惠、平安从神我们的父归与你们！'),
('CUV', '歌罗西书', 51, 1, 3, '我们感谢神、我们主耶稣基督的父，常常为你们祷告；'),
('CUV', '歌罗西书', 51, 1, 4, '因听见你们在基督耶稣里的信心，并向众圣徒的爱心，'),
('CUV', '歌罗西书', 51, 1, 5, '是为那给你们存在天上的盼望；这盼望就是你们从前在福音真理的道上所听见的。'),
('CUV', '歌罗西书', 51, 1, 6, '这福音传到你们那里，也传到普天之下，并且结果，增长，如同在你们中间，自从你们听见福音，真知道神恩惠的日子一样。'),
('CUV', '歌罗西书', 51, 1, 7, '正如你们从我们所亲爱、一同作仆人的以巴弗所学的。他为我们（有古卷：你们）作了基督忠心的执事，'),
('CUV', '歌罗西书', 51, 1, 8, '也把你们因圣灵所存的爱心告诉了我们。'),
('CUV', '歌罗西书', 51, 1, 9, '因此，我们自从听见的日子，也就为你们不住的祷告祈求，愿你们在一切属灵的智慧悟性上，满心知道神的旨意；'),
('CUV', '歌罗西书', 51, 1, 10, '好叫你们行事为人对得起主，凡事蒙他喜悦，在一切善事上结果子，渐渐的多知道神；'),
('CUV', '歌罗西书', 51, 1, 11, '照他荣耀的权能，得以在各样的力上加力，好叫你们凡事欢欢喜喜的忍耐宽容；'),
('CUV', '歌罗西书', 51, 1, 12, '又感谢父，叫我们能与众圣徒在光明中同得基业。'),
('CUV', '歌罗西书', 51, 1, 13, '他救了我们脱离黑暗的权势，把我们迁到他爱子的国里；'),
('CUV', '歌罗西书', 51, 1, 14, '我们在爱子里得蒙救赎，罪过得以赦免。'),
('CUV', '歌罗西书', 51, 1, 15, '爱子是那不能看见之神的像，是首生的，在一切被造的以先。'),
('CUV', '歌罗西书', 51, 1, 16, '因为万有都是靠他造的，无论是天上的，地上的；能看见的，不能看见的；或是有位的，主治的，执政的，掌权的；一概都是藉著他造的，又是为他造的。'),
('CUV', '歌罗西书', 51, 1, 17, '他在万有之先；万有也靠他而立。'),
('CUV', '歌罗西书', 51, 1, 18, '他也是教会全体之首。他是元始，是从死里首先复生的，使他可以在凡事上居首位。'),
('CUV', '歌罗西书', 51, 1, 19, '因为父喜欢叫一切的丰盛在他里面居住。'),
('CUV', '歌罗西书', 51, 1, 20, '既然藉著他在十字架上所流的血成就了和平，便藉著他叫万有─无论是地上的、天上的─都与自己和好了。'),
('CUV', '歌罗西书', 51, 1, 21, '你们从前与神隔绝，因著恶行，心里与他为敌。'),
('CUV', '歌罗西书', 51, 1, 22, '但如今他藉著基督的肉身受死，叫你们与自己和好，都成了圣洁，没有瑕疵，无可责备，把你们引到自己面前。'),
('CUV', '歌罗西书', 51, 1, 23, '只要你们在所信的道上恒心，根基稳固，坚定不移，不至被引动失去（原文是离开）福音的盼望。这福音就是你们所听过的，也是传与普天下万人听的（原文是凡受造的），我保罗也作了这福音的执事。'),
('CUV', '歌罗西书', 51, 1, 24, '现在我为你们受苦，倒觉欢乐；并且为基督的身体，就是为教会，要在我肉身上补满基督患难的缺欠。'),
('CUV', '歌罗西书', 51, 1, 25, '我照神为你们所赐我的职分作了教会的执事，要把神的道理传得全备，'),
('CUV', '歌罗西书', 51, 1, 26, '这道理就是历世历代所隐藏的奥秘；但如今向他的圣徒显明了。'),
('CUV', '歌罗西书', 51, 1, 27, '神愿意叫他们知道，这奥秘在外邦人中有何等丰盛的荣耀，就是基督在你们心里成了有荣耀的盼望。'),
('CUV', '歌罗西书', 51, 1, 28, '我们传扬他，是用诸般的智慧，劝戒各人，教导各人，要把各人在基督里完完全全的引到神面前。'),
('CUV', '歌罗西书', 51, 1, 29, '我也为此劳苦，照著他在我�面运用的大能尽心竭力。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '歌罗西书', 51, 2, 1, '我愿意你们晓得，我为你们和老底嘉人，并一切没有与我亲自见面的人，是何等的尽心竭力；'),
('CUV', '歌罗西书', 51, 2, 2, '要叫他们的心得安慰，因爱心互相联络，以致丰丰足足在悟性中有充足的信心，使他们真知神的奥秘，就是基督；'),
('CUV', '歌罗西书', 51, 2, 3, '所积蓄的一切智慧知识，都在他里面藏著。'),
('CUV', '歌罗西书', 51, 2, 4, '我说这话，免得有人用花言巧语迷惑你们。'),
('CUV', '歌罗西书', 51, 2, 5, '我身子虽与你们相离，心却与你们同在，见你们循规蹈矩，信基督的心也坚固，我就欢喜了。'),
('CUV', '歌罗西书', 51, 2, 6, '你们既然接受了主基督耶稣，就当遵他而行，'),
('CUV', '歌罗西书', 51, 2, 7, '在他里面生根建造，信心坚固，正如你们所领的教训，感谢的心也更增长了。'),
('CUV', '歌罗西书', 51, 2, 8, '你们要谨慎，恐怕有人用他的理学和虚空的妄言，不照著基督，乃照人间的遗传和世上的小学就把你们掳去。'),
('CUV', '歌罗西书', 51, 2, 9, '因为神本性一切的丰盛都有形有体的居住在基督里面，'),
('CUV', '歌罗西书', 51, 2, 10, '你们在他里面也得了丰盛。他是各样执政掌权者的元首。'),
('CUV', '歌罗西书', 51, 2, 11, '你们在他里面也受了不是人手所行的割礼，乃是基督使你们脱去肉体情欲的割礼。'),
('CUV', '歌罗西书', 51, 2, 12, '你们既受洗与他一同埋葬，也就在此与他一同复活，都因信那叫他从死里复活神的功用。'),
('CUV', '歌罗西书', 51, 2, 13, '你们从前在过犯和未受割礼的肉体中死了，神赦免了你们（或作：我们）一切过犯，便叫你们与基督一同活过来；'),
('CUV', '歌罗西书', 51, 2, 14, '又涂抹了在律例上所写攻击我们，有碍于我们的字据，把他撤去，钉在十字架上。'),
('CUV', '歌罗西书', 51, 2, 15, '既将一切执政的、掌权的掳来，明显给众人看，就仗著十字架夸胜。'),
('CUV', '歌罗西书', 51, 2, 16, '所以，不拘在饮食上，或节期、月朔、安息日都不可让人论断你们。'),
('CUV', '歌罗西书', 51, 2, 17, '这些原是后事的影儿；那形体却是基督。'),
('CUV', '歌罗西书', 51, 2, 18, '不可让人因著故意谦虚和敬拜天使，就夺去你们的奖赏。这等人拘泥在所见过的（有古卷作：这等人窥察所没有见过的），随著自己的欲心，无故的自高自大，'),
('CUV', '歌罗西书', 51, 2, 19, '不持定元首。全身既然靠著他，筋节得以相助联络，就因神大得长进。'),
('CUV', '歌罗西书', 51, 2, 20, '你们若是与基督同死，脱离了世上的小学，为甚么仍像在世俗中活著、服从那不可拿、不可尝、不可摸等类的规条呢？'),
('CUV', '歌罗西书', 51, 2, 21, 'a'),
('CUV', '歌罗西书', 51, 2, 22, '这都是照人所吩咐、所教导的。说到这一切，正用的时候就都败坏了。'),
('CUV', '歌罗西书', 51, 2, 23, '这些规条使人徒有智慧之名，用私意崇拜，自表谦卑，苦待己身，其实在克制肉体的情欲上是毫无功效。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '歌罗西书', 51, 3, 1, '所以，你们若真与基督一同复活，就当求在上面的事；那里有基督坐在神的右边。'),
('CUV', '歌罗西书', 51, 3, 2, '你们要思念上面的事，不要思念地上的事。'),
('CUV', '歌罗西书', 51, 3, 3, '因为你们已经死了，你们的生命与基督一同藏在神里面。'),
('CUV', '歌罗西书', 51, 3, 4, '基督是我们的生命，他显现的时候，你们也要与他一同显现在荣耀里。'),
('CUV', '歌罗西书', 51, 3, 5, '所以，要治死你们在地上的肢体，就如淫乱、污秽、邪情、恶欲，和贪婪。贪婪就与拜偶像一样。'),
('CUV', '歌罗西书', 51, 3, 6, '因这些事，神的忿怒必临到那悖逆之子。'),
('CUV', '歌罗西书', 51, 3, 7, '当你们在这些事中活著的时候，也曾这样行过。'),
('CUV', '歌罗西书', 51, 3, 8, '但现在你们要弃绝这一切的事，以及恼恨、忿怒、恶毒（或作：阴毒）、毁谤，并口中污秽的言语。'),
('CUV', '歌罗西书', 51, 3, 9, '不要彼此说谎；因你们已经脱去旧人和旧人的行为，'),
('CUV', '歌罗西书', 51, 3, 10, '穿上了新人。这新人在知识上渐渐更新，正如造他主的形像。'),
('CUV', '歌罗西书', 51, 3, 11, '在此并不分希利尼人、犹太人，受割礼的、未受割礼的，化外人，西古提人，为奴的、自主的，惟有基督是包括一切，又住在各人之内。'),
('CUV', '歌罗西书', 51, 3, 12, '所以，你们既是神的选民，圣洁蒙爱的人，就要存（原文作穿；下同）怜悯、恩慈、谦虚、温柔、忍耐的心。'),
('CUV', '歌罗西书', 51, 3, 13, '倘若这人与那人有嫌隙，总要彼此包容，彼此饶恕；主怎样饶恕了你们，你们也要怎样饶恕人。'),
('CUV', '歌罗西书', 51, 3, 14, '在这一切之外，要存著爱心，爱心就是联络全德的。'),
('CUV', '歌罗西书', 51, 3, 15, '又要叫基督的平安在你们心里作主；你们也为此蒙召，归为一体；且要存感谢的心。'),
('CUV', '歌罗西书', 51, 3, 16, '当用各样的智慧，把基督的道理丰丰富富的存在心里，（或作：当把基督的道理丰丰富富的存在心里，以各样的智慧），用诗章、颂词、灵歌，彼此教导，互相劝戒，心被恩感，歌颂神。'),
('CUV', '歌罗西书', 51, 3, 17, '无论做甚么，或说话或行事，都要奉主耶稣的名，藉著他感谢父神。'),
('CUV', '歌罗西书', 51, 3, 18, '你们作妻子的，当顺服自己的丈夫，这在主里面是相宜的。'),
('CUV', '歌罗西书', 51, 3, 19, '你们作丈夫的，要爱你们的妻子，不可苦待他们。'),
('CUV', '歌罗西书', 51, 3, 20, '你们作儿女的，要凡事听从父母，因为这是主所喜悦的。'),
('CUV', '歌罗西书', 51, 3, 21, '你们作父亲的，不要惹儿女的气，恐怕他们失了志气。'),
('CUV', '歌罗西书', 51, 3, 22, '你们作仆人的，要凡事听从你们肉身的主人，不要只在眼前事奉，像是讨人喜欢的，总要存心诚实敬畏主。'),
('CUV', '歌罗西书', 51, 3, 23, '无论做甚么，都要从心里做，像是给主做的，不是给人做的，'),
('CUV', '歌罗西书', 51, 3, 24, '因你们知道从主那里必得著基业为赏赐；你们所事奉的乃是主基督。'),
('CUV', '歌罗西书', 51, 3, 25, '那行不义的必受不义的报应；主并不偏待人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '歌罗西书', 51, 4, 1, '你们作主人的，要公公平平的待仆人，因为知道你们也有一位主在天上。'),
('CUV', '歌罗西书', 51, 4, 2, '你们要恒切祷告，在此儆醒感恩。'),
('CUV', '歌罗西书', 51, 4, 3, '也要为我们祷告，求神给我们开传道的门，能以讲基督的奥秘（我为此被捆锁），'),
('CUV', '歌罗西书', 51, 4, 4, '叫我按著所该说的话将这奥秘发明出来。'),
('CUV', '歌罗西书', 51, 4, 5, '你们要爱惜光阴，用智慧与外人交往。'),
('CUV', '歌罗西书', 51, 4, 6, '你们的言语要常常带著和气，好像用盐调和，就可知道该怎样回答各人。'),
('CUV', '歌罗西书', 51, 4, 7, '有我亲爱的兄弟推基古要将我一切的事都告诉你们。他是忠心的执事，和我一同作主的仆人，'),
('CUV', '歌罗西书', 51, 4, 8, '我特意打发他到你们那里去，好叫你们知道我们的光景，又叫他安慰你们的心。'),
('CUV', '歌罗西书', 51, 4, 9, '我又打发一位亲爱忠心的兄弟阿尼西母同去；他也是你们那里的人。他们要把这里一切的事都告诉你们。'),
('CUV', '歌罗西书', 51, 4, 10, '与我一同坐监的亚里达古问你们安。巴拿巴的表弟马可也问你们安。（说到这马可，你们已经受了吩咐；他若到了你们那里，你们就接待他。）'),
('CUV', '歌罗西书', 51, 4, 11, '耶数又称为犹士都，也问你们安。奉割礼的人中，只有这三个人是为神的国与我一同做工的，也是叫我心里得安慰的。'),
('CUV', '歌罗西书', 51, 4, 12, '有你们那里的人，作基督耶稣仆人的以巴弗问你们安。他在祷告之间，常为你们竭力的祈求，愿你们在神一切的旨意上得以完全，信心充足，能站立得稳。'),
('CUV', '歌罗西书', 51, 4, 13, '他为你们和老底嘉并希拉波立的弟兄多多的劳苦，这是我可以给他作见证的。'),
('CUV', '歌罗西书', 51, 4, 14, '所亲爱的医生路加和底马问你们安。'),
('CUV', '歌罗西书', 51, 4, 15, '请问老底嘉的弟兄和宁法，并他家里的教会安。'),
('CUV', '歌罗西书', 51, 4, 16, '你们念了这书信，便交给老底嘉的教会，叫他们也念；你们也要念从老底嘉来的书信。'),
('CUV', '歌罗西书', 51, 4, 17, '要对亚基布说：务要谨慎，尽你从主所受的职分。'),
('CUV', '歌罗西书', 51, 4, 18, '我保罗亲笔问你们安。你们要记念我的捆锁。愿恩惠常与你们同在！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '帖撒罗尼迦前书', 52, 1, 1, '保罗、西拉、提摩太写信给帖撒罗尼迦在父神和主耶稣基督里的教会。愿恩惠平安归与你们！'),
('CUV', '帖撒罗尼迦前书', 52, 1, 2, '我们为你们众人常常感谢神，祷告的时候提到你们，'),
('CUV', '帖撒罗尼迦前书', 52, 1, 3, '在神我们的父面前，不住的记念你们因信心所做的工夫，因爱心所受的劳苦，因盼望我们主耶稣基督所存的忍耐。'),
('CUV', '帖撒罗尼迦前书', 52, 1, 4, '被神所爱的弟兄阿，我知道你们是蒙拣选的；'),
('CUV', '帖撒罗尼迦前书', 52, 1, 5, '因为我们的福音传到你们那里，不独在乎言语，也在乎权能和圣灵，并充足的信心，正如你们知道、我们在你们那里，为你们的缘故是怎样为人。'),
('CUV', '帖撒罗尼迦前书', 52, 1, 6, '并且你们在大难之中，蒙了圣灵所赐的喜乐，领受真道就效法我们，也效法了主；'),
('CUV', '帖撒罗尼迦前书', 52, 1, 7, '甚至你们作了马其顿和亚该亚所有信主之人的榜样。'),
('CUV', '帖撒罗尼迦前书', 52, 1, 8, '因为主的道从你们那里已经传扬出来。你们向神的信心不但在马其顿和亚该亚，就是在各处也都传开了；所以不用我们说甚么话。'),
('CUV', '帖撒罗尼迦前书', 52, 1, 9, '因为他们自己已经报明我们是怎样进到你们那里，你们是怎样离弃偶像，归向神，要服事那又真又活的神，'),
('CUV', '帖撒罗尼迦前书', 52, 1, 10, '等候他儿子从天降临，就是他从死里复活的─那位救我们脱离将来忿怒的耶稣。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '帖撒罗尼迦前书', 52, 2, 1, '弟兄们，你们自己原晓得我们进到你们那里并不是徒然的。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 2, '我们从前在腓立比被害受辱，这是你们知道的；然而还是靠我们的神放开胆量，在大争战中把神的福音传给你们。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 3, '我们的劝勉不是出于错误，不是出于污秽，也不是用诡诈。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 4, '但神既然验中了我们，把福音托付我们，我们就照样讲，不是要讨人喜欢，乃是要讨那察验我们心的神喜欢。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 5, '因为我们从来没有用过谄媚的话，这是你们知道的；也没有藏著贪心，这是神可以作见证的。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 6, '我们作基督的使徒，虽然可以叫人尊重，却没有向你们或向别人求荣耀；'),
('CUV', '帖撒罗尼迦前书', 52, 2, 7, '只在你们中间存心温柔，如同母亲乳养自己的孩子。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 8, '我们既是这样爱你们，不但愿意将神的福音给你们，连自己的性命也愿意给你们，因你们是我们所疼爱的。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 9, '弟兄们，你们记念我们的辛苦劳碌，昼夜做工，传神的福音给你们，免得叫你们一人受累。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 10, '我们向你们信主的人，是何等圣洁、公义、无可指摘，有你们作见证，也有神作见证。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 11, '你们也晓得我们怎样劝勉你们，安慰你们，嘱咐你们各人，好像父亲待自己的儿女一样，'),
('CUV', '帖撒罗尼迦前书', 52, 2, 12, '要叫你们行事对得起那召你们进他国、得他荣耀的神。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 13, '为此，我们也不住的感谢神，因你们听见我们所传神的道就领受了；不以为是人的道，乃以为是神的道。这道实在是神的，并且运行在你们信主的人心中。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 14, '弟兄们，你们曾效法犹太中在基督耶稣里神的各教会；因为你们也受了本地人的苦害，像他们受了犹太人的苦害一样。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 15, '这犹太人杀了主耶稣和先知，又把我们赶出去。他们不得神的喜悦，且与众人为敌；'),
('CUV', '帖撒罗尼迦前书', 52, 2, 16, '不许我们传道给外邦人使外邦人得救，常常充满自己的罪恶。神的忿怒临在他们身上已经到了极处。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 17, '弟兄们，我们暂时与你们离别，是面目离别，心里却不离别；我们极力的想法子，很愿意见你们的面。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 18, '所以我们有意到你们那里；我保罗有一两次要去，只是撒但阻挡了我们。'),
('CUV', '帖撒罗尼迦前书', 52, 2, 19, '我们的盼望和喜乐，并所夸的冠冕是甚么呢？岂不是我们主耶稣来的时候，你们在他面前站立得住么？'),
('CUV', '帖撒罗尼迦前书', 52, 2, 20, '因为你们就是我们的荣耀，我们的喜乐。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '帖撒罗尼迦前书', 52, 3, 1, '我们既不能再忍，就愿意独自等在雅典，'),
('CUV', '帖撒罗尼迦前书', 52, 3, 2, '打发我们的兄弟在基督福音上作神执事的（有古卷作：与神同工的）提摩太前去，坚固你们，并在你们所信的道上劝慰你们，'),
('CUV', '帖撒罗尼迦前书', 52, 3, 3, '免得有人被诸般患难摇动。因为你们自己知道我们受患难原是命定的。'),
('CUV', '帖撒罗尼迦前书', 52, 3, 4, '我们在你们那里的时候，预先告诉你们，我们必受患难，以后果然应验了，你们也知道。'),
('CUV', '帖撒罗尼迦前书', 52, 3, 5, '为此，我既不能再忍，就打发人去，要晓得你们的信心如何，恐怕那诱惑人的到底诱惑了你们，叫我们的劳苦归于徒然。'),
('CUV', '帖撒罗尼迦前书', 52, 3, 6, '但提摩太刚才从你们那里回来，将你们信心和爱心的好消息报给我们，又说你们常常记念我们，切切的想见我们，如同我们想见你们一样。'),
('CUV', '帖撒罗尼迦前书', 52, 3, 7, '所以弟兄们，我们在一切困苦患难之中，因著你们的信心就得了安慰。'),
('CUV', '帖撒罗尼迦前书', 52, 3, 8, '你们若靠主站立得稳，我们就活了。'),
('CUV', '帖撒罗尼迦前书', 52, 3, 9, '我们在神面前，因著你们甚是喜乐，为这一切喜乐，可用何等的感谢为你们报答神呢？'),
('CUV', '帖撒罗尼迦前书', 52, 3, 10, '我们昼夜切切的祈求，要见你们的面，补满你们信心的不足。'),
('CUV', '帖撒罗尼迦前书', 52, 3, 11, '愿神我们的父和我们的主耶稣一直引领我们到你们那里去。'),
('CUV', '帖撒罗尼迦前书', 52, 3, 12, '又愿主叫你们彼此相爱的心，并爱众人的心都能增长、充足，如同我们爱你们一样；'),
('CUV', '帖撒罗尼迦前书', 52, 3, 13, '好使你们当我们主耶稣同他众圣徒来的时候，在我们父神面前，心里坚固，成为圣洁，无可责备。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '帖撒罗尼迦前书', 52, 4, 1, '弟兄们，我还有话说：我们靠著主耶稣求你们，劝你们，你们既然受了我们的教训，知道该怎样行可以讨神的喜悦，就要照你们现在所行的更加勉励。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 2, '你们原晓得我们凭主耶稣传给你们甚么命令。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 3, '神的旨意就是要你们成为圣洁，远避淫行；'),
('CUV', '帖撒罗尼迦前书', 52, 4, 4, '要你们各人晓得怎样用圣洁、尊贵守著自己的身体。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 5, '不放纵私欲的邪情，像那不认识神的外邦人。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 6, '不要一个人在这事上越分，欺负他的弟兄；因为这一类的事，主必报应，正如我预先对你们说过，又切切嘱咐你们的。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 7, '神召我们，本不是要我们沾染污秽，乃是要我们成为圣洁。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 8, '所以那弃绝的，不是弃绝人，乃是弃绝那赐圣灵给你们的神。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 9, '论到弟兄们相爱，不用人写信给你们；因为你们自己蒙了神的教训，叫你们彼此相爱。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 10, '你们向马其顿全地的众弟兄固然是这样行，但我劝弟兄们要更加勉励。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 11, '又要立志作安静人，办自己的事，亲手做工，正如我们从前所吩咐你们的，'),
('CUV', '帖撒罗尼迦前书', 52, 4, 12, '叫你们可以向外人行事端正，自己也就没有甚么缺乏了。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 13, '论到睡了的人，我们不愿意弟兄们不知道，恐怕你们忧伤，像那些没有指望的人一样。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 14, '我们若信耶稣死而复活了，那已经在耶稣里睡了的人，神也必将他与耶稣一同带来。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 15, '我们现在照主的话告诉你们一件事：我们这活著还存留到主降临的人，断不能在那已经睡了的人之先。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 16, '因为主必亲自从天降临，有呼叫的声音和天使长的声音，又有神的号吹响；那在基督里死了的人必先复活。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 17, '以后我们这活著还存留的人必和他们一同被提到云里，在空中与主相遇。这样，我们就要和主永远同在。'),
('CUV', '帖撒罗尼迦前书', 52, 4, 18, '所以，你们当用这些话彼此劝慰。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '帖撒罗尼迦前书', 52, 5, 1, '弟兄们，论到时候、日期，不用写信给你们；'),
('CUV', '帖撒罗尼迦前书', 52, 5, 2, '因为你们自己明明晓得，主的日子来到，好像夜间的贼一样。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 3, '人正说平安稳妥的时候，灾祸忽然临到他们，如同产难临到怀胎的妇人一样。他们绝不能逃脱。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 4, '弟兄们，你们却不在黑暗里，叫那日子临到你们像贼一样。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 5, '你们都是光明之子，都是白昼之子。我们不是属黑夜的，也不是属幽暗的。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 6, '所以我们不要睡觉像别人一样，总要儆醒谨守。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 7, '因为睡了的人是在夜间睡，醉了的人是在夜间醉。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 8, '但我们既然属乎白昼，就应当谨守，把信和爱当作护心镜遮胸，把得救的盼望当作头盔戴上。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 9, '因为神不是预定我们受刑，乃是预定我们藉著我们主耶稣基督得救。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 10, '他替我们死，叫我们无论醒著、睡著，都与他同活。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 11, '所以，你们该彼此劝慰，互相建立，正如你们素常所行的。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 12, '弟兄们，我们劝你们敬重那在你们中间劳苦的人，就是在主里面治理你们、劝戒你们的。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 13, '又因他们所做的工，用爱心格外尊重他们。你们也要彼此和睦。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 14, '我们又劝弟兄们，要警戒不守规矩的人，勉励灰心的人，扶助软弱的人，也要向众人忍耐。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 15, '你们要谨慎，无论是谁都不可以恶报恶；或是彼此相待，或是待众人，常要追求良善。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 16, '要常常喜乐，'),
('CUV', '帖撒罗尼迦前书', 52, 5, 17, '不住的祷告，'),
('CUV', '帖撒罗尼迦前书', 52, 5, 18, '凡事谢恩；因为这是神在基督耶稣里向你们所定的旨意。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 19, '不要销灭圣灵的感动；'),
('CUV', '帖撒罗尼迦前书', 52, 5, 20, '不要藐视先知的讲论。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 21, '但要凡事察验，善美的要持守，'),
('CUV', '帖撒罗尼迦前书', 52, 5, 22, '各样的恶事要禁戒不做。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 23, '愿赐平安的神亲自使你们全然成圣！又愿你们的灵与魂与身子得蒙保守，在我主耶稣基督降临的时候，完全无可指摘！'),
('CUV', '帖撒罗尼迦前书', 52, 5, 24, '那召你们的本是信实的，他必成就这事。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 25, '请弟兄们为我们祷告。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 26, '与众弟兄亲嘴问安，务要圣洁。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 27, '我指著主嘱咐你们，要把这信念给众弟兄听。'),
('CUV', '帖撒罗尼迦前书', 52, 5, 28, '愿我主耶稣基督的恩常与你们同在！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '帖撒罗尼迦后书', 53, 1, 1, '保罗、西拉、提摩太写信给帖撒罗尼迦在神我们的父与主耶稣基督里的教会。'),
('CUV', '帖撒罗尼迦后书', 53, 1, 2, '愿恩惠、平安从父神和主耶稣基督归与你们！'),
('CUV', '帖撒罗尼迦后书', 53, 1, 3, '弟兄们，我们该为你们常常感谢神，这本是合宜的；因你们的信心格外增长，并且你们众人彼此相爱的心也都充足。'),
('CUV', '帖撒罗尼迦后书', 53, 1, 4, '甚至我们在神的各教会里为你们夸口，都因你们在所受的一切逼迫患难中，仍旧存忍耐和信心。'),
('CUV', '帖撒罗尼迦后书', 53, 1, 5, '这正是神公义判断的明证，叫你们可算配得神的国；你们就是为这国受苦。'),
('CUV', '帖撒罗尼迦后书', 53, 1, 6, '神既是公义的，就必将患难报应那加患难给你们的人；'),
('CUV', '帖撒罗尼迦后书', 53, 1, 7, '也必使你们这受患难的人与我们同得平安。那时，主耶稣同他有能力的天使从天上在火燄中显现，'),
('CUV', '帖撒罗尼迦后书', 53, 1, 8, '要报应那不认识神和那不听从我主耶稣福音的人。'),
('CUV', '帖撒罗尼迦后书', 53, 1, 9, '他们要受刑罚，就是永远沉沦，离开主的面和他权能的荣光。'),
('CUV', '帖撒罗尼迦后书', 53, 1, 10, '这正是主降临、要在他圣徒的身上得荣耀，又在一切信的人身上显为希奇的那日子。（我们对你们作的见证，你们也信了。）'),
('CUV', '帖撒罗尼迦后书', 53, 1, 11, '因此，我们常为你们祷告，愿我们的神看你们配得过所蒙的召，又用大能成就你们一切所羡慕的良善和一切因信心所做的工夫；'),
('CUV', '帖撒罗尼迦后书', 53, 1, 12, '叫我们主耶稣的名在你们身上得荣耀，你们也在他身上得荣耀，都照著我们的神并主耶稣基督的恩。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '帖撒罗尼迦后书', 53, 2, 1, '弟兄们，论到我们主耶稣基督降临和我们到他那里聚集，'),
('CUV', '帖撒罗尼迦后书', 53, 2, 2, '我劝你们：无论有灵、有言语、有冒我名的书信，说主的日子现在（或作：就）到了，不要轻易动心，也不要惊慌。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 3, '人不拘用甚么法子，你们总不要被他诱惑；因为那日子以前，必有离道反教的事，并有那大罪人，就是沉沦之子，显露出来。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 4, '他是抵挡主，高抬自己，超过一切称为神的和一切受人敬拜的，甚至坐在神的殿里，自称是神。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 5, '我还在你们那里的时候，曾把这些事告诉你们，你们不记得么？'),
('CUV', '帖撒罗尼迦后书', 53, 2, 6, '现在你们也知道，那拦阻他的是甚么，是叫他到了的时候才可以显露。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 7, '因为那不法的隐意已经发动，只是现在有一个拦阻的，等到那拦阻的被除去，'),
('CUV', '帖撒罗尼迦后书', 53, 2, 8, '那时这不法的人必显露出来。主耶稣要用口中的气灭绝他，用降临的荣光废掉他。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 9, '这不法的人来，是照撒但的运动，行各样的异能、神迹，和一切虚假的奇事，'),
('CUV', '帖撒罗尼迦后书', 53, 2, 10, '并且在那沉沦的人身上行各样出于不义的诡诈；因他们不领受爱真理的心，使他们得救。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 11, '故此，神就给他们一个生发错误的心，叫他们信从虚谎，'),
('CUV', '帖撒罗尼迦后书', 53, 2, 12, '使一切不信真理、倒喜爱不义的人都被定罪。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 13, '主所爱的弟兄们哪，我们本该常为你们感谢神；因为他从起初拣选了你们，叫你们因信真道，又被圣灵感动，成为圣洁，能以得救。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 14, '神藉我们所传的福音召你们到这地步，好得著我们主耶稣基督的荣光。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 15, '所以，弟兄们，你们要站立得稳，凡所领受的教训，不拘是我们口传的，是信上写的，都要坚守。'),
('CUV', '帖撒罗尼迦后书', 53, 2, 16, '但愿我们主耶稣基督和那爱我们、开恩将永远的安慰并美好的盼望赐给我们的父神，'),
('CUV', '帖撒罗尼迦后书', 53, 2, 17, '安慰你们的心，并且在一切善行善言上坚固你们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '帖撒罗尼迦后书', 53, 3, 1, '弟兄们，我还有话说：请你们为我们祷告，好叫主的道理快快行开，得著荣耀，正如在你们中间一样。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 2, '也叫我们脱离无理之恶人的手，因为人不都是有信心。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 3, '但主是信实的，要坚固你们，保护你们脱离那恶者。（或作：脱离凶恶）。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 4, '我们靠主深信，你们现在是遵行我们所吩咐的，后来也必要遵行。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 5, '愿主引导你们的心，叫你们爱神，并学基督的忍耐。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 6, '弟兄们，我们奉主耶稣基督的名吩咐你们，凡有弟兄不按规矩而行，不遵守从我们所受的教训，就当远离他。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 7, '你们自己原知道应当怎样效法我们。因为我们在你们中间，未尝不按规矩而行，'),
('CUV', '帖撒罗尼迦后书', 53, 3, 8, '也未尝白吃人的饭，倒是辛苦劳碌，昼夜做工，免得叫你们一人受累。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 9, '这并不是因我们没有权柄，乃是要给你们作榜样，叫你们效法我们。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 10, '我们在你们那里的时候，曾吩咐你们说，若有人不肯做工，就不可吃饭。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 11, '因我们听说，在你们中间有人不按规矩而行，甚么工都不做，反倒专管闲事。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 12, '我们靠主耶稣基督吩咐、劝戒这样的人，要安静做工，吃自己的饭。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 13, '弟兄们，你们行善不可丧志。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 14, '若有人不听从我们这信上的话，要记下他，不和他交往，叫他自觉羞愧。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 15, '但不要以他为仇人，要劝他如弟兄。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 16, '愿赐平安的主随时随事亲自给你们平安！愿主常与你们众人同在！'),
('CUV', '帖撒罗尼迦后书', 53, 3, 17, '我保罗亲笔问你们安。凡我的信都以此为记，我的笔迹就是这样。'),
('CUV', '帖撒罗尼迦后书', 53, 3, 18, '愿我们主耶稣基督的恩常与你们众人同在！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太前书', 54, 1, 1, '奉我们救主神和我们的盼望基督耶稣之命，作基督耶稣使徒的保罗，'),
('CUV', '提摩太前书', 54, 1, 2, '写信给那因信主作我真儿子的提摩太。愿恩惠、怜悯、平安从父神和我们主基督耶稣归与你！'),
('CUV', '提摩太前书', 54, 1, 3, '我往马其顿去的时候，曾劝你仍住在以弗所，好嘱咐那几个人不可传异教，'),
('CUV', '提摩太前书', 54, 1, 4, '也不可听从荒渺无凭的话语和无穷的家谱；这等事只生辩论，并不发明神在信上所立的章程。'),
('CUV', '提摩太前书', 54, 1, 5, '但命令的总归就是爱；这爱是从清洁的心和无亏的良心，无伪的信心生出来的。'),
('CUV', '提摩太前书', 54, 1, 6, '有人偏离这些，反去讲虚浮的话，'),
('CUV', '提摩太前书', 54, 1, 7, '想要作教法师，却不明白自己所讲说的所论定的。'),
('CUV', '提摩太前书', 54, 1, 8, '我们知道律法原是好的，只要人用得合宜；'),
('CUV', '提摩太前书', 54, 1, 9, '因为律法不是为义人设立的，乃是为不法和不服的，不虔诚和犯罪的，不圣洁和恋世俗的，弑父母和杀人的，'),
('CUV', '提摩太前书', 54, 1, 10, '行淫和亲男色的，抢人口和说谎话的，并起假誓的，或是为别样敌正道的事设立的。'),
('CUV', '提摩太前书', 54, 1, 11, '这是照著可称颂之神交托我荣耀福音说的。'),
('CUV', '提摩太前书', 54, 1, 12, '我感谢那给我力量的我们主基督耶稣，因他以我有忠心，派我服事他。'),
('CUV', '提摩太前书', 54, 1, 13, '我从前是亵渎神的，逼迫人的，侮慢人的；然而我还蒙了怜悯，因我是不信不明白的时候而做的。'),
('CUV', '提摩太前书', 54, 1, 14, '并且我主的恩是格外丰盛，使我在基督耶稣里有信心和爱心。'),
('CUV', '提摩太前书', 54, 1, 15, '基督耶稣降世，为要拯救罪人。这话是可信的，是十分可佩服的。在罪人中我是个罪魁。'),
('CUV', '提摩太前书', 54, 1, 16, '然而，我蒙了怜悯，是因耶稣基督要在我这罪魁身上显明他一切的忍耐，给后来信他得永生的人作榜样。'),
('CUV', '提摩太前书', 54, 1, 17, '但愿尊贵、荣耀归与那不能朽坏、不能看见、永世的君王、独一的神，直到永永远远。阿们！'),
('CUV', '提摩太前书', 54, 1, 18, '我儿提摩太阿，我照从前指著你的预言，将这命令交托你，叫你因此可以打那美好的仗。'),
('CUV', '提摩太前书', 54, 1, 19, '常存信心和无亏的良心。有人丢弃良心，就在真道上如同船破坏了一般。'),
('CUV', '提摩太前书', 54, 1, 20, '其中有许米乃和亚力山大；我已经把他们交给撒但，使他们受责罚就不再谤渎了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太前书', 54, 2, 1, '我劝你，第一要为万人恳求、祷告、代求、祝谢；'),
('CUV', '提摩太前书', 54, 2, 2, '为君王和一切在位的，也该如此，使我们可以敬虔、端正、平安无事的度日。'),
('CUV', '提摩太前书', 54, 2, 3, '这是好的，在神我们救主面前可蒙悦纳。'),
('CUV', '提摩太前书', 54, 2, 4, '他愿意万人得救，明白真道。'),
('CUV', '提摩太前书', 54, 2, 5, '因为只有一位神，在神和人中间，只有一位中保，乃是降世为人的基督耶稣；'),
('CUV', '提摩太前书', 54, 2, 6, '他舍自己作万人的赎价，到了时候，这事必证明出来。'),
('CUV', '提摩太前书', 54, 2, 7, '我为此奉派作传道的，作使徒，作外邦人的师傅，教导他们相信，学习真道。我说的是真话，并不是谎言。'),
('CUV', '提摩太前书', 54, 2, 8, '我愿男人无忿怒，无争论（或作：疑惑），举起圣洁的手，随处祷告。'),
('CUV', '提摩太前书', 54, 2, 9, '又愿女人廉耻、自守，以正派衣裳为妆饰，不以编发、黄金、珍珠，和贵价的衣裳为妆饰；'),
('CUV', '提摩太前书', 54, 2, 10, '只要有善行，这才与自称是敬神的女人相宜。'),
('CUV', '提摩太前书', 54, 2, 11, '女人要沉静学道，一味的顺服。'),
('CUV', '提摩太前书', 54, 2, 12, '我不许女人讲道，也不许他辖管男人，只要沉静。'),
('CUV', '提摩太前书', 54, 2, 13, '因为先造的是亚当，后造的是夏娃；'),
('CUV', '提摩太前书', 54, 2, 14, '且不是亚当被引诱，乃是女人被引诱，陷在罪里。'),
('CUV', '提摩太前书', 54, 2, 15, '然而，女人若常存信心、爱心，又圣洁自守，就必在生产上得救。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太前书', 54, 3, 1, '人若想要得监督的职分，就是羡慕善工。这话是可信的。'),
('CUV', '提摩太前书', 54, 3, 2, '作监督的，必须无可指责，只作一个妇人的丈夫，有节制，自守，端正，乐意接待远人，善于教导；'),
('CUV', '提摩太前书', 54, 3, 3, '不因酒滋事，不打人，只要温和，不争竞，不贪财；'),
('CUV', '提摩太前书', 54, 3, 4, '好好管理自己的家，使儿女凡事端庄顺服（或作：端端庄庄地使儿女顺服）。'),
('CUV', '提摩太前书', 54, 3, 5, '人若不知道管理自己的家，焉能照管神的教会呢？'),
('CUV', '提摩太前书', 54, 3, 6, '初入教的不可作监督，恐怕他自高自大，就落在魔鬼所受的刑罚里。'),
('CUV', '提摩太前书', 54, 3, 7, '监督也必须在教外有好名声，恐怕被人毁谤，落在魔鬼的网罗里。'),
('CUV', '提摩太前书', 54, 3, 8, '作执事的，也是如此：必须端庄，不一口两舌，不好喝酒，不贪不义之财；'),
('CUV', '提摩太前书', 54, 3, 9, '要存清洁的良心，固守真道的奥秘。'),
('CUV', '提摩太前书', 54, 3, 10, '这等人也要先受试验，若没有可责之处，然后叫他们作执事。'),
('CUV', '提摩太前书', 54, 3, 11, '女执事（原文是女人）也是如此：必须端庄，不说谗言，有节制，凡事忠心。'),
('CUV', '提摩太前书', 54, 3, 12, '执事只要作一个妇人的丈夫，好好管理儿女和自己的家。'),
('CUV', '提摩太前书', 54, 3, 13, '因为善作执事的，自己就得到美好的地步，并且在基督耶稣里的真道上大有胆量。'),
('CUV', '提摩太前书', 54, 3, 14, '我指望快到你那里去，所以先将这些事写给你。'),
('CUV', '提摩太前书', 54, 3, 15, '倘若我耽延日久，你也可以知道在神的家中当怎样行。这家就是永生神的教会，真理的柱石和根基。'),
('CUV', '提摩太前书', 54, 3, 16, '大哉，敬虔的奥秘！无人不以为然：就是神在肉身显现，被圣灵称义（或作：在灵性称义），被天使看见，被传于外邦，被世人信服，被接在荣耀里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太前书', 54, 4, 1, '圣灵明说，在后来的时候，必有人离弃真道，听从那引诱人的邪灵和鬼魔的道理。'),
('CUV', '提摩太前书', 54, 4, 2, '这是因为说谎之人的假冒；这等人的良心如同被热铁烙惯了一般。'),
('CUV', '提摩太前书', 54, 4, 3, '他们禁止嫁娶，又禁戒食物（或作：又叫人戒荤），就是神所造、叫那信而明白真道的人感谢著领受的。'),
('CUV', '提摩太前书', 54, 4, 4, '凡神所造的物都是好的，若感谢著领受，就没有一样可弃的，'),
('CUV', '提摩太前书', 54, 4, 5, '都因神的道和人的祈求成为圣洁了。'),
('CUV', '提摩太前书', 54, 4, 6, '你若将这些事提醒弟兄们，便是基督耶稣的好执事，在真道的话语和你向来所服从的善道上得了教育。'),
('CUV', '提摩太前书', 54, 4, 7, '只是要弃绝那世俗的言语和老妇荒渺的话，在敬虔上操练自己。'),
('CUV', '提摩太前书', 54, 4, 8, '操练身体，益处还少；惟独敬虔，凡事都有益处，因有今生和来生的应许。'),
('CUV', '提摩太前书', 54, 4, 9, '这话是可信的，是十分可佩服的。'),
('CUV', '提摩太前书', 54, 4, 10, '我们劳苦努力，正是为此，因我们的指望在乎永生的神；他是万人的救主，更是信徒的救主。'),
('CUV', '提摩太前书', 54, 4, 11, '这些事，你要吩咐人，也要教导人。'),
('CUV', '提摩太前书', 54, 4, 12, '不可叫人小看你年轻，总要在言语、行为、爱心、信心、清洁上，都作信徒的榜样。'),
('CUV', '提摩太前书', 54, 4, 13, '你要以宣读、劝勉、教导为念，直等到我来。'),
('CUV', '提摩太前书', 54, 4, 14, '你不要轻忽所得的恩赐，就是从前藉著预言、在众长老按手的时候赐给你的。'),
('CUV', '提摩太前书', 54, 4, 15, '这些事你要殷勤去做，并要在此专心，使众人看出你的长进来。'),
('CUV', '提摩太前书', 54, 4, 16, '你要谨慎自己和自己的教训，要在这些事上恒心；因为这样行，又能救自己，又能救听你的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太前书', 54, 5, 1, '不可严责老年人，只要劝他如同父亲；劝少年人如同弟兄；'),
('CUV', '提摩太前书', 54, 5, 2, '劝老年妇女如同母亲；劝少年妇女如同姐妹；总要清清洁洁的。'),
('CUV', '提摩太前书', 54, 5, 3, '要尊敬那真为寡妇的。'),
('CUV', '提摩太前书', 54, 5, 4, '若寡妇有儿女，或有孙子孙女，便叫他们先在自己家中学著行孝，报答亲恩，因为这在神面前是可悦纳的。'),
('CUV', '提摩太前书', 54, 5, 5, '那独居无靠、真为寡妇的，是仰赖神，昼夜不住的祈求祷告。'),
('CUV', '提摩太前书', 54, 5, 6, '但那好宴乐的寡妇正活著的时候也是死的。'),
('CUV', '提摩太前书', 54, 5, 7, '这些事你要嘱咐他们，叫他们无可指责。'),
('CUV', '提摩太前书', 54, 5, 8, '人若不看顾亲属，就是背了真道，比不信的人还不好，不看顾自己家里的人，更是如此。'),
('CUV', '提摩太前书', 54, 5, 9, '寡妇记在册子上，必须年纪到六十岁，从来只作一个丈夫的妻子，'),
('CUV', '提摩太前书', 54, 5, 10, '又有行善的名声，就如养育儿女，接待远人，洗圣徒的脚，救济遭难的人，竭力行各样善事。'),
('CUV', '提摩太前书', 54, 5, 11, '至于年轻的寡妇，就可以辞他；因为他们的情欲发动，违背基督的时候就想要嫁人。'),
('CUV', '提摩太前书', 54, 5, 12, '他们被定罪，是因废弃了当初所许的愿；'),
('CUV', '提摩太前书', 54, 5, 13, '并且他们又习惯懒惰，挨家闲游；不但是懒惰，又说长道短，好管闲事，说些不当说的话。'),
('CUV', '提摩太前书', 54, 5, 14, '所以我愿意年轻的寡妇嫁人，生养儿女，治理家务，不给敌人辱骂的把柄。'),
('CUV', '提摩太前书', 54, 5, 15, '因为已经有转去随从撒但的。'),
('CUV', '提摩太前书', 54, 5, 16, '信主的妇女，若家中有寡妇，自己就当救济他们，不可累著教会，好使教会能救济那真无倚靠的寡妇。'),
('CUV', '提摩太前书', 54, 5, 17, '那善于管理教会的长老，当以为配受加倍的敬奉；那劳苦传道教导人的，更当如此。'),
('CUV', '提摩太前书', 54, 5, 18, '因为经上说：牛在场上踹谷的时候，不可笼住他的嘴；又说：工人得工价是应当的。'),
('CUV', '提摩太前书', 54, 5, 19, '控告长老的呈子，非有两三个见证就不要收。'),
('CUV', '提摩太前书', 54, 5, 20, '犯罪的人，当在众人面前责备他，叫其余的人也可以惧怕。'),
('CUV', '提摩太前书', 54, 5, 21, '我在神和基督耶稣并蒙拣选的天使面前嘱咐你：要遵守这些话，不可存成见，行事也不可有偏心。'),
('CUV', '提摩太前书', 54, 5, 22, '给人行按手的礼，不可急促；不要在别人的罪上有分，要保守自己清洁。'),
('CUV', '提摩太前书', 54, 5, 23, '因你胃口不清，屡次患病，再不要照常喝水，可以稍微用点酒。'),
('CUV', '提摩太前书', 54, 5, 24, '有些人的罪是明显的，如同先到审判案前；有些人的罪是随后跟了去的。'),
('CUV', '提摩太前书', 54, 5, 25, '这样，善行也有明显的，那不明显的也不能隐藏。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太前书', 54, 6, 1, '凡在轭下作仆人的，当以自己主人配受十分的恭敬，免得神的名和道理被人亵渎。'),
('CUV', '提摩太前书', 54, 6, 2, '仆人有信道的主人，不可因为与他是弟兄就轻看他；更要加意服事他；因为得服事之益处的，是信道蒙爱的。你要以此教训人，劝勉人。'),
('CUV', '提摩太前书', 54, 6, 3, '若有人传异教，不服从我们主耶稣基督纯正的话与那合乎敬虔的道理，'),
('CUV', '提摩太前书', 54, 6, 4, '他是自高自大，一无所知，专好问难，争辩言词，从此就生出嫉妒、分争、毁谤、妄疑，'),
('CUV', '提摩太前书', 54, 6, 5, '并那坏了心术、失丧真理之人的争竞。他们以敬虔为得利的门路。'),
('CUV', '提摩太前书', 54, 6, 6, '然而，敬虔加上知足的心便是大利了；'),
('CUV', '提摩太前书', 54, 6, 7, '因为我们没有带甚么到世上来，也不能带甚么去。'),
('CUV', '提摩太前书', 54, 6, 8, '只要有衣有食，就当知足。'),
('CUV', '提摩太前书', 54, 6, 9, '但那些想要发财的人，就陷在迷惑、落在网罗和许多无知有害的私欲里，叫人沉在败坏和灭亡中。'),
('CUV', '提摩太前书', 54, 6, 10, '贪财是万恶之根。有人贪恋钱财，就被引诱离了真道，用许多愁苦把自己刺透了。'),
('CUV', '提摩太前书', 54, 6, 11, '但你这属神的人要逃避这些事，追求公义、敬虔、信心、爱心、忍耐、温柔。'),
('CUV', '提摩太前书', 54, 6, 12, '你要为真道打那美好的仗，持定永生。你为此被召，也在许多见证人面前，已经作了那美好的见证。'),
('CUV', '提摩太前书', 54, 6, 13, '我在叫万物生活的神面前，并在向本丢彼拉多作过那美好见证的基督耶稣面前嘱咐你：'),
('CUV', '提摩太前书', 54, 6, 14, '要守这命令，毫不玷污，无可指责，直到我们的主耶稣基督显现。'),
('CUV', '提摩太前书', 54, 6, 15, '到了日期，那可称颂、独有权能的万王之王、万主之主，'),
('CUV', '提摩太前书', 54, 6, 16, '就是那独一不死、住在人不能靠近的光里，是人未曾看见、也是不能看见的，要将他显明出来。但愿尊贵和永远的权能都归给他。阿们！'),
('CUV', '提摩太前书', 54, 6, 17, '你要嘱咐那些今世富足的人，不要自高，也不要倚靠无定的钱财；只要倚靠那厚赐百物给我们享受的神。'),
('CUV', '提摩太前书', 54, 6, 18, '又要嘱咐他们行善，在好事上富足，甘心施舍，乐意供给（或作：体贴）人，'),
('CUV', '提摩太前书', 54, 6, 19, '为自己积成美好的根基，预备将来，叫他们持定那真正的生命。'),
('CUV', '提摩太前书', 54, 6, 20, '提摩太阿，你要保守所托付你的，躲避世俗的虚谈和那敌真道、似是而非的学问。'),
('CUV', '提摩太前书', 54, 6, 21, '已经有人自称有这学问，就偏离了真道。愿恩惠常与你们同在！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太后书', 55, 1, 1, '奉神旨意，照著在基督耶稣里生命的应许，作基督耶稣使徒的保罗，'),
('CUV', '提摩太后书', 55, 1, 2, '写信给我亲爱的儿子提摩太。愿恩惠、怜悯、平安从父神和我们主基督耶稣归与你！'),
('CUV', '提摩太后书', 55, 1, 3, '我感谢神，就是我接续祖先用清洁的良心所事奉的神。祈祷的时候，不住的想念你！'),
('CUV', '提摩太后书', 55, 1, 4, '记念你的眼泪，昼夜切切的想要见你，好叫我满心快乐。'),
('CUV', '提摩太后书', 55, 1, 5, '想到你心里无伪之信，这信是先在你外祖母罗以和你母亲友尼基心里的，我深信也在你的心里。'),
('CUV', '提摩太后书', 55, 1, 6, '为此我提醒你，使你将神藉我按手所给你的恩赐再如火挑旺起来。'),
('CUV', '提摩太后书', 55, 1, 7, '因为神赐给我们，不是胆怯的心，乃是刚强、仁爱、谨守的心。'),
('CUV', '提摩太后书', 55, 1, 8, '你不要以给我们的主作见证为耻，也不要以我这为主被囚的为耻；总要按神的能力，与我为福音同受苦难。'),
('CUV', '提摩太后书', 55, 1, 9, '神救了我们，以圣召召我们，不是按我们的行为，乃是按他的旨意和恩典；这恩典是万古之先，在基督耶稣里赐给我们的，'),
('CUV', '提摩太后书', 55, 1, 10, '但如今藉著我们救主基督耶稣的显现才表明出来了。他已经把死废去，藉著福音，将不能坏的生命彰显出来。'),
('CUV', '提摩太后书', 55, 1, 11, '我为这福音奉派作传道的，作使徒，作师傅。'),
('CUV', '提摩太后书', 55, 1, 12, '为这缘故，我也受这些苦难。然而我不以为耻；因为知道我所信的是谁，也深信他能保全我所交付他的（或作：他所交托我的），直到那日。'),
('CUV', '提摩太后书', 55, 1, 13, '你从我听的那纯正话语的规模，要用在基督耶稣里的信心和爱心，常常守著。'),
('CUV', '提摩太后书', 55, 1, 14, '从前所交托你的善道，你要靠著那住在我们里面的圣灵牢牢的守著。'),
('CUV', '提摩太后书', 55, 1, 15, '凡在亚西亚的人都离弃我，这是你知道的，其中有腓吉路和黑摩其尼。'),
('CUV', '提摩太后书', 55, 1, 16, '愿主怜悯阿尼色弗一家的人；因他屡次使我畅快，不以我的锁链为耻，'),
('CUV', '提摩太后书', 55, 1, 17, '反倒在罗马的时候，殷勤的找我，并且找著了。'),
('CUV', '提摩太后书', 55, 1, 18, '愿主使他在那日得主的怜悯。他在以弗所怎样多多的服事我，是你明明知道的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太后书', 55, 2, 1, '我儿阿，你要在基督耶稣的恩典上刚强起来。'),
('CUV', '提摩太后书', 55, 2, 2, '你在许多见证人面前听见我所教训的，也要交托那忠心能教导别人的人。'),
('CUV', '提摩太后书', 55, 2, 3, '你要和我同受苦难，好像基督耶稣的精兵。'),
('CUV', '提摩太后书', 55, 2, 4, '凡在军中当兵的，不将世务缠身，好叫那招他当兵的人喜悦。'),
('CUV', '提摩太后书', 55, 2, 5, '人若在场上比武，非按规矩，就不能得冠冕。'),
('CUV', '提摩太后书', 55, 2, 6, '劳力的农夫，理当先得粮食。'),
('CUV', '提摩太后书', 55, 2, 7, '我所说的话你要思想，因为凡事主必给你聪明。'),
('CUV', '提摩太后书', 55, 2, 8, '你要记念耶稣基督乃是大卫的后裔，他从死里复活，正合乎我所传的福音。'),
('CUV', '提摩太后书', 55, 2, 9, '我为这福音受苦难，甚至被捆绑，像犯人一样。然而神的道却不被捆绑。'),
('CUV', '提摩太后书', 55, 2, 10, '所以我为选民凡事忍耐，叫他们也可以得著那在基督耶稣里的救恩和永远的荣耀。'),
('CUV', '提摩太后书', 55, 2, 11, '有可信的话说：我们若与基督同死，也必与他同活；'),
('CUV', '提摩太后书', 55, 2, 12, '我们若能忍耐，也必和他一同作王；我们若不认他，他也必不认我们；'),
('CUV', '提摩太后书', 55, 2, 13, '我们纵然失信，他仍是可信的，因为他不能背乎自己。'),
('CUV', '提摩太后书', 55, 2, 14, '你要使众人回想这些事，在主面前嘱咐他们：不可为言语争辩；这是没有益处的，只能败坏听见的人。'),
('CUV', '提摩太后书', 55, 2, 15, '你当竭力在神面前得蒙喜悦，作无愧的工人，按著正意分解真理的道。'),
('CUV', '提摩太后书', 55, 2, 16, '但要远避世俗的虚谈，因为这等人必进到更不敬虔的地步。'),
('CUV', '提摩太后书', 55, 2, 17, '他们的话如同毒疮，越烂越大；其中有许米乃和腓理徒，'),
('CUV', '提摩太后书', 55, 2, 18, '他们偏离了真道，说复活的事已过，就败坏好些人的信心。'),
('CUV', '提摩太后书', 55, 2, 19, '然而，神坚固的根基立住了；上面有这印记说：主认识谁是他的人；又说：凡称呼主名的人总要离开不义。'),
('CUV', '提摩太后书', 55, 2, 20, '在大户人家，不但有金器银器，也有木器瓦器；有作为贵重的，有作为卑贱的。'),
('CUV', '提摩太后书', 55, 2, 21, '人若自洁，脱离卑贱的事，就必作贵重的器皿，成为圣洁，合乎主用，预备行各样的善事。'),
('CUV', '提摩太后书', 55, 2, 22, '你要逃避少年的私欲，同那清心祷告主的人追求公义、信德、仁爱、和平。'),
('CUV', '提摩太后书', 55, 2, 23, '惟有那愚拙无学问的辩论，总要弃绝，因为知道这等事是起争竞的。'),
('CUV', '提摩太后书', 55, 2, 24, '然而主的仆人不可争竞，只要温温和和的待众人，善于教导，存心忍耐，'),
('CUV', '提摩太后书', 55, 2, 25, '用温柔劝戒那抵挡的人；或者神给他们悔改的心，可以明白真道，'),
('CUV', '提摩太后书', 55, 2, 26, '叫他们这已经被魔鬼任意掳去的，可以醒悟，脱离他的网罗。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太后书', 55, 3, 1, '你该知道，末世必有危险的日子来到。'),
('CUV', '提摩太后书', 55, 3, 2, '因为那时人要专顾自己、贪爱钱财、自夸、狂傲、谤讟、违背父母、忘恩负义、心不圣洁、'),
('CUV', '提摩太后书', 55, 3, 3, '无亲情、不解怨、好说谗言、不能自约、性情凶暴、不爱良善、'),
('CUV', '提摩太后书', 55, 3, 4, '卖主卖友、任意妄为、自高自大、爱宴乐、不爱神，'),
('CUV', '提摩太后书', 55, 3, 5, '有敬虔的外貌，却背了敬虔的实意；这等人你要躲开。'),
('CUV', '提摩太后书', 55, 3, 6, '那偷进人家、牢笼无知妇女的，正是这等人。这些妇女担负罪恶，被各样的私欲引诱，'),
('CUV', '提摩太后书', 55, 3, 7, '常常学习，终久不能明白真道。'),
('CUV', '提摩太后书', 55, 3, 8, '从前雅尼和佯庇怎样敌挡摩西，这等人也怎样敌挡真道。他们的心地坏了，在真道上是可废弃的。'),
('CUV', '提摩太后书', 55, 3, 9, '然而他们不能再这样敌挡；因为他们的愚昧必在众人面前显露出来，像那二人一样。'),
('CUV', '提摩太后书', 55, 3, 10, '但你已经服从了我的教训、品行、志向、信心、宽容、爱心、忍耐，'),
('CUV', '提摩太后书', 55, 3, 11, '以及我在安提阿、以哥念、路司得所遭遇的逼迫，苦难。我所忍受是何等的逼迫；但从这一切苦难中，主都把我救出来了。'),
('CUV', '提摩太后书', 55, 3, 12, '不但如此，凡立志在基督耶稣里敬虔度日的也都要受逼迫。'),
('CUV', '提摩太后书', 55, 3, 13, '只是作恶的和迷惑人的，必越久越恶，他欺哄人，也被人欺哄。'),
('CUV', '提摩太后书', 55, 3, 14, '但你所学习的，所确信的，要存在心里；因为你知道是跟谁学的，'),
('CUV', '提摩太后书', 55, 3, 15, '并且知道你是从小明白圣经，这圣经能使你因信基督耶稣，有得救的智慧。'),
('CUV', '提摩太后书', 55, 3, 16, '圣经都是神所默示的（或作：凡神所默示的圣经），于教训、督责、使人归正、教导人学义都是有益的，'),
('CUV', '提摩太后书', 55, 3, 17, '叫属神的人得以完全，预备行各样的善事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提摩太后书', 55, 4, 1, '我在神面前，并在将来审判活人死人的基督耶稣面前，凭著他的显现和他的国度嘱咐你：'),
('CUV', '提摩太后书', 55, 4, 2, '务要传道，无论得时不得时，总要专心；并用百般的忍耐，各样的教训，责备人、警戒人、劝勉人。'),
('CUV', '提摩太后书', 55, 4, 3, '因为时候要到，人必厌烦纯正的道理，耳朵发痒，就随从自己的情欲，增添好些师傅，'),
('CUV', '提摩太后书', 55, 4, 4, '并且掩耳不听真道，偏向荒渺的言语。'),
('CUV', '提摩太后书', 55, 4, 5, '你却要凡事谨慎，忍受苦难，做传道的工夫，尽你的职分。'),
('CUV', '提摩太后书', 55, 4, 6, '我现在被浇奠，我离世的时候到了。'),
('CUV', '提摩太后书', 55, 4, 7, '那美好的仗我已经打过了，当跑的路我已经跑尽了，所信的道我已经守住了。'),
('CUV', '提摩太后书', 55, 4, 8, '从此以后，有公义的冠冕为我存留，就是按著公义审判的主到了那日要赐给我的；不但赐给我，也赐给凡爱慕他显现的人。'),
('CUV', '提摩太后书', 55, 4, 9, '你要赶紧的到我这里来。'),
('CUV', '提摩太后书', 55, 4, 10, '因为底马贪爱现今的世界，就离弃我往帖撒罗尼迦去了，革勒士往加拉太去，提多往挞马太去，'),
('CUV', '提摩太后书', 55, 4, 11, '独有路加在我这里。你来的时候，要把马可带来，因为他在传道（或作：服事我）的事上于我有益处。'),
('CUV', '提摩太后书', 55, 4, 12, '我已经打发推基古往以弗所去。'),
('CUV', '提摩太后书', 55, 4, 13, '我在特罗亚留于加布的那件外衣，你来的时候可以带来，那些书也要带来，更要紧的是那些皮卷。'),
('CUV', '提摩太后书', 55, 4, 14, '铜匠亚力山大多多的害我；主必照他所行的报应他。'),
('CUV', '提摩太后书', 55, 4, 15, '你也要防备他，因为他极力敌挡了我们的话。'),
('CUV', '提摩太后书', 55, 4, 16, '我初次申诉，没有人前来帮助，竟都离弃我；但愿这罪不归与他们。'),
('CUV', '提摩太后书', 55, 4, 17, '惟有主站在我旁边，加给我力量，使福音被我尽都传明，叫外邦人都听见；我也从狮子口里被救出来。'),
('CUV', '提摩太后书', 55, 4, 18, '主必救我脱离诸般的凶恶，也必救我进他的天国。愿荣耀归给他，直到永永远远。阿们。'),
('CUV', '提摩太后书', 55, 4, 19, '问百基拉、亚居拉，和阿尼色弗一家的人安。'),
('CUV', '提摩太后书', 55, 4, 20, '以拉都在哥林多住下了。特罗非摩病了，我就留他在米利都。'),
('CUV', '提摩太后书', 55, 4, 21, '你要赶紧在冬天以前到我这里来。有友布罗、布田、利奴、革老底亚，和众弟兄都问你安。'),
('CUV', '提摩太后书', 55, 4, 22, '愿主与你的灵同在。愿恩惠常与你们同在！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提多书', 56, 1, 1, '神的仆人，耶稣基督的使徒保罗，凭著神选民的信心与敬虔真理的知识，'),
('CUV', '提多书', 56, 1, 2, '盼望那无谎言的神在万古之先所应许的永生，'),
('CUV', '提多书', 56, 1, 3, '到了日期，藉著传扬的工夫把他的道显明了；这传扬的责任是按著神我们救主的命令交托了我。'),
('CUV', '提多书', 56, 1, 4, '现在写信给提多，就是照著我们共信之道作我真儿子的。愿恩惠、平安从父神和我们的救主基督耶稣归与你！'),
('CUV', '提多书', 56, 1, 5, '我从前留你在革哩底，是要你将那没有办完的事都办整齐了，又照我所吩咐你的，在各城设立长老。'),
('CUV', '提多书', 56, 1, 6, '若有无可指责的人，只作一个妇人的丈夫，儿女也是信主的，没有人告他们是放荡不服约束的，就可以设立。'),
('CUV', '提多书', 56, 1, 7, '监督既是神的管家，必须无可指责，不任性，不暴躁，不因酒滋事，不打人，不贪无义之财；'),
('CUV', '提多书', 56, 1, 8, '乐意接待远人，好善，庄重，公平，圣洁自持；'),
('CUV', '提多书', 56, 1, 9, '坚守所教真实的道理，就能将纯正的教训劝化人，又能把争辩的人驳倒了。'),
('CUV', '提多书', 56, 1, 10, '因为有许多人不服约束，说虚空话欺哄人；那奉割礼的更是这样。'),
('CUV', '提多书', 56, 1, 11, '这些人的口总要堵住。他们因贪不义之财，将不该教导的教导人，败坏人的全家。'),
('CUV', '提多书', 56, 1, 12, '有革哩底人中的一个本地先知说：革哩底人常说谎话，乃是恶兽又馋又懒。'),
('CUV', '提多书', 56, 1, 13, '这个见证是真的。所以，你要严严的责备他们，使他们在真道上纯全无疵，'),
('CUV', '提多书', 56, 1, 14, '不听犹太人荒渺的言语和离弃真道之人的诫命。'),
('CUV', '提多书', 56, 1, 15, '在洁净的人，凡物都洁净；在污秽不信的人，甚么都不洁净，连心地和天良也都污秽了。'),
('CUV', '提多书', 56, 1, 16, '他们说是认识神，行事却和他相背；本是可憎恶的，是悖逆的，在各样善事上是可废弃的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提多书', 56, 2, 1, '但你所讲的总要合乎那纯正的道理。'),
('CUV', '提多书', 56, 2, 2, '劝老年人要有节制、端庄、自守，在信心、爱心、忍耐上都要纯全无疵。'),
('CUV', '提多书', 56, 2, 3, '又劝老年妇人，举止行动要恭敬，不说谗言，不给酒作奴仆，用善道教训人，'),
('CUV', '提多书', 56, 2, 4, '好指教少年妇人，爱丈夫，爱儿女，'),
('CUV', '提多书', 56, 2, 5, '谨守，贞洁，料理家务，待人有恩，顺服自己的丈夫，免得神的道理被毁谤。'),
('CUV', '提多书', 56, 2, 6, '又劝少年人要谨守。'),
('CUV', '提多书', 56, 2, 7, '你自己凡事要显出善行的榜样；在教训上要正直、端庄，'),
('CUV', '提多书', 56, 2, 8, '言语纯全，无可指责，叫那反对的人，既无处可说我们的不是，便自觉羞愧。'),
('CUV', '提多书', 56, 2, 9, '劝仆人要顺服自己的主人，凡事讨他的喜欢，不可顶撞他，'),
('CUV', '提多书', 56, 2, 10, '不可私拿东西；要显为忠诚，以致凡事尊荣我们救主神的道。'),
('CUV', '提多书', 56, 2, 11, '因为神救众人的恩典已经显明出来，'),
('CUV', '提多书', 56, 2, 12, '教训我们除去不敬虔的心和世俗的情欲，在今世自守、公义、敬虔度日，'),
('CUV', '提多书', 56, 2, 13, '等候所盼望的福，并等候至大的神和我们（或作：神─我们）救主耶稣基督的荣耀显现。'),
('CUV', '提多书', 56, 2, 14, '他为我们舍了自己，要赎我们脱离一切罪恶，又洁净我们，特作自己的子民，热心为善。'),
('CUV', '提多书', 56, 2, 15, '这些事你要讲明，劝戒人，用各等权柄责备人；不可叫人轻看你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '提多书', 56, 3, 1, '你要提醒众人，叫他们顺服作官的、掌权的，遵他的命，预备行各样的善事。'),
('CUV', '提多书', 56, 3, 2, '不要毁谤，不要争竞，总要和平，向众人大显温柔。'),
('CUV', '提多书', 56, 3, 3, '我们从前也是无知、悖逆、受迷惑、服事各样私欲，和宴乐，常存恶毒（或作：阴毒）嫉妒的心，是可恨的，又是彼此相恨。'),
('CUV', '提多书', 56, 3, 4, '但到了神─我们救主的恩慈和他向人所施的慈爱显明的时候，'),
('CUV', '提多书', 56, 3, 5, '他便救了我们；并不是因我们自己所行的义，乃是照他的怜悯，藉著重生的洗和圣灵的更新。'),
('CUV', '提多书', 56, 3, 6, '圣灵就是神藉著耶稣基督我们救主厚厚浇灌在我们身上的，'),
('CUV', '提多书', 56, 3, 7, '好叫我们因他的恩得称为义，可以凭著永生的盼望成为后嗣。（或作：可以凭著盼望承受永生）。'),
('CUV', '提多书', 56, 3, 8, '这话是可信的。我也愿你把这些事切切实实的讲明，使那些已信神的人留心做正经事业（或作：留心行善）。这都是美事，并且与人有益。'),
('CUV', '提多书', 56, 3, 9, '要远避无知的辩论和家谱的空谈，以及分争，并因律法而起的争竞，因为这都是虚妄无益的。'),
('CUV', '提多书', 56, 3, 10, '分门结党的人，警戒过一两次，就要弃绝他。'),
('CUV', '提多书', 56, 3, 11, '因为知道这等人已经背道，犯了罪，自己明知不是，还是去做。'),
('CUV', '提多书', 56, 3, 12, '我打发亚提马或是推基古到你那里去的时候，你要赶紧往尼哥波立去见我，因为我已经定意在那里过冬。'),
('CUV', '提多书', 56, 3, 13, '你要赶紧给律师西纳和亚波罗送行，叫他们没有缺乏。'),
('CUV', '提多书', 56, 3, 14, '并且我们的人要学习正经事业（或作：要学习行善），预备所需用的，免得不结果子。'),
('CUV', '提多书', 56, 3, 15, '同我在一处的人都问你安。请代问那些因有信心爱我们的人安。愿恩惠常与你们众人同在！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '腓利门书', 57, 1, 1, '为基督耶稣被囚的保罗，同兄弟提摩太写信给我们所亲爱的同工腓利门，'),
('CUV', '腓利门书', 57, 1, 2, '和妹子亚腓亚并与我们同当兵的亚基布，以及在你家的教会。'),
('CUV', '腓利门书', 57, 1, 3, '愿恩惠、平安从神我们的父和主耶稣基督归与你们！'),
('CUV', '腓利门书', 57, 1, 4, '我祷告的时候提到你，常为你感谢我的神；'),
('CUV', '腓利门书', 57, 1, 5, '因听说你的爱心并你向主耶稣和众圣徒的信心（或作：因听说你向主耶稣和众圣徒有爱心有信心）。'),
('CUV', '腓利门书', 57, 1, 6, '愿你与人所同有的信心显出功效，使人知道你们各样善事都是为基督做的。'),
('CUV', '腓利门书', 57, 1, 7, '兄弟阿，我为你的爱心，大有快乐，大得安慰，因众圣徒的心从你得了畅快。'),
('CUV', '腓利门书', 57, 1, 8, '我虽然靠著基督能放胆吩咐你合宜的事；'),
('CUV', '腓利门书', 57, 1, 9, '然而像我这有年纪的保罗，现在又是为基督耶稣被囚的，宁可凭著爱心求你，'),
('CUV', '腓利门书', 57, 1, 10, '就是为我在捆锁中所生的儿子阿尼西母（就是有益处的意思）求你。'),
('CUV', '腓利门书', 57, 1, 11, '他从前与你没有益处，但如今与你我都有益处。'),
('CUV', '腓利门书', 57, 1, 12, '我现在打发他亲自回你那里去，他是我心上的人。'),
('CUV', '腓利门书', 57, 1, 13, '我本来有意将他留下，在我为福音所受的捆锁中替你伺候我。'),
('CUV', '腓利门书', 57, 1, 14, '但不知道你的意思，我就不愿意这样行，叫你的善行不是出于勉强，乃是出于甘心。'),
('CUV', '腓利门书', 57, 1, 15, '他暂时离开你，或者是叫你永远得著他，'),
('CUV', '腓利门书', 57, 1, 16, '不再是奴仆，乃是高过奴仆，是亲爱的兄弟。在我实在是如此，何况在你呢！这也不拘是按肉体说，是按主说，'),
('CUV', '腓利门书', 57, 1, 17, '你若以我为同伴，就收纳他，如同收纳我一样。'),
('CUV', '腓利门书', 57, 1, 18, '他若亏负你，或欠你甚么，都归在我的账上，'),
('CUV', '腓利门书', 57, 1, 19, '我必偿还。这是我保罗亲笔写的。我并不用对你说，连你自己也是亏欠于我。'),
('CUV', '腓利门书', 57, 1, 20, '兄弟阿，望你使我在主里因你得快乐（或作：益处）并望你使我的心在基督里得畅快。'),
('CUV', '腓利门书', 57, 1, 21, '我写信给你，深信你必顺服，知道你所要行的，必过于我所说的。'),
('CUV', '腓利门书', 57, 1, 22, '此外你还要给我预备住处；因为我盼望藉著你们的祷告，必蒙恩到你们那里去。'),
('CUV', '腓利门书', 57, 1, 23, '为基督耶稣与我同坐监的以巴弗问你安。'),
('CUV', '腓利门书', 57, 1, 24, '与我同工的马可、亚里达古、底马、路加、也都问你安。'),
('CUV', '腓利门书', 57, 1, 25, '愿我们主耶稣基督的恩常在你的心里。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 1, 1, '神既在古时藉著众先知多次多方的晓谕列祖，'),
('CUV', '希伯来书', 58, 1, 2, '就在这末世藉著他儿子晓谕我们；又早已立他为承受万有的，也曾藉著他创造诸世界。'),
('CUV', '希伯来书', 58, 1, 3, '他是神荣耀所发的光辉，是神本体的真像，常用他权能的命令托住万有。他洗净了人的罪，就坐在高天至大者的右边。'),
('CUV', '希伯来书', 58, 1, 4, '他所承受的名，既比天使的名更尊贵，就远超过天使。'),
('CUV', '希伯来书', 58, 1, 5, '所有的天使，神从来对那一个说，你是我的儿子，我今日生你？又指著那一个说：我要作他的父，他要作我的子？'),
('CUV', '希伯来书', 58, 1, 6, '再者，神使长子到世上来的时候（或作：神再使长子到世上来的时候），就说：神的使者都要拜他。'),
('CUV', '希伯来书', 58, 1, 7, '论到使者，又说：神以风为使者，以火燄为仆役；'),
('CUV', '希伯来书', 58, 1, 8, '论到子却说：神阿，你的宝座是永永远远的；你的国权是正直的。'),
('CUV', '希伯来书', 58, 1, 9, '你喜爱公义，恨恶罪恶；所以神，就是你的神，用喜乐油膏你，胜过膏你的同伴；'),
('CUV', '希伯来书', 58, 1, 10, '又说：主阿，你起初立了地的根基；天也是你手所造的。'),
('CUV', '希伯来书', 58, 1, 11, '天地都要灭没，你却要长存。天地都要像衣服渐渐旧了；'),
('CUV', '希伯来书', 58, 1, 12, '你要将天地卷起来，像一件外衣，天地就都改变了。惟有你永不改变；你的年数没有穷尽。'),
('CUV', '希伯来书', 58, 1, 13, '所有的天使，神从来对那一个说：你坐在我的右边，等我使你仇敌作你的脚凳？'),
('CUV', '希伯来书', 58, 1, 14, '天使岂不都是服役的灵、奉差遣为那将要承受救恩的人效力么？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 2, 1, '所以，我们当越发郑重所听见的道理，恐怕我们随流失去。'),
('CUV', '希伯来书', 58, 2, 2, '那藉著天使所传的话既是确定的；凡犯悖逆的都受了该受的报应。'),
('CUV', '希伯来书', 58, 2, 3, '我们若忽略这么大的救恩，怎能逃罪呢？这救恩起先是主亲自讲的，后来是听见的人给我们证实了。'),
('CUV', '希伯来书', 58, 2, 4, '神又按自己的旨意，用神迹、奇事和百般的异能，并圣灵的恩赐，同他们作见证。'),
('CUV', '希伯来书', 58, 2, 5, '我们所说将来的世界，神原没有交给天使管辖。'),
('CUV', '希伯来书', 58, 2, 6, '但有人在经上某处证明说：人算甚么，你竟顾念他？世人算甚么，你竟眷顾他？'),
('CUV', '希伯来书', 58, 2, 7, '你叫他比天使微小一点（或作：你叫他暂时比天使小），赐他荣耀尊贵为冠冕，并将你手所造的都派他管理，'),
('CUV', '希伯来书', 58, 2, 8, '叫万物都服在他的脚下。既叫万物都服他，就没有剩下一样不服他的。只是如今我们还不见万物都服他。'),
('CUV', '希伯来书', 58, 2, 9, '惟独见那成为比天使小一点的耶稣（或作：惟独见耶稣暂时比天使小）；因为受死的苦，就得了尊贵荣耀为冠冕，叫他因著神的恩，为人人尝了死味。'),
('CUV', '希伯来书', 58, 2, 10, '原来那为万物所属为万物所本的，要领许多的儿子进荣耀里去，使救他们的元帅，因受苦难得以完全，本是合宜的。'),
('CUV', '希伯来书', 58, 2, 11, '因那使人成圣的和那些得以成圣的，都是出于一。所以，他称他们为弟兄也不以为耻，'),
('CUV', '希伯来书', 58, 2, 12, '说：我要将你的名传与我的弟兄，在会中我要颂扬你；'),
('CUV', '希伯来书', 58, 2, 13, '又说：我要倚赖他；又说：看哪，我与神所给我的儿女。'),
('CUV', '希伯来书', 58, 2, 14, '儿女既同有血肉之体，他也照样亲自成了血肉之体，特要藉著死败坏那掌死权的，就是魔鬼，'),
('CUV', '希伯来书', 58, 2, 15, '并要释放那些一生因怕死而为奴仆的人。'),
('CUV', '希伯来书', 58, 2, 16, '他并不救拔天使，乃是救拔亚伯拉罕的后裔。'),
('CUV', '希伯来书', 58, 2, 17, '所以，他凡事该与他的弟兄相同，为要在神的事上成为慈悲忠信的大祭司，为百姓的罪献上挽回祭。'),
('CUV', '希伯来书', 58, 2, 18, '他自己既然被试探而受苦，就能搭救被试探的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 3, 1, '同蒙天召的圣洁弟兄阿，你们应当思想我们所认为使者、为大祭司的耶稣。'),
('CUV', '希伯来书', 58, 3, 2, '他为那设立他的尽忠，如同摩西在神的全家尽忠一样。'),
('CUV', '希伯来书', 58, 3, 3, '他比摩西算是更配多得荣耀，好像建造房屋的比房屋更尊荣；'),
('CUV', '希伯来书', 58, 3, 4, '因为房屋都必有人建造，但建造万物的就是神。'),
('CUV', '希伯来书', 58, 3, 5, '摩西为仆人，在神的全家诚然尽忠，为要证明将来必传说的事。'),
('CUV', '希伯来书', 58, 3, 6, '但基督为儿子，治理神的家；我们若将可夸的盼望和胆量坚持到底，便是他的家了。'),
('CUV', '希伯来书', 58, 3, 7, '圣灵有话说：你们今日若听他的话，'),
('CUV', '希伯来书', 58, 3, 8, '就不可硬著心，像在旷野惹他发怒、试探他的时候一样。'),
('CUV', '希伯来书', 58, 3, 9, '在那里，你们的祖宗试我探我，并且观看我的作为有四十年之久。'),
('CUV', '希伯来书', 58, 3, 10, '所以，我厌烦那世代的人，说：他们心里常常迷糊，竟不晓得我的作为！'),
('CUV', '希伯来书', 58, 3, 11, '我就在怒中起誓说；他们断不可进入我的安息。'),
('CUV', '希伯来书', 58, 3, 12, '弟兄们，你们要谨慎，免得你们中间或有人存著不信的恶心，把永生神离弃了。'),
('CUV', '希伯来书', 58, 3, 13, '总要趁著还有今日，天天彼此相劝，免得你们中间有人被罪迷惑，心里就刚硬了。'),
('CUV', '希伯来书', 58, 3, 14, '我们若将起初确实的信心坚持到底，就在基督里有分了。'),
('CUV', '希伯来书', 58, 3, 15, '经上说：你们今日若听他的话，就不可硬著心，像惹他发怒的日子一样。'),
('CUV', '希伯来书', 58, 3, 16, '那时，听见他话惹他发怒的是谁呢？岂不是跟著摩西从埃及出来的众人么？'),
('CUV', '希伯来书', 58, 3, 17, '神四十年之久，又厌烦谁呢？岂不是那些犯罪、尸首倒在旷野的人么？'),
('CUV', '希伯来书', 58, 3, 18, '又向谁起誓，不容他们进入他的安息呢；岂不是向那些不信从的人么？'),
('CUV', '希伯来书', 58, 3, 19, '这样看来，他们不能进入安息是因为不信的缘故了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 4, 1, '我们既蒙留下，有进入他安息的应许，就当畏惧，免得我们（原文是你们）中间或有人似乎是赶不上了。'),
('CUV', '希伯来书', 58, 4, 2, '因为有福音传给我们，像传给他们一样；只是所听见的道与他们无益，因为他们没有信心与所听见的道调和。'),
('CUV', '希伯来书', 58, 4, 3, '但我们已经相信的人得以进入那安息，正如神所说：我在怒中起誓说：他们断不可进入我的安息！其实造物之工，从创世以来已经成全了。'),
('CUV', '希伯来书', 58, 4, 4, '论到第七日，有一处说，到第七日神就歇了他一切的工。'),
('CUV', '希伯来书', 58, 4, 5, '又有一处说：他们断不可进入我的安息！'),
('CUV', '希伯来书', 58, 4, 6, '既有必进安息的人，那先前听见福音的，因为不信从，不得进去。'),
('CUV', '希伯来书', 58, 4, 7, '所以过了多年，就在大卫的书上，又限定一日，如以上所引的说：你们今日若听他的话，就不可硬著心。'),
('CUV', '希伯来书', 58, 4, 8, '若是约书亚已叫他们享了安息，后来神就不再提别的日子了。'),
('CUV', '希伯来书', 58, 4, 9, '这样看来，必另有一安息日的安息为神的子民存留。'),
('CUV', '希伯来书', 58, 4, 10, '因为那进入安息的，乃是歇了自己的工，正如神歇了他的工一样。'),
('CUV', '希伯来书', 58, 4, 11, '所以，我们务必竭力进入那安息，免得有人学那不信从的样子跌倒了。'),
('CUV', '希伯来书', 58, 4, 12, '神的道是活泼的，是有功效的，比一切两刃的剑更快，甚至魂与灵，骨节与骨髓，都能刺入、剖开，连心中的思念和主意都能辨明。'),
('CUV', '希伯来书', 58, 4, 13, '并且被造的没有一样在他面前不显然的；原来万物在那与我们有关系的主眼前，都是赤露敞开的。'),
('CUV', '希伯来书', 58, 4, 14, '我们既然有一位已经升入高天尊荣的大祭司，就是神的儿子耶稣，便当持定所承认的道。'),
('CUV', '希伯来书', 58, 4, 15, '因我们的大祭司并非不能体恤我们的软弱。他也曾凡事受过试探，与我们一样，只是他没有犯罪。'),
('CUV', '希伯来书', 58, 4, 16, '所以，我们只管坦然无惧的来到施恩的宝座前，为要得怜恤，蒙恩惠，作随时的帮助。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 5, 1, '凡从人间挑选的大祭司，是奉派替人办理属神的事，为要献上礼物和赎罪祭（或作：要为罪献上礼物和祭物）。'),
('CUV', '希伯来书', 58, 5, 2, '他能体谅那愚蒙的和失迷的人，因为他自己也是被软弱所困。'),
('CUV', '希伯来书', 58, 5, 3, '故此，他理当为百姓和自己献祭赎罪。'),
('CUV', '希伯来书', 58, 5, 4, '这大祭司的尊荣，没有人自取。惟要蒙神所召，像亚伦一样。'),
('CUV', '希伯来书', 58, 5, 5, '如此，基督也不是自取荣耀作大祭司，乃是在乎向他说你是我的儿子，我今日生你的那一位；'),
('CUV', '希伯来书', 58, 5, 6, '就如经上又有一处说：你是照著麦基洗德的等次永远为祭司。'),
('CUV', '希伯来书', 58, 5, 7, '基督在肉体的时候，既大声哀哭，流泪祷告，恳求那能救他免死的主，就因他的虔诚蒙了应允。'),
('CUV', '希伯来书', 58, 5, 8, '他虽然为儿子，还是因所受的苦难学了顺从。'),
('CUV', '希伯来书', 58, 5, 9, '他既得以完全，就为凡顺从他的人成了永远得救的根源、'),
('CUV', '希伯来书', 58, 5, 10, '并蒙神照著麦基洗德的等次称他为大祭司。'),
('CUV', '希伯来书', 58, 5, 11, '论到麦基洗德，我们有好些话，并且难以解明，因为你们听不进去。'),
('CUV', '希伯来书', 58, 5, 12, '看你们学习的工夫，本该作师傅，谁知还得有人将神圣言小学的开端另教导你们，并且成了那必须吃奶，不能吃干粮的人。'),
('CUV', '希伯来书', 58, 5, 13, '凡只能吃奶的都不熟练仁义的道理，因为他是婴孩；'),
('CUV', '希伯来书', 58, 5, 14, '惟独长大成人的才能吃干粮；他们的心窍习练得通达，就能分辨好歹了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 6, 1, '所以，我们应当离开基督道理的开端，竭力进到完全的地步，不必再立根基，就如那懊悔死行，信靠神、'),
('CUV', '希伯来书', 58, 6, 2, '各样洗礼、按手之礼、死人复活，以及永远审判各等教训。'),
('CUV', '希伯来书', 58, 6, 3, '神若许我们，我们必如此行。'),
('CUV', '希伯来书', 58, 6, 4, '论到那些已经蒙了光照、尝过天恩的滋味、又于圣灵有分，'),
('CUV', '希伯来书', 58, 6, 5, '并尝过神善道的滋味、觉悟来世权能的人，'),
('CUV', '希伯来书', 58, 6, 6, '若是离弃道理，就不能叫他们从新懊悔了。因为他们把神的儿子重钉十字架，明明的羞辱他。'),
('CUV', '希伯来书', 58, 6, 7, '就如一块田地，吃过屡次下的雨水，生长菜蔬，合乎耕种的人用，就从神得福；'),
('CUV', '希伯来书', 58, 6, 8, '若长荆棘和蒺藜，必被废弃，近于咒诅，结局就是焚烧。'),
('CUV', '希伯来书', 58, 6, 9, '亲爱的弟兄们，我们虽是这样说，却深信你们的行为强过这些，而且近乎得救。'),
('CUV', '希伯来书', 58, 6, 10, '因为神并非不公义，竟忘记你们所做的工和你们为他名所显的爱心，就是先前伺候圣徒，如今还是伺候。'),
('CUV', '希伯来书', 58, 6, 11, '我们愿你们各人都显出这样的殷勤，使你们有满足的指望，一直到底。'),
('CUV', '希伯来书', 58, 6, 12, '并且不懈怠，总要效法那些凭信心和忍耐承受应许的人。'),
('CUV', '希伯来书', 58, 6, 13, '当初神应许亚伯拉罕的时候，因为没有比自己更大可以指著起誓的，就指著自己起誓，说：'),
('CUV', '希伯来书', 58, 6, 14, '论福，我必赐大福给你；论子孙，我必叫你的子孙多起来。'),
('CUV', '希伯来书', 58, 6, 15, '这样，亚伯拉罕既恒久忍耐，就得了所应许的。'),
('CUV', '希伯来书', 58, 6, 16, '人都是指著比自己大的起誓，并且以起誓为实据，了结各样的争论。'),
('CUV', '希伯来书', 58, 6, 17, '照样，神愿意为那承受应许的人格外显明他的旨意是不更改的，就起誓为证。'),
('CUV', '希伯来书', 58, 6, 18, '藉这两件不更改的事，神决不能说谎，好叫我们这逃往避难所、持定摆在我们前头指望的人可以大得勉励。'),
('CUV', '希伯来书', 58, 6, 19, '我们有这指望，如同灵魂的锚，又坚固又牢靠，且通入幔内。'),
('CUV', '希伯来书', 58, 6, 20, '作先锋的耶稣，既照著麦基洗德的等次成了永远的大祭司，就为我们进入幔内。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 7, 1, '这麦基洗德就是撒冷王，又是至高神的祭司，本是长远为祭司的。他当亚伯拉罕杀败诸王回来的时候，就迎接他，给他祝福。'),
('CUV', '希伯来书', 58, 7, 2, '亚伯拉罕也将自己所得来的，取十分之一给他。他头一个名繙出来就是仁义王，他又名撒冷王，就是平安王的意思。'),
('CUV', '希伯来书', 58, 7, 3, '他无父，无母，无族谱，无生之始，无命之终，乃是与神的儿子相似。'),
('CUV', '希伯来书', 58, 7, 4, '你们想一想，先祖亚伯拉罕将自己所掳来上等之物取十分之一给他，这人是何等尊贵呢！'),
('CUV', '希伯来书', 58, 7, 5, '那得祭司职任的利未子孙，领命照例向百姓取十分之一，这百姓是自己的弟兄，虽是从亚伯拉罕身（原文是腰）中生的，还是照例取十分之一；'),
('CUV', '希伯来书', 58, 7, 6, '独有麦基洗德，不与他们同谱，倒收纳亚伯拉罕的十分之一，为那蒙应许的亚伯拉罕祝福。'),
('CUV', '希伯来书', 58, 7, 7, '从来位分大的给位分小的祝福，这是驳不倒的理。'),
('CUV', '希伯来书', 58, 7, 8, '在这里收十分之一的都是必死的人；但在那里收十分之一的，有为他作见证的说，他是活的；'),
('CUV', '希伯来书', 58, 7, 9, '并且可说那受十分之一的利未，也是藉著亚伯拉罕纳了十分之一。'),
('CUV', '希伯来书', 58, 7, 10, '因为麦基洗德迎接亚伯拉罕的时候，利未已经在他先祖的身（原文是腰）中。'),
('CUV', '希伯来书', 58, 7, 11, '从前百姓在利未人祭司职任以下受律法，倘若藉这职任能得完全，又何用另外兴起一位祭司，照麦基洗德的等次，不照亚伦的等次呢？'),
('CUV', '希伯来书', 58, 7, 12, '祭司的职任既已更改，律法也必须更改。'),
('CUV', '希伯来书', 58, 7, 13, '因为这话所指的人本属别的支派，那支派里从来没有一人伺候祭坛。'),
('CUV', '希伯来书', 58, 7, 14, '我们的主分明是从犹大出来的；但这支派，摩西并没有提到祭司。'),
('CUV', '希伯来书', 58, 7, 15, '倘若照麦基洗德的样式，另外兴起一位祭司来，我的话更是显而易见的了。'),
('CUV', '希伯来书', 58, 7, 16, '他成为祭司，并不是照属肉体的条例，乃是照无穷（原文是不能毁坏）之生命的大能。'),
('CUV', '希伯来书', 58, 7, 17, '因为有给他作见证的说：你是照著麦基洗德的等次永远为祭司。'),
('CUV', '希伯来书', 58, 7, 18, '先前的条例，因软弱无益，所以废掉了，'),
('CUV', '希伯来书', 58, 7, 19, '（律法原来一无所成）就引进了更美的指望；靠这指望，我们便可以进到神面前。'),
('CUV', '希伯来书', 58, 7, 20, '再者，耶稣为祭司，并不是不起誓立的。'),
('CUV', '希伯来书', 58, 7, 21, '至于那些祭司，原不是起誓立的，只有耶稣是起誓立的；因为那立他的对他说：主起了誓，决不后悔，你是永远为祭司。'),
('CUV', '希伯来书', 58, 7, 22, '既是起誓立的，耶稣就作了更美之约的中保。'),
('CUV', '希伯来书', 58, 7, 23, '那些成为祭司的，数目本来多，是因为有死阻隔，不能长久。'),
('CUV', '希伯来书', 58, 7, 24, '这位既是永远常存的，他祭司的职任就长久不更换。'),
('CUV', '希伯来书', 58, 7, 25, '凡靠著他进到神面前的人，他都能拯救到底；因为他是长远活著，替他们祈求。'),
('CUV', '希伯来书', 58, 7, 26, '像这样圣洁、无邪恶、无玷污、远离罪人、高过诸天的大祭司，原是与我们合宜的。'),
('CUV', '希伯来书', 58, 7, 27, '他不像那些大祭司，每日必须先为自己的罪，后为百姓的罪献祭；因为他只一次将自己献上，就把这事成全了。'),
('CUV', '希伯来书', 58, 7, 28, '律法本是立软弱的人为大祭司；但在律法以后起誓的话，是立儿子为大祭司，乃是成全到永远的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 8, 1, '我们所讲的事，其中第一要紧的，就是我们有这样的大祭司，已经坐在天上至大者宝座的右边，'),
('CUV', '希伯来书', 58, 8, 2, '在圣所，就是真帐幕里，作执事；这帐幕是主所支的，不是人所支的。'),
('CUV', '希伯来书', 58, 8, 3, '凡大祭司都是为献礼物和祭物设立的，所以这位大祭司也必须有所献的。'),
('CUV', '希伯来书', 58, 8, 4, '他若在地上，必不得为祭司，因为已经有照律法献礼物的祭司。'),
('CUV', '希伯来书', 58, 8, 5, '他们供奉的事本是天上事的形状和影像，正如摩西将要造帐幕的时候，蒙神警戒他，说：你要谨慎，作各样的物件都要照著在山上指示你的样式。'),
('CUV', '希伯来书', 58, 8, 6, '如今耶稣所得的职任是更美的，正如他作更美之约的中保；这约原是凭更美之应许立的。'),
('CUV', '希伯来书', 58, 8, 7, '那前约若没有瑕疵，就无处寻求后约了。'),
('CUV', '希伯来书', 58, 8, 8, '所以主指责他的百姓说（或作：所以主指前约的缺欠说）：日子将到，我要与以色列家和犹大家另立新约，'),
('CUV', '希伯来书', 58, 8, 9, '不像我拉著他们祖宗的手，领他们出埃及的时候，与他们所立的约。因为他们不恒心守我的约，我也不理他们。这是主说的。'),
('CUV', '希伯来书', 58, 8, 10, '主又说：那些日子以后，我与以色列家所立的约乃是这样：我要将我的律法放在他们里面，写在他们心上；我要作他们的神；他们要作我的子民。'),
('CUV', '希伯来书', 58, 8, 11, '他们不用各人教导自己的乡邻和自己的弟兄，说：你该认识主；因为他们从最小的到至大的，都必认识我。'),
('CUV', '希伯来书', 58, 8, 12, '我要宽恕他们的不义，不再记念他们的罪愆。'),
('CUV', '希伯来书', 58, 8, 13, '既说新约。就以前约为旧了；但那渐旧渐衰的，就必快归无有了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 9, 1, '原来前约有礼拜的条例和属世界的圣幕。'),
('CUV', '希伯来书', 58, 9, 2, '因为有预备的帐幕，头一层叫作圣所，里面有灯台、桌子，和陈设饼。'),
('CUV', '希伯来书', 58, 9, 3, '第二幔子后又有一层帐幕，叫作至圣所，'),
('CUV', '希伯来书', 58, 9, 4, '有金香炉（或作：坛），有包金的约柜，柜里有盛吗哪的金罐和亚伦发过芽的杖，并两块约版；'),
('CUV', '希伯来书', 58, 9, 5, '柜上面有荣耀基路伯的影罩著施恩（原文作：蔽罪）座。这几件我现在不能一一细说。'),
('CUV', '希伯来书', 58, 9, 6, '这些物件既如此预备齐了，众祭司就常进头一层帐幕，行拜神的礼。'),
('CUV', '希伯来书', 58, 9, 7, '至于第二层帐幕，惟有大祭司一年一次独自进去，没有不带著血为自己和百姓的过错献上。'),
('CUV', '希伯来书', 58, 9, 8, '圣灵用此指明，头一层帐幕仍存的时候，进入至圣所的路还未显明。'),
('CUV', '希伯来书', 58, 9, 9, '那头一层帐幕作现今的一个表样，所献的礼物和祭物，就著良心说，都不能叫礼拜的人得以完全。'),
('CUV', '希伯来书', 58, 9, 10, '这些事，连那饮食和诸般洗濯的规矩，都不过是属肉体的条例，命定到振兴的时候为止。'),
('CUV', '希伯来书', 58, 9, 11, '但现在基督已经来到，作了将来美事的大祭司，经过那更大更全备的帐幕，不是人手所造、也不是属乎这世界的；'),
('CUV', '希伯来书', 58, 9, 12, '并且不用山羊和牛犊的血，乃用自己的血，只一次进入圣所，成了永远赎罪的事。'),
('CUV', '希伯来书', 58, 9, 13, '若山羊和公牛的血，并母牛犊的灰，洒在不洁的人身上，尚且叫人成圣，身体洁净，'),
('CUV', '希伯来书', 58, 9, 14, '何况基督藉著永远的灵，将自己无瑕无疵献给神，他的血岂不更能洗净你们的心（原文是良心），除去你们的死行，使你们事奉那永生神么？'),
('CUV', '希伯来书', 58, 9, 15, '为此，他作了新约的中保，既然受死赎了人在前约之时所犯的罪过，便叫蒙召之人得著所应许永远的产业。'),
('CUV', '希伯来书', 58, 9, 16, '凡有遗命必须等到留遗命（遗命：原文与约字同）的人死了；'),
('CUV', '希伯来书', 58, 9, 17, '因为人死了，遗命才有效力，若留遗命的尚在，那遗命还有用处么？'),
('CUV', '希伯来书', 58, 9, 18, '所以，前约也不是不用血立的；'),
('CUV', '希伯来书', 58, 9, 19, '因为摩西当日照著律法将各样诫命传给众百姓，就拿朱红色绒和牛膝草，把牛犊山羊的血和水洒在书上，又洒在众百姓身上，说：'),
('CUV', '希伯来书', 58, 9, 20, '这血就是神与你们立约的凭据。'),
('CUV', '希伯来书', 58, 9, 21, '他又照样把血洒在帐幕和各样器皿上。'),
('CUV', '希伯来书', 58, 9, 22, '按著律法，凡物差不多都是用血洁净的；若不流血，罪就不得赦免了。'),
('CUV', '希伯来书', 58, 9, 23, '照著天上样式作的物件必须用这些祭物去洁净；但那天上的本物自然当用更美的祭物去洁净。'),
('CUV', '希伯来书', 58, 9, 24, '因为基督并不是进了人手所造的圣所（这不过是真圣所的影像），乃是进了天堂，如今为我们显在神面前；'),
('CUV', '希伯来书', 58, 9, 25, '也不是多次将自己献上，像那大祭司每年带著牛羊的血（牛羊的血：原文作不是自己的血）进入圣所，'),
('CUV', '希伯来书', 58, 9, 26, '如果这样，他从创世以来，就必多次受苦了。但如今在这末世显现一次，把自己献为祭，好除掉罪。'),
('CUV', '希伯来书', 58, 9, 27, '按著定命，人人都有一死，死后且有审判。'),
('CUV', '希伯来书', 58, 9, 28, '像这样，基督既然一次被献，担当了多人的罪，将来要向那等候他的人第二次显现，并与罪无关，乃是为拯救他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 10, 1, '律法既是将来美事的影儿，不是本物的真像，总不能藉著每年常献一样的祭物叫那近前来的人得以完全。'),
('CUV', '希伯来书', 58, 10, 2, '若不然，献祭的事岂不早已止住了么？因为礼拜的人，良心既被洁净，就不再觉得有罪了。'),
('CUV', '希伯来书', 58, 10, 3, '但这些祭物是叫人每年想起罪来；'),
('CUV', '希伯来书', 58, 10, 4, '因为公牛和山羊的血，断不能除罪。'),
('CUV', '希伯来书', 58, 10, 5, '所以基督到世上来的时候，就说：神阿，祭物和礼物是你不愿意的；你曾给我预备了身体。'),
('CUV', '希伯来书', 58, 10, 6, '燔祭和赎罪祭是你不喜欢的。'),
('CUV', '希伯来书', 58, 10, 7, '那时我说：神阿，我来了，为要照你的旨意行；我的事在经卷上已经记载了。'),
('CUV', '希伯来书', 58, 10, 8, '以上说：祭物和礼物，燔祭和赎罪祭，是你不愿意的，也是你不喜欢的（这都是按著律法献的）；'),
('CUV', '希伯来书', 58, 10, 9, '后又说：我来了为要照你的旨意行；可见他是除去在先的，为要立定在后的。'),
('CUV', '希伯来书', 58, 10, 10, '我们凭这旨意，靠耶稣基督，只一次献上他的身体，就得以成圣。'),
('CUV', '希伯来书', 58, 10, 11, '凡祭司天天站著事奉神，屡次献上一样的祭物，这祭物永不能除罪。'),
('CUV', '希伯来书', 58, 10, 12, '但基督献了一次永远的赎罪祭，就在神的右边坐下了。'),
('CUV', '希伯来书', 58, 10, 13, '从此，等候他仇敌成了他的脚凳。'),
('CUV', '希伯来书', 58, 10, 14, '因为他一次献祭，便叫那得以成圣的人永远完全。'),
('CUV', '希伯来书', 58, 10, 15, '圣灵也对我们作见证；因为他既已说过：'),
('CUV', '希伯来书', 58, 10, 16, '主说：那些日子以后，我与他们所立的约乃是这样：我要将我的律法写在他们心上，又要放在他们的里面。'),
('CUV', '希伯来书', 58, 10, 17, '以后就说：我不再记念他们的罪愆和他们的过犯。'),
('CUV', '希伯来书', 58, 10, 18, '这些罪过既已赦免，就不用再为罪献祭了。'),
('CUV', '希伯来书', 58, 10, 19, '弟兄们，我们既因耶稣的血得以坦然进入至圣所，'),
('CUV', '希伯来书', 58, 10, 20, '是藉著他给我们开了一条又新又活的路，从幔子经过，这幔子就是他的身体。'),
('CUV', '希伯来书', 58, 10, 21, '又有一位大祭司治理神的家！'),
('CUV', '希伯来书', 58, 10, 22, '并我们心中天良的亏欠已经洒去，身体用清水洗净了，就当存著诚心和充足的信心来到神面前；'),
('CUV', '希伯来书', 58, 10, 23, '也要坚守我们所承认的指望，不至摇动，因为那应许我们的是信实的。'),
('CUV', '希伯来书', 58, 10, 24, '又要彼此相顾，激发爱心，勉励行善。'),
('CUV', '希伯来书', 58, 10, 25, '你们不可停止聚会，好像那些停止惯了的人，倒要彼此劝勉，既知道（原文是看见）那日子临近，就更当如此。'),
('CUV', '希伯来书', 58, 10, 26, '因为我们得知真道以后，若故意犯罪，赎罪的祭就再没有了；'),
('CUV', '希伯来书', 58, 10, 27, '惟有战惧等候审判和那烧灭众敌人的烈火。'),
('CUV', '希伯来书', 58, 10, 28, '人干犯摩西的律法，凭两三个见证人，尚且不得怜恤而死，'),
('CUV', '希伯来书', 58, 10, 29, '何况人践踏神的儿子，将那使他成圣之约的血当作平常，又亵慢施恩的圣灵，你们想，他要受的刑罚该怎样加重呢！'),
('CUV', '希伯来书', 58, 10, 30, '因为我们知道谁说：伸冤在我，我必报应；又说：主要审判他的百姓。'),
('CUV', '希伯来书', 58, 10, 31, '落在永生神的手里，真是可怕的！'),
('CUV', '希伯来书', 58, 10, 32, '你们要追念往日，蒙了光照以后所忍受大争战的各样苦难：'),
('CUV', '希伯来书', 58, 10, 33, '一面被毁谤，遭患难，成了戏景，叫众人观看；一面陪伴那些受这样苦难的人。'),
('CUV', '希伯来书', 58, 10, 34, '因为你们体恤了那些被捆锁的人，并且你们的家业被人抢去，也甘心忍受，知道自己有更美长存的家业。'),
('CUV', '希伯来书', 58, 10, 35, '所以，你们不可丢弃勇敢的心；存这样的心必得大赏赐。'),
('CUV', '希伯来书', 58, 10, 36, '你们必须忍耐，使你们行完了神的旨意，就可以得著所应许的。'),
('CUV', '希伯来书', 58, 10, 37, '因为还有一点点时候，那要来的就来，并不迟延；'),
('CUV', '希伯来书', 58, 10, 38, '只是义人（有古卷：我的义人）必因信得生。他若退后，我心里就不喜欢他。'),
('CUV', '希伯来书', 58, 10, 39, '我们却不是退后入沉沦的那等人，乃是有信心以致灵魂得救的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 11, 1, '信就是所望之事的实底，是未见之事的确据。'),
('CUV', '希伯来书', 58, 11, 2, '古人在这信上得了美好的证据。'),
('CUV', '希伯来书', 58, 11, 3, '我们因著信，就知道诸世界是藉神话造成的；这样，所看见的，并不是从显然之物造出来的。'),
('CUV', '希伯来书', 58, 11, 4, '亚伯因著信，献祭与神，比该隐所献的更美，因此便得了称义的见证，就是神指他礼物作的见证。他虽然死了，却因这信，仍旧说话。'),
('CUV', '希伯来书', 58, 11, 5, '以诺因著信，被接去，不至于见死，人也找不著他，因为神已经把他接去了；只是他被接去以先，已经得了神喜悦他的明证。'),
('CUV', '希伯来书', 58, 11, 6, '人非有信，就不能得神的喜悦；因为到神面前来的人必须信有神，且信他赏赐那寻求他的人。'),
('CUV', '希伯来书', 58, 11, 7, '挪亚因著信，既蒙神指示他未见的事，动了敬畏的心，预备了一只方舟，使他全家得救。因此就定了那世代的罪，自己也承受了那从信而来的义。'),
('CUV', '希伯来书', 58, 11, 8, '亚伯拉罕因著信，蒙召的时候就遵命出去，往将来要得为业的地方去；出去的时候，还不知往那里去。'),
('CUV', '希伯来书', 58, 11, 9, '他因著信，就在所应许之地作客，好像在异地居住帐棚，与那同蒙一个应许的以撒、雅各一样。'),
('CUV', '希伯来书', 58, 11, 10, '因为他等候那座有根基的城，就是神所经营所建造的。'),
('CUV', '希伯来书', 58, 11, 11, '因著信，连撒拉自己，虽然过了生育的岁数，还能怀孕，因他以为那应许他的是可信的。'),
('CUV', '希伯来书', 58, 11, 12, '所以从一个仿佛已死的人就生出子孙，如同天上的星那样众多，海边的沙那样无数。'),
('CUV', '希伯来书', 58, 11, 13, '这些人都是存著信心死的，并没有得著所应许的；却从远处望见，且欢喜迎接，又承认自己在世上是客旅，是寄居的。'),
('CUV', '希伯来书', 58, 11, 14, '说这样话的人是表明自己要找一个家乡。'),
('CUV', '希伯来书', 58, 11, 15, '他们若想念所离开的家乡，还有可以回去的机会。'),
('CUV', '希伯来书', 58, 11, 16, '他们却羡慕一个更美的家乡，就是在天上的。所以神被称为他们的神，并不以为耻，因为他已经给他们预备了一座城。'),
('CUV', '希伯来书', 58, 11, 17, '亚伯拉罕因著信，被试验的时候，就把以撒献上；这便是那欢喜领受应许的，将自己独生的儿子献上。'),
('CUV', '希伯来书', 58, 11, 18, '论到这儿子，曾有话说：从以撒生的才要称为你的后裔。'),
('CUV', '希伯来书', 58, 11, 19, '他以为神还能叫人从死里复活；他也仿佛从死中得回他的儿子来。'),
('CUV', '希伯来书', 58, 11, 20, '以撒因著信，就指著将来的事给雅各、以扫祝福。'),
('CUV', '希伯来书', 58, 11, 21, '雅各因著信，临死的时候，给约瑟的两个儿子各自祝福，扶著杖头敬拜神。'),
('CUV', '希伯来书', 58, 11, 22, '约瑟因著信，临终的时候，提到以色列族将来要出埃及，并为自己的骸骨留下遗命。'),
('CUV', '希伯来书', 58, 11, 23, '摩西生下来，他的父母见他是个俊美的孩子，就因著信，把他藏了三个月，并不怕王命。'),
('CUV', '希伯来书', 58, 11, 24, '摩西因著信，长大了就不肯称为法老女儿之子。'),
('CUV', '希伯来书', 58, 11, 25, '他宁可和神的百姓同受苦害，也不愿暂时享受罪中之乐。'),
('CUV', '希伯来书', 58, 11, 26, '他看为基督受的凌辱比埃及的财物更宝贵，因他想望所要得的赏赐。'),
('CUV', '希伯来书', 58, 11, 27, '他因著信，就离开埃及，不怕王怒；因为他恒心忍耐，如同看见那不能看见的主。'),
('CUV', '希伯来书', 58, 11, 28, '他因著信，就守（或作：立）逾越节，行洒血的礼，免得那灭长子的临近以色列人。'),
('CUV', '希伯来书', 58, 11, 29, '他们因著信，过红海如行干地；埃及人试著要过去，就被吞灭了。'),
('CUV', '希伯来书', 58, 11, 30, '以色列人因著信，围绕耶利哥城七日，城墙就倒塌了。'),
('CUV', '希伯来书', 58, 11, 31, '妓女喇合因著信，曾和和平平的接待探子，就不与那些不顺从的人一同灭亡。'),
('CUV', '希伯来书', 58, 11, 32, '我又何必再说呢？若要一一细说，基甸、巴拉、参孙、耶弗他、大卫、撒母耳，和众先知的事，时候就不够了。'),
('CUV', '希伯来书', 58, 11, 33, '他们因著信，制伏了敌国，行了公义，得了应许，堵了狮子的口，'),
('CUV', '希伯来书', 58, 11, 34, '灭了烈火的猛势，脱了刀剑的锋刃；软弱变为刚强，争战显出勇敢，打退外邦的全军。'),
('CUV', '希伯来书', 58, 11, 35, '有妇人得自己的死人复活。又有人忍受严刑，不肯苟且得释放（原文是赎），为要得著更美的复活。'),
('CUV', '希伯来书', 58, 11, 36, '又有人忍受戏弄、鞭打、捆锁、监禁、各等的磨炼，'),
('CUV', '希伯来书', 58, 11, 37, '被石头打死，被锯锯死，受试探，被刀杀，披著绵羊山羊的皮各处奔跑，受穷乏、患难、苦害，'),
('CUV', '希伯来书', 58, 11, 38, '在旷野、山岭、山洞、地穴，飘流无定，本是世界不配有的人。'),
('CUV', '希伯来书', 58, 11, 39, '这些人都是因信得了美好的证据，却仍未得著所应许的；'),
('CUV', '希伯来书', 58, 11, 40, '因为神给我们预备了更美的事，叫他们若不与我们同得，就不能完全。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 12, 1, '我们既有这许多的见证人，如同云彩围著我们，就当放下各样的重担，脱去容易缠累我们的罪，存心忍耐，奔那摆在我们前头的路程，'),
('CUV', '希伯来书', 58, 12, 2, '仰望为我们信心创始成终的耶稣（或作：仰望那将真道创始成终的耶稣）。他因那摆在前面的喜乐，就轻看羞辱，忍受了十字架的苦难，便坐在神宝座的右边。'),
('CUV', '希伯来书', 58, 12, 3, '那忍受罪人这样顶撞的，你们要思想，免得疲倦灰心。'),
('CUV', '希伯来书', 58, 12, 4, '你们与罪恶相争，还没有抵挡到流血的地步。'),
('CUV', '希伯来书', 58, 12, 5, '你们又忘了那劝你们如同劝儿子的话，说：我儿，你不可轻看主的管教，被他责备的时候也不可灰心；'),
('CUV', '希伯来书', 58, 12, 6, '因为主所爱的，他必管教，又鞭打凡所收纳的儿子。'),
('CUV', '希伯来书', 58, 12, 7, '你们所忍受的，是神管教你们，待你们如同待儿子。焉有儿子不被父亲管教的呢？'),
('CUV', '希伯来书', 58, 12, 8, '管教原是众子所共受的，你们若不受管教，就是私子，不是儿子了。'),
('CUV', '希伯来书', 58, 12, 9, '再者，我们曾有生身的父管教我们，我们尚且敬重他，何况万灵的父，我们岂不更当顺服他得生么？'),
('CUV', '希伯来书', 58, 12, 10, '生身的父都是暂随己意管教我们；惟有万灵的父管教我们，是要我们得益处，使我们在他的圣洁上有分。'),
('CUV', '希伯来书', 58, 12, 11, '凡管教的事，当时不觉得快乐，反觉得愁苦；后来却为那经练过的人结出平安的果子，就是义。'),
('CUV', '希伯来书', 58, 12, 12, '所以，你们要把下垂的手、发酸的腿、挺起来；'),
('CUV', '希伯来书', 58, 12, 13, '也要为自己的脚，把道路修直了，使瘸子不至歪脚（或作：差路），反得痊愈。'),
('CUV', '希伯来书', 58, 12, 14, '你们要追求与众人和睦，并要追求圣洁；非圣洁没有人能见主。'),
('CUV', '希伯来书', 58, 12, 15, '又要谨慎，恐怕有人失了神的恩；恐怕有毒根生出来扰乱你们，因此叫众人沾染污秽；'),
('CUV', '希伯来书', 58, 12, 16, '恐怕有淫乱的，有贪恋世俗如以扫的，他因一点食物把自己长子的名分卖了。'),
('CUV', '希伯来书', 58, 12, 17, '后来想要承受父所祝的福，竟被弃绝，虽然号哭切求，却得不著门路使他父亲的心意回转。这是你们知道的。'),
('CUV', '希伯来书', 58, 12, 18, '你们原不是来到那能摸的山；此山有火燄、密云、黑暗、暴风、'),
('CUV', '希伯来书', 58, 12, 19, '角声与说话的声音。那些听见这声音的，都求不要再向他们说话；'),
('CUV', '希伯来书', 58, 12, 20, '因为他们当不起所命他们的话，说：靠近这山的，即便是走兽，也要用石头打死。'),
('CUV', '希伯来书', 58, 12, 21, '所见的极其可怕，甚至摩西说：我甚是恐惧战兢。'),
('CUV', '希伯来书', 58, 12, 22, '你们乃是来到锡安山，永生神的城邑，就是天上的耶路撒冷。那里有千万的天使，'),
('CUV', '希伯来书', 58, 12, 23, '有名录在天上诸长子之会所共聚的总会，有审判众人的神和被成全之义人的灵魂，'),
('CUV', '希伯来书', 58, 12, 24, '并新约的中保耶稣，以及所洒的血；这血所说的比亚伯的血所说的更美。'),
('CUV', '希伯来书', 58, 12, 25, '你们总要谨慎，不可弃绝那向你们说话的。因为，那些弃绝在地上警戒他们的尚且不能逃罪，何况我们违背那从天上警戒我们的呢？'),
('CUV', '希伯来书', 58, 12, 26, '当时他的声音震动了地，但如今他应许说：再一次我不单要震动地，还要震动天。'),
('CUV', '希伯来书', 58, 12, 27, '这再一次的话，是指明被震动的，就是受造之物都要挪去，使那不被震动的常存。'),
('CUV', '希伯来书', 58, 12, 28, '所以我们既得了不能震动的国，就当感恩，照神所喜悦的，用虔诚、敬畏的心事奉神。'),
('CUV', '希伯来书', 58, 12, 29, '因为我们的神乃是烈火。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '希伯来书', 58, 13, 1, '你们务要常存弟兄相爱的心。'),
('CUV', '希伯来书', 58, 13, 2, '不可忘记用爱心接待客旅；因为曾有接待客旅的，不知不觉就接待了天使。'),
('CUV', '希伯来书', 58, 13, 3, '你们要记念被捆绑的人，好像与他们同受捆绑；，也要记念遭苦害的人，想到自己也在肉身之内。'),
('CUV', '希伯来书', 58, 13, 4, '婚姻，人人都当尊重，床也不可污秽；因为苟合行淫的人，神必要审判。'),
('CUV', '希伯来书', 58, 13, 5, '你们存心不可贪爱钱财，要以自己所有的为足；因为主曾说：我总不撇下你，也不丢弃你。'),
('CUV', '希伯来书', 58, 13, 6, '所以我们可以放胆说：主是帮助我的，我必不惧怕；人能把我怎么样呢？'),
('CUV', '希伯来书', 58, 13, 7, '从前引导你们、传神之道给你们的人，你们要想念他们，效法他们的信心，留心看他们为人的结局。'),
('CUV', '希伯来书', 58, 13, 8, '耶稣基督，昨日、今日、一直到永远、是一样的。'),
('CUV', '希伯来书', 58, 13, 9, '你们不要被那诸般怪异的教训勾引了去；因为人心靠恩得坚固才是好的，并不是靠饮食。那在饮食上专心的从来没有得著益处。'),
('CUV', '希伯来书', 58, 13, 10, '我们有一祭坛，上面的祭物是那些在帐幕中供职的人不可同吃的。'),
('CUV', '希伯来书', 58, 13, 11, '原来牲畜的血被大祭司带入圣所作赎罪祭；牲畜的身子被烧在营外。'),
('CUV', '希伯来书', 58, 13, 12, '所以，耶稣要用自己的血叫百姓成圣，也就在城门外受苦。'),
('CUV', '希伯来书', 58, 13, 13, '这样，我们也当出到营外，就了他去，忍受他所受的凌辱。'),
('CUV', '希伯来书', 58, 13, 14, '我们在这里本没有常存的城，乃是寻求那将来的城。'),
('CUV', '希伯来书', 58, 13, 15, '我们应当靠著耶稣，常常以颂赞为祭献给神，这就是那承认主名之人嘴唇的果子。'),
('CUV', '希伯来书', 58, 13, 16, '只是不可忘记行善和捐输的事；因为这样的祭，是神所喜悦的。'),
('CUV', '希伯来书', 58, 13, 17, '你们要依从那些引导你们的，且要顺服；因他们为你们的灵魂时刻儆醒，好像那将来交账的人。你们要使他们交的时候有快乐，不至忧愁；若忧愁就与你们无益了。'),
('CUV', '希伯来书', 58, 13, 18, '请你们为我们祷告，因我们自觉良心无亏，愿意凡事按正道而行。'),
('CUV', '希伯来书', 58, 13, 19, '我更求你们为我祷告，使我快些回到你们那里去。'),
('CUV', '希伯来书', 58, 13, 20, '但愿赐平安的神，就是那凭永约之血、使群羊的大牧人─我主耶稣从死里复活的神，'),
('CUV', '希伯来书', 58, 13, 21, '在各样善事上成全你们，叫你们遵行他的旨意；又藉著耶稣基督在你们心里行他所喜悦的事。愿荣耀归给他，直到永永远远。阿们！'),
('CUV', '希伯来书', 58, 13, 22, '弟兄们，我略略写信给你们，望你们听我劝勉的话。'),
('CUV', '希伯来书', 58, 13, 23, '你们该知道，我们的兄弟提摩太已经释放了；他若快来，我必同他去见你们。'),
('CUV', '希伯来书', 58, 13, 24, '请你们问引导你们的诸位和众圣徒安。从义大利来的人也问你们安。'),
('CUV', '希伯来书', 58, 13, 25, '愿恩惠常与你们众人同在。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅各书', 59, 1, 1, '作神和主耶稣基督仆人的雅各请散住十二个支派之人的安。'),
('CUV', '雅各书', 59, 1, 2, '我的弟兄们，你们落在百般试炼中，都要以为大喜乐；'),
('CUV', '雅各书', 59, 1, 3, '因为知道你们的信心经过试验，就生忍耐。'),
('CUV', '雅各书', 59, 1, 4, '但忍耐也当成功，使你们成全、完备，毫无缺欠。'),
('CUV', '雅各书', 59, 1, 5, '你们中间若有缺少智慧的，应当求那厚赐与众人、也不斥责人的神，主就必赐给他。'),
('CUV', '雅各书', 59, 1, 6, '只要凭著信心求，一点不疑惑；因为那疑惑的人，就像海中的波浪，被风吹动翻腾。'),
('CUV', '雅各书', 59, 1, 7, '这样的人不要想从主那里得甚么。'),
('CUV', '雅各书', 59, 1, 8, '心怀二意的人，在他一切所行的路上都没有定见。'),
('CUV', '雅各书', 59, 1, 9, '卑微的弟兄升高，就该喜乐；'),
('CUV', '雅各书', 59, 1, 10, '富足的降卑，也该如此；因为他必要过去，如同草上的花一样。'),
('CUV', '雅各书', 59, 1, 11, '太阳出来，热风刮起，草就枯干，花也凋谢，美容就消没了；那富足的人，在他所行的事上也要这样衰残。'),
('CUV', '雅各书', 59, 1, 12, '忍受试探的人是有福的，因为他经过试验以后，必得生命的冠冕；这是主应许给那些爱他之人的。'),
('CUV', '雅各书', 59, 1, 13, '人被试探，不可说：「我是被神试探」；因为神不能被恶试探，他也不试探人。'),
('CUV', '雅各书', 59, 1, 14, '但各人被试探，乃是被自己的私欲牵引诱惑的。'),
('CUV', '雅各书', 59, 1, 15, '私欲既怀了胎，就生出罪来；罪既长成，就生出死来。'),
('CUV', '雅各书', 59, 1, 16, '我亲爱的弟兄们，不要看错了。'),
('CUV', '雅各书', 59, 1, 17, '各样美善的恩赐和各样全备的赏赐都是从上头来的，从众光之父那里降下来的；在他并没有改变，也没有转动的影儿。'),
('CUV', '雅各书', 59, 1, 18, '他按自己的旨意，用真道生了我们，叫我们在他所造的万物中好像初熟的果子。'),
('CUV', '雅各书', 59, 1, 19, '我亲爱的弟兄们，这是你们所知道的，但你们各人要快快的听，慢慢的说，慢慢的动怒，'),
('CUV', '雅各书', 59, 1, 20, '因为人的怒气并不成就神的义。'),
('CUV', '雅各书', 59, 1, 21, '所以，你们要脱去一切的污秽和盈余的邪恶，存温柔的心领受那所栽种的道，就是能救你们灵魂的道。'),
('CUV', '雅各书', 59, 1, 22, '只是你们要行道，不要单单听道，自己欺哄自己。'),
('CUV', '雅各书', 59, 1, 23, '因为听道而不行道的，就像人对著镜子看自己本来的面目，'),
('CUV', '雅各书', 59, 1, 24, '看见，走后，随即忘了他的相貌如何。'),
('CUV', '雅各书', 59, 1, 25, '惟有详细察看那全备、使人自由之律法的，并且时常如此，这人既不是听了就忘，乃是实在行出来，就在他所行的事上必然得福。'),
('CUV', '雅各书', 59, 1, 26, '若有人自以为虔诚，却不勒住他的舌头，反欺哄自己的心，这人的虔诚是虚的。'),
('CUV', '雅各书', 59, 1, 27, '在神我们的父面前，那清洁没有玷污的虔诚，就是看顾在患难中的孤儿寡妇，并且保守自己不沾染世俗。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅各书', 59, 2, 1, '我的弟兄们，你们信奉我们荣耀的主耶稣基督，便不可按著外貌待人。'),
('CUV', '雅各书', 59, 2, 2, '若有一个人带著金戒指，穿著华美衣服，进你们的会堂去；又有一个穷人穿著肮脏衣服也进去；'),
('CUV', '雅各书', 59, 2, 3, '你们就重看那穿华美衣服的人，说「请坐在这好位上」；又对那穷人说：「你站在那里」，或「坐在我脚凳下边。」'),
('CUV', '雅各书', 59, 2, 4, '这岂不是你们偏心待人，用恶意断定人么？'),
('CUV', '雅各书', 59, 2, 5, '我亲爱的弟兄们，请听，神岂不是拣选了世上的贫穷人，叫他们在信上富足，并承受他所应许给那些爱他之人的国么？'),
('CUV', '雅各书', 59, 2, 6, '你们反倒羞辱贫穷人。那富足人岂不是欺压你们、拉你们到公堂去么？'),
('CUV', '雅各书', 59, 2, 7, '他们不是亵渎你们所敬奉（所敬奉：或作被称）的尊名么？'),
('CUV', '雅各书', 59, 2, 8, '经上记著说：「要爱人如己。」你们若全守这至尊的律法，才是好的。'),
('CUV', '雅各书', 59, 2, 9, '但你们若按外貌待人，便是犯罪，被律法定为犯法的。'),
('CUV', '雅各书', 59, 2, 10, '因为凡遵守全律法的，只在一条上跌倒，他就是犯了众条。'),
('CUV', '雅各书', 59, 2, 11, '原来那说「不可奸淫」的，也说「不可杀人」；你就是不奸淫，却杀人，仍是成了犯律法的。'),
('CUV', '雅各书', 59, 2, 12, '你们既然要按使人自由的律法受审判，就该照这律法说话行事。'),
('CUV', '雅各书', 59, 2, 13, '因为那不怜悯人的，也要受无怜悯的审判；怜悯原是向审判夸胜。'),
('CUV', '雅各书', 59, 2, 14, '我的弟兄们，若有人说自己有信心，却没有行为，有甚么益处呢？这信心能救他么？'),
('CUV', '雅各书', 59, 2, 15, '若是弟兄或是姐妹，赤身露体，又缺了日用的饮食；'),
('CUV', '雅各书', 59, 2, 16, '你们中间有人对他们说：「平平安安的去罢！愿你们穿得暖，吃得饱」；却不给他们身体所需用的，这有甚么益处呢？'),
('CUV', '雅各书', 59, 2, 17, '这样，信心若没有行为就是死的。'),
('CUV', '雅各书', 59, 2, 18, '必有人说：「你有信心，我有行为；你将你没有行为的信心指给我看，我便藉著我的行为，将我的信心指给你看。」'),
('CUV', '雅各书', 59, 2, 19, '你信神只有一位，你信的不错；鬼魔也信，却是战惊。'),
('CUV', '雅各书', 59, 2, 20, '虚浮的人哪，你愿意知道没有行为的信心是死的么？'),
('CUV', '雅各书', 59, 2, 21, '我们的祖宗亚伯拉罕把他儿子以撒献在坛上，岂不是因行为称义么？'),
('CUV', '雅各书', 59, 2, 22, '可见，信心是与他的行为并行，而且信心因著行为才得成全。'),
('CUV', '雅各书', 59, 2, 23, '这就应验经上所说：「亚伯拉罕信神，这就算为他的义。」他又得称为神的朋友。'),
('CUV', '雅各书', 59, 2, 24, '这样看来，人称义是因著行为，不是单因著信。'),
('CUV', '雅各书', 59, 2, 25, '妓女喇合接待使者，又放他们从别的路上出去，不也是一样因行为称义么？'),
('CUV', '雅各书', 59, 2, 26, '身体没有灵魂是死的，信心没有行为也是死的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅各书', 59, 3, 1, '我的弟兄们，不要多人作师傅，因为晓得我们要受更重的判断。'),
('CUV', '雅各书', 59, 3, 2, '原来我们在许多事上都有过失；若有人在话语上没有过失，他就是完全人，也能勒住自己的全身。'),
('CUV', '雅各书', 59, 3, 3, '我们若把嚼环放在马嘴里，叫牠顺服，就能调动牠的全身。'),
('CUV', '雅各书', 59, 3, 4, '看哪，船只虽然甚大，又被大风催逼，只用小小的舵，就随著掌舵的意思转动。'),
('CUV', '雅各书', 59, 3, 5, '这样，舌头在百体里也是最小的，却能说大话。看哪，最小的火能点著最大的树林。'),
('CUV', '雅各书', 59, 3, 6, '舌头就是火，在我们百体中，舌头是个罪恶的世界，能污秽全身，也能把生命的轮子点起来，并且是从地狱里点著的。'),
('CUV', '雅各书', 59, 3, 7, '各类的走兽、飞禽、昆虫，水族，本来都可以制伏，也已经被人制伏了；'),
('CUV', '雅各书', 59, 3, 8, '惟独舌头没有人能制伏，是不止息的恶物，满了害死人的毒气。'),
('CUV', '雅各书', 59, 3, 9, '我们用舌头颂赞那为主、为父的，又用舌头咒诅那照著神形像被造的人。'),
('CUV', '雅各书', 59, 3, 10, '颂赞和咒诅从一个口里出来！我的弟兄们，这是不应当的！'),
('CUV', '雅各书', 59, 3, 11, '泉源从一个眼里能发出甜苦两样的水么？'),
('CUV', '雅各书', 59, 3, 12, '我的弟兄们，无花果树能生橄榄么？葡萄树能结无花果么？咸水里也不能发出甜水来。'),
('CUV', '雅各书', 59, 3, 13, '你们中间谁是有智慧有见识的呢？他就当在智慧的温柔上显出他的善行来。'),
('CUV', '雅各书', 59, 3, 14, '你们心里若怀著苦毒的嫉妒和分争，就不可自夸，也不可说谎话抵挡真道。'),
('CUV', '雅各书', 59, 3, 15, '这样的智慧不是从上头来的，乃是属地的，属情欲的，属鬼魔的。'),
('CUV', '雅各书', 59, 3, 16, '在何处有嫉妒、分争，就在何处有扰乱和各样的坏事。'),
('CUV', '雅各书', 59, 3, 17, '惟独从上头来的智慧，先是清洁，后是和平，温良柔顺，满有怜悯，多结善果，没有偏见，没有假冒。'),
('CUV', '雅各书', 59, 3, 18, '并且使人和平的，是用和平所栽种的义果。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅各书', 59, 4, 1, '你们中间的争战斗殴是从那里来的呢？不是从你们百体中战斗之私欲来的么？'),
('CUV', '雅各书', 59, 4, 2, '你们贪恋，还是得不著；你们杀害嫉妒，又斗殴争战，也不能得。你们得不著，是因为你们不求。'),
('CUV', '雅各书', 59, 4, 3, '你们求也得不著，是因为你们妄求，要浪费在你们的宴乐中。'),
('CUV', '雅各书', 59, 4, 4, '你们这些淫乱的人（原文是淫妇）哪，岂不知与世俗为友就是与神为敌么？所以凡想要与世俗为友的，就是与神为敌了。'),
('CUV', '雅各书', 59, 4, 5, '你们想经上所说是徒然的么？神所赐、住在我们里面的灵，是恋爱至于嫉妒么？'),
('CUV', '雅各书', 59, 4, 6, '但他赐更多的恩典，所以经上说：神阻挡骄傲的人，赐恩给谦卑的人。'),
('CUV', '雅各书', 59, 4, 7, '故此，你们要顺服神。务要抵挡魔鬼，魔鬼就必离开你们逃跑了。'),
('CUV', '雅各书', 59, 4, 8, '你们亲近神，神就必亲近你们。有罪的人哪，要洁净你们的手！心怀二意的人哪，要清洁你们的心！'),
('CUV', '雅各书', 59, 4, 9, '你们要愁苦、悲哀、哭泣，将喜笑变作悲哀，欢乐变作愁闷。'),
('CUV', '雅各书', 59, 4, 10, '务要在主面前自卑，主就必叫你们升高。'),
('CUV', '雅各书', 59, 4, 11, '弟兄们，你们不可彼此批评。人若批评弟兄，论断弟兄，就是批评律法，论断律法。你若论断律法，就不是遵行律法，乃是判断人的。'),
('CUV', '雅各书', 59, 4, 12, '设立律法和判断人的，只有一位，就是那能救人也能灭人的。你是谁，竟敢论断别人呢？'),
('CUV', '雅各书', 59, 4, 13, '嗐！你们有话说：「今天明天我们要往某城里去，在那里住一年，做买卖得利。」'),
('CUV', '雅各书', 59, 4, 14, '其实明天如何，你们还不知道。你们的生命是甚么呢？你们原来是一片云雾，出现少时就不见了。'),
('CUV', '雅各书', 59, 4, 15, '你们只当说：「主若愿意，我们就可以活著，也可以做这事，或做那事。」'),
('CUV', '雅各书', 59, 4, 16, '现今你们竟以张狂夸口；凡这样夸口都是恶的。'),
('CUV', '雅各书', 59, 4, 17, '人若知道行善，却不去行，这就是他的罪了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '雅各书', 59, 5, 1, '嗐！你们这些富足人哪，应当哭泣、号咷，因为将有苦难临到你们身上。'),
('CUV', '雅各书', 59, 5, 2, '你们的财物坏了，衣服也被虫子咬了。'),
('CUV', '雅各书', 59, 5, 3, '你们的金银都长了�；那�要证明你们的不是，又要吃你们的肉，如同火烧。你们在这末世只知积儹钱财。'),
('CUV', '雅各书', 59, 5, 4, '工人给你们收割庄稼，你们亏欠他们的工钱，这工钱有声音呼叫，并且那收割之人的冤声已经入了万军之主的耳了。'),
('CUV', '雅各书', 59, 5, 5, '你们在世上享美福，好宴乐，当宰杀的日子竟娇养你们的心。'),
('CUV', '雅各书', 59, 5, 6, '你们定了义人的罪，把他杀害，他也不抵挡你们。'),
('CUV', '雅各书', 59, 5, 7, '弟兄们哪，你们要忍耐，直到主来。看哪，农夫忍耐等候地里宝贵的出产，直到得了秋雨春雨。'),
('CUV', '雅各书', 59, 5, 8, '你们也当忍耐，坚固你们的心，因为主来的日子近了。'),
('CUV', '雅各书', 59, 5, 9, '弟兄们，你们不要彼此埋怨，免得受审判。看哪，审判的主站在门前了。'),
('CUV', '雅各书', 59, 5, 10, '弟兄们，你们要把那先前奉主名说话的众先知当作能受苦能忍耐的榜样。'),
('CUV', '雅各书', 59, 5, 11, '那先前忍耐的人，我们称他们是有福的。你们听见过约伯的忍耐，也知道主给他的结局，明显主是满心怜悯，大有慈悲。'),
('CUV', '雅各书', 59, 5, 12, '我的弟兄们，最要紧的是不可起誓；不可指著天起誓，也不可指著地起誓，无论何誓都不可起。你们说话，是，就说是；不是，就说不是，免得你们落在审判之下。'),
('CUV', '雅各书', 59, 5, 13, '你们中间有受苦的呢，他就该祷告；有喜乐的呢，他就该歌颂。'),
('CUV', '雅各书', 59, 5, 14, '你们中间有病了的呢，他就该请教会的长老来；他们可以奉主的名用油抹他，为他祷告。'),
('CUV', '雅各书', 59, 5, 15, '出于信心的祈祷要救那病人，主必叫他起来；他若犯了罪，也必蒙赦免。'),
('CUV', '雅各书', 59, 5, 16, '所以你们要彼此认罪，互相代求，使你们可以得医治。义人祈祷所发的力量是大有功效的。'),
('CUV', '雅各书', 59, 5, 17, '以利亚与我们是一样性情的人，他恳切祷告，求不要下雨，雨就三年零六个月不下在地上。'),
('CUV', '雅各书', 59, 5, 18, '他又祷告，天就降下雨来，地也生出土产。'),
('CUV', '雅各书', 59, 5, 19, '我的弟兄们，你们中间若有失迷真道的，有人使他回转，'),
('CUV', '雅各书', 59, 5, 20, '这人该知道：叫一个罪人从迷路上转回便是救一个灵魂不死，并且遮盖许多的罪。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '彼得前书', 60, 1, 1, '耶稣基督的使徒彼得写信给那分散在本都、加拉太、加帕多家、亚西亚、庇推尼寄居的，'),
('CUV', '彼得前书', 60, 1, 2, '就是照父神的先见被拣选，藉著圣灵得成圣洁，以致顺服耶稣基督，又蒙他血所洒的人。愿恩惠、平安多多的加给你们。'),
('CUV', '彼得前书', 60, 1, 3, '愿颂赞归与我们主耶稣基督的父神！他曾照自己的大怜悯，藉耶稣基督从死里复活，重生了我们，叫我们有活泼的盼望，'),
('CUV', '彼得前书', 60, 1, 4, '可以得著不能朽坏、不能玷污、不能衰残、为你们存留在天上的基业。'),
('CUV', '彼得前书', 60, 1, 5, '你们这因信蒙神能力保守的人，必能得著所预备、到末世要显现的救恩。'),
('CUV', '彼得前书', 60, 1, 6, '因此，你们是大有喜乐；但如今，在百般的试炼中暂时忧愁，'),
('CUV', '彼得前书', 60, 1, 7, '叫你们的信心既被试验，就比那被火试验仍然能坏的金子更显宝贵，可以在耶稣基督显现的时候得著称赞、荣耀、尊贵。'),
('CUV', '彼得前书', 60, 1, 8, '你们虽然没有见过他，却是爱他；如今虽不得看见，却因信他就有说不出来、满有荣光的大喜乐；'),
('CUV', '彼得前书', 60, 1, 9, '并且得著你们信心的果效，就是灵魂的救恩。'),
('CUV', '彼得前书', 60, 1, 10, '论到这救恩，那预先说你们要得恩典的众先知早已详细的寻求考察，'),
('CUV', '彼得前书', 60, 1, 11, '就是考察在他们心里基督的灵，预先证明基督受苦难，后来得荣耀，是指著甚么时候，并怎样的时候。'),
('CUV', '彼得前书', 60, 1, 12, '他们得了启示，知道他们所传讲（原文是服事）的一切事，不是为自己，乃是为你们。那靠著从天上差来的圣灵传福音给你们的人，现在将这些事报给你们；天使也愿意详细察看这些事。'),
('CUV', '彼得前书', 60, 1, 13, '所以要约束你们的心，（原文是束上你们心中的腰），谨慎自守，专心盼望耶稣基督显现的时候所带来给你们的恩。'),
('CUV', '彼得前书', 60, 1, 14, '你们既作顺命的儿女，就不要效法从前蒙昧无知的时候那放纵私欲的样子。'),
('CUV', '彼得前书', 60, 1, 15, '那召你们的既是圣洁，你们在一切所行的事上也要圣洁。'),
('CUV', '彼得前书', 60, 1, 16, '因为经上记著说：「你们要圣洁，因为我是圣洁的。」'),
('CUV', '彼得前书', 60, 1, 17, '你们既称那不偏待人、按各人行为审判人的主为父，就当存敬畏的心度你们在世寄居的日子，'),
('CUV', '彼得前书', 60, 1, 18, '知道你们得赎，脱去你们祖宗所传流虚妄的行为，不是凭著能坏的金银等物，'),
('CUV', '彼得前书', 60, 1, 19, '乃是凭著基督的宝血，如同无瑕疵、无玷污的羔羊之血。'),
('CUV', '彼得前书', 60, 1, 20, '基督在创世以前是预先被神知道的，却在这末世才为你们显现。'),
('CUV', '彼得前书', 60, 1, 21, '你们也因著他，信那叫他从死里复活、又给他荣耀的神，叫你们的信心和盼望都在于神。'),
('CUV', '彼得前书', 60, 1, 22, '你们既因顺从真理，洁净了自己的心，以致爱弟兄没有虚假，就当从心里（从心里：有古卷是从清洁的心）彼此切实相爱。'),
('CUV', '彼得前书', 60, 1, 23, '你们蒙了重生，不是由于能坏的种子，乃是由于不能坏的种子，是藉著神活泼常存的道。'),
('CUV', '彼得前书', 60, 1, 24, '因为凡有血气的，尽都如草；他的美荣都像草上的花。草必枯干，花必凋谢；'),
('CUV', '彼得前书', 60, 1, 25, '惟有主的道是永存的。所传给你们的福音就是这道。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '彼得前书', 60, 2, 1, '所以，你们既除去一切的恶毒（或译：阴毒）、诡诈，并假善、嫉妒，和一切毁谤的话，'),
('CUV', '彼得前书', 60, 2, 2, '就要爱慕那纯净的灵奶，像才生的婴孩爱慕奶一样，叫你们因此渐长，以致得救。'),
('CUV', '彼得前书', 60, 2, 3, '你们若尝过主恩的滋味，就必如此。'),
('CUV', '彼得前书', 60, 2, 4, '主乃活石，固然是被人所弃的，却是被神所拣选、所宝贵的。'),
('CUV', '彼得前书', 60, 2, 5, '你们来到主面前，也就像活石，被建造成为灵宫，作圣洁的祭司，藉著耶稣基督奉献神所悦纳的灵祭。'),
('CUV', '彼得前书', 60, 2, 6, '因为经上说：看哪，我把所拣选、所宝贵的房角石安放在锡安；信靠他的人必不至于羞愧。'),
('CUV', '彼得前书', 60, 2, 7, '所以，他在你们信的人就为宝贵，在那不信的人有话说：匠人所弃的石头已作了房角的头块石头。'),
('CUV', '彼得前书', 60, 2, 8, '又说：作了绊脚的石头，跌人的磐石。他们既不顺从，就在道理上绊跌（或译：他们绊跌都因不顺从道理）；他们这样绊跌也是预定的。'),
('CUV', '彼得前书', 60, 2, 9, '惟有你们是被拣选的族类，是有君尊的祭司，是圣洁的国度，是属神的子民，要叫你们宣扬那召你们出黑暗入奇妙光明者的美德。'),
('CUV', '彼得前书', 60, 2, 10, '你们从前算不得子民，现在却作了神的子民；从前未曾蒙怜恤，现在却蒙了怜恤。'),
('CUV', '彼得前书', 60, 2, 11, '亲爱的弟兄阿，你们是客旅，是寄居的。我劝你们要禁戒肉体的私欲；这私欲是与灵魂争战的。'),
('CUV', '彼得前书', 60, 2, 12, '你们在外邦人中，应当品行端正，叫那些毁谤你们是作恶的，因看见你们的好行为，便在鉴察（或作：眷顾）的日子归荣耀给神。'),
('CUV', '彼得前书', 60, 2, 13, '你们为主的缘故，要顺服人的一切制度，或是在上的君王，'),
('CUV', '彼得前书', 60, 2, 14, '或是君王所派罚恶赏善的臣宰。'),
('CUV', '彼得前书', 60, 2, 15, '因为神的旨意原是要你们行善，可以堵住那糊涂无知人的口。'),
('CUV', '彼得前书', 60, 2, 16, '你们虽是自由的，却不可藉著自由遮盖恶毒（或译：阴毒），总要作神的仆人。'),
('CUV', '彼得前书', 60, 2, 17, '务要尊敬众人，亲爱教中的弟兄，敬畏神，尊敬君王。'),
('CUV', '彼得前书', 60, 2, 18, '你们作仆人的，凡事要存敬畏的心顺服主人；不但顺服那善良温和的，就是那乖僻的也要顺服。'),
('CUV', '彼得前书', 60, 2, 19, '倘若人为叫良心对得住神，就忍受冤屈的苦楚，这是可喜爱的。'),
('CUV', '彼得前书', 60, 2, 20, '你们若因犯罪受责打，能忍耐，有甚么可夸的呢？但你们若因行善受苦，能忍耐，这在神看是可喜爱的。'),
('CUV', '彼得前书', 60, 2, 21, '你们蒙召原是为此；因基督也为你们受过苦，给你们留下榜样，叫你们跟随他的脚踪行。'),
('CUV', '彼得前书', 60, 2, 22, '他并没有犯罪，口里也没有诡诈。'),
('CUV', '彼得前书', 60, 2, 23, '他被骂不还口；受害不说威吓的话，只将自己交托那按公义审判人的主。'),
('CUV', '彼得前书', 60, 2, 24, '他被挂在木头上，亲身担当了我们的罪，使我们既然在罪上死，就得以在义上活。因他受的鞭伤，你们便得了医治。'),
('CUV', '彼得前书', 60, 2, 25, '你们从前好像迷路的羊，如今却归到你们灵魂的牧人监督了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '彼得前书', 60, 3, 1, '你们作妻子的要顺服自己的丈夫；这样，若有不信从道理的丈夫，他们虽然不听道，也可以因妻子的品行被感化过来；'),
('CUV', '彼得前书', 60, 3, 2, '这正是因看见你们有贞洁的品行和敬畏的心。'),
('CUV', '彼得前书', 60, 3, 3, '你们不要以外面的辫头发，戴金饰，穿美衣为妆饰，'),
('CUV', '彼得前书', 60, 3, 4, '只要以里面存著长久温柔、安静的心为妆饰；这在神面前是极宝贵的。'),
('CUV', '彼得前书', 60, 3, 5, '因为古时仰赖神的圣洁妇人正是以此为妆饰，顺服自己的丈夫，'),
('CUV', '彼得前书', 60, 3, 6, '就如撒拉听从亚伯拉罕，称他为主。你们若行善，不因恐吓而害怕，便是撒拉的女儿了。'),
('CUV', '彼得前书', 60, 3, 7, '你们作丈夫的，也要按情理（原文是知识）和妻子同住；因他比你软弱（比你软弱：原文作是软弱的器皿），与你一同承受生命之恩的，所以要敬重他。这样，便叫你们的祷告没有阻碍。'),
('CUV', '彼得前书', 60, 3, 8, '总而言之，你们都要同心，彼此体恤，相爱如弟兄，存慈怜谦卑的心。'),
('CUV', '彼得前书', 60, 3, 9, '不以恶报恶，以辱骂还辱骂，倒要祝福；因你们是为此蒙召，好叫你们承受福气。'),
('CUV', '彼得前书', 60, 3, 10, '因为经上说：人若爱生命，愿享美福，须要禁止舌头不出恶言，嘴唇不说诡诈的话；'),
('CUV', '彼得前书', 60, 3, 11, '也要离恶行善，寻求和睦，一心追赶。'),
('CUV', '彼得前书', 60, 3, 12, '因为，主的眼看顾义人；主的耳听他们的祈祷。惟有行恶的人，主向他们变脸。'),
('CUV', '彼得前书', 60, 3, 13, '你们若是热心行善，有谁害你们呢？'),
('CUV', '彼得前书', 60, 3, 14, '你们就是为义受苦，也是有福的。不要怕人的威吓（的威吓：或译所怕的），也不要惊慌；'),
('CUV', '彼得前书', 60, 3, 15, '只要心里尊主基督为圣。有人问你们心中盼望的缘由，就要常作准备，以温柔、敬畏的心回答各人；'),
('CUV', '彼得前书', 60, 3, 16, '存著无亏的良心，叫你们在何事上被毁谤，就在何事上可以叫那诬赖你们在基督里有好品行的人自觉羞愧。'),
('CUV', '彼得前书', 60, 3, 17, '神的旨意若是叫你们因行善受苦，总强如因行恶受苦。'),
('CUV', '彼得前书', 60, 3, 18, '因基督也曾一次为罪受苦（有古卷作：受死），就是义的代替不义的，为要引我们到神面前。按著肉体说，他被治死；按著灵性说，他复活了。'),
('CUV', '彼得前书', 60, 3, 19, '他藉这灵曾去传道给那些在监狱里的灵听，'),
('CUV', '彼得前书', 60, 3, 20, '就是那从前在挪亚预备方舟、神容忍等待的时候，不信从的人。当时进入方舟，藉著水得救的不多，只有八个人。'),
('CUV', '彼得前书', 60, 3, 21, '这水所表明的洗礼，现在藉著耶稣基督复活也拯救你们；这洗礼本不在乎除掉肉体的污秽，只求在神面前有无亏的良心。'),
('CUV', '彼得前书', 60, 3, 22, '耶稣已经进入天堂，在神的右边；众天使和有权柄的，并有能力的，都服从了他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '彼得前书', 60, 4, 1, '基督既在肉身受苦，你们也当将这样的心志作为兵器，因为在肉身受过苦的，就已经与罪断绝了。'),
('CUV', '彼得前书', 60, 4, 2, '你们存这样的心，从今以后就可以不从人的情欲，只从神的旨意在世度余下的光阴。'),
('CUV', '彼得前书', 60, 4, 3, '因为往日随从外邦人的心意行邪淫、恶欲、醉酒、荒宴、群饮，并可恶拜偶像的事，时候已经够了。'),
('CUV', '彼得前书', 60, 4, 4, '他们在这些事上，见你们不与他们同奔那放荡无度的路，就以为怪，毁谤你们。'),
('CUV', '彼得前书', 60, 4, 5, '他们必在那将要审判活人死人的主面前交账。'),
('CUV', '彼得前书', 60, 4, 6, '为此，就是死人也曾有福音传给他们，要叫他们的肉体按著人受审判，他们的灵性却靠神活著。'),
('CUV', '彼得前书', 60, 4, 7, '万物的结局近了。所以，你们要谨慎自守，儆醒祷告。'),
('CUV', '彼得前书', 60, 4, 8, '最要紧的是彼此切实相爱，因为爱能遮掩许多的罪。'),
('CUV', '彼得前书', 60, 4, 9, '你们要互相款待，不发怨言。'),
('CUV', '彼得前书', 60, 4, 10, '各人要照所得的恩赐彼此服事，作神百般恩赐的好管家。'),
('CUV', '彼得前书', 60, 4, 11, '若有讲道的，要按著神的圣言讲；若有服事人的，要按著神所赐的力量服事，叫神在凡事上因耶稣基督得荣耀。原来荣耀、权能都是他的，直到永永远远。阿们！'),
('CUV', '彼得前书', 60, 4, 12, '亲爱的弟兄阿，有火炼的试验临到你们，不要以为奇怪（似乎是遭遇非常的事），'),
('CUV', '彼得前书', 60, 4, 13, '倒要欢喜；因为你们是与基督一同受苦，使你们在他荣耀显现的时候，也可以欢喜快乐。'),
('CUV', '彼得前书', 60, 4, 14, '你们若为基督的名受辱骂，便是有福的；因为神荣耀的灵常住在你们身上。'),
('CUV', '彼得前书', 60, 4, 15, '你们中间却不可有人因为杀人、偷窃、作恶、好管闲事而受苦。'),
('CUV', '彼得前书', 60, 4, 16, '若为作基督徒受苦，却不要羞耻，倒要因这名归荣耀给神。'),
('CUV', '彼得前书', 60, 4, 17, '因为时候到了，审判要从神的家起首。若是先从我们起首，那不信从神福音的人将有何等的结局呢？'),
('CUV', '彼得前书', 60, 4, 18, '若是义人仅仅得救，那不虔敬和犯罪的人将有何地可站呢？'),
('CUV', '彼得前书', 60, 4, 19, '所以，那照神旨意受苦的人要一心为善，将自己灵魂交与那信实的造化之主。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '彼得前书', 60, 5, 1, '我这作长老、作基督受苦的见证、同享后来所要显现之荣耀的，劝你们中间与我同作长老的人：'),
('CUV', '彼得前书', 60, 5, 2, '务要牧养在你们中间神的群羊，按著神旨意照管他们；不是出于勉强，乃是出于甘心；也不是因为贪财，乃是出于乐意；'),
('CUV', '彼得前书', 60, 5, 3, '也不是辖制所托付你们的，乃是作群羊的榜样。'),
('CUV', '彼得前书', 60, 5, 4, '到了牧长显现的时候，你们必得那永不衰残的荣耀冠冕。'),
('CUV', '彼得前书', 60, 5, 5, '你们年幼的，也要顺服年长的。就是你们众人也都要以谦卑束腰，彼此顺服；因为神阻挡骄傲的人，赐恩给谦卑的人。'),
('CUV', '彼得前书', 60, 5, 6, '所以，你们要自卑，服在神大能的手下，到了时候他必叫你们升高。'),
('CUV', '彼得前书', 60, 5, 7, '你们要将一切的忧虑卸给神，因为他顾念你们。'),
('CUV', '彼得前书', 60, 5, 8, '务要谨守，儆醒。因为你们的仇敌魔鬼，如同吼叫的狮子，遍地游行，寻找可吞吃的人。'),
('CUV', '彼得前书', 60, 5, 9, '你们要用坚固的信心抵挡他，因为知道你们在世上的众弟兄也是经历这样的苦难。'),
('CUV', '彼得前书', 60, 5, 10, '那赐诸般恩典的神曾在基督里召你们，得享他永远的荣耀，等你们暂受苦难之后，必要亲自成全你们，坚固你们，赐力量给你们。'),
('CUV', '彼得前书', 60, 5, 11, '愿权能归给他，直到永永远远。阿们！'),
('CUV', '彼得前书', 60, 5, 12, '我略略的写了这信，托我所看为忠心的兄弟西拉转交你们，劝勉你们，又证明这恩是神的真恩。你们务要在这恩上站立得住。'),
('CUV', '彼得前书', 60, 5, 13, '在巴比伦与你们同蒙拣选的教会问你们安。我儿子马可也问你们安。'),
('CUV', '彼得前书', 60, 5, 14, '你们要用爱心彼此亲嘴问安。愿平安归与你们凡在基督里的人！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '彼得后书', 61, 1, 1, '作耶稣基督仆人和使徒的西门。彼得写信给那因我们的神和（有古卷没有和字）救主耶稣基督之义，与我们同得一样宝贵信心的人。'),
('CUV', '彼得后书', 61, 1, 2, '愿恩惠、平安，因你们认识神和我们主耶稣，多多的加给你们。'),
('CUV', '彼得后书', 61, 1, 3, '神的神能已将一切关乎生命和虔敬的事赐给我们，皆因我们认识那用自己荣耀和美德召我们的主。'),
('CUV', '彼得后书', 61, 1, 4, '因此，他已将又宝贵又极大的应许赐给我们，叫我们既脱离世上从情欲来的败坏，就得与神的性情有分。'),
('CUV', '彼得后书', 61, 1, 5, '正因这缘故，你们要分外地殷勤；有了信心，又要加上德行；有了德行，又要加上知识；'),
('CUV', '彼得后书', 61, 1, 6, '有了知识，又要加上节制；有了节制，又要加上忍耐；有了忍耐，又要加上虔敬；'),
('CUV', '彼得后书', 61, 1, 7, '有了虔敬，又要加上爱弟兄的心；有了爱弟兄的心，又要加上爱众人的心；'),
('CUV', '彼得后书', 61, 1, 8, '你们若充充足足的有这几样，就必使你们在认识我们的主耶稣基督上不至于闲懒不结果子了。'),
('CUV', '彼得后书', 61, 1, 9, '人若没有这几样，就是眼瞎，只看见近处的，忘了他旧日的罪已经得了洁净。'),
('CUV', '彼得后书', 61, 1, 10, '所以弟兄们，应当更加殷勤，使你们所蒙的恩召和拣选坚定不移。你们若行这几样，就永不失脚。'),
('CUV', '彼得后书', 61, 1, 11, '这样，必叫你们丰丰富富的得以进入我们主─救主耶稣基督永远的国。'),
('CUV', '彼得后书', 61, 1, 12, '你们虽然晓得这些事，并且在你们已有的真道上坚固，我却要将这些事常常提醒你们。'),
('CUV', '彼得后书', 61, 1, 13, '我以为应当趁我还在这帐棚的时候提醒你们，激发你们。'),
('CUV', '彼得后书', 61, 1, 14, '因为知道我脱离这帐棚的时候快到了，正如我们主耶稣基督所指示我的。'),
('CUV', '彼得后书', 61, 1, 15, '并且，我要尽心竭力，使你们在我去世以后时常记念这些事。'),
('CUV', '彼得后书', 61, 1, 16, '我们从前将我们主耶稣基督的大能和他降临的事告诉你们，并不是随从乖巧捏造的虚言，乃是亲眼见过他的威荣。'),
('CUV', '彼得后书', 61, 1, 17, '他从父神得尊贵荣耀的时候，从极大荣光之中有声音出来，向他说：「这是我的爱子，我所喜悦的。」'),
('CUV', '彼得后书', 61, 1, 18, '我们同他在圣山的时候，亲自听见这声音从天上出来。'),
('CUV', '彼得后书', 61, 1, 19, '我们并有先知更确的预言，如同灯照在暗处。你们在这预言上留意，直等到天发亮，晨星在你们心里出现的时候，才是好的。'),
('CUV', '彼得后书', 61, 1, 20, '第一要紧的，该知道经上所有的预言没有可随私意解说的；'),
('CUV', '彼得后书', 61, 1, 21, '因为预言从来没有出于人意的，乃是人被圣灵感动，说出神的话来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '彼得后书', 61, 2, 1, '从前在百姓中有假先知起来，将来在你们中间也必有假师傅，私自引进陷害人的异端，连买他们的主他们也不承认，自取速速的灭亡。'),
('CUV', '彼得后书', 61, 2, 2, '将有许多人随从他们邪淫的行为，便叫真道因他们的缘故被毁谤。'),
('CUV', '彼得后书', 61, 2, 3, '他们因有贪心，要用捏造的言语在你们身上取利。他们的刑罚，自古以来并不迟延；他们的灭亡也必速速来到（原文是不打盹）。'),
('CUV', '彼得后书', 61, 2, 4, '就是天使犯了罪，神也没有宽容，曾把他们丢在地狱，交在黑暗坑中，等候审判。'),
('CUV', '彼得后书', 61, 2, 5, '神也没有宽容上古的世代，曾叫洪水临到那不敬虔的世代，却保护了传义道的挪亚一家八口。'),
('CUV', '彼得后书', 61, 2, 6, '又判定所多玛、蛾摩拉，将二城倾覆，焚烧成灰，作为后世不敬虔人的鉴戒；'),
('CUV', '彼得后书', 61, 2, 7, '只搭救了那常为恶人淫行忧伤的义人罗得。'),
('CUV', '彼得后书', 61, 2, 8, '（因为那义人住在他们中间，看见听见他们不法的事，他的义心就天天伤痛。）'),
('CUV', '彼得后书', 61, 2, 9, '主知道搭救敬虔的人脱离试探，把不义的人留在刑罚之下，等候审判的日子。'),
('CUV', '彼得后书', 61, 2, 10, '那些随肉身、纵污秽的情欲、轻慢主治之人的，更是如此。他们胆大任性，毁谤在尊位的，也不知惧怕。'),
('CUV', '彼得后书', 61, 2, 11, '就是天使，虽然力量权能更大，还不用毁谤的话在主面前告他们。'),
('CUV', '彼得后书', 61, 2, 12, '但这些人好像没有灵性，生来就是畜类，以备捉拿宰杀的。他们毁谤所不晓得的事，正在败坏人的时候，自己必遭遇败坏。'),
('CUV', '彼得后书', 61, 2, 13, '行的不义，就得了不义的工价。这些人喜爱白昼宴乐，他们已被玷污，又有瑕疵，正与你们一同坐席，就以自己的诡诈为快乐。'),
('CUV', '彼得后书', 61, 2, 14, '他们满眼是淫色（原文是淫妇），止不住犯罪，引诱那心不坚固的人，心中习惯了贪婪，正是被咒诅的种类。'),
('CUV', '彼得后书', 61, 2, 15, '他们离弃正路，就走差了，随从比珥之子巴兰的路。巴兰就是那贪爱不义之工价的先知，'),
('CUV', '彼得后书', 61, 2, 16, '他却为自己的过犯受了责备；那不能说话的驴以人言拦阻先知的狂妄。'),
('CUV', '彼得后书', 61, 2, 17, '这些人是无水的井，是狂风催逼的雾气，有墨黑的幽暗为他们存留。'),
('CUV', '彼得后书', 61, 2, 18, '他们说虚妄矜夸的大话，用肉身的情欲和邪淫的事引诱那些刚才脱离妄行的人。'),
('CUV', '彼得后书', 61, 2, 19, '他们应许人得以自由，自己却作败坏的奴仆，因为人被谁制伏就是谁的奴仆。'),
('CUV', '彼得后书', 61, 2, 20, '倘若他们因认识主─救主耶稣基督，得以脱离世上的污秽，后来又在其中被缠住、制伏，他们末后的景况就比先前更不好了。'),
('CUV', '彼得后书', 61, 2, 21, '他们晓得义路，竟背弃了传给他们的圣命，倒不如不晓得为妙。'),
('CUV', '彼得后书', 61, 2, 22, '俗语说得真不错：狗所吐的，他转过来又吃；猪洗净了又回到泥里去辊；这话在他们身上正合式。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '彼得后书', 61, 3, 1, '亲爱的弟兄阿，我现在写给你们的是第二封信。这两封都是提醒你们，激发你们诚实的心，'),
('CUV', '彼得后书', 61, 3, 2, '叫你们记念圣先知预先所说的话和主救主的命令，就是使徒所传给你们的。'),
('CUV', '彼得后书', 61, 3, 3, '第一要紧的，该知道在末世必有好讥诮的人随从自己的私欲出来讥诮说：'),
('CUV', '彼得后书', 61, 3, 4, '「主要降临的应许在那里呢？因为从列祖睡了以来，万物与起初创造的时候仍是一样。」'),
('CUV', '彼得后书', 61, 3, 5, '他们故意忘记，从太古，凭神的命有了天，并从水而出、藉水而成的地。'),
('CUV', '彼得后书', 61, 3, 6, '故此，当时的世界被水淹没就消灭了。'),
('CUV', '彼得后书', 61, 3, 7, '但现在的天地还是凭著那命存留，直留到不敬虔之人受审判遭沉沦的日子，用火焚烧。'),
('CUV', '彼得后书', 61, 3, 8, '亲爱的弟兄阿，有一件事你们不可忘记，就是主看一日如千年，千年如一日。'),
('CUV', '彼得后书', 61, 3, 9, '主所应许的尚未成就，有人以为他是耽延，其实不是耽延，乃是宽容你们，不愿有一人沉沦，乃愿人人都悔改。'),
('CUV', '彼得后书', 61, 3, 10, '但主的日子要像贼来到一样。那日，天必大有响声废去，有形质的都要被烈火销化，地和其上的物都要烧尽了。'),
('CUV', '彼得后书', 61, 3, 11, '这一切既然都要如此销化，你们为人该当怎样圣洁，怎样敬虔，'),
('CUV', '彼得后书', 61, 3, 12, '切切仰望神的日子来到。在那日，天被火烧就销化了，有形质的都要被烈火镕化。'),
('CUV', '彼得后书', 61, 3, 13, '但我们照他的应许，盼望新天新地，有义居在其中。'),
('CUV', '彼得后书', 61, 3, 14, '亲爱的弟兄阿，你们既盼望这些事，就当殷勤，使自己没有玷污，无可指摘，安然见主；'),
('CUV', '彼得后书', 61, 3, 15, '并且要以我主长久忍耐为得救的因由，就如我们所亲爱的兄弟保罗，照著所赐给他的智慧写了信给你们。'),
('CUV', '彼得后书', 61, 3, 16, '他一切的信上也都是讲论这事。信中有些难明白的，那无学问、不坚固的人强解，如强解别的经书一样，就自取沉沦。'),
('CUV', '彼得后书', 61, 3, 17, '亲爱的弟兄阿，你们既然预先知道这事，就当防备，恐怕被恶人的错谬诱惑，就从自己坚固的地步上坠落。'),
('CUV', '彼得后书', 61, 3, 18, '你们却要在我们主─救主耶稣基督的恩典和知识上有长进。愿荣耀归给他，从今直到永远。阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰一书', 62, 1, 1, '论到从起初原有的生命之道，就是我们所听见、所看见、亲眼看过、亲手摸过的。'),
('CUV', '约翰一书', 62, 1, 2, '这生命已经显现出来，我们也看见过，现在又作见证，将原与父同在、且显现与我们那永远的生命、传给你们。'),
('CUV', '约翰一书', 62, 1, 3, '我们将所看见、所听见的传给你们，使你们与我们相交。我们乃是与父并他儿子耶稣基督相交的。'),
('CUV', '约翰一书', 62, 1, 4, '我们将这些话写给你们，使你们（有古卷作：我们）的喜乐充足。'),
('CUV', '约翰一书', 62, 1, 5, '神就是光，在他毫无黑暗。这是我们从主所听见、又报给你们的信息。'),
('CUV', '约翰一书', 62, 1, 6, '我们若说是与神相交，却仍在黑暗里行，就是说谎话，不行真理了。'),
('CUV', '约翰一书', 62, 1, 7, '我们若在光明中行，如同神在光明中，就彼此相交，他儿子耶稣的血也洗净我们一切的罪。'),
('CUV', '约翰一书', 62, 1, 8, '我们若说自己无罪，便是自欺，真理不在我们心里了。'),
('CUV', '约翰一书', 62, 1, 9, '我们若认自己的罪，神是信实的，是公义的，必要赦免我们的罪，洗净我们一切的不义。'),
('CUV', '约翰一书', 62, 1, 10, '我们若说自己没有犯过罪，便是以神为说谎的，他的道也不在我们心里了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰一书', 62, 2, 1, '我小子们哪，我将这些话写给你们，是要叫你们不犯罪。若有人犯罪，在父那里我们有一位中保，就是那义者耶稣基督。'),
('CUV', '约翰一书', 62, 2, 2, '他为我们的罪作了挽回祭，不是单为我们的罪，也是为普天下人的罪。'),
('CUV', '约翰一书', 62, 2, 3, '我们若遵守他的诫命，就晓得是认识他。'),
('CUV', '约翰一书', 62, 2, 4, '人若说我认识他，却不遵守他的诫命，便是说谎话的，真理也不在他心里了。'),
('CUV', '约翰一书', 62, 2, 5, '凡遵守主道的，爱神的心在他里面实在是完全的。从此我们知道我们是在主里面。'),
('CUV', '约翰一书', 62, 2, 6, '人若说他住在主里面，就该自己照主所行的去行。'),
('CUV', '约翰一书', 62, 2, 7, '亲爱的弟兄阿，我写给你们的，不是一条新命令，乃是你们从起初所受的旧命令；这旧命令就是你们所听见的道。'),
('CUV', '约翰一书', 62, 2, 8, '再者，我写给你们的，是一条新命令，在主是真的，在你们也是真的；因为黑暗渐渐过去，真光已经照耀。'),
('CUV', '约翰一书', 62, 2, 9, '人若说自己在光明中，却恨他的弟兄，他到如今还是在黑暗里。'),
('CUV', '约翰一书', 62, 2, 10, '爱弟兄的，就是住在光明中，在他并没有绊跌的缘由。'),
('CUV', '约翰一书', 62, 2, 11, '惟独恨弟兄的，是在黑暗里，且在黑暗里行，也不知道往那里去，因为黑暗叫他眼睛瞎了。'),
('CUV', '约翰一书', 62, 2, 12, '小子们哪，我写信给你们，因为你们的罪藉著主名得了赦免。'),
('CUV', '约翰一书', 62, 2, 13, '父老阿，我写信给你们，因为你们认识那从起初原有的。少年人哪，我写信给你们，因为你们胜了那恶者。小子们哪，我曾写信给你们，因为你们认识父。'),
('CUV', '约翰一书', 62, 2, 14, '父老阿，我曾写信给你们，因为，你们认识那从起初原有的。少年人哪，我曾写信给你们；因为，你们刚强，神的道常存在你们心里；你们也胜了那恶者。'),
('CUV', '约翰一书', 62, 2, 15, '不要爱世界和世界上的事。人若爱世界，爱父的心就不在他里面了。'),
('CUV', '约翰一书', 62, 2, 16, '因为凡世界上的事，就像肉体的情欲，眼目的情欲，并今生的骄傲，都不是从父来的，乃是从世界来的。'),
('CUV', '约翰一书', 62, 2, 17, '这世界和其上的情欲都要过去，惟独遵行神旨意的，是永远常存。'),
('CUV', '约翰一书', 62, 2, 18, '小子们哪，如今是末时了。你们曾听见说，那敌基督的要来；现在已经有好些敌基督的出来了，从此我们就知道如今是末时了。'),
('CUV', '约翰一书', 62, 2, 19, '他们从我们中间出去，却不是属我们的；若是属我们的，就必仍旧与我们同在；他们出去，显明都不是属我们的。'),
('CUV', '约翰一书', 62, 2, 20, '你们从那圣者受了恩膏，并且知道这一切的事（或作：都有知识）。'),
('CUV', '约翰一书', 62, 2, 21, '我写信给你们，不是因你们不知道真理，正是因你们知道，并且知道没有虚谎是从真理出来的。'),
('CUV', '约翰一书', 62, 2, 22, '谁是说谎话的呢？不是那不认耶稣为基督的么？不认父与子的，这就是敌基督的。'),
('CUV', '约翰一书', 62, 2, 23, '凡不认子的，就没有父；认子的，连父也有了。'),
('CUV', '约翰一书', 62, 2, 24, '论到你们，务要将那从起初所听见的，常存在心里。若将从起初所听见的存在心里，你们就必住在子里面，也必住在父里面。'),
('CUV', '约翰一书', 62, 2, 25, '主所应许我们的就是永生。'),
('CUV', '约翰一书', 62, 2, 26, '我将这些话写给你们，是指著那引诱你们的人说的。'),
('CUV', '约翰一书', 62, 2, 27, '你们从主所受的恩膏常存在你们心里，并不用人教训你们，自有主的恩膏在凡事上教训你们。这恩膏是真的，不是假的；你们要按这恩膏的教训住在主里面。'),
('CUV', '约翰一书', 62, 2, 28, '小子们哪，你们要住在主里面。这样，他若显现，我们就可以坦然无惧；当他来的时候，在他面前也不至于惭愧。'),
('CUV', '约翰一书', 62, 2, 29, '你们若知道他是公义的，就知道凡行公义之人都是他所生的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰一书', 62, 3, 1, '你看父赐给我们是何等的慈爱，使我们得称为神的儿女；我们也真是他的儿女。世人所以不认识我们，是因未曾认识他。'),
('CUV', '约翰一书', 62, 3, 2, '亲爱的弟兄阿，我们现在是神的儿女，将来如何，还未显明；但我们知道，主若显现，我们必要像他、因为必得见他的真体。'),
('CUV', '约翰一书', 62, 3, 3, '凡向他有这指望的，就洁净自己，像他洁净一样。'),
('CUV', '约翰一书', 62, 3, 4, '凡犯罪的，就是违背律法；违背律法就是罪。'),
('CUV', '约翰一书', 62, 3, 5, '你们知道主曾显现，是要除掉人的罪；在他并没有罪。'),
('CUV', '约翰一书', 62, 3, 6, '凡住在他里面的，就不犯罪；凡犯罪的，是未曾看见他，也未曾认识他。'),
('CUV', '约翰一书', 62, 3, 7, '小子们哪，不要被人诱感，行义的才是义人，正如主是义的一样。'),
('CUV', '约翰一书', 62, 3, 8, '犯罪的是属魔鬼，因为魔鬼从起初就犯罪。神的儿子显现出来，为要除灭魔鬼的作为。'),
('CUV', '约翰一书', 62, 3, 9, '凡从神生的，就不犯罪，因神的道（原文作种）存在他心里；他也不能犯罪，因为他是由神生的。'),
('CUV', '约翰一书', 62, 3, 10, '从此就显出谁是神的儿女，。谁是魔鬼的儿女。凡不行义的就不属神，不爱弟兄的也是如此。'),
('CUV', '约翰一书', 62, 3, 11, '我们应当彼此相爱。这就是你们从起初所听见的命令。'),
('CUV', '约翰一书', 62, 3, 12, '不可像该隐；他是属那恶者，杀了他的兄弟。为甚么杀了他呢？因自己的行为是恶的，兄弟的行为是善的。'),
('CUV', '约翰一书', 62, 3, 13, '弟兄们，世人若恨你们，不要以为希奇。'),
('CUV', '约翰一书', 62, 3, 14, '我们因为爱弟兄，就晓得是已经出死入生了。没有爱心的，仍住在死中。'),
('CUV', '约翰一书', 62, 3, 15, '凡恨他弟兄的，就是杀人的；你们晓得凡杀人的，没有永生存在他里面。'),
('CUV', '约翰一书', 62, 3, 16, '主为我们舍命，我们从此就知道何为爱；我们也当为弟兄舍命。'),
('CUV', '约翰一书', 62, 3, 17, '凡有世上财物的，看见弟兄穷乏，却塞住怜恤的心，爱神的心怎能存在他里面呢？'),
('CUV', '约翰一书', 62, 3, 18, '小子们哪，我们相爱，不要只在言语和舌头上，总要在行为和诚实上。'),
('CUV', '约翰一书', 62, 3, 19, '从此就知道我们是属真理的，并且我们的心在神面前可以安稳。'),
('CUV', '约翰一书', 62, 3, 20, '我们的心若责备我们，神比我们的心大，一切事没有不知道的。'),
('CUV', '约翰一书', 62, 3, 21, '亲爱的弟兄阿，我们的心若不责备我们，就可以向神坦然无惧了。'),
('CUV', '约翰一书', 62, 3, 22, '并且我们一切所求的，就从他得著；因为我们遵守他的命令，行他所喜悦的事。'),
('CUV', '约翰一书', 62, 3, 23, '神的命令就是叫我们信他儿子耶稣基督的名，且照他所赐给我们的命令彼此相爱。'),
('CUV', '约翰一书', 62, 3, 24, '遵守神命令的，就住在神里面；神也住在他里面。我们所以知道神住在我们里面是因他所赐给我们的圣灵。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰一书', 62, 4, 1, '亲爱的弟兄阿，一切的灵，你们不可都信，总要试验那些灵是出于神的不是，因为世上有许多假先知已经出来了。'),
('CUV', '约翰一书', 62, 4, 2, '凡灵认耶稣基督是成了肉身来，就是出于神的的；从此你们可以认出神的灵来。'),
('CUV', '约翰一书', 62, 4, 3, '凡灵不认耶稣，就不是出于神；这是那敌基督者的灵。你们从前听见他要来，现在已经在世上了。'),
('CUV', '约翰一书', 62, 4, 4, '小子们哪，你们是属神的，并且胜了他们；因为那在你们里面的，比那在世界上的更大。'),
('CUV', '约翰一书', 62, 4, 5, '他们是属世界的，所以论世界的事，世人也听从他们。'),
('CUV', '约翰一书', 62, 4, 6, '我们是属神的，认识神的就听从我们；不属神的就不听从我们。从此我们可以认出真理的灵和谬妄的灵来。'),
('CUV', '约翰一书', 62, 4, 7, '亲爱的弟兄阿，我们应当彼此相爱，因为爱是从神来的。凡有爱心的，都是由神而生，并且认识神。'),
('CUV', '约翰一书', 62, 4, 8, '没有爱心的，就不认识神，因为神就是爱。'),
('CUV', '约翰一书', 62, 4, 9, '神差他独生子到世间来，使我们藉著他得生，神爱我们的心在此就显明了。'),
('CUV', '约翰一书', 62, 4, 10, '不是我们爱神，乃是神爱我们，差他的儿子为我们的罪作了挽回祭，这就是爱了。'),
('CUV', '约翰一书', 62, 4, 11, '亲爱的弟兄阿，神既是这样爱我们，我们也当彼此相爱。'),
('CUV', '约翰一书', 62, 4, 12, '从来没有人见过神，我们若彼此相爱，神就住在我们里面，爱他的心在我们里面得以完全了。'),
('CUV', '约翰一书', 62, 4, 13, '神将他的灵赐给我们，从此就知道我们是住在他里面，他也住在我们里面。'),
('CUV', '约翰一书', 62, 4, 14, '父差子作世人的救主；这是我们所看见且作见证的。'),
('CUV', '约翰一书', 62, 4, 15, '凡认耶稣为神儿子的，神就住在他里面，他也住在神里面。'),
('CUV', '约翰一书', 62, 4, 16, '神爱我们的心，我们也知道也信。神就是爱；住在爱里面的，就是住在神里面，神也住在他里面。'),
('CUV', '约翰一书', 62, 4, 17, '这样，爱在我们里面得以完全，我们就可以在审判的日子坦然无惧。因为他如何，我们在这世上也如何。'),
('CUV', '约翰一书', 62, 4, 18, '爱里没有惧怕；爱既完全，就把惧怕除去。因为惧怕里含著刑罚，惧怕的人在爱里未得完全。'),
('CUV', '约翰一书', 62, 4, 19, '我们爱，因为神先爱我们。'),
('CUV', '约翰一书', 62, 4, 20, '人若说我爱神，却恨他的弟兄，就是说谎话的；不爱他所看见的弟兄，就不能爱没有看见的神（有古卷作：怎能爱没有看见的神呢）。'),
('CUV', '约翰一书', 62, 4, 21, '爱神的，也当爱弟兄，这是我们从神所受的命令。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰一书', 62, 5, 1, '凡信耶稣是基督的，都是从神而生，凡爱生他之神的，也必爱从神生的。'),
('CUV', '约翰一书', 62, 5, 2, '我们若爱神，又遵守他的诫命，从此就知道我们爱神的儿女。'),
('CUV', '约翰一书', 62, 5, 3, '我们遵守神的诫命，这就是爱他了，并且他的诫命不是难守的。'),
('CUV', '约翰一书', 62, 5, 4, '因为凡从神生的，就胜过世界；使我们胜了世界的，就是我们的信心。'),
('CUV', '约翰一书', 62, 5, 5, '胜过世界的是谁呢？不是那信耶稣是神儿子的么？'),
('CUV', '约翰一书', 62, 5, 6, '这藉著水和血而来的，就是耶稣基督；不是单用水，乃是用水又用血，'),
('CUV', '约翰一书', 62, 5, 7, '并且有圣灵作见证，因为圣灵就是真理。'),
('CUV', '约翰一书', 62, 5, 8, '作见证的原来有三：就是圣灵、水，与血，这三样也都归于一。'),
('CUV', '约翰一书', 62, 5, 9, '我们既领受人的见证，神的见证更该领受了（该领受：原文作大），因神的见证是为他儿子作的。'),
('CUV', '约翰一书', 62, 5, 10, '信神儿子的，就有这见证在他心里；不信神的，就是将神当作说谎的，因不信神为他儿子作的见证。'),
('CUV', '约翰一书', 62, 5, 11, '这见证就是神赐给我们永生；这永生也是在他儿子里面。'),
('CUV', '约翰一书', 62, 5, 12, '人有了神的儿子就有生命，没有神的儿子就没有生命。'),
('CUV', '约翰一书', 62, 5, 13, '我将这些话写给你们信奉神儿子之名的人，要叫你们知道自己有永生。'),
('CUV', '约翰一书', 62, 5, 14, '我们若照他的旨意求甚么，他就听我们，这是我们向他所存坦然无惧的心。'),
('CUV', '约翰一书', 62, 5, 15, '既然知道他听我们一切所求的，就知道我们所求于他的，无不得著。'),
('CUV', '约翰一书', 62, 5, 16, '人若看见弟兄犯了不至于死的罪，就当为他祈求，神必将生命赐给他；有至于死的罪，我不说当为这罪祈求。'),
('CUV', '约翰一书', 62, 5, 17, '凡不义的事都是罪，也有不至于死的罪。'),
('CUV', '约翰一书', 62, 5, 18, '我们知道凡从神生的，必不犯罪，从神生的，必保守自己（有古卷作：那从神生的必保护他），那恶者也就无法害他。'),
('CUV', '约翰一书', 62, 5, 19, '我们知道，我们是属神的，全世界都卧在那恶者手下。'),
('CUV', '约翰一书', 62, 5, 20, '我们也知道，神的儿子已经来到，且将智慧赐给我们，使我们认识那位真实的，我们也在那位真实的里面，就是在他儿子耶稣基督里面。这是真神，也是永生。'),
('CUV', '约翰一书', 62, 5, 21, '小子们哪，你们要自守，远避偶像！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰二书', 63, 1, 1, '作长老的写信给蒙拣选的太太（或作：教会；下同），和他的儿女，就是我诚心所爱的；不但我爱，也是一切知道真理之人所爱的。'),
('CUV', '约翰二书', 63, 1, 2, '爱你们是为真理的缘故，这真理存在我们里面，也必永远与我们同在。'),
('CUV', '约翰二书', 63, 1, 3, '恩惠，怜悯，平安从父神和他儿子耶稣基督在真理和爱心上必常与我们同在！'),
('CUV', '约翰二书', 63, 1, 4, '我见你的儿女，有照我们从父所受之命令遵行真理的，就甚欢喜。'),
('CUV', '约翰二书', 63, 1, 5, '太太阿，我现在劝你，我们大家要彼此相爱。这并不是我写一条新命令给你，乃是我们从起初所受的命令。'),
('CUV', '约翰二书', 63, 1, 6, '我们若照他的命令行，这就是爱。你们从起初所听见当行的，就是这命令。'),
('CUV', '约翰二书', 63, 1, 7, '因为世上有许多迷惑人的出来，他们不认耶稣基督是成了肉身来的；这就是那迷惑人、敌基督的。'),
('CUV', '约翰二书', 63, 1, 8, '你们要小心，不要失去你们（有古卷：我们）所做的工，乃要得著满足的赏赐。'),
('CUV', '约翰二书', 63, 1, 9, '凡越过基督的教训、不常守著的，就没有神；常守这教训的，就有父又有子。'),
('CUV', '约翰二书', 63, 1, 10, '若有人到你们那里，不是传这教训，不要接他到家里，也不要问他的安；'),
('CUV', '约翰二书', 63, 1, 11, '因为问他安的，就在他的恶行上有分。'),
('CUV', '约翰二书', 63, 1, 12, '我还有许多事要写给你们，却不愿意用纸墨写出来，但盼望到你们那里，与你们当面谈论，使你们的喜乐满足。'),
('CUV', '约翰二书', 63, 1, 13, '你那蒙拣选之姊妹的儿女都问你安。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约翰三书', 64, 1, 1, '作长老的写信给亲爱的该犹，就是我诚心所爱的。'),
('CUV', '约翰三书', 64, 1, 2, '亲爱的兄弟阿，我愿你凡事兴盛，身体健壮，正如你的灵魂兴盛一样。'),
('CUV', '约翰三书', 64, 1, 3, '有弟兄来证明你心里存的真理，正如你按真理而行，我就甚喜乐。'),
('CUV', '约翰三书', 64, 1, 4, '我听见我的儿女们按真理而行，我的喜乐就没有比这个大的。'),
('CUV', '约翰三书', 64, 1, 5, '亲爱的兄弟阿，凡你向作客旅之弟兄所行的都是忠心的。'),
('CUV', '约翰三书', 64, 1, 6, '他们在教会面前证明了你的爱；你若配得过神，帮助他们往前行，这就好了。'),
('CUV', '约翰三书', 64, 1, 7, '因他们是为主的名（原文是那名）出外，对于外邦人一无所取。'),
('CUV', '约翰三书', 64, 1, 8, '所以我们应该接待这样的人，叫我们与他们一同为真理做工。'),
('CUV', '约翰三书', 64, 1, 9, '我曾略略的写信给教会，但那在教会中好为首的丢特腓不接待我们。'),
('CUV', '约翰三书', 64, 1, 10, '所以我若去，必要提说他所行的事，就是他用恶言妄论我们。还不以此为足，他自己不接待弟兄，有人愿意接待，他也禁止，并且将接待弟兄的人赶出教会。'),
('CUV', '约翰三书', 64, 1, 11, '亲爱的兄弟阿，不要效法恶，只要效法善。行善的属乎神；行恶的未曾见过神。'),
('CUV', '约翰三书', 64, 1, 12, '低米丢行善，有众人给他作见证，又有真理给他作见证；就是我们也给他作见证。你也知道我们的见证是真的。'),
('CUV', '约翰三书', 64, 1, 13, '我原有许多事要写给你，却不愿意用笔墨写给你，'),
('CUV', '约翰三书', 64, 1, 14, '但盼望快快的见你，我们就当面谈论。[(IIIJohn1:15)愿你平安。众位朋友都问你安。请你替我按著姓名问众位朋友安。]')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '犹大书', 65, 1, 1, '耶稣基督的仆人，雅各的弟兄犹大，写信给那被召、在父神里蒙爱、为耶稣基督保守的人。'),
('CUV', '犹大书', 65, 1, 2, '愿怜恤、平安、慈爱多多的加给你们。'),
('CUV', '犹大书', 65, 1, 3, '亲爱的弟兄阿，我想尽心写信给你们，论我们同得救恩的时候，就不得不写信劝你们，要为从前一次交付圣徒的真道竭力的争辩。'),
('CUV', '犹大书', 65, 1, 4, '因为有些人偷著进来，就是自古被定受刑罚的，是不虔诚的，将我们神的恩变放纵情欲的机会，并且不认独一的主宰─我们（或作和我们）主耶稣基督。'),
('CUV', '犹大书', 65, 1, 5, '从前主救了他的百姓出埃及地，后来就把那些不信的灭绝了。这一切的事，你们虽然都知道，我却仍要提醒你们。'),
('CUV', '犹大书', 65, 1, 6, '又有不守本位、离开自己住处的天使，主用锁链把他们永远拘留在黑暗里，等候大日的审判。'),
('CUV', '犹大书', 65, 1, 7, '又如所多玛、蛾摩拉和周围城邑的人也照他们一味的行淫，随从逆性的情欲，就受永火的刑罚，作为鉴戒。'),
('CUV', '犹大书', 65, 1, 8, '这些做梦的人也像他们污秽身体，轻慢主治的，毁谤在尊位的。'),
('CUV', '犹大书', 65, 1, 9, '天使长米迦勒{为摩西的尸首与魔鬼争辩的时候，尚且不敢用毁谤的话罪责他，只说：主责备你罢！'),
('CUV', '犹大书', 65, 1, 10, '但这些人毁谤他们所不知道的。他们本性所知道的事与那没有灵性的畜类一样，在这事上竟败坏了自己。'),
('CUV', '犹大书', 65, 1, 11, '他们有祸了！因为走了该隐的道路，又为利往巴兰的错谬里直奔，并在可拉的背叛中灭亡了。'),
('CUV', '犹大书', 65, 1, 12, '这样的人在你们的爱席上与你们同吃的时候，正是礁石（或作：玷污）。他们作牧人，只知𫗪养自己，无所惧怕；是没有雨的云彩，被风飘荡；是秋天没有果子的树，死而又死，连根被拔出来；'),
('CUV', '犹大书', 65, 1, 13, '是海里的狂浪，涌出自己可耻的沫子来；是流荡的星，有墨黑的幽暗为他们永远存留。'),
('CUV', '犹大书', 65, 1, 14, '亚当的七世孙以诺，曾预言这些人说：看哪，主带著他的千万圣者降临，'),
('CUV', '犹大书', 65, 1, 15, '要在众人身上行审判，证实那一切不敬虔的人，所妄行一切不敬虔的事，又证实不敬虔之罪人所说顶撞他的刚愎话。'),
('CUV', '犹大书', 65, 1, 16, '这些人是私下议论，常发怨言的，随从自己的情欲而行，口中说夸大的话，为得便宜谄媚人。'),
('CUV', '犹大书', 65, 1, 17, '亲爱的弟兄阿，你们要记念我们主耶稣基督之使徒从前所说的话。'),
('CUV', '犹大书', 65, 1, 18, '他们曾对你们说过，末世必有好讥诮的人随从自己不敬虔的私欲而行。'),
('CUV', '犹大书', 65, 1, 19, '这就是那些引人结党、属乎血气、没有圣灵的人。'),
('CUV', '犹大书', 65, 1, 20, '亲爱的弟兄阿，你们却要在至圣的真道上造就自己，在圣灵里祷告，'),
('CUV', '犹大书', 65, 1, 21, '保守自己常在神的爱中，仰望我们主耶稣基督的怜悯，直到永生。'),
('CUV', '犹大书', 65, 1, 22, '有些人存疑心，你们要怜悯他们；'),
('CUV', '犹大书', 65, 1, 23, '有些人你们要从火中抢出来，搭救他们；有些人你们要存惧怕的心怜悯他们，连那被情欲沾染的衣服也当厌恶。'),
('CUV', '犹大书', 65, 1, 24, '那能保守你们不失脚、叫你们无瑕无疵、欢欢喜喜站在他荣耀之前的我们的救主─独一的神，'),
('CUV', '犹大书', 65, 1, 25, '愿荣耀、威严、能力、权柄，因我们的主耶稣基督归与他，从万古以前并现今，直到永永远远。阿们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 1, 1, '耶稣基督的启示，就是神赐给他，叫他将必要快成的事指示他的众仆人。他就差遣使者晓谕他的仆人约翰。'),
('CUV', '启示录', 66, 1, 2, '约翰便将神的道和耶稣基督的见证，凡自己所看见的都证明出来。'),
('CUV', '启示录', 66, 1, 3, '念这书上预言的和那些听见又遵守其中所记载的，都是有福的，因为日期近了。'),
('CUV', '启示录', 66, 1, 4, '约翰写信给亚西亚的七个教会。但愿从那昔在、今在、以后永在的神，和他宝座前的七灵，'),
('CUV', '启示录', 66, 1, 5, '并那诚实作见证的、从死里首先复活、为世上君王元首的耶稣基督，有恩惠、平安归与你们！他爱我们，用自己的血使我们脱离（有古卷作：洗去）罪恶，'),
('CUV', '启示录', 66, 1, 6, '又使我们成为国民，作他父神的祭司。但愿荣耀、权能归给他，直到永永远远。阿们！'),
('CUV', '启示录', 66, 1, 7, '看哪，他驾云降临！众目要看见他，连刺他的人也要看见他；地上的万族都要因他哀哭。这话是真实的。阿们！'),
('CUV', '启示录', 66, 1, 8, '主神说：我是阿拉法，我是俄梅戛，（阿拉法，俄梅戛：是希利尼字母首末二字），是昔在、今在、以后永在的全能者。'),
('CUV', '启示录', 66, 1, 9, '我─约翰就是你们的弟兄，和你们在耶稣的患难、国度、忍耐里一同有分，为神的道，并为给耶稣作的见证，曾在那名叫拔摩的海岛上。'),
('CUV', '启示录', 66, 1, 10, '当主日，我被圣灵感动，听见在我后面有大声音如吹号，说：'),
('CUV', '启示录', 66, 1, 11, '你所看见的当写在书上，达与以弗所、士每拿、别迦摩、推雅推喇、撒狄、非拉铁非、老底嘉、那七个教会。'),
('CUV', '启示录', 66, 1, 12, '我转过身来，要看是谁发声与我说话；既转过来，就看见七个金灯台。'),
('CUV', '启示录', 66, 1, 13, '灯台中间有一位好像人子，身穿长衣，直垂到脚，胸间束著金带。'),
('CUV', '启示录', 66, 1, 14, '他的头与发皆白，如白羊毛，如雪；眼目如同火燄；'),
('CUV', '启示录', 66, 1, 15, '脚好像在炉中煆炼光明的铜；声音如同众水的声音。'),
('CUV', '启示录', 66, 1, 16, '他右手拿著七星，从他口中出来一把两刃的利剑；面貌如同烈日放光。'),
('CUV', '启示录', 66, 1, 17, '我一看见，就仆倒在他脚前，像死了一样。他用右手按著我，说：不要惧怕！我是首先的，我是末后的，'),
('CUV', '启示录', 66, 1, 18, '又是那存活的；我曾死过，现在又活了，直活到永永远远；并且拿著死亡和阴间的钥匙。'),
('CUV', '启示录', 66, 1, 19, '所以你要把所看见的，和现在的事，并将来必成的事，都写出来。'),
('CUV', '启示录', 66, 1, 20, '论到你所看见、在我右手中的七星和七个金灯台的奥秘，那七星就是七个教会的使者，七灯台就是七个教会。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 2, 1, '你要写信给以弗所教会的使者，说：那右手拿著七星、在七个金灯台中间行走的，说：'),
('CUV', '启示录', 66, 2, 2, '我知道你的行为、劳碌、忍耐，也知道你不能容忍恶人。你也曾试验那自称为使徒却不是使徒的，看出他们是假的来。'),
('CUV', '启示录', 66, 2, 3, '你也能忍耐，曾为我的名劳苦，并不乏倦。'),
('CUV', '启示录', 66, 2, 4, '然而有一件事我要责备你，就是你把起初的爱心离弃了。'),
('CUV', '启示录', 66, 2, 5, '所以，应当回想你是从那里坠落的，并要悔改，行起初所行的事。你若不悔改，我就临到你那里，把你的灯台从原处挪去。'),
('CUV', '启示录', 66, 2, 6, '然而你还有一件可取的事，就是你恨恶尼哥拉一党人的行为，这也是我所恨恶的。'),
('CUV', '启示录', 66, 2, 7, '圣灵向众教会所说的话，凡有耳的，就应当听！得胜的，我必将神乐园中生命树的果子赐给他吃。'),
('CUV', '启示录', 66, 2, 8, '你要写信给士每拿教会的使者，说：那首先的、末后的、死过又活的，说：'),
('CUV', '启示录', 66, 2, 9, '我知道你的患难，你的贫穷（你却是富足的），也知道那自称是犹太人所说的毁谤话，其实他们不是犹太人，乃是撒但一会的人。'),
('CUV', '启示录', 66, 2, 10, '你将要受的苦你不用怕。魔鬼要把你们中间几个人下在监里，叫你们被试炼，你们必受患难十日。你务要至死忠心，我就赐给你那生命的冠冕。'),
('CUV', '启示录', 66, 2, 11, '圣灵向众教会所说的话，凡有耳的，就应当听！得胜的，必不受第二次死的害。'),
('CUV', '启示录', 66, 2, 12, '你要写信给别迦摩教会的使者，说：那有两刃利剑的，说：'),
('CUV', '启示录', 66, 2, 13, '我知道你的居所，就是有撒但座位之处；当我忠心的见证人安提帕在你们中间、撒但所住的地方被杀之时，你还坚守我的名，没有弃绝我的道。'),
('CUV', '启示录', 66, 2, 14, '然而，有几件事我要责备你：因为在你那里有人服从了巴兰的教训；这巴兰曾教导巴勒将绊脚石放在以色列人面前，叫他们吃祭偶像之物，行奸淫的事。'),
('CUV', '启示录', 66, 2, 15, '你那里也有人照样服从了尼哥拉一党人的教训。'),
('CUV', '启示录', 66, 2, 16, '所以，你当悔改；若不悔改，我就快临到你那里，用我口中的剑攻击他们。'),
('CUV', '启示录', 66, 2, 17, '圣灵向众教会所说的话，凡有耳的，就应当听！得胜的，我必将那隐藏的吗哪赐给他，并赐他一块白石，石上写著新名；除了那领受的以外，没有人能认识。'),
('CUV', '启示录', 66, 2, 18, '你要写信给推雅推喇教会的使者，说：那眼目如火燄、脚像光明铜的神之子说：'),
('CUV', '启示录', 66, 2, 19, '我知道你的行为、爱心、信心、勤劳、忍耐，又知道你末后所行的善事，比起初所行的更多。'),
('CUV', '启示录', 66, 2, 20, '然而，有一件事我要责备你，就是你容让那自称是先知的妇人耶洗别教导我的仆人，引诱他们行奸淫，吃祭偶像之物。'),
('CUV', '启示录', 66, 2, 21, '我曾给他悔改的机会，他却不肯悔改他的淫行。'),
('CUV', '启示录', 66, 2, 22, '看哪，我要叫他病卧在床。那些与他行淫的人，若不悔改所行的，我也要叫他们同受大患难。'),
('CUV', '启示录', 66, 2, 23, '我又要杀死他的党类（原文是儿女），叫众教会知道，我是那察看人肺腑心肠的，并要照你们的行为报应你们各人。'),
('CUV', '启示录', 66, 2, 24, '至于你们推雅推喇其余的人，就是一切不从那教训、不晓得他们素常所说撒但深奥之理的人，我告诉你们，我不将别的担子放在你们身上。'),
('CUV', '启示录', 66, 2, 25, '但你们已经有的，总要持守，直等到我来。'),
('CUV', '启示录', 66, 2, 26, '那得胜又遵守我命令到底的，我要赐给他权柄制伏列国；'),
('CUV', '启示录', 66, 2, 27, '他必用铁杖辖管（辖管：原文是牧）他们，将他们如同窑户的瓦器打得粉碎，像我从我父领受的权柄一样。'),
('CUV', '启示录', 66, 2, 28, '我又要把晨星赐给他。'),
('CUV', '启示录', 66, 2, 29, '圣灵向众教会所说的话，凡有耳的，就应当听！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 3, 1, '你要写信给撒狄教会的使者，说：那有神的七灵和七星的，说：我知道你的行为，按名你是活的，其实是死的。'),
('CUV', '启示录', 66, 3, 2, '你要儆醒，坚固那剩下将要衰微（原文是死）的；因我见你的行为，在我神面前，没有一样是完全的。'),
('CUV', '启示录', 66, 3, 3, '所以要回想你是怎样领受、怎样听见的、又要遵守，并要悔改。若不儆醒，我必临到你那里，如同贼一样。我几时临到，你也决不能知道。'),
('CUV', '启示录', 66, 3, 4, '然而在撒狄，你还有几名是未曾污秽自己衣服的，他们要穿白衣与我同行，因为他们是配得过的。'),
('CUV', '启示录', 66, 3, 5, '凡得胜的必这样穿白衣，我也必不从生命册上涂抹他的名；且要在我父面前，和我父众使者面前，认他的名。'),
('CUV', '启示录', 66, 3, 6, '圣灵向众教会所说的话，凡有耳的，就应当听！'),
('CUV', '启示录', 66, 3, 7, '你要写信给非拉铁非教会的使者，说：那圣洁、真实、拿著大卫的钥匙、开了就没有人能关、关了就没有人能开的，说：'),
('CUV', '启示录', 66, 3, 8, '我知道你的行为，你略有一点力量，也曾遵守我的道，没有弃绝我的名。看哪，我在你面前给你一个敞开的门，是无人能关的。'),
('CUV', '启示录', 66, 3, 9, '那撒但一会的，自称是犹太人，其实不是犹太人，乃是说谎话的，我要使他们来，在你脚前下拜，也使他们知道我是已经爱你了。'),
('CUV', '启示录', 66, 3, 10, '你既遵守我忍耐的道，我必在普天下人受试炼的时候，保守你免去你的试炼。'),
('CUV', '启示录', 66, 3, 11, '我必快来，你要持守你所有的，免得人夺去你的冠冕。'),
('CUV', '启示录', 66, 3, 12, '得胜的，我要叫他在我神殿中作柱子，他也必不再从那里出去。我又要将我神的名和我神城的名（这城就是从天上、从我神那里降下来的新耶路撒冷），并我的新名，都写在他上面。'),
('CUV', '启示录', 66, 3, 13, '圣灵向众教会所说的话，凡有耳的，就应当听！'),
('CUV', '启示录', 66, 3, 14, '你要写信给老底嘉教会的使者，说：那为阿们的，为诚信真实见证的，在神创造万物之上为元首的，说：'),
('CUV', '启示录', 66, 3, 15, '我知道你的行为，你也不冷也不热；我巴不得你或冷或热。'),
('CUV', '启示录', 66, 3, 16, '你既如温水，也不冷也不热，所以我必从我口中把你吐出去。'),
('CUV', '启示录', 66, 3, 17, '你说：我是富足，已经发了财，一样都不缺；却不知道你是那困苦、可怜、贫穷、瞎眼、赤身的。'),
('CUV', '启示录', 66, 3, 18, '我劝你向我买火炼的金子，叫你富足；又买白衣穿上，叫你赤身的羞耻不露出来；又买眼药擦你的眼睛，使你能看见。'),
('CUV', '启示录', 66, 3, 19, '凡我所疼爱的，我就责备管教他；所以你要发热心，也要悔改。'),
('CUV', '启示录', 66, 3, 20, '看哪，我站在门外叩门，若有听见我声音就开门的，我要进到他那里去，我与他他与我一同坐席。'),
('CUV', '启示录', 66, 3, 21, '得胜的，我要赐他在我宝座上与我同坐，就如我得了胜，在我父的宝座上与他同坐一般。'),
('CUV', '启示录', 66, 3, 22, '圣灵向众教会所说的话，凡有耳的，就应当听！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 4, 1, '此后，我观看，见天上有门开了。我初次听见好像吹号的声音，对我说：你上到这里来，我要将以后必成的事指示你。'),
('CUV', '启示录', 66, 4, 2, '我立刻被圣灵感动，见有一个宝座安置在天上，又有一位坐在宝座上。'),
('CUV', '启示录', 66, 4, 3, '看那坐著的，好像碧玉和红宝石；又有虹围著宝座，好像绿宝石。'),
('CUV', '启示录', 66, 4, 4, '宝座的周围又有二十四个座位；其上坐著二十四位长老，身穿白衣，头上戴著金冠冕。'),
('CUV', '启示录', 66, 4, 5, '有闪电、声音、雷轰从宝座中发出；又有七盏火灯在宝座前点著；这七灯就是神的七灵。'),
('CUV', '启示录', 66, 4, 6, '宝座前好像一个玻璃海，如同水晶。宝座中和宝座周围有四个活物，前后遍体都满了眼睛。'),
('CUV', '启示录', 66, 4, 7, '第一个活物像狮子，第二个像牛犊，第三个脸面像人，第四个像飞鹰。'),
('CUV', '启示录', 66, 4, 8, '四活物各有六个翅膀，遍体内外都满了眼睛。他们昼夜不住的说：圣哉！圣哉！圣哉！主神是昔在、今在、以后永在的全能者。'),
('CUV', '启示录', 66, 4, 9, '每逢四活物将荣耀、尊贵、感谢归给那坐在宝座上、活到永永远远者的时候，'),
('CUV', '启示录', 66, 4, 10, '那二十四位长老就俯伏在坐宝座的面前敬拜那活到永永远远的，又把他们的冠冕放在宝座前，说：'),
('CUV', '启示录', 66, 4, 11, '我们的主，我们的神，你是配得荣耀、尊贵、权柄的；因为你创造了万物，并且万物是因你的旨意被创造而有的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 5, 1, '我看见坐宝座的右手中有书卷，里外都写著字，用七印封严了。'),
('CUV', '启示录', 66, 5, 2, '我又看见一位大力的天使大声宣传说：有谁配展开那书卷，揭开那七印呢？'),
('CUV', '启示录', 66, 5, 3, '在天上、地上、地底下，没有能展开、能观看那书卷的。'),
('CUV', '启示录', 66, 5, 4, '因为没有配展开、配观看那书卷的，我就大哭。'),
('CUV', '启示录', 66, 5, 5, '长老中有一位对我说：不要哭。看哪，犹大支派中的狮子，大卫的根，他已得胜，能以展开那书卷，揭开那七印。'),
('CUV', '启示录', 66, 5, 6, '我又看见宝座与四活物，并长老之中有羔羊站立，像是被杀过的，有七角七眼，就是神的七灵，奉差遣往普天下去的。'),
('CUV', '启示录', 66, 5, 7, '这羔羊前来，从坐宝座的右手里拿了书卷。'),
('CUV', '启示录', 66, 5, 8, '他既拿了书卷，四活物和二十四位长老就俯伏在羔羊面前，各拿著琴和盛满了香的金炉；这香就是众圣徒的祈祷。'),
('CUV', '启示录', 66, 5, 9, '他们唱新歌，说：你配拿书卷，配揭开七印；因为你曾被杀，用自己的血从各族、各方、各民、各国中买了人来，叫他们归于神，'),
('CUV', '启示录', 66, 5, 10, '又叫他们成为国民，作祭司归于神，在地上执掌王权。'),
('CUV', '启示录', 66, 5, 11, '我又看见且听见，宝座与活物并长老的周围有许多天使的声音；他们的数目有千千万万，'),
('CUV', '启示录', 66, 5, 12, '大声说：曾被杀的羔羊是配得权柄、丰富、智慧、能力、尊贵、荣耀、颂赞的。'),
('CUV', '启示录', 66, 5, 13, '我又听见在天上、地上、地底下、沧海里，和天地间一切所有被造之物，都说：但愿颂赞、尊贵、荣耀、权势都归给坐宝座的和羔羊，直到永永远远！'),
('CUV', '启示录', 66, 5, 14, '四活物就说：阿们！众长老也俯伏敬拜。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 6, 1, '我看见羔羊揭开七印中第一印的时候，就听见四活物中的一个活物，声音如雷，说：你来！'),
('CUV', '启示录', 66, 6, 2, '我就观看，见有一匹白马；骑在马上的，拿著弓，并有冠冕赐给他。他便出来，胜了又要胜。'),
('CUV', '启示录', 66, 6, 3, '揭开第二印的时候，我听见第二个活物说：你来。'),
('CUV', '启示录', 66, 6, 4, '就另有一匹马出来，是红的，有权柄给了那骑马的，可以从地上夺去太平，使人彼此相杀；又有一把大刀赐给他。'),
('CUV', '启示录', 66, 6, 5, '揭开第三印的时候，我听见第三个活物说：你来！我就观看，见有一匹黑马；骑在马上的，手里拿著天平。'),
('CUV', '启示录', 66, 6, 6, '我听见在四活物中似乎有声音说：一钱银子买一升麦子，一钱银子买三升大麦；油和酒不可糟蹋。'),
('CUV', '启示录', 66, 6, 7, '揭开第四印的时候，我听见第四个活物说：你来！'),
('CUV', '启示录', 66, 6, 8, '我就观看，见有一匹灰色马；骑在马上的，名字叫作死，阴府也随著他；有权柄赐给他们，可以用刀剑、饥荒、瘟疫（或作：死亡）、野兽，杀害地上四分之一的人。'),
('CUV', '启示录', 66, 6, 9, '揭开第五印的时候，我看见在祭坛底下，有为神的道、并为作见证被杀之人的灵魂，'),
('CUV', '启示录', 66, 6, 10, '大声喊著说：圣洁真实的主阿，你不审判住在地上的人，给我们伸流血的冤，要等到几时呢？'),
('CUV', '启示录', 66, 6, 11, '于是有白衣赐给他们各人；又有话对他们说，还要安息片时，等著一同作仆人的和他们的弟兄也像他们被杀，满足了数目。'),
('CUV', '启示录', 66, 6, 12, '揭开第六印的时候，我又看见地大震动，日头变黑像毛布，满月变红像血，'),
('CUV', '启示录', 66, 6, 13, '天上的星辰坠落于地，如同无花果树被大风摇动，落下未熟的果子一样。'),
('CUV', '启示录', 66, 6, 14, '天就挪移，好像书卷被卷起来；山岭海岛都被挪移离开本位。'),
('CUV', '启示录', 66, 6, 15, '地上的君王、臣宰、将军、富户、壮士，和一切为奴的、自主的，都藏在山洞和岩石穴里，'),
('CUV', '启示录', 66, 6, 16, '向山和岩石说：倒在我们身上罢！把我们藏起来，躲避坐宝座者的面目和羔羊的忿怒；'),
('CUV', '启示录', 66, 6, 17, '因为他们忿怒的大日到了，谁能站得住呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 7, 1, '此后，我看见四位天使站在地的四角，执掌地上四方的风，叫风不吹在地上、海上，和树上。'),
('CUV', '启示录', 66, 7, 2, '我又看见另有一位天使，从日出之地上来，拿著永生神的印。他就向那得著权柄能伤害地和海的四位天使大声喊著说：'),
('CUV', '启示录', 66, 7, 3, '地与海并树木，你们不可伤害，等我们印了我们神众仆人的额。'),
('CUV', '启示录', 66, 7, 4, '我听见以色列人各支派中受印的数目有十四万四千。'),
('CUV', '启示录', 66, 7, 5, '犹大支派中受印的有一万二千；流便支派中有一万二千；迦得支派中有一万二千；'),
('CUV', '启示录', 66, 7, 6, '亚设支派中有一万二千；拿弗他利支派中有一万二千；玛拿西支派中有一万二千；'),
('CUV', '启示录', 66, 7, 7, '西缅支派中有一万二千；利未支派中有一万二千；以萨迦支派中有一万二千；'),
('CUV', '启示录', 66, 7, 8, '西布伦支派中有一万二千；约瑟支派中有一万二千；便雅悯支派中受印的有一万二千。'),
('CUV', '启示录', 66, 7, 9, '此后，我观看，见有许多的人，没有人能数过来，是从各国、各族、各民、各方来的，站在宝座和羔羊面前，身穿白衣，手拿棕树枝，'),
('CUV', '启示录', 66, 7, 10, '大声喊著说：愿救恩归与坐在宝座上我们的神，也归与羔羊！'),
('CUV', '启示录', 66, 7, 11, '众天使都站在宝座和众长老并四活物的周围，在宝座前，面伏于地，敬拜神，'),
('CUV', '启示录', 66, 7, 12, '说：阿们！颂赞、荣耀、智慧、感谢、尊贵、权柄、大力都归与我们的神，直到永永远远。阿们！'),
('CUV', '启示录', 66, 7, 13, '长老中有一位问我说：这些穿白衣的是谁？是从那里来的？'),
('CUV', '启示录', 66, 7, 14, '我对他说：我主，你知道。他向我说：这些人是从大患难中出来的，曾用羔羊的血把衣裳洗白净了。'),
('CUV', '启示录', 66, 7, 15, '所以，他们在神宝座前，昼夜在他殿中事奉他。坐宝座的要用帐幕覆庇他们。'),
('CUV', '启示录', 66, 7, 16, '他们不再饥，不再渴；日头和炎热也必不伤害他们。'),
('CUV', '启示录', 66, 7, 17, '因为宝座中的羔羊必牧养他们，领他们到生命水的泉源；神也必擦去他们一切的眼泪。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 8, 1, '羔羊揭开第七印的时候，天上寂静约有二刻。'),
('CUV', '启示录', 66, 8, 2, '我看见那站在神面前的七位天使，有七枝号赐给他们。'),
('CUV', '启示录', 66, 8, 3, '另有一位天使，拿著金香炉来，站在祭坛旁边。有许多香赐给他，要和众圣徒的祈祷一同献在宝座前的金坛上。'),
('CUV', '启示录', 66, 8, 4, '那香的烟和众圣徒的祈祷从天使的手中一同升到神面前。'),
('CUV', '启示录', 66, 8, 5, '天使拿著香炉，盛满了坛上的火，倒在地上；随有雷轰、大声、闪电、地震。'),
('CUV', '启示录', 66, 8, 6, '拿著七枝号的七位天使就预备要吹。'),
('CUV', '启示录', 66, 8, 7, '第一位天使吹号，就有雹子与火搀著血丢在地上；地的三分之一和树的三分之一被烧了，一切的青草也被烧了。'),
('CUV', '启示录', 66, 8, 8, '第二位天使吹号，就有仿佛火烧著的大山扔在海中；海的三分之一变成血，'),
('CUV', '启示录', 66, 8, 9, '海中的活物死了三分之一，船只也坏了三分之一。'),
('CUV', '启示录', 66, 8, 10, '第三位天使吹号，就有烧著的大星，好像火把从天上落下来，落在江河的三分之一和众水的泉源上。'),
('CUV', '启示录', 66, 8, 11, '这星名叫茵𫈟。众水的三分之一变为茵𫈟；因水变苦，就死了许多人。'),
('CUV', '启示录', 66, 8, 12, '第四位天使吹号，日头的三分之一，月亮的三分之一、星辰的三分之一都被击打，以致日月星的三分之一黑暗了，白昼的三分之一没有光，黑夜也是这样。'),
('CUV', '启示录', 66, 8, 13, '我又看见一个鹰飞在空中，并听见他大声说：三位天使要吹那其余的号。你们住在地上的民，祸哉！祸哉！祸哉！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 9, 1, '第五位天使吹号，我就看见一个星从天落到地上，有无底坑的钥匙赐给他。'),
('CUV', '启示录', 66, 9, 2, '他开了无底坑，便有烟从坑里往上冒，好像大火炉的烟；日头和天空都因这烟昏暗了。'),
('CUV', '启示录', 66, 9, 3, '有蝗虫从烟中出来，飞到地上；有能力赐给他们，好像地上蝎子的能力一样，'),
('CUV', '启示录', 66, 9, 4, '并且吩咐他们说，不可伤害地上的草和各样青物，并一切树木，惟独要伤害额上没有神印记的人。'),
('CUV', '启示录', 66, 9, 5, '但不许蝗虫害死他们，只叫他们受痛苦五个月。这痛苦就像蝎子螫人的痛苦一样。'),
('CUV', '启示录', 66, 9, 6, '在那些日子，人要求死，决不得死；愿意死，死却远避他们。'),
('CUV', '启示录', 66, 9, 7, '蝗虫的形状，好像预备出战的马一样，头上戴的好像金冠冕，脸面好像男人的脸面，'),
('CUV', '启示录', 66, 9, 8, '头发像女人的头发，牙齿像狮子的牙齿。'),
('CUV', '启示录', 66, 9, 9, '胸前有甲，好像铁甲。他们翅膀的声音，好像许多车马奔跑上阵的声音。'),
('CUV', '启示录', 66, 9, 10, '有尾巴像蝎子，尾巴上的毒钩能伤人五个月。'),
('CUV', '启示录', 66, 9, 11, '有无底坑的使者作他们的王，按著希伯来话，名叫亚巴顿，希利尼话，名叫亚玻伦。'),
('CUV', '启示录', 66, 9, 12, '第一样灾祸过去了，还有两样灾祸要来。'),
('CUV', '启示录', 66, 9, 13, '第六位天使吹号，我就听见有声音从神面前金坛的四角出来，'),
('CUV', '启示录', 66, 9, 14, '吩咐那吹号的第六位天使，说：把那捆绑在伯拉大河的四个使者释放了。'),
('CUV', '启示录', 66, 9, 15, '那四个使者就被释放；他们原是预备好了，到某年某月某日某时，要杀人的三分之一。'),
('CUV', '启示录', 66, 9, 16, '马军有二万万；他们的数目我听见了。'),
('CUV', '启示录', 66, 9, 17, '我在异象中看见那些马和骑马的，骑马的胸前有甲如火，与紫玛瑙并硫磺。马的头好像狮子头，有火、有烟、有硫磺从马的口中出来。'),
('CUV', '启示录', 66, 9, 18, '口中所出来的火与烟并硫磺，这三样灾杀了人的三分之一。'),
('CUV', '启示录', 66, 9, 19, '这马的能力是在口里和尾巴上；因这尾巴像蛇，并且有头用以害人。'),
('CUV', '启示录', 66, 9, 20, '其余未曾被这些灾所杀的人仍旧不悔改自己手所做的，还是去拜鬼魔和那些不能看、不能听、不能走，金、银、铜、木、石的偶像，'),
('CUV', '启示录', 66, 9, 21, '又不悔改他们那些凶杀、邪术、奸淫、偷窃的事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 10, 1, '我又看见另有一位大力的天使从天降下，披著云彩，头上有虹，脸面像日头，两脚像火柱。'),
('CUV', '启示录', 66, 10, 2, '他手里拿著小书卷，是展开的。他右脚踏海，左脚踏地，'),
('CUV', '启示录', 66, 10, 3, '大声呼喊，好像狮子吼叫。呼喊完了，就有七雷发声。'),
('CUV', '启示录', 66, 10, 4, '七雷发声之后，我正要写出来，就听见从天上有声音说：七雷所说的，你要封上，不可写出来。'),
('CUV', '启示录', 66, 10, 5, '我所看见的那踏海踏地的天使向天举起右手来，'),
('CUV', '启示录', 66, 10, 6, '指著那创造天和天上之物，地和地上之物，海和海中之物，直活到永永远远的，起誓说：不再有时日了（或作：不再耽延了）。'),
('CUV', '启示录', 66, 10, 7, '但在第七位天使吹号发声的时候，神的奥秘就成全了，正如神所传给他仆人众先知的佳音。'),
('CUV', '启示录', 66, 10, 8, '我先前从天上所听见的那声音又吩咐我说：你去，把那踏海踏地之天使手中展开的小书卷取过来。'),
('CUV', '启示录', 66, 10, 9, '我就走到天使那里，对他说：请你把小书卷给我。他对我说：你拿著吃尽了，便叫你肚子发苦，然而在你口中要甜如蜜。'),
('CUV', '启示录', 66, 10, 10, '我从天使手中把小书卷接过来，吃尽了，在我口中果然甜如蜜，吃了以后，肚子觉得发苦了。'),
('CUV', '启示录', 66, 10, 11, '天使（原文是他们）对我说：你必指著多民、多国、多方、多王再说预言。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 11, 1, '有一根苇子赐给我，当作量度的杖，且有话说：起来！将神的殿和祭坛，并在殿中礼拜的人都量一量。'),
('CUV', '启示录', 66, 11, 2, '只是殿外的院子要留下不用量，因为这是给了外邦人的；他们要践踏圣城四十二个月。'),
('CUV', '启示录', 66, 11, 3, '我要使我那两个见证人，穿著毛衣，传道一千二百六十天。'),
('CUV', '启示录', 66, 11, 4, '他们就是那两棵橄榄树，两个灯台，立在世界之主面前的。'),
('CUV', '启示录', 66, 11, 5, '若有人想要害他们，就有火从他们口中出来，烧灭仇敌。凡想要害他们的都必这样被杀。'),
('CUV', '启示录', 66, 11, 6, '这二人有权柄，在他们传道的日子叫天闭塞不下雨；又有权柄叫水变为血，并且能随时随意用各样的灾殃攻击世界。'),
('CUV', '启示录', 66, 11, 7, '他们作完见证的时候，那从无底坑里上来的兽必与他们交战，并且得胜，把他们杀了。'),
('CUV', '启示录', 66, 11, 8, '他们的尸首就倒在大城里的街上；这城按著灵意叫所多玛，又叫埃及，就是他们的主钉十字架之处。'),
('CUV', '启示录', 66, 11, 9, '从各民、各族、各方、各国中，有人观看他们的尸首三天半，又不许把尸首放在坟墓里。'),
('CUV', '启示录', 66, 11, 10, '住在地上的人就为他们欢喜快乐，互相餽送礼物，因这两位先知曾叫住在地上的人受痛苦。'),
('CUV', '启示录', 66, 11, 11, '过了这三天半，有生气从神那里进入他们里面，他们就站起来；看见他们的人甚是害怕。'),
('CUV', '启示录', 66, 11, 12, '两位先知听见有大声音从天上来，对他们说：上到这里来。他们就驾著云上了天，他们的仇敌也看见了。'),
('CUV', '启示录', 66, 11, 13, '正在那时候，地大震动，城就倒塌了十分之一，因地震而死的有七千人；其余的都恐惧，归荣耀给天上的神。'),
('CUV', '启示录', 66, 11, 14, '第二样灾祸过去，第三样灾祸快到了。'),
('CUV', '启示录', 66, 11, 15, '第七位天使吹号，天上就有大声音说：世上的国成了我主和主基督的国；他要作王，直到永永远远。'),
('CUV', '启示录', 66, 11, 16, '在神面前，坐在自己位上的二十四位长老，就面伏于地，敬拜神，'),
('CUV', '启示录', 66, 11, 17, '说：昔在、今在的主神─全能者阿，我们感谢你！因你执掌大权作王了。'),
('CUV', '启示录', 66, 11, 18, '外邦发怒，你的忿怒也临到了；审判死人的时候也到了。你的仆人众先知和众圣徒，凡敬畏你名的人，连大带小得赏赐的时候也到了。你败坏那些败坏世界之人的时候也就到了。'),
('CUV', '启示录', 66, 11, 19, '当时，神天上的殿开了，在他殿中现出他的约柜。随后有闪电、声音、雷轰、地震、大雹。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '启示录', 66, 12, 1, '天上现出大异象来：有一个妇人身披日头，脚踏月亮，头戴十二星的冠冕。'),
('CUV', '启示录', 66, 12, 2, '他怀了孕，在生产的艰难中疼痛呼叫。'),
('CUV', '启示录', 66, 12, 3, '天上又现出异象来：有一条大红龙，七头十角；七头上戴著七个冠冕。'),
('CUV', '启示录', 66, 12, 4, '他的尾巴拖拉著天上星辰的三分之一，摔在地上。龙就站在那将要生产的妇人面前，等他生产之后，要吞吃他的孩子。'),
('CUV', '启示录', 66, 12, 5, '妇人生了一个男孩子，是将来要用铁杖辖管（辖管：原文是牧）万国的；他的孩子被提到神宝座那里去了。'),
('CUV', '启示录', 66, 12, 6, '妇人就逃到旷野，在那里有神给他预备的地方，使他被养活一千二百六十天。'),
('CUV', '启示录', 66, 12, 7, '在天上就有了争战。米迦勒同他的使者与龙争战，龙也同他的使者去争战，'),
('CUV', '启示录', 66, 12, 8, '并没有得胜，天上再没有他们的地方。'),
('CUV', '启示录', 66, 12, 9, '大龙就是那古蛇，名叫魔鬼，又叫撒但，是迷惑普天下的。他被摔在地上，他的使者也一同被摔下去。'),
('CUV', '启示录', 66, 12, 10, '我听见在天上有大声音说：我神的救恩、能力、国度、并他基督的权柄，现在都来到了！因为那在我们神面前昼夜控告我们弟兄的，已经被摔下去了。'),
('CUV', '启示录', 66, 12, 11, '弟兄胜过他，是因羔羊的血和自己所见证的道。他们虽至于死，也不爱惜性命。'),
('CUV', '启示录', 66, 12, 12, '所以，诸天和住在其中的，你们都快乐罢！只是地与海有祸了！因为魔鬼知道自己的时候不多，就气忿忿的下到你们那里去了。'),
('CUV', '启示录', 66, 12, 13, '龙见自己被摔在地上，就逼迫那生男孩子的妇人。'),
('CUV', '启示录', 66, 12, 14, '于是有大鹰的两个翅膀赐给妇人，叫他能飞到旷野，到自己的地方，躲避那蛇；他在那里被养活一载二载半载。'),
('CUV', '启示录', 66, 12, 15, '蛇就在妇人身后，从口中吐出水来，像河一样，要将妇人冲去。'),
('CUV', '启示录', 66, 12, 16, '地却帮助妇人，开口吞了从龙口吐出来的水（原文作河）。'),
('CUV', '启示录', 66, 12, 17, '龙向妇人发怒，去与他其余的儿女争战，这儿女就是那守神诫命、为耶稣作见证的。那时龙就站在海边的沙上。')
on conflict (version, book, chapter, verse) do nothing;
